  connection: IConnection,
  props: post.Props,
): Promise<post.Response> {
  return !!connection.simulate
    ? post.simulate(connection, props)
    : PlainFetcher.fetch(
        {
          ...connection,
          headers: {
            ...connection.headers,
            "Content-Type": "application/json",
          },
        },
        {
          ...post.METADATA,
          path: post.path(),
          status: null,
        },
        props.body,
      );
}
export namespace post {
  export type Props = {
    /** Creation info for a new AI training dataset. */
    body: IAiTrainingData.ICreate;
  };
  export type Body = IAiTrainingData.ICreate;
  export type Response = IAiTrainingData;

  export const METADATA = {
    method: "POST",
    path: "/advancedAI/aiTrainingData",
    request: {
      type: "application/json",
      encrypted: false,
    },
    response: {
      type: "application/json",
      encrypted: false,
    },
  } as const;

  export const path = () => "/advancedAI/aiTrainingData";
