import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAiTrainingData } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiTrainingData";

/**
 * E2E Test: AI Training Data Creation & Uniqueness Constraint Validation
 *
 * This test verifies the creation of a new AI training dataset and checks the uniqueness constraint
 * enforced on (name, version, source_uri) to prevent redundant records.
 *
 * Workflow:
 * 1. Register an AI training dataset with a unique set of required fields
 *    - Validate that the response returns correct metadata, including id, timestamps, hash, etc.
 * 2. Attempt to register another dataset with the same (name, version, source_uri)
 *    - Assert that a uniqueness or conflict error is thrown, with appropriate error details
 *
 * This ensures that dataset registration is robust, complies with governance requirements, and
 * does not allow duplicate records with identical evidence attributes.
 */
export async function test_api_advancedai_test_create_ai_training_data_success_and_uniqueness_constraint(
  connection: api.IConnection,
) {
  // 1. Register a new AI training dataset with all required attributes
  const input: IAiTrainingData.ICreate = {
    name: "training-dataset-" + RandomGenerator.alphabets(8),
    version: "v1.0.0",
    source_uri: `s3://bucket-name/dataset-${RandomGenerator.alphabets(5)}.parquet`,
    schema_hash: RandomGenerator.alphaNumeric(32),
    record_count: typia.random<number & tags.Type<"int32">>(),
  };
  const dataset = await api.functional.advancedAI.aiTrainingData.post(connection, { body: input });
  typia.assert(dataset);
  TestValidator.equals("dataset name")(input.name)(dataset.name);
  TestValidator.equals("version")(input.version)(dataset.version);
  TestValidator.equals("source_uri")(input.source_uri)(dataset.source_uri);
  TestValidator.equals("schema_hash")(input.schema_hash)(dataset.schema_hash);
  if (input.record_count !== undefined) TestValidator.equals("record_count")(input.record_count)(dataset.record_count);
  TestValidator.predicate("created_at valid")(!!Date.parse(dataset.created_at));

  // 2. Try to register the same dataset again to validate uniqueness constraint
  await TestValidator.error("duplicate dataset rejected")(() =>
    api.functional.advancedAI.aiTrainingData.post(connection, { body: input }),
  );
}

