import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAiTrainingData } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiTrainingData";

/**
 * Test API validation for creation of AI training dataset with missing required fields
 *
 * Business context:
 * Ensures that critical validation and evidence traceability protections mandated
 * by AI governance are respected by rejecting incomplete registration forms. Missing
 * required fields in the dataset creation payload (such as source_uri or name) should result 
 * in clear, actionable field-validation errors—this is essential for trustworthy AI
 * operations and developer feedback during integration.
 *
 * Test Steps:
 * 1. Attempt to create a training dataset, deliberately omitting one required field (e.g. 'source_uri').
 * 2. Confirm that the API responds with a field validation error (e.g., HTTP 400, error message).
 * 3. Attempt to create a training dataset, omitting another required field (e.g. 'name').
 * 4. Confirm field-specific validation error is returned each time.
 * 5. Optionally, try omitting multiple required fields to check multi-field validation response.
 *
 * The test validates defensive backend contract enforcement and supports compliance logging/audit by verifying failed attempts result in clear evidence of proper validation checks.
 */
export async function test_api_advancedai_test_create_ai_training_data_missing_required_fields(
  connection: api.IConnection,
) {
  // 1. Try omitting 'source_uri' (should fail)
  await TestValidator.error("missing source_uri")(() =>
    api.functional.advancedAI.aiTrainingData.post(connection, {
      body: {
        name: "Test Dataset",
        version: "v1",
        // source_uri missing
        schema_hash: "hash-abc123",
      } as any, // NOTE: This is to induce a runtime error for the test, not recommended in prod
    }),
  );

  // 2. Try omitting 'name' (should fail)
  await TestValidator.error("missing name")(() =>
    api.functional.advancedAI.aiTrainingData.post(connection, {
      body: {
        // name missing
        version: "v1",
        source_uri: "s3://bucket/file.csv",
        schema_hash: "hash-abc123",
      } as any,
    }),
  );

  // 3. Try omitting multiple required fields (should fail)
  await TestValidator.error("missing name and source_uri")(() =>
    api.functional.advancedAI.aiTrainingData.post(connection, {
      body: {
        // name missing
        version: "v1",
        // source_uri missing
        schema_hash: "hash-abc123",
      } as any,
    }),
  );
}

