import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAiTrainingData } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiTrainingData";
import type { IOperationResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IOperationResult";

/**
 * E2E test for deleting an AI training dataset by ID.
 *
 * 1. Register (POST) a new AI training dataset to ensure there is a record to delete.
 * 2. Delete (DELETE) the created training dataset by its unique ID.
 *    - Expect response.success === true and a plausible operation message.
 * 3. Attempt to delete the SAME dataset ID again (should be already deleted).
 *    - Expect a failure response, e.g., success === false and a not-found or already-deleted message.
 * 4. Attempt to delete a totally random non-existent UUID.
 *    - Expect a failure response, e.g., success === false and a not-found message.
 * 5. Clean up (implicit, as delete is idempotent/soft deletion by policy).
 *
 * Notes:
 * - Dataset creation uses realistic IAiTrainingData.ICreate structure.
 * - Each major step should typia.assert() the returned value and validate business rules.
 * - Proper error messages and flags are checked (
 *     e.g., operation success/failure and informative message field in IOperationResult).
 */
export async function test_api_advancedAI_test_delete_ai_training_data_success_and_repeatability(
  connection: api.IConnection,
) {
  // 1. Register a new AI training dataset
  const createInput: IAiTrainingData.ICreate = {
    name: RandomGenerator.alphabets(10),
    version: `v${typia.random<number & tags.Type<"int32"> & tags.Minimum<1> & tags.Maximum<20>>()}`,
    source_uri: `s3://bucket-${RandomGenerator.alphabets(5)}/dataset/${RandomGenerator.alphabets(7)}.csv`,
    schema_hash: RandomGenerator.alphaNumeric(32),
    record_count: typia.random<number & tags.Type<"int32"> & tags.Minimum<100> & tags.Maximum<10000>>()
  };
  const dataset = await api.functional.advancedAI.aiTrainingData.post(connection, { body: createInput });
  typia.assert(dataset);
  TestValidator.equals("Dataset is created")(
    dataset.name
  )(createInput.name);

  // 2. Delete the created dataset
  const deleteResult = await api.functional.advancedAI.aiTrainingData.eraseById(connection, { id: dataset.id });
  typia.assert(deleteResult);
  TestValidator.equals("Dataset delete result")(
    true
  )(deleteResult.success);

  // 3. Attempt to delete again (should fail)
  const deleteAgainResult = await api.functional.advancedAI.aiTrainingData.eraseById(connection, { id: dataset.id });
  typia.assert(deleteAgainResult);
  TestValidator.equals("Second delete attempt should fail")(
    false
  )(deleteAgainResult.success);
  TestValidator.predicate('Message indicates already deleted or not found')(
    !!deleteAgainResult.message &&
    (/already deleted|not found/i).test(deleteAgainResult.message)
  );

  // 4. Attempt to delete a random non-existent UUID
  const randomId = typia.random<string & tags.Format<"uuid">>();
  const deleteNonexistent = await api.functional.advancedAI.aiTrainingData.eraseById(connection, { id: randomId });
  typia.assert(deleteNonexistent);
  TestValidator.equals("Deleting nonexistent id should fail")(
    false
  )(deleteNonexistent.success);
  TestValidator.predicate('Message indicates not found')(
    !!deleteNonexistent.message &&
    (/not found|no such|does not exist|invalid/i).test(deleteNonexistent.message)
  );
}

