 *   - 마지막 페이지에 limit보다 적은 아이템만 있을 때
 *   - name/created_at 오름차순/내림차순 정렬 검증
 *
 *   (데이터 populate/생성은 테스트 범위 밖, 사전 데이터가 있다는 전제에서 진행)
 */
export async function test_api_advancedAI_test_list_ai_feature_store_filter_and_pagination(
  connection: api.IConnection,
) {
  // 1. 기본 페이지네이션 쿼리 (필터 없음)
  const allResult = await api.functional.advancedAI.aiFeatureStore.patch(connection, {
    body: {},
  });
  typia.assert(allResult);
  TestValidator.predicate("최소 0개 이상의 records 존재")(Array.isArray(allResult.data));
  TestValidator.predicate("pagination 오브젝트 존재 검증")(typeof allResult.pagination === "object");
  TestValidator.predicate("첫 페이지 반환 확인")(allResult.pagination.current === 1);

  if (allResult.data.length > 0) {
    const anyEntry = allResult.data[0];
    // 2. Name 필터: 해당 name 값으로만 필터했을 때 해당 entry가 포함되는지 확인
    const nameFiltered = await api.functional.advancedAI.aiFeatureStore.patch(connection, {
      body: {
        name: anyEntry.name,
      },
    });
    typia.assert(nameFiltered);
    TestValidator.predicate("name-필터 성공")(nameFiltered.data.some(e => e.id === anyEntry.id));
    // 3. 모델 버전 필터
    const modelVerFiltered = await api.functional.advancedAI.aiFeatureStore.patch(connection, {
      body: {
        ai_model_version_id: anyEntry.ai_model_version_id,
      },
    });
    typia.assert(modelVerFiltered);
    TestValidator.predicate("model-version-필터 성공")(modelVerFiltered.data.some(e => e.id === anyEntry.id));
    // 4. 페이징: limit=1, page=1/2
    const paged1 = await api.functional.advancedAI.aiFeatureStore.patch(connection, {
      body: {
        limit: 1,
        page: 1,
      },
    });
    typia.assert(paged1);
    TestValidator.equals("limit")(1)(paged1.pagination.limit);
    if (paged1.pagination.pages > 1) {
      const paged2 = await api.functional.advancedAI.aiFeatureStore.patch(connection, {
        body: {
          limit: 1,
          page: 2,
        },
      });
      typia.assert(paged2);
      TestValidator.equals("limit")(1)(paged2.pagination.limit);
      // 1페이지와 2페이지 결과 데이터가 중복되지 않는지 확인
      if (paged2.data.length > 0) {
        TestValidator.predicate("페이징 데이터 중복 없음")(paged2.data[0].id !== paged1.data[0].id);
      }
    }
    // 5. name 오름차순 정렬
    const sortedNameAsc = await api.functional.advancedAI.aiFeatureStore.patch(connection, {
      body: {
        sort_by: "name",
        order: "asc",
      },
    });
    typia.assert(sortedNameAsc);
    let prevName = "";
    for (const e of sortedNameAsc.data) {
      TestValidator.predicate("name 정렬 오름차순")(prevName <= e.name);
      prevName = e.name;
    }
    // 6. created_at 내림차순 정렬
    const sortedCreatedAtDesc = await api.functional.advancedAI.aiFeatureStore.patch(connection, {
      body: {
        sort_by: "created_at",
        order: "desc",
      },
    });
    typia.assert(sortedCreatedAtDesc);
    let prevDate = new Date(sortedCreatedAtDesc.data[0]?.created_at ?? 0).getTime();
    for (const e of sortedCreatedAtDesc.data.slice(1)) {
      TestValidator.predicate("created_at 정렬 내림차순")(new Date(e.created_at).getTime() <= prevDate);
      prevDate = new Date(e.created_at).getTime();
    }
  }

  // 7. 과도하게 제한적인 필터(매칭되는 데이터 없음)
  const notFound = await api.functional.advancedAI.aiFeatureStore.patch(connection, {
    body: {
      name: "no-such--feature-set-name-1234567890",
    },
  });
  typia.assert(notFound);
  TestValidator.equals("불가능한 필터의 빈 결과")(0)(notFound.data.length);
  TestValidator.predicate("pagination 오브젝트 존재")(typeof notFound.pagination === "object");
}

