import { tags } from "typia";

/**
 * Full metadata for a review media entry, as stored in review_media table.
 * Supports evidence preservation, a11y, and multimedia compliance as per
 * requirements and DB schema comments.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IReviewMedia = {
  /**
   * Primary key. Unique identifier for this review media asset.
   *
   * Defined in the 'review_media' Prisma model.
   */
  id: string & tags.Format<"uuid">;

  /**
   * The review to which this media is attached. References reviews.id.
   *
   * Critical for evidence chain and UI rendering.
   */
  review_id: string & tags.Format<"uuid">;

  /**
   * Type/category of the media, such as 'image', 'video', etc.
   *
   * Atomic, normalized field from review_media.media_type.
   */
  media_type: string;

  /**
   * URI or URL to the actual media file/asset. Not stored as a blob, only as
   * reference.
   *
   * References review_media.uri in the schema.
   */
  uri: string;

  /**
   * Accessibility alt-text for a11y compliance and barrier-free design.
   *
   * References review_media.alt_text.
   */
  alt_text?: string | null;

  /**
   * Order or display sequence for UI ranking.
   *
   * Taken from review_media.sequence, supports ordered galleries.
   */
  sequence: number & tags.Type<"int32">;
};
export namespace IReviewMedia {
  /**
   * Structure for creating a new media asset attached to a review. All fields
   * validated against review_media schema for evidence compliance, a11y, and
   * UI integration.
   */
  export type ICreate = {
    /**
     * ID of the review this media is attached to.
     *
     * Maps to review_media.review_id. Required for referential integrity
     * and evidence compliance.
     */
    review_id: string & tags.Format<"uuid">;

    /**
     * Type of the media (e.g., 'image', 'video').
     *
     * References review_media.media_type in the schema.
     */
    media_type: string;

    /**
     * URL/URI to the media asset (image, video, PDF, etc.).
     *
     * As per review_media.uri in database. Ensures content is only
     * referenced, not stored.
     */
    uri: string;

    /**
     * Accessibility alt-text for barrier-free compliance.
     *
     * Review_media.alt_text field in the Prisma schema.
     */
    alt_text?: string | null;

    /**
     * Integer describing order or gallery sequence.
     *
     * Review_media.sequence in the schema for UI presentation.
     */
    sequence: number & tags.Type<"int32">;
  };
}

