import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IReviewMedia } from "@ORGANIZATION/PROJECT-api/lib/structures/IReviewMedia";

/**
 * Validate fetching a review media record by ID, covering both existing and nonexistent cases
 *
 * This test ensures the review media GET endpoint functions as required for compliance, a11y, and audit evidence.
 *
 * Steps:
 * 1. Create a new review media record to ensure a known ID is present.
 * 2. Fetch the review media by this ID. Confirm that: (a) all metadata fields match what was created; (b) the returned URI, media_type, and sequence are as expected; (c) type and format validity.
 * 3. Attempt to fetch a review media record by a UUID that does not exist in the system. Confirm that the endpoint returns the correct 404 error (not found).
 */
export async function test_api_communicationReview_reviewMedia_getById(
  connection: api.IConnection,
) {
  // 1. Create a new review media
  const createInput: IReviewMedia.ICreate = {
    review_id: typia.random<string & tags.Format<"uuid">>(),
    media_type: "image",
    uri: "https://example.com/media/test.jpg",
    alt_text: "Description of test image for a11y",
    sequence: 1,
  };
  const created: IReviewMedia = await api.functional.communicationReview.reviewMedia.post(connection, { body: createInput });
  typia.assert(created);
  // 2. Fetch the review media by valid ID
  const fetched: IReviewMedia = await api.functional.communicationReview.reviewMedia.getById(connection, { id: created.id });
  typia.assert(fetched);
  TestValidator.equals("review_id")(created.review_id)(fetched.review_id);
  TestValidator.equals("media_type")(created.media_type)(fetched.media_type);
  TestValidator.equals("uri")(created.uri)(fetched.uri);
  TestValidator.equals("alt_text")(created.alt_text)(fetched.alt_text);
  TestValidator.equals("sequence")(created.sequence)(fetched.sequence);
  // 3. Fetch a review media by a non-existent ID (should 404)
  const randomId = typia.random<string & tags.Format<"uuid">>();
  TestValidator.error("not found (404) for nonexistent ID")(async () => {
    await api.functional.communicationReview.reviewMedia.getById(connection, { id: randomId });
  });
}

