import api from "@ORGANIZATION/PROJECT-api";
import type { IReviewMedia } from "@ORGANIZATION/PROJECT-api/lib/structures/IReviewMedia";

/**
 * E2E validation for creation of review media entries (review_media table).
 *
 * This test validates both successful and failure cases for creating media assets attached to reviews. It ensures:
 * 1. A review media entry with valid data (review_id, media_type, uri, sequence, optionally alt_text) can be created, and the correct metadata is returned.
 * 2. Attempts to create a review media entry missing required fields (e.g., missing review_id, uri, etc.) fail with proper validation errors.
 *
 * Steps:
 * 1. Compose fully valid input for IReviewMedia.ICreate and call the creation endpoint, verifying the positive path.
 * 2. For each required property, try omitting it or providing an invalid value, ensure the API responds with a validation error and does not create the record.
 * 3. Ensure negative cases are checked for all fields required by IReviewMedia.ICreate; 'alt_text' is optional.
 */
export async function test_api_communicationReview_test_create_review_media_with_valid_and_invalid_input(connection: api.IConnection) {
  // 1. Success case: Create review media with valid data
  const validInput: IReviewMedia.ICreate = {
    review_id: typia.random<string & tags.Format<"uuid">>(),
    media_type: "image",
    uri: "https://media-cdn.example.com/path/to/image.jpg",
    sequence: 1,
    alt_text: "Evidence for review details",
  };

  const creation = await api.functional.communicationReview.reviewMedia.post(connection, { body: validInput });
  typia.assert(creation);
  TestValidator.equals("review_id")(creation.review_id)(validInput.review_id);
  TestValidator.equals("media_type")(creation.media_type)(validInput.media_type);
  TestValidator.equals("uri")(creation.uri)(validInput.uri);
  TestValidator.equals("sequence")(creation.sequence)(validInput.sequence);
  TestValidator.equals("alt_text")(creation.alt_text)(validInput.alt_text);

  // 2. Validation: Try omitting each required field - should fail
  // a. Missing review_id
  await TestValidator.error("Missing review_id should fail")(() =>
    api.functional.communicationReview.reviewMedia.post(connection, {
      body: {
        // review_id: omitted
        media_type: "image",
        uri: "https://media-cdn.example.com/path/to/image.jpg",
        sequence: 2,
      } as any, // purposely triggers validation error
    })
  );

  // b. Missing media_type
  await TestValidator.error("Missing media_type should fail")(() =>
    api.functional.communicationReview.reviewMedia.post(connection, {
      body: {
        review_id: typia.random<string & tags.Format<"uuid">>(),
        // media_type: omitted
        uri: "https://media-cdn.example.com/path/to/image.jpg",
        sequence: 3,
      } as any,
    })
  );

  // c. Missing uri
  await TestValidator.error("Missing uri should fail")(() =>
    api.functional.communicationReview.reviewMedia.post(connection, {
      body: {
        review_id: typia.random<string & tags.Format<"uuid">>(),
        media_type: "video",
        // uri: omitted
        sequence: 4,
      } as any,
    })
  );

  // d. Missing sequence
  await TestValidator.error("Missing sequence should fail")(() =>
    api.functional.communicationReview.reviewMedia.post(connection, {
      body: {
        review_id: typia.random<string & tags.Format<"uuid">>(),
        media_type: "audio",
        uri: "https://media-cdn.example.com/path/to/audio.mp3",
        // sequence: omitted
      } as any,
    })
  );

  // 3. Negative: Provide all required fields but with null/invalid types
  await TestValidator.error("Null review_id should fail")(() =>
    api.functional.communicationReview.reviewMedia.post(connection, {
      body: {
        review_id: null,
        media_type: "image",
        uri: "https://media-cdn.example.com/path/to/image.jpg",
        sequence: 5,
      } as any,
    })
  );
  await TestValidator.error("Null media_type should fail")(() =>
    api.functional.communicationReview.reviewMedia.post(connection, {
      body: {
        review_id: typia.random<string & tags.Format<"uuid">>(),
        media_type: null,
        uri: "https://media-cdn.example.com/path/to/image.jpg",
        sequence: 6,
      } as any,
    })
  );
  await TestValidator.error("Null uri should fail")(() =>
    api.functional.communicationReview.reviewMedia.post(connection, {
      body: {
        review_id: typia.random<string & tags.Format<"uuid">>(),
        media_type: "image",
        uri: null,
        sequence: 7,
      } as any,
    })
  );
  await TestValidator.error("Null sequence should fail")(() =>
    api.functional.communicationReview.reviewMedia.post(connection, {
      body: {
        review_id: typia.random<string & tags.Format<"uuid">>(),
        media_type: "image",
        uri: "https://media-cdn.example.com/path/to/image.jpg",
        sequence: null,
      } as any,
    })
  );

  // 4. Optional field alt_text can be omitted or null and still succeed
  const minimalInput: IReviewMedia.ICreate = {
    review_id: typia.random<string & tags.Format<"uuid">>(),
    media_type: "video",
    uri: "https://media-cdn.example.com/path/to/video.mp4",
    sequence: 8,
  };
  const creation2 = await api.functional.communicationReview.reviewMedia.post(connection, { body: minimalInput });
  typia.assert(creation2);
  TestValidator.equals("review_id")(creation2.review_id)(minimalInput.review_id);
  TestValidator.equals("media_type")(creation2.media_type)(minimalInput.media_type);
  TestValidator.equals("uri")(creation2.uri)(minimalInput.uri);
  TestValidator.equals("sequence")(creation2.sequence)(minimalInput.sequence);
  TestValidator.equals("alt_text")(creation2.alt_text)(undefined);
}

