import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ICartOrderOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/ICartOrderOrder";
import type { IOrderStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/IOrderStatus";

/**
 * Validate creation of order status lifecycle event records, including success and error scenarios
 *
 * This test ensures that new order_status records can be created for valid orders, that invalid foreign keys are rejected,
 * and that missing required fields are schema-validated. It covers positive-case creation as well as negative/edge cases.
 *
 * Steps:
 * 1. Create a new order using valid user_id and cart_id (requires a valid UUID for each)
 * 2. Create a new order_status event linked to the created order_id, with a valid status_code and timestamp; assert success
 * 3. Attempt to create an order_status with a random, non-existent order_id; assert foreign-key error or not-found failure
 * 4. Attempt to create an order_status with missing required fields (e.g., status_code/timestamp); expect validation error
 */
export async function test_api_cartOrder_test_create_order_status_valid_and_invalid_cases(
  connection: api.IConnection,
) {
  // 1. Create a new order for status event testing
  const userId = typia.random<string & tags.Format<"uuid">>();
  const cartId = typia.random<string & tags.Format<"uuid">>();
  const order = await api.functional.cartOrder.order.post(connection, {
    body: {
      user_id: userId,
      cart_id: cartId,
    } satisfies ICartOrderOrder.ICreate
  });
  typia.assert(order);

  // 2. Create a valid order_status event
  const now = new Date().toISOString();
  const status = await api.functional.cartOrder.orderStatus.post(connection, {
    body: {
      order_id: order.id,
      status_code: "paid",
      changed_at: now,
      changed_by: userId,
    } satisfies IOrderStatus.ICreate
  });
  typia.assert(status);
  TestValidator.equals("order_id")(order.id)(status.order_id);

  // 3. Try to create order_status with non-existing order_id
  await TestValidator.error("non-existent order_id fails")(() =>
    api.functional.cartOrder.orderStatus.post(connection, {
      body: {
        order_id: typia.random<string & tags.Format<"uuid">>(), // random UUID not linked to any order
        status_code: "paid",
        changed_at: now,
        changed_by: userId,
      } satisfies IOrderStatus.ICreate
    })
  );

  // 4. Try to create order_status missing required fields
  await TestValidator.error("missing required fields fails")(() =>
    // Remove status_code to verify schema enforcement
    api.functional.cartOrder.orderStatus.post(connection, {
      body: {
        order_id: order.id,
        // status_code missing
        changed_at: now,
        changed_by: userId,
      } as any // Will fail at runtime due to schema validation
    })
  );
}

