import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IOrderStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/IOrderStatus";

/**
 * 테스트 목적: CartOrder.order_status(주문 상태 이력) API의 수정(putById) 동작을 종합적으로 검증한다.
 *
 * 비즈니스 컨텍스트: 주문 상태(state)는 이커머스 오더의 라이프사이클과 컴플라이언스 감사에 핵심이다. 변경 기록은 불변/감사 필요. 실수, 이벤트 구독자 트리거, 운영 및 규제 시나리오 등 다양한 케이스에서 상태값의 변경이 요구된다.
 *
 * 1. 우선, 정상 케이스 검증을 위해 order_status 엔트리를 새로 생성한다.
 * 2. 생성된 order_status에 대해, status_code와 changed_at 일부 필드만 부분적으로 업데이트 한다.
 *  2-1. update 결과가 정상적으로 반영되었는지 단언한다.
 * 3. 존재하지 않는 id(정상적 uuid이긴 하나 실제 데이터가 없음)로 update 시도를 하여 not found(404) 오류 발생을 검증한다.
 * 4. 유효하지 않은 status_code(예: 빈 문자열) 등으로 업데이트 시 400 validation 오류가 반환되는지 검증한다.
 * 5. 필수 필드 누락(아예 body를 빈 오브젝트로 전달) 시 validation 오류를 검증한다.
 */
export async function test_api_cartOrder_test_update_order_status_various_cases(connection: api.IConnection) {
  // 1. 유효한 상태값 생성 (테스트 준비)
  const created: IOrderStatus = await api.functional.cartOrder.orderStatus.post(connection, {
    body: {
      order_id: typia.random<string & tags.Format<"uuid">>(),
      status_code: "pending",
      changed_at: new Date().toISOString(),
      changed_by: typia.random<string & tags.Format<"uuid">>(),
    }
  });
  typia.assert(created);

  // 2. 일부 필드(status_code, changed_at)만 정상적으로 업데이트
  const updated: IOrderStatus = await api.functional.cartOrder.orderStatus.putById(connection, {
    id: created.id,
    body: {
      status_code: "paid",
      changed_at: new Date(Date.now() + 1000 * 60).toISOString(),
    }
  });
  typia.assert(updated);
  TestValidator.equals("order_id should not change")(created.order_id)(updated.order_id);
