  const created = await api.functional.cartOrder.orderStatus.post(connection, {
    body: {
      order_id: typia.random<string & tags.Format<"uuid">>(),
      status_code: "pending",
      changed_at: new Date().toISOString(),
      changed_by: typia.random<string & tags.Format<"uuid">>(),
    },
  });
  typia.assert(created);

  // 2. 정상 업데이트: status_code, changed_at 갱신만
  const updated = await api.functional.cartOrder.orderStatus.putById(connection, {
    id: created.id,
    body: {
      status_code: "paid",
      changed_at: new Date(Date.now() + 60 * 1000).toISOString(),
