 * - Deleting must not break audit trail; querying the ID must fail for active list, but remain in evidence log if queried as audit.
 *
 * Test Steps:
 * 1. Create a new order_status for a randomly generated order ID (simulate real transition, use unique uuid and code).
 * 2. Delete the status by its returned ID via eraseById().
 * 3. Attempt to retrieve the deleted status in a hypothetical list (if API supported)—instead, confirm erasure response is ok: true.
 * 4. Attempt to delete again with the same ID (should result in not found or error—if API gives meaningful error or ok: false, validate behavior).
 * 5. Attempt to delete a status with a random non-existent UUID (should return not found error—validate this is handled and does not return ok: true).
 * 6. (If reading audit trail is supported, confirm the deleted status persists for audit.)
 */
export async function test_api_cartOrder_test_delete_order_status_valid_and_invalid_id(
  connection: api.IConnection,
) {
