  const orderId: string = typia.random<string & tags.Format<"uuid">>();
  const createdStatus = await api.functional.cartOrder.orderStatus.post(connection, {
    body: {
      order_id: orderId,
      status_code: RandomGenerator.pick(["pending", "processing", "shipped", "delivered"]) ,
      changed_at: new Date().toISOString(),
      changed_by: null,
    },
  });
  typia.assert(createdStatus);

  // 2. Delete by its ID
  const eraseResult = await api.functional.cartOrder.orderStatus.eraseById(connection, {
    id: createdStatus.id,
  });
  typia.assert(eraseResult);
  TestValidator.equals("erase ok")(true)(eraseResult.ok);

  // 3. Attempt to delete again (should error or return not-ok)
  await TestValidator.error("second erase should fail")(async () => {
    await api.functional.cartOrder.orderStatus.eraseById(connection, {
      id: createdStatus.id,
    });
  });

  // 4. Attempt to delete with non-existent ID (should error)
  await TestValidator.error("erase with invalid id fails")(async () => {
    await api.functional.cartOrder.orderStatus.eraseById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
    });
  });
}

