import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IOrderLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IOrderLog";
import type { IPageIOrderLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIOrderLog";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * E2E 테스트: 주문 로그의 필터링 및 페이지네이션 기능 검증
 *
 * 이 테스트는 /cartOrder/orderLog PATCH 엔드포인트의 정교한 리스트/검색 기능에 대한 종합적인 시나리오를 검증합니다. 실제 사용 맥락에서, 대량의 주문 처리와 이력 조사가 필요한 경우를 가정하여 다양한 조건과 페이지네이션 조합, 그리고 잘못된 입력값 처리까지 모두 점검합니다.
 *
 * [주요 테스트 단계]
 * 1. 여러 서로 다른 order_id와 event_type을 혼합하여, 다양한 조건의 order_log 데이터 기록을 10개 이상 생성한다.
 * 2. order_id로만 필터링 요청 → 해당 order_id의 데이터만 추출되는지 검증한다.
 * 3. event_type으로만 필터링 요청 → 지정 event_type만 반환되는지 검증한다.
 * 4. order_id + event_type 동시에 필터 → AND 조건이 정확히 반영되는지 확인.
 * 5. paging: limit=3, page=2로 요청 → 3개씩 끊어서 2번째 페이지가 기대 데이터만 반환되는지 검증.
 * 6. 잘못된 order_id, 잘못된 event_type 입력 시 빈 데이터 또는 에러가 안전하게 반환되는지 확인한다.
 * 7. 잘못된 페이징(음수, 0) 등 입력값 오류시 적정 안전 결과 반환 확인.
 */
export async function test_api_cartOrder_test_list_order_log_filtering_and_pagination(
  connection: api.IConnection,
) {
  // 1. 여러 조합의 주문 로그 10개 이상 생성
  const orderIds = ArrayUtil.repeat(3)(() => typia.random<string & tags.Format<"uuid">>());
  const eventTypes = ["create", "update", "status_change", "attach_evidence"];
  const createdLogs: IOrderLog[] = [];
  for (let i = 0; i < 12; ++i) {
    const log = await api.functional.cartOrder.orderLog.post(connection, {
      body: {
        order_id: RandomGenerator.pick(orderIds),
        event_type: RandomGenerator.pick(eventTypes),
        event_time: new Date(Date.now() - i * 60000).toISOString(),
        evidence_id: null,
        event_description: `log-${i}`,
        actor_id: typia.random<string & tags.Format<"uuid">>(),
      } satisfies IOrderLog.ICreate
    });
    typia.assert(log);
    createdLogs.push(log);
  }

  // 2. order_id 필터
  const orderIdToTest = orderIds[1];
  const respOrderId = await api.functional.cartOrder.orderLog.patch(connection, {
    body: { order_id: orderIdToTest }
  });
  typia.assert(respOrderId);
  TestValidator.predicate("order_id로 필터링된 모든 로그는 해당 order_id이어야 함")(
    respOrderId.data.every(log => log.order_id === orderIdToTest)
  );

  // 3. event_type 필터
  const eventTypeToTest = eventTypes[2];
  const respEventType = await api.functional.cartOrder.orderLog.patch(connection, {
    body: { event_type: eventTypeToTest }
  });
  typia.assert(respEventType);
  TestValidator.predicate("event_type으로 필터링된 로그만 반환되어야 함")(
    respEventType.data.every(log => log.event_type === eventTypeToTest)
  );

  // 4. order_id + event_type 동시 필터
  const respBoth = await api.functional.cartOrder.orderLog.patch(connection, {
    body: {
      order_id: orderIdToTest,
      event_type: eventTypeToTest
    }
  });
  typia.assert(respBoth);
  TestValidator.predicate("order_id와 event_type 모두 일치")(
    respBoth.data.every(log => log.order_id === orderIdToTest && log.event_type === eventTypeToTest)
  );

  // 5. 페이징 체크: limit=3, page=2
  const respPaging = await api.functional.cartOrder.orderLog.patch(connection, {
    body: { limit: 3, page: 2 }
  });
  typia.assert(respPaging);
  TestValidator.equals("페이지 용량 확인")(3)(respPaging.pagination.limit);
  TestValidator.equals("현재 페이지 존재")(2)(respPaging.pagination.current);
  TestValidator.equals("데이터 개수 3개")(3)(respPaging.data.length);

  // 6. 잘못된 order_id/event_type → 빈 데이터
  const respInvalidOrderId = await api.functional.cartOrder.orderLog.patch(connection, {
    body: { order_id: typia.random<string & tags.Format<"uuid">>() }
  });
  typia.assert(respInvalidOrderId);
  TestValidator.equals("잘못된 order_id 입력은 empty 결과")(0)(respInvalidOrderId.data.length);

  const respInvalidEventType = await api.functional.cartOrder.orderLog.patch(connection, {
    body: { event_type: "non_existent_event_type" }
  });
  typia.assert(respInvalidEventType);
  TestValidator.equals("존재하지 않는 event_type은 empty 결과")(0)(respInvalidEventType.data.length);

  // 7. 잘못된 페이지 번호/limit(0, 음수 등) → 안전 케이스
  await TestValidator.error("page=0 입력시 에러")(() =>
    api.functional.cartOrder.orderLog.patch(connection, {
      body: { page: 0 }
    })
  );
  await TestValidator.error("limit=0 입력시 에러")(() =>
    api.functional.cartOrder.orderLog.patch(connection, {
      body: { limit: 0 }
    })
  );
}

