/**
 * Get a single order_log entry (CartOrder.order_log) by ID.
 *
 * This API fetches one specific order_log entry using its unique identifier.
 * Returned details include the exact event_type, description, timestamp,
 * evidence linkage (if any), and actor responsible. This supports auditability,
 * dispute resolution, and evidence preservation for each event in an order’s
 * lifecycle. Access is restricted according to security and compliance
 * policies. Related operations handle listing, creation, update, and deletion
 * for ongoing event/audit management.
 *
 * @param props.connection
 * @param props.id Target order_log entry's ID
 * @path /cartOrder/orderLog/:id
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export async function getById(
  connection: IConnection,
  props: getById.Props,
