import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IOrderLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IOrderLog";

/**
 * Test for fetching order_log entry by ID (both existing and non-existing).
 *
 * This E2E test verifies retrieval of an order_log entry using a valid ID, confirming all required fields and content are present and correct. It also attempts to retrieve a non-existing order_log by a random UUID, and checks for proper not found error handling.
 *
 * Steps:
 * 1. Create a valid order_log entry via the post endpoint (to guarantee we have an existing entry).
 * 2. Fetch the order_log by its returned ID. Assert all properties are as expected, typia asserts the output type.
 * 3. Attempt to fetch an order_log with a random UUID that does not exist in the system.
 * 4. Assert that the API returns a proper not found (error) response for non-existent ID.
 */
export async function test_api_cartOrder_test_get_order_log_by_id_valid_and_invalid(connection: api.IConnection) {
  // 1. Create required log for testing retrieval
  const logInput: IOrderLog.ICreate = {
    order_id: typia.random<string & tags.Format<"uuid">>(),
    event_type: "status_change", // Example event type
    event_time: new Date().toISOString(),
    evidence_id: null,
    event_description: "Order moved to shipped status.",
    actor_id: typia.random<string & tags.Format<"uuid">>(),
  };
  const created: IOrderLog = await api.functional.cartOrder.orderLog.post(connection, { body: logInput });
  typia.assert(created);

  // 2. Fetch by valid ID
  const found: IOrderLog = await api.functional.cartOrder.orderLog.getById(connection, { id: created.id });
  typia.assert(found);
  TestValidator.equals("id matches")(created.id)(found.id);
  TestValidator.equals("order_id matches")(created.order_id)(found.order_id);
  TestValidator.equals("event_type matches")(created.event_type)(found.event_type);
  TestValidator.equals("event_description matches")(created.event_description)(found.event_description);
  TestValidator.equals("event_time matches")(created.event_time)(found.event_time);
  TestValidator.equals("actor_id matches")(created.actor_id)(found.actor_id);

  // 3. Fetch with random (non-existent) ID
  const invalidId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("not found for non-existing id")(async () => {
    await api.functional.cartOrder.orderLog.getById(connection, { id: invalidId });
  });
}

