import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ICartOrderOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/ICartOrderOrder";
import type { IOrderLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IOrderLog";

/**
 * Validate logging of order events with correct and incorrect data.
 *
 * This test checks creation of order event log entries (order_log) using both valid and invalid scenarios for CartOrder.order_log POST endpoint. Includes setup for order creation, order_log creation, and error validation for missing/invalid references/fields.
 *
 * Steps:
 * 1. Create a valid order via CartOrder.order POST (dependency).
 * 2. Create an order_log entry for this order with valid event details and ensure result is persisted and structure correct.
 * 3. Attempt to create an order_log using a non-existent order_id and check for rejection.
 * 4. Attempt to create an order_log with missing mandatory fields (e.g., missing event_type or event_time) and validate error response.
 * 5. (Optional) If supported by the API, retrieve or list order logs for the order to confirm the creation in step 2.
 *
 * Expected: Valid logs are accepted and persisted, invalid data produces error responses without side-effects.
 */
export async function test_api_cartOrder_test_create_order_log_valid_and_invalid_data(
  connection: api.IConnection,
) {
  // 1. Create a valid order to log events against
  const user_id = typia.random<string & tags.Format<'uuid'>>();
  const cart_id = typia.random<string & tags.Format<'uuid'>>();
  const order = await api.functional.cartOrder.order.post(connection, {
    body: {
      user_id,
      cart_id
    } satisfies ICartOrderOrder.ICreate
  });
  typia.assert(order);

  // 2. Create a valid order_log entry
  const now = new Date().toISOString();
  const validEventType = "status_change";
  const log = await api.functional.cartOrder.orderLog.post(connection, {
    body: {
      order_id: order.id,
      event_type: validEventType,
      event_time: now,
      event_description: "Order status changed to PAID",
      actor_id: order.user_id
    } satisfies IOrderLog.ICreate
  });
  typia.assert(log);
  TestValidator.equals("order_id")(order.id)(log.order_id);
  TestValidator.equals("event_type")(validEventType)(log.event_type);

  // 3. Attempt to create an order_log for a non-existent order
  const fakeOrderId = typia.random<string & tags.Format<'uuid'>>();
  await TestValidator.error("order_log with nonexistent order_id fails")(() =>
    api.functional.cartOrder.orderLog.post(connection, {
      body: {
        order_id: fakeOrderId,
        event_type: "nonexistent_order_event",
        event_time: now
      } satisfies IOrderLog.ICreate
    })
  );

  // 4. Attempt to create an order_log with missing/invalid required fields
  await TestValidator.error("order_log missing event_type fails")(() =>
    api.functional.cartOrder.orderLog.post(connection, {
      body: {
        order_id: order.id,
        event_time: now
        // event_type omitted intentionally
      } as any // Typescript would error, test only for runtime error
    })
  );

  await TestValidator.error("order_log missing event_time fails")(() =>
    api.functional.cartOrder.orderLog.post(connection, {
      body: {
        order_id: order.id,
        event_type: validEventType
        // event_time omitted intentionally
      } as any // Typescript would error, test only for runtime error
    })
  );
}

