import { tags } from "typia";

/**
 * Order event/audit log entry from CartOrder.order_log table.
 *
 * Implements evidence-grade change, status, or attached documentation
 * auditability. Core for compliance, regulatory export, post-facto forensics,
 * and advanced analytics cycles.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IOrderLog = {
  /** Unique identifier for log entry. PK in CartOrder.order_log. */
  id: string & tags.Format<"uuid">;

  /** Reference to parent order (CartOrder.order.id). */
  order_id: string & tags.Format<"uuid">;

  /**
   * Reference to attached order evidence, if any (order_evidence.id). Null if
   * no evidence attached to this event.
   */
  evidence_id?: (string & tags.Format<"uuid">) | null;

  /**
   * Type of event: e.g., 'create', 'update', 'status_change',
   * 'attach_evidence'. Per requirements' state/event taxonomy.
   */
  event_type: string;

  /**
   * Narrative or annotation describing the event. Used for audit and
   * analytics.
   */
  event_description?: string;

  /** UTC timestamp when the event occurred. */
  event_time: string & tags.Format<"date-time">;

  /**
   * User or system actor responsible for the event. Null if executed by
   * system automation.
   */
  actor_id?: (string & tags.Format<"uuid">) | null;
};
export namespace IOrderLog {
  /**
   * Payload for creating a new order event/audit log entry
   * (CartOrder.order_log).
   *
   * All fields undergo strict parsing/audit for evidence preservation and
   * compliance. Adheres to immutability requirements for workflow and legal
   * reporting.
   */
  export type ICreate = {
    /** Order ID for which to record this log event (CartOrder.order.id). */
    order_id: string & tags.Format<"uuid">;

    /** If attaching external evidence, its ID (order_evidence.id). */
    evidence_id?: (string & tags.Format<"uuid">) | null;

    /**
     * Type of event: must be valid under system state/event taxonomy. E.g.,
     * 'create', 'update', 'status_change', 'attach_evidence'.
     */
    event_type: string;

    /**
     * Narrative or annotation for event, for audit trace.
     *
     * Required for evidence-related or non-mechanical events.
     */
    event_description?: string;

    /** UTC timestamp of event occurrence, for evidence purposes. */
    event_time: string & tags.Format<"date-time">;

    /** Responsible user/system actor (users.id). Null for system events. */
    actor_id?: (string & tags.Format<"uuid">) | null;
  };

  /**
   * Payload for updating permitted mutable fields of an order log entry.
   *
   * Used for audit corrections, additional evidence, or regulatory
   * supplementation. Strictly controlled by business logic. Each update is
   * fully logged for evidence traceability.
   */
  export type IUpdate = {
    /** If correcting or attaching evidence to the event post-facto. */
    evidence_id?: (string & tags.Format<"uuid">) | null;

    /** Corrected event type, if compliance or regulatory correction needed. */
    event_type?: string;

    /**
     * Revision/addendum to event note for compliance or explanatory
     * purposes.
     */
    event_description?: string;

    /** Corrected event time (rarely updated; subject to compliance). */
    event_time?: string & tags.Format<"date-time">;

    /** Correction/addition of responsible actor. */
    actor_id?: (string & tags.Format<"uuid">) | null;
  };
}

