import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IOrderLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IOrderLog";

/**
 * E2E test for order_log metadata update (PUT /cartOrder/orderLog/{id})
 *
 * This test validates the ability to update mutable fields of an order log entry.
 * 1. Create a new order log entry first.
 * 2. Perform a valid update on its metadata (change event_type, event_description, event_time, and actor_id).
 * 3. Verify the changes are reflected while immutable fields remain unchanged and a new audit snapshot is made/preserved.
 * 4. Attempt to update a non-existent order_log ID and verify a not found error (404 or appropriate error handling).
 * 5. Attempt to update with bad data (e.g. invalid uuid format, missing required field in body) and check that validation errors are raised.
 */
export async function test_api_cartOrder_test_update_order_log_metadata(connection: api.IConnection) {
  // 1. Create a new order log for a specific order (dependency)
  const newLog = await api.functional.cartOrder.orderLog.post(connection, {
    body: {
      order_id: typia.random<string & tags.Format<"uuid">>(),
      event_type: "create",
      event_time: new Date().toISOString(),
      evidence_id: null,
      actor_id: null,
      event_description: "Initial creation log for order"
    } satisfies IOrderLog.ICreate,
  });
  typia.assert(newLog);

  // 2. Update the mutable fields using putById
  const updatedInput = {
    event_type: "status_change",
    event_description: "Order status updated to shipped",
    event_time: new Date(Date.now() + 1000 * 60 * 60).toISOString(),
    actor_id: typia.random<string & tags.Format<"uuid">>()
  } satisfies IOrderLog.IUpdate;

  const updatedLog = await api.functional.cartOrder.orderLog.putById(connection, {
    id: newLog.id,
    body: updatedInput,
  });
  typia.assert(updatedLog);
  // Confirm updated fields
  TestValidator.equals("event_type change")(updatedInput.event_type)(updatedLog.event_type);
  TestValidator.equals("event_description change")(updatedInput.event_description)(updatedLog.event_description);
  TestValidator.equals("event_time change")(updatedInput.event_time)(updatedLog.event_time);
  TestValidator.equals("actor_id change")(updatedInput.actor_id)(updatedLog.actor_id);
  // Confirm immutable fields remain
  TestValidator.equals("order_id remains")(newLog.order_id)(updatedLog.order_id);
  TestValidator.equals("id remains")(newLog.id)(updatedLog.id);

  // 3. Try to update a nonexistent order_log ID
  await TestValidator.error("404 not found on invalid id")(async () => {
    await api.functional.cartOrder.orderLog.putById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
      body: updatedInput,
    });
  });

  // 4. Invalid update: missing all fields (should error)
  await TestValidator.error("validation error on empty body")(async () => {
    await api.functional.cartOrder.orderLog.putById(connection, {
      id: newLog.id,
      body: {} as IOrderLog.IUpdate,
    });
  });

  // 5. Invalid update: invalid format for actor_id (string but not uuid)
  await TestValidator.error("validation error on invalid actor_id")(async () => {
    await api.functional.cartOrder.orderLog.putById(connection, {
      id: newLog.id,
      body: { actor_id: "not-a-uuid" } as IOrderLog.IUpdate,
    });
  });
}

