import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IOrderLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IOrderLog";

/**
 * E2E test for updating order_log metadata (PUT /cartOrder/orderLog/{id})
 *
 * This test ensures:
 * 1. Proper update of mutable fields (event_type, event_description, event_time, actor_id)
 * 2. Immutability of the primary fields (id, order_id)
 * 3. Existence and error handling for non-existent log IDs
 * 4. Validation on missing/invalid input data
 *
 * Steps:
 * 1. Create a new order_log via the dependency POST.
 * 2. Update the log's mutable fields and assert changes.
 * 3. Attempt update with a nonexistent log ID and expect an error.
 * 4. Attempt update with invalid input data and expect validation errors.
 */
export async function test_api_cartOrder_test_update_order_log_metadata(
  connection: api.IConnection,
) {
  // 1. Create a new order_log as a dependency for update
  const createBody: IOrderLog.ICreate = {
    order_id: typia.random<string & tags.Format<"uuid">>(),
    event_type: "create",
    event_time: new Date().toISOString(),
    event_description: "Initial creation log for update test",
    evidence_id: null,
    actor_id: null,
  };
  const orderLog = await api.functional.cartOrder.orderLog.post(connection, {
    body: createBody,
  });
  typia.assert(orderLog);

  // 2. Valid update: change event_type, event_description, event_time, actor_id
  const updateInput: IOrderLog.IUpdate = {
    event_type: "status_change",
    event_description: "Order log update: status shipped",
    event_time: new Date(Date.now() + 60 * 60 * 1000).toISOString(), // +1h
    actor_id: typia.random<string & tags.Format<"uuid">>(),
  };
  const updated = await api.functional.cartOrder.orderLog.putById(connection, {
    id: orderLog.id,
    body: updateInput,
  });
  typia.assert(updated);
  // Verify mutable changes
  TestValidator.equals("event_type changed")(updateInput.event_type)(updated.event_type);
  TestValidator.equals("event_description changed")(updateInput.event_description)(updated.event_description);
  TestValidator.equals("event_time changed")(updateInput.event_time)(updated.event_time);
  TestValidator.equals("actor_id changed")(updateInput.actor_id)(updated.actor_id);
  // Immutable fields unchanged
  TestValidator.equals("order_id remains")(orderLog.order_id)(updated.order_id);
  TestValidator.equals("id remains")(orderLog.id)(updated.id);
  // Optional field (evidence_id) remains as before
  TestValidator.equals("evidence_id remains")(orderLog.evidence_id)(updated.evidence_id);

  // 3. Error: update on nonexistent ID
  await TestValidator.error("404 not found for invalid order_log id")(async () => {
    await api.functional.cartOrder.orderLog.putById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
      body: updateInput,
    });
  });

  // 4. Error: submit empty update body (should be rejected)
  await TestValidator.error("update with empty object fails")(async () => {
    await api.functional.cartOrder.orderLog.putById(connection, {
      id: orderLog.id,
      body: {} as IOrderLog.IUpdate,
    });
  });

  // 5. Error: actor_id has invalid UUID format
  await TestValidator.error("invalid actor_id is rejected")(async () => {
    await api.functional.cartOrder.orderLog.putById(connection, {
      id: orderLog.id,
      body: { actor_id: "bad-uuid-format" } as IOrderLog.IUpdate,
    });
  });
}

