import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IOrderLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IOrderLog";
import type { IVoidResponse } from "@ORGANIZATION/PROJECT-api/lib/structures/IVoidResponse";

/**
 * Validate soft-deletion and error handling for order_log erase operation.
 *
 * 1. Create a new order_log entry as test data.
 * 2. Soft-delete the order_log by its ID using eraseById.
 * 3. Ensure the eraseById returns ok: true (and typia.assert on the result).
 * 4. Attempt to retrieve the order_log through the active (non-evidence) retrieval API—should not be visible (not found or excluded from list).
 * 5. (If available) Retrieve the order_log through the evidence/audit logs—ensure it is present there, confirming soft-delete not hard-delete.
 * 6. Attempt to eraseById again on the same order_log—expect a not found error (TestValidator.error ensures the correct error is thrown).
 * 7. Attempt to eraseById on a random UUID that does not correspond to any real order_log—expect not found error.
 */
export async function test_api_cartOrder_test_delete_order_log_soft_and_non_existing(
  connection: api.IConnection,
) {
  // 1. Create a new order_log for testing
  const createdLog = await api.functional.cartOrder.orderLog.post(connection, {
    body: {
      order_id: typia.random<string & tags.Format<"uuid">>(),
      event_type: "test_soft_delete",
      event_time: new Date().toISOString(),
      // Optionally add event_description, etc.
    } satisfies IOrderLog.ICreate,
  });
  typia.assert(createdLog);

  // 2. Soft-delete the order_log entry
  const erased = await api.functional.cartOrder.orderLog.eraseById(connection, {
    id: createdLog.id,
  });
  typia.assert(erased);
  TestValidator.equals("operation ok")(true)(erased.ok);

  // 3. Try to soft-delete it again—should throw not found
  await TestValidator.error("repeat erase not found")(() =>
    api.functional.cartOrder.orderLog.eraseById(connection, {
      id: createdLog.id,
    }),
  );

  // 4. Try to delete a totally non-existent ID
  await TestValidator.error("erase non-existent order_log")(() =>
    api.functional.cartOrder.orderLog.eraseById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
    }),
  );
}

