import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IOrderEvidence } from "@ORGANIZATION/PROJECT-api/lib/structures/IOrderEvidence";
import type { IPageIOrderEvidence } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIOrderEvidence";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Tests paginated and filterable retrieval of order_evidence records from CartOrder.
 *
 * Scenario:
 * - Create multiple order evidence records with distinct evidence_type, 
 *   provided_at and other fields.
 * - Validate paginated fetching, filtering by specific evidence_type, and date boundaries.
 * - Provide invalid filter values to check error handling (e.g., invalid date, non-existent evidence_type).
 *
 * Steps:
 * 1. Generate several order_evidence records via POST endpoint using a variety of evidence_type and provided_at.
 * 2. PATCH /cartOrder/orderEvidence to retrieve all records - ensure all created items are returned (pagination check).
 * 3. PATCH with a filter for a specific evidence_type and confirm only the matching records are returned.
 * 4. PATCH with from_time and to_time filters, confirm only the correct temporal records are included.
 * 5. PATCH with invalid date range, expect error or empty result.
 * 6. PATCH with non-existent evidence_type and check empty result.
 * 7. PATCH with invalid page/limit values (e.g., page=0, limit=500) to confirm error response.
 *
 * After each PATCH, assert that returned data matches the expected filter criteria, and pagination metadata is correct.
 */
export async function test_api_cartOrder_test_list_order_evidence_filtering_and_pagination(
  connection: api.IConnection,
) {
  // Step 1: Generate multiple order_evidence records
  const order_id = typia.random<string & tags.Format<"uuid">>();
  const evidence_records: IOrderEvidence[] = [];
  // Generate 5 evidence_types and 3 different timestamps
  const evidence_types = ["invoice", "signature", "photo", "receipt", "video"];
  const baseTime = new Date();
  const timestamps = [
    baseTime.toISOString(),
    new Date(baseTime.getTime() - 24 * 3600 * 1000).toISOString(), // -1 day
    new Date(baseTime.getTime() - 2 * 24 * 3600 * 1000).toISOString(), // -2 days
  ];
  for (const type of evidence_types) {
    for (const ts of timestamps) {
      const record = await api.functional.cartOrder.orderEvidence.post(connection, {
        body: {
          order_id: order_id,
          evidence_type: type,
          evidence_uri: RandomGenerator.alphaNumeric(30),
          provided_at: ts,
          provided_by: null,
        } satisfies IOrderEvidence.ICreate,
      });
      typia.assert(record);
      evidence_records.push(record);
    }
  }
  // Step 2: Fetch all records (no filter, default paging)
  const allRes = await api.functional.cartOrder.orderEvidence.patch(connection, {
    body: {
      order_id,
      page: 1,
      limit: 100,
    } satisfies IOrderEvidence.IRequest,
  });
  typia.assert(allRes);
  TestValidator.equals("records count")(evidence_records.length)(allRes.data.length);

  // Step 3: Filter by specific evidence_type
  const filterType = "photo";
  const filteredRes = await api.functional.cartOrder.orderEvidence.patch(connection, {
    body: {
      order_id,
      evidence_type: filterType,
    } satisfies IOrderEvidence.IRequest,
  });
  typia.assert(filteredRes);
  TestValidator.predicate("evidence_type filter")(
    filteredRes.data.every((r) => r.evidence_type === filterType)
  );

  // Step 4: Filter by from_time and to_time
  const dateRangeRes = await api.functional.cartOrder.orderEvidence.patch(connection, {
    body: {
      order_id,
      from_time: timestamps[1],
      to_time: timestamps[0],
    } satisfies IOrderEvidence.IRequest,
  });
  typia.assert(dateRangeRes);
  TestValidator.predicate("date range filter")(
    dateRangeRes.data.every((r) =>
      r.provided_at >= timestamps[1] && r.provided_at < timestamps[0]
    )
  );

  // Step 5: Invalid date range (from_time after to_time) - expect empty result or error
  await TestValidator.error("invalid date range")(() =>
    api.functional.cartOrder.orderEvidence.patch(connection, {
      body: {
        order_id,
        from_time: timestamps[0],
        to_time: timestamps[1],
      } satisfies IOrderEvidence.IRequest,
    })
  );

  // Step 6: Non-existent evidence_type filter yields empty data
  const noneType = "nonexistent_type";
  const noneRes = await api.functional.cartOrder.orderEvidence.patch(connection, {
    body: {
      order_id,
      evidence_type: noneType,
    } satisfies IOrderEvidence.IRequest,
  });
  typia.assert(noneRes);
  TestValidator.equals("no result for fake evidence_type")(0)(noneRes.data.length);

  // Step 7: Invalid page and limit (page=0, limit=500) - expect error
  await TestValidator.error("invalid pagination params")(() =>
    api.functional.cartOrder.orderEvidence.patch(connection, {
      body: {
        order_id,
        page: 0,
        limit: 500,
      } satisfies IOrderEvidence.IRequest,
    })
  );
}

