import { tags } from "typia";

/**
 * Evidence record for audit, compliance, or legal referencing, from
 * CartOrder.order_evidence Prisma table.
 *
 * Links to order, covers type/category, external reference (uri), and full
 * chain of custody for regulatory, dispute, and audit workflows. Immutable,
 * never physically deleted.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IOrderEvidence = {
  /**
   * Unique evidence record ID (CartOrder.order_evidence.id). PK for all
   * audit/legal workflows.
   */
  id: string & tags.Format<"uuid">;

  /**
   * Reference to the associated order (CartOrder.order.id).
   *
   * Links evidence to the root business transaction.
   */
  order_id: string & tags.Format<"uuid">;

  /**
   * Type/category of evidence (e.g., 'invoice', 'signature', 'photo',
   * 'receipt').
   *
   * Fulfills business and legal requirements for evidence.
   */
  evidence_type: string;

  /**
   * URI to external evidence file or record (e.g., S3, IPFS, CDN, file
   * server).
   *
   * Ensures audit trail preserves vital artifacts; actual files not stored in
   * DB.
   */
  evidence_uri: string & tags.MaxLength<80000>;

  /**
   * UTC timestamp of when evidence was provided/archived. Core for evidence
   * chain of custody tracking.
   */
  provided_at: string & tags.Format<"date-time">;

  /**
   * User or system actor who provided the evidence (users.id); null for
   * system-automated entries.
   */
  provided_by?: (string & tags.Format<"uuid">) | null;
};
export namespace IOrderEvidence {
  /**
   * Payload for creating a new evidence record for an order
   * (CartOrder.order_evidence).
   *
   * Covers regulatory evidence requirements, attaches via external uri, and
   * captures full compliance trace fields.
   */
  export type ICreate = {
    /** Order for which evidence is recorded (CartOrder.order.id). */
    order_id: string & tags.Format<"uuid">;

    /** Type/category of evidence record (business/use case driven). */
    evidence_type: string;

    /**
     * Reference URI for external evidence artifact (required for traceable
     * legal evidence, never stored in DB).
     */
    evidence_uri: string & tags.MaxLength<80000>;

    /**
     * UTC timestamp for when evidence was attached; used for
     * legal/non-repudiation purposes.
     */
    provided_at: string & tags.Format<"date-time">;

    /**
     * User/system actor providing evidence (users.id). Null for
     * system-automatic entries.
     */
    provided_by?: (string & tags.Format<"uuid">) | null;
  };
}

