import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ICartOrderOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/ICartOrderOrder";
import type { IOrderEvidence } from "@ORGANIZATION/PROJECT-api/lib/structures/IOrderEvidence";

/**
 * Validate creation of order evidence for an order, ensuring correct behavior for both valid and invalid scenarios.
 *
 * This test covers:
 *  1. Creating an order to establish a valid order_id
 *  2. Creating an order_evidence with this valid order_id and required metadata
 *  3. Asserting the order_evidence is created correctly and all fields are accurate
 *  4. Attempting to create an order_evidence with a non-existing order_id (should yield error)
 *  5. Attempting to create order_evidence with missing/incomplete data (should yield validation error)
 *
 * Test steps:
 *   1. Create CartOrder order (dependency)
 *   2. Create order evidence for the order
 *   3. Assert fields: id, order_id, evidence_type, evidence_uri, provided_at, provided_by (if supplied)
 *   4. Try to create evidence with random (non-existing) order_id (expect rejection)
 *   5. Try to create evidence omitting required field (e.g., evidence_uri or evidence_type); validate error
 */
export async function test_api_cartOrder_test_create_order_evidence_valid_and_invalid_scenarios(
  connection: api.IConnection,
) {
  // 1. Create dependency order
  const userId = typia.random<string & tags.Format<"uuid">>();
  const cartId = typia.random<string & tags.Format<"uuid">>();
  const order = await api.functional.cartOrder.order.post(connection, {
    body: {
      user_id: userId,
      cart_id: cartId,
    } satisfies ICartOrderOrder.ICreate,
  });
  typia.assert(order);

  // 2. Create valid order evidence
  const evidenceInput: IOrderEvidence.ICreate = {
    order_id: order.id,
    evidence_type: "invoice",
    evidence_uri: `https://fileserver.com/evidence/${typia.random<string & tags.Format<"uuid">>()}.pdf`,
    provided_at: new Date().toISOString(),
    provided_by: order.user_id,
  };
  const evidence = await api.functional.cartOrder.orderEvidence.post(connection, {
    body: evidenceInput,
  });
  typia.assert(evidence);
  TestValidator.equals("order_id")(order.id)(evidence.order_id);
  TestValidator.equals("evidence_type")("invoice")(evidence.evidence_type);
  TestValidator.equals("evidence_uri")(evidenceInput.evidence_uri)(evidence.evidence_uri);
  TestValidator.equals("provided_by")(order.user_id)(evidence.provided_by);

  // 3. Negative test: non-existing order_id
  await TestValidator.error("non-existing order_id should fail")(() =>
    api.functional.cartOrder.orderEvidence.post(connection, {
      body: {
        ...evidenceInput,
        order_id: typia.random<string & tags.Format<"uuid">>() // random uuid not matching any order
      },
    }),
  );

  // 4. Negative test: missing evidence_type
  await TestValidator.error("missing evidence_type validation")(() =>
    api.functional.cartOrder.orderEvidence.post(connection, {
      body: {
        order_id: order.id,
        // missing evidence_type
        evidence_uri: evidenceInput.evidence_uri,
        provided_at: evidenceInput.provided_at,
        provided_by: order.user_id,
      } as any,
    }),
  );

  // 5. Negative test: missing evidence_uri
  await TestValidator.error("missing evidence_uri validation")(() =>
    api.functional.cartOrder.orderEvidence.post(connection, {
      body: {
        order_id: order.id,
        evidence_type: "photo",
        // missing evidence_uri
        provided_at: evidenceInput.provided_at,
        provided_by: order.user_id,
      } as any,
    }),
  );
}

