import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IOrderEvidence } from "@ORGANIZATION/PROJECT-api/lib/structures/IOrderEvidence";

/**
 * Test update and error-handling for CartOrder.order_evidence metadata.
 *
 * Validates admin-style correction of evidence metadata on immutable audit records. Covers successful update, not found, and validation error flows.
 *
 * 1. Create an order_evidence record (dependency).
 * 2. Update metadata fields (type, uri, provided_by) on the created evidence and verify changes.
 * 3. Attempt update with non-existing evidence id, expect not found error (404).
 * 4. Attempt update with invalid evidence_uri (empty string or too long), expect validation error.
 * 5. (Optional) Attempt update with forbidden values for evidence_type, expect error if business rules restrict to fixed set.
 */
export async function test_api_cartOrder_test_update_order_evidence_metadata_and_error_handling(
  connection: api.IConnection,
) {
  // 1. Create an order_evidence record to update
  const original: IOrderEvidence = await api.functional.cartOrder.orderEvidence.post(connection, {
    body: {
      order_id: typia.random<string & tags.Format<"uuid">>(),
      evidence_type: "invoice",
      evidence_uri: "https://evidence.example.com/artifact123.pdf",
      provided_at: new Date().toISOString(),
      provided_by: typia.random<string & tags.Format<"uuid">>(),
    } satisfies IOrderEvidence.ICreate
  });
  typia.assert(original);

  // 2. Successful update of metadata
  const updateBody: IOrderEvidence.IUpdate = {
    evidence_type: "receipt",
    evidence_uri: "https://evidence.example.com/updated_artifact456.pdf",
    provided_by: typia.random<string & tags.Format<"uuid">>(),
  };
  const updated = await api.functional.cartOrder.orderEvidence.putById(connection, {
    id: original.id,
    body: updateBody
  });
  typia.assert(updated);
  TestValidator.equals("updated id")(original.id)(updated.id);
  TestValidator.equals("updated evidence_type")("receipt")(updated.evidence_type);
  TestValidator.equals("updated evidence_uri")(updateBody.evidence_uri)(updated.evidence_uri);
  TestValidator.equals("updated provided_by")(updateBody.provided_by)(updated.provided_by);

  // 3. Not found error on non-existing id
  await TestValidator.error("update non-existing order evidence should fail")(() =>
    api.functional.cartOrder.orderEvidence.putById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
      body: updateBody
    })
  );

  // 4a. Validation error (empty uri)
  await TestValidator.error("empty evidence_uri should fail validation")(() =>
    api.functional.cartOrder.orderEvidence.putById(connection, {
      id: original.id,
      body: {
        ...updateBody,
        evidence_uri: ""
      }
    })
  );

  // 4b. Validation error (overly long uri)
  await TestValidator.error("overly long evidence_uri should fail validation")(() =>
    api.functional.cartOrder.orderEvidence.putById(connection, {
      id: original.id,
      body: {
        ...updateBody,
        evidence_uri: "https://x" + "x".repeat(80001)
      }
    })
  );
}

