import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IOrderEvidence } from "@ORGANIZATION/PROJECT-api/lib/structures/IOrderEvidence";

/**
 * E2E test for soft-deleting an order_evidence record, verifying compliance archival rather than physical deletion,
 * and checking error handling for non-existent record.
 *
 * Business requirements:
 * - Evidence records are never fully deleted (for audit/compliance/legal needs)
 * - Deletion marks the evidence as archived, but data remains physically available for future audit
 * - API should return the archived record (not void or null)
 * - Attempts to delete a non-existent record should result in an error (HTTP 404 or equivalent)
 *
 * Steps:
 * 1. Create a new order_evidence record using the POST endpoint
 * 2. Soft-delete the evidence record using the DELETE endpoint
 * 3. Validate the response is the same record, and validate presence of compliance-sensitive fields
 * 4. Attempt to delete a non-existent evidence id (random UUID) and assert error is thrown
 */
export async function test_api_cartOrder_test_delete_order_evidence_soft_and_non_existing(
  connection: api.IConnection,
) {
  // 1. Create a new order_evidence record
  const evidenceInput: IOrderEvidence.ICreate = {
    order_id: typia.random<string & tags.Format<"uuid">>(),
    evidence_type: "invoice",
    evidence_uri: "https://compliance.host/documents/proof.pdf",
    provided_at: new Date().toISOString(),
    provided_by: typia.random<string & tags.Format<"uuid">>(),
  };
  const created = await api.functional.cartOrder.orderEvidence.post(connection, {
    body: evidenceInput,
  });
  typia.assert(created);

  // 2. Soft-delete the order_evidence record (archived, not fully deleted)
  const archived = await api.functional.cartOrder.orderEvidence.eraseById(connection, {
