  TestValidator.equals("archived order id matches original")(created.order_id)(archived.order_id);
  TestValidator.equals("archived evidence_uri matches")(created.evidence_uri)(archived.evidence_uri);

  // 3. Attempt to soft-delete an order_evidence record that does not exist
  await TestValidator.error("deleting non-existent order_evidence must throw error")(async () => {
    await api.functional.cartOrder.orderEvidence.eraseById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(), // random UUID never used before
    });
  });
}

