import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPayment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPayment";
import type { IPageIPayment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPayment";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Tests listing and searching of payment records with various filters and pagination.
 *
 * This validates that payment record querying works correctly even with large datasets, filters, and edge cases.
 * The test covers filtering by:
 *   - user (via user_id)
 *   - transaction (transaction_id)
 *   - payment method (payment_method_id)
 *   - status (pending, completed, failed, etc.)
 *   - currency type
 *   - initiation and completion date range
 *   - pagination (page/limit) and sorting
 * In addition, it ensures that invalid search parameters (bad UUIDs, impossible dates, unknown fields, negative page/limit) elicit proper error handling responses.
 *
 * Test Steps:
 * 1. Seed multiple payment records, with varying users, methods, statuses, amounts, and dates.
 * 2. Query the full list (default: no filter) and assert total count matches seeds.
 * 3. Filter by specific user and validate only payments of that user appear.
 * 4. Filter by payment method, status, currency, or transaction_id and confirm only matching records are returned.
 * 5. Filter by date ranges (initiation, completion) and verify correct window.
 * 6. Use limit and page parameters, confirm pagination metadata and correct slicing.
 * 7. Combine filters (e.g., user_id + currency + time window), confirm result set is intersection.
 * 8. Use sorting (amount, initiated_at, etc), confirm order in result.
 * 9. Attempt with negative/invalid page/limit and expect error or strict validation.
 * 10. Attempt filters with impossible or unknown field values, expect 0 results or error.
 */
export async function test_api_paymentsDiscounts_test_list_payments_filter_and_pagination(
  connection: api.IConnection,
) {
  // 1. Seed several payment records of different users, methods, currencies, and dates
  const NUM_USERS = 2;
  const NUM_RECORDS = 8;
  const users = ArrayUtil.repeat(NUM_USERS)(() => typia.random<string & tags.Format<"uuid">>());
  const methods = ArrayUtil.repeat(2)(() => typia.random<string & tags.Format<"uuid">>());
  const transactions = ArrayUtil.repeat(NUM_RECORDS)(() => typia.random<string & tags.Format<"uuid">>());
  const currencies = ["USD", "KRW"];
  const statuses = ["pending", "completed", "failed"];
  const now = new Date();

  const seeds = await ArrayUtil.asyncRepeat(NUM_RECORDS)(async (idx) => {
    return api.functional.paymentsDiscounts.payments.post(connection, {
      body: {
        transaction_id: transactions[idx],
        payment_method_id: RandomGenerator.pick(methods),
        amount: 35.5 + 10 * idx,
        currency: RandomGenerator.pick(currencies),
        description: `Test seed ${idx}`,
      },
    });
  });
  seeds.forEach((p) => typia.assert(p));

  // 2. Query all payments
  let page = await api.functional.paymentsDiscounts.payments.patch(connection, {
    body: {},
  });
  typia.assert(page);
  TestValidator.equals("all count")(seeds.length)(page.pagination.records);

  // 3. Filter by user (by seeding user_id manually in extra pass if needed)
  // Not possible in core API unless post allows user_id setting, so test is skipped/marked.

  // 4. Filter by payment_method_id
  {
    const filterId = methods[0];
    const page2 = await api.functional.paymentsDiscounts.payments.patch(connection, {
      body: { payment_method_id: filterId },
    });
    typia.assert(page2);
    TestValidator.predicate("filtered by method only correct records")(
      page2.data.every((p) => p.payment_method_id === filterId),
    );
  }

  // 5. Filter by currency
  {
    const filterCurrency = RandomGenerator.pick(currencies);
    const filtered = await api.functional.paymentsDiscounts.payments.patch(connection, {
      body: { currency: filterCurrency },
    });
    typia.assert(filtered);
    TestValidator.predicate("filtered by currency matches")(
      filtered.data.every((p) => p.currency === filterCurrency),
    );
  }

  // 6. Date range filtering (initiation, completion window)
  {
    const fromDate = new Date(now.getTime() - 24 * 60 * 60 * 1000).toISOString();
    const toDate = new Date(now.getTime() + 24 * 60 * 60 * 1000).toISOString();
    const byDate = await api.functional.paymentsDiscounts.payments.patch(connection, {
      body: { initiated_from: fromDate, initiated_to: toDate },
    });
    typia.assert(byDate);
    TestValidator.predicate("initiated in window")(
      byDate.data.every((p) =>
        new Date(p.initiated_at) >= new Date(fromDate) && new Date(p.initiated_at) < new Date(toDate),
      ),
    );
  }

  // 7. Pagination
  {
    const limited = await api.functional.paymentsDiscounts.payments.patch(connection, {
      body: { limit: 2, page: 1 },
    });
    typia.assert(limited);
    TestValidator.equals("pagination limit")(2)(limited.data.length);
    TestValidator.equals("pagination metadata")(2)(limited.pagination.limit);
  }

  // 8. Sorting
  {
    const sorted = await api.functional.paymentsDiscounts.payments.patch(connection, {
      body: { sort: "amount:desc" },
    });
    typia.assert(sorted);
    const amounts = sorted.data.map((p) => p.amount);
    const sortedAmounts = [...amounts].sort((a, b) => b - a);
    TestValidator.equals("sorted desc")(sortedAmounts)(amounts);
  }

  // 9. Combine filters (method + currency + window)
  {
    const filterMethod = methods[1];
    const filterCurrency = currencies[1];
    const fromDate = new Date(now.getTime() - 24 * 60 * 60 * 1000).toISOString();
    const toDate = new Date(now.getTime() + 24 * 60 * 60 * 1000).toISOString();
    const combined = await api.functional.paymentsDiscounts.payments.patch(connection, {
      body: { payment_method_id: filterMethod, currency: filterCurrency, initiated_from: fromDate, initiated_to: toDate },
    });
    typia.assert(combined);
    TestValidator.predicate("filter intersection matches")(
      combined.data.every((p) =>
        p.payment_method_id === filterMethod &&
        p.currency === filterCurrency &&
        new Date(p.initiated_at) >= new Date(fromDate) &&
        new Date(p.initiated_at) < new Date(toDate),
      ),
    );
  }

  // 10. Invalid/edge parameter: negative page/limit
  for (const bad of [
    { limit: -1 },
    { page: -2 },
    { limit: 0 },
    { page: 0 },
  ]) {
    await TestValidator.error("invalid paging should error")(() =>
      api.functional.paymentsDiscounts.payments.patch(connection, {
        body: bad,
      }),
    );
  }

  // 11. Impossible/unknown value
  {
    const res = await api.functional.paymentsDiscounts.payments.patch(connection, {
      body: { payment_method_id: "11111111-1111-1111-1111-111111111111" },
    });
    typia.assert(res);
    TestValidator.equals("no records for unknown method")(0)(res.data.length);
  }

  // 12. Invalid UUID format
  await TestValidator.error("invalid uuid error")(() =>
    api.functional.paymentsDiscounts.payments.patch(connection, {
      body: { payment_method_id: "not-a-uuid" },
    }),
  );
