import { tags } from "typia";

/**
 * Payment record object.
 *
 * Represents one atomic payment transaction in the shopping mall system,
 * referencing PaymentsDiscounts.payments. Used for audit, financial
 * reconciliation, user dashboards, and compliance evidence.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IPayment = {
  /**
   * Unique identifier for payment record.
   *
   * See PaymentsDiscounts.payments.id. Serves as immutable record for audit,
   * trace, and legal evidence.
   */
  id: string & tags.Format<"uuid">;

  /**
   * Linked transaction's ID. References
   * PaymentsDiscounts.payments.transaction_id. Ties payment to its parent
   * business event (e.g., order checkout, wallet top-up) for reconciliation
   * and evidence reporting.
   */
  transaction_id: string & tags.Format<"uuid">;

  /**
   * Associated payment method's ID. See
   * PaymentsDiscounts.payments.payment_method_id. Points to the underlying
   * instrument (card, wallet, crypto, etc) used for payment, supporting
   * reconciliation, fraud analysis, and user dashboards.
   */
  payment_method_id: string & tags.Format<"uuid">;

  /**
   * Monetary amount of the payment (positive).
   *
   * References PaymentsDiscounts.payments.amount. Always positive. E.g.,
   * 99.99, 1234.5, etc.
   */
  amount: number &
    tags.JsonSchemaPlugin<{
      format: "double";
    }>;

  /** 3-letter ISO currency code. */
  currency: string;

  /**
   * Status of the payment (pending, completed, failed, refunded, held, etc).
   *
   * Column: PaymentsDiscounts.payments.status for integrity and audit
   * tracking.
   */
  status: string;

  /**
   * Timestamp when payment was initiated.
   *
   * See PaymentsDiscounts.payments.initiated_at. Used for evidence
   * preservation and value-chain analysis.
   */
  initiated_at: string & tags.Format<"date-time">;

  /**
   * Completion time for payment if/when succeeded. Column:
   * PaymentsDiscounts.payments.completed_at.
   */
  completed_at?: (string & tags.Format<"date-time">) | null;

  /**
   * Business note or memo associated with payment, supporting audit and
   * dispute resolution evidence.
   *
   * References PaymentsDiscounts.payments.description. Not required, often
   * used to annotate context.
   */
  description?: string | null;
};
export namespace IPayment {
  /**
   * Payload for creating a new payment record.
   *
   * Maps directly to PaymentsDiscounts.payments table (see Prisma schema),
   * with business-required and evidence-compliant attributes.
   */
  export type ICreate = {
    /**
     * Linked transaction's ID for this payment (required).
     *
     * Must refer to an existing transactions.id.
     *
     * Completes integrity for all monetary activity.
     */
    transaction_id: string & tags.Format<"uuid">;

    /**
     * User's payment method ID (required).
     *
     * References payment_methods.id. Sets source for the monetary
     * operation. Must exist and belong to user (or system for automation).
     */
    payment_method_id: string & tags.Format<"uuid">;

    /**
     * Payment amount (positive, float). Required.
     *
     * Column: PaymentsDiscounts.payments.amount. Must match or not exceed
     * business logic requirements (e.g., order total).
     *
     * Subject to further validation in payment logic.
     */
    amount: number &
      tags.JsonSchemaPlugin<{
        format: "double";
      }>;

    /**
     * ISO-4217 3-letter currency code (required).
     *
     * E.g., 'USD', 'KRW', 'EUR'.
     */
    currency: string;

    /**
     * Optional memo/note for this payment for operator context, audit,
     * analytics, or evidence ('order 1234 - first payment', 'manual
     * refund', etc).
     */
    description?: string | null;
  };
}

