import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPayment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPayment";

/**
 * Validate retrieving a payment record by ID and not-found error handling.
 *
 * This test verifies correct retrieval of an existing payment by its ID and appropriate handling when requesting a non-existent payment. This is crucial for audit, user dashboards, and error management in financial systems, ensuring compliance and transparency.
 *
 * Workflow:
 * 1. Create a valid payment record as prerequisite
 * 2. Retrieve the payment record by its ID and verify all fields and values match
 * 3. Attempt to retrieve a payment with a random (unused) UUID and verify that a not found error (e.g., 404) is thrown
 */
export async function test_api_paymentsDiscounts_test_get_payment_by_id_various_cases(
  connection: api.IConnection,
) {
  // 1. Create a valid payment record as a prerequisite
  const paymentCreate: IPayment.ICreate = {
    transaction_id: typia.random<string & tags.Format<"uuid">>(),
    payment_method_id: typia.random<string & tags.Format<"uuid">>(),
    amount: typia.random<number & tags.JsonSchemaPlugin<{ format: "double" }>>(),
    currency: "KRW",
    description: "Automated E2E test payment"
  };
  const created: IPayment = await api.functional.paymentsDiscounts.payments.post(connection, {
    body: paymentCreate,
  });
  typia.assert(created);

  // 2. Retrieve the payment record by its ID
  const fetched: IPayment = await api.functional.paymentsDiscounts.payments.getById(connection, {
    id: created.id,
  });
  typia.assert(fetched);
  TestValidator.equals("payment.id")(created.id)(fetched.id);
  TestValidator.equals("payment.transaction_id")(created.transaction_id)(fetched.transaction_id);
  TestValidator.equals("payment.amount")(created.amount)(fetched.amount);
  TestValidator.equals("payment.currency")(created.currency)(fetched.currency);
  TestValidator.equals("payment.payment_method_id")(created.payment_method_id)(fetched.payment_method_id);
  TestValidator.equals("payment.status")(typeof fetched.status === "string")(true); // should be a string
  TestValidator.predicate("payment.initiated_at is date-time formatted")(
    typeof fetched.initiated_at === "string" && fetched.initiated_at.includes("T") && fetched.initiated_at.includes(":")
  );

  // 3. Attempt to view a payment by a non-existent ID and verify error is thrown
  await TestValidator.error("payment not found throws error")(() =>
    api.functional.paymentsDiscounts.payments.getById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
    })
  );
}

