import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ICartOrderOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/ICartOrderOrder";
import type { IPayment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPayment";
import type { IPaymentMethod } from "@ORGANIZATION/PROJECT-api/lib/structures/IPaymentMethod";

/**
 * Comprehensive E2E test for payment creation covering validation, errors, and duplicate handling.
 *
 * 1. Create a valid order for a (random) user and cart
 * 2. Register a valid payment method for that user
 * 3. Create a payment event referencing the valid order and method; verify all returned fields, linkage, and correctness of values.
 * 4. Negative case: Attempt payment with invalid/unknown transaction_id, unknown method, and invalid amounts (e.g., negative, zero).
 * 5. Test for duplicate payment creation (same transaction_id) to verify idempotency or error.
 */
export async function test_api_paymentsDiscounts_test_create_payment_valid_invalid_duplicate_cases(connection: api.IConnection) {
  // ---------- Step 1: Create and persist a valid order ----------
  const user_id = typia.random<string & tags.Format<"uuid">>();
  const cart_id = typia.random<string & tags.Format<"uuid">>();
  const order = await api.functional.cartOrder.order.post(connection, {
    body: {
      user_id,
      cart_id
    } satisfies ICartOrderOrder.ICreate
  });
  typia.assert(order);

  // ---------- Step 2: Create payment method for same user ----------
  const paymentMethod = await api.functional.paymentsDiscounts.paymentMethods.post(connection, {
    body: {
      user_id,
      type: "VISA",
      masked_detail: "**** **** **** 1234",
      provider: "Stripe",
      active: true,
    } satisfies IPaymentMethod.ICreate
  });
  typia.assert(paymentMethod);

  // ---------- Step 3: Valid payment creation ----------
  const paymentAmount = 1000.00;
  const paymentCurrency = "USD";
  const payment = await api.functional.paymentsDiscounts.payments.post(connection, {
    body: {
      transaction_id: order.id,
      payment_method_id: paymentMethod.id,
      amount: paymentAmount,
      currency: paymentCurrency,
      description: "Test payment"
    } satisfies IPayment.ICreate
  });
  typia.assert(payment);
  TestValidator.equals("amount")(payment.amount)(paymentAmount);
  TestValidator.equals("currency")(payment.currency)(paymentCurrency);
  TestValidator.equals("transaction linkage")(payment.transaction_id)(order.id);
  TestValidator.equals("method linkage")(payment.payment_method_id)(paymentMethod.id);
  TestValidator.equals("description")(payment.description)("Test payment");

  // ---------- Step 4: Invalid/missing/inconsistent fields ----------
  // a. Unknown transaction_id
  await TestValidator.error("invalid transaction_id should fail")(async () => {
    await api.functional.paymentsDiscounts.payments.post(connection, {
      body: {
        transaction_id: typia.random<string & tags.Format<"uuid">>(),
        payment_method_id: paymentMethod.id,
        amount: 100.0,
        currency: paymentCurrency
      } satisfies IPayment.ICreate
    });
  });
  // b. Unknown payment_method_id
  await TestValidator.error("invalid payment_method_id should fail")(async () => {
    await api.functional.paymentsDiscounts.payments.post(connection, {
      body: {
        transaction_id: order.id,
        payment_method_id: typia.random<string & tags.Format<"uuid">>(),
        amount: 100.0,
        currency: paymentCurrency
      } satisfies IPayment.ICreate
    });
  });
  // c. Negative amount
  await TestValidator.error("negative amount should fail")(async () => {
    await api.functional.paymentsDiscounts.payments.post(connection, {
      body: {
        transaction_id: order.id,
        payment_method_id: paymentMethod.id,
        amount: -50,
        currency: paymentCurrency
      } satisfies IPayment.ICreate
    });
  });
  // d. Zero amount
  await TestValidator.error("zero amount should fail")(async () => {
    await api.functional.paymentsDiscounts.payments.post(connection, {
      body: {
        transaction_id: order.id,
        payment_method_id: paymentMethod.id,
        amount: 0,
        currency: paymentCurrency
      } satisfies IPayment.ICreate
    });
  });
  // e. Missing required fields (should be skipped - causes TypeScript error, not runtime)

  // ---------- Step 5: Duplicate payment for same transaction_id ----------
  await TestValidator.error("duplicate payment creation should fail")(async () => {
    await api.functional.paymentsDiscounts.payments.post(connection, {
      body: {
        transaction_id: order.id,
        payment_method_id: paymentMethod.id,
        amount: paymentAmount,
        currency: paymentCurrency,
        description: "Second try"
      } satisfies IPayment.ICreate
    });
  });
}

