 * 2. Register a valid payment method for that user
 * 3. Create a payment for that order and method, verifying all fields
 * 4. Attempt payment with invalid transaction_id (should fail)
 * 5. Attempt payment with invalid payment_method_id (should fail)
 * 6. Attempt payment with negative or zero amount (should fail)
 * 7. Attempt to create a duplicate payment event for the same transaction_id (should fail or be idempotent)
 */
export async function test_api_paymentsDiscounts_test_create_payment_valid_invalid_duplicate_cases(
  connection: api.IConnection,
) {
