  const user_id = typia.random<string & tags.Format<"uuid">>();
  const cart_id = typia.random<string & tags.Format<"uuid">>();
  const order = await api.functional.cartOrder.order.post(connection, {
    body: {
      user_id,
      cart_id,
    } satisfies ICartOrderOrder.ICreate,
  });
  typia.assert(order);

  // 2. Register a valid payment method for the same user ----------
  const paymentMethod = await api.functional.paymentsDiscounts.paymentMethods.post(
    connection,
    {
      body: {
        user_id,
        type: "VISA",
        masked_detail: "**** **** **** 1234",
        provider: "Stripe",
        active: true,
      } satisfies IPaymentMethod.ICreate,
    },
  );
  typia.assert(paymentMethod);

  // 3. Create a payment for that order/method; verify all fields ----------
  const paymentAmount = 1000.0;
  const paymentCurrency = "USD";
  const payment = await api.functional.paymentsDiscounts.payments.post(
    connection,
    {
      body: {
        transaction_id: order.id,
        payment_method_id: paymentMethod.id,
        amount: paymentAmount,
        currency: paymentCurrency,
        description: "Test payment",
      } satisfies IPayment.ICreate,
    },
  );
  typia.assert(payment);
  TestValidator.equals("amount")(payment.amount)(paymentAmount);
  TestValidator.equals("currency")(payment.currency)(paymentCurrency);
  TestValidator.equals("transaction linkage")(payment.transaction_id)(order.id);
  TestValidator.equals("method linkage")(payment.payment_method_id)(paymentMethod.id);
  TestValidator.equals("description")(payment.description)("Test payment");

  // 4a. Attempt payment with invalid transaction_id ----------
  await TestValidator.error("invalid transaction_id should fail")(async () => {
    await api.functional.paymentsDiscounts.payments.post(connection, {
      body: {
        transaction_id: typia.random<string & tags.Format<"uuid">>(),
        payment_method_id: paymentMethod.id,
        amount: 100.0,
        currency: paymentCurrency,
      } satisfies IPayment.ICreate,
    });
  });
  // 4b. Attempt payment with invalid payment_method_id ----------
  await TestValidator.error("invalid payment_method_id should fail")(async () => {
    await api.functional.paymentsDiscounts.payments.post(connection, {
      body: {
        transaction_id: order.id,
        payment_method_id: typia.random<string & tags.Format<"uuid">>(),
        amount: 100.0,
        currency: paymentCurrency,
      } satisfies IPayment.ICreate,
    });
  });
  // 4c. Attempt payment with negative amount ----------
  await TestValidator.error("negative amount should fail")(async () => {
    await api.functional.paymentsDiscounts.payments.post(connection, {
      body: {
        transaction_id: order.id,
        payment_method_id: paymentMethod.id,
        amount: -50,
        currency: paymentCurrency,
      } satisfies IPayment.ICreate,
    });
  });
  // 4d. Attempt payment with zero amount ----------
  await TestValidator.error("zero amount should fail")(async () => {
    await api.functional.paymentsDiscounts.payments.post(connection, {
      body: {
        transaction_id: order.id,
        payment_method_id: paymentMethod.id,
        amount: 0,
        currency: paymentCurrency,
      } satisfies IPayment.ICreate,
    });
  });

  // 7. Attempt to create a duplicate payment for the same transaction_id ----------
  await TestValidator.error("duplicate payment creation should fail")(async () => {
    await api.functional.paymentsDiscounts.payments.post(connection, {
      body: {
        transaction_id: order.id,
        payment_method_id: paymentMethod.id,
        amount: paymentAmount,
        currency: paymentCurrency,
        description: "Second try",
      } satisfies IPayment.ICreate,
    });
  });
}

