import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPayment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPayment";

/**
 * Validate updating permitted fields of a payment record and proper error handling on forbidden/invalid updates.
 *
 * This test covers multiple business and error scenarios:
 * 1. Create a baseline payment record for update testing
 * 2. Update allowed metadata fields (payment_method_id, completed_at, description) and confirm the updates are applied and only the permitted fields can be changed
 * 3. Attempt update for a non-existent payment ID and confirm a 'Not Found' error is returned
 * 4. Attempt update with invalid data (e.g., bad date format, invalid payment_method_id format) and confirm validation errors are returned
 * 5. Attempt to update immutable fields (such as amount, transaction_id, status) and confirm such properties are ignored or cause error if not supported by the schema
 */
export async function test_api_paymentsDiscounts_test_update_payment_metadata_and_error_cases(
  connection: api.IConnection,
) {
  // 1. Create a baseline payment record to update
  const baselinePaymentCreate: IPayment.ICreate = {
    transaction_id: typia.random<string & tags.Format<"uuid">>(),
    payment_method_id: typia.random<string & tags.Format<"uuid">>(),
    amount: 125000.99,
    currency: "USD",
    description: "Initial payment for order #1001"
  };
  const payment = await api.functional.paymentsDiscounts.payments.post(connection, { body: baselinePaymentCreate });
  typia.assert(payment);

  // 2. Update allowed metadata fields and confirm response
  const newMethodId = typia.random<string & tags.Format<"uuid">>();
  const newDescription = "Corrected: Updated payment method and memo";
  const newCompletedAt = new Date().toISOString();
  const updatePayload: IPayment.IUpdate = {
    payment_method_id: newMethodId,
    description: newDescription,
    completed_at: newCompletedAt,
  };
  const updatedPayment = await api.functional.paymentsDiscounts.payments.putById(connection, { id: payment.id, body: updatePayload });
  typia.assert(updatedPayment);
  TestValidator.equals("payment_method_id updated")(newMethodId)(updatedPayment.payment_method_id);
  TestValidator.equals("description updated")(newDescription)(updatedPayment.description);
  TestValidator.equals("completed_at updated")(newCompletedAt)(updatedPayment.completed_at);

  // 3. Attempt update for a non-existent payment ID (should return 404)
  await TestValidator.error("update with non-existent ID should fail")(() =>
    api.functional.paymentsDiscounts.payments.putById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
      body: updatePayload,
    })
  );

  // 4. Attempt update with invalid data (bad payment_method_id and completed_at formats)
  await TestValidator.error("update with invalid payment_method_id format should fail")(() =>
    api.functional.paymentsDiscounts.payments.putById(connection, {
      id: payment.id,
      body: {
        payment_method_id: "bad-format-123",
        description: newDescription,
        completed_at: newCompletedAt,
      },
    })
  );
  await TestValidator.error("update with invalid completed_at format should fail")(() =>
    api.functional.paymentsDiscounts.payments.putById(connection, {
      id: payment.id,
      body: {
        payment_method_id: newMethodId,
        description: newDescription,
        completed_at: "2025-13-32T99:99:99Z", // Clearly invalid date
      },
    })
  );

  // 5. Attempt to update immutable fields (should be ignored by schema and not applied)
  // (By schema, additional fields are not allowed, but test for non-effect by adding extra props
  // Only fields in IPayment.IUpdate are applied; extra are ignored or error)
  const extraFields: any = {
    payment_method_id: newMethodId,
    amount: 7777, // illegal field
    transaction_id: typia.random<string & tags.Format<"uuid">>(), // illegal field
    status: "hacked", // illegal field
  };
  await TestValidator.error("update with forbidden fields must fail or be ignored")(() =>
    api.functional.paymentsDiscounts.payments.putById(connection, {
      id: payment.id,
      body: extraFields,
    })
  );
}

