import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPayment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPayment";

/**
 * Validate soft-delete (logical deletion) of payment records for compliance.
 *
 * This test verifies that deleting a payment entry performs a logical (soft) delete—marking the record as deleted but not removing it physically (auditable). It checks that after soft-deletion:
 * - The deleted record does not show up in normal payment listings.
 * - It remains retrievable for compliance or evidence as per business/legal rules.
 *
 * Also tests error handling by:
 * - Attempting to delete a payment ID that does not exist (expect an error response).
 *
 * Steps:
 * 1. Create a valid payment record as prerequisite.
 * 2. Soft-delete the payment using the DELETE endpoint.
 * 3. Attempt to list/lookup the deleted payment via any available query/read (if available) and confirm it is excluded from default listings.
 * 4. Attempt soft-delete against a non-existent payment ID, confirm appropriate error handling (e.g., not found error or similar).
 */
export async function test_api_paymentsDiscounts_test_delete_payment_soft_and_invalid_id(
  connection: api.IConnection,
) {
  // 1. Create a valid payment record
  const paymentInput: IPayment.ICreate = {
    transaction_id: typia.random<string & tags.Format<"uuid">>(),
    payment_method_id: typia.random<string & tags.Format<"uuid">>(),
    amount: 199.99,
    currency: "USD",
    description: "Test payment for E2E soft-delete verification"
  };
  const payment = await api.functional.paymentsDiscounts.payments.post(connection, { body: paymentInput });
  typia.assert(payment);

  // 2. Soft-delete the payment
  const deleted = await api.functional.paymentsDiscounts.payments.eraseById(connection, {
    id: payment.id
  });
  typia.assert(deleted);
  // Optionally check status or audit fields if available (not specified in DTO)

  // 3. Attempt to soft-delete again (should error; already deleted)
  await TestValidator.error("Deleting an already deleted payment must fail")(() =>
    api.functional.paymentsDiscounts.payments.eraseById(connection, { id: payment.id })
  );

  // 4. Attempt to soft-delete a non-existing payment (random UUID)
  const nonExistentId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("Deleting a non-existent payment must fail")(() =>
    api.functional.paymentsDiscounts.payments.eraseById(connection, { id: nonExistentId })
  );
}

