import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPaymentMethod } from "@ORGANIZATION/PROJECT-api/lib/structures/IPaymentMethod";
import type { IPageIPaymentMethod } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPaymentMethod";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * 테스트: 결제수단 목록 페이징, 필터, 유효 범위 테스트 및 오류 처리 확인
 *
 * 결제수단 리스트 API의 페이징 및 다양한 필터(유저, 타입, 활성화 상태, 프로바이더, 생성일자 범위 등) 기능을 검증합니다. 
 * 사전조건으로 여러 사용자의 다양한 결제수단을 생성한 다음 다음을 확인합니다.
 *
 * 1. 페이지네이션 정상 동작 및 pagination 필드 검증
 * 2. 타입(카드/지갑 등), 프로바이더, 활성화여부, 생성일(범위) 필터로 개별/조합 검색 결과 정확성 확인
 * 3. 존재하지 않는 값/잘못된 조합의 필터로 검색 시 빈 결과 도출/오류 응답 확인
 * 4. Limit/page 옵션 조합 등 페이징 엣지케이스(마지막 페이지, limit=1, limit>전체 등)
 * 5. 불필요한/허용되지 않은 필드 전달 시 적절한 에러 반환(비즈니스 오류 및 json schema 오류 구분)
 */
export async function test_api_paymentsDiscounts_test_list_payment_methods_filter_and_pagination(
  connection: api.IConnection,
) {
  // 1. 테스트용 유저 ID 및 결제수단 (타입/프로바이더/활성화) 다양한 조합으로 6개 이상 생성
  const userId1 = typia.random<string & tags.Format<'uuid'>>();
  const userId2 = typia.random<string & tags.Format<'uuid'>>();

  const now = new Date();
  const methodVariants = [
    { user_id: userId1, type: 'VISA', masked_detail: '**** 1234', provider: 'Stripe', active: true },
    { user_id: userId1, type: 'PayPal', masked_detail: 'user@paypal.com', provider: 'PayPal', active: true },
    { user_id: userId1, type: 'Wallet', masked_detail: 'wallet-01', provider: 'Toss', active: false },
    { user_id: userId2, type: 'VISA', masked_detail: '**** 5678', provider: 'Stripe', active: false },
    { user_id: userId2, type: 'Crypto', masked_detail: 'btc-xxx', provider: 'Binance', active: true },
    { user_id: userId2, type: 'Wallet', masked_detail: 'wallet-02', provider: 'Toss', active: true }
  ];
  const createdMethods = [];
  for (const variant of methodVariants) {
    const method = await api.functional.paymentsDiscounts.paymentMethods.post(connection, { body: { ...variant } });
    typia.assert(method);
    createdMethods.push(method);
  }

  // 2. 페이징{page, limit} 전체/일부/엣지케이스 요청, 응답 meta 및 데이터 개수 일치 확인
  let res = await api.functional.paymentsDiscounts.paymentMethods.patch(connection, { body: { limit: 2, sort: 'created_at:asc' } });
  typia.assert(res);
  TestValidator.equals('limit=2')(2)(res.data.length);
  TestValidator.equals('pagination.limit=2')(2)(res.pagination.limit);

  // 마지막 페이지(데이터수/limit 올림), page=N 등
  const total = createdMethods.length;
  const pageCount = Math.ceil(total / 2);
  res = await api.functional.paymentsDiscounts.paymentMethods.patch(connection, { body: { limit: 2, page: pageCount } });
  typia.assert(res);
  TestValidator.equals('last page count')(total - 2 * (pageCount - 1))(res.data.length);

  // page 초과(비어있음)
  res = await api.functional.paymentsDiscounts.paymentMethods.patch(connection, { body: { limit: 2, page: pageCount + 1 } });
  typia.assert(res);
  TestValidator.equals('empty page')(0)(res.data.length);

  // 3. 타입, 프로바이더, 활성화 등 단일 필터
  res = await api.functional.paymentsDiscounts.paymentMethods.patch(connection, { body: { type: 'VISA' } });
  typia.assert(res);
  TestValidator.predicate('VISA only')(res.data.every(d => d.type === 'VISA'));

  res = await api.functional.paymentsDiscounts.paymentMethods.patch(connection, { body: { provider: 'Stripe' } });
  typia.assert(res);
  TestValidator.predicate('Stripe only')(res.data.every(d => d.provider === 'Stripe'));

  res = await api.functional.paymentsDiscounts.paymentMethods.patch(connection, { body: { active: false } });
  typia.assert(res);
  TestValidator.predicate('active=false only')(res.data.every(d => d.active === false));

  res = await api.functional.paymentsDiscounts.paymentMethods.patch(connection, { body: { user_id: userId2 } });
  typia.assert(res);
  TestValidator.predicate('userId2 only')(res.data.every(d => d.user_id === userId2));

  // 4. 복합 필터 (type+provider, provider+active, etc.)
  res = await api.functional.paymentsDiscounts.paymentMethods.patch(connection, { body: { type: 'Wallet', provider: 'Toss' } });
  typia.assert(res);
  TestValidator.predicate('Wallet+Toss')(res.data.every(d => d.type === 'Wallet' && d.provider === 'Toss'));

  res = await api.functional.paymentsDiscounts.paymentMethods.patch(connection, { body: { provider: 'Toss', active: true } });
  typia.assert(res);
  TestValidator.predicate('Toss+active')(res.data.every(d => d.provider === 'Toss' && d.active === true));

  // 5. 생성일 범위(from/to) - 하나 임의 pick해서...
  const createdSample = createdMethods[0];
  res = await api.functional.paymentsDiscounts.paymentMethods.patch(connection, { body: { created_from: createdSample.created_at, created_to: createdSample.created_at } });
  typia.assert(res);
  TestValidator.predicate('created at exact')(res.data.find(d => d.id === createdSample.id));

  // 6. 잘못된(존재하지 않는 type) 필터 → 반환 0
  res = await api.functional.paymentsDiscounts.paymentMethods.patch(connection, { body: { type: 'NONEXISTENT_TYPE_!!!' } });
  typia.assert(res);
  TestValidator.equals('no such type')(0)(res.data.length);

  // 7. 스키마 위반(페이지 음수 등), 허용되지 않는 필드 등 - 에러응답
  await TestValidator.error('negative page', 400)(() =>
    api.functional.paymentsDiscounts.paymentMethods.patch(connection, { body: { page: -3 } })
  );
  await TestValidator.error('extra not-allowed field', 400)(() =>
    api.functional.paymentsDiscounts.paymentMethods.patch(connection, { body: { bogus: 123 } as any })
  );
}

