/**
 * 결제수단 목록 페이징, 각종 필터, 기간/조건별 조회, 오류처리를 종합적으로 검증하는 E2E 시나리오입니다.
 *
 * [비즈니스 흐름]
 * - 사전조건: 다양한 타입/유저/프로바이더/활성화여부 조합의 결제수단을 6개 이상 등록(2명의 user_id 생성, 각 user_id 당 3개씩).
 * 1. 결제수단을 여러 조건(타입/프로바이더/활성화)으로 생성 후 ID, 생성일자 등 정보 확보
 * 2. 각종 단일 필터(type, active, provider, user_id 등)로 일치 결과만 반환되는지 확인
 * 3. 조건 조합(AND)으로 복합 필터링이 정상 동작하는지 확인
 * 4. created_from/to 간 범위로 특정 생성일만 해당되는 결과가 반환되는지 확인
 * 5. 페이지네이션 정상 동작 및 마지노선, 페이지 넘치는 경우 등 엣지케이스 검증
 * 6. 잘못된 입력(type 미존재, page 음수 등) 및 스키마 위반 필드 요청에 적절한 오류 발생/반환 확인
 *
 * [주요 검증 포인트]
 * - 필터 조건(단일/조합) 별 정확한 데이터 반환
 * - 페이지네이션 처리와 pagination meta값 동기화
 * - 정상/오류 응답 명확히 구분
 */
export async function test_api_paymentsDiscounts_test_list_payment_methods_filter_and_pagination(
  connection: api.IConnection,
) {
  // === 1. 테스트 데이터 사전 세팅: sample user 및 다양한 결제수단 입력 ===
  const userId1 = typia.random<string & tags.Format<'uuid'>>();
  const userId2 = typia.random<string & tags.Format<'uuid'>>();
  // 미리 현재시각 기록 (생성일 비교용)
  const now = new Date();
  // 결제수단 유형/프로바이더/활성화여부 다양하게 6개 생성
  const variants: Array<api.IPaymentMethod.ICreate> = [
    { user_id: userId1, type: 'VISA', masked_detail: '**** 1234', provider: 'Stripe', active: true },
    { user_id: userId1, type: 'PayPal', masked_detail: 'user@paypal.com', provider: 'PayPal', active: true },
    { user_id: userId1, type: 'Wallet', masked_detail: 'wallet-01', provider: 'Toss', active: false },
    { user_id: userId2, type: 'VISA', masked_detail: '**** 5678', provider: 'Stripe', active: false },
    { user_id: userId2, type: 'Crypto', masked_detail: 'btc-xxx', provider: 'Binance', active: true },
    { user_id: userId2, type: 'Wallet', masked_detail: 'wallet-02', provider: 'Toss', active: true },
  ];
  // 실제 post로 insert하고 생성결과(생성일 등) 확보
  const methods: api.IPaymentMethod[] = [];
  for (const v of variants) {
    const res = await api.functional.paymentsDiscounts.paymentMethods.post(connection, { body: v });
    typia.assert(res);
    methods.push(res);
  }

  // === 2. pagination/limit 관련 엣지 및 page count 보정 ===
  let resp = await api.functional.paymentsDiscounts.paymentMethods.patch(connection, { body: { limit: 2, sort: 'created_at:asc' } });
  typia.assert(resp);
  TestValidator.equals('limit=2')(2)(resp.data.length);
  TestValidator.equals('pagination.limit=2')(2)(resp.pagination.limit);
  // 마지막 페이지 - (총건수/limit 올림, page=N)
  const total = methods.length;
  const pCount = Math.ceil(total/2);
  resp = await api.functional.paymentsDiscounts.paymentMethods.patch(connection, { body: { limit: 2, page: pCount } });
  typia.assert(resp);
  TestValidator.equals('last page count')(total - 2*(pCount-1))(resp.data.length);
  // page 초과(데이터 없음)
  resp = await api.functional.paymentsDiscounts.paymentMethods.patch(connection, { body: { limit: 2, page: pCount+1 } });
  typia.assert(resp);
  TestValidator.equals('empty page')(0)(resp.data.length);

  // === 3. 단일 필터(type, provider, active, user_id) 정상 동작 확인 ===
  resp = await api.functional.paymentsDiscounts.paymentMethods.patch(connection, { body: { type: 'VISA' } });
  typia.assert(resp);
  TestValidator.predicate('VISA only')(resp.data.every(d => d.type==='VISA'));
  resp = await api.functional.paymentsDiscounts.paymentMethods.patch(connection, { body: { provider: 'Stripe' } });
  typia.assert(resp);
  TestValidator.predicate('Stripe only')(resp.data.every(d => d.provider==='Stripe'));
  resp = await api.functional.paymentsDiscounts.paymentMethods.patch(connection, { body: { active: false } });
  typia.assert(resp);
  TestValidator.predicate('inactive only')(resp.data.every(d=>d.active===false));
  resp = await api.functional.paymentsDiscounts.paymentMethods.patch(connection, { body: { user_id: userId2 } });
  typia.assert(resp);
  TestValidator.predicate('userId2 only')(resp.data.every(d=>d.user_id===userId2));

  // === 4. 복합 필터(type+provider, provider+active 등) ===
  resp = await api.functional.paymentsDiscounts.paymentMethods.patch(connection, { body: { type: 'Wallet', provider: 'Toss' } });
  typia.assert(resp);
  TestValidator.predicate('Wallet+Toss')(resp.data.every(d => d.type==='Wallet' && d.provider==='Toss'));
  resp = await api.functional.paymentsDiscounts.paymentMethods.patch(connection, { body: { provider: 'Toss', active: true } });
  typia.assert(resp);
  TestValidator.predicate('Toss+active')(resp.data.every(d=>d.provider==='Toss' && d.active===true));

  // === 5. 생성일자 from/to 필터 ===
  const sample = methods[0];
  resp = await api.functional.paymentsDiscounts.paymentMethods.patch(connection, { body: { created_from: sample.created_at, created_to: sample.created_at } });
  typia.assert(resp);
  TestValidator.predicate('created at exact')(resp.data.find(d=>d.id===sample.id));

  // === 6. 존재하지 않는 값(query) - 반환 0 확인 ===
  resp = await api.functional.paymentsDiscounts.paymentMethods.patch(connection, { body: { type: 'UNKNOWN_!!!' } });
  typia.assert(resp);
  TestValidator.equals('no such type')(0)(resp.data.length);

  // === 7. 스키마 오류(음수 page 등)/비허용 필드 - 400 명확히 반환 ===
  await TestValidator.error('negative page',400)(()=>
    api.functional.paymentsDiscounts.paymentMethods.patch(connection, { body: { page: -100 } })
  );
  await TestValidator.error('unexpected field',400)(()=>
    api.functional.paymentsDiscounts.paymentMethods.patch(connection, { body: { bogus: 999 } as any })
  );
}

