import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPaymentMethod } from "@ORGANIZATION/PROJECT-api/lib/structures/IPaymentMethod";

/**
 * E2E test for retrieving a payment method by its ID and confirming details,
 * including handling not-found cases.
 *
 * This test validates the retrieval of payment methods, confirming that all
 * detail fields (including sensitive values like masked_detail, provider,
 * activation flag, timestamps, etc.) are returned as expected. It also asserts
 * compliance with correct error handling when requesting a non-existent ID.
 *
 * Steps:
 * 1. Register a new payment method (dependency) using the API, recording its ID.
 * 2. Retrieve the payment method by its ID and verify all returned fields match what was created.
 * 3. Attempt to retrieve a payment method by a non-existent/random UUID; expect a not found error (and proper error response).
 *
 * This ensures that sensitive but non-secret details are safely fetchable for account UIs and audit, but that invalid IDs never leak unwanted info.
 */
export async function test_api_paymentsDiscounts_test_get_payment_method_by_id_various_cases(
  connection: api.IConnection,
) {
  // 1. Register a new payment method
  const pmCreate: IPaymentMethod.ICreate = {
    user_id: typia.random<string & tags.Format<"uuid">>(),
    type: "VISA",
    masked_detail: "**** **** **** 1234",
    provider: "Stripe",
    active: true,
  };
  const created = await api.functional.paymentsDiscounts.paymentMethods.post(connection, {
    body: pmCreate,
  });
  typia.assert(created);
  // 2. Retrieve the method by ID and verify fields
  const retrieved = await api.functional.paymentsDiscounts.paymentMethods.getById(connection, {
    id: created.id,
  });
  typia.assert(retrieved);

  TestValidator.equals("id")(created.id)(retrieved.id);
  TestValidator.equals("user_id")(created.user_id)(retrieved.user_id);
  TestValidator.equals("type")(created.type)(retrieved.type);
  TestValidator.equals("masked_detail")(created.masked_detail)(retrieved.masked_detail);
  TestValidator.equals("provider")(created.provider)(retrieved.provider);
  TestValidator.equals("active")(created.active)(retrieved.active);
  // created_at must be ISO8601 string
  TestValidator.predicate("created_at is iso8601")(!!Date.parse(retrieved.created_at));

  // 3. Attempt retrieval with non-existent ID
  const fakeId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("not found error for missing payment method")(
    async () => {
      await api.functional.paymentsDiscounts.paymentMethods.getById(connection, { id: fakeId });
    },
  );
}

