import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolicy } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolicy";
import type { IPageIPolicy } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPolicy";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test the permission policy paginated list/search endpoint.
 *
 * - Validates searching/filtering by name, conditions, and datetime ranges.
 * - Checks paginated results: first page, last page, page beyond available, page-size limit.
 * - Confirm result matches search/filter: policies returned contain filter value in name/conditions.
 * - Confirm that when there are no matches for filters, the result is an empty array and pagination metadata is correct.
 * - Ensure all result policies conform to IPolicy and overall response matches IPageIPolicy.
 */
export async function test_api_securityCompliance_test_list_permission_policies_with_filter_and_pagination(
  connection: api.IConnection,
) {
  // 1. Basic list query with no filters (should return at least one page)
  const res1 = await api.functional.securityCompliance.policy.patch(connection, {
    body: { page: 1, limit: 3 },
  });
  typia.assert(res1);
  TestValidator.equals("first page number")(1)(res1.pagination.current);
  TestValidator.predicate("data is array")(Array.isArray(res1.data));
  if (res1.data.length > 0) {
    res1.data.forEach((policy) => typia.assert(policy));
  }

  // 2. Filter by non-matching name -- expect empty result
  const res2 = await api.functional.securityCompliance.policy.patch(connection, {
    body: { name: "__NO_POLICY_MATCHES_THIS__", page: 1, limit: 3 },
  });
  typia.assert(res2);
  TestValidator.equals("no results for unmatched filter")(0)(res2.data.length);

  // 3. If there is at least one policy, test fuzzy search by name
  if (res1.data.length > 0) {
    const matchName = res1.data[0].name.slice(0, 3);
    const res3 = await api.functional.securityCompliance.policy.patch(connection, {
      body: { name: matchName, page: 1, limit: 10 },
    });
    typia.assert(res3);
    TestValidator.predicate("fuzzy search returns data")(
      res3.data.length > 0 && res3.data.some((x) => x.name.includes(matchName)),
    );
    res3.data.forEach((policy) => typia.assert(policy));
  }

  // 4. Last page should have correct page number, even if data is possibly empty
  const countRes = await api.functional.securityCompliance.policy.patch(connection, {
    body: { page: 1, limit: 1 },
  });
  typia.assert(countRes);
  const lastPage = countRes.pagination.pages;
  const lastPageRes = await api.functional.securityCompliance.policy.patch(connection, {
    body: { page: lastPage, limit: 1 },
  });
  typia.assert(lastPageRes);
  TestValidator.equals("last page number")(lastPage)(lastPageRes.pagination.current);

  // 5. Excessive page number (beyond last page) returns empty data
  const overPageRes = await api.functional.securityCompliance.policy.patch(connection, {
    body: { page: lastPage + 1, limit: 1 },
  });
  typia.assert(overPageRes);
  TestValidator.equals("over-page is empty")(0)(overPageRes.data.length);
}

