/**
 * Validate fetching a single permission policy by its ID, including negative scenarios and authorization checks.
 *
 * This test ensures that:
 * 1. A permission policy can be created and then fetched by its UUID, with all details returned matching the creation data.
 * 2. When attempting to fetch a policy by a non-existent or deleted UUID, the system returns the appropriate 404 error.
 * 3. (If applicable) Permission checks are enforced for policy detail access—if the endpoint is restricted, ensure forbidden access is handled, otherwise skip.
 *
 * Steps:
 * 1. Create a new permission policy using the 'post' endpoint.
 * 2. Fetch the just-created policy by its ID, asserting all fields and their types/values, ensuring it matches what was created.
 * 3. Attempt to fetch a policy by a random non-existent UUID and confirm that a 404 not found error (or the documented error) is returned.
 * 4. (Conditional) If the system requires elevated privileges or roles for policy read, validate access control logic. If not, document that and proceed.
 */
export async function test_api_securityCompliance_test_get_permission_policy_by_id_and_invalid_id(connection: api.IConnection) {
  // 1. Create a policy to fetch
  const policyCreate: IPolicy.ICreate = {
    name: `TestPolicy_${RandomGenerator.alphaNumeric(8)}`,
    conditions: '{ "role": "admin", "resource": "system" }',
  };
  const created = await api.functional.securityCompliance.policy.post(connection, { body: policyCreate });
  typia.assert(created);
  TestValidator.equals("name matches")(policyCreate.name)(created.name);
  TestValidator.equals("conditions matches")(policyCreate.conditions)(created.conditions);

  // 2. Fetch policy by created ID
  const fetched = await api.functional.securityCompliance.policy.getById(connection, { id: created.id });
  typia.assert(fetched);
  TestValidator.equals("all fields match")(created)(fetched);

  // 3. Attempt to fetch by a random invalid/deleted ID
  const invalidId = typia.random<string & tags.Format<"uuid">>();
  if (invalidId !== created.id) {
    await TestValidator.error("not found for nonexistent ID")(() =>
      api.functional.securityCompliance.policy.getById(connection, { id: invalidId }),
    );
  }

  // 4. (If access control applies) Test forbidden scenario—skip if not applicable per scenario
}

