    api.functional.securityCompliance.policy.post(connection, {
      body: {
        name: uniqueName, // Use same name as previously created policy
        conditions: JSON.stringify({ role: "user", allowed: false }),
      } satisfies IPolicy.ICreate,
    }),
  );

  // 5. [OPTIONAL] Audit trail verification could be added here if API provides a way.
}

