import { tags } from "typia";

/**
 * Permission policy registry entity used for grouping, enforcing, and recording
 * complex access rules. All fields reflect column structure as per Prisma
 * schema, supporting advanced ABAC, RBAC, and audit workflows. Used across
 * every permissioned API system, with direct DB linkage to permission
 * registry.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IPolicy = {
  /** Unique identifier (primary key) for the policy entity. */
  id: string & tags.Format<"uuid">;

  /**
   * Humanfriendly name for policy grouping.
   *
   * All policies must use unique name system-wide; enforced by DB constraint.
   */
  name: string;

  /**
   * Serialized JSON or custom string encoding for policy logic, e.g., time
   * restrictions, geo rules, custom ABAC/segment logic.
   *
   * Strictly required for regulatory audit and permission enforcement.
   */
  conditions: string;

  /**
   * Policy record creation timestamp for evidence chains and compliance
   * analytics.
   */
  created_at: string & tags.Format<"date-time">;
};
export namespace IPolicy {
  /**
   * Creation request structure for registering a new permission policy. Used
   * by security admin flows, registry onboarding, and for compliance
   * explainability export. All fields validated. Uniqueness checked.
   */
  export type ICreate = {
    /** Unique policy name (must not collide with existing name). */
    name: string;

    /**
     * Serialized condition logic (JSON, string DSL, or policy description
     * body). Must not be empty.
     */
    conditions: string;
  };
}

