import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolicy } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolicy";

/**
 * Test soft-deleting an existing permission policy and edge cases.
 *
 * This test validates the soft deletion flow of the permission policy registry. It ensures deleted policies cannot be retrieved or enforced but remain available for audit/evidence if the system supports archival viewing.
 *
 * Steps:
 * 1. Create a new permission policy with unique name and valid condition logic.
 * 2. Soft-delete this policy and verify response structure and evidence retention (deleted policy data returned).
 * 3. Attempt to fetch or delete again and check correct error/response.
 * 4. Try deleting non-existent policy (random UUID) and verify error behavior.
 * 5. If archived/forensic viewing is supported, optionally verify it's accessible only via dedicated methods (not normal lookups).
 *
 * Validations:
 * - Soft deletion disables normal enforcement/lookup, but preserves data for compliance.
 * - API returns pre-deletion info or audit details in deletion response.
 * - Errors for double deletion and not found events are correct type.
 */
export async function test_api_securityCompliance_test_soft_delete_permission_policy_and_edge_cases(connection: api.IConnection) {
  // 1. Create a new permission policy
  const uniqueName = `policy_${RandomGenerator.alphaNumeric(8)}`;
  const conditions = JSON.stringify({ allow: ["admin"], deny: ["guest"] });
  const policy = await api.functional.securityCompliance.policy.post(connection, {
    body: {
      name: uniqueName,
      conditions,
    },
  });
  typia.assert(policy);

  // 2. Soft-delete that policy
  const erased = await api.functional.securityCompliance.policy.eraseById(connection, { id: policy.id });
  typia.assert(erased);
  TestValidator.equals("id")(policy.id)(erased.id);
  TestValidator.equals("name")(policy.name)(erased.name);
  TestValidator.equals("conditions")(policy.conditions)(erased.conditions);

  // 3. Try to soft-delete again; should error (not found or already deleted)
  await TestValidator.error("second deletion must fail")(async () => {
    await api.functional.securityCompliance.policy.eraseById(connection, { id: policy.id });
  });

  // 4. Try deleting a non-existent policy (random UUID)
  await TestValidator.error("non-existent deletion must fail")(async () => {
    await api.functional.securityCompliance.policy.eraseById(connection, { id: typia.random<string & tags.Format<"uuid">>() });
  });
}

