  user_id?: string & tags.Format<"uuid">;

  /**
   * ID of the associated evidence archive, for legal/compliance linkage.
   *
   * References evidence_archive.id; optional.
   */
  evidence_archive_id?: string & tags.Format<"uuid">;

  /**
   * Type of action performed (e.g., 'create', 'update', 'delete',
   * 'payment.approve').
   *
   * Supports compliance, explainability, and evidence review by tracking
   * operations.
   */
  action: string;

  /**
   * Indicates the type of entity affected by the action.
   *
   * Atomic per audit_log schema—examples include 'order', 'user', etc.
   */
  entity_type: string;

  /**
   * ID of the specific affected entity. Nullable for system actions/uncoupled
   * events.
   */
  entity_id?: string & tags.Format<"uuid">;

  /**
   * JSON-encoded metadata for this event.
   *
   * Contains structured data (before/after snapshots, env, etc) for evidence
   * preservation.
   */
  context: string;

  /**
   * Timestamp indicating when the audit record was created.
   *
   * Used for non-repudiation and evidence trails.
   */
  created_at: string & tags.Format<"date-time">;
};
export namespace IAuditLog {
  /**
   * Creation payload for an audit log entry.
   *
