     * Type of action (e.g., 'create', 'update', 'delete'). Atomic, required
     * for regulatory review.
     */
    action: string;

    /**
     * The type of entity affected by the action (e.g., 'order', 'user',
     * 'payment')
     */
    entity_type: string;

    /** UUID of the affected entity (nullable for system/global actions). */
    entity_id?: string & tags.Format<"uuid">;

    /**
     * JSON string holding metadata, before/after snapshots, or rationale
     * (required for compliance/evidence).
     */
