import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuditLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuditLog";

/**
 * Test updating audit log records for field validation, immutability, and nonexistent IDs.
 *
 * Business context:
 * - Audit log records are critical for compliance and should be mostly immutable, allowing changes ONLY to permissible fields (context, evidence_archive_id).
 * - Regulatory traceability and evidence protocols demand strong validation—"hard" fields (action, entity_type, entity_id, created_at, user_id) must NEVER be mutable once created.
 *
 * Test Purpose:
 * - Validate that permitted update fields (context, evidence_archive_id) can be changed and that changes persist as expected.
 * - Ensure attempts to modify forbidden/immutable fields (action, entity_type, created_at, user_id, etc.) are STRICTLY rejected.
 * - Confirm correct error/404 handling for updates to a nonexistent audit log record.
 *
 * Test Steps:
 * 1. Create a valid audit log record
 * 2. Update the log’s allowed fields (context/evidence_archive_id) and verify changes
 * 3. Attempt to update forbidden/immutable fields (expect validation errors/400+ response)
 * 4. Attempt to update an audit log with a random, nonexistent ID (expect 404/not found error)
 */
export async function test_api_securityCompliance_test_update_audit_log_record_field_validations_and_nonexistent_id(
  connection: api.IConnection,
) {
  // 1. Create a valid audit log record via dependency
  const original: IAuditLog = await api.functional.securityCompliance.auditLog.post(connection, {
    body: {
      user_id: typia.random<string & tags.Format<"uuid">>(),
      action: "update",
      entity_type: "user",
      entity_id: typia.random<string & tags.Format<"uuid">>(),
      context: JSON.stringify({ before: "state", after: "state" }),
    } satisfies IAuditLog.ICreate,
  });
  typia.assert(original);

  // 2. Update allowed fields
  const updatePayloadAllowed: IAuditLog.IUpdate = {
    context: JSON.stringify({ before: "state", after: "changed" }),
    evidence_archive_id: typia.random<string & tags.Format<"uuid">>(),
  };
  const updated: IAuditLog = await api.functional.securityCompliance.auditLog.putById(connection, {
    id: original.id,
    body: updatePayloadAllowed,
  });
  typia.assert(updated);
  TestValidator.equals("updated context")(
    updatePayloadAllowed.context,
  )(updated.context);
  TestValidator.equals("updated evidence_archive_id")(
    updatePayloadAllowed.evidence_archive_id,
  )(updated.evidence_archive_id);

  // 3. Attempt to update forbidden/immutable fields
  const forbiddenFieldUpdatesCases = [
    { action: "forbidden_update" },
    { entity_type: "forbidden_entity_type" },
    { created_at: new Date().toISOString() },
    { user_id: typia.random<string & tags.Format<"uuid">>() },
    { id: typia.random<string & tags.Format<"uuid">>() },
  ];
  for (const forbiddenPayload of forbiddenFieldUpdatesCases) {
    await TestValidator.error("immutable field update fails")(async () => {
      await api.functional.securityCompliance.auditLog.putById(connection, {
        id: original.id,
        body: forbiddenPayload as any,
      });
    });
  }

  // 4. Update with random non-existing log ID
  await TestValidator.error("update nonexistent record fails")(async () => {
    await api.functional.securityCompliance.auditLog.putById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
      body: updatePayloadAllowed,
    });
  });
}

