import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuditLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuditLog";

/**
 * Test updating audit log records for permitted mutable fields,
 * immutability enforcement, and nonexistent record handling.
 *
 * Business context:
 * - Audit log records are designed to be immutable except for regulated fields (context, evidence_archive_id); all mutations are strictly controlled and must be audit-traceable.
 * - This ensures regulatory compliance and preserves the integrity of the evidence chain for legal/forensic purposes.
 *
 * Test Purpose:
 * - Validate that permitted update fields (context, evidence_archive_id) can be changed and that changes persist.
 * - Ensure that forbidden/immutable fields (action, entity_type, etc.) are not updatable (and cannot be supplied at compile time by DTO structure).
 * - Attempt an update for a nonexistent audit log ID and verify correct error handling.
 *
 * Test Steps:
 * 1. Create an audit log record via dependency
 * 2. Update its allowed fields and verify persistence
 * 3. Attempt an update for a nonexistent record (expect error)
 * 4. Test partial (empty) update (should succeed/minimally persist)
 */
export async function test_api_securityCompliance_test_update_audit_log_record_field_validations_and_nonexistent_id(
  connection: api.IConnection,
) {
  // 1. Create a valid audit log record
  const original: IAuditLog = await api.functional.securityCompliance.auditLog.post(connection, {
    body: {
      user_id: typia.random<string & tags.Format<"uuid">>(),
      action: "update",
      entity_type: "user",
      entity_id: typia.random<string & tags.Format<"uuid">>(),
      context: JSON.stringify({ before: "state", after: "state" }),
    } satisfies IAuditLog.ICreate,
  });
  typia.assert(original);

  // 2. Update allowed fields (context and evidence_archive_id)
  const updatePayloadAllowed: IAuditLog.IUpdate = {
    context: JSON.stringify({ before: "state", after: "changed" }),
    evidence_archive_id: typia.random<string & tags.Format<"uuid">>(),
  };
  const updated: IAuditLog = await api.functional.securityCompliance.auditLog.putById(connection, {
    id: original.id,
    body: updatePayloadAllowed,
  });
  typia.assert(updated);
  TestValidator.equals("updated context")(updatePayloadAllowed.context)(updated.context);
  TestValidator.equals("updated evidence_archive_id")(updatePayloadAllowed.evidence_archive_id)(updated.evidence_archive_id);
  TestValidator.equals("action unmodified")(original.action)(updated.action);
  TestValidator.equals("entity_type unmodified")(original.entity_type)(updated.entity_type);
  TestValidator.equals("entity_id unmodified")(original.entity_id)(updated.entity_id);
  TestValidator.equals("user_id unmodified")(original.user_id)(updated.user_id);

  // 3. Attempt update for a nonexistent audit log record
  await TestValidator.error("update nonexistent record fails")(async () => {
    await api.functional.securityCompliance.auditLog.putById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
      body: updatePayloadAllowed,
    });
  });

  // 4. Partial/empty update payload (should succeed — no change expected)
  const resultEmpty: IAuditLog = await api.functional.securityCompliance.auditLog.putById(connection, {
    id: original.id,
    body: {}, // no fields to update
  });
  typia.assert(resultEmpty);
  TestValidator.equals("no fields changed")(original.context)(resultEmpty.context);
  TestValidator.equals("no fields changed")(original.evidence_archive_id)(resultEmpty.evidence_archive_id);
}

