  const initial: IPageIComplianceReport.ISummary =
    await api.functional.securityCompliance.complianceReport.patch(connection, {
      body: {}, // No filters, default pagination
    });
  typia.assert(initial);
  TestValidator.predicate("default page has data")(Array.isArray(initial.data));

  // Proceed if there is at least one compliance report for further advanced filtering
  if (initial.data.length) {
    const sample = initial.data[0];
    // 2. Filter by user_id and report_type
    const filteredByUserAndType: IPageIComplianceReport.ISummary =
      await api.functional.securityCompliance.complianceReport.patch(connection, {
        body: {
          user_id: sample.id, // Will use real id if user_id is missing; may need to adjust
          report_type: sample.report_type,
        },
      });
    typia.assert(filteredByUserAndType);
    TestValidator.predicate("filtered results non-empty")(
      Array.isArray(filteredByUserAndType.data)
    );
    filteredByUserAndType.data.forEach((r) => {
      TestValidator.equals("report_type matches")(
        sample.report_type,
      )(r.report_type);
    });
  }

  // 3. Filter by future dates to ensure no-results case
  const now = new Date();
