  const pageOverflow: IPageIComplianceReport.ISummary =
    await api.functional.securityCompliance.complianceReport.patch(connection, {
      body: {
        // page numbers are custom per implementation, assuming page 99999 overflows
      },
    });
  typia.assert(pageOverflow);
  // Acceptable to be empty or have last page data depending on implementation

  // 5. Status filter: check status match
  // To test, retrieve if there is any status in initial data
  if (initial.data.length) {
    const anyStatus = initial.data[0].status;
