import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IComplianceReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IComplianceReport";

/**
 * Validate updating mutable fields of a compliance report and error scenarios for immutables/invalids/nonexistent ID.
 *
 * This test ensures that only allowed fields (status, published_at) can be updated in a compliance report using the update endpoint, and attempts to change immutable fields
 * or provide invalid data result in appropriate errors as enforced by business and legal requirements.
 *
 * 1. Create a new compliance report (dependency setup).
 * 2. Update the compliance report status using an allowed value.
 *      - Verify that the status has been updated properly in the response and other fields remain unchanged.
 * 3. Update the published_at field to a new value (ISO date-time string).
 *      - Confirm the field is changed, others remain the same, and type validation passes.
 * 4. Attempt to update immutable fields (id, user_id, organization_id, report_type, generated_at) and expect a business validation error.
 * 5. Attempt to update with an invalid status (e.g., empty string or unacceptable value) and expect error.
 * 6. Attempt to update a nonexistent compliance report ID and ensure the error is a not-found/business error.
 */
export async function test_api_securityCompliance_test_update_compliance_report_allowed_fields_and_edge_cases(
  connection: api.IConnection,
) {
  // 1. Create new compliance report
  const createInput: IComplianceReport.ICreate = {
    user_id: typia.random<string & tags.Format<"uuid">>(),
    organization_id: typia.random<string & tags.Format<"uuid">>(),
    report_type: "GDPR_EXPORT",
    status: "pending",
    generated_at: new Date().toISOString(),
    published_at: null,
  };
  const created: IComplianceReport = await api.functional.securityCompliance.complianceReport.post(connection, {
    body: createInput,
  });
  typia.assert(created);

  // 2. Update mutable field: status
  const updateStatus = "published";
  const updatedStatus: IComplianceReport = await api.functional.securityCompliance.complianceReport.putById(connection, {
    id: created.id,
    body: { status: updateStatus },
  });
  typia.assert(updatedStatus);
  TestValidator.equals("update status")(updateStatus)(updatedStatus.status);
  TestValidator.equals("id unchanged")(created.id)(updatedStatus.id);
  TestValidator.equals("report_type unchanged")(created.report_type)(updatedStatus.report_type);

  // 3. Update mutable field: published_at
  const pubDate = new Date(Date.now() + 1000 * 60 * 60).toISOString();
  const updatedPub: IComplianceReport = await api.functional.securityCompliance.complianceReport.putById(connection, {
    id: created.id,
    body: { published_at: pubDate },
  });
  typia.assert(updatedPub);
  TestValidator.equals("published_at updated")(pubDate)(updatedPub.published_at);
  TestValidator.equals("id unchanged")(created.id)(updatedPub.id);

  // 4. Attempt to update immutable fields (should fail)
  const tryImmutableFields = async () => {
    await api.functional.securityCompliance.complianceReport.putById(connection, {
      id: created.id,
      body: {
        // These are not allowed and should trigger a validation/business error
        // @ts-expect-error: purposely invalid
        id: typia.random<string & tags.Format<"uuid">>(),
        // @ts-expect-error: purposely invalid
        user_id: typia.random<string & tags.Format<"uuid">>(),
        // @ts-expect-error: purposely invalid
        report_type: "CCPA_EXPORT",
        // @ts-expect-error: purposely invalid
        generated_at: new Date().toISOString(),
      },
    });
  };
  await TestValidator.error("immutable fields reject update")(tryImmutableFields);

  // 5. Attempt invalid status value (empty string)
  const tryInvalidStatus = async () => {
    await api.functional.securityCompliance.complianceReport.putById(connection, {
      id: created.id,
      body: { status: "" },
    });
  };
  await TestValidator.error("invalid status fails")(tryInvalidStatus);

  // 6. Attempt to update a nonexistent compliance report
  const tryNonexistentId = async () => {
    await api.functional.securityCompliance.complianceReport.putById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
      body: { status: "pending" },
    });
  };
  await TestValidator.error("update non-existent report fails")(tryNonexistentId);
}

