import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDataRetention } from "@ORGANIZATION/PROJECT-api/lib/structures/IDataRetention";

/**
 * Validates data retention policy update operations including normal, invalid, and not-found scenarios.
 *
 * This test covers the following:
 * 1. Successfully updating an existing data retention policy with valid changes.
 * 2. Attempting to update with invalid (malformed) values and ensuring validation is triggered.
 * 3. Trying to update a non-existent data retention policy and expecting an appropriate not-found (error) response.
 *
 * Business steps:
 * - First, create a valid data retention policy via the POST endpoint (dependency).
 * - Attempt to update this policy with valid fields (e.g., change retention_period_days and is_legal_hold), verify successful update and correct value changes.
 * - Attempt updates missing both fields or supplying data of wrong type (e.g., negative retention or non-boolean is_legal_hold), and confirm validation errors.
 * - Try updating using a random UUID for policy ID that doesn't exist, and ensure a not-found error is produced.
 * - At each stage, assert type correctness and business logic validity of responses.
 */
export async function test_api_securityCompliance_test_update_data_retention_policy_validations_and_nonexistent_id(connection: api.IConnection) {
  // 1. Create a valid data retention policy as setup
  const initialPolicy = await api.functional.securityCompliance.dataRetention.post(connection, {
    body: {
      entity_type: "user",
      retention_period_days: 365,
      is_legal_hold: false
    }
  });
  typia.assert(initialPolicy);

  // 2. Successful update: change retention_period_days and is_legal_hold
  const updatedPolicy = await api.functional.securityCompliance.dataRetention.putById(connection, {
    id: initialPolicy.id,
    body: {
      retention_period_days: initialPolicy.retention_period_days + 100,
      is_legal_hold: true
    }
  });
  typia.assert(updatedPolicy);
  TestValidator.equals("id")(initialPolicy.id)(updatedPolicy.id);
  TestValidator.equals("retention_period_days")(initialPolicy.retention_period_days + 100)(updatedPolicy.retention_period_days);
  TestValidator.equals("is_legal_hold")(true)(updatedPolicy.is_legal_hold);

  // 3. Invalid update: negative retention_period_days
  await TestValidator.error("negative retention fails")(() =>
    api.functional.securityCompliance.dataRetention.putById(connection, {
      id: initialPolicy.id,
      body: {
        retention_period_days: -5
      }
    })
  );

  // 4. Invalid update: missing both fields (empty body)
  await TestValidator.error("missing update fields fails")(() =>
    api.functional.securityCompliance.dataRetention.putById(connection, {
      id: initialPolicy.id,
      body: {}
    })
  );

  // 5. Attempt update on nonexistent policy
  await TestValidator.error("nonexistent ID fails")(() =>
    api.functional.securityCompliance.dataRetention.putById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
      body: {
        retention_period_days: 1000,
        is_legal_hold: false
      }
    })
  );
}

