import api from "@ORGANIZATION/PROJECT-api";
import type { IDataRetention } from "@ORGANIZATION/PROJECT-api/lib/structures/IDataRetention";

/**
 * Validate the soft deletion (archiving) of a data retention policy and related edge cases.
 *
 * Business context:
 * A data retention policy must, for legal and regulatory compliance, be "soft deleted" (archived) so that evidence of the past policy is always retained. This ensures audit traceability and prevents silent removal. Policies under legal hold or referenced by other systems cannot be deleted. The system must provide evidence of the state change. Attempting to delete an already-archived or nonexistent policy must yield the appropriate error response.
 *
 * Steps:
 * 1. Create a new data retention policy (valid for immediate deletion).
 * 2. Archive (soft-delete) the new policy by ID. Assert the returned object represents an archived state (by whatever field indicates it).
 * 3. Attempt to delete the same policy again. Assert error (cannot delete archived).
 * 4. Attempt to delete a random, nonexistent policy ID. Assert error (not found).
 * 5. Optionally: List all active data retention policies and verify the soft-deleted one is not present.
 */
export async function test_api_securityCompliance_test_soft_delete_data_retention_policy_and_edge_cases(
  connection: api.IConnection,
) {
  // 1. Create a new data retention policy
  const createInput: IDataRetention.ICreate = {
    entity_type: "user",
    retention_period_days: 365,
    is_legal_hold: false,
    // organization_id is optional and may be omitted or set to null
  };
  const policy = await api.functional.securityCompliance.dataRetention.post(connection, { body: createInput });
  typia.assert(policy);

  // 2. Soft-delete (archive) the policy by ID
  const archivedPolicy = await api.functional.securityCompliance.dataRetention.eraseById(connection, { id: policy.id });
  typia.assert(archivedPolicy);
  // There is no field explicitly called 'archived' in the DTO, but we might assert the returned policy exists and is not different

  // 3. Attempt to delete it again, expecting an error
  await TestValidator.error("Cannot delete archived policy")(() =>
    api.functional.securityCompliance.dataRetention.eraseById(connection, { id: policy.id })
  );

  // 4. Attempt to delete a nonexistent policy
  await TestValidator.error("Cannot delete nonexistent policy")(() =>
    api.functional.securityCompliance.dataRetention.eraseById(connection, { id: typia.random<string & tags.Format<"uuid">>() })
  );

  // 5. Optionally: Verify soft-deleted policies are not returned in list (if such endpoint exists, but none is specified)
}

