import { IEvidenceArchive } from "../../../structures/IEvidenceArchive";
import { IPageIEvidenceArchive } from "../../../structures/IPageIEvidenceArchive";

/**
 * List/search evidence archives from SecurityCompliance evidence_archive table.
 *
 * This endpoint allows clients to retrieve a paginated list of evidence archive
 * records. It references the evidence_archive table in the Prisma schema, which
 * preserves evidence such as compliance snapshots, legal exports, payment logs,
 * and user data requests. All search parameters (such as evidence_type,
 * checksum, created_at) are mapped to schema columns for traceability. Security
 * controls must enforce strict access for compliance teams, and all queries
 * must be logged with full audit. The data returned includes immutable evidence
 * metadata, blob links, sizes, cryptographic hashes, and creation timestamps.
 * Extensive error handling accounts for unauthorized access, malformed queries,
 * or compliance policy violations. This endpoint supports regulatory reporting,
 * forensics, and evidence search in audits. Related endpoints include GET,
 * POST/PUT, and DELETE for detailed evidence archive management. All requests
 * and responses are evidence-grade and append-only, and critical for compliance
 * with legal and audit requirements.
 *
 * @param props.connection
 * @param props.body Search and pagination parameters for evidence archives.
 * @path /securityCompliance/evidenceArchive
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export async function patch(
  connection: IConnection,
  props: patch.Props,
): Promise<patch.Response> {
  return !!connection.simulate
    ? patch.simulate(connection, props)
    : PlainFetcher.fetch(
        {
          ...connection,
          headers: {
            ...connection.headers,
            "Content-Type": "application/json",
          },
        },
        {
          ...patch.METADATA,
          path: patch.path(),
          status: null,
        },
        props.body,
      );
}
export namespace patch {
  export type Props = {
    /** Search and pagination parameters for evidence archives. */
    body: IEvidenceArchive.IRequest;
  };
  export type Body = IEvidenceArchive.IRequest;
  export type Response = IPageIEvidenceArchive;

  export const METADATA = {
    method: "PATCH",
    path: "/securityCompliance/evidenceArchive",
    request: {
      type: "application/json",
      encrypted: false,
    },
    response: {
      type: "application/json",
      encrypted: false,
    },
  } as const;

  export const path = () => "/securityCompliance/evidenceArchive";
  export const random = (
    g?: Partial<typia.IRandomGenerator>,
  ): IPageIEvidenceArchive => typia.random<IPageIEvidenceArchive>(g);
  export const simulate = (
    connection: IConnection,
    props: patch.Props,
  ): Response => {
    const assert = NestiaSimulator.assert({
      method: METADATA.method,
      host: connection.host,
      path: patch.path(),
      contentType: "application/json",
    });
    try {
      assert.body(() => typia.assert(props.body));
    } catch (exp) {
      if (!typia.is<HttpError>(exp)) throw exp;
      return {
        success: false,
        status: exp.status,
        headers: exp.headers,
        data: exp.toJSON().message,
      } as any;
    }
    return random(
      "object" === typeof connection.simulate && null !== connection.simulate
        ? connection.simulate
        : undefined,
    );
  };
}

