   * 'PAYMENT_LOG_SNAPSHOT'.
   *
   * Reference: IEvidenceArchive.evidence_type.
   */
  evidence_type: string;

  /**
   * URI or reference to binary content storage: S3, Blob Storage, external
   * evidence vault, etc.
   *
   * Reference: IEvidenceArchive.blob_url.
   */
  blob_url: string;

  /**
   * Size of the archived evidence file (bytes).
   *
   * Reference: IEvidenceArchive.size_bytes.
   */
  size_bytes: number & tags.Type<"int32">;

  /**
   * Cryptographic hash (eg, SHA256) for integrity evidence.
   *
   * Reference: IEvidenceArchive.checksum.
   */
  checksum: string;

  /**
   * Timestamp of evidence creation/archival.
   *
   * Reference: IEvidenceArchive.created_at.
   */
  created_at: string & tags.Format<"date-time">;
};
export namespace IEvidenceArchive {
  /**
   * Search, filtering, and pagination request for evidence archives.
   *
   * Aligns with queryable fields of the evidence_archive schema for
   * regulatory and forensic queries.
   */
  export type IRequest = {
    /**
     * (Optional) Evidence type/category filter for search, e.g.,
     * 'GDPR_EXPORT', 'PAYMENT_LOG'.
     *
     * Reference: IEvidenceArchive.evidence_type.
     */
    evidence_type?: string;

    /**
     * (Optional) Exact or partial checksum to match evidence by integrity
     * hash.
     *
     * Reference: IEvidenceArchive.checksum.
     */
    checksum?: string;

    /** (Optional) Filter evidence created after this time (inclusive). */
    created_at_from?: string & tags.Format<"date-time">;

    /** (Optional) Filter evidence created before this time (inclusive). */
    created_at_to?: string & tags.Format<"date-time">;

    /** Requested page number for pagination. */
    page?: number & tags.Type<"int32">;

    /** Number of records per page. */
    limit?: number & tags.Type<"int32">;
  };
}

