import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test searching and paginating through evidence archive records with various filters.
 *
 * - Validates that evidence archive query returns correct paginated results according to supplied filters (evidence_type, checksum, created_at_from/to, etc).
 * - Ensures pagination metadata (limit, current, pages, records) is accurate and consistent.
 * - Tests filtering by evidence_type, checksum, and created date boundaries, including edge cases (no result pages, last page, first page, etc).
 * - Confirms that search for a nonexistent or unauthorized record yields empty data (and no info leakage).
 * - Verifies that only authorized users can access evidence records. If the user is not authorized, the API must not return data or must reject the request.
 *
 * Steps:
 * 1. Populate several evidence archive records of different types and dates (precondition or as part of test setup).
 * 2. Search with broad filters and assert results and pagination meta are correct (covers multiple types).
 * 3. Narrow filter by evidence_type, assert only relevant records appear.
 * 4. Filter by checksum (test exact/partial matching, case-sensitivity).
 * 5. Apply created_at_from and created_at_to, checking time boundaries are respected.
 * 6. Request beyond last page (should get empty data, correct pagination meta).
 * 7. Try an unauthorized account; confirm no data leakage or rejection.
 */
export async function test_api_securityCompliance_test_list_evidence_archive_with_pagination_filter_and_authz(connection: api.IConnection) {
  // 1. [SETUP] Create (or ensure exist) evidence archive records of different types and dates for meaningful testing
  // -- In real environments, insert at least two evidence_type, spread checksums/timestamps
  // (As precondition, or simulate using admin rights if allowed. Code can skip creation if no API for it)

  // (a) Base search with no filter (should retrieve all paged)
  const allRes = await api.functional.securityCompliance.evidenceArchive.patch(connection, { body: { page: 1, limit: 5 } });
  typia.assert(allRes);
  TestValidator.predicate("should return records with correct pagination")(allRes.data.length > 0 && allRes.pagination.current === 1);

  const pageCount = allRes.pagination.pages;
  const totalRecords = allRes.pagination.records;

  // (b) Filter by evidence_type if present
  if (allRes.data.length > 0) {
    const evidenceType = allRes.data[0].evidence_type;
    const filteredByType = await api.functional.securityCompliance.evidenceArchive.patch(connection, { body: { evidence_type: evidenceType, page: 1, limit: 10 } });
    typia.assert(filteredByType);
    TestValidator.predicate("all records should match type")(filteredByType.data.every(x => x.evidence_type === evidenceType));
  }

  // (c) Filter by checksum (exact match)
  if (allRes.data.length > 0) {
    const checksum = allRes.data[0].checksum;
    const filteredByChecksum = await api.functional.securityCompliance.evidenceArchive.patch(connection, { body: { checksum, page: 1, limit: 10 } });
    typia.assert(filteredByChecksum);
    TestValidator.predicate("all records should match checksum")(filteredByChecksum.data.every(x => x.checksum === checksum));
  }

  // (d) created_at range (pick at least one existing record's time)
  if (allRes.data.length > 0) {
    const baseTime = allRes.data[0].created_at;
    const dateFiltered = await api.functional.securityCompliance.evidenceArchive.patch(connection, { body: { created_at_from: baseTime, created_at_to: baseTime, page: 1, limit: 10 } });
    typia.assert(dateFiltered);
    TestValidator.predicate("results within time bounds")(dateFiltered.data.every(x => x.created_at === baseTime));
  }

  // (e) Go to a page beyond the last
  if (pageCount > 0) {
    const tooHigh = await api.functional.securityCompliance.evidenceArchive.patch(connection, { body: { page: pageCount + 1, limit: 5 } });
    typia.assert(tooHigh);
    TestValidator.equals("out of bounds empty page")(0)(tooHigh.data.length);
  }

  // (f) Empty filter for definitely empty result
  const emptyFilter = await api.functional.securityCompliance.evidenceArchive.patch(connection, {
    body: {
      evidence_type: "NON_EXISTENT_TYPE_NAME_DOES_NOT_EXIST",
      page: 1, limit: 10
    }
  });
  typia.assert(emptyFilter);
  TestValidator.equals("completely empty search")(0)(emptyFilter.data.length);

  // (g) [OPTIONAL] Try with an unauthorized connection/profile if framework supports impersonation (skip if not supported)
  // If possible: create/reuse an unauthorized IConnection, then expect API to return nothing/sensitive fields NOT present, or error.
  // Example:
  /*
  await TestValidator.error("unauthorized must fail")(() =>
    api.functional.securityCompliance.evidenceArchive.patch(unauthConn, {
      body: { page: 1, limit: 1 },
    })
  );
  */
}

