  const validBody: IEvidenceArchive.ICreate = {
    evidence_type: "GDPR_EXPORT",
    blob_url: "https://evidence-bucket/compliance/proof1234.pdf",
    size_bytes: 2048,
    checksum: "87cfab065bfcf13e4a3fda0ad2c8dae40d6b0c374c50c9822a3f2f3818698837"
  };
  const created = await api.functional.securityCompliance.evidenceArchive.post(connection, { body: validBody });
  typia.assert(created);
  TestValidator.equals("evidence_type")(validBody.evidence_type)(created.evidence_type);
  TestValidator.equals("blob_url")(validBody.blob_url)(created.blob_url);
  TestValidator.equals("size_bytes")(validBody.size_bytes)(created.size_bytes);
  TestValidator.equals("checksum")(validBody.checksum)(created.checksum);
  TestValidator.predicate("created_at should be ISO8601 date string")(/T.*Z$/.test(created.created_at));
