    });
  });
  // 2c: Missing blob_url -- skip
  // 2d: Empty blob_url
  await TestValidator.error("empty blob_url fails")(async () => {
    await api.functional.securityCompliance.evidenceArchive.post(connection, {
      body: { ...validBody, blob_url: "" },
    });
  });
  // 2e: Negative size_bytes
