    await api.functional.securityCompliance.evidenceArchive.post(connection, {
      body: { ...validBody, size_bytes: -100 },
    });
  });

  // 3. Duplicate record (if backend deduplicates or rejects duplicates)
  await TestValidator.error("duplicate evidence cannot be created")(async () => {
    await api.functional.securityCompliance.evidenceArchive.post(connection, { body: validBody });
