import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IEvidenceArchive } from "@ORGANIZATION/PROJECT-api/lib/structures/IEvidenceArchive";

/**
 * Validate updating evidence archive entries with both valid and invalid data.
 *
 * Ensures the /securityCompliance/evidenceArchive/{id} PUT endpoint allows updating only permitted metadata fields. Tests both success and expected failure modes:
 *
 * 1. Successfully updates an evidence archive entry's evidence_type and verifies the change is reflected.
 * 2. Attempts updates with missing required data (e.g., empty body or lacking updatable fields), expecting validation errors.
 * 3. Attempts to update immutable fields (e.g., size_bytes or checksum), expecting rejection/validation errors.
 * 4. Attempts to update an entry by a nonexistent ID and expects not found handling.
 *
 * Prerequisite: An evidence archive entry is created for use as the update target.
 */
export async function test_api_securityCompliance_test_update_evidence_archive_entry_fields_and_nonexistent_id(
  connection: api.IConnection,
) {
  // 1. Create an evidence archive entry to update
  const createInput: IEvidenceArchive.ICreate = {
    evidence_type: "PAYMENT_EXPORT",
    blob_url: "https://bucket.example.com/path/to/file1.pdf",
    size_bytes: 2048,
    checksum: "a4c13b10e222ecb3adc66414cd368788f5ad10aaa671e0e2ea5d93b85e632229"
  };
  const created: IEvidenceArchive = await api.functional.securityCompliance.evidenceArchive.post(connection, { body: createInput });
  typia.assert(created);

  // 2. Successfully update evidence_type (a permitted field)
  const updatedType = created.evidence_type + "_MODIFIED";
  const updateResult: IEvidenceArchive = await api.functional.securityCompliance.evidenceArchive.putById(connection, {
    id: created.id,
    body: { evidence_type: updatedType }
  });
  typia.assert(updateResult);
  TestValidator.equals("evidence_type was updated")(updatedType)(updateResult.evidence_type);

  // 3. Attempt update with empty body (should fail validation)
  await TestValidator.error("update fails with empty body")(() =>
    api.functional.securityCompliance.evidenceArchive.putById(connection, {
      id: created.id,
      body: {} as IEvidenceArchive.IUpdate
    })
  );

  // 4. Attempt update with an immutable field (should fail validation or be ignored)
  await TestValidator.error("update fails on immutable field size_bytes")(() =>
    api.functional.securityCompliance.evidenceArchive.putById(connection, {
      id: created.id,
      body: { size_bytes: 1234 } as any // purposely inject invalid field
    })
  );

  // 5. Attempt update with a nonexistent record ID (should result in not found error)
  await TestValidator.error("update fails with nonexistent ID")(() =>
    api.functional.securityCompliance.evidenceArchive.putById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
      body: { evidence_type: "GDPR_EXPORT" }
    })
  );
}

