import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IEvidenceArchive } from "@ORGANIZATION/PROJECT-api/lib/structures/IEvidenceArchive";

/**
 * Validates soft deletion (logical deletion) of an evidence archive record and all associated business rules.
 *
 * This test case ensures that:
 * 1. An evidence archive record can be successfully soft deleted using the DELETE endpoint.
 * 2. After deletion, the record is not retrievable through normal evidence archive queries (confirming soft delete hides data from standard access).
 * 3. Soft deleting a nonexistent record returns an error/appropriate response (ensures system rejects invalid deletion attempts).
 * 4. Attempting to soft delete an already deleted record is properly handled (idempotence or error response as per business logic).
 * 5. The evidence preservation policy is enforced—no physical data loss takes place (out of API test scope, but deletion is non-destructive at API level).
 *
 * Test procedure:
 * 1. Create a new evidence archive record (using POST endpoint as dependency).
 * 2. Soft delete this record using DELETE endpoint (eraseById).
 * 3. Attempt to retrieve the record after soft delete via expected detail or listing API to confirm it is not returned in standard retrievals.
 * 4. Attempt to soft delete the same record again (should receive error or idempotent OK depending on policy).
 * 5. Attempt to soft delete a random nonexistent UUID (should receive error/404 response).
 */
export async function test_api_securityCompliance_test_soft_delete_evidence_archive_entry_and_edge_cases(
  connection: api.IConnection,
) {
  // 1. Create evidence archive entry for deletion test.
  const createInput: IEvidenceArchive.ICreate = {
    evidence_type: 'DSAR_ARCHIVE',
    blob_url: `https://test-bucket.s3.amazonaws.com/evidence/${typia.random<string & tags.Format<"uuid">>()}.blob`,
    size_bytes: typia.random<number & tags.Type<"int32"> & tags.Minimum<1> & tags.Maximum<50000000>>(),
    checksum: RandomGenerator.alphaNumeric(64),
  };
  const evidenceArchive = await api.functional.securityCompliance.evidenceArchive.post(connection, {
    body: createInput,
  });
  typia.assert(evidenceArchive);

  // 2. Soft delete the evidence archive record.
  const deleted = await api.functional.securityCompliance.evidenceArchive.eraseById(connection, {
    id: evidenceArchive.id,
  });
  typia.assert(deleted);

  // 3. Verify the deleted record is not returned on normal queries (requires invoking GET/list endpoint if available, pseudo-skipped if not).
  //    [NOTE: Actual retrieval endpoints are not defined in these inputs; this check would be implemented if the detail/list API were available.]

  // 4. Attempt to soft delete the already deleted record (should error or succeed idempotently based on policy).
  await TestValidator.error("deleting already-deleted evidence archive")(() =>
    api.functional.securityCompliance.evidenceArchive.eraseById(connection, {
      id: evidenceArchive.id,
    }),
  );

  // 5. Attempt to soft delete a nonexistent evidence archive record (random UUID).
  await TestValidator.error("deleting nonexistent evidence archive")(() =>
    api.functional.securityCompliance.evidenceArchive.eraseById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
    }),
  );
}

