/**
 * List and search API clients in API_Omnichannel api_clients table.
 *
 * Fetches a paginated list of API clients with search and filter criteria (such
 * as client_name, status, contact_email, created_at). Implements best practices
 * for API credential management and audit. Strict permission controls and
 * detailed access logging are enforced. Only administrators or delegated system
 * automation may view or list API clients. Each listed client includes
 * identification, status, public keys, contact info, and registration dates,
 * all necessary for omnichannel and extensibility compliance. Result set
 * follows IPageIApiClients for structured pagination, metadata, total counts,
 * and evidence-grade logging. Related endpoints include GHET/POST for specifics
 * or creating new API clients, PUT for updates, DELETE for soft removal.
 *
 * @param props.connection
 * @param props.body Filtering and pagination for API clients.
 * @path /apiOmnichannel/apiClients
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export async function patch(
  connection: IConnection,
  props: patch.Props,
): Promise<patch.Response> {
  return !!connection.simulate
    ? patch.simulate(connection, props)
    : PlainFetcher.fetch(
        {
          ...connection,
          headers: {
            ...connection.headers,
            "Content-Type": "application/json",
          },
        },
        {
          ...patch.METADATA,
          path: patch.path(),
          status: null,
        },
        props.body,
      );
}
export namespace patch {
  export type Props = {
    /** Filtering and pagination for API clients. */
    body: IApiClients.IRequest;
  };
  export type Body = IApiClients.IRequest;
  export type Response = IPageIApiClients;

  export const METADATA = {
    method: "PATCH",
    path: "/apiOmnichannel/apiClients",
    request: {
      type: "application/json",
      encrypted: false,
    },
    response: {
      type: "application/json",
      encrypted: false,
    },
  } as const;

  export const path = () => "/apiOmnichannel/apiClients";
  export const random = (
    g?: Partial<typia.IRandomGenerator>,
  ): IPageIApiClients => typia.random<IPageIApiClients>(g);
