import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IApiClients } from "@ORGANIZATION/PROJECT-api/lib/structures/IApiClients";
import type { IPageIApiClients } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIApiClients";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * E2E test function to verify listing and searching of API clients using the /apiOmnichannel/apiClients PATCH endpoint.
 *
 * Business context: System administrators need to be able to search, filter, and obtain paginated API client registry records for audit, compliance, integration, and management tasks. This test ensures the backend correctly implements filtering, paging, and edge-case responses for various search scenarios, and provides the correct structure for result and pagination metadata.
 *
 * Steps:
 * 1. List API clients with no filters (default page/limit; expect data and correct pagination info).
 * 2. Search by a likely-nonexistent client name (expect empty data array and correct pagination metadata for empty result).
 * 3. Use a high page number (e.g., 9999) beyond the record count (expect empty data and last/empty page edge-case).
 * 4. Filter by is_active=false and is_active=true, if possible (expect correct boolean filtering and only results matching that status).
 * 5. If any clients exist, pick a real client's name, then search by exact name (expect data contains only those clients).
 * 6. Confirm result structure matches IPageIApiClients (has pagination metadata, data array; no unexpected properties; all types are correct).
 * 7. Explore limit parameter by using small and large limits, and ensure page size matches, and pagination.info accurate.
 *
 * This validates both the happy-path, filter, and edge-case handling for admin API client search and listing in a paginated system.
 */
export async function test_api_apiOmnichannel_test_list_api_clients_filtering_and_pagination(connection: api.IConnection) {
  // 1. List clients, default (no filter)
  const noFilter = await api.functional.apiOmnichannel.apiClients.patch(connection, { body: {} });
  typia.assert(noFilter);
  TestValidator.predicate("data is array")(Array.isArray(noFilter.data));
  TestValidator.predicate("pagination present")(typeof noFilter.pagination === 'object');
  TestValidator.predicate("pagination.current valid")(typeof noFilter.pagination.current === 'number');

  // 2. Likely-nonexistent client name
  const emptyRes = await api.functional.apiOmnichannel.apiClients.patch(connection, {
    body: { client_name: "zzz_nonexistent_client_name_zzz", page: 1, limit: 10 },
  });
  typia.assert(emptyRes);
  TestValidator.equals("Empty set returns empty data")(0)(emptyRes.data.length);

  // 3. Excessive/high page number
  const pageBeyond = await api.functional.apiOmnichannel.apiClients.patch(connection, {
    body: { page: 9999, limit: 10 },
  });
  typia.assert(pageBeyond);
  TestValidator.equals("Page beyond count")(0)(pageBeyond.data.length);

  // 4. Filter by is_active=false & is_active=true
  for (const flag of [true, false]) {
    const flt = await api.functional.apiOmnichannel.apiClients.patch(connection, { body: { is_active: flag, page: 1, limit: 10 } });
    typia.assert(flt);
    TestValidator.predicate(`filter is_active=${flag}`)(flt.data.every(cli => cli.is_active === flag));
  }

  // 5. Search by existing name if possible
  if (noFilter.data.length > 0) {
    const example = noFilter.data[0];
    const byName = await api.functional.apiOmnichannel.apiClients.patch(connection, {
      body: { client_name: example.client_name, page: 1, limit: 10 },
    });
    typia.assert(byName);
    TestValidator.predicate("data found by name")(byName.data.length > 0);
    TestValidator.predicate("all match by name")(byName.data.every(cli => cli.client_name === example.client_name));
  }

  // 6/7. Pagination: limits & structure
  for (const limit of [1, 2, 20]) {
    const paged = await api.functional.apiOmnichannel.apiClients.patch(connection, {
      body: { page: 1, limit },
    });
    typia.assert(paged);
    TestValidator.predicate(`limit respected: ${limit}`)(paged.data.length <= limit);
    TestValidator.predicate(`pagination.limit matches`)(paged.pagination.limit === limit);
  }
}

