import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IApiClients } from "@ORGANIZATION/PROJECT-api/lib/structures/IApiClients";

/**
 * 테스트 목적: 특정 API 클라이언트의 메타데이터를 ID로 조회하는 기능을 검증한다.
 *
 * 주요 단계:
 * 1. 신규 API 클라이언트를 등록한다(선행조건).
 * 2. 정상적인(존재하는) ID로 /apiOmnichannel/apiClients/{id}를 조회한다.
 *    - 메타데이터의 모든 필드(키와 값)를 점검한다.
 *    - 반환되는 클라이언트 정보가 생성 시 입력한 값과 일치하는지 확인한다.
 * 3. 존재하지 않거나 잘못된 ID(랜덤 UUID 등)로 조회를 시도한다.
 *    - 404 Not Found 등 적절한 오류 응답이 반환되는지 검증한다.
 * 4. (옵션) 기밀이거나 제한된 권한의 API 클라이언트에 접근 통제 확인.
 *
 * 비즈니스 및 보안 관점에서, 관리자/레지스트리 권한이 없는 사용자가 접근 시 허가되지 않음(401/403)을 반환해야 함도 추가로 점검할 수 있다. (테스트 환경에 따라 생략 가능)
 */
export async function test_api_apiOmnichannel_test_get_api_client_by_valid_and_invalid_id(connection: api.IConnection) {
  // 1. 신규 API 클라이언트 등록 (선행조건)
  const clientName = RandomGenerator.alphaNumeric(10);
  const email = `${RandomGenerator.alphaNumeric(8)}@company.com`;
  const createInput: IApiClients.ICreate = {
    client_name: clientName,
    contact_email: email,
    public_key: RandomGenerator.alphaNumeric(32),
    description: RandomGenerator.paragraph()(1),
  };
  const created = await api.functional.apiOmnichannel.apiClients.post(connection, { body: createInput });
  typia.assert(created);

  // 2. 유효한 ID로 API 클라이언트 조회
  const fetched = await api.functional.apiOmnichannel.apiClients.getById(connection, { id: created.id });
  typia.assert(fetched);
  TestValidator.equals("조회된 client_name은 생성값과 동일해야 함")(createInput.client_name)(fetched.client_name);
  TestValidator.equals("조회된 contact_email은 생성값과 동일해야 함")(createInput.contact_email)(fetched.contact_email);
  TestValidator.equals("is_active는 true여야 함")(true)(fetched.is_active);
  TestValidator.equals("id 필드는 유효한 UUID여야 함")(created.id)(fetched.id);
  TestValidator.equals("created_at 필드는 존재해야 함")(true)(!!fetched.created_at);

  // 3. 잘못된(존재하지 않는) ID로 조회 시도 - 404 등 오류 검증
  await TestValidator.error("존재하지 않는 ID로 조회하면 404 오류가 발생해야 함")(async () => {
    await api.functional.apiOmnichannel.apiClients.getById(connection, { id: typia.random<string & tags.Format<"uuid">>() });
  });

  // 4. (옵션) 제한된 권한 또는 기밀 클라이언트 ID 접근 검증은 환경에 따라 생략
}

