import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IApiClients } from "@ORGANIZATION/PROJECT-api/lib/structures/IApiClients";

/**
 * Validate the creation of a new API client via POST /apiOmnichannel/apiClients.
 *
 * This test covers both successful creation and validation/business logic errors:
 * 1. Create a new API client with all required fields and valid values – expect success and correct record returned.
 * 2. Attempt to create with missing required fields (e.g., omit client_name or contact_email) – expect validation errors.
 * 3. Attempt to create a client with duplicate client_name or contact_email – expect unique constraint policy error.
 * 4. Attempt to create with an invalid value (e.g., contact_email not an email, or too short names) – expect input validation error.
 * 5. On successful creation, verify key onboarding/audit side effects (created_at is set, is_active default/field, returned object matches input plus audit/registry fields).
 *
 * Steps:
 * 1. Compose a well-formed IApiClients.ICreate with unique client_name and contact_email, valid public_key and description, call POST and assert successful creation.
 * 2. Validate success record fields (id, client_name, contact_email, is_active, created_at, etc), assert types and values.
 * 3. Compose an invalid request: missing client_name, expect error.
 * 4. Compose an invalid request: missing contact_email, expect error.
 * 5. Compose an invalid request: invalid format contact_email, expect error.
 * 6. Compose a duplicate client creation (same client_name/contact_email as valid), expect duplicate error.
 */
export async function test_api_apiOmnichannel_test_create_api_client_with_field_validations_and_uniqueness(
  connection: api.IConnection,
) {
  // 1. Happy path: Create a unique valid API client
  const uniqueName = `client_${RandomGenerator.alphaNumeric(8)}`;
  const uniqueEmail = `admin_${RandomGenerator.alphaNumeric(8)}@test-api.com`;
  const createInput: IApiClients.ICreate = {
    client_name: uniqueName,
    contact_email: uniqueEmail,
    public_key: RandomGenerator.alphaNumeric(32),
    description: RandomGenerator.paragraph()(1),
  };
  const created = await api.functional.apiOmnichannel.apiClients.post(connection, { body: createInput });
  typia.assert(created);
  // Validate returned fields
  TestValidator.equals("client_name")(createInput.client_name)(created.client_name);
  TestValidator.equals("contact_email")(createInput.contact_email)(created.contact_email);
  TestValidator.predicate("is_active default true")(
    typeof created.is_active === "boolean" && created.is_active === true
  );
  TestValidator.predicate("id is uuid")(
    typeof created.id === "string" && /^[0-9a-f-]{36,}$/i.test(created.id)
  );
  TestValidator.predicate("created_at is date-time")(
    typeof created.created_at === "string" && !isNaN(Date.parse(created.created_at))
  );
  // 2. Validation error: Missing required client_name
  await TestValidator.error("missing client_name fails")(() =>
    api.functional.apiOmnichannel.apiClients.post(connection, {
      body: {
        // client_name: missing
        contact_email: `error${RandomGenerator.alphaNumeric(6)}@test-api.com`,
        public_key: RandomGenerator.alphaNumeric(32),
        description: RandomGenerator.paragraph()(1),
      } as any,
    })
  );
  // 3. Validation error: Missing contact_email
  await TestValidator.error("missing contact_email fails")(() =>
    api.functional.apiOmnichannel.apiClients.post(connection, {
      body: {
        client_name: `errorClient_${RandomGenerator.alphaNumeric(8)}`,
        // contact_email: missing
        public_key: RandomGenerator.alphaNumeric(32),
        description: RandomGenerator.paragraph()(1),
      } as any,
    })
  );
  // 4. Validation error: Invalid email format
  await TestValidator.error("invalid contact_email format fails")(() =>
    api.functional.apiOmnichannel.apiClients.post(connection, {
      body: {
        client_name: `invalidEmailClient_${RandomGenerator.alphaNumeric(8)}`,
        contact_email: "not-an-email",
        public_key: RandomGenerator.alphaNumeric(32),
        description: RandomGenerator.paragraph()(1),
      } satisfies IApiClients.ICreate,
