export namespace IFavoritesPersonalization {
  /**
   * Payload for creating a new bookmark in the
   * FavoritesPersonalization.bookmarks entity.
   *
   * Defines minimum fields and all permissible user metadata for creation
   * (product, optional custom_folder/tag/note). Creation is subject to
   * evidence and uniqueness validation (per-user/per-product one bookmark).
   * Audit entry required for compliance and explainability (e.g., DSAR, A11Y,
   * AI recommendations feedback).
   */
  export type IBookmarkCreate = {
    /**
     * The user creating the bookmark (users.id).
     *
     * Required for audit, DSAR, downstream analytics.
     */
    user_id: string & tags.Format<"uuid">;

    /**
     * The product being bookmarked (products.id).
     *
     * Required, must refer to existing, visible product entity.
     */
    product_id: string & tags.Format<"uuid">;

    /** Optional folder/category (user-defined) for organizing bookmarks. */
    custom_folder?: string | null;

    /** Optional user-set tag for advanced search/analytics linkage. */
    tag?: string | null;

    /**
     * Optional user note attached to this bookmark, for personalization,
     * DSAR, or A11Y purposes.
     */
    note?: string | null;
  };

  /**
   * A user's bookmark entry for a product/item, in the
   * FavoritesPersonalization domain.
   *
   * This entity records the per-user customized organization of a product via
   * bookmarks, allowing extra metadata, organization (custom_folder), tags,
   * notes, and evidence of deletion. Normalized per schema, with clear
   * separation of audit evidence, metadata, and domain references. All fields
   * are atomic, with strict typing for evidence preservation, a11y, and DSAR
   * needs. Bookmarks always reference user and product entities for privacy
   * tracing.
   */
  export type IBookmark = {
    /**
     * Unique identifier for this bookmark entry (PK). Used for reference,
     * audit, and evidence logs.
     */
    id: string & tags.Format<"uuid">;

    /**
     * Reference to the user who owns this bookmark (users.id FK). Enables
     * personalized, privacy-compliant data scoping.
     */
    user_id: string & tags.Format<"uuid">;

    /**
     * Reference to the bookmarked product/item (products.id FK). For
     * analytics, dashboard, and AI/ML personalization.
     */
    product_id: string & tags.Format<"uuid">;

    /**
     * Optional user label/folder/category for this bookmark. Implements
     * user customization for wishlists, gift-lists, etc.
     */
    custom_folder?: string | null;

    /**
     * User-defined tag for advanced search/analytics and explainability of
     * personalization.
     */
    tag?: string | null;

    /**
     * Optional private user note attached to a bookmark. For export, DSAR
     * compliance, and advanced analytics.
     */
    note?: string | null;

    /**
     * Timestamp when bookmark was created (UTC, RFC3339). For timeline
     * analytics, evidence, regulatory trace.
     */
    created_at: string & tags.Format<"date-time">;

    /**
     * If non-null, soft deletion evidence timestamp for compliance,
     * evidence, or user preference deletion.
     */
    deleted_at?: (string & tags.Format<"date-time">) | null;
  };
}

