/**
 * Validate the soft deletion mechanism of bookmarks by ID.
 *
 * This test ensures that:
 * 1. A bookmark can be soft deleted by its unique identifier and the deletion timestamp is set.
 * 2. The record remains retrievable or at least logically present (for compliance/audit evidence) after deletion, reflecting its deleted/inactive status through a set deleted_at.
 * 3. Deleting a non-existent or already deleted bookmark results in a 404 or other error indicating non-existence.
 *
 * Step-by-step process:
 * 1. Create a new bookmark using the POST /favoritesPersonalization/bookmarks endpoint to ensure a valid, undeleted bookmark for testing.
 * 2. Call DELETE /favoritesPersonalization/bookmarks/{id} to soft delete the created bookmark.
 * 3. Assert that the response includes the same bookmark ID and a non-null deleted_at timestamp (soft delete, not remove).
 * 4. (Optional, if API allows) Attempt to fetch the bookmark again and verify its deleted_at timestamp remains, and that data is retrievable for compliance/audit trace purposes. If the API returns 404, ensure that is per specification.
 * 5. Attempt to delete the same bookmark a second time and assert an error (e.g., 404) indicating the bookmark is already deleted or does not exist.
 * 6. Attempt to delete a completely random non-existent bookmark ID, expect similar error response.
 */
export async function test_api_favoritesPersonalization_test_delete_bookmark_by_id_with_soft_delete_and_not_found_handling(connection: api.IConnection) {
  // 1. Create bookmark
  const user_id = typia.random<string & tags.Format<'uuid'>>();
  const product_id = typia.random<string & tags.Format<'uuid'>>();
  const createInput = {
    user_id,
    product_id,
    custom_folder: "Test Folder",
    tag: "testtag",
    note: "Soft delete test"
  } satisfies IFavoritesPersonalization.IBookmarkCreate;
  const bookmark = await api.functional.favoritesPersonalization.bookmarks.post(connection, { body: createInput });
  typia.assert(bookmark);
  TestValidator.equals("bookmark not deleted at creation")(bookmark.deleted_at)(null);
  TestValidator.equals("bookmark user_id")(bookmark.user_id)(user_id);
  TestValidator.equals("bookmark product_id")(bookmark.product_id)(product_id);

  // 2. Soft delete bookmark
  const deleted = await api.functional.favoritesPersonalization.bookmarks.eraseById(connection, { id: bookmark.id });
  typia.assert(deleted);
  TestValidator.equals("deleted id")(deleted.id)(bookmark.id);
  TestValidator.notEquals("deleted_at must be set")(deleted.deleted_at)(null);

  // 3. (Optional: re-fetch to assert soft deleted) - would require a GET endpoint, omitted if not available.

  // 4. Attempt to delete again -> must fail, e.g. 404
  await TestValidator.error("Deleting already soft deleted bookmark throws 404")(() =>
    api.functional.favoritesPersonalization.bookmarks.eraseById(connection, { id: bookmark.id })
