import { tags } from "typia";

import { IPage } from "./IPage";

export namespace IFavoritesPersonalization {
  /**
   * Parameters for searching and filtering personalized events within
   * FavoritesPersonalization.personalization_events.
   *
   * Used for retrieving batches of personalization event entries through
   * filtering/analytics (e.g., by event_type, user, product, model_version,
   * context, or range). Enables user experience dashboards, DSAR analytics,
   * and advanced closed-loop AI feedback workflows. Critical for
   * explainability per requirements analysis.
   */
  export type IPersonalizationEventSearchRequest = {
    /** Restricts search to events of this user (users.id FK). */
    user_id?: string & tags.Format<"uuid">;

    /** Restricts search to events originating from this recommendation. */
    recommendation_id?: string & tags.Format<"uuid">;

    /** Restricts results to personalization events for a single product. */
    product_id?: string & tags.Format<"uuid">;

    /**
     * Filter for event type (e.g. view, click, save, dismiss) in event
     * omni-taxonomy.
     */
    event_type?: string;

    /**
     * Filter by AI/ML model version associated with event for
     * explainability analytics.
     */
    model_version?: string;

    /**
     * Free-text filter for event context (device, locale, channel, etc.),
     * as stored in event context field.
     */
    context?: string;

    /** Start window for event timestamp, for range queries. */
    timestamp_from?: string & tags.Format<"date-time">;

    /** End window for event timestamp, for range queries. */
    timestamp_to?: string & tags.Format<"date-time">;

    /** Page number for pagination. */
    page?: number & tags.Type<"int32"> & tags.Minimum<1>;

    /** Results per page for batch query, default as per business logic. */
    limit?: number & tags.Type<"int32"> & tags.Minimum<1> & tags.Maximum<100>;

    /** Sort order specifier, e.g. timestamp:desc. */
    sort?: string;
  };

  /**
   * Container for paginated result set of personalization events, with paging
   * metadata.
   *
   * Primary output for advanced list/search analytics. Combines
   * evidence-grade summary, per-event data array, and full pagination
   * controls, aligning with OpenAPI and DSAR compliance/explainability
   * requirements.
   */
  export type PageIPersonalizationEvent = {
    pagination: IPage.IPagination;

    /** Personalization event records for the current page. */
    data: IFavoritesPersonalization.IPersonalizationEvent[];
  };

  /**
   * Atomic entity for a single personalization event in
   * FavoritesPersonalization.personalization_events.
   *
   * Encodes user's interaction with recommendations (e.g. view, click, save)
   * alongside AI metadata, context, linked entities, and evidence fields per
   * requirements analysis. Each field aligns to authorization/audit control
   * per GDPR/DSAR.
   *
   * Implements strict property typing for trace, evidence, and AI
   * explainability. No denormalized or computed values; always references
   * user, recommendation, product. Downstream feedback and analytics depend
   * on these entities for continuous improvement.
   */
  export type IPersonalizationEvent = {
    /**
     * Unique identifier (PK) for this personalization event.
     *
     * Set by backend evidence tracking for analytic/export.
     */
    id: string & tags.Format<"uuid">;

    /**
     * The user who triggered the event (users.id FK).
     *
     * Required for personalization/DSAR traceability.
     */
    user_id: string & tags.Format<"uuid">;

    /**
     * Originating recommendation for this event (recommendations.id FK).
     *
     * Provides AI/ML lineage/evidence trace.
     */
    recommendation_id: string & tags.Format<"uuid">;

    /**
     * Reference to product involved in event.
     *
     * Enables closed-loop feedback and explainability.
     */
    product_id: string & tags.Format<"uuid">;

    /**
     * Event type (e.g. view, click, save, dismiss) as per evidence/ML
     * taxonomy.
     *
     * Categorizes the action for analytics and feedback.
     */
    event_type: string;

    /**
     * Version of the AI model used to generate this event.
     *
     * Required for explainability, audit, and closed-loop learning.
     */
    model_version: string;

    /**
     * Contextual information (device/browser, locale, channel, or
     * additional metadata). Nullable as not all events store context.
     */
    context?: string | null;

    /** RFC3339 evidence timestamp for when the event occurred. */
    timestamp: string & tags.Format<"date-time">;
  };

  /**
   * Payload structure for creating a new personalization event entity in
   * FavoritesPersonalization.personalization_events.
   *
   * This creation shape enforces evidence, audit, and trace compliance,
   * ensuring correct linkage to user, recommendation, product, and all ML/AI
   * feedback/training flows. Reference and typing requirements are enforced
   * by schema and business logic. Context is optional, for additional
   * evidence (device, locale, channel) or null for minimal event.
   */
  export type IPersonalizationEventCreate = {
    /**
     * User performing the event (users.id FK).
     *
     * Must exist and be authorized.
     */
    user_id: string & tags.Format<"uuid">;

    /**
     * Linked recommendation entity (recommendations.id FK).
     *
     * Provides AI/ML provenance and audit feedback.
     */
    recommendation_id: string & tags.Format<"uuid">;

    /**
     * Product the event relates to (products.id FK).
     *
     * Required for analytics, feedback, and evidence logging.
     */
    product_id: string & tags.Format<"uuid">;

    /**
     * Type of event (view/click/save/dismiss/etc) per evidence/analytics
     * taxonomy.
     *
     * Required for analytics segmentation and model feedback.
     */
    event_type: string;

    /**
     * Version string of the model generating or related to this event.
     *
     * Ensures full explainability and traceability.
     */
    model_version: string;

    /**
     * Optional field capturing device, channel, locale, or relevant
     * metadata for deep explainability/evidence.
     */
    context?: string | null;
  };
}

