import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IFavoritesPersonalization } from "@ORGANIZATION/PROJECT-api/lib/structures/IFavoritesPersonalization";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test advanced retrieval of personalization events with filtering and pagination.
 *
 * This test validates the favoritesPersonalization.personalizationEvents.patch
 * endpoint's ability to correctly filter, paginate, and sort personalization events,
 * and its behavior on edge cases.
 *
 * 1. Create multiple distinct personalization events with varying properties:
 *    - Different event_type, user_id, product_id, model_version, context, timestamps.
 * 2. Retrieve page 1 with limit N (e.g., N=3) without any filters.
 *    - Validate number of results, ordering (default or by requested sort order), and page metadata.
 * 3. Filter by exact event_type (should only return correct subset).
 * 4. Filter by user_id (should only return events for that user).
 * 5. Filter by date: timestamp_from and timestamp_to (validate proper time window filtering).
 * 6. Filter with a combination of filters (e.g., event_type + model_version).
 * 7. Test sort order (e.g., timestamp desc and asc).
 * 8. Query with filters that should result in an empty list (e.g., invalid event_type).
 * 9. Confirm pagination information is consistent with filtered results (pages, records, current, limit).
 * 10. Test with invalid filter values (e.g., invalid uuid, invalid date format) and assert error response or graceful handling.
 */
export async function test_api_favoritesPersonalization_test_list_personalization_events_with_pagination_and_filtering(
  connection: api.IConnection,
) {
  // 1. Prepare multiple events covering a variety of properties to exercise all filter cases.
  const N = 7; // Generate at least enough to paginate and filter.
  const users = ArrayUtil.repeat(2)(() => typia.random<string & tags.Format<"uuid">>());
  const products = ArrayUtil.repeat(2)(() => typia.random<string & tags.Format<"uuid">>());
  const recommendations = ArrayUtil.repeat(2)(() => typia.random<string & tags.Format<"uuid">>());
  const eventTypes = ["view", "click", "save", "dismiss"];
  const modelVersions = ["v1", "v2"];
  const now = new Date();
  const timestamps = [
    new Date(now.getTime() - 5 * 24 * 60 * 60 * 1000).toISOString(), // 5 days ago
    new Date(now.getTime() - 2 * 24 * 60 * 60 * 1000).toISOString(), // 2 days ago
    now.toISOString(),
  ];
  const simulated = [] as IFavoritesPersonalization.IPersonalizationEvent[];
  for (let i = 0; i < N; ++i) {
    const evt = await api.functional.favoritesPersonalization.personalizationEvents.post(
      connection,
      {
        body: {
          user_id: RandomGenerator.pick(users),
          recommendation_id: RandomGenerator.pick(recommendations),
          product_id: RandomGenerator.pick(products),
          event_type: RandomGenerator.pick(eventTypes),
          model_version: RandomGenerator.pick(modelVersions),
          context: RandomGenerator.alphabets(5),
        },
      },
    );
    // Patch: update the event's timestamp to choose testable range
    evt.timestamp = RandomGenerator.pick(timestamps);
    simulated.push(evt);
  }

  // 2. Retrieve first page (limit 3, no filters)
  const page1 = await api.functional.favoritesPersonalization.personalizationEvents.patch(
    connection,
    { body: { page: 1, limit: 3 } },
  );
  typia.assert(page1);
  TestValidator.equals("page limit")(3)(page1.pagination.limit);
  TestValidator.equals("page current")(1)(page1.pagination.current);
  TestValidator.predicate("records <= total")(page1.data.length <= page1.pagination.records);

  // 3. Filter by event_type
  const filterType = simulated[0].event_type;
  const byType = await api.functional.favoritesPersonalization.personalizationEvents.patch(
    connection,
    { body: { event_type: filterType } },
  );
  typia.assert(byType);
  for (const e of byType.data) {
    TestValidator.equals("event_type match")(filterType)(e.event_type);
  }

  // 4. Filter by user_id
  const filterUser = simulated[0].user_id;
  const byUser = await api.functional.favoritesPersonalization.personalizationEvents.patch(
    connection,
    { body: { user_id: filterUser } },
  );
  typia.assert(byUser);
  for (const e of byUser.data) {
    TestValidator.equals("user_id match")(filterUser)(e.user_id);
  }

  // 5. Date range filtering
  const startDate = timestamps[0]; // earliest
  const endDate = timestamps[2]; // latest
  const byDate = await api.functional.favoritesPersonalization.personalizationEvents.patch(
    connection,
    { body: { timestamp_from: startDate, timestamp_to: endDate } },
  );
  typia.assert(byDate);
  for (const e of byDate.data) {
    TestValidator.predicate("timestamp >= from and <= to")(e.timestamp >= startDate && e.timestamp <= endDate);
  }

  // 6. Combination: event_type + model_version
  const combType = simulated[1].event_type;
  const combVersion = simulated[1].model_version;
  const byCombo = await api.functional.favoritesPersonalization.personalizationEvents.patch(
    connection,
    {
      body: {
        event_type: combType,
        model_version: combVersion,
      },
    },
  );
  typia.assert(byCombo);
  for (const e of byCombo.data) {
    TestValidator.equals("combo type")(combType)(e.event_type);
    TestValidator.equals("combo version")(combVersion)(e.model_version);
  }

  // 7. Sorting: timestamp desc/asc
  const sortDesc = await api.functional.favoritesPersonalization.personalizationEvents.patch(
    connection,
    {
      body: {
        sort: "timestamp:desc",
        limit: 5,
      },
    },
  );
  typia.assert(sortDesc);
  for (let i = 1; i < sortDesc.data.length; ++i) {
    TestValidator.predicate("desc order")(sortDesc.data[i - 1].timestamp >= sortDesc.data[i].timestamp);
  }
  const sortAsc = await api.functional.favoritesPersonalization.personalizationEvents.patch(
    connection,
    {
      body: {
        sort: "timestamp:asc",
        limit: 5,
      },
    },
  );
  typia.assert(sortAsc);
  for (let i = 1; i < sortAsc.data.length; ++i) {
    TestValidator.predicate("asc order")(sortAsc.data[i - 1].timestamp <= sortAsc.data[i].timestamp);
  }

  // 8. Query with filter that returns empty (invalid event_type)
  const emptyRes = await api.functional.favoritesPersonalization.personalizationEvents.patch(
    connection,
    {
      body: {
        event_type: "doesnotexist",
      },
    },
  );
  typia.assert(emptyRes);
  TestValidator.equals("empty filtered")(0)(emptyRes.data.length);

  // 9. Pagination consistency for filtered query
  const limited = await api.functional.favoritesPersonalization.personalizationEvents.patch(
    connection,
    {
      body: { limit: 2, page: 1 },
    },
  );
  typia.assert(limited);
  TestValidator.equals("limited results")(2)(limited.data.length > 2 ? 2 : limited.data.length);
  TestValidator.equals("limit")(2)(limited.pagination.limit);

  // 10. Invalid filter values
  await TestValidator.error("invalid uuid")(() =>
    api.functional.favoritesPersonalization.personalizationEvents.patch(connection, {
      body: { user_id: "invalid-uuid" },
    })
  );
  await TestValidator.error("invalid date format")(() =>
    api.functional.favoritesPersonalization.personalizationEvents.patch(connection, {
      body: { timestamp_from: "not-a-date" },
    })
  );
}

