/**
 * E2E test for fetching a personalization event by ID, including edge cases for deletion/non-existence.
 *
 * Test steps:
 * 1. Create a personalization event (dependency)
 * 2. Fetch the created event by its ID and verify all fields match expectation
 * 3. Attempt to fetch a non-existent event ID and expect 404 error
 * 4. (Assumption) If soft deletion is available: attempt to simulate a deleted event and verify it does not appear as active (or expect 404/410)
 *
 * Notes:
 * - This test covers standard fetch as well as error/edge conditions for non-existent and deleted records.
 * - Assumes deletion or at least non-active event handling exists; simulated behavior if not.
 */
export async function test_api_favoritesPersonalization_test_get_personalization_event_by_id_including_deleted(
  connection: api.IConnection,
) {
  // 1. Create event for testing
  const createInput: IFavoritesPersonalization.IPersonalizationEventCreate = {
    user_id: typia.random<string & tags.Format<"uuid">>(),
    recommendation_id: typia.random<string & tags.Format<"uuid">>(),
    product_id: typia.random<string & tags.Format<"uuid">>(),
    event_type: "view",
    model_version: "v1-test",
    context: "unit-test-e2e"
  };
  const created = await api.functional.favoritesPersonalization.personalizationEvents.post(connection, { body: createInput });
  typia.assert(created);
  // 2. Fetch event by valid ID
  const fetched = await api.functional.favoritesPersonalization.personalizationEvents.getById(connection, { id: created.id });
  typia.assert(fetched);
  // All fields should match (excluding generated fields such as timestamp, which we can check for correct format)
  TestValidator.equals("fetched.id")(created.id)(fetched.id);
  TestValidator.equals("fetched.user_id")(created.user_id)(fetched.user_id);
  TestValidator.equals("fetched.recommendation_id")(created.recommendation_id)(fetched.recommendation_id);
  TestValidator.equals("fetched.product_id")(created.product_id)(fetched.product_id);
  TestValidator.equals("fetched.event_type")(created.event_type)(fetched.event_type);
  TestValidator.equals("fetched.model_version")(created.model_version)(fetched.model_version);
  TestValidator.equals("fetched.context")(created.context)(fetched.context);
  // Timestamp should be recent and RFC3339
  TestValidator.predicate("fetched.timestamp RFC3339")(typeof fetched.timestamp === "string" && fetched.timestamp.includes("T"));
  // 3. Attempt to fetch with non-existent ID
