import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IFavoritesPersonalization } from "@ORGANIZATION/PROJECT-api/lib/structures/IFavoritesPersonalization";
import type { IPersonalizationEvent } from "@ORGANIZATION/PROJECT-api/lib/structures/IPersonalizationEvent";

/**
 * E2E test for updating a personalization event by ID (PUT /favoritesPersonalization/personalizationEvents/{id}), including business logic, error handling, and field restriction enforcement.
 *
 * Business context:
 * - Personalization events track user interactions with recommendations for AI feedback, audit, analytics, and compliance.
 * - Updating a record should be permitted only for mutable fields subject to audit/compliance rules; some fields may be immutable or restricted.
 * - Must handle attempts to update non-existent records with the correct error.
 * - Attempts to update restricted fields (e.g., user_id) should result in validation or authorization error.
 *
 * Test Workflow:
 * 1. Create a valid personalization event (DB setup via POST dependency).
 * 2. Update the event's allowed fields (event_type, model_version, context, timestamp, product_id, recommendation_id) and validate update succeeds; validate response fields and type.
 * 3. (If available in system) Confirm an audit/history record was created for the update (requires a follow-up GET if API provides).
 * 4. Attempt to update a non-existent event (random UUID) and validate correct error response (e.g., 404 Not Found).
 * 5. Attempt to update restricted/immutable fields (simulate changes to user_id) and validate that the API enforces immutability/reference restrictions (should return validation or error).
 */
export async function test_api_favoritesPersonalization_test_update_personalization_event_by_id_with_error_and_permission_handling(connection: api.IConnection) {
  // Step 1: Create a valid personalization event for update tests
  const eventCreate: IFavoritesPersonalization.IPersonalizationEventCreate = {
    user_id: typia.random<string & tags.Format<"uuid">>(),
    recommendation_id: typia.random<string & tags.Format<"uuid">>(),
    product_id: typia.random<string & tags.Format<"uuid">>(),
    event_type: "view",
    model_version: "v1.0.0",
    context: null,
  };
  const created = await api.functional.favoritesPersonalization.personalizationEvents.post(connection, { body: eventCreate });
  typia.assert(created);

  // Step 2: Update allowed fields (event_type, model_version, context, timestamp, product_id, recommendation_id)
  const updateBody: IPersonalizationEvent.IUpdate = {
    event_type: "click",
    model_version: "v1.1.0",
    context: "updated-context",
    timestamp: new Date().toISOString(),
    product_id: created.product_id,
    recommendation_id: created.recommendation_id,
  };
  const updated = await api.functional.favoritesPersonalization.personalizationEvents.putById(connection, { id: created.id, body: updateBody });
  typia.assert(updated);
  TestValidator.equals("event_type updated")("click")(updated.event_type);
  TestValidator.equals("model_version updated")("v1.1.0")(updated.model_version);
  TestValidator.equals("context updated")("updated-context")(updated.context);

  // (Optional/Audit) If audit/history endpoints are exposed, add a GET here to confirm audit, else skip.

  // Step 3: Attempt update for a non-existent ID
  await TestValidator.error("update non-existent event should error")(async () => {
    await api.functional.favoritesPersonalization.personalizationEvents.putById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
      body: updateBody,
    });
  });

  // Step 4: Attempt to update an immutable/restricted field (simulate user_id change; user_id is not allowed in IUpdate)
  // Since user_id is not in the IUpdate schema, we cannot send it. But for demonstration, if restricted fields existed in update body, we'd validate they are rejected.
  // This step is here to demonstrate that TypeScript enforces property omission, and the server will reject payloads with extra fields.
}

