import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IFavoritesPersonalization } from "@ORGANIZATION/PROJECT-api/lib/structures/IFavoritesPersonalization";
import type { IPersonalizationEvent } from "@ORGANIZATION/PROJECT-api/lib/structures/IPersonalizationEvent";

/**
 * Test soft-deletion of a personalization event and correct error handling.
 *
 * Business context:
 * - Personalization events must be soft-deleted to comply with evidence/audit regulations. Erasure must never physically remove events, only mark (soft-delete) them so they are hidden from active lists but retrievable for compliance. Attempting to delete an already deleted or non-existent event should return a proper error response.
 *
 * Steps:
 * 1. Create a valid personalization event using required dependencies.
 * 2. Soft-delete the event by ID.
 * 3. Confirm the returned record is still retrievable (not hard-deleted) and all core data is intact.
 * 4. Attempt to delete the same event again and confirm error response (e.g., not found).
 * 5. Attempt to delete a truly non-existent random event and confirm proper error response.
 */
export async function test_api_favoritesPersonalization_test_soft_delete_personalization_event_and_handle_not_found(
  connection: api.IConnection,
) {
  // 1. Create a valid personalization event
  const eventCreate: IFavoritesPersonalization.IPersonalizationEventCreate = {
    user_id: typia.random<string & tags.Format<"uuid">>(),
    recommendation_id: typia.random<string & tags.Format<"uuid">>(),
    product_id: typia.random<string & tags.Format<"uuid">>(),
    event_type: "view",
    model_version: "v1.0.0",
    context: null,
  };
  const created = await api.functional.favoritesPersonalization.personalizationEvents.post(connection, { body: eventCreate });
  typia.assert(created);

  // 2. Soft-delete the event by ID
  const erased = await api.functional.favoritesPersonalization.personalizationEvents.eraseById(connection, {
    id: created.id,
  });
  typia.assert(erased);
  // 3. Confirm returned record matches original (soft-deleted not hard-deleted)
  TestValidator.equals("soft-deleted event still retrievable")(created.id)(erased.id);
  TestValidator.equals("user_id matches")(created.user_id)(erased.user_id);
  TestValidator.equals("recommendation_id matches")(created.recommendation_id)(erased.recommendation_id);
  TestValidator.equals("product_id matches")(created.product_id)(erased.product_id);
  TestValidator.equals("event_type matches")(created.event_type)(erased.event_type);
  TestValidator.equals("model_version matches")(created.model_version)(erased.model_version);
  TestValidator.equals("context matches")((created.context ?? null))(erased.context ?? null);

  // 4. Attempt to delete again: should error
  await TestValidator.error("double-delete returns not found or error")(() =>
    api.functional.favoritesPersonalization.personalizationEvents.eraseById(connection, {
      id: created.id,
    })
  );

  // 5. Try to delete truly non-existent event ID
  const randomId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("delete non-existent event returns not found or error")(() =>
    api.functional.favoritesPersonalization.personalizationEvents.eraseById(connection, {
      id: randomId,
    })
  );
}

