  // 1. Data population: create 12 diverse recommendations
  const userIds = ArrayUtil.repeat(3)(() => typia.random<string & tags.Format<"uuid">>());
  const productIds = ArrayUtil.repeat(3)(() => typia.random<string & tags.Format<"uuid">>());
  const modelIds = [RandomGenerator.alphabets(6), RandomGenerator.alphabets(7)];
  const modelVersions = ["1.0.0", "2.1.5", RandomGenerator.alphabets(5)];
  const rationaleSnippets = ["AI suggest", "upgraded", "personalized", null];
  const timeBase = new Date();
  const recommendations: IRecommendation[] = [];
  for (let i = 0; i < 12; ++i) {
    const rec = await api.functional.favoritesPersonalization.recommendations.post(
      connection,
      {
        body: {
          user_id: RandomGenerator.pick(userIds),
          product_id: RandomGenerator.pick(productIds),
          model_id: RandomGenerator.pick(modelIds),
          model_version: RandomGenerator.pick(modelVersions),
          rationale: RandomGenerator.pick(rationaleSnippets),
          recommendation_time: new Date(timeBase.getTime() - 1000 * 60 * 60 * 24 * i).toISOString(),
        } satisfies IRecommendation.ICreate,
      },
    );
    typia.assert(rec);
    recommendations.push(rec);
  }

  // Helper: get a random record for filter sanity checks
  const rec0 = recommendations[5];

  // 2. Test: filter by user_id
  {
    const output = await api.functional.favoritesPersonalization.recommendations.patch(connection, {
      body: { user_id: rec0.user_id } satisfies IRecommendation.IRequest,
    });
    typia.assert(output);
    TestValidator.predicate("all user_ids match")(output.data.every(x => x.user_id === rec0.user_id));
  }

  // 3. Filter by product_id
  {
    const output = await api.functional.favoritesPersonalization.recommendations.patch(connection, {
      body: { product_id: rec0.product_id } satisfies IRecommendation.IRequest,
    });
    typia.assert(output);
    TestValidator.predicate("all product_ids match")(output.data.every(x => x.product_id === rec0.product_id));
  }

  // 4. Filter by model_id
  {
    const output = await api.functional.favoritesPersonalization.recommendations.patch(connection, {
      body: { model_id: rec0.model_id } satisfies IRecommendation.IRequest,
    });
    typia.assert(output);
    TestValidator.predicate("all model_ids match")(output.data.every(x => x.model_id === rec0.model_id));
  }

  // 5. Filter by model_version
  {
    const output = await api.functional.favoritesPersonalization.recommendations.patch(connection, {
      body: { model_version: rec0.model_version } satisfies IRecommendation.IRequest,
    });
    typia.assert(output);
    TestValidator.predicate("all model_versions match")(output.data.every(x => x.model_version === rec0.model_version));
  }

  // 6. Filter by rationale (full text)
  {
    const body: IRecommendation.IRequest = rec0.rationale ? { rationale: rec0.rationale } : { rationale: "AI suggest" };
    const output = await api.functional.favoritesPersonalization.recommendations.patch(connection, {
      body,
    });
    typia.assert(output);
    if (body.rationale !== null)
      TestValidator.predicate("rationale contains")(output.data.every(x => x.rationale?.includes(body.rationale!)));
  }

  // 7. Date range filters: from, to, both
  {
    const fromTime = recommendations[8].recommendation_time;
    const toTime = recommendations[2].recommendation_time;
    // From only
    {
      const output = await api.functional.favoritesPersonalization.recommendations.patch(connection, {
        body: { recommendation_time_from: fromTime } satisfies IRecommendation.IRequest,
      });
      typia.assert(output);
      TestValidator.predicate("all recommendations after from")(
        output.data.every(x => x.recommendation_time >= fromTime),
      );
    }
    // To only
    {
      const output = await api.functional.favoritesPersonalization.recommendations.patch(connection, {
        body: { recommendation_time_to: toTime } satisfies IRecommendation.IRequest,
      });
      typia.assert(output);
      TestValidator.predicate("all recommendations before to")(
        output.data.every(x => x.recommendation_time <= toTime),
      );
    }
    // Both
    {
      const output = await api.functional.favoritesPersonalization.recommendations.patch(connection, {
        body: { recommendation_time_from: fromTime, recommendation_time_to: toTime } satisfies IRecommendation.IRequest,
      });
      typia.assert(output);
      TestValidator.predicate("all recommendations in range")(
        output.data.every(x => x.recommendation_time >= fromTime && x.recommendation_time <= toTime),
      );
    }
  }

  // 8. Pagination: limit, offset, boundaries
  {
    const output = await api.functional.favoritesPersonalization.recommendations.patch(connection, {
      body: { limit: 4, offset: 0 } satisfies IRecommendation.IRequest,
    });
    typia.assert(output);
    TestValidator.equals("limit count")(output.data.length)(Math.min(4, recommendations.length));
    // Check next page
    const output2 = await api.functional.favoritesPersonalization.recommendations.patch(connection, {
      body: { limit: 4, offset: 4 } satisfies IRecommendation.IRequest,
    });
    typia.assert(output2);
    TestValidator.equals("next offset count")(output2.data.length)(Math.min(4, recommendations.length - 4));
    // Boundary (offset at last page)
    const output3 = await api.functional.favoritesPersonalization.recommendations.patch(connection, {
      body: { limit: 4, offset: 20 } satisfies IRecommendation.IRequest,
    });
    typia.assert(output3);
    TestValidator.equals("boundary empty")(output3.data.length)(0);
  }

  // 9. Combination filtering (user + product + model)
  {
    const output = await api.functional.favoritesPersonalization.recommendations.patch(connection, {
      body: {
        user_id: rec0.user_id,
        product_id: rec0.product_id,
        model_id: rec0.model_id,
        model_version: rec0.model_version,
      } satisfies IRecommendation.IRequest,
    });
    typia.assert(output);
    TestValidator.predicate("AND combination")(output.data.every(x =>
      x.user_id === rec0.user_id && x.product_id === rec0.product_id && x.model_id === rec0.model_id && x.model_version === rec0.model_version
    ));
  }

  // 10. No-match scenario (impossible UUID, rationale)
  {
    // Nonsense uuid
    const output = await api.functional.favoritesPersonalization.recommendations.patch(connection, {
      body: { user_id: "00000000-0000-0000-0000-000000000000" } satisfies IRecommendation.IRequest,
    });
    typia.assert(output);
    TestValidator.equals("no match uuid")(output.data.length)(0);

    // Unmatched rationale
    const output2 = await api.functional.favoritesPersonalization.recommendations.patch(connection, {
      body: { rationale: "not-a-match-uniq-str" } satisfies IRecommendation.IRequest,
    });
    typia.assert(output2);
    TestValidator.equals("no match rationale")(output2.data.length)(0);
  }

  // 11. Invalid input errors (invalid uuid, datetime, negative offset, excessive limit)
  {
    // Invalid UUID
    await TestValidator.error("invalid uuid fails")(async () => {
      await api.functional.favoritesPersonalization.recommendations.patch(connection, { body: { user_id: "bad-uuid" } as any });
    });
    // Invalid date
    await TestValidator.error("invalid date fails")(async () => {
      await api.functional.favoritesPersonalization.recommendations.patch(connection, { body: { recommendation_time_from: "not-a-date" } as any });
    });
    // Negative offset
    await TestValidator.error("negative offset fails")(async () => {
      await api.functional.favoritesPersonalization.recommendations.patch(connection, { body: { offset: -1 } as any });
    });
    // Excessively large limit
    await TestValidator.error("huge limit fails")(async () => {
      await api.functional.favoritesPersonalization.recommendations.patch(connection, { body: { limit: 1000000 } as any });
    });
  }
}

