import { tags } from "typia";

/**
 * Auditable record of an AI/ML-powered recommendation delivered to a user.
 *
 * Supports end-to-end traceability, feedback analytics, compliance, and
 * explainability. Prisma recommendations table entity.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IRecommendation = {
  /** Unique recommendation record ID as stored in recommendations.id. */
  id: string & tags.Format<"uuid">;

  /**
   * UUID for the user who received the recommendation.
   *
   * FK to users.id in Prisma, essential for evidence and explainability
   * workflows.
   */
  user_id: string & tags.Format<"uuid">;

  /** UUID for target product recommended. */
  product_id: string & tags.Format<"uuid">;

  /** AI model identifier generating the recommendation. */
  model_id: string;

  /** AI/ML model version for the explainability pipeline. */
  model_version: string;

  /**
   * Optional rationale for the recommendation, for auditing, explainability,
   * and continuous learning.
   *
   * May include weightings, decision path, or other explainable output per
   * recommendations.rationale field.
   */
  rationale?: string | null;

  /** When the recommendation was delivered (ISO8601 timestamp). */
  recommendation_time: string & tags.Format<"date-time">;
};
export namespace IRecommendation {
  /**
   * Creation schema for a new recommendation record.
   *
   * Conforms to AI-native explainability and compliance requirements for
   * delivering evidence-grade recommendation entries.
   *
   * Prisma: recommendations table.
   */
  export type ICreate = {
    /**
     * UUID of the user for whom the recommendation is made. Required.
     *
     * References users.id; enforcement of FK constraint and analytic
     * traceability.
     */
    user_id: string & tags.Format<"uuid">;

    /**
     * UUID of the recommended product. Required.
     *
     * References products.id; analytics and evidence need atomic linkage.
     */
    product_id: string & tags.Format<"uuid">;

    /**
     * String AI model identifier (required).
     *
     * Used for machine explainability, evidence preservation, and
     * regulatory trace.
     */
    model_id: string;

    /**
     * String version of AI/ML model issuing recommendation. Required for
     * audit, explainability, and continuous learning pipeline.
     */
    model_version: string;

    /**
     * Optional explainability rationale for this recommendation.
     *
     * Enables downstream AI regulatory, feedback, and analytics flows.
     */
    rationale?: string | null;

    /**
     * Timestamp when recommendation was delivered (ISO8601). Required.
     *
     * Needed for continuous feedback, time-based analytics, and evidence
     * preservation.
     */
    recommendation_time: string & tags.Format<"date-time">;
  };
}

