  TestValidator.equals("user_id")(created.user_id)(fetched.user_id);
  TestValidator.equals("product_id")(created.product_id)(fetched.product_id);
  TestValidator.equals("model_id")(created.model_id)(fetched.model_id);
  TestValidator.equals("model_version")(created.model_version)(fetched.model_version);
  TestValidator.equals("rationale")(created.rationale)(fetched.rationale);
  TestValidator.equals("recommendation_time")(created.recommendation_time)(fetched.recommendation_time);

  // 3. Try to fetch a non-existent recommendation (random UUID)
  const notFoundId = typia.random<string & tags.Format<"uuid">>();
  TestValidator.error("not-found recommendation throws error")(async () => {
    await api.functional.favoritesPersonalization.recommendations.getById(
      connection,
      { id: notFoundId },
