import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IRecommendation } from "@ORGANIZATION/PROJECT-api/lib/structures/IRecommendation";

/**
 * Comprehensive E2E test for creating recommendations in the FavoritesPersonalization domain.
 *
 * This scenario validates the creation of a new recommendation with all required and optional fields, as well as the API's behavior in edge cases such as duplicate entries, missing required field submissions, and invalid (malformed) data. The business expectation is that the system enforces validation (e.g., for required fields and correct formats) and uniqueness (e.g., for duplicate recommendations) and returns appropriate error messages or status codes.
 *
 * Steps:
 * 1. Create a well-formed, complete recommendation (all required and optional fields supplied).
 * 2. Attempt to create a duplicate recommendation with the same user_id, product_id, recommendation_time (expect failure due to unique constraint).
 * 3. Try to create recommendations missing each required field in turn (expect validation error for each case).
 * 4. Submit with obviously invalid data (e.g., malformed uuid, invalid date-time) and verify system rejects them.
 * 5. Try creating with only required fields to verify optional field null/omission handling.
 */
export async function test_api_favoritesPersonalization_test_create_recommendation_with_full_and_partial_fields(connection: api.IConnection) {
  // 1. Create a new recommendation with all fields
  const recommendationInput: IRecommendation.ICreate = {
    user_id: typia.random<string & tags.Format<"uuid">>(),
    product_id: typia.random<string & tags.Format<"uuid">>(),
    model_id: RandomGenerator.alphabets(8),
    model_version: RandomGenerator.alphabets(5),
    rationale: RandomGenerator.content()()(),
    recommendation_time: new Date().toISOString(),
  };
  const created = await api.functional.favoritesPersonalization.recommendations.post(connection, { body: recommendationInput });
  typia.assert(created);
  TestValidator.equals("user_id matches")(recommendationInput.user_id)(created.user_id);
  TestValidator.equals("product_id matches")(recommendationInput.product_id)(created.product_id);
  TestValidator.equals("model_id matches")(recommendationInput.model_id)(created.model_id);
  TestValidator.equals("model_version matches")(recommendationInput.model_version)(created.model_version);
  TestValidator.equals("rationale matches")(recommendationInput.rationale)(created.rationale);
  TestValidator.equals("recommendation_time matches")(recommendationInput.recommendation_time)(created.recommendation_time);

  // 2. Attempt to create duplicate recommendation (expect error)
  await TestValidator.error("duplicate recommendation")(async () => {
    await api.functional.favoritesPersonalization.recommendations.post(connection, { body: recommendationInput });
  });

  // 3. Missing required fields (one by one)
  const requiredFields = ["user_id", "product_id", "model_id", "model_version", "recommendation_time"];
  for (const field of requiredFields) {
    // NOTE: Because TypeScript requires type-safe objects, we must only omit the field at runtime with a valid structure.
    // Skip compilation-error scenarios. Instead, purposely provide empty string or invalid value to trigger runtime validation if possible.
    const badInput = { ...recommendationInput, [field]: "" };
    if (field === "recommendation_time") badInput[field] = "not-a-date";
    await TestValidator.error(`missing or bad required field: ${field}`)(async () => {
      await api.functional.favoritesPersonalization.recommendations.post(connection, { body: badInput });
    });
  }

  // 4. Invalid UUID and date-time
  const malformedInput = {
    ...recommendationInput,
    user_id: "not-a-uuid",
    product_id: "invalid-uuid",
    recommendation_time: "not-a-datetime",
  };
  await TestValidator.error("invalid uuid and date-time")(async () => {
    await api.functional.favoritesPersonalization.recommendations.post(connection, { body: malformedInput });
  });

  // 5. Required fields only, rationale omitted
  const requiredOnly: IRecommendation.ICreate = {
    user_id: typia.random<string & tags.Format<"uuid">>(),
    product_id: typia.random<string & tags.Format<"uuid">>(),
    model_id: RandomGenerator.alphabets(10),
    model_version: RandomGenerator.alphabets(6),
    recommendation_time: new Date().toISOString(),
  };
  const created2 = await api.functional.favoritesPersonalization.recommendations.post(connection, { body: requiredOnly });
  typia.assert(created2);
  TestValidator.equals("user_id matches")(requiredOnly.user_id)(created2.user_id);
  TestValidator.equals("rationale null when omitted")(null)(created2.rationale);
}

