import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IRecommendation } from "@ORGANIZATION/PROJECT-api/lib/structures/IRecommendation";

/**
 * E2E test for updating a recommendation record by ID with valid and invalid scenarios.
 *
 * This test covers the following business scenarios:
 *
 * 1. Creation of a recommendation (dependency) to update.
 * 2. Update all allowed fields (model_version, rationale, recommendation_time) and verify the changes are persisted.
 * 3. Attempt to update a recommendation using a non-existent ID and confirm proper error handling.
 * 4. Attempt to change immutable/system fields (id, user_id, product_id, model_id) and verify such updates are not permitted (should be rejected).
 *
 * Steps:
 * 1. Create a recommendation (POST /favoritesPersonalization/recommendations).
 * 2. Update all mutable fields using PUT /favoritesPersonalization/recommendations/{id}, verify updated values.
 * 3. Attempt to update using a random (non-existent) ID, expect error.
 * 4. Attempt to change immutable/system fields (via body), ensure updates are ignored or rejected (should error or not change those fields).
 */
export async function test_api_favoritesPersonalization_test_update_recommendation_by_id_with_valid_and_invalid_scenarios(connection: api.IConnection) {
  // 1. Create recommendation
  const created = await api.functional.favoritesPersonalization.recommendations.post(connection, {
    body: {
      user_id: typia.random<string & tags.Format<"uuid">>(),
      product_id: typia.random<string & tags.Format<"uuid">>(),
      model_id: RandomGenerator.alphabets(10),
      model_version: RandomGenerator.alphabets(6),
      rationale: RandomGenerator.paragraph()(),
      recommendation_time: new Date().toISOString()
    }
  });
  typia.assert(created);

  // 2. Update allowed fields
  const updateBody = {
    model_version: RandomGenerator.alphabets(8),
    rationale: RandomGenerator.paragraph()(),
    recommendation_time: new Date(Date.now() + 100000).toISOString()
  } satisfies IRecommendation.IUpdate;

  const updated = await api.functional.favoritesPersonalization.recommendations.putById(connection, {
    id: created.id,
    body: updateBody
  });
  typia.assert(updated);
  TestValidator.equals("model_version updated")(updateBody.model_version)(updated.model_version);
  TestValidator.equals("rationale updated")(updateBody.rationale)(updated.rationale);
  TestValidator.equals("recommendation_time updated")(updateBody.recommendation_time)(updated.recommendation_time);

  // 3. Update using a non-existent ID
  await TestValidator.error("update fails for non-existent ID")(() =>
    api.functional.favoritesPersonalization.recommendations.putById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
      body: updateBody
    })
  );

  // 4. Attempt to change immutable/system fields (should be ignored or error)
  const illegalBody: any = {
    ...updateBody,
    id: typia.random<string & tags.Format<"uuid">>(),
    user_id: typia.random<string & tags.Format<"uuid">>(),
    product_id: typia.random<string & tags.Format<"uuid">>(),
    model_id: RandomGenerator.alphabets(12)
  };

  await TestValidator.error("update fails if immutable/system fields are included")(() =>
    api.functional.favoritesPersonalization.recommendations.putById(connection, {
      id: created.id,
      body: illegalBody
    })
  );
}

