 * 5. (Planned) - Attempt delete on a non-existent recommendation (should return appropriate error)
 * 6. (Planned) - Ensure audit/history is preserved for compliance (if an endpoint/audit-log is available)
 *
 * Due to limited endpoint/SDK disclosure, only the DELETE mechanics using eraseById can be shown here.
 */
export async function test_api_favoritesPersonalization_test_soft_delete_recommendation_by_id_and_handle_redundant_deletion(
  connection: api.IConnection,
) {
  // 1. Create a recommendation to be deleted
  const created = await api.functional.favoritesPersonalization.recommendations.post(connection, {
