import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPersonalizationAudit } from "@ORGANIZATION/PROJECT-api/lib/structures/IPersonalizationAudit";
import type { IPageIPersonalizationAudit } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPersonalizationAudit";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * E2E test for advanced search and pagination of personalization audit records with robust filter/edge case coverage.
 *
 * This test ensures all aspects of the audit listing endpoint:
 *   - Diverse records (multiple users, actions, timestamps, related entities)
 *   - All filter fields (user, favorite, action type, etc) work and return correct results
 *   - Pagination logic is correct for small, large, boundary cases
 *   - Empty/invalid filter scenarios handled gracefully (never throw, always correct metadata)
 *
 * Steps:
 * 1. Create ~18 diverse audit logs (3 users * 3 action_types * 2-3 timestamps each)
 * 2. Search all (no filter); validate count (>= 18), pagination meta, data integrity
 * 3. Filter by user_id: only that user's records returned
 * 4. Filter by invalid/random user_id: empty, meta correct
 * 5. Filter by action_type: only matching actions, meta/data correct
 * 6. Timestamp range filter: records within window only
 * 7. Pagination small limit (limit: 5): check pages, iteratively fetch all; validate page mechanics
 * 8. Last page (offset>max): empty, meta correct
 * 9. Invalid filter (junk action_type): empty, no error
 * 10. High limit (e.g. 100+): system caps output, meta reflects cap, no crash
 */
export async function test_api_favoritesPersonalization_test_list_personalization_audits_with_filter_pagination_and_edge_cases(connection: api.IConnection) {
  // 1. Prepare diversified audit data
  const users = ArrayUtil.repeat(3)(() => typia.random<string & tags.Format<"uuid">>());
  const action_types = ["ADD_FAVORITE", "REMOVE_FAVORITE", "ACTIONS"];
  const timestamps: (string & tags.Format<"date-time">)[] = [
    new Date(Date.now() - 3 * 24 * 60 * 60 * 1000).toISOString() as string & tags.Format<"date-time">, // 3 days ago
    new Date(Date.now() - 1 * 24 * 60 * 60 * 1000).toISOString() as string & tags.Format<"date-time">, // 1 day ago
    new Date(Date.now()).toISOString() as string & tags.Format<"date-time">,
  ];
  const all_audits: IPersonalizationAudit[] = [];
  for (const user_id of users) {
    for (const action_type of action_types) {
      for (const timestamp of timestamps) {
        const created = await api.functional.favoritesPersonalization.personalizationAudits.post(connection, {
          body: {
            user_id,
            action_type,
            evidence_hash: RandomGenerator.alphaNumeric(32),
            timestamp,
            favorite_id: Math.random() < 0.5
              ? (typia.random<string & tags.Format<"uuid">>() as string & tags.Format<"uuid">)
              : null,
            bookmark_id: null,
            recommendation_id: null,
            personalization_event_id: null,
          } satisfies IPersonalizationAudit.ICreate,
        });
        typia.assert(created);
        all_audits.push(created);
      }
    }
  }

  // 2. List all audits (no filters)
  let res = await api.functional.favoritesPersonalization.personalizationAudits.patch(connection, {
    body: {},
  });
  typia.assert(res);
  TestValidator.predicate("at least 18 audits exist")(res.pagination.records >= 18);
  TestValidator.equals("all audits count matches page data + remaining")(
    res.pagination.records >= res.data.length,
  );
  res.data.forEach(typia.assert);

  // 3. Filter by user_id
  const selected_user = users[0];
  res = await api.functional.favoritesPersonalization.personalizationAudits.patch(connection, {
    body: { user_id: selected_user },
  });
  typia.assert(res);
  res.data.forEach((audit) => {
    typia.assert(audit);
    TestValidator.equals("user_id matches filter")(selected_user)(audit.user_id);
  });

  // 4. Filter by invalid user_id (should be empty)
  const random_user = typia.random<string & tags.Format<"uuid">>();
  res = await api.functional.favoritesPersonalization.personalizationAudits.patch(connection, {
    body: { user_id: random_user },
  });
  typia.assert(res);
  TestValidator.equals("empty for unknown user")(0)(res.pagination.records);
  TestValidator.equals("no data for unknown user")(0)(res.data.length);

  // 5. Filter by action_type
  const filter_action = action_types[1];
  res = await api.functional.favoritesPersonalization.personalizationAudits.patch(connection, {
    body: { action_type: filter_action },
  });
  typia.assert(res);
  res.data.forEach((audit) => {
    typia.assert(audit);
    TestValidator.equals("action_type matches filter")(filter_action)(audit.action_type);
  });

  // 6. Timestamp window (between middle and now)
  const start_time = timestamps[1];
  const end_time = timestamps[2];
  res = await api.functional.favoritesPersonalization.personalizationAudits.patch(connection, {
    body: {
      timestamp_from: start_time,
      timestamp_to: end_time,
    },
  });
  typia.assert(res);
  res.data.forEach((audit) => {
    typia.assert(audit);
    TestValidator.predicate("within date range")(
      audit.timestamp >= start_time && audit.timestamp <= end_time,
    );
  });

  // 7. Pagination (limit = 5)
  res = await api.functional.favoritesPersonalization.personalizationAudits.patch(connection, {
    body: { limit: 5 },
  });
  typia.assert(res);
  TestValidator.equals("page size == 5")(5)(res.data.length);
  TestValidator.equals("limit meta == 5")(5)(res.pagination.limit);
  let fetched = [...res.data];
  let page_count = 1;
  let offset = 5;
  while (res.data.length === 5 && fetched.length < res.pagination.records) {
    res = await api.functional.favoritesPersonalization.personalizationAudits.patch(connection, {
      body: { limit: 5, offset },
    });
    typia.assert(res);
    fetched = [...fetched, ...res.data];
    offset += 5;
    page_count += 1;
  }
  TestValidator.equals("all records paginated fetched")(res.pagination.records)(fetched.length);

  // 8. Paginate out of bounds (offset > available)
  res = await api.functional.favoritesPersonalization.personalizationAudits.patch(connection, {
    body: { limit: 5, offset: 9999 },
  });
  typia.assert(res);
  TestValidator.equals("out-of-range offset yields empty")(
    0,
  )(res.data.length);

  // 9. Invalid action_type (junk value)
  res = await api.functional.favoritesPersonalization.personalizationAudits.patch(connection, {
    body: { action_type: "NON_EXISTENT_ACTION" },
  });
  typia.assert(res);
  TestValidator.equals("invalid action_type - empty")(
    0,
  )(res.data.length);

  // 10. Limit above cap (e.g. 200): should not return more than allowed (system cap is 100)
  res = await api.functional.favoritesPersonalization.personalizationAudits.patch(connection, {
    body: { limit: 200 },
  });
  typia.assert(res);
  TestValidator.predicate("limit cannot exceed max allowed")(
    res.data.length <= 100,
  );
}

