import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPersonalizationAudit } from "@ORGANIZATION/PROJECT-api/lib/structures/IPersonalizationAudit";

/**
 * Validate retrieval and error handling for personalization audit records.
 *
 * This test covers both normal (existing) and exceptional (null, non-existent, deleted) retrieval cases.
 *
 * Steps:
 * 1. Create a new personalization audit using POST /favoritesPersonalization/personalizationAudits.
 * 2. Retrieve that audit by ID via GET /favoritesPersonalization/personalizationAudits/{id}, and validate all returned fields' integrity.
 * 3. Attempt to fetch a non-existent audit record by a random UUID, validate a 404 or error response.
 * 4. (If deletion is supported) Delete the audit record and confirm GET returns not found or proper error. Optionally, confirm audit data is preserved for evidence/audit trail if business rules require such retention after deletion.
 *
 * Validates: field-level accuracy, error handling for missing/deleted, and immutability of audit records as per compliance.
 */
export async function test_api_favoritesPersonalization_test_get_personalization_audit_by_id_with_null_and_deleted_handling(connection: api.IConnection) {
  // 1. Create a personalization audit record
  const auditCreate: IPersonalizationAudit.ICreate = {
    user_id: typia.random<string & tags.Format<"uuid">>(),
    action_type: "ACTIONS",
    evidence_hash: RandomGenerator.alphabets(32),
    timestamp: new Date().toISOString(),
  };
  const createdAudit: IPersonalizationAudit = await api.functional.favoritesPersonalization.personalizationAudits.post(connection, { body: auditCreate });
  typia.assert(createdAudit);

  // 2. Retrieve audit by ID and validate all returned fields match creation
  const fetched: IPersonalizationAudit = await api.functional.favoritesPersonalization.personalizationAudits.getById(connection, { id: createdAudit.id });
  typia.assert(fetched);
  TestValidator.equals("id matches")(createdAudit.id)(fetched.id);
  TestValidator.equals("user_id matches")(auditCreate.user_id)(fetched.user_id);
  TestValidator.equals("action_type matches")(auditCreate.action_type)(fetched.action_type);
  TestValidator.equals("evidence_hash matches")(auditCreate.evidence_hash)(fetched.evidence_hash);
  TestValidator.equals("timestamp matches")(auditCreate.timestamp)(fetched.timestamp);

  // 3. Attempt to retrieve a non-existent record (random UUID) - expect not found error
  const randomId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("not found for missing audit")(() =>
    api.functional.favoritesPersonalization.personalizationAudits.getById(connection, { id: randomId })
  );

  // 4. (Optional if supported) Test deletion and access to audit afterwards if API offers DELETE endpoint.
  // (Not implemented here as no DELETE endpoint was provided in input.)
}

