import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPersonalizationAudit } from "@ORGANIZATION/PROJECT-api/lib/structures/IPersonalizationAudit";

/**
 * E2E test for creating a personalization audit with comprehensive field coverage and validation
 *
 * Business Context:
 * - Audits are cryptographically persistent records capturing a user or system action for personalization compliance or forensic review. Creating an audit is a privileged/controlled action; all fields (user, action_type, evidence_hash, timestamp, and all potential entity references) must be validated.
 * - The API must enforce type, format and business rule validations on creation: required fields, format/uuid checks, valid timestamps, and business constraints such as non-existing/conflicting duplicate entries.
 *
 * Steps:
 * 1. Happy path: Create an audit record with all fields present and valid, assert response fields and serve-side persistence
 * 2. Validation error: Omit required fields (should fail with actionable validation error)
 * 3. Validation error: Use invalid uuid or date-time format for fields (should fail)
 * 4. Business logic error: Attempt creating a duplicate/conflicting record (should receive a business error, if system supports such logical uniqueness)
 * 5. Ensure error messages and HTTP codes are correct for each failure mode
 */
export async function test_api_favoritesPersonalization_personalizationAudits_post(connection: api.IConnection) {
  // 1. Create with all fields valid
  const validBody: IPersonalizationAudit.ICreate = {
    user_id: typia.random<string & tags.Format<'uuid'>>(),
    favorite_id: typia.random<string & tags.Format<'uuid'>>(),
    bookmark_id: typia.random<string & tags.Format<'uuid'>>(),
    recommendation_id: typia.random<string & tags.Format<'uuid'>>(),
    personalization_event_id: typia.random<string & tags.Format<'uuid'>>(),
    action_type: RandomGenerator.alphabets(10),
    evidence_hash: RandomGenerator.alphaNumeric(64),
    timestamp: new Date().toISOString() as string & tags.Format<'date-time'>,
  };
  const output = await api.functional.favoritesPersonalization.personalizationAudits.post(connection, { body: validBody });
  typia.assert(output);
  TestValidator.equals('user_id matches')(validBody.user_id)(output.user_id);
  TestValidator.equals('action_type matches')(validBody.action_type)(output.action_type);
  TestValidator.equals('timestamp matches')(validBody.timestamp)(output.timestamp);

  // 2. Omit required field (user_id)
  await TestValidator.error('missing user_id should fail')(async () => {
    const { user_id, ...rest } = validBody;
    // @ts-expect-error - purposely omit for test
    await api.functional.favoritesPersonalization.personalizationAudits.post(connection, {
      body: rest,
    });
  });

  // 3. Invalid UUID in user_id
  await TestValidator.error('invalid uuid should fail')(async () => {
    await api.functional.favoritesPersonalization.personalizationAudits.post(connection, {
      body: {
        ...validBody,
        user_id: 'not-a-uuid' as string & tags.Format<'uuid'>,
      },
    });
  });
  // 3b. Invalid date-time in timestamp
  await TestValidator.error('invalid timestamp should fail')(async () => {
    await api.functional.favoritesPersonalization.personalizationAudits.post(connection, {
      body: {
        ...validBody,
        timestamp: 'not-a-time' as string & tags.Format<'date-time'>,
      },
    });
  });

  // 4. Attempt business conflict (duplicate)
  await TestValidator.error('conflicting business record should fail')(async () => {
    await api.functional.favoritesPersonalization.personalizationAudits.post(connection, {
      body: validBody,
    });
  });
}

