import { tags } from "typia";

/**
 * Represents an immutable, cryptographically signed personalization audit
 * evidence record.
 *
 * Implements DSAR export, regulatory compliance trace, forensic review, and
 * explainability in the personalization module.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IPersonalizationAudit = {
  /**
   * Unique audit record ID.
   *
   * Directly from personalization_audits.id.
   */
  id: string & tags.Format<"uuid">;

  /**
   * UUID of user associated with this audit record.
   *
   * Personalization_audits.user_id FK to users.
   */
  user_id: string & tags.Format<"uuid">;

  /** ID of favorite related to this audit record, if any. */
  favorite_id?: (string & tags.Format<"uuid">) | null;

  /** Bookmark record linked to audit, if any. */
  bookmark_id?: (string & tags.Format<"uuid">) | null;

  /** Associated recommendation ID (if any). */
  recommendation_id?: (string & tags.Format<"uuid">) | null;

  /** Link to personalization_event for audit evidence, if exists. */
  personalization_event_id?: (string & tags.Format<"uuid">) | null;

  /**
   * Category of audit action performed (e.g. 'ACTIONS', 'REMOVE_BOOKMARK').
   *
   * Atomic, evidence-grade, mapped to personalization_audits.action_type.
   */
  action_type: string;

  /**
   * Cryptographic hash for non-repudiation evidence.
   *
   * Ensures tamper-evident audit logs, as per
   * personalization_audits.evidence_hash.
   */
  evidence_hash: string;

  /**
   * Time audit event recorded (ISO8601, UTC preferred).
   *
   * Mapped from personalization_audits.timestamp.
   */
  timestamp: string & tags.Format<"date-time">;
};
export namespace IPersonalizationAudit {
  /**
   * Creation schema for a new personalization audit record.
   *
   * All audits are cryptographically and time-traceable. Prisma:
   * personalization_audits table.
   */
  export type ICreate = {
    /**
     * UUID for the user associated with the audit action.
     *
     * Prisma: personalization_audits.user_id.
     */
    user_id: string & tags.Format<"uuid">;

    /**
     * Favorite reference (if relevant) linked to audit.
     *
     * Personalization_audits.favorite_id.
     */
    favorite_id?: (string & tags.Format<"uuid">) | null;

    /**
     * Bookmark ID, if applicable.
     *
     * Personalization_audits.bookmark_id.
     */
    bookmark_id?: (string & tags.Format<"uuid">) | null;

    /**
     * Recommendation involved in the audited action (if any).
     *
     * Prisma: personalization_audits.recommendation_id.
     */
    recommendation_id?: (string & tags.Format<"uuid">) | null;

    /**
     * Linked personalization event (optional).
     *
     * Field: personalization_audits.personalization_event_id.
     */
    personalization_event_id?: (string & tags.Format<"uuid">) | null;

    /** Category/type of audit event or action (e.g. 'ACTIONS'). */
    action_type: string;

    /**
     * Cryptographic evidence hash, immutably logs event.
     *
     * Prisma: personalization_audits.evidence_hash.
     */
    evidence_hash: string;

    /**
     * Exact moment event was recorded (ISO8601).
     *
     * Personalization_audits.timestamp.
     */
    timestamp: string & tags.Format<"date-time">;
  };

  /**
   * Allowed updates for a personalization audit (annotation, evidence hash
   * correction).
   *
   * All such changes are themselves fully evidence logged for regulatory
   * traceability.
   */
  export type IUpdate = {
    /**
     * Update to audit action category/type (e.g. after annotation or
     * evidence update).
     *
     * Personalization_audits.action_type.
     */
    action_type?: string;

    /**
     * Updated cryptographic evidence hash after annotation/correction.
     *
     * Ensures non-repudiation and evidence preservation.
     */
    evidence_hash?: string;

    /**
     * Update for audit timestamp (rare, for corrections or evidence
     * annotation).
     *
     * From personalization_audits.timestamp.
     */
    timestamp?: string & tags.Format<"date-time">;
  };
}

