import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPersonalizationAudit } from "@ORGANIZATION/PROJECT-api/lib/structures/IPersonalizationAudit";

/**
 * E2E test to validate the update of a personalization audit record by ID, including integrity, immutability, and error scenarios.
 *
 * **Workflow covered:**
 * 1. Create a personalization audit record as prerequisite.
 * 2. Successfully annotate/update permitted fields (`action_type`, `evidence_hash`, `timestamp`) on the audit record by ID.
 * 3. Assert all updatable fields are changed as intended, and that immutable fields (`id`, `user_id`, `favorite_id`, etc.) do not change after update.
 * 4. Attempt to update a non-existent audit record and assert the system returns the correct error.
 * 5. (Type constraint) Show that immutable fields cannot be updated via this API and system behavior will enforce or ignore such attempts.
 *
 * **Business rationale:**
 * - Personalization audit records are core to regulatory, forensic, and compliance requirements—improper mutation must be impossible.
 * - The update endpoint allows only evidence annotation or correction to permitted fields; identity and referential integrity must remain immutable.
 * - System should enforce correct API error semantics for missing/invalid IDs.
 *
 * **Steps:**
 * 1. POST a valid audit record (covers dependency, setup).
 * 2. PUT update to allowed fields and assert response (changed fields and protected fields).
 * 3. Re-validate all fields for correct mutability/immutability.
 * 4. PUT update to a random (non-existing) ID and confirm error.
 * 5. Document system protection against attempts to update immutable fields (enforced at type and API levels).
 */
export async function test_api_favoritesPersonalization_test_update_personalization_audit_by_id_with_integrity_and_permissions(
  connection: api.IConnection,
) {
  // 1. Create a new audit record for baseline (dependency)
  const initialAudit = await api.functional.favoritesPersonalization.personalizationAudits.post(
    connection,
    {
      body: {
        user_id: typia.random<string & tags.Format<"uuid">>(),
        favorite_id: typia.random<string & tags.Format<"uuid">>(),
        bookmark_id: null,
        recommendation_id: null,
        personalization_event_id: null,
        action_type: "ACTIONS",
        evidence_hash: RandomGenerator.alphaNumeric(32),
        timestamp: new Date().toISOString(),
      } satisfies IPersonalizationAudit.ICreate,
    },
  );
  typia.assert(initialAudit);

  // 2. Prepare valid update (only allowed fields)
  const updatedFields = {
    action_type: "REMOVE_BOOKMARK",
    evidence_hash: RandomGenerator.alphaNumeric(32),
    timestamp: new Date(Date.now() + 5 * 60 * 1000).toISOString(),
  } satisfies IPersonalizationAudit.IUpdate;

  // 3. Update audit, validate mutability and integrity
  const updatedAudit = await api.functional.favoritesPersonalization.personalizationAudits.putById(
    connection,
    {
      id: initialAudit.id,
      body: updatedFields,
    },
  );
  typia.assert(updatedAudit);
  // Updatable fields must have been changed
  TestValidator.notEquals("action_type updated")(initialAudit.action_type)(updatedAudit.action_type);
  TestValidator.notEquals("evidence_hash updated")(initialAudit.evidence_hash)(updatedAudit.evidence_hash);
  TestValidator.notEquals("timestamp updated")(initialAudit.timestamp)(updatedAudit.timestamp);
  // Immutable fields must be unchanged
  TestValidator.equals("id unchanged")(initialAudit.id)(updatedAudit.id);
  TestValidator.equals("user_id immutable")(initialAudit.user_id)(updatedAudit.user_id);
  TestValidator.equals("favorite_id unchanged")(initialAudit.favorite_id)(updatedAudit.favorite_id);
  TestValidator.equals("bookmark_id unchanged")(initialAudit.bookmark_id)(updatedAudit.bookmark_id);
  TestValidator.equals("recommendation_id unchanged")(initialAudit.recommendation_id)(updatedAudit.recommendation_id);
  TestValidator.equals("personalization_event_id unchanged")(initialAudit.personalization_event_id)(updatedAudit.personalization_event_id);

  // 4. Try updating a non-existent record; system must error
  const nonExistentId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("update on non-existent id fails")(() =>
    api.functional.favoritesPersonalization.personalizationAudits.putById(
      connection,
      {
        id: nonExistentId,
        body: updatedFields,
      },
    ),
  );

  // 5. TypeScript strictly prevents updating immutable fields—test verifies that only permitted properties are processed anyway
  // (If API were to permit, code here would try to send extra fields, but the types prevent this, which is correct)
}

