import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPersonalizationAudit } from "@ORGANIZATION/PROJECT-api/lib/structures/IPersonalizationAudit";

/**
 * Soft-delete (archive) a personalization audit record by unique ID, and handle not-found scenarios.
 *
 * This test validates both the happy path (archiving a real record) and error handling when the record doesn't exist or is already deleted.
 * It also confirms that audit evidence persists for compliance (audits remain for trace/review, but inactive).
 *
 * Steps:
 * 1. Create a valid audit record using the audit creation endpoint.
 * 2. Delete (archive) that record by ID, and confirm the response marks it as deleted or inactive.
 * 3. Attempt a second delete of the same ID, and verify an appropriate error is returned (e.g., not found or already deleted).
 * 4. Attempt to delete a completely non-existent ID (random UUID), and confirm a not found error is returned.
 * 5. Optionally, check that the deleted record's historical evidence (e.g., immutable fields) can still be retrieved for compliance inquiry if business logic allows, or confirm archival state.
 */
export async function test_api_favoritesPersonalization_test_soft_delete_personalization_audit_and_handle_not_found(connection: api.IConnection) {
  // 1. Create a new audit record for testing
typia.assert(connection);
const createInput: IPersonalizationAudit.ICreate = {
  user_id: typia.random<string & tags.Format<"uuid">>(),
  favorite_id: typia.random<string & tags.Format<"uuid">>(),
  bookmark_id: null,
  recommendation_id: null,
  personalization_event_id: null,
  action_type: "REMOVE_BOOKMARK",
  evidence_hash: RandomGenerator.alphaNumeric(64),
  timestamp: new Date().toISOString(),
};
const created = await api.functional.favoritesPersonalization.personalizationAudits.post(connection, { body: createInput });
typia.assert(created);
TestValidator.equals("audit user")(createInput.user_id)(created.user_id);
TestValidator.equals("audit action")(createInput.action_type)(created.action_type);

// 2. Delete (soft-delete) the created record by ID
const deleted = await api.functional.favoritesPersonalization.personalizationAudits.eraseById(connection, { id: created.id });
typia.assert(deleted);
TestValidator.equals("deleted id")(created.id)(deleted.id);
// Optionally verify logic - depending on implementation, marker/flag for archival or status

// 3. Attempt to delete the same record again - should fail (already deleted)
await TestValidator.error("double delete yields not found")(async () => {
  await api.functional.favoritesPersonalization.personalizationAudits.eraseById(connection, { id: created.id });
});

// 4. Try deleting a random (non-existent) audit ID
await TestValidator.error("delete non-existent audit yields not found")(async () => {
  await api.functional.favoritesPersonalization.personalizationAudits.eraseById(connection, { id: typia.random<string & tags.Format<"uuid">>() });
});

// 5. Confirm (if required by business logic) that evidence of deleted record is still present for compliance (i.e., via another endpoint), or this step is not available / implementation-dependent
}

