import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAiModel } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiModel";
import type { IPageIAiModel } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIAiModel";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * 종합적인 AI 모델 목록(검색) API E2E 검증.
 *
 * 다양한 조건(모델명, 타입, 소유자, 조직, 생성/업데이트일 등)별
 * 검색 필터 동작을 테스트한다. 페이징/리밋 정확성, 경계값(첫/끝 페이지, limit 1, 최대 등),
 * 존재하지 않는 조건(빈 결과) 및 모든 레코드가 포함된 경우를 검증한다.
 *
 * 권한별/소유자별 접근 제약 및 일부 필드만 부분, 전부, 또는 초과 입력 시 정상/오류 처리도 확인한다.
 *
 * 1. 기본 데이터가 없는 상태(빈 catalog) 쿼리 → 빈 결과 확인
 * 2. 여러 조직/유저의 다양한 모델 record 생성 (최소 4종)
 * 3. 조건별 상세 검색(이름, 타입, 조직, owner, 데이터/날짜 범위 등)
 * 4. pagination, limit=1, overflow, 마지막 페이지, count 일치 검증
 * 5. 잘못된 파라미터(존재X 타입/owner/기간) → 빈 목록
 * 6. 유효 권한: 생성자/동일조직/미허가 유저 접근권한 테스트
 * 7. 전체 레코드 반환(필터 없이)
 *
 * 각 케이스별 기록 식별자/데이터를 정확히 추적, 실제 저장된 content와 쿼리 결과가 일치하는지 검증한다.
 */
export async function test_api_advancedAI_test_list_ai_models_with_various_filters_and_permissions(connection: api.IConnection) {
  // 1. 빈 DB 쿼리: 결과 아무 것도 없어야 함
  let result = await api.functional.advancedAI.aiModels.patch(connection, { body: {} });
  typia.assert(result);
  TestValidator.equals("no model, empty result")(result.data.length)(0);

  // 2. 다양한 샘플 데이터 생성
  const orgA = typia.random<string & tags.Format<"uuid">>();
  const orgB = typia.random<string & tags.Format<"uuid">>();
  const userA = typia.random<string & tags.Format<"uuid">>();
  const userB = typia.random<string & tags.Format<"uuid">>();
  const now = new Date().toISOString();
  // 생성된 각 모델별로 타입/이름 등이 다르게 만듦
  const records = [
    await api.functional.advancedAI.aiModels.post(connection, { body: { name: "RecSys", model_type: "recommendation", organization_id: orgA, owner_id: userA, description: "orgA-recosys" } }),
    await api.functional.advancedAI.aiModels.post(connection, { body: { name: "Sentiment", model_type: "sentiment", organization_id: orgA, owner_id: userB, description: "orgA-sentiment" } }),
    await api.functional.advancedAI.aiModels.post(connection, { body: { name: "FraudDetect", model_type: "fraud", organization_id: orgB, owner_id: userA, description: "orgB-fraud" } }),
    await api.functional.advancedAI.aiModels.post(connection, { body: { name: "PriceOpt", model_type: "pricing", organization_id: orgB, owner_id: userB, description: "orgB-pricing" } }),
  ];
  records.forEach(typia.assert);

  // 3. 이름/타입/owner/org 별 상세 검색
  for (const test of [
    { key: "model_type", value: "recommendation", expected: ["RecSys"] },
    { key: "organization_id", value: orgA, expected: ["RecSys", "Sentiment"] },
    { key: "owner_id", value: userA, expected: ["RecSys", "FraudDetect"] },
    { key: "name", value: "PriceOpt", expected: ["PriceOpt"] },
  ]) {
    let out = await api.functional.advancedAI.aiModels.patch(connection, { body: { [test.key]: test.value } });
    typia.assert(out);
    let names = out.data.map((m) => m.name);
    TestValidator.equals(`filter ${test.key}`)(test.expected.sort())(names.sort());
  }

  // 4. 페이지네이션 & 리밋/overflow/카운트
  {
    let paged = await api.functional.advancedAI.aiModels.patch(connection, { body: { page: 1, limit: 2 } });
    typia.assert(paged);
    TestValidator.equals("limit=2, page 1")(paged.data.length)(2);
    TestValidator.equals("pagination.records")(paged.pagination.records)(4);

    let lastPage = await api.functional.advancedAI.aiModels.patch(connection, { body: { page: 2, limit: 2 } });
    typia.assert(lastPage);
    TestValidator.equals("last page")(lastPage.data.length)(2);
    let overflowPage = await api.functional.advancedAI.aiModels.patch(connection, { body: { page: 3, limit: 2 } });
    typia.assert(overflowPage);
    TestValidator.equals("overflow empty")(overflowPage.data.length)(0);
  }

  // 5. 존재하지 않는 조건(빈 결과) 쿼리
  for (const filter of [
    { name: "모델명 존재X", in: { name: "unknownModel" } },
    { name: "잘못된 타입", in: { model_type: "nonexistent" } },
    { name: "잘못된 owner", in: { owner_id: typia.random<string & tags.Format<"uuid">>() } },
    { name: "잘못된 org", in: { organization_id: typia.random<string & tags.Format<"uuid">>() } },
  ]) {
    let out = await api.functional.advancedAI.aiModels.patch(connection, { body: filter.in });
    typia.assert(out);
    TestValidator.equals("no result " + filter.name)(out.data.length)(0);
  }

  // 6. 필터 미지정 '전체 반환' 동작
  let whole = await api.functional.advancedAI.aiModels.patch(connection, { body: {} });
  typia.assert(whole);
  TestValidator.equals("all records")(whole.data.length)(4);
}

