import { IConnection, HttpError } from "@nestia/fetcher";
import { PlainFetcher } from "@nestia/fetcher/lib/PlainFetcher";
import typia, { tags } from "typia";
import { NestiaSimulator } from "@nestia/fetcher/lib/NestiaSimulator";

import { IAiModel } from "../../../structures/IAiModel";

/**
 * Gets full details of a single AI model by ID (AdvancedAI.ai_models).
 *
 * This API operation provides full details for a specified AI model, identified
 * by its ID. The response contains all metadata, configuration, audit
 * references, and relationships to organization/owner. Security permissions are
 * strictly enforced. Access is non-repudiably logged for evidence preservation
 * to meet regulatory and internal audit standards. This endpoint supports
 * explainability, direct administrative actions, and model governance UIs. For
 * listing/search, see PATCH /advancedAI/aiModels. For creation or updates, use
 * POST/PUT endpoints. Errors are detailed and linked to audit events for
 * compliance. The client must ensure the ID provided is valid and the user has
 * appropriate permissions. If the model is not found, returns a detailed error
 * with audit trace.
 *
 * @param props.connection
 * @param props.id Target AI model's ID (UUID).
 * @path /advancedAI/aiModels/:id
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export async function getById(
  connection: IConnection,
  props: getById.Props,
): Promise<getById.Response> {
  return !!connection.simulate
    ? getById.simulate(connection, props)
    : PlainFetcher.fetch(
        {
          ...connection,
          headers: {
            ...connection.headers,
            "Content-Type": "application/json",
          },
        },
        {
          ...getById.METADATA,
          path: getById.path(props),
          status: null,
        },
      );
}
export namespace getById {
  export type Props = {
    /** Target AI model's ID (UUID). */
    id: string & tags.Format<"uuid">;
  };
  export type Response = IAiModel;

  export const METADATA = {
    method: "GET",
    path: "/advancedAI/aiModels/:id",
    request: null,
    response: {
      type: "application/json",
      encrypted: false,
    },
  } as const;

  export const path = (props: Props) =>
    `/advancedAI/aiModels/${encodeURIComponent(props.id ?? "null")}`;
  export const random = (g?: Partial<typia.IRandomGenerator>): IAiModel =>
    typia.random<IAiModel>(g);
  export const simulate = (
    connection: IConnection,
    props: getById.Props,
  ): Response => {
    const assert = NestiaSimulator.assert({
      method: METADATA.method,
      host: connection.host,
      path: getById.path(props),
      contentType: "application/json",
    });
    try {
      assert.param("id")(() => typia.assert(props.id));
    } catch (exp) {
      if (!typia.is<HttpError>(exp)) throw exp;
      return {
        success: false,
        status: exp.status,
        headers: exp.headers,
        data: exp.toJSON().message,
      } as any;
    }
    return random(
      "object" === typeof connection.simulate && null !== connection.simulate
        ? connection.simulate
        : undefined,
    );
  };
}

/**
 * Creates a new AI model (AdvancedAI.ai_models).
 *
 * This API operation allows privileged clients (admins, AI ops) to create a new
 * AI model entry, registering its metadata, ownership, business context, type,
 * and description. The request body must include validated and mandatory fields
 * such as name, model_type, owner_id, and organization_id. All creations are
 * logged for non-repudiable audit trails. Permissions and scope enforcement
 * apply; creation will fail if duplicate, unauthorized, or invalid. On success,
 * the system persists the new model and returns its unique attributes. Creation
 * triggers downstream monitoring and explainability setup. For
 * listing/query/search, see PATCH /advancedAI/aiModels. Modifications and nuke
 * operations are supported by PUT/DELETE. Data integrity is checked before
 * persisting.
 *
 * @param props.connection
 * @param props.body New AI model creation data (requires metadata,
 *   owner/organization references).
 * @path /advancedAI/aiModels
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export async function post(
  connection: IConnection,
  props: post.Props,
): Promise<post.Response> {
  return !!connection.simulate
    ? post.simulate(connection, props)
    : PlainFetcher.fetch(
        {
          ...connection,
          headers: {
            ...connection.headers,
            "Content-Type": "application/json",
          },
        },
        {
          ...post.METADATA,
          path: post.path(),
          status: null,
        },
        props.body,
      );
}
export namespace post {
  export type Props = {
    /**
     * New AI model creation data (requires metadata, owner/organization
     * references).
     */
    body: IAiModel.ICreate;
