/**
 * E2E Test: Retrieve AI Model by ID, including error and deleted record handling
 *
 * This test covers retrieval of an AI Model record by its unique ID, including full detail verification, and proper error and deleted record responses.
 *
 * Steps:
 * 1. Create a new AI Model for test (dependency + setup)
 * 2. Retrieve the created model by ID, ensuring all returned fields match
 * 3. Attempt to fetch a random UUID (non-existent ID) and expect a 404 or error
 * 4. (If supported) Soft-delete the record, then re-attempt fetch and validate data is preserved or error as per business logic
 */
export async function test_api_advancedAI_test_get_ai_model_by_id_with_deleted_and_not_found_handling(
  connection: api.IConnection,
) {
  // 1. Create a new AI Model to set up the test
  const input: IAiModel.ICreate = {
    organization_id: typia.random<string & tags.Format<"uuid">>(),
    owner_id: typia.random<string & tags.Format<"uuid">>(),
    name: RandomGenerator.alphaNumeric(8),
    model_type: RandomGenerator.alphabets(5),
    description: RandomGenerator.paragraph()(),
  };

  const created: IAiModel = await api.functional.advancedAI.aiModels.post(
    connection,
    { body: input },
  );
  typia.assert(created);

  // 2. Fetch model by its ID and verify complete field accuracy
  const read: IAiModel = await api.functional.advancedAI.aiModels.getById(
    connection,
    { id: created.id },
  );
  typia.assert(read);
  TestValidator.equals("model.id matches")(created.id)(read.id);
  TestValidator.equals("organization_id matches")(created.organization_id)(read.organization_id);
  TestValidator.equals("owner_id matches")(created.owner_id)(read.owner_id);
  TestValidator.equals("name matches")(created.name)(read.name);
  TestValidator.equals("model_type matches")(created.model_type)(read.model_type);
  TestValidator.equals("description matches")(created.description)(read.description);

  // 3. Attempt to retrieve a non-existent ID, expect error (404)
  await TestValidator.error("getById should 404 or error on missing ID")(async () => {
    await api.functional.advancedAI.aiModels.getById(
      connection,
      { id: typia.random<string & tags.Format<"uuid">>() },
    );
  });

  // 4. (Soft-delete validation omitted unless API provides a delete/restore route)
  //   ...if deletion supported, would attempt delete then getById again, verifying correct handling
}

