import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAiModel } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiModel";

/**
 * AI 모델(AdvancedAI.ai_models)의 ID별 수정 테스트
 *
 * 이 테스트는 AI 모델 관리자의 관점에서, 기존에 생성된 AI/ML 모델 레지스트리 엔터티의 일부 필드(이름, 모델 타입, 설명, 오너 등)를 정상적으로 업데이트할 수 있는지 검증합니다. 또한 다음의 비즈니스 규칙과 에러 케이스도 확인합니다:
 *
 * 1. 정상 수정 플로우: 허용된 필드(name, model_type, description, owner_id, organization_id)를 갱신하면 최신 업데이트가 반영되어 반환됨을 검증
 * 2. 존재하지 않거나 소프트삭제된(id가 없거나 무효) 모델에 대해 수정 요청시 적절한 에러(404 등) 발생 확인
 * 3. system field(생성/수정시각 created_at, updated_at 등)와 불변 필드(id)는 수정 시도시 business rule validation에 의해 거부되는지 검증
 *
 * 시나리오 절차 상세:
 * 1. 사전 준비로써 AI 모델을 신규 생성한다 (post)
 * 2. 정상 업데이트
 *   a. 일부 주요 필드(name, model_type 등)를 변경 업데이트 요청 → 응답/DB에서 값이 반영되었는지 확인
 * 3. 존재하지 않는(랜덤 UUID) 모델 id로 수정 요청 → 404 반환 여부 확인
 * 4. immutable/system 필드(id, created_at, updated_at 등)를 body에 포함해 수정 시도 → 400 혹은 비즈니스 검증 에러 응답 확인
 */
export async function test_api_advancedAI_test_update_ai_model_by_id_with_business_rule_enforcement(
  connection: api.IConnection,
) {
  // 1. 신규 AI 모델 생성 (post; create)
  const aiModel = await api.functional.advancedAI.aiModels.post(
    connection,
    {
      body: {
        organization_id: typia.random<string & tags.Format<"uuid">>(),
        owner_id: typia.random<string & tags.Format<"uuid">>(),
        name: "Test Model " + RandomGenerator.alphaNumeric(4),
        model_type: "classification",
        description: "Initial model for update test.",
      } satisfies IAiModel.ICreate,
    },
  );
  typia.assert(aiModel);

  // 2. 허용 필드 업데이트 정상 케이스
  const updatedName = "Updated Model " + RandomGenerator.alphaNumeric(4);
  const updatedDescription = "Updated description.";
  const updatedModelType = "recommendation";
  const updateResult = await api.functional.advancedAI.aiModels.putById(
    connection,
    {
      id: aiModel.id,
      body: {
        name: updatedName,
        model_type: updatedModelType,
        description: updatedDescription,
      } satisfies IAiModel.IUpdate,
    },
  );
  typia.assert(updateResult);
  TestValidator.equals("name")(updatedName)(updateResult.name);
  TestValidator.equals("model_type")(updatedModelType)(updateResult.model_type);
  TestValidator.equals("description")(updatedDescription)(updateResult.description);

  // 3. 존재하지 않는 id로 수정 → 404 확인
  const nonExistId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("Not found; update non-existent model")(() =>
    api.functional.advancedAI.aiModels.putById(connection, {
      id: nonExistId,
      body: { name: "DoesNotMatter" },
    }),
  );

  // 4. 시스템/immutable 필드를 포함한 업데이트 → 비즈니스룰 validation
  await TestValidator.error("Immutable/system field update rejected")(() =>
    api.functional.advancedAI.aiModels.putById(connection, {
      id: aiModel.id,
      body: {
        name: "StillValid",
        model_type: "classification",
        description: "try to update system",
        // Immutable fields (should be ignored or rejected)
        // @ts-expect-error
        id: typia.random<string & tags.Format<"uuid">>(),
        created_at: new Date().toISOString(),
        updated_at: new Date().toISOString(),
      } as any, // Intentionally inject forbidden keys for error
    }),
  );
}

