import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAiModel } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiModel";
import type { ICommon } from "@ORGANIZATION/PROJECT-api/lib/structures/ICommon";

/**
 * AI 모델(머신러닝/딥러닝 등) Soft Delete 및 삭제 후 동작 검증.
 *
 * 이 테스트는 관리자/운영 권한이 있는 사용자가 실제로 AI 모델 엔터티(AdvancedAI.ai_models)를 삭제 요청할 때, 단순히 물리 삭제가
 * 아닌 컴플라이언스 준수를 위해 소프트 딜리트(비가역적 비활성 처리/증적 보존)가 잘 동작하는지, 그리고 삭제된 후 모델이 활성 목록
 *(예: 조회 API)엔 출력되지 않으나, 별도 감사/이력/복구용으론 참조 가능한지 반드시 테스트해야 함을 의미합니다. 또한,
 * 반복 삭제(이미 지운 모델에 대해 또 delete 요청) 시 예외처리 및 비존재 ID 지정시 에러 핸들링도 확인해야 합니다.
 *
 * [테스트 순서]
 * 1. 모델 생성 (dependency)
 * 2. 정상 삭제 요청 및 응답(IIdDeleted.deleted_at, status 등) 확인
 * 3. 삭제된 모델이 활성 모델 목록엔 없고, 증적/감사용으론 조회 가능함을 별도(가상) API로 검증(단, 조회 API 제공 없으면 스킵)
 * 4. 동일 ID로 delete 재요청 시, idempotency/이미 삭제 예외 동작 확인
 * 5. 비존재/임의 UUID로 delete 시 에러 응답 검증
 */
export async function test_api_advancedAI_test_delete_ai_model_by_id_with_soft_delete_and_error_handling(connection: api.IConnection) {
  // 1. 사전 엔터티 생성: 의존 AI모델 1개 등록
  const aiModel: IAiModel = await api.functional.advancedAI.aiModels.post(connection, {
    body: {
      organization_id: typia.random<string & tags.Format<"uuid">>(),
      owner_id: typia.random<string & tags.Format<"uuid">>(),
      name: RandomGenerator.alphabets(10),
      model_type: "recommendation",
      description: RandomGenerator.paragraph()(),
    } satisfies IAiModel.ICreate,
  });
  typia.assert(aiModel);

  // 2. 정상 삭제 호출 및 response(삭제 이력 포함) 검증
  const deleted: ICommon.IIdDeleted = await api.functional.advancedAI.aiModels.eraseById(connection, {
    id: aiModel.id,
  });
  typia.assert(deleted);
  TestValidator.equals("model id")(aiModel.id)(deleted.id);
  TestValidator.predicate("soft deleted_at present")(
    typeof deleted.deleted_at === "string" && deleted.deleted_at.length > 0,
  );
  TestValidator.equals("status")(deleted.status)("deleted");

  // 3. (옵션) 삭제 후 모델 리스트 및 증적/이력/감사 조회 검증(구현 API 있을 시)
  //    → 예: 삭제된 id로 조회 API 또는 증적 로그 API로 fetch/감사 확인 가능
  //    해당 기능 제공 없다면 skip, 있으면 id로 조회 시 deleted=true 등 검증

  // 4. 동일 id로 delete 재시도: idempotency 처리(200-OK 또는 에러) 혹은 already-deleted Status 반환 확인
  const deletedAgain: ICommon.IIdDeleted = await api.functional.advancedAI.aiModels.eraseById(connection, {
    id: aiModel.id,
  });
  typia.assert(deletedAgain);
  TestValidator.equals("model id (again)")(aiModel.id)(deletedAgain.id);
  TestValidator.equals("deleted_at idem")(
    deleted.deleted_at,
  )(deletedAgain.deleted_at);
  TestValidator.equals("status (again)")(deletedAgain.status)("deleted");

  // 5. 비존재/임의 uuid 사용 delete 시 에러 반응 검증
  await TestValidator.error("delete non-existent id")(() =>
    api.functional.advancedAI.aiModels.eraseById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
    }),
  );
}

