import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAiModelVersion } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiModelVersion";
import type { IPageIAiModelVersion } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIAiModelVersion";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate advanced list/search for AI model versions with all filter and pagination edge cases.
 *
 * Purpose: Ensure that listing AI model versions returns correct results for diverse filter/pagination scenarios including empty, overloaded, and edge conditions.
 *
 * Business context:
 * - MLOps or AI governance portals must let users search and list model versions by modelId, version string, creation timeframe, framework, deployed status, and with pagination.
 * - This ensures dashboards, audit tools, and analytics can find correct records and handle boundary situations robustly.
 *
 * Test Steps:
 * 1. Create multiple AI model versions with different parent modelIds, version labels, frameworks, dates, and deployed states.
 *    - Create data so that search and filtering can use:
 *        - Different ai_model_id values for grouping
 *        - Diverse "version" values including similar/prefix and unique
 *        - Some models with deployed_at set, some null
 *        - Different frameworks (e.g., TensorFlow, PyTorch)
 *        - Varied creation times (simulate past and present edge)
 * 2. List using empty filter (should return all, paginated)
 * 3. Filter by specific ai_model_id (returns only relevant versions)
 * 4. Filter by version string (exact, partial/prefix)
 * 5. Filter by framework (should match only corresponding versions)
 * 6. Use created_from/created_to to limit by creation range (test edge inclusions)
 * 7. Set deployed true/false to select deployed/undeployed only
 * 8. Provide filters that result in empty/no-match results (invalid ids, conflicting filters)
 * 9. Test pagination: limit = 1, limit > total, page out of range
 * 10. For each step, validate that response data matches expected subset and meta (IPage pagination)
 */
export async function test_api_advancedAI_test_list_ai_model_versions_with_search_and_filter_edge_cases(connection: api.IConnection) {
  // Step 1: Data preparation
  // Create multiple unique ai_model_id values
  const aiModelIds = [
    typia.random<string & tags.Format<"uuid">>(),
    typia.random<string & tags.Format<"uuid">>(),
  ];
  // Diverse creation times
  const now = new Date();
  const dayAgo = new Date(now.getTime() - 24 * 60 * 60 * 1000);
  const weekAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
  // Insert records
  const modelVersions = [
    // Model A - v1
    await api.functional.advancedAI.aiModelVersions.post(connection, {
      body: {
        ai_model_id: aiModelIds[0],
        version: "v1.0.0",
        version_hash: typia.random<string>(),
        artifact_url: "https://models.com/modelA/v1",
        framework: "TensorFlow",
        metadata: JSON.stringify({ accuracy: 0.99 }),
      } satisfies IAiModelVersion.ICreate,
    }),
    // Model A - v2, deployed, older
    await api.functional.advancedAI.aiModelVersions.post(connection, {
      body: {
        ai_model_id: aiModelIds[0],
        version: "v2.0.0",
        version_hash: typia.random<string>(),
        artifact_url: "https://models.com/modelA/v2",
        framework: "TensorFlow",
        metadata: JSON.stringify({ accuracy: 0.991 }),
      } satisfies IAiModelVersion.ICreate,
    }),
    // Model B - v1, PyTorch
    await api.functional.advancedAI.aiModelVersions.post(connection, {
      body: {
        ai_model_id: aiModelIds[1],
        version: "alpha",
        version_hash: typia.random<string>(),
        artifact_url: "https://models.com/modelB/alpha",
        framework: "PyTorch",
        metadata: JSON.stringify({ f1: 0.8 }),
      } satisfies IAiModelVersion.ICreate,
    }),
    // Model B - v2, PyTorch
    await api.functional.advancedAI.aiModelVersions.post(connection, {
      body: {
        ai_model_id: aiModelIds[1],
        version: "beta",
        version_hash: typia.random<string>(),
        artifact_url: "https://models.com/modelB/beta",
        framework: "PyTorch",
        metadata: JSON.stringify({ f1: 0.85 }),
      } satisfies IAiModelVersion.ICreate,
    }),
  ];
  await Promise.all(modelVersions);

  // Step 2: List - empty filter
  const allResult = await api.functional.advancedAI.aiModelVersions.patch(connection, { body: {} });
  typia.assert(allResult);
  TestValidator.predicate("Should have >= 4 records")(allResult.pagination.records >= 4);

  // Step 3: Filter by ai_model_id
  const filterAiModel = await api.functional.advancedAI.aiModelVersions.patch(connection, { body: { ai_model_id: aiModelIds[1] } });
  typia.assert(filterAiModel);
  TestValidator.predicate("All records match ai_model_id")(
    filterAiModel.data.every((v) => v.ai_model_id === aiModelIds[1])
  );

  // Step 4: Filter by version (exact and partial prefix)
  const byVersionExact = await api.functional.advancedAI.aiModelVersions.patch(connection, { body: { version: "v1.0.0" } });
  typia.assert(byVersionExact);
  TestValidator.predicate("All records version=v1.0.0")(
    byVersionExact.data.every((v) => v.version === "v1.0.0")
  );
  const byVersionPrefix = await api.functional.advancedAI.aiModelVersions.patch(connection, { body: { version: "v" } });
  typia.assert(byVersionPrefix);
  TestValidator.predicate("All records version starts with 'v'")(
    byVersionPrefix.data.every((v) => v.version.startsWith("v"))
  );

  // Step 5: Filter by framework
  const byFramework = await api.functional.advancedAI.aiModelVersions.patch(connection, { body: { framework: "PyTorch" } });
  typia.assert(byFramework);
  TestValidator.predicate("All records are PyTorch")(
    byFramework.data.every((v) => v.framework === "PyTorch")
  );

  // Step 6: Filter by created_from/created_to
  // Use present and past filter ranges
  const byCreatedFrom = await api.functional.advancedAI.aiModelVersions.patch(connection, { body: { created_from: weekAgo.toISOString() } });
  typia.assert(byCreatedFrom);
  TestValidator.predicate("All records created after weekAgo")(
    byCreatedFrom.data.every((v) => new Date(v.created_at) >= weekAgo)
  );
  const byCreatedTo = await api.functional.advancedAI.aiModelVersions.patch(connection, { body: { created_to: now.toISOString() } });
  typia.assert(byCreatedTo);
  TestValidator.predicate("All records created before now")(
    byCreatedTo.data.every((v) => new Date(v.created_at) <= now)
  );

  // Step 7: Deployed/undeployed records
  // First, find a deployed and undeployed record (based on deployed_at presence)
  const checkDeployed = (deployed?: boolean) => async () => {
    const result = await api.functional.advancedAI.aiModelVersions.patch(connection, { body: { deployed } });
    typia.assert(result);
    TestValidator.predicate("All records deployed flag matches")(
      result.data.every((v) => ((deployed ? v.deployed_at != null : v.deployed_at == null)))
    );
  };
  await checkDeployed(true)();
  await checkDeployed(false)();

  // Step 8: No-match filter (invalid ai_model_id)
  const none = await api.functional.advancedAI.aiModelVersions.patch(connection, { body: { ai_model_id: typia.random<string & tags.Format<"uuid">>() } });
  typia.assert(none);
  TestValidator.equals("Should be empty array")(0)(none.data.length);

  // Step 9: Pagination: limit=1, limit too high, invalid page
  const onePerPage = await api.functional.advancedAI.aiModelVersions.patch(connection, { body: { limit: 1 } });
  typia.assert(onePerPage);
  TestValidator.equals("Page size 1")(1)(onePerPage.data.length);
  const allCount = allResult.pagination.records;
  const overLimit = await api.functional.advancedAI.aiModelVersions.patch(connection, { body: { limit: allCount + 10 } });
  typia.assert(overLimit);
  TestValidator.equals("Should return all records")(allCount)(overLimit.data.length);
  const outOfRange = await api.functional.advancedAI.aiModelVersions.patch(connection, { body: { current: 100, limit: 1 } });
  typia.assert(outOfRange);
  TestValidator.equals("Page out of range should be empty")(0)(outOfRange.data.length);
}

