/**
 * Validate fetching a single AI model version by id, and error handling for missing records.
 *
 * 1. Create an AI model version for retrieval test.
 * 2. Retrieve the AI model version using its id and ensure all details match the creation response.
 * 3. Attempt to fetch a random (not used) UUID, expecting a not found or error result.
 * 4. (If delete feature exists: Delete the record, then check it cannot be fetched again.)
 */
export async function test_api_advancedAI_test_get_ai_model_version_by_id_and_handle_absent_records(
  connection: api.IConnection,
) {
  // 1. Create a model version (dependency)
  const createInput: IAiModelVersion.ICreate = {
    ai_model_id: typia.random<string & tags.Format<"uuid">>(),
    version: "v" + typia.random<number & tags.Type<"uint32"> & tags.Minimum<1> & tags.Maximum<9999>>().toString(),
    version_hash: RandomGenerator.alphaNumeric(16),
    artifact_url: "https://bucket.example.com/model/" + RandomGenerator.alphaNumeric(8),
    framework: RandomGenerator.pick(["TensorFlow","PyTorch","Keras","Scikit-learn"]),
    metadata: JSON.stringify({ batch: typia.random<number>(), comment: RandomGenerator.content()()() }),
  };
  const version: IAiModelVersion = await api.functional.advancedAI.aiModelVersions.post(connection, {
    body: createInput,
  });
  typia.assert(version);

  // 2. Retrieve the created version by its id
  const read: IAiModelVersion = await api.functional.advancedAI.aiModelVersions.getById(connection, {
    id: version.id,
  });
  typia.assert(read);
  TestValidator.equals("version id")(version.id)(read.id);
  TestValidator.equals("ai_model_id")(createInput.ai_model_id)(read.ai_model_id);
  TestValidator.equals("version")(createInput.version)(read.version);
  TestValidator.equals("version_hash")(createInput.version_hash)(read.version_hash);
  TestValidator.equals("artifact_url")(createInput.artifact_url)(read.artifact_url);
  TestValidator.equals("framework")(createInput.framework)(read.framework);
  if (createInput.metadata)
    TestValidator.equals("metadata")(createInput.metadata)(read.metadata);

  // 3. Attempt to fetch a non-existent version
  await TestValidator.error("fetching non-existent ai model version fails")(async () => {
    await api.functional.advancedAI.aiModelVersions.getById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
    });
  });
}

