import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAiModelVersion } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiModelVersion";

/**
 * Test creation of a new AI model version with comprehensive validation logic.
 *
 * This test covers:
 * - Successful creation with all fields (including optional metadata)
 * - Failure cases: missing required fields, invalid field data (invalid UUID, empty required, etc.)
 * - Attempting to create a duplicate (same model and version) and validating error handling
 *
 * Step-by-step process:
 * 1. Prepare a valid IAiModelVersion.ICreate object with all fields
 * 2. Call aiModelVersions.post to create the new version, verify response
 * 3. Verify that created model version matches input including metadata
 * 4. Attempt to create with missing required fields and expect errors
 * 5. Attempt to create with invalid ai_model_id (invalid UUID etc.)
 * 6. Attempt to create a duplicate model/version combination, expect error (unique constraint)
 * 7. Attempt to create with minimal (only required) fields to ensure path works
 */
export async function test_api_advancedAI_test_create_ai_model_version_with_full_validation_logic(
  connection: api.IConnection
) {
  // Step 1: Prepare a valid ICreate payload
  const ai_model_id = typia.random<string & tags.Format<"uuid">>();
  const body: IAiModelVersion.ICreate = {
    ai_model_id,
    version: "v1.0.0",
    version_hash: RandomGenerator.alphaNumeric(64),
    artifact_url: `s3://bucket/model_v1.0.0.bin`,
    framework: "PyTorch",
    metadata: JSON.stringify({ accuracy: 0.97, note: "Initial deployment" }),
  };

  // Step 2: Successful creation
  const created = await api.functional.advancedAI.aiModelVersions.post(connection, { body });
  typia.assert(created);
  TestValidator.equals("ai_model_id")(created.ai_model_id)(body.ai_model_id);
  TestValidator.equals("version")(created.version)(body.version);
  TestValidator.equals("version_hash")(created.version_hash)(body.version_hash);
  TestValidator.equals("artifact_url")(created.artifact_url)(body.artifact_url);
  TestValidator.equals("framework")(created.framework)(body.framework);
  TestValidator.equals("metadata")(created.metadata)(body.metadata);

  // Step 3: Create duplicate model version (should fail: uniqueness constraint on ai_model_id+version)
  await TestValidator.error("duplicate creation should fail")(async () => {
    return api.functional.advancedAI.aiModelVersions.post(connection, { body });
  });

  // Step 4: Missing required fields
  await TestValidator.error("missing version should fail")(async () => {
    const noVersion: IAiModelVersion.ICreate = {
      ai_model_id,
      // version intentionally omitted (should error by typescript, but illustrate)
      version_hash: RandomGenerator.alphaNumeric(64),
      artifact_url: `s3://bucket/model_missing.bin`,
      framework: "PyTorch",
    } as any;
    return api.functional.advancedAI.aiModelVersions.post(connection, { body: noVersion });
  });

  // Step 5: Invalid ai_model_id (should be uuid, give invalid string)
  await TestValidator.error("invalid ai_model_id should fail")(async () => {
    const invalidIdBody: IAiModelVersion.ICreate = {
      ai_model_id: "not-a-uuid" as any,
      version: "v1.1.0",
      version_hash: RandomGenerator.alphaNumeric(64),
      artifact_url: `s3://bucket/model_v1.1.0.bin`,
      framework: "PyTorch",
    };
    return api.functional.advancedAI.aiModelVersions.post(connection, { body: invalidIdBody });
  });

  // Step 6: Minimal required fields only
  const minimalBody: IAiModelVersion.ICreate = {
    ai_model_id,
    version: "v1.2.0",
    version_hash: RandomGenerator.alphaNumeric(64),
    artifact_url: `s3://bucket/model_minimal.bin`,
    framework: "TensorFlow",
