import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAiModelVersion } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiModelVersion";

/**
 * Test creation of a new AI model version with comprehensive validation logic.
 *
 * Business context:
 * - This function verifies the end-to-end creation of AI model versions via POST /advancedAI/aiModelVersions.
 * - Confirms handling of all required and optional fields, optimistic and pessimistic scenarios, and unique constraint enforcement.
 *
 * Steps:
 * 1. Prepare a valid IAiModelVersion.ICreate object with all fields (incl. optional metadata)
 * 2. Call aiModelVersions.post: expect success; verify returned object integrity w/ typia.assert & TestValidator
 * 3. Attempt to create with a duplicate ai_model_id+version: expect unique constraint violation (error)
 * 4. Attempt to create with invalid ai_model_id (format error, non-UUID): expect error
 * 5. Create a model version with minimal required fields only; expect success and valid output
 */
export async function test_api_advancedAI_test_create_ai_model_version_with_full_validation_logic(
  connection: api.IConnection,
) {
  // 1. Prepare valid payload (all fields)
  const ai_model_id: string & tags.Format<"uuid"> = typia.random<string & tags.Format<"uuid">>();
  const body: IAiModelVersion.ICreate = {
    ai_model_id,
    version: "v1.0.0",
    version_hash: RandomGenerator.alphaNumeric(64),
    artifact_url: `s3://bucket/model_v1.0.0.bin`,
    framework: "PyTorch",
    metadata: JSON.stringify({ accuracy: 0.98, team: "ml-core", note: "First release" }),
  };

  // 2. Create model version (expect success)
  const created = await api.functional.advancedAI.aiModelVersions.post(connection, { body });
  typia.assert(created);
  TestValidator.equals("ai_model_id")(created.ai_model_id)(body.ai_model_id);
  TestValidator.equals("version")(created.version)(body.version);
  TestValidator.equals("version_hash")(created.version_hash)(body.version_hash);
  TestValidator.equals("artifact_url")(created.artifact_url)(body.artifact_url);
  TestValidator.equals("framework")(created.framework)(body.framework);
  TestValidator.equals("metadata")(created.metadata)(body.metadata);

  // 3. Try duplicate create (should fail with unique constraint error)
  await TestValidator.error("duplicate ai_model_id+version fails")(async () => {
    return api.functional.advancedAI.aiModelVersions.post(connection, { body });
  });

  // 4. Try invalid ai_model_id (not uuid)
  await TestValidator.error("invalid ai_model_id format fails")(async () => {
    const invalidBody: IAiModelVersion.ICreate = {
      ai_model_id: "not-a-uuid" as string,
      version: "v2.0.0",
      version_hash: RandomGenerator.alphaNumeric(64),
      artifact_url: "s3://bucket/model_invalid_id.bin",
      framework: "TensorFlow",
    };
    return api.functional.advancedAI.aiModelVersions.post(connection, { body: invalidBody });
  });

  // 5. Minimal required fields
  const minimalBody: IAiModelVersion.ICreate = {
    ai_model_id,
    version: "v1.1.0",
    version_hash: RandomGenerator.alphaNumeric(64),
    artifact_url: `s3://bucket/model_v1.1.0-minimal.bin`,
    framework: "TensorFlow",
  };
  const minimalCreated = await api.functional.advancedAI.aiModelVersions.post(connection, { body: minimalBody });
  typia.assert(minimalCreated);
  TestValidator.equals("ai_model_id")(minimalCreated.ai_model_id)(minimalBody.ai_model_id);
  TestValidator.equals("version")(minimalCreated.version)(minimalBody.version);
}

