import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAiModelVersion } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiModelVersion";

/**
 * E2E 테스트: AI 모델 버전 정보를 ID로 수정 처리 및 변경 로그/감사 체인 확인
 *
 * - 비즈니스 목적: AiModelVersion 버전 엔트리의 주요 변경(버전명, 해시, artifact_uri, 프레임워크, 메타, 배포시각) 정상 반영 및 audit chain 검증
 * - 유효성 검증: 존재하지 않는 ID 혹은 변경 불가(immutable) 필드 시도시 정책·비즈니스 룰에 따라 오류 발생·거절
 *
 * 테스트 단계:
 * 1. 의존성: 모델 버전 엔티티 1건을 신규 생성한다.
 * 2. 정상 수정: update 허용 필드 일부(예: version_hash, metadata, deployed_at) 변경하여 putById 호출, 응답엔 변경 내용이 즉시 반영되고, "created_at" 등 불변필드는 불변임을 확인
 * 3. 변경 로그/감사: 변경 후 응답의 수정 필드 값 및 일시(audit chain)가 API 반환값에 반영되는지 확인
 * 4. 예외 - 미존재 id로 putById시 not found 오류나는지 확인
 * 5. 예외 - immutable 필드(ai_model_id, created_at 등) 강제 수정 요청시 비즈니스 정책상 거절/오류 처리되는지 확인(400/422 등)
 */
export async function test_api_advancedai_test_update_ai_model_version_by_id_with_audit_and_restriction_handling(connection: api.IConnection) {
  // 1. 선행: 모델버전 신규 생성
  const createInput: IAiModelVersion.ICreate = {
    ai_model_id: typia.random<string & tags.Format<"uuid">>(),
    version: "v1.0.0",
    version_hash: RandomGenerator.alphabets(16),
    artifact_url: `https://artifact.example.com/model-${RandomGenerator.alphaNumeric(6)}`,
    framework: "TensorFlow",
    metadata: JSON.stringify({ base_accuracy: 0.855, note: "original" }),
  };
  const created = await api.functional.advancedAI.aiModelVersions.post(connection, { body: createInput });
  typia.assert(created);

  // 2. 정상 업데이트 (허용 필드)
  const updateInput: IAiModelVersion.IUpdate = {
    version_hash: RandomGenerator.alphabets(32),
    metadata: JSON.stringify({ updated_accuracy: 0.872, note: "quick bugfix" }),
    deployed_at: new Date().toISOString() as any,
  };
  const updated = await api.functional.advancedAI.aiModelVersions.putById(connection, { id: created.id, body: updateInput });
  typia.assert(updated);
  // 변경 필드 적용 확인
  TestValidator.equals("updated version_hash")(updateInput.version_hash)(updated.version_hash);
  TestValidator.equals("updated metadata")(updateInput.metadata)(updated.metadata);
  TestValidator.equals("deployed_at")(updateInput.deployed_at)(updated.deployed_at);
  // 불변필드 확인
  TestValidator.equals("ai_model_id unchanged")(createInput.ai_model_id)(updated.ai_model_id);
  TestValidator.equals("created_at unchanged")(created.created_at)(updated.created_at);
  // version 등 미변경시 불변
  TestValidator.equals("version unchanged")(created.version)(updated.version);

  // 3. 변경 로그/감사 체인 관련(일단은 수정된 데이터가 직접 반영됐는지 검증)
  // 향후 확장: 내부 이력 API로 감사체인 확인시 보완 필요

  // 4. 예외: 미존재 id
  const fakeId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("Not found for non-existent id")(async () => {
    await api.functional.advancedAI.aiModelVersions.putById(connection, { id: fakeId, body: updateInput });
  });

  // 5. 예외: immutable 필드 수정 시도 (ai_model_id, created_at 등 불변)
  const illegalUpdate: IAiModelVersion.IUpdate = {
    // permitted-field이 아니므로 실제로는 반영되면 안됨. (api_model_id, created_at 등은 IUpdate에 존재하지 않으므로 불법 조작 불가)
    // 대신 update 내에서 존재하지 않는 필드 추가 검증 및 비허용 요청 거절 정책 보장 확인
    version_hash: RandomGenerator.alphabets(24),
  };
  // (IUpdate type상 ai_model_id, created_at 지정 불가. 실제로는 payload 조작을 통한 비정상 요청은 E2E 목적상 테스트 불가함)

  // 허용필드만 존재시 문제 없음, (불변 필드를 수정할 수 없으니 스킵)
}

