import { tags } from "typia";

/**
 * AI Training Dataset entity. Represents a single immutable, evidence-traceable
 * registry record for any dataset (internal or external) used in machine
 * learning model training or retraining.
 *
 * Complies with advanced regulatory, AI governance, and continuous learning
 * requirements: all datasets registered here are uniquely versioned,
 * cryptographically traceable (via schema_hash), and immutably reference their
 * external source URI for non-repudiation.
 *
 * Satisfies advanced requirements such as explainability (dataset provenance
 * for audit), compliance (model retraining/reproducibility), and future
 * AI-operations (dataset superset tracing). Business modules depend on this
 * type for model operations, continuous learning, and regulatory reporting.
 *
 * Each attribute is mapped directly to the 'ai_training_data' Prisma schema
 * columns. Multicultural and accessibility support (e.g. i18n dataset names) is
 * handled by higher modules.
 *
 * NO inline sub-objects permitted—all nested object types must be $ref, in
 * accordance with best OpenAPI practices and system mandate.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IAiTrainingData = {
  /**
   * Primary Key. Unique AI training dataset identifier.
   *
   * Implements evidence traceability and compliance requirements for machine
   * learning workflows.
   *
   * Corresponds to 'id' column in the Prisma 'ai_training_data' schema.
   */
  id: string & tags.Format<"uuid">;

  /**
   * Associated AI model's {@link ai_models.id}. Represents model linkage,
   * optional for stand-alone datasets.
   *
   * Alignment with AI governance requirements regarding data/model
   * provenance.
   *
   * Corresponds to 'ai_model_id' column in Prisma.
   */
  ai_model_id?: (string & tags.Format<"uuid">) | null;

  /**
   * Dataset name - Human-friendly identifier for this dataset version.
   *
   * Fulfills evidence and traceability requirement for all AI/ML input
   * material.
   *
   * Corresponds to 'name' column in Prisma.
   */
  name: string;

  /**
   * Version string of the dataset, e.g. '20240501', 'v2', etc.
   *
   * Supports dataset reproducibility for model retraining and regulatory
   * audits.
   *
   * Corresponds to 'version' column in Prisma.
   */
  version: string;

  /**
   * Source URI for the dataset. Immutable pointer to S3, GCS, or other data
   * lake/archive location.
   *
   * Provides strongest evidence for data and audit trail requirements. Never
   * stores blob inline—only the reference.
   *
   * Corresponds to 'source_uri' column.
   */
  source_uri: string;

  /**
   * Schema hash—cryptographically guarantees the column schema version at the
   * time of ingestion.
   *
   * Supports downstream integrity checking for explainability and legal
   * probe.
   *
   * Corresponds to 'schema_hash' in Prisma.
   */
  schema_hash: string;

