   *
   * Corresponds to 'created_at' column in Prisma.
   */
  created_at: string & tags.Format<"date-time">;
};
export namespace IAiTrainingData {
  /**
   * AI 훈련 데이터셋 목록/검색 요청 스키마입니다. 데이터셋명, 버전, 모델, 생성일, 레코드수, 소스URI, 해시 등 검색과
   * 페이징을 지원합니다. 사용처: 데이터 거버넌스, 증적, MLOps 대시보드, AI 컴플라이언스 보고 등.
