import { tags } from "typia";

export namespace IPage {
  /**
   * Pagination information accompanying paginated result types; standard
   * IPage.IPagination structure for uniform response metadata across
   * endpoints.
   */
  export type IPagination = {
    /** Current page number in the paginated result set. */
    current: number &
      tags.Type<"int32"> &
      tags.JsonSchemaPlugin<{
        format: "uint32";
      }>;

    /** Maximum number of records per page. Default is usually 100. */
    limit: number &
      tags.Type<"int32"> &
      tags.JsonSchemaPlugin<{
        format: "uint32";
      }>;

    /** Total number of records in the database or satisfying current filter. */
    records: number &
      tags.Type<"int32"> &
      tags.JsonSchemaPlugin<{
        format: "uint32";
      }>;

    /** Total number of pages in the result set. */
    pages: number &
      tags.Type<"int32"> &
      tags.JsonSchemaPlugin<{
        format: "uint32";
      }>;
  };
}

