import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAiTrainingData } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiTrainingData";
import type { IPageIAiTrainingData } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIAiTrainingData";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate advanced listing, searching, and permission-checking logic for AI training data registry (ai_training_data).
 *
 * This test verifies that dataset registry filtering, pagination, and permission enforcement work as intended. It covers:
 * - Registry creation with varied names, versions, sources, and model associations
 * - Paginated queries and boundary/overflow page handling
 * - Filtering by dataset name, model association, and unique fields
 * - Handling of non-matching and over-specific filters (should yield zero results)
 * - Permissions: Only authorized users can list/search registries
 * - Robustness to empty queries and overload (large result set)
 * - Response structure (IPageIAiTrainingData + expected data shape)
 *
 * Test plan:
 * 1. Create multiple distinct AI training data registries (different names, models).
 * 2. Query list without filters; verify all registries are returned in expected order/page.
 * 3. Paginate: Request with page/limit, including overflow pages.
 * 4. Filter by name (exact/partial match), ai_model_id, version, schema_hash, record_count, created_at, etc.
 * 5. Use non-matching filters (e.g. wrong name, model) and expect no results.
 * 6. Query with empty filter (should act as unfiltered list, all records paginated).
 * 7. Permission edge case: (if possible, switch user or clear perms), confirm unauthorized users get rejection.
 * 8. Robustness: Query with extreme/invalid pagination (e.g. page=9999, limit=1).
 * 9. Validate response type and all required fields on item and page.
 */
export async function test_api_advancedai_test_list_ai_training_data_with_advanced_filtering_and_permissions(connection: api.IConnection) {
  // 1. Create a set of diverse AI training data registries
  const registries: IAiTrainingData[] = [];
  for (let i = 0; i < 5; ++i) {
    const reg = await api.functional.advancedAI.aiTrainingData.post(connection, {
      body: {
        ai_model_id: i % 2 === 0 ? typia.random<string & tags.Format<"uuid">>() : null,
        name: `dataset_${i}_` + RandomGenerator.alphabets(5),
        version: `v${i + 1}.0.${RandomGenerator.alphabets(2)}`,
        source_uri: `s3://open-data/ai_training_${i}_${Date.now()}`,
        schema_hash: RandomGenerator.alphaNumeric(32),
        record_count: 100 + i * 10,
      } satisfies IAiTrainingData.ICreate
    });
    typia.assert(reg);
    registries.push(reg);
  }

  // 2. Query with no filter (should retrieve all, paginated)
  let page = await api.functional.advancedAI.aiTrainingData.patch(connection, {
    body: { page: 1, limit: 10 },
  });
  typia.assert(page);
  TestValidator.predicate("Registry count matches")(page.data.length >= 5);

  // 3. Pagination boundary cases
  let p2 = await api.functional.advancedAI.aiTrainingData.patch(connection, { body: { page: 2, limit: 3 } });
  typia.assert(p2);
  TestValidator.predicate("Pagination boundary")(p2.pagination.current === 2);

  // 4. Filter by dataset name (partial match)
  const qname = registries[2].name.substring(0, 6);
  let byName = await api.functional.advancedAI.aiTrainingData.patch(connection, {
    body: { name: qname },
  });
  typia.assert(byName);
  TestValidator.predicate("Name filter")(byName.data.some(x => x.name.includes(qname)));

  // 5. Filter by ai_model_id
  let byModel = await api.functional.advancedAI.aiTrainingData.patch(connection, {
    body: { ai_model_id: registries[0].ai_model_id ?? undefined },
  });
  typia.assert(byModel);
  if (registries[0].ai_model_id)
    TestValidator.predicate("Model filter")(byModel.data.every(x => x.ai_model_id === registries[0].ai_model_id));

  // 6. Non-matching filter (no result)
  let nonMatch = await api.functional.advancedAI.aiTrainingData.patch(connection, {
    body: { name: "no_such_dataset_" + RandomGenerator.alphabets(8) },
  });
  typia.assert(nonMatch);
  TestValidator.equals("no match filter count")(0)(nonMatch.data.length);

  // 7. Empty filter (should list them all, paginated)
  let empty = await api.functional.advancedAI.aiTrainingData.patch(connection, { body: {} });
  typia.assert(empty);
  TestValidator.predicate("empty filter returns all")(empty.data.length >= 5);

  // 8. Very large/overflow page
  let overflow = await api.functional.advancedAI.aiTrainingData.patch(connection, { body: { page: 9999, limit: 1 } });
  typia.assert(overflow);
  TestValidator.equals("overflow page is empty")(overflow.data.length === 0 || overflow.pagination.current > overflow.pagination.pages)(true);

  // 9. Permission check (simulate unauthorized user - if infra supports)
  // If the connection object can be modified to remove/replace token:
  /*
  const unauthConn = { ...connection, headers: { ...connection.headers } };
  delete unauthConn.headers.Authorization;
  await TestValidator.error("unauthorized fails")(() =>
    api.functional.advancedAI.aiTrainingData.patch(unauthConn, { body: {} })
  );
  */
}

