  active: boolean;

  /** 룰 레코드 생성시각(불변증거) */
  created_at: string & tags.Format<"date-time">;

  /** AI/ML 할인 적용 시 해당 모델 버전(@ref ai_model_versions.id) 참조. 일반 고정 정책은 null. */
  ai_model_version_id?: (string & tags.Format<"uuid">) | null;
};
export namespace IDiscountRule {
  /**
   * 할인 룰 목록 조회 시(body 기반) 필터/검색 조건 전달용 타입입니다.
