     *
     * 이 값으로 다양한 할인 유형(rule type) 기반 분류·검색이 가능합니다.
     */
    type?: string | null;

    /**
     * 활성화/비활성화 룰 여부 필터.
     *
     * True면 현재 적용 가능, false면 과거 불가/비활성 룰만 조회. Any/무관이면 null.
     */
    active?: boolean | null;

    /**
     * 생성일(DateTime) 범위에 대한 쿼리용 배열. ['2025-01-01T00:00:00Z',
