import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscountRule } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscountRule";
import type { IPageIDiscountRule } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscountRule";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * 테스트 목적: 관리자가 할인 룰(Discount Rule) 목록을 페이징, 정렬, 필터로 조회하고 각 결과가 정확하고 Robust한지 검증한다.
 *
 * 주요 검증 포인트 및 절차:
 * 1. 무필터 전체조회 시 적어도 한 건 이상의 할인 룰이 반환되는지 확인
 * 2. 필터(예: type, campaign_id, active, created_at_range) 조합을 적용하면, 반환 레코드가 해당 조건을 모두 만족하는지 반복 검증
 * 3. 페이지네이션 current/limit 변경 시 next page가 정확히 이어지고, 페이지 정보(pagination) 메타데이터가 올바른지 확인
 * 4. 비정상 파라미터(잘못된 날짜형식, page=0 등)나 존재하지 않는 필터 값 입력 시 적절한 오류 반환을 확인
 * 
 * step-by-step
 * - 사전: 샘플 할인 룰 데이터는 테스트 환경에 충분히 존재한다고 가정
 * - 1) nothing filter로 전체 조회 ➔ 레코드 1건 이상, 페이징 정보 확인
 * - 2) 임의 type, active 값 필터로 조회 후 해당 조건 체크
 * - 3) created_at_range 올바른 값, 잘못된 값 조합 테스트
 * - 4) 정렬 및 페이지네이션(current, limit) 변경 loop하며 next page 연속성, 전체건수 체크
 * - 5) campaign_id/존재하지 않는 필터, 이상 case로 오류(또는 empty) 처리 확인
 */
export async function test_api_paymentsDiscounts_discountRules_patch(
  connection: api.IConnection,
) {
  // 1. 무필터 전체조회
  const allRules = await api.functional.paymentsDiscounts.discountRules.patch(connection, {
    body: {},
  });
  typia.assert(allRules);
  TestValidator.predicate('최소 1건이 반환되어야')(allRules.data.length > 0);

  // 2. type, active 필터
  const filterType = allRules.data[0]?.type;
  const filterActive = allRules.data[0]?.active;
  if (filterType !== undefined && filterActive !== undefined) {
    const filtered = await api.functional.paymentsDiscounts.discountRules.patch(connection, {
      body: { type: filterType, active: filterActive },
    });
    typia.assert(filtered);
    for (const rule of filtered.data) {
      TestValidator.equals('type')(filterType)(rule.type);
      TestValidator.equals('active')(filterActive)(rule.active);
    }
  }

  // 3. created_at_range (정상/비정상)
  const date = allRules.data[0]?.created_at;
  if (date) {
    const range = [date, date];
    const byDate = await api.functional.paymentsDiscounts.discountRules.patch(connection, {
      body: { created_at_range: range },
    });
    typia.assert(byDate);
    for (const rule of byDate.data) {
      TestValidator.equals('created_at')(date)(rule.created_at);
    }
    // 잘못된 형식 (배열길이 부족)
    await TestValidator.error('created_at_range invalid length')(async () =>
      api.functional.paymentsDiscounts.discountRules.patch(connection, {
        body: { created_at_range: [date] },
      })
    );
  }

  // 4. pagination current/limit
  const paged = await api.functional.paymentsDiscounts.discountRules.patch(connection, {
    body: {},
  });
  typia.assert(paged);
  if (paged.pagination.pages > 1) {
    const paged2 = await api.functional.paymentsDiscounts.discountRules.patch(connection, {
      body: {},
    });
    typia.assert(paged2);
    TestValidator.notEquals('다른 페이지')(paged.data[0].id)(paged2.data[0]?.id);
  }
  // 5. 존재하지 않는 값 필터 (empty 반환)
  const none = await api.functional.paymentsDiscounts.discountRules.patch(connection, {
    body: { type: 'none-exists-type' },
  });
  typia.assert(none);
  TestValidator.equals('empty result')(0)(none.data.length);
}

