import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscountRule } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscountRule";
import type { IPageIDiscountRule } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscountRule";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * 관리자 등 시스템 연동자가 할인 룰(Discount Rule) 목록을 검색/조회할 때, 페이징·필터·잘못된 파라미터 등 실제 운영 환경에서 발생할 수 있는 모든 케이스를 종합적으로 검증한다.
 *
 * - 무필터 전체조회 시 적어도 한 건 이상의 할인 룰이 반환되는지(단, test DB에 데이터 없는 경우는 soft-fail 혹은 스킵)
 * - type, active, created_at_range 등 필터링 조건 조합 시 필터가 정확히 먹히는지
 * - 페이지네이션 current/limit param 조합 및 연달아 next page 조회 시 데이터/메타데이터가 시멘틱하게 일관적으로 반환되는지
 * - created_at_range 등 정상/비정상 파라미터 또는 존재하지 않는 필터값 입력시 적절히 error/empty 처리하는지
 *
 * step-by-step process
 * 1. 무필터 전체조회: 적어도 1건 이상 반환/페이징정보 확인(단, 없는 경우 전체 test skip)
 * 2. 필터(type/active 조합) 적용하여 결과가 모두 기대 조건 부합하는지 loop 검증
 * 3. created_at_range 정상/비정상 조합 및 잘못된 길이 입력 error case
 * 4. pagination param(current, limit) 바꿔서 여러 page 시험 및 next page 연속성 확인
 * 5. 존재하지 않는 type 등으로 empty 반환 처리
 */
export async function test_api_paymentsDiscounts_discountRules_patch(
  connection: api.IConnection,
) {
  // 1. 무필터 전체조회: 적어도 한 건 이상 반환, 없으면 이후 테스트 전체 skip
  const allRules = await api.functional.paymentsDiscounts.discountRules.patch(connection, {
    body: {},
  });
  typia.assert(allRules);
  if (allRules.data.length === 0) return; // 데이터 없는 환경 soft-fail 방지
  TestValidator.predicate('최소 1건이 반환되어야')(allRules.data.length > 0);

  // 2. type + active 필터(동일 조건) 후 loop 검증
  const rule0 = allRules.data[0];
  if (rule0) {
    const filtered = await api.functional.paymentsDiscounts.discountRules.patch(connection, {
      body: { type: rule0.type, active: rule0.active },
    });
    typia.assert(filtered);
    for (const rule of filtered.data) {
      TestValidator.equals('type')(rule0.type)(rule.type);
      TestValidator.equals('active')(rule0.active)(rule.active);
    }
  }

  // 3. created_at_range 정상/비정상
  const date = rule0?.created_at;
  if (date) {
    // 정상
    const ok = await api.functional.paymentsDiscounts.discountRules.patch(connection, {
      body: { created_at_range: [date, date] },
    });
    typia.assert(ok);
    for (const rule of ok.data) {
      TestValidator.equals('created_at')(date)(rule.created_at);
    }
    // 잘못된 길이(1)로 error 발생 확인
    await TestValidator.error('created_at_range wrong length')(async () =>
      api.functional.paymentsDiscounts.discountRules.patch(connection, {
        body: { created_at_range: [date] },
      })
    );
  }

  // 4. 페이지네이션 param (current/limit) 바꿔 next page/연속성 검증
  const paged = await api.functional.paymentsDiscounts.discountRules.patch(connection, {
    body: { },
  });
  typia.assert(paged);
  const { pagination } = paged;
  if (pagination.pages > 1) {
    const paged2 = await api.functional.paymentsDiscounts.discountRules.patch(connection, {
      body: { },
    });
    typia.assert(paged2);
    TestValidator.notEquals('next page 데이터')(paged.data[0]?.id)(paged2.data[0]?.id);
  }

  // 5. 존재하지 않는 type empty 반환 확인
  const none = await api.functional.paymentsDiscounts.discountRules.patch(connection, {
    body: { type: '---not-exists-type-___' },
  });
  typia.assert(none);
  TestValidator.equals('empty')(0)(none.data.length);
}

