 * Security is enforced for administrative and system contexts. All read
 * operations are audited for compliance and evidence tracking, with
 * parameterized controls on result size, frequency, and operator context.
 * Related endpoints: GET/POST/PUT/DELETE rules, mapping to discount/campaign
 * usage.
 *
 * @param props.connection
 * @param props.body Discount rule filter/search parameters (type, campaign,
 *   status, AI, etc) and paging info.
 * @path /paymentsDiscounts/discountRules
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export async function patch(
  connection: IConnection,
  props: patch.Props,
): Promise<patch.Response> {
  return !!connection.simulate
    ? patch.simulate(connection, props)
    : PlainFetcher.fetch(
        {
          ...connection,
          headers: {
            ...connection.headers,
            "Content-Type": "application/json",
          },
        },
        {
          ...patch.METADATA,
          path: patch.path(),
          status: null,
        },
        props.body,
      );
}
export namespace patch {
  export type Props = {
    /**
     * Discount rule filter/search parameters (type, campaign, status, AI,
     * etc) and paging info.
     */
    body: IDiscountRule.IRequest;
  };
  export type Body = IDiscountRule.IRequest;
  export type Response = IPageIDiscountRule;

  export const METADATA = {
    method: "PATCH",
    path: "/paymentsDiscounts/discountRules",
    request: {
      type: "application/json",
      encrypted: false,
    },
    response: {
      type: "application/json",
      encrypted: false,
    },
  } as const;

  export const path = () => "/paymentsDiscounts/discountRules";
  export const random = (
    g?: Partial<typia.IRandomGenerator>,
  ): IPageIDiscountRule => typia.random<IPageIDiscountRule>(g);
  export const simulate = (
    connection: IConnection,
    props: patch.Props,
  ): Response => {
    const assert = NestiaSimulator.assert({
      method: METADATA.method,
      host: connection.host,
      path: patch.path(),
      contentType: "application/json",
    });
    try {
      assert.body(() => typia.assert(props.body));
    } catch (exp) {
      if (!typia.is<HttpError>(exp)) throw exp;
      return {
        success: false,
        status: exp.status,
        headers: exp.headers,
        data: exp.toJSON().message,
      } as any;
    }
    return random(
      "object" === typeof connection.simulate && null !== connection.simulate
        ? connection.simulate
        : undefined,
    );
  };
