import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscountRule } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscountRule";
import type { IPageIDiscountRule } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscountRule";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * 인증되지 않거나 권한이 없는 사용자가 할인 룰 목록(정책 리스트) 정보를 조회 시 정상적으로 인증/인가 에러가 발생하는지 검증
 *
 * 비즈니스 맥락:
 * - 할인 룰(DiscountRule)은 관리자·시스템 권한이 필요한 민감 리소스이므로
 *   일반 사용자 혹은 미로그인 상태에서는 접근 차단, 에러(401/403) 반환 필수
 *
 * 테스트 단계:
 * 1. 인증 없는 connection으로 할인 룰 검색 API(PATCH /paymentsDiscounts/discountRules) 호출 시도
 * 2. 결과로 HttpError가 발생하며, status가 401 혹은 403인지 확인
 * 3. 빈 body뿐만 아니라 여러 필터 조합(예: campaign_id, 활성화 등) 시도해 일관적 거부 보장
 */
export async function test_api_paymentsDiscounts_test_list_discount_rules_unauthorized_access(
  connection: api.IConnection,
) {
  // 1. 인증 없는 connection으로 빈 필터 조회 시도 → 401/403 에러 검증
  await TestValidator.error("미인증(disabled auth) 상태로 할인 룰(정책) 조회 시 401/403 오류 반환해야 함")(
    async () => {
      try {
        await api.functional.paymentsDiscounts.discountRules.patch(connection, { body: {} });
      } catch (exp) {
        // HttpError 타입이면서 status가 401 또는 403이어야 한다
        if (
          typeof exp === "object" &&
          exp !== null &&
          "status" in exp &&
          (exp.status === 401 || exp.status === 403)
        ) {
          return;
        }
        throw exp;
      }
      throw new Error("권한/인증이 없는 connection에도 조회가 허용되었습니다. (실패)");
    },
  );

  // 2. 일부 필터(campaign_id/type 등) 지정 시도도 동일하게 인증 에러 나는지 확인
  await TestValidator.error("미인증 + 필터조건(campaign_id 등)으로 조회시도도 거부되어야 함")(
    async () => {
      try {
        await api.functional.paymentsDiscounts.discountRules.patch(connection, {
          body: {
            campaign_id: typia.random<string & tags.Format<"uuid">>(),
            type: "percentage",
            active: true,
            created_at_range: [
              "2025-01-01T00:00:00Z",
              "2025-12-31T23:59:59Z",
            ],
          },
        });
      } catch (exp) {
        if (
          typeof exp === "object" &&
          exp !== null &&
          "status" in exp &&
          (exp.status === 401 || exp.status === 403)
        ) {
          return;
        }
        throw exp;
      }
      throw new Error("미인증 + 필터조건으로도 정책 데이터가 조회되어 실패");
    },
  );
}

