import { tags } from "typia";

/**
 * 할인 룰 개별 객체(`discount_rules`)
 *
 * - 캠페인, 할인 방식(type), 금액/비율 값, 활성 상태, AI모델 등과 연결되는 정책 기록
 * - 컴플라이언스·트러블슈팅·동적 가격 정책 관리 등 여러 엔터프라이즈 백엔드에서 핵심 기준
 * - 모든 필드는 Prisma DB 컬럼 주석에 따라 문서화/정의
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IDiscountRule = {
  /** 할인 룰의 유일 식별자(Primary key). */
  id: string & tags.Format<"uuid">;

  /** 해당 룰이 속해 있는 캠페인의 참조(ID). */
  campaign_id?: (string & tags.Format<"uuid">) | null;

  /** 이 할인 룰의 적용방식을 나타냅니다. (e.g., 'percentage', 'fixed', 'ML-driven') */
  type: string;

  /** 할인 계산에 사용되는 코어 수치(퍼센트/고정/AI적용 등). */
  value: number &
    tags.JsonSchemaPlugin<{
      format: "double";
    }>;

  /** 해당 할인룰의 활성화(적용 가능) 여부. false면 과거 이력·감사 용도만 사용. */
  active: boolean;

  /** 룰 레코드 생성시각(불변증거) */
  created_at: string & tags.Format<"date-time">;

  /** AI/ML 할인 적용 시 해당 모델 버전(@ref ai_model_versions.id) 참조. 일반 고정 정책은 null. */
  ai_model_version_id?: (string & tags.Format<"uuid">) | null;
};
export namespace IDiscountRule {
  /**
   * 새로운 할인 룰을 등록(POST)할 때 사용하는 입력 타입입니다.
   *
   * - 캠페인, 정책 방침(타입), 값(금액/비율), 활성화유무, AI 정책 적용여부 등 Prisma 설계와 동치
   * - 필드를 명확히 분리하여 비즈니스/AI 정책 확장 및 감사 적용 용이하게 설계합니다.
   */
  export type ICreate = {
    /**
     * 할인 룰이 속할 캠페인의 UUID입니다. (선택사항)
     *
     * 대규모 마케팅, 시즌 이벤트, 혹은 특정 정책 묶음 단위에 바인딩 시 필요.
     */
    campaign_id?: (string & tags.Format<"uuid">) | null;

    /**
     * 할인 룰의 적용 방식(필수, 예시: 'percentage', 'fixed', 'ML-driven')
     *
     * 정책 생성시 항상 지정하며, 정책 룰 관리·AI연동 등에서 강제.
     */
    type: string;

    /** 룰의 수치 값(고정할인: -1000, 퍼센트: 15, AI모델: 예측값) */
    value: number &
      tags.JsonSchemaPlugin<{
        format: "double";
      }>;

    /** 등록시 활성 상태(적용 가능 여부). 최초 등록시 true가 대부분이나 과거 정책 이관 등 예외도 있음. */
    active: boolean;

    /** AI/ML 기반 할인정책 적용 시 사용되는 모델 버전의 식별자(UUID). 고정/정적 룰이면 null. */
    ai_model_version_id?: (string & tags.Format<"uuid">) | null;
  };
}

