 *
 * 1. 신규 할인 룰 생성(POST)을 통해 고유 id를 확보
 * 2. 해당 id로 할인 룰 상세 조회를 수행 (GET)
 *    - 응답의 필드 값들이 생성시 입력값·정책과 일치하는지 검증
 * 3. 존재하지 않는 ID로 조회시 404 에러 발생을 검증
 * 4. (실제 권한 시스템 연동시) 토큰 미포함·권한이 낮은 계정·시스템외부 접근 등 권한 통제 시나리오도 체크
 *
 * @business 할인정책 배포/관리시 감시/증거 수집·이상 행동 탐지 등에 핵심
 * @reason 할인함수 또는 캠페인 정책 변경사항의 실시간 감시 또는 현장 복구 대응 핵심요소
 */
export async function test_api_paymentsDiscounts_discountRules_getById(
  connection: api.IConnection,
) {
  // 1. 신규 할인 룰 생성(테스트용 입력값 활용)
  const createInput: IDiscountRule.ICreate = {
    type: "percentage",
    value: 15.5,
    active: true,
    campaign_id: null,
    ai_model_version_id: null,
  };
  const created: IDiscountRule = await api.functional.paymentsDiscounts.discountRules.post(connection, { body: createInput });
  typia.assert(created);

  // 2. 실제 ID로 상세조회 및 값 비교 검증
  const found: IDiscountRule = await api.functional.paymentsDiscounts.discountRules.getById(connection, { id: created.id });
  typia.assert(found);
  TestValidator.equals("fetched discount rule matches created")(
    { type: createInput.type, value: createInput.value, active: createInput.active, campaign_id: createInput.campaign_id, ai_model_version_id: createInput.ai_model_version_id }
  )(
    { type: found.type, value: found.value, active: found.active, campaign_id: found.campaign_id, ai_model_version_id: found.ai_model_version_id }
  );

  // 3. 존재하지 않는 ID 조회 (임의 UUID)
  await TestValidator.error("404 not found for invalid id")(async () => {
    await api.functional.paymentsDiscounts.discountRules.getById(connection, { id: typia.random<string & tags.Format<"uuid">>() });
  });

