import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscountRule } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscountRule";

/**
 * Validate the creation of discount rule configurations in the paymentsDiscounts domain.
 * 
 * This test ensures:
 * 1. A new discount rule can be successfully created with all required fields.
 * 2. Validation failure occurs when required fields are missing or invalid (e.g., negative value, blank type).
 * 3. (If applicable) Uniqueness constraint triggers error when attempting to create a rule with the same parameters as an existing rule.
 *
 * Steps:
 * 1. Attempt to create a discount rule with valid values.
 * 2. Try to create a rule missing required fields (should fail validation).
 * 3. Try to create a rule with invalid data types or nonsensical values (e.g., negative value for percentage type).
 * 4. Attempt to create another rule with the same unique constraint (should fail if uniqueness enforced).
 */
export async function test_api_paymentsDiscounts_test_create_discount_rule_with_validation_and_uniqueness(
  connection: api.IConnection,
) {
  // 1. Create a valid discount rule
  const discountType = "percentage";
  const discountValue = 15.0;
  const campaignId = typia.random<string & tags.Format<"uuid">>();
  const result = await api.functional.paymentsDiscounts.discountRules.post(connection, {
    body: {
      campaign_id: campaignId,
      type: discountType,
      value: discountValue,
      active: true,
      ai_model_version_id: null,
    } satisfies IDiscountRule.ICreate,
  });
  typia.assert(result);
  TestValidator.equals("type")(discountType)(result.type);
  TestValidator.equals("value")(discountValue)(result.value);
  TestValidator.equals("campaign_id")(campaignId)(result.campaign_id);

  // 2. Validation error: missing required 'type'
  await TestValidator.error("missing required 'type' should fail")(() =>
    api.functional.paymentsDiscounts.discountRules.post(connection, {
      body: {
        // type: omitted
        value: 10,
        active: true,
      } as any, // This would break type safety, so skip actual omission in TS but acknowledge case.
    })
  );
  // 2b. Validation error: invalid value (negative)
  await TestValidator.error("negative value should fail")(() =>
    api.functional.paymentsDiscounts.discountRules.post(connection, {
      body: {
        type: "fixed",
        value: -100,
        active: true,
      } satisfies IDiscountRule.ICreate,
    })
  );
  // 3. Attempt duplication: create same rule again
  await TestValidator.error("duplicate campaign_id + type + value should fail if unique")(() =>
    api.functional.paymentsDiscounts.discountRules.post(connection, {
      body: {
        campaign_id: campaignId,
        type: discountType,
        value: discountValue,
        active: true,
        ai_model_version_id: null,
      } satisfies IDiscountRule.ICreate,
    })
  );
}

