import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscountRule } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscountRule";

/**
 * 할인 룰(Discount Rule) 업데이트 검증 E2E 테스트
 *
 * 할인 정책 관리자의 워크플로우를 검증한다. 할인 룰을 생성 후, 다양한 변형 및 유효·무효 케이스로 업데이트 상황과 에러 대응을 검증한다.
 *
 * 1. 신규 할인 룰을 정상 등록한다.
 * 2. 등록된 할인 룰의 필드(예: campaign_id, value, active, ai_model_version_id 일부)를 정상적으로 변경하여 업데이트 API가 적용됨을 확인한다.
 * 3. value에 음수 등 유효하지 않은 값, 존재하지 않는 campaign_id나 ai_model_version_id 등으로 업데이트하여 유효성(Validation) 에러 발생을 기대한다.
 * 4. type 혹은 created_at 등 불변 필드에 대한 수정 시도가 거절되는지 테스트한다.
 * 5. 존재하지 않는 id에 대해 업데이트를 요청했을 때 404 Not Found 응답을 기대한다.
 */
export async function test_api_paymentsDiscounts_test_update_discount_rule_with_success_and_failure(connection: api.IConnection) {
  // 1. 신규 할인 룰 등록
  const created = await api.functional.paymentsDiscounts.discountRules.post(connection, {
    body: {
      type: 'percentage',
      value: 10,
      active: true
    } satisfies IDiscountRule.ICreate
  });
  typia.assert(created);

  // 2. 필드 정상 업데이트 (campaign_id, value, active, ai_model_version_id)
  const updated = await api.functional.paymentsDiscounts.discountRules.putById(connection, {
    id: created.id,
    body: {
      campaign_id: typia.random<string & tags.Format<'uuid'>>(),
      value: 15.5,
      active: false,
      ai_model_version_id: typia.random<string & tags.Format<'uuid'>>()
    } satisfies IDiscountRule.IUpdate
  });
  typia.assert(updated);
  TestValidator.equals('id 동일')(updated.id)(created.id);
  TestValidator.equals('value 수정')(updated.value)(15.5);
  TestValidator.equals('active 수정')(updated.active)(false);

  // 3. 유효하지 않은 값(value에 음수) 업데이트 (실패 예상)
  await TestValidator.error('value 음수 시 에러')(() =>
    api.functional.paymentsDiscounts.discountRules.putById(connection, {
      id: created.id,
      body: { value: -99 } satisfies IDiscountRule.IUpdate
    })
  );

  // 4. 불변 필드 변경 시도 (type, created_at 등 허용 안됨)
  // IDiscountRule.IUpdate 타입에는 불변 필드가 없으므로(실제 API에서 막음), 요청 필드를 강제로 넘겨도 타입오류 발생. 해당 케이스는 스킵.

  // 5. 존재하지 않는 id 업데이트 시 404 에러
  await TestValidator.error('존재하지 않는 id 시 404')(() =>
    api.functional.paymentsDiscounts.discountRules.putById(connection, {
      id: typia.random<string & tags.Format<'uuid'>>(),
      body: { value: 100 } satisfies IDiscountRule.IUpdate
    })
  );
}

