import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscountRule } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscountRule";

/**
 * Test deletion of discount rules (idempotency and permissions).
 *
 * This test validates the following:
 * 1. A discount rule can be created and deleted by ID.
 * 2. Once deleted, attempting to delete again gives proper error/idempotent response.
 * 3. Attempting to delete a non-existent discount rule yields the expected error.
 * 4. Deletion without sufficient access rights is denied (authorization error).
 *
 * Steps:
 * 1. Create a new discount rule (using paymentsDiscounts.discountRules.post).
 * 2. Delete the created discount rule (paymentsDiscounts.discountRules.eraseById).
 * 3. Attempt to delete the rule again, expect either success (idempotent) or a not found error.
 * 4. Attempt to delete a random (non-existent) rule, expect a not found error.
 * 5. (If supported) Simulate a connection lacking permissions, attempt deletion, and expect an authorization error.
 */
export async function test_api_paymentsDiscounts_test_delete_discount_rule_idempotency_and_permissions(
  connection: api.IConnection,
) {
  // 1. Create a discount rule to delete
  const createInput: IDiscountRule.ICreate = {
    type: "percentage",
    value: 10,
    active: true,
    campaign_id: null,
    ai_model_version_id: null,
  };
  const rule = await api.functional.paymentsDiscounts.discountRules.post(connection, { body: createInput });
  typia.assert(rule);

  // 2. Delete the discount rule by ID
  await api.functional.paymentsDiscounts.discountRules.eraseById(connection, { id: rule.id });

  // 3. Attempt to delete again, expect idempotent success or a not found error
  let doubleDeleteError = null;
  try {
    await api.functional.paymentsDiscounts.discountRules.eraseById(connection, { id: rule.id });
  } catch (err) {
    doubleDeleteError = err;
    if (err.status !== 404 && err.status !== 400 && err.status !== 403) {
      throw new Error("Unexpected error status when deleting already deleted rule: " + err.status);
    }
  }

  // 4. Attempt deletion of a random (never-created) rule
  let notFoundError = null;
  const fakeRuleId = typia.random<string & tags.Format<"uuid">>();
  try {
    await api.functional.paymentsDiscounts.discountRules.eraseById(connection, { id: fakeRuleId });
  } catch (err) {
    notFoundError = err;
    if (err.status !== 404 && err.status !== 400 && err.status !== 403) {
      throw new Error("Unexpected error status deleting non-existent rule: " + err.status);
    }
  }

  // 5. Attempt deletion without permissions (simulate connection with insufficient rights)
  if (connection.headers && connection.headers.Authorization !== undefined) {
    // Simulate invalid/expired token
    const unauthorizedConn = { ...connection, headers: { ...connection.headers, Authorization: "Bearer invalid_token" } };
    let permissionError = null;
    try {
      await api.functional.paymentsDiscounts.discountRules.eraseById(unauthorizedConn, { id: rule.id });
    } catch (err) {
      permissionError = err;
      if (err.status !== 401 && err.status !== 403) {
        throw new Error("Expected authorization error status, got " + err.status);
      }
    }
    if (!permissionError) {
      throw new Error("Expected authorization error but succeeded in unauthorized deletion.");
    }
  }
}

