    Array.isArray(page1.data)
  );

  // Prepare for deeper queries if data is non-empty
  const sample = page1.data[0];
  let substring: string | undefined;
  if (sample) {
    substring = sample.name.substring(0, 3);
  }

  // 2. Filter by partial name (if data exists)
  if (substring) {
    const pageByName = await api.functional.paymentsDiscounts.discountCampaigns.patch(connection, {
      body: { name: substring },
    });
    typia.assert(pageByName);
    for (const campaign of pageByName.data) {
      TestValidator.predicate("name contains substring")(
        campaign.name.includes(substring)
      );
    }
  }

  // 3. Filter by active=true and active=false
  // Try both, but only validate if items returned, to avoid false assertion failure
  for (const bool of [true, false]) {
    const pageActive = await api.functional.paymentsDiscounts.discountCampaigns.patch(connection, {
      body: { active: bool },
    });
    typia.assert(pageActive);
    if (pageActive.data.length > 0)
      for (const campaign of pageActive.data) {
        TestValidator.equals("active filter matches")(bool)(campaign.active);
      }
  }

  // 4. Filter by start_at_range, created_at_range
  if (sample) {
    // Compute min/max for ranges using available data
    const all = page1.data;
    const startAts = all.map(x => x.start_at).sort();
    const createdAts = all.map(x => x.created_at).sort();
    const startRange = [startAts[0], startAts[startAts.length - 1]];
    const createdRange = [createdAts[0], createdAts[createdAts.length - 1]];

    // Start_at_range
    const pageByStartRange = await api.functional.paymentsDiscounts.discountCampaigns.patch(connection, {
      body: { start_at_range: startRange as [string, string] },
    });
    typia.assert(pageByStartRange);
    for (const c of pageByStartRange.data) {
      TestValidator.predicate("start_at in range")(
        c.start_at >= startRange[0] && c.start_at <= startRange[1]
      );
    }

    // Created_at_range
    const pageByCreatedRange = await api.functional.paymentsDiscounts.discountCampaigns.patch(connection, {
      body: { created_at_range: createdRange as [string, string] },
    });
    typia.assert(pageByCreatedRange);
    for (const c of pageByCreatedRange.data) {
      TestValidator.predicate("created_at in range")(
        c.created_at >= createdRange[0] && c.created_at <= createdRange[1]
      );
    }
  }

  // 5. Combine filters (name + active + date)
  if (sample) {
    const complexFilters = {
      name: substring!,
      active: sample.active,
      start_at_range: [sample.start_at, sample.start_at] as [string, string],
      created_at_range: [sample.created_at, sample.created_at] as [string, string],
    };
    const pageCombo = await api.functional.paymentsDiscounts.discountCampaigns.patch(connection, {
      body: complexFilters,
    });
    typia.assert(pageCombo);
    for (const c of pageCombo.data) {
      TestValidator.predicate("intersection filter - name")(
        c.name.includes(substring!)
      );
      TestValidator.equals("intersection filter - active")(sample.active)(c.active);
      TestValidator.equals("intersection filter - start_at")(sample.start_at)(c.start_at);
      TestValidator.equals("intersection filter - created_at")(sample.created_at)(c.created_at);
    }
  }

  // 6. Invalid parameters: start_at_range too short and wrong types
  await TestValidator.error("1-item date range rejected")(() =>
    api.functional.paymentsDiscounts.discountCampaigns.patch(connection, {
      body: { start_at_range: [new Date().toISOString()] },
    })
  );

  await TestValidator.error("wrong type name field")(() =>
    api.functional.paymentsDiscounts.discountCampaigns.patch(connection, {
      body: { name: 123 as any },
    })
  );

  await TestValidator.error("malformed active field")(() =>
    api.functional.paymentsDiscounts.discountCampaigns.patch(connection, {
      body: { active: "notabool" as any },
    })
  );
}

