import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscountRule } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscountRule";
import type { IDiscountCampaign } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscountCampaign";

/**
 * E2E 테스트: 할인 캠페인 생성 (유효성/비즈니스 규칙 포함)
 * 
 * 할인 캠페인을 생성할 때 필수 필드 입력, 날짜 유효성, 중복 이름, 스케줄 overlap, 연관 룰 존재성 등
 * 실질적 비즈니스 규칙들이 강제되는지 전체적으로 검증한다. 이름 unique, 기간 오버랩, 비어있는 필드, 룰 참조 등
 * error scenario도 커버한다.
 *
 * 1. discount rule 사전 생성 (캠페인에 연결용)
 * 2. 정상 할인 캠페인 생성
 *   - name, description, start_at, end_at, active 등 필드 모두 지정
 * 3. 필수값 누락 (name, start_at 등)시 validation error 발생 여부 확인
 * 4. 잘못된 날짜, start_at > end_at 등 예외 입력시 에러
 * 5. 동일 name‧기간 겹치는 캠페인 추가 생성 시 비즈니스 중복/충돌 에러 확인
 * 6. 정상 생성된 캠페인 필드 assert (name, active, 기간 등)
 */
export async function test_api_paymentsDiscounts_test_create_discount_campaign_with_validation_and_business_rules(
  connection: api.IConnection,
) {
  // 1. discount rule 생성 (campaign 연결용)
  const rule = await api.functional.paymentsDiscounts.discountRules.post(connection, {
    body: {
      type: 'percentage',
      value: 10,
      active: true,
    },
  });
  typia.assert(rule);

  // 2. 정상 캠페인 생성
  const now = new Date();
  const start = new Date(now.getTime() + 3600 * 1000); // 1시간 후
  const end = new Date(start.getTime() + 7 * 24 * 3600 * 1000); // 1주
  const campaignName = 'E2E-캠페인-' + now.valueOf();
  const campaign = await api.functional.paymentsDiscounts.discountCampaigns.post(connection, {
    body: {
      name: campaignName,
      description: 'E2E 테스트용 할인 캠페인',
      start_at: start.toISOString(),
      end_at: end.toISOString(),
      active: true,
    },
  });
  typia.assert(campaign);
  TestValidator.equals('캠페인명')(campaignName)(campaign.name);
  TestValidator.equals('활성여부')(true)(campaign.active);

  // 3. 필수값 누락(name) → validation error
  await TestValidator.error('이름 누락시 validation 에러')(() =>
    api.functional.paymentsDiscounts.discountCampaigns.post(connection, {
      body: {
        description: 'name 누락',
        start_at: start.toISOString(),
        end_at: end.toISOString(),
        active: true,
      } as any,
    })
  );

  // 4. 잘못된 날짜 (start > end) → 에러
  await TestValidator.error('start_at > end_at일때 에러')(() =>
    api.functional.paymentsDiscounts.discountCampaigns.post(connection, {
      body: {
        name: campaignName + '-dateError',
        start_at: end.toISOString(),
        end_at: start.toISOString(),
        active: true,
      },
    })
  );

  // 5. 동일한 기간‧이름 중복 캠페인 → conflict error
  await TestValidator.error('이름 및 스케줄 중복시 에러')(() =>
    api.functional.paymentsDiscounts.discountCampaigns.post(connection, {
      body: {
        name: campaignName,
        description: '중복 등록',
        start_at: start.toISOString(),
        end_at: end.toISOString(),
        active: true,
      },
    })
  );
}

