import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscountRule } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscountRule";
import type { IDiscountCampaign } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscountCampaign";

/**
 * Test full update of a discount campaign with both business validation and failure (negative) scenarios.
 *
 * This E2E test covers updating an existing discount campaign via the 'putById' endpoint,
 * ensuring successful modification, response property correctness, and proper error handling
 * for invalid scenarios, including:
 *   1. Changing time range, active flag, or campaign name
 *   2. Attempting an update with a duplicate campaign name to trigger a unique constraint violation
 *   3. Setting invalid time ranges (e.g., end_at before start_at) to test business rule rejection
 *   4. Sending overly short or missing required fields (valid TypeScript, invalid business)
 *   5. Trying to update a non-existent campaign to ensure 404 Not Found is returned
 *
 * Steps:
 * 1. Create a discount rule to ensure campaigns can reference existing rules.
 * 2. Create two discount campaigns with properly constrained, unique names.
 * 3. Successfully update the first campaign's time window, description, and status.
 * 4. Fetch and validate update was applied correctly.
 * 5. Try to update the first campaign with the duplicate name of the second: expect rejection (e.g., 409).
 * 6. Try to update with end_at before start_at: expect rejection (e.g., 400/422).
 * 7. Try to update a non-existent campaign ID: expect 404 Not Found error.
 */
export async function test_api_paymentsDiscounts_test_update_discount_campaign_with_validation_and_failure_cases(connection: api.IConnection) {
  // 1. Create a discount rule for association
  const rule = await api.functional.paymentsDiscounts.discountRules.post(connection, {
    body: {
      type: "percentage",
      value: 10,
      active: true
    } satisfies IDiscountRule.ICreate,
  });
  typia.assert(rule);

  // 2. Create two discount campaigns
  const uniqueName1 = `Campaign-${RandomGenerator.alphaNumeric(8)}`;
  const uniqueName2 = `Campaign-${RandomGenerator.alphaNumeric(8)}`;
  const baseStart = new Date(Date.now() + 60 * 1000).toISOString();
  const baseEnd = new Date(Date.now() + 60 * 60 * 1000).toISOString();

  const campaign1 = await api.functional.paymentsDiscounts.discountCampaigns.post(connection, {
    body: {
      name: uniqueName1,
      start_at: baseStart,
      end_at: baseEnd,
      active: true
    } satisfies IDiscountCampaign.ICreate,
  });
  typia.assert(campaign1);

  const campaign2 = await api.functional.paymentsDiscounts.discountCampaigns.post(connection, {
    body: {
      name: uniqueName2,
      start_at: baseStart,
      end_at: baseEnd,
      active: true
    } satisfies IDiscountCampaign.ICreate,
  });
  typia.assert(campaign2);

  // 3. Update campaign1: alter name, description, time window, status
  const newName = uniqueName1 + "-v2";
  const newDescription = "Updated campaign description.";
  const updatedStart = new Date(Date.now() + 5 * 60 * 1000).toISOString();
  const updatedEnd = new Date(Date.now() + 2 * 60 * 60 * 1000).toISOString();
  const updatedActive = false;

  const updated = await api.functional.paymentsDiscounts.discountCampaigns.putById(connection, {
    id: campaign1.id,
    body: {
      name: newName,
      description: newDescription,
      start_at: updatedStart,
      end_at: updatedEnd,
      active: updatedActive
    } satisfies IDiscountCampaign.IUpdate
  });
  typia.assert(updated);
  TestValidator.equals("update - name")(newName)(updated.name);
  TestValidator.equals("update - description")(newDescription)(updated.description);
  TestValidator.equals("update - active")(updatedActive)(updated.active);

  // 4. Business validation: duplicate campaign name
  await TestValidator.error("duplicate campaign name")(async () => {
    await api.functional.paymentsDiscounts.discountCampaigns.putById(connection, {
      id: campaign1.id,
      body: {
        name: uniqueName2 // already exists
      } satisfies IDiscountCampaign.IUpdate
    });
  });

  // 5. Business validation: end_at before start_at
  await TestValidator.error("invalid time window")(async () => {
    await api.functional.paymentsDiscounts.discountCampaigns.putById(connection, {
      id: campaign1.id,
      body: {
        start_at: updatedEnd,
        end_at: updatedStart // reversed, should be rejected
      } satisfies IDiscountCampaign.IUpdate
    });
  });

  // 6. Not found (404): try to update a non-existent campaign
  await TestValidator.error("update non-existent campaign")(async () => {
    await api.functional.paymentsDiscounts.discountCampaigns.putById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
      body: {
        name: "DoesNotExist"
      } satisfies IDiscountCampaign.IUpdate
    });
  });
}

