import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscountRule } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscountRule";
import type { IDiscountCampaign } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscountCampaign";

/**
 * Test full update of a discount campaign with both business validation and failure (negative) scenarios.
 *
 * This E2E test covers updating an existing discount campaign via the 'putById' endpoint,
 * ensuring successful modification, response property correctness, and proper error handling
 * for invalid scenarios, including:
 *   1. Changing time range, active flag, or campaign name
 *   2. Attempting an update with a duplicate campaign name to trigger a unique constraint violation
 *   3. Setting invalid time ranges (e.g., end_at before start_at) to test business rule rejection
 *   4. Trying to update a non-existent campaign to ensure 404 Not Found is returned
 *
 * Test Steps:
 * 1. Create a discount rule for association if needed (not used in update, but for campaign realism).
 * 2. Create two discount campaigns with unique names for negative tests.
 * 3. Update the first campaign's major fields, validate changes reflected.
 * 4. Try updating with a duplicate name (should fail with duplicate/409 error).
 * 5. Try updating with an invalid time window (end_at before start_at, expect rejection).
 * 6. Try updating a non-existent campaign (expect 404 Not Found error).
 */
export async function test_api_paymentsDiscounts_test_update_discount_campaign_with_validation_and_failure_cases(connection: api.IConnection) {
  // 1. Create a discount rule (for association realism)
  const rule = await api.functional.paymentsDiscounts.discountRules.post(connection, {
    body: {
      type: "percentage",
      value: 10.0,
      active: true
    } satisfies IDiscountRule.ICreate,
  });
  typia.assert(rule);

  // 2. Create two campaigns with unique names/times
  const name1 = `Camp-${RandomGenerator.alphaNumeric(8)}`;
  const name2 = `Camp-${RandomGenerator.alphaNumeric(8)}`;
  const now = Date.now();
  const baseStart = new Date(now + 60 * 1000).toISOString();
  const baseEnd = new Date(now + 60 * 60 * 1000).toISOString();

  const campaign1 = await api.functional.paymentsDiscounts.discountCampaigns.post(connection, {
    body: {
      name: name1,
      start_at: baseStart,
      end_at: baseEnd,
      active: true
    } satisfies IDiscountCampaign.ICreate,
  });
  typia.assert(campaign1);

  const campaign2 = await api.functional.paymentsDiscounts.discountCampaigns.post(connection, {
    body: {
      name: name2,
      start_at: baseStart,
      end_at: baseEnd,
      active: true
    } satisfies IDiscountCampaign.ICreate,
  });
  typia.assert(campaign2);

  // 3. Update campaign1: change name, description, dates, status
  const newName = name1 + "-v2";
  const newDesc = "Updated campaign for test validation.";
  const updateStart = new Date(now + 5 * 60 * 1000).toISOString();
  const updateEnd = new Date(now + 2 * 60 * 60 * 1000).toISOString();
  const newActive = false;

  const updated = await api.functional.paymentsDiscounts.discountCampaigns.putById(connection, {
    id: campaign1.id,
    body: {
      name: newName,
      description: newDesc,
      start_at: updateStart,
      end_at: updateEnd,
      active: newActive
    } satisfies IDiscountCampaign.IUpdate
  });
  typia.assert(updated);
  TestValidator.equals("updated name")(newName)(updated.name);
  TestValidator.equals("updated description")(newDesc)(updated.description);
  TestValidator.equals("updated active")(newActive)(updated.active);
  TestValidator.equals("updated start_at")(updateStart)(updated.start_at);
  TestValidator.equals("updated end_at")(updateEnd)(updated.end_at);

  // 4. Attempt duplicate name update (should fail)
  await TestValidator.error("duplicate campaign name")(async () => {
    await api.functional.paymentsDiscounts.discountCampaigns.putById(connection, {
      id: campaign1.id,
      body: {
        name: name2
      } satisfies IDiscountCampaign.IUpdate
    });
  });

  // 5. Invalid time window (end_at before start_at)
  await TestValidator.error("invalid time window")(async () => {
    await api.functional.paymentsDiscounts.discountCampaigns.putById(connection, {
      id: campaign1.id,
      body: {
        start_at: updateEnd,
        end_at: updateStart
      } satisfies IDiscountCampaign.IUpdate
    });
  });

  // 6. Not found - update non-existent campaign
  await TestValidator.error("update non-existent campaign")(async () => {
    await api.functional.paymentsDiscounts.discountCampaigns.putById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
      body: {
        name: "ShouldNotExist"
      } satisfies IDiscountCampaign.IUpdate
    });
