import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscountCampaign } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscountCampaign";

/**
 * Delete a discount campaign and test idempotency and permission errors.
 *
 * This test function ensures robust handling of discount campaign deletion, idempotency, and security. The function executes:
 *
 * 1. Create a new discount campaign as a privileged(admin) user (dependency setup).
 * 2. Delete the campaign with correct permissions.
 * 3. Validate that the campaign is not retrievable/listable after deletion.
 * 4. Attempt to delete the same campaign again to test idempotency or proper error (expect no-op or specific error).
 * 5. Attempt to delete a truly non-existent campaign (random uuid) and check for correct error handling.
 * 6. Attempt to delete a campaign while logged out or with insufficient permissions (e.g., normal user/no token) and check for authorization error.
 *
 * This verifies both normal and abnormal flows: successful deletion, access control, repeated deletion safety, and correct error reporting.
 */
export async function test_api_paymentsDiscounts_test_delete_discount_campaign_idempotency_and_permissions(
  connection: api.IConnection,
) {
  // 1. Create a campaign as admin
  const campaign = await api.functional.paymentsDiscounts.discountCampaigns.post(connection, {
    body: {
      name: `Test Campaign ${RandomGenerator.alphaNumeric(8)}`,
      description: "Test campaign for deletion E2E.",
      start_at: new Date(Date.now() - 24 * 3600 * 1000).toISOString(), // started yesterday
      end_at: new Date(Date.now() + 24 * 3600 * 1000).toISOString(),   // ends tomorrow
      active: true,
    } satisfies IDiscountCampaign.ICreate
  });
  typia.assert(campaign);

  // 2. Delete the campaign (as admin)
  await api.functional.paymentsDiscounts.discountCampaigns.eraseById(connection, {
    id: campaign.id
  });

  // 3. Ensure campaign is gone (e.g., try to fetch/list and expect error or no result)
  // NOTE: If retrieval/listing endpoint is not available, document the intent and skip.
  // TODO: Uncomment if there is a GET endpoint (e.g., .at or .list). Example:
  // await TestValidator.error("deleted campaign should not be found")(async () => {
  //   await api.functional.paymentsDiscounts.discountCampaigns.at(connection, { id: campaign.id });
  // });

  // 4. Re-delete (should be idempotent or error with known code)
  await TestValidator.error("delete already deleted campaign should produce proper error")(async () => {
    await api.functional.paymentsDiscounts.discountCampaigns.eraseById(connection, {
      id: campaign.id
    });
  });

  // 5. Delete a truly-nonexistent campaign (random UUID)
  await TestValidator.error("delete non-existent campaign")(async () => {
    await api.functional.paymentsDiscounts.discountCampaigns.eraseById(connection, {
      id: typia.random<string & tags.Format<"uuid">>()
    });
  });

  // 6. Test lack of permission: simulate 'no auth' by removing token and expect error
  const noAuthConnection = {
    ...connection,
    headers: { ...connection.headers }
  };
  // Remove Auth headers (convention: Authorization/Bearer)
  delete noAuthConnection.headers.Authorization;
  await TestValidator.error("unauthorized campaign delete should fail")(async () => {
    await api.functional.paymentsDiscounts.discountCampaigns.eraseById(noAuthConnection, {
      id: campaign.id
    });
  });
}

