  const baseline = await api.functional.paymentsDiscounts.transactions.patch(connection, {
    body: {},
  });
  typia.assert(baseline);
  TestValidator.predicate("paginated data array")(Array.isArray(baseline.data));

  // If there are no transactions, skip further filter/pagination tests
  if (!baseline.data.length) return;

  // 2. Search by random user_id of a listed transaction
  const testUserId = baseline.data[0].user_id;
  const userFiltered = await api.functional.paymentsDiscounts.transactions.patch(connection, {
    body: { user_id: testUserId },
  });
  typia.assert(userFiltered);
  TestValidator.predicate("user filter: all user_ids match")(
    userFiltered.data.every(tx => tx.user_id === testUserId)
  );

  // 3. Search by transaction type if present
  const presentTypes = [...new Set(baseline.data.map(tx => tx.type))];
  if (presentTypes.length > 0) {
    const testType = presentTypes[0];
    const typeFiltered = await api.functional.paymentsDiscounts.transactions.patch(connection, {
      body: { type: testType },
    });
    typia.assert(typeFiltered);
    TestValidator.predicate("type filter: all types match")(
      typeFiltered.data.every(tx => tx.type === testType)
    );
  }

  // 4. Date range filter: use created_at of two transactions if possible
  if (baseline.data.length >= 2) {
    // Sort transactions by created_at ascending
    const sorted = [...baseline.data].sort((a, b) => a.created_at.localeCompare(b.created_at));
    const from = sorted[0].created_at;
    const to = sorted[sorted.length-1].created_at;
    const dateFiltered = await api.functional.paymentsDiscounts.transactions.patch(connection, {
      body: { created_after: from, created_before: to },
    });
    typia.assert(dateFiltered);
    TestValidator.predicate("date range filter: within bounds")(
      dateFiltered.data.every(tx => (tx.created_at >= from && tx.created_at <= to))
    );
  }

  // 5. Pagination: get first page, then another page with same limit
  const pageSize = 2;
  const page1 = await api.functional.paymentsDiscounts.transactions.patch(connection, {
