    await api.functional.paymentsDiscounts.transactions.patch(connection, {
      body: { created_after: "2025-99-99" },
    });
  });

  // 8. INVALID page: 0
  await TestValidator.error("invalid page 0 triggers error")(async () => {
    await api.functional.paymentsDiscounts.transactions.patch(connection, {
      body: { page: 0 },
    });
  });

  // 9. INVALID negative page value
  await TestValidator.error("invalid negative page triggers error")(async () => {
    await api.functional.paymentsDiscounts.transactions.patch(connection, {
      body: { page: -1 },
    });
  });
