import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ITransaction } from "@ORGANIZATION/PROJECT-api/lib/structures/ITransaction";

/**
 * 테스트 목적: 트랜잭션 ID로 상세 조회 권한, 존재 여부, 전체 정보 노출 확인
 * 
 * 1. 트랜잭션을 생성한 후, 해당 ID로 정상 조회 후 모든 필드가 정확히 반환되는지 검증
 * 2. 존재하지 않는 ID로 조회하여 404(or 적절한 에러) 반환 여부 확인
 * 3. (권한 검사) 타 유저가 생성한 트랜잭션을 타 유저가 접근 시 거부 혹은 제한 반환되는지 검증
 */
export async function test_api_paymentsDiscounts_test_get_transaction_by_id_with_permission_and_existence(
  connection: api.IConnection,
) {
  // 1. 트랜잭션을 생성
  const createInput: ITransaction.ICreate = {
    user_id: typia.random<string & tags.Format<"uuid">>(),
    type: "purchase",
    created_at: new Date().toISOString(),
    description: "권한/존재 테스트용 트랜잭션"
  };
  const transaction = await api.functional.paymentsDiscounts.transactions.post(connection, { body: createInput });
  typia.assert(transaction);

  // 2. 정상 조회: 생성된 트랜잭션 ID로 호출, 모든 필드 확인
  const read = await api.functional.paymentsDiscounts.transactions.getById(connection, { id: transaction.id });
  typia.assert(read);
  TestValidator.equals("id")(transaction.id)(read.id);
  TestValidator.equals("user_id")(transaction.user_id)(read.user_id);
  TestValidator.equals("type")(transaction.type)(read.type);
  TestValidator.equals("created_at")(transaction.created_at)(read.created_at);
  TestValidator.equals("description")(transaction.description)(read.description);

  // 3. 존재하지 않는 ID로 호출 → 404(또는 도메인 정의 에러) 확인
  const nonexistId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("404 for non-existent transaction")(() =>
    api.functional.paymentsDiscounts.transactions.getById(connection, { id: nonexistId })
  );

  // 4. 타 유저 트랜잭션 접근 제한: 다른 유저의 트랜잭션 생성 후 현재 유저가 접근 시도
  const anotherUserId = typia.random<string & tags.Format<"uuid">>();
  const anotherTx = await api.functional.paymentsDiscounts.transactions.post(connection, {
    body: {
      ...createInput,
      user_id: anotherUserId,
      description: "타 유저 트랜잭션"
    }
  });
  typia.assert(anotherTx);
  await TestValidator.error("permission error for another user's transaction")(() =>
    api.functional.paymentsDiscounts.transactions.getById(connection, { id: anotherTx.id })
  );
}

