import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ITransaction } from "@ORGANIZATION/PROJECT-api/lib/structures/ITransaction";

/**
 * 트랜잭션 단일 조회 시 권한, 존재 여부, 전체 정보 노출 검증 E2E 테스트
 *
 * 1. 트랜잭션을 생성 후, 해당 ID로 정상 조회하여 모든 핵심 필드가 정확히 반환되는지 검증
 * 2. 랜덤(nonexistent) ID로 조회 시 404 등 올바른 도메인 에러가 반환되는지 확인
 * 3. 권한 검사 - 현재(로그인) 유저가 아닌 uuid를 가진 트랜잭션을 생성 후 현재 유저가 접근할 때 접근 불가(권한 에러) 확인
 *
 * 시나리오 처리 과정:
 *   - 각 단계별 결과물은 typia.assert로 타입 검증
 *   - 모든 값은 business context(랜덤 uuid, 트랜잭션 타입, 생성 시각, 설명 등) 부여
 *   - TestValidator로 값 일치 및 에러 발생 여부 검증
 */
export async function test_api_paymentsDiscounts_test_get_transaction_by_id_with_permission_and_existence(
  connection: api.IConnection,
) {
  // 1. 트랜잭션 신규 생성 (권한, 존재성 검증을 위한 테스트 데이터)
  const myUserId: string = typia.random<string & tags.Format<"uuid">>();
  const createInput: ITransaction.ICreate = {
    user_id: myUserId,
    type: "purchase",
    created_at: new Date().toISOString(),
    description: "E2E 상세조회 권한/존재성 검증용"
  };
  const transaction = await api.functional.paymentsDiscounts.transactions.post(
    connection,
    { body: createInput }
  );
  typia.assert(transaction);

  // 2. 성공 케이스: 생성된 트랜잭션 ID로 상세조회 및 모든 정보 매칭 확인
  const read = await api.functional.paymentsDiscounts.transactions.getById(
    connection,
    { id: transaction.id }
  );
  typia.assert(read);
  TestValidator.equals("id")(transaction.id)(read.id);
  TestValidator.equals("user_id")(transaction.user_id)(read.user_id);
  TestValidator.equals("type")(transaction.type)(read.type);
  TestValidator.equals("created_at")(transaction.created_at)(read.created_at);
  TestValidator.equals("description")(transaction.description)(read.description);

  // 3. 존재하지 않는 ID로 조회 → 404 또는 적절한 도메인 정의 에러 발생 확인
  const nonexistId: string = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("404 for non-existent transaction")(() =>
    api.functional.paymentsDiscounts.transactions.getById(connection, { id: nonexistId })
  );

  // 4. 타 유저 트랜잭션을 임의로 하나 더 생성, 현재 user_id와 다르게 입력
  const anotherUserId: string = typia.random<string & tags.Format<"uuid">>();
  const otherTx = await api.functional.paymentsDiscounts.transactions.post(
    connection,
    {
      body: {
        ...createInput,
        user_id: anotherUserId,
        description: "타 유저 트랜잭션 접근불가권한 검증"
      }
    }
  );
  typia.assert(otherTx);
  // (실제 RBAC 정책에 따라 허용/거부 응답 체크 필요) → 이 테스트에서는 에러(권한거부) 기대
  await TestValidator.error("permission error for another user's transaction")(() =>
    api.functional.paymentsDiscounts.transactions.getById(connection, { id: otherTx.id })
  );
}

