 * wallet/account flows and admin registry.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IPaymentMethod = {
  /** Unique payment method ID (PK for payment_methods). */
  id: string & tags.Format<"uuid">;

