import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPaymentMethod } from "@ORGANIZATION/PROJECT-api/lib/structures/IPaymentMethod";
import type { ITransaction } from "@ORGANIZATION/PROJECT-api/lib/structures/ITransaction";

/**
 * Validate creation of transaction records with required field validation and business constraints.
 *
 * This test verifies:
 * 1. Proper creation of a transaction with valid user, timestamp, and type
 * 2. Validation errors when required or type-constrained fields are omitted or invalid
 * 3. Integrity constraints or duplicate creation are correctly handled
 *
 * Steps:
 * 1. Register a payment method to obtain valid user_id and payment context
 * 2. Create a valid transaction for the registered user
 * 3. Attempt creation with missing required fields or invalid types (invalid or null user_id, type, created_at)
 * 4. Attempt to create a transaction with identical data (simulate duplication/conflict)
 */
export async function test_api_paymentsDiscounts_test_create_transaction_with_validation_rules(connection: api.IConnection) {
  // 1. Register a payment method for the user
  const user_id: string = typia.random<string & tags.Format<"uuid">>();
  const paymentMethod = await api.functional.paymentsDiscounts.paymentMethods.post(connection, {
    body: {
      user_id: user_id,
      type: "VISA",
      masked_detail: "**** **** **** 1234",
      provider: "Stripe",
      active: true
    }
  });
  typia.assert(paymentMethod);

  // 2. Create a valid transaction for that user
  const validTransaction = await api.functional.paymentsDiscounts.transactions.post(connection, {
    body: {
      user_id: user_id,
      type: "purchase",
      created_at: new Date().toISOString(),
      description: "Test transaction from E2E"
    }
  });
  typia.assert(validTransaction);
  // Basic validation that transaction's user_id matches
  TestValidator.equals("user_id matches")(user_id)(validTransaction.user_id);
  // created_at is a valid ISO8601 string
  TestValidator.predicate("created_at is ISO string")(!isNaN(Date.parse(validTransaction.created_at)));

  // 3. Attempt to create a transaction missing required field (user_id)
  await TestValidator.error("missing user_id triggers validation error")(async () => {
    await api.functional.paymentsDiscounts.transactions.post(connection, {
      body: {
        // user_id: missing
        type: "refund",
        created_at: new Date().toISOString()
      } as any // Intentionally malformed for test – expected runtime error
    });
  });

  // 4. Attempt to create a transaction with invalid 'created_at'
  await TestValidator.error("invalid created_at triggers validation error")(async () => {
    await api.functional.paymentsDiscounts.transactions.post(connection, {
      body: {
        user_id: user_id,
        type: "refund",
        created_at: "not-a-date"
      } as any
    });
  });

  // 5. Simulate potential conflict by submitting a duplicate transaction (same user_id, type, created_at)
  await TestValidator.error("duplicate transaction triggers business constraint error")(async () => {
    await api.functional.paymentsDiscounts.transactions.post(connection, {
      body: {
        user_id: user_id,
        type: "purchase",
        created_at: validTransaction.created_at,
        description: "Test transaction from E2E"
      }
    });
  });
}

