 * Test updating a transaction and edge-case validation for paymentsDiscounts.transactions.
 *
 * This function validates:
 * 1. You can update allowed fields (description, type, order_id) for a transaction.
 * 2. Updated values are correctly reflected in the response.
 * 3. Attempts to update forbidden/immutable fields (user_id, created_at) cannot be performed thanks to DTO type safety (cannot test at runtime).
 * 4. Attempting to update a non-existent transaction returns the appropriate error (typically 404).
 *
 * Test Workflow:
 * 1. Create a baseline transaction as the subject for update via dependency.
 * 2. Update permitted fields and validate the change.
 * 3. (Documented only) Attempt to update forbidden fields is skipped (runtime type safety makes this impossible).
 * 4. Try to update a non-existent transaction and assert 404 is returned.
 */
export async function test_api_paymentsDiscounts_test_update_transaction_with_validation_and_edge_cases(
  connection: api.IConnection,
) {
  // 1. Create a new transaction to act as the test subject
  const createPayload: ITransaction.ICreate = {
    user_id: typia.random<string & tags.Format<'uuid'>>(),
    order_id: typia.random<string & tags.Format<'uuid'>>(),
    type: "purchase",
    created_at: new Date().toISOString(),
    description: "Initial transaction for update workflow.",
  };
  const original = await api.functional.paymentsDiscounts.transactions.post(
    connection,
    { body: createPayload },
  );
  typia.assert(original);

  // 2. Update allowed fields - set description, type, and clear order_id
  const updatePayload: ITransaction.IUpdate = {
    description: "Updated for E2E test validation.",
    type: "refund",
    order_id: null,
  };
  const updated = await api.functional.paymentsDiscounts.transactions.putById(
    connection,
    { id: original.id, body: updatePayload },
  );
  typia.assert(updated);
  // Assert updated fields
  TestValidator.equals("description")(updatePayload.description)(updated.description);
  TestValidator.equals("type")(updatePayload.type)(updated.type);
  TestValidator.equals("order_id")(updatePayload.order_id)(updated.order_id);
  // Optional: validate other fields remain unchanged
  TestValidator.equals("id")(original.id)(updated.id);
  TestValidator.equals("user_id")(original.user_id)(updated.user_id);
  TestValidator.equals("created_at")(original.created_at)(updated.created_at);

  // 3. Impossible to test updating forbidden fields due to strict DTO typing
  //    (e.g., trying to include user_id/created_at will cause TypeScript error, so this is skipped)

  // 4. Attempt to update a non-existent transaction (should yield 404 or a not-found error)
  const nonExistentId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("update non-existent transaction fails")(() =>
    api.functional.paymentsDiscounts.transactions.putById(connection, {
      id: nonExistentId,
      body: updatePayload,
    }),
  );
}

