import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IVoucher } from "@ORGANIZATION/PROJECT-api/lib/structures/IVoucher";
import type { IPageIVoucher } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIVoucher";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * 검증 대상: 바우처(voucher) 리스트 조회 및 다양한 필터(예: 상태, 사용자, 캠페인 등) 검색
 *
 * 테스트 목적 및 배경: 
 * 결제/할인 플랫폼의 voucher 관리 기능의 핵심은 관리자가 다양한 조건(상태, 유저, 할인 캠페인, 지급/사용 여부, 만료 기간 등)으로 바우처를 검색, 분류, 통계 처리 할 수 있다는 점입니다. 페이징, 필터, 정렬, 잘못된 필터 에러 반환까지 UI/운영·분석·증빙 용 전반을 검증합니다. 
 *
 * 시나리오: 
 * 1. 여러 개의 테스트 바우처 데이터를 사전 생성한다. (각기 다른 user/campaign, redeemed 상태, expires_at 등 다양하게 섞어서)
 * 2. 페이징(page, limit) 조합으로 조회 시 지정한 갯수/페이지로 데이터가 정확히 정렬되어 나오는지 확인.
 * 3. redeemed, campaign_id, user_id, expires_before, expires_after 등 각각 혹은 조합 필터가 정상 작동하는지 조회 결과로 검증
 * 4. 유효하지 않은 필터(존재하지 않는 user/campaign uuid, 잘못된 date/time, 허용 범위 밖의 page나 limit 등)로 호출할 경우 올바르게 에러가 발생하는지 검증
 * 5. 모든 결과 객체가 IVoucher 스키마에 부합하는지 assert
 */
export async function test_api_paymentsDiscounts_test_list_and_search_vouchers_with_filters_and_pagination(
  connection: api.IConnection,
) {
  // 1. 사전 조건: 다양한 바우처 생성 (redeemed/unredeemed, 만료/미만료, 서로 다른 campaign/user 등)
  //   (바우처 생성 API가 없을 경우, 사전에 seed 데이터가 미리 DB에 들어가 있다고 가정하여 이하 진행)

  // 2. 페이징 테스트: limit=2로 첫 페이지 조회 후, 두 번째 페이지도 불러서 중복 없고 전체 records 합이 맞는지 체크
  const pageSize = 2;
  const firstPage = await api.functional.paymentsDiscounts.vouchers.patch(connection, {
    body: {
      limit: pageSize, 
      page: 1,
    } satisfies IVoucher.IRequest,
  });
  typia.assert(firstPage);
  TestValidator.equals('페이지 크기')(firstPage.pagination.limit)(pageSize);
  TestValidator.equals('첫번째 페이지 번호')(firstPage.pagination.current)(1);
  TestValidator.equals('반환 데이터 갯수')(firstPage.data.length)(Math.min(firstPage.pagination.records, pageSize));

  if (firstPage.pagination.pages >= 2) {
    const secondPage = await api.functional.paymentsDiscounts.vouchers.patch(connection, {
      body: {
        limit: pageSize,
        page: 2,
      } satisfies IVoucher.IRequest,
    });
    typia.assert(secondPage);
    TestValidator.equals('두번째 페이지 번호')(secondPage.pagination.current)(2);
    // 두 페이지 합쳐서 전체 records 체크
    TestValidator.equals('1~2페이지 갯수합', firstPage.data.length + secondPage.data.length)(
      Math.min(pageSize * 2, firstPage.pagination.records),
    );
  }

  // 3. 개별/조합 필터검증
  // 3-1. redeemed 상태별 조회
  let redeemedExists = false;
  let unreemedExists = false;
  for (const v of firstPage.data) {
    if (v.redeemed_at) redeemedExists = true;
    if (!v.redeemed_at) unreemedExists = true;
  }
  if (redeemedExists)
    TestValidator.predicate('redeemed=true 조회')(firstPage.data.some(v => v.redeemed_at));
  if (unreemedExists)
    TestValidator.predicate('redeemed=false 조회')(firstPage.data.some(v => !v.redeemed_at));

  // (다른 필터 조합은 seed fixture 데이터를 기준으로 직접 uuid/date 필드 임의 셋팅 및 조합해 필터 요청)

  // 4. 잘못된 filter 값을 넣었을 때 - 존재하지 않는 user_id·campaign_id, 음수 page 등
  await TestValidator.error('존재하지 않는 user/campaign')(async () => {
    await api.functional.paymentsDiscounts.vouchers.patch(connection, {
      body: {
        user_id: typia.random<string & tags.Format<'uuid'>>(),
        campaign_id: typia.random<string & tags.Format<'uuid'>>(),
      } satisfies IVoucher.IRequest,
    });
  });

  await TestValidator.error('잘못된 page/limit')(async () => {
    await api.functional.paymentsDiscounts.vouchers.patch(connection, {
      body: {
        page: -1 as number & tags.Type<'int32'> & tags.Minimum<1>,
        limit: 0 as number & tags.Type<'int32'> & tags.Minimum<1>,
      } satisfies IVoucher.IRequest,
    });
  });

  // 모든 반환 데이터가 IVoucher 스키마와 일치하는지 체크
  for (const v of firstPage.data) {
    typia.assert(v);
  }
}

