 *
 * - 관리자/운영/통계 목적에서 바우처 조건별(list+filter+pagination) 검색 기능의 시나리오별 정상동작 및 예외 처리를 검증합니다.
 * - 다양한 redeemed 상태, campaign/user/expiry 조건 가정, 만약 바우처 생성 API가 별도 없다면 미리 사전 fixture 데이터를 준비해야 합니다.
 * - page/limit 페이징, redeemed 등의 상태 필터, 잘못된 filter error 등 = 전체 동작 경로 테스트
 *
 * 단계별:
 * 1. 다양한 상태/유저/캠페인 바우처 DB 내 존재를 가정(또는 사전 세팅)
 * 2. 제한된 페이지/limit값 페이징 조회 -> 반환된 meta/length assert
 * 3. redeemed 등 의미있는 필터 및 조합의 동작 검증, 결과 데이터 내 일치성/상태 체크
 * 4. 존재하지 않는 UUID, 허용범위 밖 page/limit 등 invalid params로 error처리 동작 검증
 * 5. 반환 모든 row가 스키마와 일치하는지 assert
 */
export async function test_api_paymentsDiscounts_test_list_and_search_vouchers_with_filters_and_pagination(
  connection: api.IConnection,
) {
  // 1. 다양한 바우처(test fixture) DB내에 있다고 가정 (실제 신규 생성 API가 있다면 여기 setup 추가)

  // 2. 페이징 테스트 - limit=2, page=1/2 두 번 요청, 반환 meta/길이 체크
  const pageSize = 2;
  const firstPage = await api.functional.paymentsDiscounts.vouchers.patch(connection, {
    body: {
      limit: pageSize,
      page: 1,
    } satisfies IVoucher.IRequest,
  });
  typia.assert(firstPage);
  TestValidator.equals('페이지 크기')(firstPage.pagination.limit)(pageSize);
  TestValidator.equals('페이지 번호')(firstPage.pagination.current)(1);
  TestValidator.equals('레코드 수')(firstPage.data.length)(Math.min(firstPage.pagination.records, pageSize));

  if (firstPage.pagination.pages >= 2) {
    const secondPage = await api.functional.paymentsDiscounts.vouchers.patch(connection, {
      body: {
        limit: pageSize,
        page: 2,
      } satisfies IVoucher.IRequest,
    });
    typia.assert(secondPage);
    TestValidator.equals('2페이지 번호')(secondPage.pagination.current)(2);
    TestValidator.equals('1~2page 레코드수 합', firstPage.data.length + secondPage.data.length)(
      Math.min(pageSize * 2, firstPage.pagination.records),
    );
  }

  // 3. redeemed 필터 (해당 상태 바우처 존재여부 보고 개별 rows 검사)
  let redeemedExists = false;
  let unredeemedExists = false;
  for (const v of firstPage.data) {
    if (v.redeemed_at) redeemedExists = true;
    if (!v.redeemed_at) unredeemedExists = true;
  }
  if (redeemedExists)
    TestValidator.predicate('redeemed=true 필터')(firstPage.data.some(v => v.redeemed_at));
  if (unredeemedExists)
    TestValidator.predicate('redeemed=false 필터')(firstPage.data.some(v => !v.redeemed_at));

  // 4. invalid filter 값 (존재하지 않는 uuid, 음수/제로 page 등)
  await TestValidator.error('존재하지 않는 user/campaign')(async () => {
    await api.functional.paymentsDiscounts.vouchers.patch(connection, {
      body: {
        user_id: typia.random<string & tags.Format<'uuid'>>(),
        campaign_id: typia.random<string & tags.Format<'uuid'>>(),
      } satisfies IVoucher.IRequest,
    });
  });
  await TestValidator.error('잘못된 page/limit')(async () => {
    await api.functional.paymentsDiscounts.vouchers.patch(connection, {
      body: {
        page: -1 as number & tags.Type<'int32'> & tags.Minimum<1>,
        limit: 0 as number & tags.Type<'int32'> & tags.Minimum<1>,
      } satisfies IVoucher.IRequest,
    });
  });

  // 5. 반환 데이터 타입 assert
  for (const v of firstPage.data) {
    typia.assert(v);
  }
}

