import { IConnection, HttpError } from "@nestia/fetcher";
import { PlainFetcher } from "@nestia/fetcher/lib/PlainFetcher";
import typia from "typia";
import { NestiaSimulator } from "@nestia/fetcher/lib/NestiaSimulator";

import { IVoucher } from "../../../structures/IVoucher";
import { IPageIVoucher } from "../../../structures/IPageIVoucher";

/**
 * Search/list vouchers from paymentsDiscounts.vouchers with flexible query
 * support.
 *
 * Lists all or filtered vouchers according to request body criteria—filters,
 * sorts, and paginates as per post-2024 standards. Enables analysts, business
 * managers, or automated AI/ML pipelines to examine current/expired/redeemed
 * vouchers, trace usage, and integrate results into evidence pipelines. All
 * actions are recorded for compliance. Supports full text, date range, user,
 * campaign, status, or business-criteria search parameters. Output structure is
 * suitable for dashboard reporting, operational APIs, and AI/ML model feedback
 * channels.
 *
 * @param props.connection
 * @param props.body Search, filters, sort and pagination definitions for
 *   voucher listing.
 * @path /paymentsDiscounts/vouchers
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export async function patch(
  connection: IConnection,
  props: patch.Props,
): Promise<patch.Response> {
  return !!connection.simulate
    ? patch.simulate(connection, props)
    : PlainFetcher.fetch(
        {
          ...connection,
          headers: {
            ...connection.headers,
            "Content-Type": "application/json",
          },
        },
        {
          ...patch.METADATA,
          path: patch.path(),
          status: null,
        },
        props.body,
      );
}
export namespace patch {
  export type Props = {
    /** Search, filters, sort and pagination definitions for voucher listing. */
    body: IVoucher.IRequest;
  };
  export type Body = IVoucher.IRequest;
  export type Response = IPageIVoucher;

  export const METADATA = {
    method: "PATCH",
    path: "/paymentsDiscounts/vouchers",
    request: {
      type: "application/json",
      encrypted: false,
    },
    response: {
      type: "application/json",
      encrypted: false,
    },
  } as const;

  export const path = () => "/paymentsDiscounts/vouchers";
  export const random = (g?: Partial<typia.IRandomGenerator>): IPageIVoucher =>
    typia.random<IPageIVoucher>(g);
  export const simulate = (
    connection: IConnection,
    props: patch.Props,
  ): Response => {
    const assert = NestiaSimulator.assert({
      method: METADATA.method,
      host: connection.host,
      path: patch.path(),
      contentType: "application/json",
    });
    try {
      assert.body(() => typia.assert(props.body));
    } catch (exp) {
      if (!typia.is<HttpError>(exp)) throw exp;
      return {
        success: false,
        status: exp.status,
        headers: exp.headers,
        data: exp.toJSON().message,
      } as any;
    }
    return random(
      "object" === typeof connection.simulate && null !== connection.simulate
        ? connection.simulate
        : undefined,
    );
  };
}

