import { tags } from "typia";

/**
 * Atomic, auditable representation of a voucher, gift card, or credit
 * instrument as defined in PaymentsDiscounts.vouchers Prisma table. All fields
 * evidence-preserved, mapped to compliance and analytics workflows. Used in
 * admin, self-service, evidence export, or regulatory review.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IVoucher = {
  /**
   * Voucher record UUID (primary key). Non-null. Referenced as
   * PaymentsDiscounts.vouchers.id.
   */
  id: string & tags.Format<"uuid">;

  /**
   * User to whom voucher is owned/assigned. Required evidence for user-asset
   * relationships. See vouchers.user_id.
   */
  user_id: string & tags.Format<"uuid">;

  /**
   * Discount campaign to which the voucher was issued (if any). See
   * vouchers.campaign_id. Optional.
   */
  campaign_id?: (string & tags.Format<"uuid">) | null;

  /**
   * Optional payment method constraint: restricts redemption to specific
   * method type (e.g. in-app wallet, card). See vouchers.payment_method_id.
   */
  payment_method_id?: (string & tags.Format<"uuid">) | null;

  /**
   * Human-readable, unique voucher code. Asset redemption key. See
   * vouchers.code.
   */
  code: string;

  /**
   * Current outstanding voucher balance (positive value only; updated on
   * use/partial redemption). See vouchers.balance.
   */
  balance: number &
    tags.JsonSchemaPlugin<{
      format: "double";
    }>;

  /**
   * Monetary currency/region code. 3-letter ISO standard. See
   * vouchers.currency.
   */
  currency: string;

  /**
   * Voucher expiration date. Null means non-expiring (subject to
   * campaign/user rules). Prisma vouchers.expires_at.
   */
  expires_at?: (string & tags.Format<"date-time">) | null;

  /**
   * Asset creation timestamp; evidence trail for audit, analytics. See
   * vouchers.created_at.
   */
  created_at: string & tags.Format<"date-time">;

  /**
   * Timestamp when voucher was fully redeemed (used, depleted, or revoked).
   * Null if open. See vouchers.redeemed_at.
   */
  redeemed_at?: (string & tags.Format<"date-time">) | null;
};
export namespace IVoucher {
  /**
   * Request/criteria for searching, filtering and paginating voucher records
   * from PaymentsDiscounts.vouchers. Supports admin, analytics, and
   * self-service use cases, per compliance and evidence preservation
   * guidelines.
   */
  export type IRequest = {
    /**
     * User owning or assigned to the voucher. Filter for personalized
     * credit/gift management. See vouchers.user_id.
     */
    user_id?: string & tags.Format<"uuid">;

    /**
     * Associated discount campaign for the voucher, if any. Optional; see
     * vouchers.campaign_id.
     */
    campaign_id?: (string & tags.Format<"uuid">) | null;

    /**
     * Restrict to vouchers tied to a particular payment method (in-app,
     * external card, etc). Optional.
     */
    payment_method_id?: (string & tags.Format<"uuid">) | null;

    /**
     * Filter for a specific voucher code (case-insensitive search
     * permitted). Must match vouchers.code.
     */
    code?: string;

    /** Return vouchers expiring before this date/time. */
    expires_before?: string & tags.Format<"date-time">;

    /** Return vouchers expiring after this date/time. */
    expires_after?: string & tags.Format<"date-time">;

    /** Return only redeemed or not redeemed vouchers by status. */
    redeemed?: boolean;

    /** Filter vouchers by 3-letter ISO currency (e.g., USD, KRW). */
    currency?: string;

    /** Page number for paginated result in vouchering analytics or admin UI. */
    page?: number &
      tags.Type<"int32"> &
      tags.Minimum<1> &
      tags.JsonSchemaPlugin<{
        format: "uint32";
      }>;

    /**
     * Pagination page size. Controls returned voucher list length, with
     * default per system config.
     */
    limit?: number &
      tags.Type<"int32"> &
      tags.Minimum<1> &
      tags.JsonSchemaPlugin<{
        format: "uint32";
      }>;
  };
}

