 *
 * Step-by-step validation:
 * 1. Create a voucher for User A (Owner)
 * 2. Retrieve the voucher by its ID while authenticated as User A and validate all fields
 * 3. Attempt to retrieve a random/non-existent voucher (random UUID) and expect a 404 error
 * 4. Create a second user (User B); attempt to retrieve User A's voucher as User B—you must either get access denied, filtered data or other permission-enforced result
 */
export async function test_api_paymentsDiscounts_test_get_voucher_by_id_with_permissions_and_not_found(connection: api.IConnection) {
  // 1. Create User A (owner) - If auth required, simulate or register
  const userAId: string = typia.random<string & tags.Format<"uuid">>();
