  const userAId: string = typia.random<string & tags.Format<"uuid">>();

  // 2. Create a voucher owned by User A
  const voucher: IVoucher = await api.functional.paymentsDiscounts.vouchers.post(connection, {
    body: {
      user_id: userAId,
