import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscountCampaign } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscountCampaign";
import type { IVoucher } from "@ORGANIZATION/PROJECT-api/lib/structures/IVoucher";

/**
 * 통합 바우처(쿠폰) 발급 API 주요 검증 시나리오
 *
 * 비즈니스 요구
 * - 신규 바우처를 필수 정보(금액, 고유 코드, 만료일 포함)로 정상 발급할 수 있다.
 * - Campaign이 연동된 경우(의존성) 올바르게 campaign_id로 할당되어야 한다.
 * - 필수필드 누락 또는 유효하지 않은 값 제출 시 서버 측 Validation 실패를 반드시 체증한다.
 * - 이미 존재하는 voucher code로 발급 요청하면 반드시 고유성(uniqueness) 에러가 발생해야 한다.
 *
 * #### Step-by-step 검증
 * 1. 신규 discount campaign(할인 캠페인)을 반드시 생성(의존성)한다. (캠페인 join test)
 * 2. 신규 바우처를 정상/필수값으로 성공 발급하며, campaign_id field로 위 캠페인 id를 지정
 * 3. 누락/유효하지 않은 데이터(필수값 미입력, 잘못된 balance, 만료일 등)로 각각 요청 후 validation 에러 검증
 * 4. 2번에서 발급한 고유코드(code)와 동일한 값으로 발급 재시도 시, 반드시 중복/고유성 제약 위반을 검증
 * 5. 정상 발급된 바우처의 모든 주요 필드와 타입을 assert(typia)로 검증 및 값 유효성 체크
 */
export async function test_api_paymentsDiscounts_test_create_voucher_with_validation_and_uniqueness(
  connection: api.IConnection,
) {
  // 1. 신규 discount campaign 생성(의존 준비)
  const campaignName = `캠페인-${RandomGenerator.alphaNumeric(8)}`;
  const now = new Date();
  const campaignStartAt = now.toISOString();
  const campaignEndAt = new Date(now.getTime() + 1000*60*60*24*14).toISOString();
  const campaign = await api.functional.paymentsDiscounts.discountCampaigns.post(
    connection,
    {
      body: {
        name: campaignName,
        description: "이 바우처 테스트용 할인캠페인입니다.",
        start_at: campaignStartAt,
        end_at: campaignEndAt,
        active: true,
      } satisfies IDiscountCampaign.ICreate,
    }
  );
  typia.assert(campaign);

  // 2. 정상 신규 바우처 데이터 준비 및 발급
  const userId = typia.random<string & tags.Format<"uuid">>();
  const voucherCode = `TESTVOUCHER${RandomGenerator.alphaNumeric(5)}`;
  const balance = 10000;
  const currency = "KRW";
  const expiresAt = new Date(now.getTime() + 1000*60*60*24*30).toISOString();
  const voucherPayload = {
    user_id: userId,
    campaign_id: campaign.id,
    code: voucherCode,
    balance,
    currency,
    expires_at: expiresAt,
  } satisfies IVoucher.ICreate;
  const created = await api.functional.paymentsDiscounts.vouchers.post(
    connection,
    {
      body: voucherPayload,
    }
  );
  typia.assert(created);
  TestValidator.equals("voucher code")(voucherCode)(created.code);
  TestValidator.equals("campaign id")(campaign.id)(created.campaign_id);
  TestValidator.equals("user id")(userId)(created.user_id);
  TestValidator.equals("balance")(balance)(created.balance);
  TestValidator.equals("currency")(currency)(created.currency);
  TestValidator.equals("expires_at")(expiresAt)(created.expires_at);

  // 3. 유효성 실패(필수값 누락/유효하지 않은 값) 케이스 검증
  await TestValidator.error("user_id 미입력")(() =>
    api.functional.paymentsDiscounts.vouchers.post(connection, {
      body: {
        ...voucherPayload,
        user_id: undefined as unknown as string,
      } as any,
    })
  );
  await TestValidator.error("balance 음수 불가")(() =>
    api.functional.paymentsDiscounts.vouchers.post(connection, {
      body: {
        ...voucherPayload,
        balance: -5000,
      } as any,
    })
  );
  await TestValidator.error("누락 또는 잘못된 만료일")(() =>
    api.functional.paymentsDiscounts.vouchers.post(connection, {
      body: {
        ...voucherPayload,
        expires_at: "notADate",
      } as any,
    })
  );
  await TestValidator.error("누락/미입력 통화코드")(() =>
    api.functional.paymentsDiscounts.vouchers.post(connection, {
      body: {
        ...voucherPayload,
        currency: undefined as unknown as string,
      } as any,
    })
  );
  // 4. 이미 발급된 코드(code)로 또 발급하면 고유성 실패 검증
  await TestValidator.error("중복 바우처 코드")(() =>
    api.functional.paymentsDiscounts.vouchers.post(connection, {
      body: {
        ...voucherPayload,
        user_id: typia.random<string & tags.Format<"uuid">>(),
      },
    })
  );

  // 5. 성공 바우처 주요 필드/타입 assert 재확인
  typia.assert(created);
  if (created.created_at) {
    TestValidator.predicate("created_at 형식과 시점")(
      (typeof created.created_at === "string") && (created.created_at >= campaignStartAt)
    );
  }

  // redeemed_at(아직 미사용/미소멸) 필드는 null 또는 undefined임이 맞아야 함
  TestValidator.predicate("redeemed_at 미사용")(
    created.redeemed_at === null || created.redeemed_at === undefined
  );
}

