import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IVoucher } from "@ORGANIZATION/PROJECT-api/lib/structures/IVoucher";

/**
 * Test updating voucher details by ID with both valid and invalid changes.
 *
 * - First, create a voucher to serve as the update target.
 * - Perform a valid update (e.g., change expiry to a new valid future date).
 * - Confirm changes are reflected in the returned voucher and persisted.
 * - Attempt to update immutable fields (e.g., code, user_id) and expect validation errors.
 * - Try to set the expiry date to a past date and expect a validation error.
 * - Try updating a voucher with a random (non-existent) UUID, expect a 404 or not found error.
 */
export async function test_api_paymentsDiscounts_test_update_voucher_with_validation_and_failure_cases(connection: api.IConnection) {
  // 1. Create a voucher
  const createInput: IVoucher.ICreate = {
    user_id: typia.random<string & tags.Format<"uuid">>(),
    code: RandomGenerator.alphaNumeric(12),
    balance: 5000,
    currency: "KRW",
    expires_at: new Date(Date.now() + 7*24*3600*1000).toISOString(), // 7 days in future
  };
  const created = await api.functional.paymentsDiscounts.vouchers.post(connection, { body: createInput });
  typia.assert(created);

  // 2. Valid update: extend expiry and change campaign
  const updatePayload: IVoucher.IUpdate = {
    expires_at: new Date(Date.now() + 14*24*3600*1000).toISOString(), // 14 days in future
    campaign_id: typia.random<string & tags.Format<"uuid">>(),
  };
  const updated = await api.functional.paymentsDiscounts.vouchers.putById(connection, { id: created.id, body: updatePayload });
  typia.assert(updated);
  TestValidator.equals("expiry updated")(updatePayload.expires_at)(updated.expires_at);
  TestValidator.equals("campaign updated")(updatePayload.campaign_id)(updated.campaign_id);

  // 3. Negative test: try to update immutable field 'code' (should fail)
  await TestValidator.error("update immutable field 'code' fails")(async () => {
    await api.functional.paymentsDiscounts.vouchers.putById(connection, {
      id: created.id,
      body: { code: RandomGenerator.alphaNumeric(12) } as any, // code isn't in IUpdate so this is intentionally invalid typewise for illustration but should not be used.
    });
  });

  // 4. Negative test: set expiry to past date (should fail)
  await TestValidator.error("set expiry to past date fails")(async () => {
    await api.functional.paymentsDiscounts.vouchers.putById(connection, {
      id: created.id,
      body: { expires_at: new Date(Date.now() - 7*24*3600*1000).toISOString() } satisfies IVoucher.IUpdate,
    });
  });

  // 5. Negative test: update non-existent voucher
  await TestValidator.error("update non-existent voucher")(async () => {
    await api.functional.paymentsDiscounts.vouchers.putById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
      body: updatePayload,
    });
  });
}

