import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IVoucher } from "@ORGANIZATION/PROJECT-api/lib/structures/IVoucher";

/**
 * Test updating voucher details by ID with both valid and invalid changes.
 *
 * This test verifies that voucher detail updates via /paymentsDiscounts/vouchers/:id
 * work as expected: persistence of changes, business validation failures, and proper
 * error codes for not found or invalid input cases.
 *
 * Steps:
 * 1. Create a voucher to serve as update target
 * 2. Perform a valid update (extend future expiry and assign campaign)
 * 3. Verify the update was applied
 * 4. Try to update expiry to a past date (expect validation failure)
 * 5. Attempt to update a non-existent voucher (expect a 404 not found)
 */
export async function test_api_paymentsDiscounts_test_update_voucher_with_validation_and_failure_cases(
  connection: api.IConnection,
) {
  // 1. Create a new voucher
  const createInput: IVoucher.ICreate = {
    user_id: typia.random<string & tags.Format<"uuid">>(),
    code: RandomGenerator.alphaNumeric(16),
    balance: 5000,
    currency: "KRW",
    // Set a future expiry
    expires_at: new Date(Date.now() + 7 * 24 * 3600 * 1000).toISOString(),
  };
  const voucher = await api.functional.paymentsDiscounts.vouchers.post(connection, { body: createInput });
  typia.assert(voucher);

  // 2. Valid update: extend expiry and assign to new campaign
  const updatePayload: IVoucher.IUpdate = {
    expires_at: new Date(Date.now() + 14 * 24 * 3600 * 1000).toISOString(),
    campaign_id: typia.random<string & tags.Format<"uuid">>(),
  };
  const updated = await api.functional.paymentsDiscounts.vouchers.putById(connection, {
    id: voucher.id,
    body: updatePayload,
  });
  typia.assert(updated);
  TestValidator.equals("expiry updated")(updatePayload.expires_at)(updated.expires_at);
  TestValidator.equals("campaign updated")(updatePayload.campaign_id)(updated.campaign_id);

  // 3. Negative test: set expiry to a past date → should fail
  await TestValidator.error("set expiry to past date fails")(async () => {
    await api.functional.paymentsDiscounts.vouchers.putById(connection, {
      id: voucher.id,
      body: {
        expires_at: new Date(Date.now() - 7 * 24 * 3600 * 1000).toISOString(),
      } satisfies IVoucher.IUpdate,
    });
  });

  // 4. Negative test: update with random (non-existent) voucher id → should 404
  await TestValidator.error("update non-existent voucher fails")(async () => {
    await api.functional.paymentsDiscounts.vouchers.putById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
      body: updatePayload,
    });
  });
}

