import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IVoucher } from "@ORGANIZATION/PROJECT-api/lib/structures/IVoucher";

/**
 * 소프트 삭제(삭제 처리)된 바우처의 정상적인 삭제 및 권한/존재성 오류 확인
 *
 * 이 테스트는 아래의 주요 검증 시나리오를 포함합니다.
 * 1. 신규 바우처 발급 → 정상 삭제를 수행하고 삭제된 바우처가 더 이상 조회되지 않음을 확인
 * 2. 권한이 부족한 계정(또는 인증되지 않은 상태)에서 삭제 시도 → 권한 오류 발생 확인
 * 3. 존재하지 않는 ID로 삭제 시도 → 적절한 에러 응답 확인
 *
 * 단계별 절차
 * 1. 의존성으로 새로운 바우처를 생성한다 (paymentsDiscounts.vouchers.post)
 * 2. 생성한 바우처 id로 정상 삭제(soft-delete)를 수행
 * 3. 동일 id로 재삭제 시도(IDEMPOTENCY 또는 관련 메시지 확인)
 * 4. 임의의 무작위/존재하지 않는 UUID로 삭제 요청 → "존재하지 않음" 에러/응답 확인
 * 5. 권한 없는 상태에서 삭제 요청(Authorization 헤더 미포함) → 권한 에러(401/403) 발생 확인
 */
export async function test_api_paymentsDiscounts_test_delete_voucher_soft_delete_and_permissions(
  connection: api.IConnection,
) {
  // 1. 바우처 신규 발급
  const voucherInput: IVoucher.ICreate = {
    user_id: typia.random<string & tags.Format<"uuid">>(),
    code: RandomGenerator.alphaNumeric(12),
    balance: 50000,
    currency: "KRW",
  };
  const voucher = await api.functional.paymentsDiscounts.vouchers.post(connection, { body: voucherInput });
  typia.assert(voucher);

  // 2. 생성한 바우처 id로 정상 삭제(soft-delete)
  const deletedVoucher = await api.functional.paymentsDiscounts.vouchers.eraseById(connection, { id: voucher.id });
  typia.assert(deletedVoucher);
  TestValidator.equals("삭제된 바우처 ID")(voucher.id)(deletedVoucher.id);

  // 3. 동일 id로 재삭제 시도(idempotency 또는 결과 메시지 확인)
  await api.functional.paymentsDiscounts.vouchers.eraseById(connection, { id: voucher.id });

  // 4. 임의의 존재하지 않는 id(UUID)로 삭제 시도 → 에러(assert error 404)
  await TestValidator.error("존재하지 않는 id 삭제 시 404 에러")(() =>
    api.functional.paymentsDiscounts.vouchers.eraseById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
    }),
  );

  // 5. 인증/권한 없는 상태에서 삭제 요청 (Authorization 없음) → 권한 에러(assert error 401/403)
  if (connection.headers && connection.headers.Authorization) {
    const connectionNoAuth = { ...connection, headers: { ...connection.headers, Authorization: undefined } };
    await TestValidator.error("권한 없는 삭제 시 401/403 에러")(() =>
      api.functional.paymentsDiscounts.vouchers.eraseById(connectionNoAuth, { id: voucher.id }),
    );
  }
}

