 * The operation is available to both end-users and operators, with RBAC
 * restricting visibility to a user’s own ledger (end-user) or the full corpus
 * (admin/analytics roles). Each search is evidence tracked, including request
 * params, response data, and actor ID. All mapping is to normalized table
 * fields; no denormalized summary in this endpoint.
 *
 * Errors (e.g., malformed query, RBAC violation) are logged in audit evidence
 * and return detailed, compliance-ready errors.
 *
 * @param props.connection
 * @param props.body Query/filter parameters for loyalty points
 *   pagination/search; mapped to ILoyaltyPoint.IRequest.
 * @path /paymentsDiscounts/loyaltyPoints
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export async function patch(
  connection: IConnection,
  props: patch.Props,
): Promise<patch.Response> {
  return !!connection.simulate
    ? patch.simulate(connection, props)
    : PlainFetcher.fetch(
        {
          ...connection,
          headers: {
            ...connection.headers,
            "Content-Type": "application/json",
          },
        },
        {
          ...patch.METADATA,
          path: patch.path(),
          status: null,
        },
        props.body,
      );
}
export namespace patch {
  export type Props = {
    /**
     * Query/filter parameters for loyalty points pagination/search; mapped
     * to ILoyaltyPoint.IRequest.
     */
    body: ILoyaltyPoint.IRequest;
  };
  export type Body = ILoyaltyPoint.IRequest;
  export type Response = IPageILoyaltyPoint;

  export const METADATA = {
    method: "PATCH",
    path: "/paymentsDiscounts/loyaltyPoints",
    request: {
      type: "application/json",
      encrypted: false,
    },
    response: {
      type: "application/json",
      encrypted: false,
    },
  } as const;

  export const path = () => "/paymentsDiscounts/loyaltyPoints";
  export const random = (
    g?: Partial<typia.IRandomGenerator>,
  ): IPageILoyaltyPoint => typia.random<IPageILoyaltyPoint>(g);
  export const simulate = (
    connection: IConnection,
    props: patch.Props,
  ): Response => {
    const assert = NestiaSimulator.assert({
      method: METADATA.method,
      host: connection.host,
      path: patch.path(),
      contentType: "application/json",
    });
    try {
      assert.body(() => typia.assert(props.body));
