import type { IPageILoyaltyPoint } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageILoyaltyPoint";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * E2E test for listing and filtering loyalty points records with a variety of filters and error states.
 *
 * Business context:
 * Loyalty points systems require robust evidence and auditability for rewards and redemptions. This test validates that users and admins can:
 *   - Search loyalty point ledgers by user, event type, transaction, and campaign,
 *   - Filter by date/time ranges,
 *   - Filter by awarded and spent/expired points,
 *   - Paginate results for large ledgers,
 *   - And receive proper error feedback for malformed searches or RBAC issues.
 *
 * Test steps:
 * 1. Create multiple loyalty point records for two random users (simulate awards and redemptions across several types, campaign/no campaign, with realistic timestamps).
 * 2. List records for one user. Confirm only their events are returned, and points are accurate (ignore cross-user data).
 * 3. Filter by known event types (e.g., 'earn', 'redeem') and validate only matching types appear.
 * 4. Filter by a tight date range and confirm only records within the window are returned.
 * 5. Test pagination: request first N, then next page, confirm no overlap and correct total/paging.
 * 6. Test search with invalid filter values (e.g., nonexistent user_id, nonsense date, bad event type) and confirm API returns compliance-ready error messages.
 */
export async function test_api_paymentsDiscounts_test_list_loyalty_points_records_with_various_filters(connection: api.IConnection) {
  // 1. Create sample loyalty points ledgers for two users
  const userA = typia.random<string & tags.Format<"uuid">>();
  const userB = typia.random<string & tags.Format<"uuid">>();
  // Simulate a mix of types and campaigns for diverse records
  const baseDate = new Date();
  const ledger: ILoyaltyPoint[] = ArrayUtil.repeat(20)(i => {
    const user = i < 10 ? userA : userB;
    const type = RandomGenerator.pick(["earn", "redeem", "expire", "bonus"]);
    return {
      id: typia.random<string & tags.Format<"uuid">>(),
      user_id: user,
      transaction_id: Math.random() > 0.5 ? typia.random<string & tags.Format<"uuid">>() : null,
      campaign_id: Math.random() > 0.7 ? typia.random<string & tags.Format<"uuid">>() : null,
      points: type === "redeem" || type === "expire" ? -Math.floor(Math.random() * 100) : Math.floor(Math.random() * 200) + 10,
      type: type,
      created_at: new Date(baseDate.getTime() - i * 1000 * 60 * 60).toISOString(),
    };
  });

  // Helper to filter ledger manually the way API should
  const filterLedger = (records: ILoyaltyPoint[], filter: Partial<ILoyaltyPoint.IRequest>) =>
    records.filter(e =>
      (filter.user_id === undefined || filter.user_id === e.user_id) &&
      (filter.type == null || filter.type === e.type) &&
      (filter.created_from == null || new Date(e.created_at) >= new Date(filter.created_from)) &&
      (filter.created_to == null || new Date(e.created_at) <= new Date(filter.created_to))
    );

  // 2. List all records for userA
  const respUserA = await api.functional.paymentsDiscounts.loyaltyPoints.patch(connection, {
    body: { user_id: userA },
  });
  typia.assert(respUserA);
  const should = filterLedger(ledger, { user_id: userA });
  TestValidator.equals("UserA-only loyalty points")(should.length)(respUserA.data.length);
  TestValidator.predicate("No data leakage to other users")(respUserA.data.every(e => e.user_id === userA));

  // 3. Filter by event type (e.g. 'earn')
  const respEarn = await api.functional.paymentsDiscounts.loyaltyPoints.patch(connection, {
    body: { user_id: userA, type: "earn" },
  });
  typia.assert(respEarn);
  const shouldEarn = filterLedger(ledger, { user_id: userA, type: "earn" });
  TestValidator.equals("Type=earn only")(shouldEarn.length)(respEarn.data.length);
  TestValidator.predicate("Correct types only")(respEarn.data.every(e => e.type === "earn" && e.user_id === userA));

  // 4. Filter by narrow date range for userB
  const from = ledger[15].created_at;
  const to = ledger[13].created_at;
  const respDate = await api.functional.paymentsDiscounts.loyaltyPoints.patch(connection, {
    body: { user_id: userB, created_from: from, created_to: to },
  });
  typia.assert(respDate);
  const shouldDate = filterLedger(ledger, { user_id: userB, created_from: from, created_to: to });
  TestValidator.equals("Date range result")(shouldDate.length)(respDate.data.length);
  TestValidator.predicate("Dates in range")(respDate.data.every(e => new Date(e.created_at) >= new Date(from) && new Date(e.created_at) <= new Date(to)));

  // 5. Test pagination for userA (first 3, then next 3)
  const respPage1 = await api.functional.paymentsDiscounts.loyaltyPoints.patch(connection, {
    body: { user_id: userA, limit: 3, page: 1 },
  });
  typia.assert(respPage1);
  TestValidator.equals("Pagination page1 count")(3)(respPage1.data.length);

  const respPage2 = await api.functional.paymentsDiscounts.loyaltyPoints.patch(connection, {
    body: { user_id: userA, limit: 3, page: 2 },
  });
  typia.assert(respPage2);
  // Check page 2 doesn't overlap page 1
  const idsPage1 = respPage1.data.map(e => e.id);
  const idsPage2 = respPage2.data.map(e => e.id);
  TestValidator.predicate("Pages are disjoint")(!idsPage1.some(id => idsPage2.includes(id)));

  // 6. Invalid filter: garbage user_id
  await TestValidator.error("Invalid user_id returns error")(async () => {
    await api.functional.paymentsDiscounts.loyaltyPoints.patch(connection, {
      body: { user_id: "not-a-uuid" },
    });
  });
  // 6b. Invalid filter: impossible event type
  await TestValidator.error("Invalid type returns error")(async () => {
    await api.functional.paymentsDiscounts.loyaltyPoints.patch(connection, {
      body: { type: "thisDoesNotExist" },
    });
  });
  // 6c. Invalid filter: created_from after created_to
  await TestValidator.error("created_from after created_to returns error")(async () => {
    await api.functional.paymentsDiscounts.loyaltyPoints.patch(connection, {
      body: { created_from: "2100-01-01T00:00:00.000Z", created_to: "2000-01-01T00:00:00.000Z" },
    });
  });
}

