import { tags } from "typia";

/**
 * Loyalty points ledger entry. Represents atomic user reward/action event
 * (earn, redeem, etc). Fully evidence-compliant as per schema and business
 * requirements.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type ILoyaltyPoint = {
  /**
   * Primary key of the loyalty points entry.
   *
   * Direct reference to loyalty_points.id. Uniquely identifies a ledger
   * record for compliance, analytics, and reference.
   */
  id: string & tags.Format<"uuid">;

  /**
   * The unique identifier of the user associated with this point event.
   *
   * Direct from loyalty_points.user_id. Required for audit, analytics, and
   * user-facing displays.
   */
  user_id: string & tags.Format<"uuid">;

  /**
   * Transaction identifier if the event is driven by a transaction.
   *
   * From loyalty_points.transaction_id; null if unrelated to transaction.
   */
  transaction_id?: (string & tags.Format<"uuid">) | null;

  /**
   * Campaign reference for campaign-driven loyalty events.
   *
   * Direct from loyalty_points.campaign_id; nullable.
   */
  campaign_id?: (string & tags.Format<"uuid">) | null;

  /**
   * Number of loyalty points accrued or deducted (positive or negative).
   *
   * Maps to loyalty_points.points. Required for all analytics/compliance
   * queries.
   */
  points: number &
    tags.JsonSchemaPlugin<{
      format: "double";
    }>;

  /**
   * Type of loyalty event (e.g., 'earn', 'redeem', 'bonus', 'expire').
   *
   * Mapped directly from loyalty_points.type. Enum enforced by business
   * logic/UI.
   */
  type: string;

  /**
   * Atomic creation timestamp of the loyalty event (UTC).
   *
   * Core evidence field. From loyalty_points.created_at.
   */
  created_at: string & tags.Format<"date-time">;
};
export namespace ILoyaltyPoint {
  /**
   * Query request for paginated loyalty_points listing. All fields map to
   * loyalty_points schema fields, supporting analytics, compliance and
   * evidence-focused filtering for audit and reporting.
   */
  export type IRequest = {
    /**
     * The unique identifier of the user whose loyalty points are being
     * queried.
     *
     * Referenced from loyalty_points.user_id in schema. Atomic, immutable,
     * used for filtering user-specific histories.
     */
    user_id?: string & tags.Format<"uuid">;

    /**
     * The identifier of the transaction associated with the loyalty points
     * entry.
     *
     * Referenced from loyalty_points.transaction_id. Optional for filtering
     * events sourced from specific transactions or business event types.
     */
    transaction_id?: (string & tags.Format<"uuid">) | null;

    /**
     * The unique campaign identifier, applicable for filtering entries
     * connected to campaign-driven point events.
     *
     * Directly from loyalty_points.campaign_id column. Required for
     * campaign/scenario-specific ledger breakdown.
     */
    campaign_id?: (string & tags.Format<"uuid">) | null;

    /**
     * The event type for the points record (e.g., 'earn', 'redeem',
     * 'expire').
     *
     * Allows searching by event categories for analytics and reporting. See
     * loyalty_points.type.
     */
    type?: string | null;

    /**
     * Start timestamp for time range filtering. Used for analytics or
     * regulatory evidence queries.
     */
    created_from?: (string & tags.Format<"date-time">) | null;

    /**
     * End timestamp for time range filtering. Used for analytics or
     * regulatory evidence queries.
     */
    created_to?: (string & tags.Format<"date-time">) | null;

    /** The page number to retrieve. Default is 1 as per pagination contract. */
    page?:
      | (number &
          tags.Type<"int32"> &
          tags.JsonSchemaPlugin<{
            format: "uint32";
          }>)
      | null;

    /**
     * How many records per page to return. Default/max values enforced at
     * service level for performance/evidence compliance.
     */
    limit?:
      | (number &
          tags.Type<"int32"> &
          tags.JsonSchemaPlugin<{
            format: "uint32";
          }>)
      | null;
  };
}

