import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ILoyaltyPoint } from "@ORGANIZATION/PROJECT-api/lib/structures/ILoyaltyPoint";

/**
 * 테스트 목적:
 *   1. 올바른 ID로 적립금 원장(로열티 포인트) 단건 조회 API의 상세 정보 정확성을 검증한다.
 *   2. 존재하지 않는 ID로 조회 시 404 Not Found 에러를, 다른 사용자가 소유한 원장에 접근하는 경우 권한 거부(403 등)을 검증한다.
 *
 * 비즈니스 컨텍스트:
 *   적립금 원장 조회는 유저 본인 및 감사/관리자 등 RBAC 정책에 의해 엄격히 제한된다. 단건 조회가 성공할 경우 ID, 적립/차감 기록, 사건 원인, 생성 시각 등 모든 세부 정보를 반환해야 한다. 존재하지 않는 원장은 404, 타인 소유의 원장은 권한 에러를 반환한다.
 *
 * 테스트 단계:
 *   1. 테스트용 유저 A와 B를 생성한다(시뮬레이션 환경 기준; 실제 서비스에서는 로그인 절차 필요).
 *   2. 유저 A 명의로 적립금 이벤트 단건을 생성한다.
 *   3. 정상적으로 해당 ID로 단건 조회 후 반환 상세 정보와 입력 데이터 일치 검증.
 *   4. 무작위/존재하지 않는 UUID로 조회 시 404 반환.
 *   5. 유저 B로 로그인 후 유저 A의 원장 ID로 조회 시 권한 거부(403 등) 에러 반환.
 */
export async function test_api_paymentsDiscounts_test_get_loyalty_point_record_by_id_and_permissions(connection: api.IConnection) {
  // 1. 유저 A, B를 시뮬레이션 (실제 환경에서는 회원가입/로그인 필요)
  //    NOTE: connection.headers로 임의 user_id 주입 또는 시나리오별 상황별 연결 사용.
  const userAId = typia.random<string & tags.Format<"uuid">>();
  const userBId = typia.random<string & tags.Format<"uuid">>();

  // 2. 유저 A가 포인트 적립 이벤트 생성
  const loyaltyCreateInput: ILoyaltyPoint.ICreate = {
    user_id: userAId,
    points: 100,
    type: "earn",
  };
  const created: ILoyaltyPoint = await api.functional.paymentsDiscounts.loyaltyPoints.post(connection, { body: loyaltyCreateInput });
  typia.assert(created);

  // 3. 정상이력 ID로 단건 조회 - 상세 정보 일치 확인
  const read: ILoyaltyPoint = await api.functional.paymentsDiscounts.loyaltyPoints.getById(connection, { id: created.id });
  typia.assert(read);
  TestValidator.equals("id")(created.id)(read.id);
  TestValidator.equals("user_id")(userAId)(read.user_id);
  TestValidator.equals("points")(loyaltyCreateInput.points)(read.points);
  TestValidator.equals("type")(loyaltyCreateInput.type)(read.type);

  // 4. 무작위(존재하지 않는) ID 조회 → 404
  const nonExistentId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("not found for non-existent id")(async () => {
    await api.functional.paymentsDiscounts.loyaltyPoints.getById(connection, { id: nonExistentId });
  });

  // 5. 유저 B 시점에서 유저 A 소유 ID 조회 시 권한 거부 에러 (RBAC 불가)
  //   - 실 서비스라면 connection을 userB의 토큰으로 변경해야 함
  //   - 여기서는 user_id를 지정해 실제 요청처럼 최대한 시뮬레이션
  //     (실제 테스트 환경의 connection/user_id/role 관리방식에 맞게 조정 필요)
  const userBConnection = { ...connection, headers: { ...connection.headers, "x-user-id": userBId } };
  await TestValidator.error("RBAC access denied for other's record")(async () => {
    await api.functional.paymentsDiscounts.loyaltyPoints.getById(userBConnection, { id: created.id });
  });
}

