import api from "@ORGANIZATION/PROJECT-api";
import type { ILoyaltyPoint } from "@ORGANIZATION/PROJECT-api/lib/structures/ILoyaltyPoint";

/**
 * 로열티 포인트(적립금 원장) 단건 조회 및 권한 검증 API E2E 테스트.
 *
 * **목적**
 * - 정상적인 ID로 적립금 원장 단건 상세 조회 성공 및 데이터 정확성 확인.
 * - 존재하지 않는 UUID로 요청 시 404 NotFound 발생 보장.
 * - 타인 소유의 원장에 대한 RBAC 접근 거부(403 등) 보장.
 *
 * **비즈니스 컨텍스트**
 * - 적립금/로열티 포인트 원장 조회는 소유 유저(본인) 및 감사/운영 관리자 등 한정적으로 허용된다.
 * - 자신의 이벤트만 정상 단건 조회되고, 타인의 event는 권한 없는 요청으로 처리되어야 함.
 * - 모든 이벤트는 증적 단위로 불변 기록되어야 하며, 단건 상세 정보는 생성값과 일치해야 함.
 *
 * **테스트 단계**
 * 1. 유저 A, 유저 B의 UUID를 시뮬레이션으로 준비한다.
 * 2. 유저 A 소유의 적립금 이벤트를 1건 생성한다.
 * 3. 해당 ID로 단건 조회 API 호출 후 상세 정보 및 입력값 정확성(식별자, 금액, 타입 등) 검증.
 * 4. 무작위(존재하지 않는) UUID로 조회 시 404 Not Found 오류 반환 검증.
 * 5. 유저 B(시뮬 연결)로 유저 A 소유 이벤트를 조회 시 RBAC 접근 거부(403 등) 오류 반환을 검증.
 */
export async function test_api_paymentsDiscounts_test_get_loyalty_point_record_by_id_and_permissions(
  connection: api.IConnection,
) {
  // 1. 테스트 유저 A, B용 UUID 준비 (실제 서비스라면 회원가입/로그인 필요)
  const userAId: string & tags.Format<"uuid"> = typia.random<string & tags.Format<"uuid">>();
  const userBId: string & tags.Format<"uuid"> = typia.random<string & tags.Format<"uuid">>();

  // 2. 유저 A 소유 적립금 이벤트 1건 생성
  const createInput: ILoyaltyPoint.ICreate = {
    user_id: userAId,
    points: 100,
    type: "earn",
  };
  const created: ILoyaltyPoint = await api.functional.paymentsDiscounts.loyaltyPoints.post(connection, {
    body: createInput,
  });
  typia.assert(created);

  // 3. 정상 ID로 단건 상세 조회 → 모든 필드/값 일치
  const read: ILoyaltyPoint = await api.functional.paymentsDiscounts.loyaltyPoints.getById(connection, {
    id: created.id,
  });
  typia.assert(read);
  TestValidator.equals("id")(created.id)(read.id);
  TestValidator.equals("user_id")(userAId)(read.user_id);
  TestValidator.equals("points")(createInput.points)(read.points);
  TestValidator.equals("type")(createInput.type)(read.type);

  // 4. 존재하지 않는 무작위 UUID로 단건 조회 요청 → 404
  const randomId: string & tags.Format<"uuid"> = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("not found 404 for random UUID")(async () => {
    await api.functional.paymentsDiscounts.loyaltyPoints.getById(connection, {
      id: randomId,
    });
  });

  // 5. 유저 B 연결로 타인(A) 소유 이벤트 단건 조회 → RBAC 접근 거부(403 등)
  const userBConnection: api.IConnection = {
    ...connection,
    headers: {
      ...connection.headers,
      "x-user-id": userBId,
    },
  };
  await TestValidator.error("RBAC forbidden by user B")(async () => {
    await api.functional.paymentsDiscounts.loyaltyPoints.getById(userBConnection, {
      id: created.id,
    });
  });
}

