import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ILoyaltyPoint } from "@ORGANIZATION/PROJECT-api/lib/structures/ILoyaltyPoint";

/**
 * E2E test for awarding a new loyalty point event, including validation and error handling.
 *
 * This test validates the creation of a loyalty point ledger entry using all required fields
 * (user_id, points, type, and optional transaction/campaign linkage). It ensures that:
 *   - Proper events can be awarded under normal and edge-case data scenarios.
 *   - Required fields cause an error if missing or invalid.
 *   - The system enforces business logic (such as no duplicated identical event, if applicable).
 *
 * Workflow:
 * 1. Create a valid loyalty point ledger event for a user and validate the result.
 * 2. Attempt to create a similar event for the same user/event with duplication to test idempotency (if enforced).
 * 3. Attempt to create an event omitting one or more required fields to ensure validation errors are thrown.
 * 4. Attempt to create an event with invalid data (e.g., negative points in earn event, unsupported type, or malformed user_id).
 * 5. Test with optional fields present and absent.
 * 6. Validate that every successful event returns full, asserted output and each failed scenario produces expected errors.
 */
export async function test_api_paymentsDiscounts_test_create_loyalty_point_event_with_validation(
  connection: api.IConnection,
) {
  // 1. Create a valid loyalty point event
  const user_id = typia.random<string & tags.Format<"uuid">>();
  const validBody = {
    user_id,
    points: 100,
    type: "earn",
    transaction_id: typia.random<string & tags.Format<"uuid">>(),
    campaign_id: null,
  } satisfies ILoyaltyPoint.ICreate;
  const result = await api.functional.paymentsDiscounts.loyaltyPoints.post(connection, { body: validBody });
  typia.assert(result);
  TestValidator.equals("user id")(user_id)(result.user_id);

  // 2. Test duplication/idempotency if business rule applies
  await TestValidator.error("duplicate event")(() =>
    api.functional.paymentsDiscounts.loyaltyPoints.post(connection, { body: validBody })
  );

  // 3. Omit a required field (user_id)
  await TestValidator.error("missing user_id")(() =>
    api.functional.paymentsDiscounts.loyaltyPoints.post(connection, { body: { ...validBody, user_id: undefined as any } })
  );

  // 4. Invalid data: negative points in earn event
  await TestValidator.error("negative points in earn")(() =>
    api.functional.paymentsDiscounts.loyaltyPoints.post(connection, { body: { ...validBody, points: -50 } })
  );

  // 5. Invalid user_id format
  await TestValidator.error("invalid user_id format")(() =>
    api.functional.paymentsDiscounts.loyaltyPoints.post(connection, { body: { ...validBody, user_id: "not-a-uuid" as any } })
  );

  // 6. Unsupported type
  await TestValidator.error("invalid type")(() =>
    api.functional.paymentsDiscounts.loyaltyPoints.post(connection, { body: { ...validBody, type: "unsupported" } })
  );

  // 7. Optional fields omitted (no transaction_id/campaign_id)
  const minimalBody = {
    user_id: typia.random<string & tags.Format<"uuid">>(),
    points: 10,
    type: "redeem"
  } satisfies ILoyaltyPoint.ICreate;
  const minimalResult = await api.functional.paymentsDiscounts.loyaltyPoints.post(connection, { body: minimalBody });
  typia.assert(minimalResult);
  TestValidator.equals("user id (minimal)")(minimalBody.user_id)(minimalResult.user_id);
}

