import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IRefund } from "@ORGANIZATION/PROJECT-api/lib/structures/IRefund";
import type { IPageIRefund } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIRefund";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * E2E test for listing/searching refund events with filters, pagination, access control, and error handling
 *
 * Business Context:
 * This test validates the /paymentsDiscounts/refunds PATCH API, ensuring: filtering by transaction_id, status, dates; correct pagination; robust validation/errors for bad filters; and strict access control for different users.
 *
 * Steps:
 * 1. Log in as admin and list refunds using valid filters (transaction_id, status, date ranges).
 *    - Assert that all returned refunds match applied filters.
 *    - Paginate and check correctness of pagination fields/data.
 * 2. Try bad-case filters: malformed uuid, bad status, invalid date, negative page/limit; expect proper error or validation responses.
 * 3. Log in as a regular user, request all refunds; ensure only own are returned (or permission denied for others’).
 * 4. Remove authentication and attempt a request; expect access denied error.
 */
export async function test_api_paymentsDiscounts_test_list_refund_events_with_filters_and_permissions(
  connection: api.IConnection,
) {
  // Helper: Save/restore auth header
  const originalAuth = connection.headers?.Authorization;

  // -- Data Setup (ideally via test API or seeding, here random IDs for demo) --
  // Assumed that at least one refund exists matching these
  const knownRefund: IRefund = typia.random<IRefund>();
  const altRefund: IRefund = typia.random<IRefund>();

  // Admin credentials (simulate)
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "Test123!";

  // User credentials (simulate)
  const userEmail = typia.random<string & tags.Format<"email">>();
  const userPassword = "Test123!";

  // 1. [ADMIN] Simulate login (replace with login API if present)
  if (connection.headers)
    connection.headers.Authorization = `Bearer admin-token-mock`;

  // 1a. List refunds with filter: by transaction_id
  const byTransaction = await api.functional.paymentsDiscounts.refunds.patch(
    connection,
    {
      body: { transaction_id: knownRefund.transaction_id } satisfies IRefund.IRequest,
    }
  );
  typia.assert(byTransaction);
  TestValidator.predicate("all refunds match transaction id")(byTransaction.data.every(r => r.transaction_id === knownRefund.transaction_id));

  // 1b. List refunds with filter: by status
  const byStatus = await api.functional.paymentsDiscounts.refunds.patch(
    connection,
    { body: { status: knownRefund.status } satisfies IRefund.IRequest },
  );
  typia.assert(byStatus);
  TestValidator.predicate("all refunds match status")(byStatus.data.every(r => r.status === knownRefund.status));

  // 1c. List refunds with filter: date range (requested_at)
  const dateFrom = knownRefund.requested_at;
  const dateTo = typia.random<string & tags.Format<"date-time">>();
  const byDate = await api.functional.paymentsDiscounts.refunds.patch(
    connection,
    {
      body: {
        requested_from: dateFrom,
        requested_to: dateTo,
      } satisfies IRefund.IRequest,
    }
  );
  typia.assert(byDate);
  TestValidator.predicate("all refunds requested after from-date")(
    byDate.data.every(r => r.requested_at >= dateFrom && r.requested_at <= dateTo)
  );

  // 1d. Check pagination: small limit, check pages
  const paged = await api.functional.paymentsDiscounts.refunds.patch(
    connection,
    {
      body: {
        limit: 1,
        page: 1,
      } satisfies IRefund.IRequest,
    }
  );
  typia.assert(paged);
  TestValidator.equals("page number")(1)(paged.pagination.current);
  TestValidator.equals("limit")(1)(paged.pagination.limit);

  // 1e. Second page
  const paged2 = await api.functional.paymentsDiscounts.refunds.patch(
    connection,
    {
      body: {
        limit: 1,
        page: 2,
      } satisfies IRefund.IRequest,
    }
  );
  typia.assert(paged2);
  TestValidator.equals("page number")(2)(paged2.pagination.current);

  // 2. Invalid filters trigger errors
  // 2a. Malformed uuid
  await TestValidator.error("patch: bad uuid filter triggers error")(() =>
    api.functional.paymentsDiscounts.refunds.patch(connection, {
      body: { transaction_id: "not-a-uuid" as any },
    })
  );
  // 2b. Impossible status
  await TestValidator.error("patch: bad status filter triggers error")(() =>
    api.functional.paymentsDiscounts.refunds.patch(connection, {
      body: { status: "not-a-status" },
    })
  );
  // 2c. Invalid date
  await TestValidator.error("patch: bad date filter triggers error")(() =>
    api.functional.paymentsDiscounts.refunds.patch(connection, {
      body: { requested_from: "not-a-date" as any },
    })
  );
  // 2d. Negative page/limit
  await TestValidator.error("patch: negative page triggers error")(() =>
    api.functional.paymentsDiscounts.refunds.patch(connection, {
      body: { page: -1 as any },
    })
  );
  await TestValidator.error("patch: negative limit triggers error")(() =>
    api.functional.paymentsDiscounts.refunds.patch(connection, {
      body: { limit: -5 as any },
    })
  );

  // 3. [USER] Simulate user login (if available, else simulate)
  if (connection.headers)
    connection.headers.Authorization = `Bearer user-token-mock`;
  // Attempt to list ALL refunds (should only see user's, or error/empty)
  const userList = await api.functional.paymentsDiscounts.refunds.patch(
    connection,
    { body: {} as IRefund.IRequest },
  );
  typia.assert(userList);
  // Extra logic could validate user only sees own data; here just typia check.

  // 4. [UNAUTHENTICATED] Remove auth, expect error
  if (connection.headers)
    delete connection.headers.Authorization;
  await TestValidator.error("patch: unauthenticated list triggers error")(() =>
    api.functional.paymentsDiscounts.refunds.patch(connection, {
      body: {} as IRefund.IRequest,
    })
  );

  // Restore auth
  if (connection.headers)
    connection.headers.Authorization = originalAuth;
}

