 */
export type ITransaction = {
  /**
   * Unique identifier for the transaction event. Maps to transactions.id.
   * Primary key referenced in all audit and evidence flows.
   */
  id: string & tags.Format<"uuid">;

  /**
   * User performing or credited with the transaction. Matches
   * transactions.user_id. Required for compliance/person trace.
   */
  user_id: string & tags.Format<"uuid">;

  /**
   * Optional reference to linked order (if transaction relates to
   * checkout/payment, null for top-ups or external events). See
   * transactions.order_id.
   */
  order_id?: (string & tags.Format<"uuid">) | null;

  /**
   * Categorized type of business event (purchase, refund, credit, debit,
   * wallet-topup, etc). Required. See transactions.type.
   */
  type: string;

  /**
   * Record creation timestamp (ISO8601/UTC), supporting compliance and
   * regulatory analytics. See transactions.created_at.
   */
  created_at: string & tags.Format<"date-time">;

  /**
   * Context or memo for transaction, e.g., payment reason or event note.
   * Optional. See transactions.description.
   */
  description?: string | null;
};
