  export type ICreate = {
    /**
     * User who is assigned or performing the transaction. Required. See
     * transactions.user_id.
     */
    user_id: string & tags.Format<"uuid">;

    /**
     * Order event triggering the transaction. Null for wallet or standalone
     * events. See transactions.order_id.
     */
    order_id?: (string & tags.Format<"uuid">) | null;

    /**
     * Transaction type ('purchase', 'refund', etc). Business context. See
     * transactions.type.
     */
    type: string;

    /**
     * Timestamp the event occurs. Required for evidence trace
