 */
export async function test_api_paymentsDiscounts_test_create_refund_event_with_validation_and_business_constraints(connection: api.IConnection) {
  // 1. 환불 대상 트랜잭션 생성
  const transaction = await api.functional.paymentsDiscounts.transactions.post(connection, {
    body: {
      user_id: typia.random<string & tags.Format<"uuid">>(),
      order_id: typia.random<string & tags.Format<"uuid">>(),
      type: "purchase",
      created_at: new Date().toISOString(),
      description: "테스트용 트랜잭션"
    } satisfies ITransaction.ICreate
  });
  typia.assert(transaction);

  // 2. 정상 환불 이벤트 생성
  const refundInput: IRefund.ICreate = {
    payment_id: typia.random<string & tags.Format<"uuid">>(),
    transaction_id: transaction.id,
    order_id: transaction.order_id,
    amount: 10000,
    currency: "KRW",
    status: "requested",
    reason: "테스트 환불"
  };
  const refund = await api.functional.paymentsDiscounts.refunds.post(connection, { body: refundInput });
  typia.assert(refund);
  TestValidator.equals("환불 트랜잭션 일치")(transaction.id)(refund.transaction_id);
  TestValidator.equals("환불 금액")(refundInput.amount)(refund.amount);
  TestValidator.equals("환불 상태")(refundInput.status)(refund.status);

  // 3. 잘못된 입력: 필수 필드 누락
  await TestValidator.error("필수 필드 누락 오류")(() =>
    api.functional.paymentsDiscounts.refunds.post(connection, { body: {
      // payment_id 누락
      transaction_id: transaction.id,
      amount: 10000,
      currency: "KRW",
      status: "requested"
    } as any })
  );

  // 3-2. 잘못된 입력: 타입 오류
  await TestValidator.error("타입 오류(amount string)")(() =>
    api.functional.paymentsDiscounts.refunds.post(connection, { body: {
      payment_id: typia.random<string & tags.Format<"uuid">>(),
      transaction_id: transaction.id,
      amount: "10000", // 숫자 대신 문자열
      currency: "KRW",
      status: "requested"
    } as any })
  );

  // 4. 같은 트랜잭션 중복 환불 (비즈니스 오류)
  await TestValidator.error("중복 환불 방지 오류")(() =>
    api.functional.paymentsDiscounts.refunds.post(connection, { body: refundInput })
  );
}

