import type { ICoreLocale } from "@ORGANIZATION/PROJECT-api/lib/structures/ICoreLocale";

/**
 * Validate update of locale records and error handling.
 *
 * This test covers updating locale details by ID, confirming changes have persisted, as well as error scenarios including not-found records, missing required fields, and duplicate codes (violating uniqueness constraint).
 *
 * Steps:
 * 1. Create a locale (so we have a valid id).
 * 2. Update some or all fields by id, confirm the update is reflected in the system (GET again or check response).
 * 3. Try to update a non-existent id (random UUID), expect and assert not-found error.
 * 4. Attempt to update the record with a code that collides with another existing locale, ensure proper error.
 * 5. Test behavior of updating with missing required data (invalid input), e.g. empty code string, both fields null, etc.; confirm API rejects and returns proper validation error.
 */
export async function test_api_core_test_update_locale_by_id_success_and_error_cases(
  connection: api.IConnection,
) {
  // 1. Create initial locale record A
  const localeA: ICoreLocale = await api.functional.core.locales.post(connection, {
    body: {
      code: "en-US",
      name: "English (United States)",
    } satisfies ICoreLocale.ICreate,
  });
  typia.assert(localeA);

  // Create a second unique locale B for duplicate code test
  const localeB: ICoreLocale = await api.functional.core.locales.post(connection, {
    body: {
      code: "fr-FR",
      name: "French (France)",
    } satisfies ICoreLocale.ICreate,
  });
  typia.assert(localeB);

  // 2. Update locale A's name
  const updatedLocale: ICoreLocale = await api.functional.core.locales.putById(connection, {
    id: localeA.id,
    body: {
      name: "US English (changed)",
    } satisfies ICoreLocale.IUpdate,
  });
  typia.assert(updatedLocale);
  TestValidator.equals("locale name updated")("US English (changed)")(updatedLocale.name);

  // 3. Update a non-existent id
  await TestValidator.error("update non-existent locale yields not-found error")(async () => {
    await api.functional.core.locales.putById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
      body: { name: "Ghost" },
    });
  });

  // 4. Attempt invalid update (duplicate code)
  await TestValidator.error("update locale with duplicate code") (async () => {
    await api.functional.core.locales.putById(connection, {
      id: localeA.id,
      body: { code: localeB.code },
    });
  });

  // 5. Attempt update with invalid input (empty code)
  await TestValidator.error("update locale with empty code fails") (async () => {
    await api.functional.core.locales.putById(connection, {
      id: localeA.id,
      body: { code: "" },
    });
  });

  // 6. Attempt update with both fields null (which is allowed as per IUpdate, but may fail validation if required by business rule)
  await TestValidator.error("update locale with both fields null or missing fails") (async () => {
    await api.functional.core.locales.putById(connection, {
      id: localeA.id,
      body: { code: null, name: null },
    });
  });
}

