/**
 * Describes a single locale/language-region entry in the Core `locales` table.
 *
 * Provides BCP 47 compliance for regional multi-language support, see
 * requirements for accessible and multicultural flows.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type ICoreLocale = {
  /**
   * Unique identifier for the locale record. `locales.id`.
   *
   * Evidence-grade, never reused or recycled.
   */
  id: string & tags.Format<"uuid">;

  /**
   * BCP 47 code for the locale (`locales.code`).
   *
   * Used throughout the system to context-switch localizations/UI. E.g.,
   * 'en-US', 'ko-KR'.
   */
  code: string;

  /**
   * Human-readable local name (`locales.name`).
   *
   * Used in UIs, preference selectors, and reporting.
   */
  name: string;
};
export namespace ICoreLocale {
  /**
   * Payload for creating a new locale/language-region entry.
