import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ICoreLocale } from "@ORGANIZATION/PROJECT-api/lib/structures/ICoreLocale";

/**
 * Validate deletion behavior for core locale entries.
 *
 * This test verifies that deleting a locale by ID results in a soft-delete that preserves evidence (audit trail); attempts to delete already deleted or non-existent entries should produce clear errors.
 *
 * Steps:
 * 1. Create a new locale (to guarantee a deletable record).
 * 2. Delete the locale and validate the structure and content of the returned IDeleteResult.
 * 3. Attempt to delete the same locale again, assert that an error (not-found or already-deleted) is thrown.
 * 4. Attempt to delete a random non-existent locale ID (same format), expect error thrown and verify error information.
 */
export async function test_api_core_test_delete_locale_by_id_and_non_existent_case(
  connection: api.IConnection,
) {
  // 1. Create a new locale to ensure a valid entry for deletion
  const localeInput: ICoreLocale.ICreate = {
    code: `e2e-${RandomGenerator.alphaNumeric(6)}`,
    name: `E2E Test Locale ${RandomGenerator.alphabets(3)}`,
  };
  const created: ICoreLocale = await api.functional.core.locales.post(connection, {
    body: localeInput,
  });
  typia.assert(created);

  // 2. Delete the locale by ID
  const deleteResult: ICoreLocale.IDeleteResult = await api.functional.core.locales.eraseById(connection, {
    id: created.id,
  });
  typia.assert(deleteResult);
  TestValidator.equals("deleteResult.success")(true)(deleteResult.success);
  TestValidator.equals("deleteResult.locale_id matches")(created.id)(deleteResult.locale_id);
  TestValidator.predicate("deleteResult.deleted_at - ISO string")(!!Date.parse(deleteResult.deleted_at));

  // 3. Try deleting the same locale again (should fail)
  await TestValidator.error("Deleting already-deleted locale should fail")(() =>
    api.functional.core.locales.eraseById(connection, {
      id: created.id,
    }),
  );

  // 4. Try deleting a non-existent random locale ID
  await TestValidator.error("Deleting non-existent locale should fail")(() =>
    api.functional.core.locales.eraseById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
    }),
  );
}

