/**
 * Validate deletion behavior for core locale entries.
 *
 * 이 테스트는 ID로 로케일을 삭제 시, 증거(감사 추적)를 보존하는 soft-delete가 정상적으로 동작하는지 검증합니다. 이미 삭제된 항목이나 존재하지 않는 엔트리를 삭제 시도하면 명확한 오류가 발생하는지도 확인합니다.
 *
 * 프로세스:
 * 1. 삭제가 가능한 레코드를 보장하기 위해 새로운 locale을 생성합니다.
 * 2. 해당 locale을 삭제한 뒤, IDeleteResult의 구조 및 반환 내용을 확인합니다.
 * 3. 동일한 locale 재삭제를 시도해 오류 응답(존재하지 않음 또는 이미 삭제됨)을 확인합니다.
 * 4. 임의의 존재하지 않는 locale ID로 삭제 요청 시도, 오류가 발생하고 오류 정보를 검증합니다.
 */
export async function test_api_core_test_delete_locale_by_id_and_non_existent_case(
  connection: api.IConnection,
) {
  // 1. 삭제 가능한 locale을 생성
  const localeInput: ICoreLocale.ICreate = {
    code: `e2e-${RandomGenerator.alphaNumeric(6)}`,
    name: `E2E Test Locale ${RandomGenerator.alphabets(3)}`,
  };
  const created: ICoreLocale = await api.functional.core.locales.post(connection, {
    body: localeInput,
  });
  typia.assert(created);

  // 2. 생성된 locale을 ID로 삭제
  const deleteResult: ICoreLocale.IDeleteResult = await api.functional.core.locales.eraseById(connection, {
    id: created.id,
  });
  typia.assert(deleteResult);
  TestValidator.equals("삭제 성공 여부")(true)(deleteResult.success);
  TestValidator.equals("삭제된 locale_id 일치 여부")(created.id)(deleteResult.locale_id);
  TestValidator.predicate("deleted_at이 ISO 포맷인지")(!!Date.parse(deleteResult.deleted_at));

  // 3. 동일 locale 재삭제 시도(실패해야 함)
  await TestValidator.error("이미 삭제된 locale 삭제 시 실패해야 함")(() =>
    api.functional.core.locales.eraseById(connection, {
      id: created.id,
    }),
  );

  // 4. 존재하지 않는 임의 locale ID 삭제 시도(실패해야 함)
  await TestValidator.error("존재하지 않는 locale 삭제 시 실패해야 함")(() =>
    api.functional.core.locales.eraseById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
    }),
  );
}

