import { tags } from "typia";

/**
 * Consent Entity. Fulfills regulatory consent management and audit tracking for
 * user data access, AI/ML operations, and communications (see Prisma model
 * consents).
 *
 * Captures each explicit user consent by type, records all relevant timestamps,
 * and preserves an immutable audit paper trail.
 *
 * References: GDPR/CCPA compliance, user privacy dashboard requirements.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type ICoreConsent = {
  /**
   * Primary Key. Unique consent record (Prisma: consents.id). Links to a
   * specific consent instance for a user.
   *
   * The UUID ensures non-collision and referential integrity across
   * distributed systems and audit logs. Required for compliance tracking and
   * regulatory DSAR responses.
   */
  id: string & tags.Format<"uuid">;

  /**
   * User ID. Foreign key to users.id (Prisma: consents.user_id). Indicates
   * the user to whom this consent record applies.
   *
   * Required for evidencing consent provenance (GDPR/CCPA, etc.).
   */
  user_id: string & tags.Format<"uuid">;

  /**
   * Type of consent (e.g., 'ai_training', 'marketing', 'data_sharing').
   * Uniquely identifies the nature of each permission per user (Prisma:
   * consents.type).
   *
   * Business rules validate the uniqueness of (user_id, type) to ensure
   * traceability at a granular level for compliance exports.
   */
  type: string;

  /**
   * Is Granted. Indicates if consent has been given or revoked (Prisma:
   * consents.is_granted).
   *
   * A boolean for fast analysis by privacy dashboards or compliance modules.
   */
  is_granted: boolean;

  /**
   * Timestamp when consent was granted (Prisma: consents.granted_at).
   *
   * Crucial for regulatory evidence and time-bounded permission tracking.
   * Immutable after creation.
   */
  granted_at: string & tags.Format<"date-time">;

  /**
   * Timestamp when consent was revoked or made inactive (nullable; Prisma:
   * consents.revoked_at).
   *
   * Used for evidencing lifecycle of consent, compliance reporting, and
   * time-window analysis.
   */
  revoked_at?: (string & tags.Format<"date-time">) | null;
};
export namespace ICoreConsent {
  /**
   * Request object for paginated, filtered list/search of user consent
   * records in Core.consents.
   *
   * Used for DSAR, regulatory, analytics dashboards. Includes common
   * pagination, searching, and consent status filters.
   */
  export type IRequest = {
    /** General search (applies to type or user email, etc.). */
    search?: string | null;

    /**
     * Structured filter object. Possible fields: user_id, type, granted
     * state, etc.
     */
    filter?: {} | null;

    /** Sorting (e.g., by granted_at:desc). */
    sort?: string | null;

    /** Page number for paginated browsing. */
    page?: (number & tags.Type<"int32">) | null;

    /** Maximum records per page (regulatory default: 100). */
    limit?: (number & tags.Type<"int32">) | null;
  };

  /**
   * Consent Creation DTO. Used for creating a new user consent entry, as per
   * regulatory evidence requirements.
   *
   * All fields are needed to ensure reliable audit and privacy compliance.
   */
  export type ICreate = {
    /** Target user to whom the consent applies (Prisma: consents.user_id). */
    user_id: string & tags.Format<"uuid">;

    /**
     * Consent type/category, such as 'ai_training', 'marketing', or
     * 'analytics' (Prisma: consents.type).
     */
    type: string;

    /**
     * Indicates opt-in/out status. Defaults to true if granted, false if
     * declined (Prisma: consents.is_granted).
     */
    is_granted: boolean;

    /**
     * Timestamp when the consent was granted or created (Prisma:
     * consents.granted_at).
     */
    granted_at: string & tags.Format<"date-time">;

    /**
     * Optional: When consent is revoked (Prisma: consents.revoked_at).
     *
     * Should be null if not revoked at creation.
     */
    revoked_at?: (string & tags.Format<"date-time">) | null;
  };
}

