 * Steps:
 * 1. Create several user consent records with well-controlled values (multiple types, different user_ids, various granted states, distinct timestamps)
 * 2. Filter by type and verify only correct types are returned, pagination works, and sorting order is correct
 * 3. Filter by user_id and is_granted and validate results
 * 4. Perform a text search against type and check fuzzy matching
 * 5. Test sorting in both ascending and descending granted_at order
 * 6. Test pagination: request page/limit combos, confirm correct data count, and page content differences
 * 7. Test edge cases where filters yield no results
 * 8. Test request with invalid filter value (e.g., non-existent field): expect error or empty results, as per business logic
 *
 * Rationale:
 * The scenario assures the API’s flexibility and correctness in complex real-world filtering/paging situations, underpinning compliance displays and user DSAR controls.
 */
export async function test_api_core_test_search_and_paginate_consents_with_various_filters(connection: api.IConnection) {
  // Step 1: Data Setup - Create multiple controlled consent records
  const consentRecords: ICoreConsent[] = [];
  const userIds = ArrayUtil.repeat(3)(() => typia.random<string & tags.Format<"uuid">>());
