    // Expecting either empty data[] or API-side error
    TestValidator.equals("invalid filter field - empty data")(0)(invalid.data.length);
  } catch (err) {
    // Acceptable: API throws error for bad filter fields
    TestValidator.predicate("caught error for invalid filter field")(!!err);
  }
}

