import { IConnection, HttpError } from "@nestia/fetcher";
import { PlainFetcher } from "@nestia/fetcher/lib/PlainFetcher";
import typia, { tags } from "typia";
import { NestiaSimulator } from "@nestia/fetcher/lib/NestiaSimulator";

import { ICoreConsent } from "../../../structures/ICoreConsent";

/**
 * Get Core.consents (user consent) entry detail by ID.
 *
 * This API retrieves a single user consent entry from the 'consents' table in
 * the Core schema, identified by its unique identifier. It enables users,
 * admins, or compliance officers to audit/regulate data subject consent for
 * data use, AI/ML, marketing, or third-party sharing.
 *
 * The operation ensures that only the relevant user (data subject) or properly
 * privileged roles may access the consent record, in accordance with privacy
 * regulations (GDPR, CCPA, etc.). The response includes all atomic consent
 * attributes: type, grant status, timestamps for granted/revoked, and
 * identifying references.
 *
 * All accesses are evidence-logged. Errors cover not found, unauthorized
 * access, or system errors. The result may be redacted for non-authorized
 * accesses or in legal hold situations.
 *
 * @param props.connection
 * @param props.id Unique identifier (UUID) of the consent to fetch.
 * @path /core/consents/:id
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export async function getById(
  connection: IConnection,
  props: getById.Props,
): Promise<getById.Response> {
  return !!connection.simulate
    ? getById.simulate(connection, props)
    : PlainFetcher.fetch(
        {
          ...connection,
          headers: {
            ...connection.headers,
            "Content-Type": "application/json",
          },
        },
        {
          ...getById.METADATA,
          path: getById.path(props),
          status: null,
        },
      );
}
export namespace getById {
  export type Props = {
    /** Unique identifier (UUID) of the consent to fetch. */
    id: string & tags.Format<"uuid">;
  };
  export type Response = ICoreConsent;

  export const METADATA = {
    method: "GET",
    path: "/core/consents/:id",
    request: null,
    response: {
      type: "application/json",
      encrypted: false,
    },
  } as const;

  export const path = (props: Props) =>
    `/core/consents/${encodeURIComponent(props.id ?? "null")}`;
  export const random = (g?: Partial<typia.IRandomGenerator>): ICoreConsent =>
    typia.random<ICoreConsent>(g);
  export const simulate = (
    connection: IConnection,
    props: getById.Props,
  ): Response => {
    const assert = NestiaSimulator.assert({
      method: METADATA.method,
      host: connection.host,
      path: getById.path(props),
      contentType: "application/json",
    });
    try {
      assert.param("id")(() => typia.assert(props.id));
    } catch (exp) {
      if (!typia.is<HttpError>(exp)) throw exp;
      return {
        success: false,
        status: exp.status,
        headers: exp.headers,
        data: exp.toJSON().message,
      } as any;
    }
    return random(
      "object" === typeof connection.simulate && null !== connection.simulate
        ? connection.simulate
        : undefined,
    );
  };
}

/**
 * Create/register a new Core.consents (user regulatory consent) entry.
 *
 * This API operation creates a new user consent entry in the 'consents' table
 * as defined in the Core schema. It is called when a user (or system on behalf
 * of a user) grants or revokes a specific type of consent (AI/ML, marketing,
 * data use, etc.).
 *
 * The operation requires strict validation to ensure (user, type) uniqueness
 * and conformance to regulatory formats. All attributes, including grant status
 * and timestamps, are required. Consent changes are recorded in evidence and
 * audit logs, supporting regulatory DSAR and privacy compliance workflows.
 *
 * Errors include duplicate entry, conflicts, invalid types, and insufficient
 * permissions. Only authorized users may create/modify their consents. The
 * created entry is fully detailed in the response for client confirmation and
 * compliance audit.
 *
 * @param props.connection
 * @param props.body Details for the new consent entry (user, type, grant
 *   status, timestamps).
 * @path /core/consents
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export async function post(
  connection: IConnection,
  props: post.Props,
): Promise<post.Response> {
  return !!connection.simulate
    ? post.simulate(connection, props)
    : PlainFetcher.fetch(
