import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ICoreConsent } from "@ORGANIZATION/PROJECT-api/lib/structures/ICoreConsent";

/**
 * 테스트 목적: 특정 동의(consent)를 ID로 조회할 때, 정상적으로 상세 정보를 반환하는지(유효 ID),
 * 그리고 잘못된 ID 입력시 적절한 not found 오류를 반환하는지 모두 검증한다.
 *
 * [비즈니스 컨텍스트 및 필요성]
 * - 개인정보/AI/마케팅 등 각종 사용자 동의에 대해 개별 record를 제공하며, 내부 감사 또는 규제 대응에서 특정 동의이력 상세 조회가 필수다.
 * - 올바른 상세정보 반환 보장과 동시에, 존재하지 않는 ID에 대한 예외처리(404 등)도 중요하다.
 *
 * [테스트 절차]
 * 1. 테스트용 consent 레코드를 사전 생성한다 (core.consents.post 활용)
 * 2. 해당 consent의 id로 상세 조회하여, 입력 정보와 반환값이 일치하는지 검증한다
 * 3. 임의의 잘못된 uuid로 조회시 not found 오류(404 등)가 발생하는지 확인한다
 */
export async function test_api_core_test_get_consent_by_id_success_and_not_found(
  connection: api.IConnection,
) {
  // 1. 테스트용 consent entity 생성
  const consentInput: ICoreConsent.ICreate = {
    user_id: typia.random<string & tags.Format<"uuid">>(),
    type: "ai_training",
    is_granted: true,
    granted_at: new Date().toISOString(),
    revoked_at: null,
  };
  const created: ICoreConsent = await api.functional.core.consents.post(connection, {
    body: consentInput,
  });
  typia.assert(created);

  // 2. 정상 ID로 consent 상세 조회
  const readById = await api.functional.core.consents.getById(connection, {
    id: created.id,
  });
  typia.assert(readById);
  TestValidator.equals("id must match")(created.id)(readById.id);
  TestValidator.equals("user_id matches")(created.user_id)(readById.user_id);
  TestValidator.equals("type matches")(created.type)(readById.type);
  TestValidator.equals("is_granted matches")(created.is_granted)(readById.is_granted);
  TestValidator.equals("granted_at matches")(created.granted_at)(readById.granted_at);
  TestValidator.equals("revoked_at matches")(
    created.revoked_at === undefined ? null : created.revoked_at,
  )(readById.revoked_at === undefined ? null : readById.revoked_at);

  // 3. 존재하지 않는 ID (random uuid)로 조회시 not found (404) 반환 확인
  await TestValidator.error("조회 불가 id는 404 반환")(async () => {
    await api.functional.core.consents.getById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
    });
  });
}

