 * - 개인정보/AI/마케팅 규제 동의 상세 열람(Audit) 및 감사 기록 목적
 * - 유효한 동의 id에 대해 상세 정보 정확히 반환되는지, 잘못된 id는 not found(404)가 반환되는지 확인
 *
 * [프로세스]
 * 1. 테스트를 위한 consent 엔트리 신규 생성
 * 2. 해당 consent의 id로 단건 상세 조회 후, 생성값과 응답 일치 검증
 * 3. 존재하지 않는 임의의 uuid로 조회 시 not found(404) 오류 발생 검증
 */
export async function test_api_core_test_get_consent_by_id_success_and_not_found(
  connection: api.IConnection,
) {
  // 1. 테스트용 consent 신규 생성
  const consentInput = {
    user_id: typia.random<string & tags.Format<"uuid">>(),
    type: "ai_training",
    is_granted: true,
    granted_at: new Date().toISOString(),
    revoked_at: null,
  } satisfies ICoreConsent.ICreate;
  const created: ICoreConsent = await api.functional.core.consents.post(connection, {
    body: consentInput,
  });
  typia.assert(created);

  // 2. 정상 ID로 consent 상세 조회 및 데이터 일치 검증
  const readById: ICoreConsent = await api.functional.core.consents.getById(connection, {
    id: created.id,
  });
  typia.assert(readById);
  TestValidator.equals("id must match")(created.id)(readById.id);
  TestValidator.equals("user_id matches")(created.user_id)(readById.user_id);
  TestValidator.equals("type matches")(created.type)(readById.type);
  TestValidator.equals("is_granted matches")(created.is_granted)(readById.is_granted);
  TestValidator.equals("granted_at matches")(created.granted_at)(readById.granted_at);
  TestValidator.equals("revoked_at matches")(
    created.revoked_at === undefined ? null : created.revoked_at,
  )(readById.revoked_at === undefined ? null : readById.revoked_at);

  // 3. 잘못된 ID (존재하지 않는 uuid)로 조회 시 not found(404) 예외 검증
  await TestValidator.error("조회 불가 id는 404 반환")(async () => {
    await api.functional.core.consents.getById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
    });
  });
}

