import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ICoreConsent } from "@ORGANIZATION/PROJECT-api/lib/structures/ICoreConsent";

/**
 * Test creation of new regulatory user consent records.
 *
 * This test validates acceptance of a well-formed consent payload, enforces unique constraints for (user_id, type), and detects missing/invalid input errors. It covers business and compliance requirements for audit tracking, and ensures the API defends against both user error and attempts to create duplicates.
 *
 * Steps:
 * 1. Create a new consent for a random user and type with valid data (should succeed)
 * 2. Attempt to create another consent using the same (user_id, type) — expect a uniqueness violation or duplicate error
 * 3. Attempt creation with missing required fields (e.g., omit user_id, type, is_granted, or granted_at) and expect validation errors
 * 4. Attempt creation with invalid data types (e.g., wrong uuid format, string for boolean, invalid date-time format) and expect validation errors
 * 5. Confirm correct response structure for all success/error cases
 */
export async function test_api_core_test_create_user_consent_success_and_validation_errors(
  connection: api.IConnection,
) {
  // 1. Create a new consent with valid data
  const userId: string & tags.Format<"uuid"> = typia.random<string & tags.Format<"uuid">>();
  const consentType = RandomGenerator.pick(["ai_training", "marketing", "analytics"]);
  const grantedAt: string & tags.Format<"date-time"> = new Date().toISOString() as string & tags.Format<"date-time">;

  const validPayload: ICoreConsent.ICreate = {
    user_id: userId,
    type: consentType,
    is_granted: true,
    granted_at: grantedAt,
    revoked_at: null,
  };
  const created = await api.functional.core.consents.post(connection, { body: validPayload });
  typia.assert(created);
  TestValidator.equals("consent type")(consentType)(created.type);
  TestValidator.equals("granted user")(userId)(created.user_id);
  TestValidator.equals("is granted")(true)(created.is_granted);
  TestValidator.equals("granted_at")(grantedAt)(created.granted_at);
  TestValidator.equals("revoked_at")(null)(created.revoked_at);

  // 2. Try to create a duplicate consent for the same user and type (should fail or return duplicate error)
  await TestValidator.error("duplicate consent should fail")(
    () => api.functional.core.consents.post(connection, { body: validPayload })
  );

  // 3. Attempt to create consent with missing required fields
  // (omit user_id)
  await TestValidator.error("missing user_id")(
    () => api.functional.core.consents.post(connection, {
      body: {
        // user_id omitted intentionally (TypeScript disallows it, so skip actual code for broken types)
        type: "marketing",
        is_granted: true,
        granted_at: grantedAt,
      } as any,
    })
  );
  // (omit type)
  await TestValidator.error("missing type")(
    () => api.functional.core.consents.post(connection, {
      body: {
        user_id: userId,
        // type omitted intentionally
        is_granted: true,
        granted_at: grantedAt,
      } as any,
    })
  );
  // (omit is_granted)
  await TestValidator.error("missing is_granted")(
    () => api.functional.core.consents.post(connection, {
      body: {
        user_id: userId,
        type: "ai_training",
        granted_at: grantedAt,
      } as any,
    })
  );
  // (omit granted_at)
  await TestValidator.error("missing granted_at")(
    () => api.functional.core.consents.post(connection, {
      body: {
        user_id: userId,
        type: "ai_training",
        is_granted: true,
      } as any,
    })
  );

  // 4. Attempt to create consent with invalid data types
  // Invalid user_id (not uuid)
  await TestValidator.error("invalid user_id format")(
    () => api.functional.core.consents.post(connection, {
      body: {
        user_id: "not-a-uuid",
        type: "ai_training",
        is_granted: true,
        granted_at: grantedAt,
      } as any,
    })
  );
  // Invalid is_granted (should be boolean)
  await TestValidator.error("is_granted as string should fail")(
    () => api.functional.core.consents.post(connection, {
      body: {
        user_id: userId,
        type: "ai_training",
        is_granted: "yes",
        granted_at: grantedAt,
      } as any,
    })
  );
  // Invalid granted_at (not date-time)
  await TestValidator.error("invalid granted_at format")(
    () => api.functional.core.consents.post(connection, {
      body: {
        user_id: userId,
        type: "ai_training",
        is_granted: true,
        granted_at: "yesterday",
      } as any,
    })
  );
}

