import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ICoreConsent } from "@ORGANIZATION/PROJECT-api/lib/structures/ICoreConsent";

/**
 * E2E test for updating a consent entry by ID.
 *
 * This test validates the complete lifecycle and constraints around updating a user consent record via the Core.consents API:
 *
 * 1. Create a valid consent record (dependency: POST /core/consents).
 * 2. Perform a successful update using valid data and verify that the updates are saved.
 * 3. Attempt to update the resource using incomplete/invalid data (such as blank type, or revoked_at in the past if logic mandates) and verify the API returns validation errors.
 * 4. Attempt to update a non-existent consent (random uuid) and verify the API returns a 'not found' error.
 *
 * Steps:
 * 1. Create a consent record for a specific user and type (using valid fields: user_id, type, is_granted, granted_at, [revoked_at=null]).
 * 2. Send PUT /core/consents/{id} with updated fields: change is_granted, maybe update type or set revoked_at.
 *    - Assert that the returned record reflects the changes.
 * 3. Try to update the same consent with incomplete/invalid data:
 *    - Example: missing all fields (empty body)
 *    - Example: invalid type (empty string if not allowed)
 *    - Example: invalid timestamps (revoked_at before granted_at)
 *    - Assert that the API returns correct validation errors for each.
 * 4. Try to update a consent with a random non-existent UUID as id. Assert 'not found' or equivalent error is returned.
 *
 * Success Criteria:
 * - The record is updated as expected when data is valid.
 * - Validation errors are returned for incomplete or invalid data according to DTO constraints/business logic.
 * - 'Not found' error for non-existent consent ID.
 */
export async function test_api_core_test_update_consent_by_id_with_success_invalid_and_not_found_cases(connection: api.IConnection) {
  // 1. Create dependency: a valid consent record.
  const user_id: string = typia.random<string & tags.Format<"uuid">>();
  const created = await api.functional.core.consents.post(connection, {
    body: {
      user_id,
      type: "ai_training",
      is_granted: true,
      granted_at: new Date().toISOString(),
      revoked_at: null,
    } satisfies ICoreConsent.ICreate,
  });
  typia.assert(created);

  // 2. Successful update: change is_granted and type.
  const updatedType = "marketing";
  const updatePayload = {
    is_granted: false,
    type: updatedType,
    revoked_at: new Date().toISOString(),
  } satisfies ICoreConsent.IUpdate;
  const updated = await api.functional.core.consents.putById(connection, {
    id: created.id,
    body: updatePayload,
  });
  typia.assert(updated);
  TestValidator.equals("updated type")(updated.type)(updatedType);
  TestValidator.equals("updated grant")(updated.is_granted)(false);
  TestValidator.equals("updated revoked_at")(typeof updated.revoked_at)("string");

  // 3-1. Invalid update: empty object (no fields).
  await TestValidator.error("empty update should fail validation")(() =>
    api.functional.core.consents.putById(connection, {
      id: created.id,
      body: {},
    }),
  );

  // 3-2. Invalid update: invalid type (empty string if type must be non-empty)
  await TestValidator.error("invalid type should fail validation")(() =>
    api.functional.core.consents.putById(connection, {
      id: created.id,
      body: { type: "" },
    }),
  );

  // 3-3. Invalid update: revoked_at before granted_at
  const revokedEarlier = new Date(Date.now() - 10000000).toISOString();
  await TestValidator.error("revoked_at before granted_at should fail")(() =>
    api.functional.core.consents.putById(connection, {
      id: created.id,
      body: { revoked_at: revokedEarlier },
    }),
  );

  // 4. Non-existent id update
  const randomId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("updating non-existent consent should 404")(() =>
    api.functional.core.consents.putById(connection, {
      id: randomId,
      body: { is_granted: true },
    }),
  );
}

