import { tags } from "typia";

/**
 * Access Log Entity. Immutable, evidence-grade record of authentication or
 * access events as per access_logs table (Prisma schema).
 *
 * Supports regulatory, security, forensics, and DSAR activities.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type ICoreAccessLog = {
  /** Primary Key. Unique access log record (Prisma: access_logs.id). */
  id: string & tags.Format<"uuid">;

  /**
   * Foreign key to users.id for this access event (Prisma:
   * access_logs.user_id).
   */
  user_id: string & tags.Format<"uuid">;

  /**
   * Foreign key to the session in which the event occurred (Prisma:
   * access_logs.session_id). Nullable for system/service access.
   */
  session_id?: (string & tags.Format<"uuid">) | null;

  /**
   * Type of access event: e.g., 'login', 'logout', 'api_call' (Prisma:
   * access_logs.event_type).
   */
  event_type: string;

  /** Source IP address (Prisma: access_logs.ip). */
  ip: string;

  /** User agent or device string (Prisma: access_logs.agent). */
  agent: string;

  /**
   * Outcome of the action: true for successful, false for failure (Prisma:
   * access_logs.success).
   */
  success: boolean;

  /**
   * Timestamp of when the access event occurred (Prisma:
   * access_logs.occurred_at).
   *
   * Immutable after log entry creation; used for audit trace chains.
   */
  occurred_at: string & tags.Format<"date-time">;
};
export namespace ICoreAccessLog {
  /**
   * Access Log Query/Search DTO. Enables advanced, filterable retrieval of
   * access log records for user, security, and regulatory evidencing.
   *
   * Directly references normalized access_logs table fields (Prisma schema).
   */
  export type IRequest = {
    /**
     * Optional: Filter logs to target user_id (Prisma:
     * access_logs.user_id).
     *
     * Used in user self-audits or admin security reports.
     */
    user_id?: string & tags.Format<"uuid">;

    /**
     * Optional: Filter for a specific session context (Prisma:
     * access_logs.session_id).
     */
    session_id?: string & tags.Format<"uuid">;

    /**
     * Optional: Filter events by type (e.g. 'login', 'api_call'; Prisma:
     * access_logs.event_type).
     *
     * Critical for event-frequency analytics and regulatory queries.
     */
    event_type?: string;

    /**
     * Optional: Filter by originating IP address (Prisma: access_logs.ip).
     *
     * Allows for investigation of suspicious or targeted activities.
     */
    ip?: string;

    /**
     * Optional: Filter by user agent string (Prisma: access_logs.agent).
     *
     * Useful in device/user analytics and forensics.
     */
    agent?: string;

    /**
     * Optional: Filter by authentication or action result success/failure
     * (Prisma: access_logs.success).
     */
    success?: boolean;

    /**
     * Optional: Lower bound filter on occurred_at (Prisma:
     * access_logs.occurred_at).
     *
     * Supports range queries for compliance export and anomaly detection.
     */
    occurred_at_from?: string & tags.Format<"date-time">;

    /**
     * Optional: Upper bound filter on occurred_at.
     *
     * Critical for point-in-time analysis, breach tracing, and incident
     * investigation.
     */
    occurred_at_to?: string & tags.Format<"date-time">;

    /** Page number for paginated retrieval. Default 1. */
    page?: number &
      tags.Type<"int32"> &
      tags.Minimum<1> &
      tags.JsonSchemaPlugin<{
        format: "int32";
      }>;

    /** Max results per page, for rate limiting/large exports. */
    limit?: number &
      tags.Type<"int32"> &
      tags.Default<100> &
      tags.Minimum<1> &
      tags.Maximum<1000> &
      tags.JsonSchemaPlugin<{
        format: "int32";
      }>;
  };

  /**
   * Access Log Creation DTO. Used for recording system or user access events
   * for regulatory, analytics, and forensics audit.
   */
  export type ICreate = {
    /** FK to user performing/accessed (Prisma: access_logs.user_id). */
    user_id: string & tags.Format<"uuid">;

    /** FK to session context. Nullable if not session-driven. */
    session_id?: (string & tags.Format<"uuid">) | null;

    /**
     * Type of access event, e.g., 'login', 'api_call', etc. (Prisma:
     * access_logs.event_type).
     */
    event_type: string;

    /** Origin IP address of access (Prisma: access_logs.ip). */
    ip: string;

    /** User agent/device info (Prisma: access_logs.agent). */
    agent: string;

    /** Whether the access was successful (Prisma: access_logs.success). */
    success: boolean;

    /** Timestamp when event occurred (Prisma: access_logs.occurred_at). */
    occurred_at: string & tags.Format<"date-time">;
  };
