import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ICoreAccessLog } from "@ORGANIZATION/PROJECT-api/lib/structures/ICoreAccessLog";
import type { IPageICoreAccessLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageICoreAccessLog";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate listing of access logs with advanced filters, pagination, and sorting options.
 *
 * Business context:
 *   - Access logs are critical for security, regulatory, and audit evidencing, and must support highly flexible queries.
 *   - Filtering scenarios include by user_id, session_id, event_type, ip, agent, success (true/false), and time range (occurred_at_from/to).
 *   - Edge cases: empty result set (filters matching no records), page out of bounds, and malformed/invalid filter queries, as well as permission/authorization limits.
 *
 * Test Workflow:
 *   1. Insert multiple known access log records (with distinct user_id, session_id, event_type, etc.) to enable precise filter targeting.
 *   2. Query all access logs with no filter to confirm successful bulk fetch (should include all inserted records).
 *   3. Filter by user_id, session_id, event_type, ip, agent, success individually—validate only correct records are returned each time.
 *   4. Use time range (occurred_at_from, occurred_at_to) to include/exclude records—validate correct records based on timestamp.
 *   5. Apply pagination: fetch pages and confirm correct paging logic (limit/count, page boundaries, empty pages).
 *   6. Attempt out-of-bounds page and ensure result set is empty but with correct pagination meta.
 *   7. Test a filter that can never match (e.g., fake ip/user_id) and confirm data is [] and paging meta is correct.
 *   8. [Error] Pass malformed filter (e.g., non-UUID in user_id) and confirm API error (TestValidator.error).
 *   9. [AuthZ] (If applicable) Call as unauthorized user (or missing/invalid auth) and check permission error (TestValidator.error).
 */
export async function test_api_core_test_list_access_logs_with_filter_and_pagination_options(
  connection: api.IConnection,
) {
  // 1. Insert multiple known access log records
  const userA = typia.random<string & tags.Format<"uuid">>();
  const userB = typia.random<string & tags.Format<"uuid">>();
  const sessionA = typia.random<string & tags.Format<"uuid">>();
  const now = new Date();
  const logs = await Promise.all([
    api.functional.core.accessLogs.post(connection, {
      body: {
        user_id: userA,
        session_id: sessionA,
        event_type: "login",
        ip: "192.0.2.1",
        agent: "Chrome/Asia",
        success: true,
        occurred_at: new Date(now.getTime() - 60000).toISOString() as string & tags.Format<"date-time">,
      } satisfies ICoreAccessLog.ICreate
    }),
    api.functional.core.accessLogs.post(connection, {
      body: {
        user_id: userB,
        session_id: null,
        event_type: "api_call",
        ip: "198.51.100.5",
        agent: "Safari/Europe",
        success: false,
        occurred_at: new Date(now.getTime() - 120000).toISOString() as string & tags.Format<"date-time">,
      }
    }),
    api.functional.core.accessLogs.post(connection, {
      body: {
        user_id: userA,
        session_id: sessionA,
        event_type: "logout",
        ip: "203.0.113.8",
        agent: "Firefox/Korea",
        success: true,
        occurred_at: now.toISOString() as string & tags.Format<"date-time">,
      }
    })
  ]);

  logs.forEach(typia.assert);

  // 2. Query all access logs with no filter
  let page = await api.functional.core.accessLogs.patch(connection, {
    body: {} satisfies ICoreAccessLog.IRequest,
  });
  typia.assert(page);
  TestValidator.predicate("all inserted logs present")(
    logs.every(r => page.data.some(d => d.id === r.id))
  );

  // 3. Filter by user_id
  page = await api.functional.core.accessLogs.patch(connection, {
    body: { user_id: userA } satisfies ICoreAccessLog.IRequest
  });
  typia.assert(page);
  TestValidator.predicate("only userA logs")(
    page.data.every(d => d.user_id === userA)
  );

  // Filter by event_type
  page = await api.functional.core.accessLogs.patch(connection, {
    body: { event_type: "api_call" } satisfies ICoreAccessLog.IRequest
  });
  typia.assert(page);
  TestValidator.equals("single api_call log")(1)(page.data.length);
  TestValidator.equals("correct user_id")(userB)(page.data[0]?.user_id);

  // Filter by ip
  page = await api.functional.core.accessLogs.patch(connection, {
    body: { ip: "203.0.113.8" } satisfies ICoreAccessLog.IRequest
  });
  typia.assert(page);
  TestValidator.equals("single log for ip")(1)(page.data.length);
  TestValidator.equals("correct ip")("203.0.113.8")(page.data[0]?.ip);

  // 4. Filter by time range
  page = await api.functional.core.accessLogs.patch(connection, {
    body: { occurred_at_from: new Date(now.getTime() - 90000).toISOString() as string & tags.Format<"date-time"> } satisfies ICoreAccessLog.IRequest,
  });
  typia.assert(page);
  TestValidator.predicate("only recent logs")(
    page.data.every(d => Date.parse(d.occurred_at) >= now.getTime() - 90000)
  );

  // 5. Pagination (limit)
  page = await api.functional.core.accessLogs.patch(connection, {
    body: { limit: 2 } satisfies ICoreAccessLog.IRequest
  });
