  // 7. Unmatched filter (fake ip)
  page = await api.functional.core.accessLogs.patch(connection, {
    body: { ip: "255.255.255.255" } satisfies ICoreAccessLog.IRequest
  });
  typia.assert(page);
  TestValidator.equals("empty for unmatched ip")(0)(page.data.length);

  // 8. Malformed UUID (should error)
  await TestValidator.error("malformed user_id fails")(() =>
    api.functional.core.accessLogs.patch(connection, {
      body: { user_id: "not-a-uuid" as any },
    })
  );

