/**
 * Validate fetching a specific access log entry by its ID, including normal and edge cases.
 *
 * This test covers both successful fetch by a valid ID and error handling for non-existent, improperly typed, or deleted IDs.
 * Access logs are immutable and evidence-grade, so only valid, existing IDs should yield a log record.
 *
 * 1. Create an access log entry using api.functional.core.accessLogs.post.
 * 2. Fetch the created log by its ID with api.functional.core.accessLogs.getById and assert all fields match.
 * 3. Attempt to fetch a log with a completely random (but valid format) UUID that was never created; assert a not found error is raised.
 * 4. Attempt to fetch a log with a deleted (if supported) or similarly invalid ID and assert correct error.
 * 5. Attempt to fetch with an invalidly formatted ID (not a UUID) and assert format validation error or bad request is triggered if system supports this edge case.
 *
 * Validates proper functioning of ID-based access log fetching and correct error handling for typical edge cases.
 */
export async function test_api_core_test_get_access_log_by_id_normal_and_edge_cases(
  connection: api.IConnection,
) {
  // 1. Create access log entry
  const createInput: ICoreAccessLog.ICreate = {
    user_id: typia.random<string & tags.Format<"uuid">>(),
    event_type: "api_call",
    ip: "192.168.1.1",
    agent: "test-agent",
    success: true,
    occurred_at: new Date().toISOString(),
  };
  const logEntry: ICoreAccessLog = await api.functional.core.accessLogs.post(connection, { body: createInput });
  typia.assert(logEntry);
  // 2. Fetch by valid ID
  const fetched: ICoreAccessLog = await api.functional.core.accessLogs.getById(connection, { id: logEntry.id });
  typia.assert(fetched);
  TestValidator.equals("id should match")(logEntry.id)(fetched.id);

  // 3. Fetch non-existent UUID
  await TestValidator.error("should throw on non-existent id")(() =>
    api.functional.core.accessLogs.getById(connection, { id: typia.random<string & tags.Format<"uuid">>() }),
  );

  // 4. Fetch by invalid format (simulate non-uuid)
  await TestValidator.error("should throw on invalid id format")(() =>
    api.functional.core.accessLogs.getById(connection, { id: "not-a-uuid" as any }),
  );
}

