 * 3. Attempt to fetch a log with a random (but valid UUID format) that does not exist, expect not found error.
 * 4. Attempt to fetch a log with an invalid ID format, expect a validation/bad request error.
 *
 * Note: Deletion of logs is not supported (access logs are immutable evidence records), so delete scenario is skipped.
 */
export async function test_api_core_test_get_access_log_by_id_normal_and_edge_cases(
  connection: api.IConnection,
) {
  // 1. Create access log entry for testing
  const createInput: ICoreAccessLog.ICreate = {
    user_id: typia.random<string & tags.Format<"uuid">>(),
    event_type: "api_call",
    ip: "192.168.1.1",
    agent: "test-agent",
    success: true,
    occurred_at: new Date().toISOString(),
  };
  const created: ICoreAccessLog = await api.functional.core.accessLogs.post(connection, {
    body: createInput,
  });
  typia.assert(created);

  // 2. Fetch the created log entry by ID and assert correctness
  const fetched: ICoreAccessLog = await api.functional.core.accessLogs.getById(connection, {
