  TestValidator.equals("Event type matches")(createInput.event_type)(fetched.event_type);
  TestValidator.equals("IP matches")(createInput.ip)(fetched.ip);
  TestValidator.equals("Agent matches")(createInput.agent)(fetched.agent);
  TestValidator.equals("Success flag matches")(createInput.success)(fetched.success);
  TestValidator.equals("Occurred at matches")(createInput.occurred_at)(fetched.occurred_at);

  // 3. Try to fetch a non-existent access log (random valid UUID)
