import api from "@ORGANIZATION/PROJECT-api";
import type { ICoreAccessLog } from "@ORGANIZATION/PROJECT-api/lib/structures/ICoreAccessLog";

/**
 * Test creation of a new access log record.
 *
 * 1. Attempt to create a valid access log and verify success.
 * 2. Attempt to create an access log with missing required fields and validate error response.
 * 3. If business logic prevents duplicate entries (e.g., evidence hash), verify that submitting a duplicate is rejected with an appropriate error and does not create multiple identical records.
 *
 * Steps:
 * - Prepare minimal valid ICoreAccessLog.ICreate input, submit, and check normal creation and output shape (type-assert).
 * - Attempt with one or more required fields missing each time and check API responds with input validation error.
 * - If applicable, create duplicate access log and verify prevention or error (if evidence duplication makes sense in business context).
 */
export async function test_api_core_test_create_access_log_and_validate_errors(
  connection: api.IConnection,
) {
  // 1. Create a valid access log entry
  const validInput: ICoreAccessLog.ICreate = {
    user_id: typia.random<string & tags.Format<"uuid">>(),
    session_id: typia.random<string & tags.Format<"uuid">>(),
    event_type: "login",
    ip: "192.168.1.10",
    agent: "Mozilla/5.0 test-agent",
    success: true,
    occurred_at: new Date().toISOString() as string & tags.Format<"date-time">,
  };
  const created = await api.functional.core.accessLogs.post(connection, { body: validInput });
  typia.assert(created);
  // Validate fields and check id assigned
  TestValidator.predicate("id assigned")(!!created.id);
  TestValidator.equals("event_type")(validInput.event_type)(created.event_type);

  // 2. Attempt to create with missing required fields, expecting validation errors
  const requiredFields: (keyof ICoreAccessLog.ICreate)[] = [
    "user_id",
    "event_type",
    "ip",
    "agent",
    "success",
    "occurred_at",
  ];
  for (const field of requiredFields) {
    const invalidInput = { ...validInput };
    delete (invalidInput as any)[field];
    await TestValidator.error(`Missing ${field} fails validation`)(async () => {
      await api.functional.core.accessLogs.post(connection, { body: invalidInput });
    });
  }

  // 3. (If relevant) Duplicate input prevention test
  // Try to create the EXACT same access log again
  // If the endpoint enforces deduplication, this should fail. If not, may allow it.
  // We'll expect duplicate prevention (if so, error; if not, should create a second record with a different id)
  const duplicate = await api.functional.core.accessLogs.post(connection, { body: validInput });
  typia.assert(duplicate);
  if (duplicate.id === created.id) {
    throw new Error("Duplicate access log accepted but returned identical id - must create unique records or reject duplicates.");
  }
}

