import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ICoreAccessLog } from "@ORGANIZATION/PROJECT-api/lib/structures/ICoreAccessLog";

/**
 * 접근 로그 항목 메타데이터 수정/불변 필드 검증 및 잘못된 업데이트 케이스 처리 테스트
 *
 * - 정상 수정: 기존 access log의 event_type, ip, agent, success(선택적 입력) 등
 *   mutable 필드만을 PUT으로 수정 시, 해당 값은 변경되며 id, user_id, session_id, occurred_at 등
 *   immutable 필드는 절대 변경되지 않아야 함을 검증합니다.
 * - 불완전 데이터/비어있는 업데이트 요청은 400 등 오류 반환을 검증합니다.
 * - 존재하지 않는 id로의 접근은 404 오류 등이 반환됨을 검증합니다.
 *
 * 실제 감사·컴플라이언스 목적 로그의 변조 프로세스, 필드 레벨 허용 정책 변경 검증 및 기본적인 입력 값 오류, 비정상 id 등 횡단 케이스까지 일괄 검증합니다.
 *
 * Steps:
 * 1. 접근 로그 생성 (accessLogs.post) 및 id 확보
 * 2. 일부 mutable 필드만 수정해서 putById: 변경 필드 반영 및 불변 필드 불변 검증
 * 3. 빈 데이터로 업데이트 요청 시 즉시 오류 검증
 * 4. 존재하지 않는 id로 put 시도 → not found 등 오류 검증
 */
export async function test_api_coreAccessLogs_test_update_access_log_entry_and_invalid_cases(
  connection: api.IConnection,
) {
  // 1. 접근 로그 생성
  const createInput: ICoreAccessLog.ICreate = {
    user_id: typia.random<string & tags.Format<"uuid">>(),
    session_id: typia.random<boolean>() ? typia.random<string & tags.Format<"uuid">>() : null,
    event_type: "login",
    ip: "192.168.1.1",
    agent: "Mozilla/5.0 E2E-UnitTest",
    success: true,
    occurred_at: new Date().toISOString() as string & tags.Format<"date-time">,
  };
  const created: ICoreAccessLog = await api.functional.core.accessLogs.post(
    connection,
    { body: createInput },
  );
  typia.assert(created);

  // 2. mutable 필드만 업데이트
  const updateInput: ICoreAccessLog.IUpdate = {
    event_type: "logout",
    ip: "10.20.30.40",
    agent: "HTTPie/3.2.0-E2E"
  };
  const updated = await api.functional.core.accessLogs.putById(
    connection,
    { id: created.id, body: updateInput },
  );
  typia.assert(updated);
  TestValidator.equals("event_type 변경")(updateInput.event_type)(updated.event_type);
  TestValidator.equals("ip 변경")(updateInput.ip)(updated.ip);
  TestValidator.equals("agent 변경")(updateInput.agent)(updated.agent);
  TestValidator.equals("id 불변")(created.id)(updated.id);
  TestValidator.equals("user_id 불변")(created.user_id)(updated.user_id);
  TestValidator.equals("session_id 불변")(created.session_id)(updated.session_id);
  TestValidator.equals("occurred_at 불변")(created.occurred_at)(updated.occurred_at);

  // 3. 불완전/빈 업데이트 요청 -> 오류 확인
  await TestValidator.error("빈 업데이트 데이터는 오류여야 함")(async () => {
    await api.functional.core.accessLogs.putById(connection, {
      id: created.id,
      body: {},
    });
  });

  // 4. 존재하지 않는 id로 업데이트 시도 → 404 등 오류 반환
  await TestValidator.error("존재하지 않는 id는 not found 오류여야 함")(async () => {
    await api.functional.core.accessLogs.putById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
      body: { ip: "203.0.113.10" },
    });
  });
}

