import { tags } from "typia";

/**
 * Access Log Entity. Immutable, evidence-grade record of authentication or
 * access events as per access_logs table (Prisma schema).
 *
 * Supports regulatory, security, forensics, and DSAR activities.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type ICoreAccessLog = {
  /** Primary Key. Unique access log record (Prisma: access_logs.id). */
  id: string & tags.Format<"uuid">;

  /**
   * Foreign key to users.id for this access event (Prisma:
   * access_logs.user_id).
   */
  user_id: string & tags.Format<"uuid">;

  /**
   * Foreign key to the session in which the event occurred (Prisma:
   * access_logs.session_id). Nullable for system/service access.
   */
  session_id?: (string & tags.Format<"uuid">) | null;

  /**
   * Type of access event: e.g., 'login', 'logout', 'api_call' (Prisma:
   * access_logs.event_type).
   */
  event_type: string;

  /** Source IP address (Prisma: access_logs.ip). */
  ip: string;

  /** User agent or device string (Prisma: access_logs.agent). */
  agent: string;

  /**
   * Outcome of the action: true for successful, false for failure (Prisma:
   * access_logs.success).
   */
  success: boolean;

  /**
   * Timestamp of when the access event occurred (Prisma:
   * access_logs.occurred_at).
   *
   * Immutable after log entry creation; used for audit trace chains.
   */
  occurred_at: string & tags.Format<"date-time">;
};
export namespace ICoreAccessLog {
  /**
   * Access Log Creation DTO. Used for recording system or user access events
   * for regulatory, analytics, and forensics audit.
   */
  export type ICreate = {
    /** FK to user performing/accessed (Prisma: access_logs.user_id). */
    user_id: string & tags.Format<"uuid">;

    /** FK to session context. Nullable if not session-driven. */
    session_id?: (string & tags.Format<"uuid">) | null;

    /**
     * Type of access event, e.g., 'login', 'api_call', etc. (Prisma:
     * access_logs.event_type).
     */
    event_type: string;

    /** Origin IP address of access (Prisma: access_logs.ip). */
    ip: string;

    /** User agent/device info (Prisma: access_logs.agent). */
    agent: string;

    /** Whether the access was successful (Prisma: access_logs.success). */
    success: boolean;

    /** Timestamp when event occurred (Prisma: access_logs.occurred_at). */
    occurred_at: string & tags.Format<"date-time">;
  };

  /**
   * Access Log Delete Result DTO. Used for audit/compliance confirmation of
   * logical removal.
   */
  export type IDeleteResult = {
    /**
     * ID of the access log entry marked as deleted (Prisma:
     * access_logs.id).
     */
    id: string & tags.Format<"uuid">;

    /**
     * Indicates if the record was successfully deleted
     * (soft-deleted/archived per compliance).
     */
    deleted: boolean;
  };
}

