import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ICoreAccessLog } from "@ORGANIZATION/PROJECT-api/lib/structures/ICoreAccessLog";

/**
 * Validate the deletion of an access log entry and evidence preservation.
 *
 * This test covers the compliance requirement that access log records, even after deletion, should preserve audit trail evidence (i.e., use logical/soft deletion rather than physical removal). It also checks error handling for deletion of non-existent records and verifies that deleted entries are not retrievable as active access logs.
 *
 * Workflow:
 * 1. Create a new access log entry as a dependency/precondition for deletion.
 * 2. Delete the created access log entry by its unique ID.
 * 3. Assert that the deletion response confirms logical/soft deletion (evidence of deletion remains with deleted=true and correct ID).
 * 4. Attempt to delete a non-existent access log entry, expecting a business error (e.g., 404 or compliance error response).
 * 5. Optionally, attempt to retrieve the deleted access log entry (using GET or equivalent, if available) to confirm the entry is not accessible as an active log, or response indicates deleted/archived status appropriately.
 */
export async function test_api_core_test_delete_access_log_entry_and_confirm_evidence(
  connection: api.IConnection,
) {
  // 1. Create a new access log entry
  const accessLog: ICoreAccessLog = await api.functional.core.accessLogs.post(connection, {
    body: {
      user_id: typia.random<string & tags.Format<"uuid">>(),
      session_id: null,
      event_type: "login",
      ip: "192.168.1.1",
      agent: "UnitTestAgent/1.0",
      success: true,
      occurred_at: new Date().toISOString(),
    } satisfies ICoreAccessLog.ICreate,
  });
  typia.assert(accessLog);

  // 2. Delete the access log entry by ID
  const delRes: ICoreAccessLog.IDeleteResult = await api.functional.core.accessLogs.eraseById(connection, {
    id: accessLog.id,
  });
  typia.assert(delRes);
  TestValidator.equals("deleted ID matches")(accessLog.id)(delRes.id);
  TestValidator.equals("delete flag true")(true)(delRes.deleted);

  // 3. Attempt to delete the same (now non-existent) log again and expect error
  await TestValidator.error("delete of non-existent should fail")(async () => {
    await api.functional.core.accessLogs.eraseById(connection, { id: accessLog.id });
  });

  // 4. (If a GET by ID exists, optionally verify the log is no longer available as an active record)
  // // const read = await api.functional.core.accessLogs.getById(connection, { id: accessLog.id });
  // // TestValidator.equals("status")("deleted")(read.status); // Example, if implementation exists
}

