import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IProductCatalogProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IProductCatalogProduct";
import type { IPageIProductCatalogProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIProductCatalogProduct";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate product search, filter, and sorting in the product catalog.
 *
 * This test ensures the /productCatalog/products PATCH endpoint returns correct paginated product lists
 * for various filter criteria, reflecting different product status/category inputs and edge cases.
 * It comprehensively validates filtering by category, status, product name, time range,
 * sorting by name, no result cases, and handling invalid filter inputs.
 *
 * Steps:
 * 1. Create multiple catalog products with various categories, names, and statuses.
 * 2. Fetch product lists with different filters (category, status, name, date range).
 * 3. Check pagination behavior (limit, page) and ensure correct record counts.
 * 4. Sort results by name and verify order.
 * 5. Test filter yielding zero results for unmatched queries.
 * 6. Test error response for invalid filter input (e.g., bad date format).
 */
export async function test_api_productCatalog_test_list_and_filter_products_with_various_criteria(
  connection: api.IConnection,
) {
  // 1. Create sample products with known field values
  const userId = typia.random<string & tags.Format<"uuid">>();

  const categories = ["electronics", "books", "office", "sports"];
  const statuses = ["active", "draft", "archived"];

  const createdProducts = await ArrayUtil.asyncRepeat(5)(async (i) => {
    const category = RandomGenerator.pick(categories);
    const status = RandomGenerator.pick(statuses);
    const name = `TestProduct_${category}_${status}_${i}`;
    const product = await api.functional.productCatalog.products.post(connection, {
      body: {
        name,
        description: `Description for ${name}`,
        internal_code: RandomGenerator.alphaNumeric(8),
        status,
        created_by_user_id: userId,
        updated_by_user_id: userId,
      } satisfies IProductCatalogProduct.ICreate,
    });
    typia.assert(product);
    return product;
  });

  // 2. Fetch products by specific category
  const categoryToTest = createdProducts[0].name.split('_')[1];
  const categoryResult = await api.functional.productCatalog.products.patch(connection, {
    body: { category: categoryToTest } satisfies IProductCatalogProduct.IRequest,
  });
  typia.assert(categoryResult);
  TestValidator.predicate("category filter should return at least one product")(
    categoryResult.data.length > 0
  );
  TestValidator.predicate("All returned products match category")(
    categoryResult.data.every(prod => prod.name.includes(categoryToTest))
  );

  // 3. Fetch products by product name substring
  const nameToTest = createdProducts[1].name.substring(0, 12); // 'TestProduct_'
  const nameResult = await api.functional.productCatalog.products.patch(connection, {
    body: { name: nameToTest } satisfies IProductCatalogProduct.IRequest,
  });
  typia.assert(nameResult);
  TestValidator.predicate("name filter should return partial matches")(
    nameResult.data.length > 0 &&
    nameResult.data.every(prod => prod.name.includes(nameToTest))
  );

  // 4. Fetch by status
  const statusToTest = createdProducts[2].status;
  const statusResult = await api.functional.productCatalog.products.patch(connection, {
    body: { status: statusToTest } satisfies IProductCatalogProduct.IRequest,
  });
  typia.assert(statusResult);
  TestValidator.predicate("All returned products match status")(
    statusResult.data.every(prod => prod.status === statusToTest)
  );

  // 5. Pagination: limit to 2 per page
  const pagedResult = await api.functional.productCatalog.products.patch(connection, {
    body: { limit: 2, page: 1 } satisfies IProductCatalogProduct.IRequest,
  });
  typia.assert(pagedResult);
  TestValidator.equals("Max 2 products per page")(2)(pagedResult.data.length);

  // 6. Pagination: second page
  const pagedResult2 = await api.functional.productCatalog.products.patch(connection, {
    body: { limit: 2, page: 2 } satisfies IProductCatalogProduct.IRequest,
  });
  typia.assert(pagedResult2);
  TestValidator.predicate("Correct pagination for page 2")(pagedResult2.pagination.current === 2);

  // 7. Date range: created_at_from/created_at_to
  const minDate = createdProducts[0].created_at;
  const maxDate = createdProducts[createdProducts.length - 1].created_at;
  const dateRangeResult = await api.functional.productCatalog.products.patch(connection, {
    body: { created_at_from: minDate, created_at_to: maxDate } satisfies IProductCatalogProduct.IRequest,
  });
  typia.assert(dateRangeResult);
  TestValidator.predicate("Products within date range")(
    dateRangeResult.data.every(prod => prod.created_at >= minDate && prod.created_at <= maxDate)
  );

  // 8. No match filter
  const noMatchResult = await api.functional.productCatalog.products.patch(connection, {
    body: { name: "nonexistent_product_name_zzz" } satisfies IProductCatalogProduct.IRequest,
  });
  typia.assert(noMatchResult);
  TestValidator.equals("Empty result for non-matching filter")(0)(noMatchResult.data.length);

  // 9. Invalid filter input: bad date format
  await TestValidator.error("invalid date-time filter triggers error")(async () => {
    await api.functional.productCatalog.products.patch(connection, {
      body: { created_at_from: "bad-date-format" as any } as any,
    });
  });
}

