 *
 * Scenario:
 * 1. Attempt to create a product with valid required and all optional fields.
 *    - Expect success and assert all returned values.
 * 2. Try creating a product with missing required fields (each field missing in turn).
 *    - Expect API-level validation error for each attempt.
 * 3. Try creating a product with invalid formats (e.g., invalid UUID format for user id).
 *    - Expect validation errors on the appropriate fields.
 * 4. Attempt to create a product with a duplicated internal_code (should be unique per business rule).
 *    - Expect conflict or duplication error.
 *
 * Steps:
 * 1. Generate random user ids (created_by_user_id, updated_by_user_id) with valid uuids.
 * 2. Create a valid IProductCatalogProduct.ICreate input and POST it—expect success, validate output.
 * 3. For each required field, try creating a product with it missing; expect error.
 * 4. For user id fields, try sending an invalid UUID; expect error.
 * 5. Try to create a duplicate product (same internal_code); expect error.
 */
export async function test_api_productCatalog_test_create_product_with_success_and_failure_cases(connection: api.IConnection) {
  // Step 1: Create a valid product
  const productInput: IProductCatalogProduct.ICreate = {
    created_by_user_id: typia.random<string & tags.Format<"uuid">>(),
    updated_by_user_id: typia.random<string & tags.Format<"uuid">>(),
