  typia.assert(product);
  TestValidator.equals("name")(productInput.name)(product.name);
  TestValidator.equals("internal_code")(productInput.internal_code)(product.internal_code);

  // Step 2: Create product with missing required fields
  for (const key of Object.keys(productInput)) {
    const invalidInput = { ...productInput };
    // @ts-expect-error intentionally remove field for test
    delete invalidInput[key];
    await TestValidator.error(`missing required field: ${key}`)(async () => {
      return api.functional.productCatalog.products.post(connection, { body: invalidInput });
    });
  }

  // Step 3: Invalid UUID formats for user id fields
  for (const key of ["created_by_user_id", "updated_by_user_id"]) {
    const invalidInput = { ...productInput, [key]: "not-a-uuid" };
    await TestValidator.error(`invalid uuid format for field: ${key}`)(async () => {
      return api.functional.productCatalog.products.post(connection, { body: invalidInput });
    });
  }

  // Step 4: Create product with duplicate internal_code
  const duplicateInput = { ...productInput, name: RandomGenerator.paragraph()(2) };
  await TestValidator.error("duplicate internal_code")(async () => {
    return api.functional.productCatalog.products.post(connection, { body: duplicateInput });
  });
