import { tags } from "typia";

/**
 * Detailed ProductCatalog product object as per products table definition in
 * Prisma DB schema. Used as context for catalog, event, audit, and evidence
 * embedding.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IProductCatalogProduct = {
  id: string & tags.Format<"uuid">;
  created_by_user_id: string & tags.Format<"uuid">;
  updated_by_user_id: string & tags.Format<"uuid">;
  name: string;
  description: string;
  internal_code: string;
  status: string;
  created_at: string & tags.Format<"date-time">;
  updated_at: string & tags.Format<"date-time">;
};
export namespace IProductCatalogProduct {
  /**
   * 신규 제품 생성에 필요한 페이로드 타입입니다. 카탈로그 정규화 규칙에 따라 name, description,
   * internal_code, status 등 필수 입력값과 생성/수정 이력용 유저 ID를 포함합니다.
   *
   * 신규 제품 등록 시, business logic 에서는 중복 internal_code, 필수 필드 누락, 조직/권한 유효성, AI
   * 트리거링 등을 검증합니다.
   */
  export type ICreate = {
    /** 제품 최초 등록자(사용자 ID). 필수. 감사 및 책임 추적, 내부 규정 준수 목적. */
    created_by_user_id: string & tags.Format<"uuid">;

    /** 초기 생성자와 동일하게 입력. 최초 생성시에는 생성자와 동일, 이후 수정 요청에는 변경됨. */
    updated_by_user_id: string & tags.Format<"uuid">;

    /** 제품 공식명. UI 표기 및 검색 키. 예: 'Apple iPhone 23'. */
    name: string;

    /** 제품 설명문. 마케팅, AI 태깅/분석에 활용. */
    description: string;

    /** 조직 내 유일한 내부 코드. 외부 연동 및 벤더 시스템과의 싱크에 필요. */
    internal_code: string;

    /** 초기 등록 시점의 상태. 예: 'draft', 'active'. 결재/승인 로직과 워크플로우 분리 목적. */
    status: string;
  };

  /**
   * 제품 정보 업데이트(수정)에 필요한 페이로드 타입. 수정 가능 필드만 포함.
   *
   * 모든 수정 작업은 업데이트 사용자의 user_id, 변경 대상 제품 식별자, 변경 필드에 대한 유효성 체크, 중복
   * internal_code 방지, 기업 정책 및 AI 피드백 처리까지 반영.
   */
  export type IUpdate = {
    /** 변경을 시도하는 사용자 ID. 업데이트 이력 감사, 관리 책임 추적. */
    updated_by_user_id: string & tags.Format<"uuid">;

    /** 수정 대상 제품의 공식명. (선택적) */
    name?: string;

    /** 수정 대상 제품의 상세 설명 (옵션, 일부만 수정 가능). */
    description?: string;

    /** 수정 시에도 유일성 검증이 필요한 내부 코드. */
    internal_code?: string;

    /** 제품의 상태 필드 변경. */
    status?: string;
  };
}

