import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IProductCatalogProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IProductCatalogProduct";

/**
 * Test updating a product in the product catalog by ID, with validation of both success and failure edge cases.
 *
 * This test covers realistic update scenarios, including business rule and field validation, ensuring evidence audit
driven PATCH/PUT behavior. It also covers error handling for invalid or non-existent product IDs, missing required fields,
and API-side normalization logic.
 *
 * Steps:
 * 1. Create a baseline product via POST for update testing (ensuring proper dependency setup).
 * 2. Update the product by ID using api.functional.productCatalog.products.putById() with valid IUpdate payload.
 *    - Verify update result reflects requested changes and audit fields.
 * 3. Try updates with invalid (e.g. bad UUID, duplicate internal_code) or missing fields to check validation and error responses.
 * 4. Attempt to update a non-existent product ID and ensure a not-found or error response is received.
 */
export async function test_api_productCatalog_test_update_product_by_id_with_success_and_edge_cases(
  connection: api.IConnection,
) {
  // 1. Create a baseline product to update
  const initialProduct = await api.functional.productCatalog.products.post(connection, {
    body: {
      created_by_user_id: typia.random<string & tags.Format<"uuid">>(),
      updated_by_user_id: typia.random<string & tags.Format<"uuid">>(),
      name: `Test Product ${RandomGenerator.alphaNumeric(8)}`,
      description: RandomGenerator.paragraph()(),
      internal_code: `CODE_${RandomGenerator.alphaNumeric(6)}`,
      status: "active",
    } satisfies IProductCatalogProduct.ICreate,
  });
  typia.assert(initialProduct);

  // 2. Update with valid changes - name and description
  const updatedName = `Updated Product ${RandomGenerator.alphaNumeric(8)}`;
  const updatedDescription = RandomGenerator.paragraph()();
  const updateResult = await api.functional.productCatalog.products.putById(connection, {
    id: initialProduct.id,
    body: {
      updated_by_user_id: initialProduct.updated_by_user_id,
      name: updatedName,
      description: updatedDescription,
    } satisfies IProductCatalogProduct.IUpdate,
  });
  typia.assert(updateResult);
  TestValidator.equals("updated name should persist")(updatedName)(updateResult.name);
  TestValidator.equals("updated description should persist")(updatedDescription)(updateResult.description);
  TestValidator.equals("internal_code should be unchanged")(initialProduct.internal_code)(updateResult.internal_code);

  // 3a. Attempt with missing required updated_by_user_id
  await TestValidator.error("update missing updated_by_user_id should fail")(async () => {
    // Forcefully omit updated_by_user_id (but code generation should never break type safety)
    // Only runtime invalid values allowed
    await api.functional.productCatalog.products.putById(connection, {
      id: initialProduct.id,
      // @ts-expect-error: omitted for runtime failure
      body: {
        // missing updated_by_user_id - should fail validation at runtime
        name: "X",
      },
    });
  });

  // 3b. Attempt with duplicate internal_code
  // Setup: create a second product
  const secondProduct = await api.functional.productCatalog.products.post(connection, {
    body: {
      created_by_user_id: typia.random<string & tags.Format<"uuid">>(),
      updated_by_user_id: typia.random<string & tags.Format<"uuid">>(),
      name: `Another Product ${RandomGenerator.alphaNumeric(8)}`,
      description: RandomGenerator.paragraph()(),
      internal_code: `DUPLICATE_CODE_${RandomGenerator.alphaNumeric(6)}`,
      status: "active",
    } satisfies IProductCatalogProduct.ICreate,
  });
  typia.assert(secondProduct);
  // Try to set first product's internal_code to the new one's (should fail)
  await TestValidator.error("duplicate internal_code should fail")(async () => {
    await api.functional.productCatalog.products.putById(connection, {
      id: initialProduct.id,
      body: {
        updated_by_user_id: initialProduct.updated_by_user_id,
        internal_code: secondProduct.internal_code,
      } satisfies IProductCatalogProduct.IUpdate,
    });
  });

  // 4. Attempt to update non-existent product ID
  await TestValidator.error("update with non-existent ID should fail")(async () => {
    await api.functional.productCatalog.products.putById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(), // random ID unlikely to exist
      body: {
        updated_by_user_id: typia.random<string & tags.Format<"uuid">>(),
        name: "NonExistent Product",
      } satisfies IProductCatalogProduct.IUpdate,
    });
  });
}

