 *
 * Covers the following business scenarios:
 * - Updating a product with valid changes and verifying persistence and normalization.
 * - Attempting update with missing required fields (should fail runtime validation).
 * - Attempting update with duplicate internal_code (should fail business rule uniqueness validation).
 * - Trying to update a non-existent product (should return a not-found or error response).
 *
 * Steps:
 * 1. Create an initial product (dependency - to test updates on an existing entity).
 * 2. Update the product's name and description with valid values. Verify that changes are reflected.
 * 3. Attempt to update using an invalid payload (missing required field 'updated_by_user_id').
 * 4. Attempt to update with a duplicate internal_code already used by another product.
 * 5. Try to update a non-existent product and ensure proper error response.
 */
export async function test_api_productCatalog_test_update_product_by_id_with_success_and_edge_cases(
  connection: api.IConnection,
) {
  // 1. Create an initial product
  const initialProduct = await api.functional.productCatalog.products.post(connection, {
    body: {
      created_by_user_id: typia.random<string & tags.Format<"uuid">>(),
      updated_by_user_id: typia.random<string & tags.Format<"uuid">>(),
      name: `Test Product ${RandomGenerator.alphaNumeric(8)}`,
      description: RandomGenerator.paragraph()(),
      internal_code: `CODE_${RandomGenerator.alphaNumeric(6)}`,
      status: "active",
    } satisfies IProductCatalogProduct.ICreate,
  });
  typia.assert(initialProduct);

  // 2. Update the product's name and description (valid update)
  const updatedName = `Updated Product ${RandomGenerator.alphaNumeric(8)}`;
  const updatedDescription = RandomGenerator.paragraph()();
  const updateResult = await api.functional.productCatalog.products.putById(connection, {
    id: initialProduct.id,
    body: {
      updated_by_user_id: initialProduct.updated_by_user_id,
      name: updatedName,
      description: updatedDescription,
    } satisfies IProductCatalogProduct.IUpdate,
  });
  typia.assert(updateResult);
  TestValidator.equals("name updated")(updatedName)(updateResult.name);
  TestValidator.equals("description updated")(updatedDescription)(updateResult.description);
  TestValidator.equals("internal_code unchanged")(initialProduct.internal_code)(updateResult.internal_code);

  // 3. Try to update with missing required field (should fail)
  await TestValidator.error("missing updated_by_user_id should fail")(async () => {
