  // 4. Try update with duplicate internal_code (should fail)
  const secondProduct = await api.functional.productCatalog.products.post(connection, {
    body: {
      created_by_user_id: typia.random<string & tags.Format<"uuid">>(),
      updated_by_user_id: typia.random<string & tags.Format<"uuid">>(),
      name: `Second Product ${RandomGenerator.alphaNumeric(8)}`,
      description: RandomGenerator.paragraph()(),
      internal_code: `DUPLICATE_CODE_${RandomGenerator.alphaNumeric(6)}`,
      status: "active",
    } satisfies IProductCatalogProduct.ICreate,
  });
  typia.assert(secondProduct);
  await TestValidator.error("duplicate internal_code should fail")(async () => {
    await api.functional.productCatalog.products.putById(connection, {
      id: initialProduct.id,
      body: {
        updated_by_user_id: initialProduct.updated_by_user_id,
        internal_code: secondProduct.internal_code,
      } satisfies IProductCatalogProduct.IUpdate,
    });
  });

  // 5. Try to update non-existent product (should fail)
  await TestValidator.error("non-existent product ID should fail")(async () => {
    await api.functional.productCatalog.products.putById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
      body: {
        updated_by_user_id: typia.random<string & tags.Format<"uuid">>(),
        name: "Should Not Work",
      } satisfies IProductCatalogProduct.IUpdate,
