import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IProductCatalogProductVariant } from "@ORGANIZATION/PROJECT-api/lib/structures/IProductCatalogProductVariant";
import type { IPageIProductCatalogProductVariant } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIProductCatalogProductVariant";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * E2E 테스트: 다양한 필터로 제품 변형(Variant) 목록/검색 검증
 *
 * 이 테스트는 카탈로그 내 제품 변형(variant) 리스트 조회/검색 기능의 정상 동작을 검증합니다.
 * 주요 목표:
 *  - parent product, SKU, barcode, 사용 가능 여부, import_feed_id 등으로 필터링 시 올바른 결과 반환
 *  - 페이징(offest, limit) 옵션 정상 동작 확인
 *  - 존재하지 않는 값/유효하지 않은 필터 입력시 에러 혹은 empty 반환 등 edge case 대응
 *  - 여러 variants 데이터가 생성된 상태여야 하므로 사전 데이터 생성이 필요함
 *
 * [테스트 절차]
 * 1. (Dependency) 임의의 parent product_id로 여러 variants 생성 (sku, barcode, available 상이한 값 섞어서)
 * 2. parent product_id로만 필터 시 해당 product에 해당되는 variant만
 * 3. 개별 sku, barcode 값으로 각각 필터 시 단일/정확히 매칭되는 variant만
 * 4. available true/false 별로 구분 조회
 * 5. import_feed_id, created_at 범위 등 필터 조합/edge case
 * 6. limit, offset 입력시 페이지네이션 정확성 확인
 * 7. 엉뚱한 uuid, 이상한 필드값 입력 시 empty or 적절한 에러 반환 확인
 */
export async function test_api_productCatalog_test_list_search_product_variants_with_various_filters(
  connection: api.IConnection,
) {
  // 1. 사전 데이터 생성 (서로 다른 product_id/sku/barcode/available 조합 여러 개)
  const baseProductId = typia.random<string & tags.Format<"uuid">>();
  // 임의 spec 다르게 최소 3개 생성, 일부는 다른 product_id도 섞기
  const variants = await Promise.all([
    api.functional.productCatalog.productVariants.post(connection, { body: { product_id: baseProductId, sku: RandomGenerator.alphaNumeric(8), price: 12000, barcode: RandomGenerator.alphaNumeric(10), available: true } satisfies IProductCatalogProductVariant.ICreate }),
    api.functional.productCatalog.productVariants.post(connection, { body: { product_id: baseProductId, sku: RandomGenerator.alphaNumeric(8), price: 15500, barcode: RandomGenerator.alphaNumeric(10), available: false } satisfies IProductCatalogProductVariant.ICreate }),
    api.functional.productCatalog.productVariants.post(connection, { body: { product_id: baseProductId, sku: RandomGenerator.alphaNumeric(8), price: 19800, barcode: RandomGenerator.alphaNumeric(10), available: true } satisfies IProductCatalogProductVariant.ICreate }),
    // product_id 다르게 추가
    api.functional.productCatalog.productVariants.post(connection, { body: { product_id: typia.random<string & tags.Format<"uuid">﻿>(), sku: RandomGenerator.alphaNumeric(8), price: 26800, barcode: RandomGenerator.alphaNumeric(10), available: true } satisfies IProductCatalogProductVariant.ICreate })
  ]);
  typia.assert(variants);

  // 2. parent product_id로만 필터
  const resByProduct = await api.functional.productCatalog.productVariants.patch(connection, {
    body: { product_id: baseProductId } satisfies IProductCatalogProductVariant.IRequest
  });
  typia.assert(resByProduct);
  TestValidator.equals("filtered by product_id")(
    resByProduct.data.map(v => v.id).sort()
  )(
    variants.filter(v => v.product_id === baseProductId).map(v => v.id).sort()
  );

  // 3. SKU별 개별 필터 확인
  for (const v of variants) {
    const resBySku = await api.functional.productCatalog.productVariants.patch(connection, {
      body: { sku: v.sku } satisfies IProductCatalogProductVariant.IRequest
    });
    typia.assert(resBySku);
    TestValidator.predicate("filtered by SKU")(
      resBySku.data.some(item => item.sku === v.sku && item.id === v.id)
    );
  }

  // 4. available true/false 필터
  for (const flag of [true, false]) {
    const resByAvailable = await api.functional.productCatalog.productVariants.patch(connection, {
      body: { available: flag } satisfies IProductCatalogProductVariant.IRequest
    });
    typia.assert(resByAvailable);
    // 생성한 variants 중 해당 available 인 것들이 포함되어야 함
    for (const x of variants.filter(v => v.available === flag)) {
      TestValidator.predicate(`filtered by available=${flag}`)(
        resByAvailable.data.some(item => item.id === x.id)
      );
    }
  }

  // 5. 존재하지 않는 barcode나 product_id로 필터 -> empty
  const notExistsId = typia.random<string & tags.Format<"uuid">>();
  const notExistsRes = await api.functional.productCatalog.productVariants.patch(connection, {
    body: { product_id: notExistsId } satisfies IProductCatalogProductVariant.IRequest
  });
  typia.assert(notExistsRes);
  TestValidator.equals("non-existent id yields empty")(notExistsRes.data.length)(0);

  // 6. 페이징 테스트: limit = 1, offset = 1
  const pagingRes = await api.functional.productCatalog.productVariants.patch(connection, {
    body: { product_id: baseProductId, limit: 1, offset: 1 } satisfies IProductCatalogProductVariant.IRequest
  });
  typia.assert(pagingRes);
  TestValidator.equals("pagination count")(pagingRes.data.length)(1);

  // 7. invalid 필드값 입력 (available: 'xx' 등) -> type error는 타입스크립트에서 잡으므로, runtime 에러만 check
  // 만약 runtime 에러 케이스 추가시 아래처럼 작성 가능합니다 (예시)
  // TestValidator.error("invalid uuid")(async () => {
  //   await api.functional.productCatalog.productVariants.patch(connection, { body: { product_id: "invalid-uuid" as any } });
  // });
}

