/**
 * Detailed product variant entity as defined in Prisma
 * ProductCatalog.product_variants table. Used throughout inventory, cart/order,
 * and catalog evidencing.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IProductCatalogProductVariant = {
  /**
   * Unique primary key for the variant. See product_variants.id in Prisma
   * schema.
   */
  id: string & tags.Format<"uuid">;

  /** Reference to the parent product. */
  product_id: string & tags.Format<"uuid">;

  /**
   * Reference to source import feed if this variant was loaded from external
   * data.
   */
  import_feed_id?: string & tags.Format<"uuid">;

  /**
   * Stock-keeping unit (SKU / unique variant code). Used in commerce,
   * fulfillment, analytics.
   */
  sku: string;

  /** Current unit price for this variant. */
  price: number &
    tags.JsonSchemaPlugin<{
      format: "double";
    }>;

  /** Retail barcode/EAN for this variant. */
  barcode: string;

  /** Whether the variant is available for sale. */
  available: boolean;

  /** Timestamp of variant creation. */
  created_at: string & tags.Format<"date-time">;

  /** Timestamp when this variant was last updated. */
  updated_at: string & tags.Format<"date-time">;
};
