import api from "@ORGANIZATION/PROJECT-api";
import type { IProductCatalogProductVariant } from "@ORGANIZATION/PROJECT-api/lib/structures/IProductCatalogProductVariant";

/**
 * Validate retrieval of a product variant's details by its unique identifier (ID).
 *
 * Business context:
 * - Ensures core catalog lookup by ID functions as expected for inventory, evidence, and audit processes.
 *
 * Steps:
 * 1. Create a product variant via POST /productCatalog/productVariants (to guarantee a known variant exists)
 * 2. Perform GET /productCatalog/productVariants/{id} using the ID from the created variant: the call should return a valid record and all fields should match
 * 3. Attempt to GET by a random (non-existent) UUID: the call should fail with a not found/business error
 * 4. (Optionally) Confirm the error type and message for the not found case
 *
 * Validations:
 * - The correct record is returned for the valid ID
 * - Type and field-level shape match the IProductCatalogProductVariant DTO
 * - Error thrown for invalid/random ID as per API contract
 */
export async function test_api_productCatalog_test_get_product_variant_by_valid_and_invalid_id(
  connection: api.IConnection,
) {
  // 1. Create a product variant for testing retrieval
  const createInput: IProductCatalogProductVariant.ICreate = {
    product_id: typia.random<string & tags.Format<"uuid">>(),
    sku: RandomGenerator.alphabets(12),
    price: Math.round(Math.random() * 100000) / 100,
    barcode: RandomGenerator.alphaNumeric(13),
    available: true,
    // Optional: import_feed_id omitted for non-import case
  };
  const created = await api.functional.productCatalog.productVariants.post(connection, { body: createInput });
  typia.assert(created);

  // 2. Retrieve the product variant by the valid ID
  const fetched = await api.functional.productCatalog.productVariants.getById(connection, { id: created.id });
  typia.assert(fetched);

  // Assert all critical fields are as expected
  TestValidator.equals("id matches")(created.id)(fetched.id);
  TestValidator.equals("sku")(created.sku)(fetched.sku);
  TestValidator.equals("barcode")(created.barcode)(fetched.barcode);
  TestValidator.equals("available")(created.available)(fetched.available);
  TestValidator.equals("price")(created.price)(fetched.price);
  TestValidator.equals("product_id")(created.product_id)(fetched.product_id);

  // 3. Attempt retrieval by a random (non-existent) UUID
  await TestValidator.error("not found for unknown id")(() =>
    api.functional.productCatalog.productVariants.getById(connection, {
      id: typia.random<string & tags.Format<"uuid">>()
    })
  );
}

