import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IProductCatalogProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IProductCatalogProduct";
import type { IProductCatalogProductVariant } from "@ORGANIZATION/PROJECT-api/lib/structures/IProductCatalogProductVariant";

/**
 * Validate creation of product variants attached to a valid product,
 * as well as error handling for invalid or duplicate attribute cases.
 *
 * 1. Create a parent Product (audit/evidence required for success)
 * 2. Create a ProductVariant, passing all required fields, and optional if relevant (audit/evidence required)
 * 3. Confirm the product variant matches attributes and links to parent product
 * 4. Try to create a variant with missing required field (e.g., missing SKU) → expect failure
 * 5. Try to create a variant with duplicate SKU or duplicate barcode for same product → expect error
 * 6. Try to create a variant referencing non-existent product_id → expect not found or invalid reference error
 */
export async function test_api_productCatalog_test_create_product_variant_success_and_failure_cases(
  connection: api.IConnection,
) {
  // 1. Create a parent Product
  const userId: string = typia.random<string & tags.Format<"uuid">>();

  const parentProduct = await api.functional.productCatalog.products.post(connection, {
    body: {
      created_by_user_id: userId,
      updated_by_user_id: userId,
      name: RandomGenerator.paragraph()(),
      description: RandomGenerator.content()()(),
      internal_code: RandomGenerator.alphaNumeric(8),
      status: "draft",
    } satisfies IProductCatalogProduct.ICreate,
  });
  typia.assert(parentProduct);

  // 2. Create a valid ProductVariant attached to the product
  const variantSku: string = RandomGenerator.alphaNumeric(10);
  const variantBarcode: string = RandomGenerator.alphaNumeric(12);
  const variant = await api.functional.productCatalog.productVariants.post(connection, {
    body: {
      product_id: parentProduct.id,
      sku: variantSku,
      price: 999.99,
      barcode: variantBarcode,
      available: true,
    } satisfies IProductCatalogProductVariant.ICreate,
  });
  typia.assert(variant);
  TestValidator.equals("linked product_id")(parentProduct.id)(variant.product_id);
  TestValidator.equals("SKU matches")(variantSku)(variant.sku);
  TestValidator.equals("barcode matches")(variantBarcode)(variant.barcode);
  TestValidator.equals("availability")(true)(variant.available);
  TestValidator.equals("price")(999.99)(variant.price);

  // 3. Attempt to create with missing required field (SKU)
  await TestValidator.error("missing required SKU should error")(async () => {
    // TypeScript does not allow actual omission, so test with empty string
    await api.functional.productCatalog.productVariants.post(connection, {
      body: {
        product_id: parentProduct.id,
        sku: "",
        price: 19.5,
        barcode: RandomGenerator.alphaNumeric(13),
        available: true,
      } satisfies IProductCatalogProductVariant.ICreate,
    });
  });

  // 4. Attempt to create with duplicate SKU
  await TestValidator.error("duplicate SKU should error")(async () => {
    await api.functional.productCatalog.productVariants.post(connection, {
      body: {
        product_id: parentProduct.id,
        sku: variantSku,
        price: 88.5,
        barcode: RandomGenerator.alphaNumeric(13),
