 *   b) Update a variant with non-existent ID (should fail with error).
 *   c) Update with invalid data types (e.g., string for price).
 *
 * Validation:
 * - Assert the variant is updated correctly (changed fields).
 * - Assert errors for invalid updates and for updating non-existent variants.
 */
export async function test_api_productCatalog_test_update_product_variant_by_id_various_cases(
  connection: api.IConnection,
) {
