import type { IProductCatalogProductVariant } from "@ORGANIZATION/PROJECT-api/lib/structures/IProductCatalogProductVariant";
import type { IProductVariant } from "@ORGANIZATION/PROJECT-api/lib/structures/IProductVariant";

/**
 * Soft-delete a product variant by id, ensuring evidential trace and referential integrity.
 *
 * - First, create a valid product variant using the create endpoint to ensure an existing variant is present.
 * - Delete the variant by its id, checking that the response indicates soft deletion with correct evidence fields retained and status change.
 * - Try to delete the same variant again: expect an error indicating already deleted (idempotency/error).
 * - Try to delete a random/nonexistent UUID variant, expect correct error handling (not found/integrity).
 * - Ensure original variant's id and evidence fields are not lost.
 * - Validate foreign key integrity (dependent resources not present: cart/order/inventory, so deletion should proceed).
 * - Assert structure/types of results and errors for contract compliance.
 */
export async function test_api_productCatalog_test_delete_product_variant_by_id_and_validate_integrity(
  connection: api.IConnection,
) {
  // 1. Create a product variant to operate on.
  //    This will serve as the variant to be deleted.
  const variantCreateInput: IProductCatalogProductVariant.ICreate = {
    product_id: typia.random<string & tags.Format<"uuid">>(),
    sku: RandomGenerator.alphaNumeric(8),
    price: typia.random<number>(),
    barcode: RandomGenerator.alphaNumeric(12),
    available: true,
  };
  const created = await api.functional.productCatalog.productVariants.post(connection, {
    body: variantCreateInput,
  });
  typia.assert(created);

  // 2. Delete the product variant by its id.
  const deleted = await api.functional.productCatalog.productVariants.eraseById(connection, {
    id: created.id,
  });
  typia.assert(deleted);
  TestValidator.equals("id after delete")(created.id)(deleted.id);
  TestValidator.predicate("delete result includes deleted_at timestamp")(!!deleted.deleted_at);
  TestValidator.equals("deleted status is marked")(deleted.status)("deleted");

  // 3. Attempt to delete again (should error / 404 / conflict)
  await TestValidator.error("double delete on already deleted variant")(() =>
    api.functional.productCatalog.productVariants.eraseById(connection, { id: created.id })
  );

  // 4. Attempt to delete a non-existent id (should error, not found)
  await TestValidator.error("delete non-existent variant")(() =>
    api.functional.productCatalog.productVariants.eraseById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
    })
  );
}

