import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IProductCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IProductCategory";
import type { IPageIProductCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIProductCategory";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate the listing and searching of product categories in the product catalog.
 *
 * This test covers a variety of list/search scenarios using the filtering options provided by the IProductCategory.IRequest type. It checks hierarchical filtering (parent_id), name-based search, pagination (offset, limit), and also success/failure behavior for invalid filter parameters. It also validates that the system responds correctly for empty filters (no filter), and edge cases such as no matching results or bad input. The setup creates multiple categories with and without hierarchy, to ensure the search behaviors are properly exercised.
 *
 * Steps:
 * 1. Create several root and child product categories (ensure some categories share a parent; others have none).
 * 2. List all categories with an empty filter -- expect all created categories are returned, paginated.
 * 3. Search using name filter for a known name substring -- expect only matching categories (case-insensitive, partial match).
 * 4. Search using parent_id filter for a parent with known children -- expect only direct children returned.
 * 5. Use offset/limit pagination and validate page boundaries and presence of result data.
 * 6. Attempt invalid parameter (bad UUID for parent_id, negative limit) -- verify appropriate error/failure responses.
 * 7. Edge: filter for name or parent_id that doesn't exist -- expect empty results, not error.
 */
export async function test_api_productCatalog_test_list_search_product_categories_with_various_criteria(connection: api.IConnection) {
  // 1. Create categories: root, second root, then several children under each
  const root1 = await api.functional.productCatalog.productCategories.post(connection, {
    body: { name: "RootOne" },
  });
  typia.assert(root1);
  const root2 = await api.functional.productCatalog.productCategories.post(connection, {
    body: { name: "RootTwo" },
  });
  typia.assert(root2);
  const child1a = await api.functional.productCatalog.productCategories.post(connection, {
    body: { name: "ChildA", parent_id: root1.id },
  });
  typia.assert(child1a);
  const child1b = await api.functional.productCatalog.productCategories.post(connection, {
    body: { name: "ChildB", parent_id: root1.id },
  });
  typia.assert(child1b);
  const child2a = await api.functional.productCatalog.productCategories.post(connection, {
    body: { name: "ChildA2", parent_id: root2.id },
  });
  typia.assert(child2a);
  // 2. List all categories, empty filter
  const all = await api.functional.productCatalog.productCategories.patch(connection, {
    body: {},
  });
  typia.assert(all);
  TestValidator.predicate("list all - contains all created")([
    root1.id,
    root2.id,
    child1a.id,
    child1b.id,
    child2a.id,
  ].every(id => all.data.map(cat => cat.id).includes(id)));
  // 3. Search by name (substring, case-insensitive)
  const matchChild = await api.functional.productCatalog.productCategories.patch(connection, {
    body: { name: "child" },
  });
  typia.assert(matchChild);
  TestValidator.equals("name search #child count")(2)(matchChild.data.length);
  TestValidator.predicate("name search - correct children found")(matchChild.data.every(cat => cat.name.toLowerCase().includes("child")));
  // 4. Filter by parent_id (root1)
  const byParent = await api.functional.productCatalog.productCategories.patch(connection, {
    body: { parent_id: root1.id },
  });
  typia.assert(byParent);
  TestValidator.equals("children under root1")(2)(byParent.data.length);
  TestValidator.predicate("parent filter - correct children")(byParent.data.every(cat => cat.parent_id === root1.id));
  // 5. Paginated (limit 2)
  const paged = await api.functional.productCatalog.productCategories.patch(connection, {
    body: { limit: 2 },
  });
  typia.assert(paged);
  TestValidator.equals("paged - limit")(2)(paged.pagination.limit);
  TestValidator.predicate("paged - data length")(paged.data.length <= 2);
  // 6. Invalid param (bad UUID)
  await TestValidator.error("invalid parent_id fails")(async () => {
    await api.functional.productCatalog.productCategories.patch(connection, {
      body: { parent_id: "not-a-uuid" },
    });
  });
  // 6b. Negative limit (should fail)
  await TestValidator.error("negative limit fails")(async () => {
    await api.functional.productCatalog.productCategories.patch(connection, {
      body: { limit: -1 },
    });
  });
  // 7. No match on name
  const noMatch = await api.functional.productCatalog.productCategories.patch(connection, {
    body: { name: "notpresent" },
  });
  typia.assert(noMatch);
  TestValidator.equals("no matching name")(0)(noMatch.data.length);
  // 7b. No match on parent_id
  const fakeParent = await api.functional.productCatalog.productCategories.patch(connection, {
    body: { parent_id: root1.id.replace(/./g, "f") },
  });
  typia.assert(fakeParent);
  TestValidator.equals("no matching parent_id")(0)(fakeParent.data.length);
}

