import { tags } from "typia";

/**
 * Represents a single product category in the catalog, aligned with the Product
 * Management module requirements and Prisma DB schema.
 *
 * This entity forms the basis of faceted, hierarchical product taxonomy, as
 * required for discoverability, navigation, and AI-driven enrichment (see
 * requirements for AI/ML enrichment, analytics, evidence preservation, and
 * global commerce adaptation).
 *
 * The design ensures strict 3NF—parent/child relationships are normalized via
 * parent_id. All metadata is captured for compliance, evidence, and audit
 * tracking.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IProductCategory = {
  /**
   * Globally unique product category identifier. References 'id' in
   * product_categories (PK).
   */
  id: string & tags.Format<"uuid">;

  /**
   * Optional parent category reference. Null for root categories. Based on
   * 3NF normalization requirements and supporting unlimited hierarchical
   * taxonomies (see ER diagrams, requirements, and schema comment).
   */
  parent_id?: (string & tags.Format<"uuid">) | null;

  /**
   * Human-readable category name. Must be unique and atomic. E.g., 'Apparel',
   * 'Shoes', 'Men's Running'. Enforced by the unique constraint in the Prisma
   * DB schema.
   */
  name: string;

  /**
   * Timestamp when the category was created. Essential for audit/evidence,
   * analytics, and materialized views. Required by audit/compliance log
   * modules.
   */
  created_at: string & tags.Format<"date-time">;

  /**
   * Timestamp of the last update to the category. Enables change tracking,
   * compliance, and analytics. Not derived from other fields.
   */
  updated_at: string & tags.Format<"date-time">;
};
export namespace IProductCategory {
  /**
   * Payload for creating a new product category.
   *
   * Maps to fields in product_categories. Parent_id enables tree/hierarchy.
