import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IProductCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IProductCategory";

/**
 * Validate the update functionality for product categories by id.
 *
 * This test ensures that updates to a product category respect atomic field changes, allow modification of both the category name and its hierarchy (parent_id), and properly enforce business rules including tree integrity and DB constraints.
 *
 * Key validation points:
 * 1. Successful atomic update of name and parent_id.
 * 2. Attempt update with invalid data (e.g., duplicate name).
 * 3. Attempt a circular hierarchy update (set category parent to itself).
 * 4. Attempt to update a non-existent category.
 * 5. Validate all failure modes have correct error handling.
 *
 * Test Workflow:
 * 1. Create a root category (parent_id=null).
 * 2. Create a subcategory (parent_id=root.id).
 * 3. Update subcategory name and parent_id (move under a new parent, or to root).
 * 4. Attempt to update subcategory with a duplicate name (should fail).
 * 5. Attempt to set parent to its own id (circular, should fail).
 * 6. Attempt to update a random UUID that does not exist (should fail).
 */
export async function test_api_productCatalog_productCategories_putById(
  connection: api.IConnection,
) {
  // 1. Create a root category
  const rootCategory = await api.functional.productCatalog.productCategories.post(connection, {
    body: { name: RandomGenerator.paragraph()(2), parent_id: null },
  });
  typia.assert(rootCategory);

  // 2. Create a subcategory under the root
  const subCategory = await api.functional.productCatalog.productCategories.post(connection, {
    body: { name: RandomGenerator.paragraph()(2), parent_id: rootCategory.id },
  });
  typia.assert(subCategory);

  // 3. Create another (sibling) category, to test duplicate naming
  const siblingCategory = await api.functional.productCatalog.productCategories.post(connection, {
    body: { name: RandomGenerator.paragraph()(2), parent_id: rootCategory.id },
  });
  typia.assert(siblingCategory);

  // 4. Atomic update: Change the subcategory's name and move under sibling
  const newName = RandomGenerator.paragraph()(2);
  const updated = await api.functional.productCatalog.productCategories.putById(connection, {
    id: subCategory.id,
    body: { name: newName, parent_id: siblingCategory.id },
  });
  typia.assert(updated);
  TestValidator.equals("updated name")(newName)(updated.name);
  TestValidator.equals("updated parent")(siblingCategory.id)(updated.parent_id);

  // 5. Failure: Try to update subcategory to a duplicate name (should fail)
  await TestValidator.error("duplicate name fails")(async () => {
    await api.functional.productCatalog.productCategories.putById(connection, {
      id: subCategory.id,
      body: { name: siblingCategory.name },
    });
  });

  // 6. Failure: Try to make subCategory parent itself (should fail - circular)
  await TestValidator.error("circular parent")(async () => {
    await api.functional.productCatalog.productCategories.putById(connection, {
      id: subCategory.id,
      body: { parent_id: subCategory.id },
    });
  });

  // 7. Failure: Try to update a non-existent category
  await TestValidator.error("non-existent category")(async () => {
    await api.functional.productCatalog.productCategories.putById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
      body: { name: RandomGenerator.paragraph()(2) },
    });
  });
}

