import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IProductCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IProductCategory";

/**
 * Validate the soft-deletion and referential integrity for product category deletion by ID.
 *
 * This test covers:
 * 1. Creating categories (both orphan and parent-child).
 * 2. Deleting an orphan/root category – verify evidence retention (soft-delete, ID confirmed, deleted_at set).
 * 3. Attempting to delete a parent category that still has a child – verify 409 Conflict error (referential integrity).
 * 4. Attempting to delete a non-existent UUID – verify 404 or appropriate error.
 * 5. Attempting to delete a category already deleted – verify graceful error (e.g., 404).
 */
export async function test_api_productCatalog_test_delete_product_category_by_id_with_referential_integrity(
  connection: api.IConnection,
) {
  // 1. Create categories
  // 1.1. Orphan/root category
  const orphanPayload: IProductCategory.ICreate = { name: "Orphan Category" };
  const orphanCategory: IProductCategory = await api.functional.productCatalog.productCategories.post(connection, { body: orphanPayload });
  typia.assert(orphanCategory);

  // 1.2. Parent with child
  const parentPayload: IProductCategory.ICreate = { name: "Parent Category" };
  const parentCategory: IProductCategory = await api.functional.productCatalog.productCategories.post(connection, { body: parentPayload });
  typia.assert(parentCategory);
  const childPayload: IProductCategory.ICreate = { name: "Child Category", parent_id: parentCategory.id };
  const childCategory: IProductCategory = await api.functional.productCatalog.productCategories.post(connection, { body: childPayload });
  typia.assert(childCategory);

  // 2. Delete orphan category – should succeed, evidence retained
  const orphanDelete: IProductCategory.IDeleteResult = await api.functional.productCatalog.productCategories.eraseById(connection, { id: orphanCategory.id });
  typia.assert(orphanDelete);
  TestValidator.equals("Deleted orphan category should match the original")(orphanDelete.id)(orphanCategory.id);
  TestValidator.predicate("deleted_at field should be set, evidence optional")(typeof orphanDelete.deleted_at === 'string' && orphanDelete.deleted_at.length > 0);

