import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IProductCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IProductCategory";

/**
 * Validate the soft-deletion and referential integrity for product category deletion by ID.
 *
 * This test covers:
 * 1. Creating categories (orphan/root, parent-child)
 * 2. Deleting an orphan category – evidence retention is verified (soft-delete, ID check, deleted_at present)
 * 3. Attempting deletion of a parent category with children – ensure 409 Conflict (referential integrity ensured)
 * 4. Deleting a non-existent category – 404 error
 * 5. Deleting an already deleted category – graceful 404 error
 */
export async function test_api_productCatalog_test_delete_product_category_by_id_with_referential_integrity(
  connection: api.IConnection,
) {
  // 1. Create categories
  // 1.1 Orphan/root category
  const orphanPayload: IProductCategory.ICreate = {
    name: "Orphan Category",
  };
  const orphanCategory: IProductCategory = await api.functional.productCatalog.productCategories.post(
    connection,
    { body: orphanPayload },
  );
  typia.assert(orphanCategory);

  // 1.2 Parent with child
  const parentPayload: IProductCategory.ICreate = {
    name: "Parent Category",
  };
  const parentCategory: IProductCategory = await api.functional.productCatalog.productCategories.post(
    connection,
    { body: parentPayload },
  );
  typia.assert(parentCategory);
  const childPayload: IProductCategory.ICreate = {
    name: "Child Category",
    parent_id: parentCategory.id,
  };
  const childCategory: IProductCategory = await api.functional.productCatalog.productCategories.post(
    connection,
    { body: childPayload },
  );
  typia.assert(childCategory);

  // 2. Delete orphan category
  const orphanDelete: IProductCategory.IDeleteResult = await api.functional.productCatalog.productCategories.eraseById(
    connection,
    { id: orphanCategory.id },
  );
  typia.assert(orphanDelete);
  TestValidator.equals("Deleted orphan category should match the original")(orphanDelete.id)(orphanCategory.id);
  TestValidator.predicate("deleted_at field should be set, evidence optional")(typeof orphanDelete.deleted_at === "string" && orphanDelete.deleted_at.length > 0);

  // 3. Delete parent category with child – must fail (referential integrity, 409)
  await TestValidator.error("Parent category with child cannot be deleted")(
    async () => {
      await api.functional.productCatalog.productCategories.eraseById(connection, { id: parentCategory.id });
    },
    (exp) => {
      TestValidator.equals("should fail with 409 Conflict")((exp as any)?.status)(409);
      return true;
    },
  );

  // 4. Delete non-existent category
  const randomId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("Deleting non-existent category should fail")(
    async () => {
      await api.functional.productCatalog.productCategories.eraseById(connection, { id: randomId });
    },
    (exp) => {
      TestValidator.equals("should fail with 404 Not Found")((exp as any)?.status)(404);
      return true;
    },
  );

  // 5. Delete an already deleted category
  await TestValidator.error("Deleting already deleted category should fail")(
    async () => {
      await api.functional.productCatalog.productCategories.eraseById(connection, { id: orphanCategory.id });
    },
    (exp) => {
      TestValidator.equals("should fail with 404 Not Found")((exp as any)?.status)(404);
      return true;
    },
  );
}

