import { tags } from "typia";

/**
 * Represents a single product option for a product in the product catalog.
 *
 * Implements the graded attribute/variant structure per requirements and DB
 * schema comments. Forms the basis for onboarding, analytics, and variant
 * management. AI workflows may auto-suggest or import these during catalog
 * enrichment.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IProductOption = {
  /** Unique identifier for the product option. PK in 'product_options'. */
  id: string & tags.Format<"uuid">;

  /** Identifies the product this option belongs to. FK in product_options. */
  product_id: string & tags.Format<"uuid">;

  /**
   * Type/kind of the product option (e.g., 'color', 'size'). Enables AI
   * onboarding and multi-variant support.
   */
  option_type: string;

  /**
   * Atomic option value (e.g., 'Red', 'XL'). Fully normalized and used for
   * search, analytics, onboarding.
   */
  value: string;
};
export namespace IProductOption {
  /**
   * Payload structure for paginated, filtered search of product options.
   *
   * Supports onboarding, analytics, bulk edits, and catalog QA workflows.
   * Mirrors best practices for API search semantics and is consistent with
   * related IPageIProductOption patterns.
   */
  export type IRequest = {
    /**
     * Optional filter: product to which option is scoped. Allows listing
     * only options for that product.
     */
    product_id?: (string & tags.Format<"uuid">) | null;

    /**
     * Filter: type/kind of the product option (e.g., 'color', 'size').
     * Enables faceted onboarding, bulk operations.
     */
    option_type?: string | null;

    /**
     * Filter: exact or partial search for product option value (e.g.,
     * 'Red'). Used for query and auto-suggest in onboarding flows.
     */
    value?: string | null;

    /**
     * Which page of data to return (pagination). See IPage.IRequest for
     * details.
     */
    page?:
      | (number &
          tags.Type<"int32"> &
          tags.JsonSchemaPlugin<{
            format: "uint32";
          }>)
      | null;

    /** Maximum number of records per page. Default depends on system policy. */
    limit?:
      | (number &
          tags.Type<"int32"> &
          tags.JsonSchemaPlugin<{
            format: "uint32";
          }>)
      | null;
  };

  /**
   * Creation payload for a new product option/attribute for onboarding,
   * AI-driven catalog management, or manual entry.
   *
   * Input is validated for reference integrity, uniqueness, and normalization
   * per catalog management requirements.
   */
  export type ICreate = {
    /**
     * The product to which this option will be added. Must reference a
     * valid product.
     */
    product_id: string & tags.Format<"uuid">;

    /**
     * The type of option to associate with the product (e.g., 'color',
     * 'size').
     */
    option_type: string;

    /**
     * Atomic string value—must be unique per product:type:value tuple (see
     * DB schema uniqueness/analytics requirements).
     */
    value: string;
  };
}

