  const listKeyword = await api.functional.productCatalog.productOptions.patch(connection, {
    body: { value: "Co" },
  });
  typia.assert(listKeyword);
  for (const opt of listKeyword.data) TestValidator.predicate("키워드 포함 확인")(opt.value.includes("Co"));

