import { tags } from "typia";

/**
 * A single API client registry record (integration partner, app, or system
 * client).
 *
 * Captures business, registry, audit, and onboarding fields per Prisma schema
 * for api_clients.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IApiClients = {
  /**
   * Unique API client record identifier.
   *
   * Reference: IApiClients.id, system registry index.
   */
  id: string & tags.Format<"uuid">;

  /**
   * Display/human readable name of the API client.
   *
   * Reference: IApiClients.client_name; unique for system registry.
   */
  client_name: string;

  /**
   * Business or technical description of the client app/integration.
   *
   * Reference: IApiClients.description; optional field for admins.
   */
  description?: string | null;

  /**
   * Administrative/support contact email for this client (unique).
   *
   * Reference: IApiClients.contact_email.
   */
  contact_email: string;

  /**
   * Public key/certificate used for secure signing or auth.
   *
   * Reference: IApiClients.public_key; may be null if not used.
   */
  public_key?: string | null;

  /**
   * Current activation status of this client (true = may use API).
   *
   * Reference: IApiClients.is_active.
   */
  is_active: boolean;

  /**
   * When this client was registered with the platform.
   *
   * Reference: IApiClients.created_at.
   */
  created_at: string & tags.Format<"date-time">;

  /**
   * Soft deletion timestamp (set if deactivated/deleted, but record remains
   * for audit).
   *
   * Reference: IApiClients.deleted_at.
   */
  deleted_at?: (string & tags.Format<"date-time">) | null;
};
export namespace IApiClients {
  /**
   * API 클라이언트 신규 등록 요청(파트너/앱/온보딩 등). client_name, contact_email,
   * public_key필수, description옵션. 활성화 기본 true. 생성 이벤트는 감사·증적 로그로 처리합니다.
   */
  export type ICreate = {
    /** 등록할 클라이언트 앱/파트너 이름(고유) */
    client_name: string;

    /** 관리자/운영 연락용 이메일(UNIQUE) */
    contact_email: string;

    /** 서명/인증용 공개키(X.509 등), 옵션 */
    public_key?: string;

    /** 사업,파트너 설명 */
    description?: string;
  };

  /**
   * API 클라이언트 메타데이터, 활성/비활성(삭제/복구), 설명·연락처·공개키 등 일부 필드 변경 요청 타입입니다.
   * client_name, id는 불변/수정불가.
   */
  export type IUpdate = {
    /** 클라이언트 설명 갱신 */
    description?: string;

    /** 메일주소 변경 */
    contact_email?: string;

    /** 공개키(교체시) */
    public_key?: string;

    /** 활성/비활성(soft delete 등) */
    is_active?: boolean;
  };
}

