import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IApiClients } from "@ORGANIZATION/PROJECT-api/lib/structures/IApiClients";

/**
 * E2E test for updating an API client record via PUT.
 *
 * Validates that API clients can be updated with allowed metadata (such as rotating public key, changing contact email, updating description, and toggling activation), and that business rules and validation are properly enforced. Negative cases for duplicating unique data or invalid modifications are confirmed.
 *
 * Scenario Steps:
 * 1. Create a new API client (dependency setup).
 * 2. Update allowed fields (description, contact_email, public_key, is_active) and verify the changes persisted.
 * 3. Attempt a valid contact_email change to another unique value and verify.
 * 4. Attempt to update with duplicate or invalid contact_email and verify error is raised.
 * 5. Attempt to change immutable fields (client_name, id) and verify that they are not changed.
 */
export async function test_api_apiOmnichannel_test_update_api_client_metadata_and_invalid_cases(connection: api.IConnection) {
  // 1. Create baseline API client
  const initialClient = await api.functional.apiOmnichannel.apiClients.post(connection, {
    body: {
      client_name: RandomGenerator.alphaNumeric(12),
      contact_email: RandomGenerator.alphabets(8) + "@bizdomain.com",
      public_key: RandomGenerator.alphaNumeric(32),
      description: RandomGenerator.paragraph()(1),
    },
  });
  typia.assert(initialClient);

  // 2. Update mutable fields (description, public_key, contact_email, is_active)
  const newDescription = RandomGenerator.paragraph()(1);
  const newPublicKey = RandomGenerator.alphaNumeric(32);
  const newEmail = RandomGenerator.alphabets(10) + "@partner.com";
  const updateResult = await api.functional.apiOmnichannel.apiClients.putById(connection, {
    id: initialClient.id,
    body: {
      description: newDescription,
      public_key: newPublicKey,
      contact_email: newEmail,
      is_active: !initialClient.is_active,
    },
  });
  typia.assert(updateResult);
  TestValidator.equals("description")(newDescription)(updateResult.description);
  TestValidator.equals("public_key")(newPublicKey)(updateResult.public_key);
  TestValidator.equals("contact_email")(newEmail)(updateResult.contact_email);
  TestValidator.equals("is_active")(!initialClient.is_active)(updateResult.is_active);
  TestValidator.equals("client_name unmodified")(initialClient.client_name)(updateResult.client_name);
  TestValidator.equals("id")(initialClient.id)(updateResult.id);

  // 3. Valid contact_email change again
  const altEmail = RandomGenerator.alphabets(8) + "@unique.com";
  const updateRes2 = await api.functional.apiOmnichannel.apiClients.putById(connection, {
    id: initialClient.id,
    body: { contact_email: altEmail },
  });
  typia.assert(updateRes2);
  TestValidator.equals("contact_email")(altEmail)(updateRes2.contact_email);

  // 4. Attempt duplicate contact_email (should trigger uniqueness error)
  // Create another client with a conflicting email
  const secondClient = await api.functional.apiOmnichannel.apiClients.post(connection, {
    body: {
      client_name: RandomGenerator.alphaNumeric(10),
      contact_email: RandomGenerator.alphabets(8) + "@dup.com",
      public_key: RandomGenerator.alphaNumeric(30),
      description: RandomGenerator.paragraph()(1),
    },
  });
  typia.assert(secondClient);
  // Try to update its contact_email to that of the first client
  await TestValidator.error("duplicate contact_email must fail async")(async () => {
    await api.functional.apiOmnichannel.apiClients.putById(connection, {
      id: secondClient.id,
      body: { contact_email: altEmail },
    });
  });

  // 5. Attempt to update immutable fields (should ignore or error: id, client_name cannot change)
  await api.functional.apiOmnichannel.apiClients.putById(connection, {
    id: initialClient.id,
    body: {
      client_name: RandomGenerator.alphaNumeric(10), // should be ignored
      id: typia.random<string & tags.Format<"uuid">>(), // should be ignored
      description: "Attempt changing immutable fields.",
    } as any, // forcibly included for negative test, server ignores or errors
  });
  // Confirm in DB (via GET or relying on updateRes2), name/id not changed
  const unchanged = await api.functional.apiOmnichannel.apiClients.putById(connection, {
    id: initialClient.id,
    body: {},
  });
  typia.assert(unchanged);
  TestValidator.equals("client_name unchanged")(initialClient.client_name)(unchanged.client_name);
  TestValidator.equals("id unchanged")(initialClient.id)(unchanged.id);
}

