import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IApiClients } from "@ORGANIZATION/PROJECT-api/lib/structures/IApiClients";

/**
 * Validates the soft deletion (logical deletion) process for API client records in the Omnichannel platform.
 *
 * This test ensures that when an API client is deleted:
 *  - The client is no longer returned in active/normal queries
 *  - The record remains available in audit logs/history (not physically deleted)
 *  - Attempts to delete a non-existent or already-deleted client yield correct error responses
 *
 * Steps:
 * 1. Create a new API client entry (prerequisite)
 * 2. Soft-delete (logically delete) the entry via DELETE endpoint
 * 3. Assert that the response marks the client as deactivated and sets a non-null deleted_at timestamp
 * 4. (Assuming there is an endpoint for active/normal queries) Confirm the deleted client does not appear in normal/active queries
 * 5. (Assuming there is an endpoint or mechanism for audit logs) Confirm the record remains present in historical/audit logs
 * 6. Attempt to delete the same client again, and assert the system returns an appropriate error (e.g., not-found, already-deleted)
 * 7. Attempt to delete a totally random/non-existent client id and assert the system returns the correct error (not-found)
 *
 * Business Rationales:
 * - Ensures compliance with evidence-retention and audit requirements
 * - Verifies robust error handling for improper deletions
 * - Prevents accidental or unauthorized hard-deletion of registry records
 */
export async function test_api_apiOmnichannel_test_soft_delete_api_client_and_error_on_missing(
  connection: api.IConnection,
) {
  // Step 1: Create a new API client for test
  const clientCreateInput = {
    client_name: RandomGenerator.alphaNumeric(12),
    contact_email: RandomGenerator.email(),
    description: RandomGenerator.paragraph()(),
    public_key: RandomGenerator.alphaNumeric(64),
  } satisfies IApiClients.ICreate;
  const client = await api.functional.apiOmnichannel.apiClients.post(connection, { body: clientCreateInput });
  typia.assert(client);

  // Step 2: Delete the client (soft delete)
  const deleted = await api.functional.apiOmnichannel.apiClients.eraseById(connection, { id: client.id });
  typia.assert(deleted);
  TestValidator.equals("is_active after delete")(false)(deleted.is_active);
  if (!deleted.deleted_at) {
    throw new Error("deleted_at should be set after deletion");
  }

  // Step 3: Attempt to delete already deleted client
  await TestValidator.error("already-deleted client deletion should error")(async () => {
    await api.functional.apiOmnichannel.apiClients.eraseById(connection, { id: client.id });
  });

  // Step 4: Attempt to delete a non-existent client
  await TestValidator.error("non-existent client deletion should error")(async () => {
    await api.functional.apiOmnichannel.apiClients.eraseById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
    });
  });

  // NOTE: Placeholder for audit log/history/active-client validations
  // (Would require additional list/get endpoints or access to internal query logic)
}

