import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IApiClients } from "@ORGANIZATION/PROJECT-api/lib/structures/IApiClients";
import type { IApiTokens } from "@ORGANIZATION/PROJECT-api/lib/structures/IApiTokens";
import type { IPageIApiTokens } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIApiTokens";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IApiToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IApiToken";

/**
 * Validate searching API access tokens (api_tokens) with and without using filter criteria.
 *
 * This scenario tests the token search endpoint's filtering and pagination, including:
 * 1. That tokens are returned only for active (non-revoked) tokens by default.
 * 2. That filter criteria for api_client_id, scope, and active/revoked status work correctly.
 * 3. That pagination metadata (current, limit, records, pages) make sense.
 *
 * Steps:
 * 1. Create a new API client (to ensure isolation and a unique client for this test)
 * 2. Issue multiple tokens for this client, with at least one being active and (optionally) one revoked (simulate revocation if possible)
 * 3. Search for tokens using no filter criteria – validate only active tokens are in the results and data corresponds to created tokens.
 * 4. Search for tokens using explicit filter: api_client_id (should only return tokens for that client)
 * 5. Search for tokens using filter: active=false (should return revoked tokens if supported)
 * 6. Confirm pagination information and data counts are consistent for all above steps.
 */
export async function test_api_apiomnichannel_test_list_search_api_tokens_with_and_without_filters(
  connection: api.IConnection,
) {
  // 1. Create a new API client
  const clientCreate: IApiClients.ICreate = {
    client_name: RandomGenerator.alphaNumeric(10),
    contact_email: RandomGenerator.alphabets(8) + "@test.local",
    public_key: undefined,
    description: "E2E test client, created at " + new Date().toISOString(),
  };
  const client = await api.functional.apiOmnichannel.apiClients.post(connection, { body: clientCreate });
  typia.assert(client);

  // 2. Issue multiple API tokens for this client
  const now = new Date();
  const tokenActive = await api.functional.apiOmnichannel.apiTokens.post(connection, {
    body: {
      api_client_id: client.id,
      scope: "default",
      issued_at: now.toISOString(),
      expires_at: new Date(now.getTime() + 1000 * 60 * 60 * 24 * 7).toISOString(),
    } satisfies IApiToken.ICreate,
  });
  typia.assert(tokenActive);

  // (Optionally) Issue a second, soon-to-expire token
  const tokenExpiresSoon = await api.functional.apiOmnichannel.apiTokens.post(connection, {
    body: {
      api_client_id: client.id,
      scope: "default",
      issued_at: now.toISOString(),
      expires_at: new Date(now.getTime() + 1000 * 60).toISOString(), // expires in 1 minute
    } satisfies IApiToken.ICreate,
  });
  typia.assert(tokenExpiresSoon);

  // (Optionally) Simulate revoked token - not possible via API (if not supported, skip this)
  // Otherwise, tokens start as active (non-revoked)

  // 3. Search for tokens WITHOUT filter criteria (should return only active tokens)
  const resultDefault = await api.functional.apiOmnichannel.apiTokens.patch(connection, {
    body: {},
  });
  typia.assert(resultDefault);
  for (const t of resultDefault.data) {
    if (t.revoked_at) {
      throw new Error("Found revoked token in default (active tokens) search");
    }
  }

  // 4. Search for tokens using api_client_id filter
  const resultByClient = await api.functional.apiOmnichannel.apiTokens.patch(connection, {
    body: { api_client_id: client.id },
  });
  typia.assert(resultByClient);
  for (const t of resultByClient.data) {
    TestValidator.equals("api_client_id matches filtered client")(client.id)(t.api_client_id);
  }

  // 5. Search for tokens with active=false (should return no records since we have no revoked tokens)
  const resultRevoked = await api.functional.apiOmnichannel.apiTokens.patch(connection, {
    body: { active: false },
  });
  typia.assert(resultRevoked);
  TestValidator.equals("No revoked tokens yet")(0)(resultRevoked.data.length);

  // 6. Confirm pagination info
  for (const r of [resultDefault, resultByClient, resultRevoked]) {
    TestValidator.predicate("valid pagination current page")(r.pagination.current >= 1);
    TestValidator.predicate("valid pagination limit")(r.pagination.limit >= 1);
    TestValidator.predicate("pagination records >= data count")(r.pagination.records >= r.data.length);
    TestValidator.predicate("pagination pages >= 1")(r.pagination.pages >= 1);
  }
}

