import { NestiaSimulator } from "@nestia/fetcher/lib/NestiaSimulator";

import { IApiClients } from "../../../structures/IApiClients";

/**
 * Create new API client record in API_Omnichannel api_clients table.
 *
 * Creates a new API client entry as per omni-channel extensibility and partner
 * onboarding requirements. Request must conform to IApiClients.ICreate schema
 * and include client_name, contact_email, public_key/certificate, activation
 * status, and other core metadata. After successful validation and registry
 * insert, a new API client record is persisted with evidence-grade change
 * audit. Only privileged admin or controlled automation roles may perform this
 * operation. All attempts and results are logged, supporting explainability,
 * attack investigation, and compliance reporting. Related GET/PUT/DELETE
 * endpoints support further management of the registered client. Error
 * responses detail any validation or policy error. Responses return the
 * registered client record for use in integration/channel setup.
 *
 * @param props.connection
 * @param props.body API client metadata for onboarding and registry.
 * @path /apiOmnichannel/apiClients
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export async function post(
  connection: IConnection,
  props: post.Props,
): Promise<post.Response> {
  return !!connection.simulate
    ? post.simulate(connection, props)
    : PlainFetcher.fetch(
        {
          ...connection,
          headers: {
            ...connection.headers,
            "Content-Type": "application/json",
          },
        },
        {
          ...post.METADATA,
          path: post.path(),
          status: null,
        },
        props.body,
      );
}
export namespace post {
  export type Props = {
    /** API client metadata for onboarding and registry. */
    body: IApiClients.ICreate;
  };
  export type Body = IApiClients.ICreate;
  export type Response = IApiClients;

  export const METADATA = {
    method: "POST",
    path: "/apiOmnichannel/apiClients",
    request: {
      type: "application/json",
      encrypted: false,
    },
    response: {
      type: "application/json",
      encrypted: false,
    },
  } as const;

  export const path = () => "/apiOmnichannel/apiClients";
  export const random = (g?: Partial<typia.IRandomGenerator>): IApiClients =>
    typia.random<IApiClients>(g);
  export const simulate = (
    connection: IConnection,
    props: post.Props,
  ): Response => {
    const assert = NestiaSimulator.assert({
      method: METADATA.method,
      host: connection.host,
      path: post.path(),
      contentType: "application/json",
    });
    try {
      assert.body(() => typia.assert(props.body));
    } catch (exp) {
      if (!typia.is<HttpError>(exp)) throw exp;
      return {
        success: false,
        status: exp.status,
        headers: exp.headers,
        data: exp.toJSON().message,
      } as any;
    }
    return random(
      "object" === typeof connection.simulate && null !== connection.simulate
        ? connection.simulate
        : undefined,
    );
  };
}

