import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IApiClients } from "@ORGANIZATION/PROJECT-api/lib/structures/IApiClients";
import type { IApiTokens } from "@ORGANIZATION/PROJECT-api/lib/structures/IApiTokens";
import type { IApiToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IApiToken";

/**
 * API 토큰(Access Token) 상세 정보 조회 및 예외 처리 검증 E2E 테스트
 *
 * 이 테스트는 정상적으로 발급된 API 토큰의 상세 정보를 ID로 조회하는 정상 흐름과,
 * 잘못된(존재하지 않는) ID, 혹은 폐기(취소/만료/비활성화)된 토큰 ID로 조회할 때
 * 올바른 에러 및 상태 코드가 반환되는지를 검증합니다.
 *
 * 1. API 클라이언트 신규 생성 (등록 및 온보딩)
 * 2. 위 클라이언트로 API 토큰 정상 발급 (정상 토큰 생성)
 * 3. 정상 발급 토큰의 ID로 상세정보 GET (정상적 상세 정보 반환)
 * 4. 무작위(존재하지 않는) UUID로 상세정보 GET 시도 (404 Not Found 등 올바른 예외 확인)
 * 5. 토큰의 상태를 폐기(만료/비활성)로 만든 후 해당 ID로 상세정보 GET 시도 (폐기/비활성화 예외 확인)
 */
export async function test_api_apiomnichannel_test_get_api_token_detail_and_error_on_invalid_or_revoked(
  connection: api.IConnection,
) {
  // 1. 신규 API 클라이언트 등록 (필수 정보 포함)
  const newClient = await api.functional.apiOmnichannel.apiClients.post(
    connection,
    {
      body: {
        client_name: RandomGenerator.alphabets(8),
        contact_email: typia.random<string & tags.Format<"email">>(),
        public_key: RandomGenerator.alphaNumeric(32),
        description: RandomGenerator.paragraph()(),
      },
    },
  );
  typia.assert(newClient);

  // 2. 발급된 클라이언트로 API 토큰 생성
  const now = new Date();
  const expires = new Date(now);
  expires.setDate(expires.getDate() + 7); // 1주일 후 만료

  const newToken = await api.functional.apiOmnichannel.apiTokens.post(
    connection,
    {
      body: {
        api_client_id: newClient.id,
        scope: "read:all",
        issued_at: now.toISOString(),
        expires_at: expires.toISOString(),
      },
    },
  );
  typia.assert(newToken);

  // 3. 정상 발급 토큰 상세조회
  const tokenDetail = await api.functional.apiOmnichannel.apiTokens.getById(
    connection,
    { id: newToken.id },
  );
  typia.assert(tokenDetail);
  TestValidator.equals("token id")(newToken.id)(tokenDetail.id);
  TestValidator.equals("api_client_id")(newClient.id)(tokenDetail.api_client_id);

  // 4. 존재하지 않는 임의의 UUID로 상세조회시 NotFound 검증
  const randomUUID = typia.random<string & tags.Format<"uuid">>();
  TestValidator.error("not found for invalid token id")(() =>
    api.functional.apiOmnichannel.apiTokens.getById(connection, { id: randomUUID }),
  );

  // 5. (폐기/비활성화 시나리오) - 토큰을 만료시키는 추가 API가 없으므로 토큰 생성 시 만료시간을 과거로 지정하여 검증
  const expiredToken = await api.functional.apiOmnichannel.apiTokens.post(
    connection,
    {
      body: {
        api_client_id: newClient.id,
        scope: "read:all",
        issued_at: now.toISOString(),
        expires_at: new Date(now.getTime() - 24 * 60 * 60 * 1000).toISOString(), // 전날로 만료
      },
    },
  );
  typia.assert(expiredToken);
  TestValidator.error("get by expired token id should fail")(() =>
    api.functional.apiOmnichannel.apiTokens.getById(connection, { id: expiredToken.id }),
  );
}

