import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IApiClients } from "@ORGANIZATION/PROJECT-api/lib/structures/IApiClients";
import type { IApiToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IApiToken";

/**
 * Validate token issuance for API clients (positive and negative scenarios).
 *
 * This test confirms that the /apiOmnichannel/apiTokens POST endpoint correctly issues tokens for valid API clients, rejects
token issuance for invalid/nonexistent clients, and returns appropriate validation errors for malformed payloads.
 *
 * Steps:
 * 1. Register a valid API client using /apiOmnichannel/apiClients POST.
 * 2. Issue a token for the registered client: verify token is created, fields are correct, and token_value is present.
 * 3. (Negative) Attempt to issue a token referencing a non-existent client id: expect business validation error.
 * 4. (Negative) Attempt to issue a token with an invalid payload (missing required fields or malformed scope): expect validation error.
 */
export async function test_api_apiomnichannel_test_issue_api_token_for_valid_and_invalid_clients(
  connection: api.IConnection,
) {
  // 1. Create a valid API client
  const clientInput: IApiClients.ICreate = {
    client_name: RandomGenerator.alphaNumeric(10),
    contact_email: RandomGenerator.email(),
    public_key: RandomGenerator.alphaNumeric(48),
    description: RandomGenerator.paragraph()(1),
  };
  const client = await api.functional.apiOmnichannel.apiClients.post(connection, {
    body: clientInput,
  });
  typia.assert(client);

  // 2. Issue a token for this valid client
  const now = new Date();
  const issuedAt = now.toISOString();
  const expiresAt = new Date(now.getTime() + 1000 * 60 * 60 * 24 * 30).toISOString(); // +30d
  const tokenInput: IApiToken.ICreate = {
    api_client_id: client.id,
    scope: "read:all", // basic/valid sample scope
    issued_at: issuedAt,
    expires_at: expiresAt,
  };
  const token = await api.functional.apiOmnichannel.apiTokens.post(connection, {
    body: tokenInput,
  });
  typia.assert(token);
  TestValidator.equals("token.api_client_id")(client.id)(token.api_client_id);
  TestValidator.equals("token.scope")("read:all")(token.scope);

  // 3. Negative: Attempt to issue a token for non-existent client id
  await TestValidator.error("token issuance fails for non-existent client id")(() =>
    api.functional.apiOmnichannel.apiTokens.post(connection, {
      body: {
        api_client_id: typia.random<string & tags.Format<"uuid">>(), // unlikely to exist
        scope: "read:all",
        issued_at: issuedAt,
        expires_at: expiresAt,
      },
    }),
  );

  // 4. Negative: Attempt invalid payload (missing required field `scope`)
  await TestValidator.error("token issuance fails with invalid payload")(() =>
    api.functional.apiOmnichannel.apiTokens.post(connection, {
      body: {
        api_client_id: client.id,
        // Missing scope
        issued_at: issuedAt,
        expires_at: expiresAt,
      } as any, // skip, only test with type-valid values
    }),
  );
}

