import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IApiClients } from "@ORGANIZATION/PROJECT-api/lib/structures/IApiClients";
import type { IApiToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IApiToken";

/**
 * Update metadata (such as expiration or scope) of an existing API token and verify changes.
 * - Scenario includes both successful update of an active token and guarded failure:
 *   - Attempting to update a revoked token should fail
 *   - Attempting to update a non-existent token should also fail
 *
 * Test flow:
 * 1. Create an API client.
 * 2. Issue a new API token for that client (active, not revoked).
 * 3. Update the token: change its expiration (expires_at) and/or scope
 * 4. Fetch/inspect the token to confirm changes took effect (wherever possible).
 * 5. Revoke the token by setting revoked_at, then attempt a further update; expect failure.
 * 6. Attempt to update a random (non-existent) token; expect failure or not found error.
 */
export async function test_api_apiOmnichannel_test_update_api_token_metadata_and_fail_on_revoked_nonexistent(connection: api.IConnection) {
  // 1. Create a new API client
  const client = await api.functional.apiOmnichannel.apiClients.post(connection, {
    body: {
      client_name: RandomGenerator.alphaNumeric(8),
      contact_email: typia.random<string & tags.Format<"email">>(),
      public_key: RandomGenerator.alphabets(32),
      description: RandomGenerator.paragraph()(1),
    } satisfies IApiClients.ICreate,
  });
  typia.assert(client);

  // 2. Issue a new token for that client
  const issued_at = new Date().toISOString();
  const expires_at = new Date(Date.now() + 7200 * 1000).toISOString(); // +2h
  const token = await api.functional.apiOmnichannel.apiTokens.post(connection, {
    body: {
      api_client_id: client.id,
      scope: "read:all",
      issued_at,
      expires_at,
    } satisfies IApiToken.ICreate,
  });
  typia.assert(token);
  TestValidator.equals("api_client_id")(client.id)(token.api_client_id);
  TestValidator.equals("revoked_at not set")(undefined)(token.revoked_at);

  // 3. Update the token metadata (extend expires_at & change scope)
  const new_scope = "write:all";
  const new_expires_at = new Date(Date.now() + 14400 * 1000).toISOString(); // +4h
  const updated = await api.functional.apiOmnichannel.apiTokens.putById(connection, {
    id: token.id,
    body: {
      scope: new_scope,
      expires_at: new_expires_at,
    } satisfies IApiToken.IUpdate,
  });
  typia.assert(updated);
  TestValidator.equals("token.id")(token.id)(updated.id);
  TestValidator.equals("new scope")(new_scope)(updated.scope);
  TestValidator.equals("new expires_at")(new_expires_at)(updated.expires_at);

  // 4. Revoke the token and verify update fails
  const revoked = await api.functional.apiOmnichannel.apiTokens.putById(connection, {
    id: token.id,
    body: {
      revoked_at: new Date().toISOString(),
    } satisfies IApiToken.IUpdate,
  });
  typia.assert(revoked);
  TestValidator.equals("revoked id")(token.id)(revoked.id);
  TestValidator.predicate("revoked_at is set")(!!revoked.revoked_at);

  // Now, attempt to update a revoked token → expect an error
  await TestValidator.error("update of revoked token must fail")(async () => {
    await api.functional.apiOmnichannel.apiTokens.putById(connection, {
      id: token.id,
      body: {
        scope: "should-not-work",
      } satisfies IApiToken.IUpdate,
    });
  });

  // 5. Update a non-existent (random) token ID → expect error
  await TestValidator.error("update of non-existent token")(async () => {
    await api.functional.apiOmnichannel.apiTokens.putById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
      body: {
        scope: "random-updated",
      } satisfies IApiToken.IUpdate,
    });
  });
}

