  const issued_at = new Date().toISOString();
  const expires_at = new Date(Date.now() + 3600 * 1000).toISOString(); // +1h
  const token = await api.functional.apiOmnichannel.apiTokens.post(connection, {
    body: {
      api_client_id: client.id,
      scope: "read:all",
      issued_at,
      expires_at,
    } satisfies IApiToken.ICreate,
  });
  typia.assert(token);
  TestValidator.equals("api_client_id")(client.id)(token.api_client_id);
  TestValidator.equals("revoked_at not set")(undefined)(token.revoked_at);

  // 3. Update the token's metadata: extend expires_at, change scope
  const new_scope = "write:all";
  const new_expires_at = new Date(Date.now() + 3 * 3600 * 1000).toISOString(); // +3h
  const updated = await api.functional.apiOmnichannel.apiTokens.putById(connection, {
    id: token.id,
    body: {
      scope: new_scope,
      expires_at: new_expires_at,
    } satisfies IApiToken.IUpdate,
  });
  typia.assert(updated);
  TestValidator.equals("token.id")(token.id)(updated.id);
  TestValidator.equals("scope updated")(new_scope)(updated.scope);
  TestValidator.equals("expires_at updated")(new_expires_at)(updated.expires_at);

  // 4. Revoke the token by setting revoked_at
