import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IApiClients } from "@ORGANIZATION/PROJECT-api/lib/structures/IApiClients";
import type { IApiToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IApiToken";

/**
 * Test the revocation of API tokens, both successful and error paths.
 *
 * 1. Create an API client (to own the token).
 * 2. Issue a new API token for that client (to be later revoked).
 * 3. Revoke the API token (using its id) – assert successful revocation.
 * 4. Confirm that revoking the same token again throws an appropriate error (already revoked).
 * 5. Try revoking a random/nonexistent token id – confirm correct error is returned.
 * 6. (Optional/if supported): Check the token no longer shows up in an active tokens list or cannot be used for authentication.
 */
export async function test_api_apiOmnichannel_test_revoke_api_token_and_error_on_already_revoked_nonexistent(connection: api.IConnection) {
  // 1. Create an API client
  const apiClient = await api.functional.apiOmnichannel.apiClients.post(connection, {
    body: {
      client_name: RandomGenerator.alphaNumeric(12),
      contact_email: RandomGenerator.alphabets(8)+"@test.com",
      public_key: RandomGenerator.alphaNumeric(16),
      description: RandomGenerator.paragraph()(1),
    } satisfies IApiClients.ICreate
  });
  typia.assert(apiClient);

  // 2. Issue a token for the client
  const expiresAt = new Date(Date.now() + 24*60*60*1000).toISOString();
  const issuedAt = new Date().toISOString();
  const token = await api.functional.apiOmnichannel.apiTokens.post(connection, {
    body: {
      api_client_id: apiClient.id,
      scope: "read:all",
      issued_at: issuedAt,
      expires_at: expiresAt,
    } satisfies IApiToken.ICreate,
  });
  typia.assert(token);

  // 3. Revoke the token
  const revokedToken = await api.functional.apiOmnichannel.apiTokens.eraseById(connection, { id: token.id });
  typia.assert(revokedToken);
  // Token should now have revoked_at set
  TestValidator.predicate("revoked_at is set after successful revoke")(!!revokedToken.revoked_at);

  // 4. Try revoking again (should error)
  await TestValidator.error("Revoking already revoked token should error")(async () => {
    await api.functional.apiOmnichannel.apiTokens.eraseById(connection, { id: token.id });
  });

  // 5. Try revoking a non-existent token (should error)
  await TestValidator.error("Revoking nonexistent token id should error")(async () => {
    await api.functional.apiOmnichannel.apiTokens.eraseById(connection, { id: typia.random<string & tags.Format<"uuid">>() });
  });

  // (Optional) 6. If there is an endpoint to list active tokens, could check that this token no longer appears
}

