import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IApiClients } from "@ORGANIZATION/PROJECT-api/lib/structures/IApiClients";
import type { IApiToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IApiToken";

/**
 * Test the revocation of API tokens, including success and error handling.
 *
 * This validates that tokens can be revoked (soft-deleted), that revoked tokens are marked as such, and that attempts to revoke an already-revoked or nonexistent token produce correct errors.
 *
 * 1. Create an API client for ownership of the token.
 * 2. Issue a new API token for that client.
 * 3. Revoke the API token (should succeed and set revoked_at).
 * 4. Confirm that revocation of the same token again returns an error (already revoked).
 * 5. Try to revoke a random UUID (nonexistent token) and validate that a proper error occurs.
 */
export async function test_api_apiOmnichannel_test_revoke_api_token_and_error_on_already_revoked_nonexistent(
  connection: api.IConnection,
) {
  // 1. Create an API client (to issue a token for)
  const apiClient = await api.functional.apiOmnichannel.apiClients.post(connection, {
    body: {
      client_name: RandomGenerator.alphaNumeric(12),
      contact_email: `${RandomGenerator.alphabets(8)}@test.com`,
      public_key: RandomGenerator.alphaNumeric(16),
      description: RandomGenerator.paragraph()(1),
    } satisfies IApiClients.ICreate,
  });
  typia.assert(apiClient);

  // 2. Issue a new API token
  const now = new Date();
  const issuedAt = now.toISOString();
  const expiresAt = new Date(now.getTime() + 24 * 60 * 60 * 1000).toISOString();
  const token = await api.functional.apiOmnichannel.apiTokens.post(connection, {
    body: {
      api_client_id: apiClient.id,
      scope: "read:all",
      issued_at: issuedAt,
      expires_at: expiresAt,
    } satisfies IApiToken.ICreate,
  });
  typia.assert(token);

  // 3. Revoke the token successfully
  const revokedToken = await api.functional.apiOmnichannel.apiTokens.eraseById(connection, {
    id: token.id,
  });
  typia.assert(revokedToken);
  // Ensure that revoked_at timestamp is set
  TestValidator.predicate("revoked_at should be set after revoke")(!!revokedToken.revoked_at);

  // 4. Attempt to revoke the already-revoked token (should error)
  await TestValidator.error("Revoking an already revoked token returns error")(
    async () => {
      await api.functional.apiOmnichannel.apiTokens.eraseById(connection, {
        id: token.id,
      });
    },
  );

  // 5. Attempt to revoke a completely random token id (should error)
  await TestValidator.error("Revoking nonexistent token returns error")(
    async () => {
      await api.functional.apiOmnichannel.apiTokens.eraseById(connection, {
        id: typia.random<string & tags.Format<"uuid">>(),
      });
    },
  );

  // (If there were a list endpoint, would check the token is gone from there)
}

