 * 필터 조건별 동작을 확인하며, evidence(감사 레코드) 정보가 정확히 모두 포함되는지,
 * 정렬이 올바른지, no result(검색결과 없음), 단건, 그리고 pagination edge cases(페이징 에지)까지 모두 검증합니다.
 *
 * 단계:
 * 1. 다양한 속성의 감사 레코드를 5개 등록한다 (api_client_id, api_token_id, http_method, endpoint, status_code 등이 서로 다르게)
 * 2. 각각의 단일 속성 및 조합 필터로 API를 검색하여 결과가 정확히 필터링되는지 검증한다
 * 3. 존재하지 않는 값을 필터로 넣으면 결과가 비어 있음을 확인한다
 * 4. 페이징 및 정렬: limit, page 조건을 달리하여 응답 pagination 정보와 정렬 순서 검사
 * 5. (각 케이스별) 응답 data의 각 element마다 evidence(모든 필드)가 요구 형식에 맞는지 typia.assert를 통해 검증한다
 */
export async function test_api_apiOmnichannel_test_list_api_audits_with_various_filters_and_pagination(
  connection: api.IConnection,
) {
  // 1. 다양한 속성의 감사 레코드를 5개 등록
  const audits: IApiAudit[] = [];
  const baseClientId = typia.random<string & tags.Format<"uuid">>();
  const baseTokenId = typia.random<string & tags.Format<"uuid">>();
  const baseActorId = typia.random<string & tags.Format<"uuid">>();

  for (let i = 0; i < 5; ++i) {
    const audit = await api.functional.apiOmnichannel.apiAudits.post(connection, {
      body: {
        api_client_id: i % 2 === 0 ? baseClientId : typia.random<string & tags.Format<"uuid">>(),
        api_token_id: i % 3 === 0 ? baseTokenId : typia.random<string & tags.Format<"uuid">>(),
        actor_id: i < 3 ? baseActorId : typia.random<string & tags.Format<"uuid">>(),
        endpoint: `/api/test/${i}`,
        http_method: i % 2 === 0 ? "GET" : "POST",
        is_success: i % 2 === 0,
        status_code: 200 + i,
        created_at: new Date(Date.now() + i * 1000).toISOString(),
      } as IApiAudit.ICreate,
    });
    audits.push(audit);
  }

  // 2. 각각의 단일 속성 필터 및 조합 케이스로 검색/검증
  // (api_client_id, api_token_id, actor_id, endpoint, http_method, status_code, is_success)
  for (const [key, value] of Object.entries({
    api_client_id: baseClientId,
    api_token_id: baseTokenId,
    actor_id: baseActorId,
    http_method: "POST",
    is_success: false,
    status_code: 202,
    endpoint: audits[2].endpoint,
  })) {
    const filter: Record<string, unknown> = { [key]: value };
    const res = await api.functional.apiOmnichannel.apiAudits.patch(connection, {
      body: filter as IApiAudit.IRequest,
    });
    typia.assert(res);
    // 응답 내 전체 evidence 모두 필드타입 검증
    res.data.forEach((item) => typia.assert(item));
    // 해당 속성별 값 필터
    res.data.forEach((item) => {
      if (key === "status_code") {
        TestValidator.equals(key)(value)(item[key]);
      } else {
        TestValidator.equals(key)(value)(item[key as keyof typeof item]);
      }
    });
  }

  // 3. 존재하지 않는 값 필터 시 결과 없음 확인
  const noResult1 = await api.functional.apiOmnichannel.apiAudits.patch(connection, {
    body: { api_client_id: typia.random<string & tags.Format<"uuid">>() } as IApiAudit.IRequest,
  });
  typia.assert(noResult1);
  TestValidator.equals("result empty with random client_id")(0)(noResult1.data.length);

  // 4. 페이징 및 정렬 동작 체크
  // 모든 감사이력을 limit 2, page 2로(3번째부터), 시간 역순 정렬로 요청
  const paged = await api.functional.apiOmnichannel.apiAudits.patch(connection, {
    body: {
      page: 2,
      limit: 2,
    } as IApiAudit.IRequest,
  });
  typia.assert(paged);
  TestValidator.equals("page 2 of limit 2")(2)(paged.pagination.current);
  TestValidator.equals("limit 2")(2)(paged.pagination.limit);
  TestValidator.equals("length")(2)(paged.data.length);

  // 5. 단건 필터 확인
  const single = await api.functional.apiOmnichannel.apiAudits.patch(connection, {
    body: { id: audits[0].id } as any,
  });
  typia.assert(single);
  TestValidator.equals("found single result")(1)(single.data.length);
  TestValidator.equals("id matches")(audits[0].id)(single.data[0].id);
}

