import { IConnection, HttpError } from "@nestia/fetcher";
import { PlainFetcher } from "@nestia/fetcher/lib/PlainFetcher";
import typia, { tags } from "typia";
import { NestiaSimulator } from "@nestia/fetcher/lib/NestiaSimulator";

import { IApiAudit } from "../../../structures/IApiAudit";

/**
 * Get a single API audit record (api_audits table) by ID.
 *
 * This endpoint returns the complete information for an API audit log entry
 * specified by its unique ID, referencing activity across omnichannel API
 * usage, including the actor, API client/token, endpoint, method, status,
 * request/response hashes, and associated evidence. The audit entry is critical
 * for forensic analysis, regulatory reporting, incident review, and operational
 * compliance.
 *
 * The operation validates existence of the ID and returns all metadata fields
 * without exposing any sensitive request/response bodies, complying with
 * security and privacy best practices. Results are directly derived from the
 * api_audits table as per the schema.
 *
 * @param props.connection
 * @param props.id The unique ID of the API audit entry to retrieve.
 * @path /apiOmnichannel/apiAudits/:id
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export async function getById(
  connection: IConnection,
  props: getById.Props,
): Promise<getById.Response> {
  return !!connection.simulate
    ? getById.simulate(connection, props)
    : PlainFetcher.fetch(
        {
          ...connection,
          headers: {
            ...connection.headers,
            "Content-Type": "application/json",
          },
        },
        {
          ...getById.METADATA,
          path: getById.path(props),
          status: null,
        },
      );
}
export namespace getById {
  export type Props = {
    /** The unique ID of the API audit entry to retrieve. */
    id: string & tags.Format<"uuid">;
  };
  export type Response = IApiAudit;

  export const METADATA = {
    method: "GET",
    path: "/apiOmnichannel/apiAudits/:id",
    request: null,
    response: {
      type: "application/json",
      encrypted: false,
    },
  } as const;

  export const path = (props: Props) =>
    `/apiOmnichannel/apiAudits/${encodeURIComponent(props.id ?? "null")}`;
  export const random = (g?: Partial<typia.IRandomGenerator>): IApiAudit =>
    typia.random<IApiAudit>(g);
  export const simulate = (
    connection: IConnection,
    props: getById.Props,
  ): Response => {
    const assert = NestiaSimulator.assert({
      method: METADATA.method,
      host: connection.host,
      path: getById.path(props),
      contentType: "application/json",
    });
    try {
      assert.param("id")(() => typia.assert(props.id));
    } catch (exp) {
      if (!typia.is<HttpError>(exp)) throw exp;
      return {
        success: false,
        status: exp.status,
        headers: exp.headers,
        data: exp.toJSON().message,
      } as any;
    }
    return random(
      "object" === typeof connection.simulate && null !== connection.simulate
        ? connection.simulate
        : undefined,
    );
  };
}

/**
 * Manually create a new API audit entry (api_audits table).
 *
 * This operation creates an ad-hoc entry in the api_audits log, simulating or
 * manually registering an API event/action. This is generally reserved for
 * system processes, data imports, or retroactive compliance actions that
 * require augmenting the audit log with additional entries not directly tied to
 * API traffic.
 *
 * All standard validation and security controls apply. The operation must
 * validate the supplied references (api_client, token, etc.), timestamps, and
