 *
 * [절차 및 핵심 검증]
 * 1. 감사 evidence를 신규 생성한다 (apiAudits.post)
 * 2. 성공적으로 생성되면 반환된 id로 단건 조회(apiAudits.getById)를 수행한다
 *    - 필드: id, api_client_id, api_token_id, endpoint, http_method, actor_id, is_success, status_code, created_at 등 전체 evidence 정보 반환을 확인
 *    - 생성 결과 DTO와 getById 결과를 비교해 정확성 검증 (대소문자/공백/타임스탬프 등 올바른지 포함)
 * 3. 존재하지 않는 임의의 UUID로 조회를 시도해 404나 적절한 에러 핸들링(예외) 발생을 확인
 * 4. (시스템이 권한 체크를 한다면) 적절하지 않은 API 토큰/액터 등으로 접근 시, 403/401 등 error 처리 유효성도 확인
 */
export async function test_api_apiOmnichannel_test_get_api_audit_by_id_and_error_on_unauthorized_or_missing(
  connection: api.IConnection,
) {
  // 1. 감사 evidence 신규 생성 (적합한 IApiAudit.ICreate 사용)
  const createInput: IApiAudit.ICreate = {
    api_client_id: typia.random<string & tags.Format<"uuid">>(),
    api_token_id: typia.random<string & tags.Format<"uuid">>(),
    integration_channel_id: typia.random<string & tags.Format<"uuid">>(),
    endpoint: "/some/api/resource",
    http_method: "GET",
    actor_id: typia.random<string & tags.Format<"uuid">>(),
    is_success: true,
    status_code: 200,
    created_at: new Date().toISOString(),
    decision_log_id: typia.random<string>(),
    request_hash: typia.random<string>(),
    response_hash: typia.random<string>()
  };
  const created: IApiAudit = await api.functional.apiOmnichannel.apiAudits.post(connection, {
    body: createInput,
  });
  typia.assert(created);

  // 2. getById로 정상적으로 evidence 조회
  const fetched: IApiAudit = await api.functional.apiOmnichannel.apiAudits.getById(connection, {
    id: created.id,
  });
  typia.assert(fetched);
  // 주요 필드 값이 생성값과 일치하는지 확인
