 * 3. Attempt to POST with critical fields omitted or malformed (e.g., missing api_client_id, invalid http_method string, omitted status_code). Confirm that the API correctly rejects the request with validation errors.
 * 4. Cover edge cases for optional fields (e.g., providing integration_channel_id as null or omitting optional hashes) and verify the system accepts these.
 * 5. Confirm the audit evidence record links to the intended API client and endpoint, and that is_success and status_code reflect input values.
 */
export async function test_api_apiOmnichannel_test_create_api_audit_entry_success_and_fail_on_invalid_payload(
  connection: api.IConnection,
) {
  // 1. Prepare valid payload for API audit creation
  const validPayload: IApiAudit.ICreate = {
    api_client_id: typia.random<string & tags.Format<"uuid">>(),
    api_token_id: typia.random<string & tags.Format<"uuid">>(),
    integration_channel_id: typia.random<string & tags.Format<"uuid">>(),
    endpoint: "/some/api/path",
    http_method: "POST",
    actor_id: typia.random<string & tags.Format<"uuid">>(),
    decision_log_id: typia.random<string>(),
    request_hash: typia.random<string>(),
    response_hash: typia.random<string>(),
    is_success: true,
    status_code: 200,
    created_at: new Date().toISOString(),
  };

  // 2. Call the create API audit endpoint with valid payload
  const output = await api.functional.apiOmnichannel.apiAudits.post(connection, { body: validPayload });
  typia.assert(output);
  TestValidator.equals("endpoint")(validPayload.endpoint)(output.endpoint);
  TestValidator.equals("api_client_id")(validPayload.api_client_id)(output.api_client_id);
  TestValidator.equals("is_success")(validPayload.is_success)(output.is_success);
  TestValidator.equals("status_code")(validPayload.status_code)(output.status_code);

  // 3. Omit required field (api_client_id)
  const { api_client_id, ...payloadMissingClient } = validPayload;
  await TestValidator.error("Missing required api_client_id should fail")(() =>
    api.functional.apiOmnichannel.apiAudits.post(connection, { body: payloadMissingClient as any }),
  );

  // 4. Provide malformed http_method
  const payloadMalformedMethod = { ...validPayload, http_method: "INVALID_METHOD" };
  await TestValidator.error("Malformed http_method should fail")(() =>
    api.functional.apiOmnichannel.apiAudits.post(connection, { body: payloadMalformedMethod }),
  );

