  await TestValidator.error("Missing required status_code should fail")(() =>
    api.functional.apiOmnichannel.apiAudits.post(connection, { body: payloadMissingStatus as any }),
  );

  // 6. Optional fields: integration_channel_id as null, omit request/response_hash
  const payloadOptional: IApiAudit.ICreate = {
    ...validPayload,
    integration_channel_id: undefined,
    request_hash: undefined,
    response_hash: undefined,
  };
  const outputOptional = await api.functional.apiOmnichannel.apiAudits.post(connection, { body: payloadOptional });
  typia.assert(outputOptional);
  TestValidator.equals("integration_channel_id")(undefined)(outputOptional.integration_channel_id);
  TestValidator.equals("request_hash")(undefined)(outputOptional.request_hash);
  TestValidator.equals("response_hash")(undefined)(outputOptional.response_hash);
}

