import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IApiAudit } from "@ORGANIZATION/PROJECT-api/lib/structures/IApiAudit";

/**
 * Test updating allowed metadata fields in an existing API audit entry.
 *
 * This test verifies:
 * 1. That permitted/allowed metadata fields of an API audit record (such as request_hash, response_hash) can be updated by privileged operations.
 * 2. An update does not destroy the original audit evidence; response is consistent and correct.
 * 3. Attempts to update restricted/immutable fields (such as id, api_client_id, created_at, etc.) are appropriately rejected.
 *
 * Steps:
 * 1. Create an API audit record using the POST endpoint.
 * 2. Prepare a valid update payload, targeting allowed (mutable) fields (such as request_hash, response_hash, status_code, is_success).
 * 3. Perform the update via PUT /apiOmnichannel/apiAudits/{id}.
 * 4. Assert that the returned audit record reflects the updated metadata.
 * 5. Attempt to update immutable fields – in this schema, test an update with a changed 'id' or mismatched 'created_at', expecting error or rejection.
 * 6. Validate that audit evidence is preserved and append-only/business rules are respected.
 */
export async function test_api_apiAudits_test_update_api_audit_metadata_and_handle_restricted_fields(connection: api.IConnection) {
  // Step 1. Create a new audit record for the test
  const originalAudit = await api.functional.apiOmnichannel.apiAudits.post(connection, {
    body: {
      api_client_id: typia.random<string & tags.Format<"uuid">>(),
      api_token_id: typia.random<string & tags.Format<"uuid">>(),
      integration_channel_id: typia.random<string & tags.Format<"uuid">>(),
      endpoint: "/v1/products/1001/cancel",
      http_method: "POST",
      actor_id: typia.random<string & tags.Format<"uuid">>(),
      decision_log_id: typia.random<string & tags.Format<"uuid">>(),
      request_hash: RandomGenerator.alphaNumeric(32),
      response_hash: RandomGenerator.alphaNumeric(32),
      is_success: true,
      status_code: 200,
      created_at: new Date().toISOString(),
    } satisfies IApiAudit.ICreate,
  });
  typia.assert(originalAudit);

  // Step 2. Update allowed/mutable fields (request_hash, response_hash, status_code, is_success)
  const updated_hash = RandomGenerator.alphaNumeric(64);
  const updated_response_hash = RandomGenerator.alphaNumeric(64);
  const updated_status_code = 500;
  const updated_success = false;
  const updateResult = await api.functional.apiOmnichannel.apiAudits.putById(connection, {
    id: originalAudit.id,
    body: {
      ...originalAudit,
      request_hash: updated_hash,
      response_hash: updated_response_hash,
      status_code: updated_status_code,
      is_success: updated_success,
      // The contract requires all fields, but only mutable ones should be changed
      // Note: we keep id and created_at as originals since these are immutable
    } satisfies IApiAudit.IUpdate,
  });
  typia.assert(updateResult);
  TestValidator.equals("request_hash updated")(updateResult.request_hash)(updated_hash);
  TestValidator.equals("response_hash updated")(updateResult.response_hash)(updated_response_hash);
  TestValidator.equals("status_code updated")(updateResult.status_code)(updated_status_code);
  TestValidator.equals("is_success updated")(updateResult.is_success)(updated_success);
  TestValidator.equals("id unchanged")(updateResult.id)(originalAudit.id);
  TestValidator.equals("created_at unchanged")(updateResult.created_at)(originalAudit.created_at);

  // Step 3. Attempt to update immutable fields and expect failure (error thrown)
  await TestValidator.error("Should reject immutable field updates")(() =>
    api.functional.apiOmnichannel.apiAudits.putById(connection, {
      id: originalAudit.id,
      body: {
        ...originalAudit,
        // Try to maliciously change id and created_at
        id: typia.random<string & tags.Format<"uuid">>(),
        created_at: new Date(Date.now() + 10000).toISOString(), // attempt a future timestamp
        // leave other fields as original or as previous valid update
      } as any, // for error scenario (will fail schema validation/server logic)
    }),
  );
}

