import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IApiAudit } from "@ORGANIZATION/PROJECT-api/lib/structures/IApiAudit";

/**
 * Test updating allowed metadata fields in an existing API audit entry and attempting forbidden changes.
 *
 * This test ensures:
 * 1. Only permitted (mutable) fields of an API audit record (e.g., request_hash, response_hash, status_code, is_success, decision_log_id) can be updated by privileged operations.
 * 2. Updates do not destroy/overwrite the original core audit evidence (id, created_at, api_client_id, etc.).
 * 3. Attempts to update immutable fields (e.g., setting created_at to a new value) are rejected by the system.
 *
 * Test steps:
 * 1. Create a new API audit record using the POST endpoint.
 * 2. Compose an update payload that modifies only allowed (mutable) fields for the audit record.
 * 3. Update the audit record using PUT /apiOmnichannel/apiAudits/{id} and verify the update is reflected correctly.
 * 4. Verify that restricted (immutable) fields remain unchanged after update (id and created_at).
 * 5. Attempt to update an immutable field (created_at) and assert that the update fails (error thrown or rejected by server).
 */
export async function test_api_apiAudits_test_update_api_audit_metadata_and_handle_restricted_fields(
  connection: api.IConnection,
) {
  // 1. Create a new audit record
  const originalAudit = await api.functional.apiOmnichannel.apiAudits.post(connection, {
    body: {
      api_client_id: typia.random<string & tags.Format<"uuid">>(),
      api_token_id: typia.random<string & tags.Format<"uuid">>(),
      integration_channel_id: typia.random<string & tags.Format<"uuid">>(),
      endpoint: "/v1/products/1001/cancel",
      http_method: "POST",
      actor_id: typia.random<string & tags.Format<"uuid">>(),
      decision_log_id: typia.random<string & tags.Format<"uuid">>(),
      request_hash: RandomGenerator.alphaNumeric(32),
      response_hash: RandomGenerator.alphaNumeric(32),
      is_success: true,
      status_code: 200,
      created_at: new Date().toISOString(),
    } satisfies IApiAudit.ICreate,
  });
  typia.assert(originalAudit);

  // 2. Update allowed fields only; prepare new values
  const updated_request_hash = RandomGenerator.alphaNumeric(64);
  const updated_response_hash = RandomGenerator.alphaNumeric(64);
  const updated_status_code = 500;
  const updated_success = false;
  const updated_decision_log_id = RandomGenerator.alphaNumeric(24);

  // Compose update payload by copying from original, changing only permitted fields
  const updatePayload: IApiAudit.IUpdate = {
    api_client_id: originalAudit.api_client_id,
    api_token_id: originalAudit.api_token_id,
    integration_channel_id: originalAudit.integration_channel_id,
    endpoint: originalAudit.endpoint,
    http_method: originalAudit.http_method,
    actor_id: originalAudit.actor_id,
    decision_log_id: updated_decision_log_id,
    request_hash: updated_request_hash,
    response_hash: updated_response_hash,
    is_success: updated_success,
    status_code: updated_status_code,
    created_at: originalAudit.created_at,
  };

  // 3. Perform the update
  const updatedAudit = await api.functional.apiOmnichannel.apiAudits.putById(
    connection,
    {
      id: originalAudit.id,
      body: updatePayload,
    },
  );
  typia.assert(updatedAudit);

  // 4. Assert allowed fields changed and restricted fields remain unchanged
  TestValidator.equals("id remains unchanged")(updatedAudit.id)(originalAudit.id);
  TestValidator.equals("created_at remains unchanged")(updatedAudit.created_at)(originalAudit.created_at);
  TestValidator.equals("request_hash updated")(updatedAudit.request_hash)(updated_request_hash);
  TestValidator.equals("response_hash updated")(updatedAudit.response_hash)(updated_response_hash);
  TestValidator.equals("status_code updated")(updatedAudit.status_code)(updated_status_code);
  TestValidator.equals("is_success updated")(updatedAudit.is_success)(updated_success);
  TestValidator.equals("decision_log_id updated")(updatedAudit.decision_log_id)(updated_decision_log_id);
  // No evidence/core fields overwritten!

  // 5. Negative test: attempt to update immutable field (created_at)
  await TestValidator.error("Changing immutable created_at should be rejected")(() =>
    api.functional.apiOmnichannel.apiAudits.putById(connection, {
      id: originalAudit.id,
      body: {
        ...updatePayload,
        created_at: new Date(Date.now() + 10 * 1000).toISOString(), // attempt future timestamp
      },
    }),
  );
}

