import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IApiAudit } from "@ORGANIZATION/PROJECT-api/lib/structures/IApiAudit";

/**
 * Validate soft-deletion of an API audit entry and error handling for non-existent entries.
 *
 * 1. Create a new API audit entry to simulate a real audit record for deletion.
 * 2. Soft-delete the created audit entry via the eraseById endpoint.
 * 3. Validate the audit entry is flagged as deleted (not physically removed, still exists for compliance).
 * 4. Attempt to soft-delete a non-existent audit entry and confirm error response is returned.
 */
export async function test_api_apiaudits_test_soft_delete_api_audit_and_fail_on_nonexistent(connection: api.IConnection) {
  // 1. Create an API audit entry for testing deletion
  const auditInput: IApiAudit.ICreate = {
    api_client_id: typia.random<string & tags.Format<"uuid">>(),
    api_token_id: typia.random<string & tags.Format<"uuid">>(),
    integration_channel_id: typia.random<string & tags.Format<"uuid">>(),
    endpoint: "/example/api/resource",
    http_method: "POST",
    actor_id: typia.random<string & tags.Format<"uuid">>(),
    decision_log_id: typia.random<string>(),
    request_hash: typia.random<string>(),
    response_hash: typia.random<string>(),
    is_success: true,
    status_code: 200,
    created_at: new Date().toISOString()
  };
  const created: IApiAudit = await api.functional.apiOmnichannel.apiAudits.post(connection, { body: auditInput });
  typia.assert(created);

  // 2. Soft-delete the just-created audit entry
  const erased: IApiAudit = await api.functional.apiOmnichannel.apiAudits.eraseById(connection, { id: created.id });
  typia.assert(erased);
  // 3. Check the erased record represents a soft-deleted state;
  TestValidator.equals("id should match the deleted target")(created.id)(erased.id);
  // (Optional: add custom assertion on soft-delete marker when available)

  // 4. Attempt soft-deletion of a random non-existent audit entry and expect error
  await TestValidator.error("deleting a non-existent audit entry should fail")(async () => {
    await api.functional.apiOmnichannel.apiAudits.eraseById(connection, {
      id: typia.random<string & tags.Format<"uuid">>()
    });
  });
}

