import { tags } from "typia";

/**
 * IntegrationChannel is the atomic registry object for backend integration
 * sources (web, mobile, partners, platforms) used across the omnichannel
 * architecture. Matches ERD and Prisma schema fields exactly to support
 * evidence reporting and full compliance trace.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IIntegrationChannel = {
  /**
   * Globally unique identifier for the integration channel. Primary key as
   * defined in integration_channels.id (see ERD and Prisma).
   */
  id: string & tags.Format<"uuid">;

  /**
   * Unique technical identifier for the channel. Enforces cross-platform
   * uniqueness and audit traceability; see schema for required format and
   * uniqueness constraint.
   */
  channel_code: string;

  /**
   * Human-readable, unique/channel-scoped name. Required for all audit,
   * reporting, and UI logic. Complements channel_code and fulfills
   * accessibility mandates.
   */
  channel_name: string;

  /**
   * Activation status; true means channel is enabled, false means
   * archived/deactivated. Mandatory for evidence, compliance, and incident
   * dashboards.
   */
  is_active: boolean;

  /**
   * Timestamp (ISO8601) of channel registration. Non-null; required for
   * regulatory chain-of-custody and evidence auditing.
   */
  created_at: string & tags.Format<"date-time">;

  /**
   * Timestamp (ISO8601) when channel is logically deleted/archived. Null if
   * active. Implements PRISMA soft-delete/evidence retention requirement.
   */
  deleted_at?: (string & tags.Format<"date-time">) | null;
};
export namespace IIntegrationChannel {
  /**
   * Advanced filter, sort, and pagination options for integration channel
   * querying. Required by API_Omnichannel registry and analytics.
   */
  export type IRequest = {
    /**
     * Object grouping field-level search filters for integration channels
     * in API_Omnichannel. All properties directly reference ERD/Prisma
     * columns.
     */
    filters?: {
      /**
       * Exact, prefix, or pattern match for channel code. Unique
       * identifier per channel for multi-channel and analytics workflows.
       * See integration_channels.channel_code in ERD.
       */
      channel_code?: string;

      /**
       * Search or filter for integration channel display name. Supports
       * full-text and partial match, required for UIs and admin
       * registries.
       */
      channel_name?: string;

      /**
       * Optional filter for activation status (true = active, false =
       * archived/blocked). Enforced in regulatory/analytics reporting
       * flows.
       */
      is_active?: boolean;

      /**
       * Time window for when the channel was registered. Used for
       * filtering large datasets and evidence review/audit dashboards.
       */
      created_at?: {
        from?: string & tags.Format<"date-time">;
        to?: string & tags.Format<"date-time">;
      };
    };

    /**
     * Sort order and parameter for result set, supporting regulatory
     * reporting and UI rendering.
     */
    sort?: {
      /**
       * Field to sort results by—'created_at', 'channel_name', or
       * 'channel_code'. Chosen to support typical UI and evidence
       * queries.
       */
      by?: "created_at" | "channel_name" | "channel_code";

      /**
       * Order ('asc' or 'desc'). Supports natural user navigation and
       * compliance export needs.
       */
      order?: "asc" | "desc";
    };

    /**
     * Pagination controls for result set. Essential for compliance evidence
     * export and meta reporting.
     */
    pagination?: {
      /**
       * Page number for pagination, 1-based. Required for evidence and
       * dashboard compliance.
       */
      page?: number & tags.Type<"int32"> & tags.Default<1> & tags.Minimum<1>;

      /**
       * Records per page; upper-limit enforced for performance and
       * evidence trace. 100 per page recommended default.
       */
      limit?: number &
        tags.Type<"int32"> &
        tags.Default<100> &
        tags.Minimum<1> &
        tags.Maximum<1000>;
    };
  };

  /**
   * Input payload for creating a new IntegrationChannel. Fields reference the
   * required PRISMA schema and regulatory requirements for uniqueness and
   * audit logging.
   *
   * Creation events are always logged for evidence.
   */
  export type ICreate = {
    /**
     * Technical, unique code for the integration channel (e.g., 'web',
     * 'mobileapp', 'partner_erp'). Must conform to system format and not
     * collide with existing channels. Implements ERD/prisma code uniqueness
     * for omnichannel workflows.
     */
    channel_code: string;

    /**
     * Human display name for the channel. Used for UIs, admin search, and
     * legal/regulatory reporting. Required in schema.
     */
    channel_name: string;
  };
}

