export async function test_api_apiOmnichannel_test_search_integration_channels_with_various_filters(
  connection: api.IConnection,
) {
  // 1. Create multiple integration channels with unique codes/names/status
  const baseTimestamp = new Date();
  const createdChannels: IIntegrationChannel[] = [];
  for (const details of [
    { code: "web_portal", name: "Web Portal Channel", status: true },
    { code: "mobile_app", name: "Mobile App Channel", status: false },
    { code: "partner_erp", name: "ERP Partner", status: true },
  ]) {
    const channel = await api.functional.apiOmnichannel.integrationChannels.post(connection, {
      body: {
        channel_code: `${details.code}_${RandomGenerator.alphaNumeric(5)}`,
        channel_name: `${details.name} ${RandomGenerator.alphaNumeric(4)}`,
      } satisfies IIntegrationChannel.ICreate,
    });
    typia.assert(channel);
    // PATCH needs is_active and created_at, so collect those too
    createdChannels.push(channel);
  }

  // 2. PATCH (search) for all channels, no filters—expect all
  let searchAll = await api.functional.apiOmnichannel.integrationChannels.patch(connection, { body: {} });
  typia.assert(searchAll);
  for (const ch of createdChannels) {
    TestValidator.predicate(`channel ${ch.channel_code} is present`)(
      searchAll.data.some(row => row.id === ch.id)
    );
  }

  // 3. Search channel_code (expect exactly one)
  const codeToSearch = createdChannels[0].channel_code;
  let searchByCode = await api.functional.apiOmnichannel.integrationChannels.patch(connection, {
    body: { filters: { channel_code: codeToSearch } },
  });
  typia.assert(searchByCode);
  TestValidator.equals("found one by code")(1)(searchByCode.data.filter(row => row.channel_code === codeToSearch).length);

  // 4. Search channel_name partial (uppercase fragment)
  const fragment = createdChannels[2].channel_name.slice(0, 5);
  let searchFragment = await api.functional.apiOmnichannel.integrationChannels.patch(connection, {
    body: { filters: { channel_name: fragment } },
  });
  typia.assert(searchFragment);
  TestValidator.predicate("partial name match present")(
    searchFragment.data.some(row => row.channel_name.includes(fragment))
  );

  // 5. Search is_active true/false
  for (const desiredStatus of [true, false]) {
    let searchByStatus = await api.functional.apiOmnichannel.integrationChannels.patch(connection, {
      body: { filters: { is_active: desiredStatus } },
    });
    typia.assert(searchByStatus);
    for (const row of searchByStatus.data) {
      TestValidator.equals(`is_active should be ${desiredStatus}`)(desiredStatus)(row.is_active);
    }
    // At least one expected on true; may be none for false
    TestValidator.predicate("matched by status filter")(
      searchByStatus.data.some(row => row.is_active === desiredStatus)
    );
  }

  // 6. Search created_at outside all records (future window)
  const futureDate = new Date(+baseTimestamp + 10 * 24 * 60 * 60 * 1000).toISOString();
  let searchFuture = await api.functional.apiOmnichannel.integrationChannels.patch(connection, {
    body: {
      filters: {
        created_at: { from: futureDate },
      },
    },
  });
  typia.assert(searchFuture);
  TestValidator.equals("no channels expected in future search")(0)(searchFuture.data.length);

  // 7. Pagination: limit=1, get first 2 pages, total count matches all
  let paged1 = await api.functional.apiOmnichannel.integrationChannels.patch(connection, {
    body: { pagination: { page: 1, limit: 1 } },
  });
  typia.assert(paged1);
  TestValidator.equals("limit 1 on page 1")(1)(paged1.data.length);
  let paged2 = await api.functional.apiOmnichannel.integrationChannels.patch(connection, {
    body: { pagination: { page: 2, limit: 1 } },
  });
  typia.assert(paged2);
  TestValidator.equals("limit 1 on page 2")(1)(paged2.data.length);
  // Total records check
  TestValidator.predicate("total records includes all created")(
    paged1.pagination.records >= createdChannels.length
  );
}

