/**
 * Test updating integration channel metadata and handling invalid updates.
 *
 * Business rationale: Integration channels must support updating user-facing metadata (like names or activation status) for compliance and operational auditability. Must also enforce error handling on invalid or non-existent IDs.
 *
 * Step-by-step process:
 * 1. Create a new integration channel (dependency)
 * 2. Update the channel's metadata (e.g., change display name and activation status)
 * 3. Fetch or inspect the returned channel, confirming that changes were applied and immutable fields remain unchanged
 * 4. Attempt to update a channel using an invalid (random, non-existent) UUID as id, and validate that an error is thrown or a suitable error message/status is returned
 */
export async function test_api_apiOmnichannel_integrationChannels_test_update_integration_channel_metadata_and_fail_on_invalid_id(
  connection: api.IConnection,
) {
  // 1. Create a new integration channel (dependency)
  const createInput: IIntegrationChannel.ICreate = {
    channel_code: RandomGenerator.alphabets(8),
    channel_name: `Channel ${RandomGenerator.alphabets(5)}`,
  };
  const channel = await api.functional.apiOmnichannel.integrationChannels.post(connection, {
    body: createInput
  });
  typia.assert(channel);

  // 2. Update the channel metadata (change name & activate/deactivate)
  const updateInput: IIntegrationChannel.IUpdate = {
    channel_name: channel.channel_name + " (renamed)",
    is_active: !channel.is_active,
  };
  const updated = await api.functional.apiOmnichannel.integrationChannels.putById(connection, {
    id: channel.id,
    body: updateInput
  });
  typia.assert(updated);
  TestValidator.equals("updated id")(channel.id)(updated.id);
  TestValidator.equals("updated channel_code")(channel.channel_code)(updated.channel_code);
  TestValidator.equals("updated channel_name")(updateInput.channel_name)(updated.channel_name);
  TestValidator.equals("updated is_active")(updateInput.is_active)(updated.is_active);
  TestValidator.equals("created_at should remain unchanged")(channel.created_at)(updated.created_at);

  // 3. Attempt to update a non-existent channel and validate error
  await TestValidator.error("update fails for non-existent channel")(() =>
    api.functional.apiOmnichannel.integrationChannels.putById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(), // random UUID unlikely to exist
      body: { channel_name: "Should fail" }
    })
  );
}

