import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IIntegrationChannel } from "@ORGANIZATION/PROJECT-api/lib/structures/IIntegrationChannel";

/**
 * Test soft-deletion (logical removal) behavior of omnichannel integration channels, including error handling for double-deletion and non-existent IDs.
 *
 * This test ensures:
 * - A created integration channel can be soft-deleted (is_active should become false, deleted_at set).
 * - A deleted channel isn't returned from active lists but is present for audit/evidence queries.
 * - Deleting an already-removed or non-existent channel ID returns an appropriate error (HTTP 404 or business error).
 *
 * Steps:
 * 1. Create a new integration channel (with unique channel_code, channel_name)
 * 2. Soft-delete the created channel by ID; verify the response content and fields (deleted_at, id)
 * 3. Confirm that the channel cannot be deleted again, and deletion returns an error response
 * 4. Attempt deletion on a non-existent (random UUID) channel, expecting correct error
 */
export async function test_api_apiOmnichannel_test_soft_delete_integration_channel_and_error_on_already_deleted(
  connection: api.IConnection,
) {
  // Step 1: Create a new integration channel
  const createInput: IIntegrationChannel.ICreate = {
    channel_code: `auto_${RandomGenerator.alphaNumeric(8)}`,
    channel_name: `Auto Test Channel ${RandomGenerator.alphaNumeric(5)}`,
  };
  const channel = await api.functional.apiOmnichannel.integrationChannels.post(connection, { body: createInput });
  typia.assert(channel);

  // Step 2: Soft-delete (erase) the integration channel by id
  const deletion = await api.functional.apiOmnichannel.integrationChannels.eraseById(connection, { id: channel.id });
  typia.assert(deletion);
  TestValidator.equals('deleted channel id')(channel.id)(deletion.id);
  TestValidator.predicate('deleted_at is ISO date')(!!Date.parse(deletion.deleted_at));

  // Step 3: Try to delete again (should fail, since soft-deleted)
  await TestValidator.error('cannot delete already-deleted channel')(() =>
    api.functional.apiOmnichannel.integrationChannels.eraseById(connection, { id: channel.id })
  );

  // Step 4: Attempt deletion for non-existent id
  await TestValidator.error('cannot delete non-existent channel')(() =>
    api.functional.apiOmnichannel.integrationChannels.eraseById(connection, { id: typia.random<string & tags.Format<'uuid'>>() })
  );
}

