import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IChannelSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IChannelSession";
import type { IPageIChannelSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIChannelSession";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * E2E test for searching and paginating channel sessions via the PATCH /apiOmnichannel/channelSessions endpoint.
 *
 * Business context:
 * - Channel sessions support search with various filters (user_id, integration_channel_id, api_token_id, session_key) for auditing, analytics, and debugging omnichannel session behavior.
 * - Results must only include non-deleted sessions.
 * - Pagination is essential for handling large result sets and compliance workflows.
 *
 * Test Process:
 * 1. Create multiple channel sessions with overlapping and unique combinations of user_id, integration_channel_id, and api_token_id for realistic filter scenarios.
 * 2. Patch with no filters; assert all created sessions are returned (paginated if needed) and pagination meta is accurate.
 * 3. Filter: Search separately by user_id, integration_channel_id, and api_token_id—assert each returns only matching sessions.
 * 4. Paginate: Query with limit smaller than total count, fetch all pages, validate full coverage, and no duplicate/missing items.
 * 5. Boundary: Try out-of-bounds pagination and invalid limits, expect correct error handling or clamping.
 */
export async function test_api_apiOmnichannel_test_search_channel_sessions_and_paginate_results(
  connection: api.IConnection,
) {
  // --- 1. Create a diverse array of channel sessions ---
  const userIds = [
    typia.random<string & tags.Format<"uuid">>(),
    typia.random<string & tags.Format<"uuid">>()
  ];
  const integrationChannelIds = [
    typia.random<string & tags.Format<"uuid">>(),
    typia.random<string & tags.Format<"uuid">>()
  ];
  const apiTokenIds = [
    typia.random<string & tags.Format<"uuid">>(),
    typia.random<string & tags.Format<"uuid">>()
  ];
  // Create 1 session per unique combo, with overlap so each filter is tested
  const created: IChannelSession[] = [];
  for (let i=0; i<6; ++i) {
    const session = await api.functional.apiOmnichannel.channelSessions.post(connection, {
      body: {
        integration_channel_id: RandomGenerator.pick(integrationChannelIds),
        api_token_id: RandomGenerator.pick(apiTokenIds),
        user_id: RandomGenerator.pick(userIds),
        session_key: RandomGenerator.alphaNumeric(12),
        started_at: new Date(Date.now() - i * 60000).toISOString()
      } satisfies IChannelSession.ICreate,
    });
    typia.assert(session);
    created.push(session);
  }
  // Also create an anonymous session (user_id null)
  const anonSession = await api.functional.apiOmnichannel.channelSessions.post(connection, {
    body: {
      integration_channel_id: integrationChannelIds[0],
      api_token_id: apiTokenIds[0],
      user_id: null,
      session_key: RandomGenerator.alphaNumeric(12),
      started_at: new Date().toISOString()
    } satisfies IChannelSession.ICreate,
  });
  typia.assert(anonSession);
  created.push(anonSession);

  // --- 2. Patch: No filters, get all sessions ---
  let allResults: IChannelSession[] = [];
  let returnedIds: Set<string> = new Set();
  let page = 1;
  const limit = 4;
  let gotAll = false;
  while (!gotAll) {
    const res = await api.functional.apiOmnichannel.channelSessions.patch(connection, {
      body: { pagination: { page, limit } }
    });
    typia.assert(res);
    for (const sess of res.data) {
      // Ensure uniqueness and data integrity
      TestValidator.predicate("non-duplicate session id")(!returnedIds.has(sess.id));
      returnedIds.add(sess.id);
      allResults.push(sess);
    }
    if (returnedIds.size >= created.length || res.data.length===0 || page >= res.pagination.pages)
      gotAll = true;
    else
      ++page;
  }
  // All created sessions should be returned
  const createdIds = created.map(s => s.id);
  TestValidator.equals("all created sessions found")(
    createdIds.length
  )(
    createdIds.filter(id=>returnedIds.has(id)).length
  );

  // --- 3. Filtering by user_id, integration_channel_id, api_token_id, session_key ---
  for (const user_id of userIds) {
    const filtered = created.filter(s => s.user_id === user_id);
    const res = await api.functional.apiOmnichannel.channelSessions.patch(connection, {
      body: { filters: { user_id } }
    });
    typia.assert(res);
    TestValidator.equals(`user_id ${user_id} count`)(filtered.length)(res.data.length);
    for (const row of res.data)
      TestValidator.equals("user_id match")(user_id)(row.user_id);
  }
  for (const integration_channel_id of integrationChannelIds) {
    const filtered = created.filter(s => s.integration_channel_id === integration_channel_id);
    const res = await api.functional.apiOmnichannel.channelSessions.patch(connection, {
      body: { filters: { integration_channel_id } }
    });
    typia.assert(res);
    TestValidator.equals(`integration_channel_id count`)(filtered.length)(res.data.length);
    for (const row of res.data)
      TestValidator.equals("integration_channel_id match")(integration_channel_id)(row.integration_channel_id);
  }
  for (const api_token_id of apiTokenIds) {
    const filtered = created.filter(s => s.api_token_id === api_token_id);
    const res = await api.functional.apiOmnichannel.channelSessions.patch(connection, {
      body: { filters: { api_token_id } }
    });
    typia.assert(res);
    TestValidator.equals(`api_token_id count`)(filtered.length)(res.data.length);
    for (const row of res.data)
      TestValidator.equals("api_token_id match")(api_token_id)(row.api_token_id);
  }
  // Search by session_key for a random session
  const randomSession = RandomGenerator.pick(created);
  const resByKey = await api.functional.apiOmnichannel.channelSessions.patch(connection, {
    body: { filters: { session_key: randomSession.session_key } }
  });
  typia.assert(resByKey);
  TestValidator.equals("session_key precise match")(1)(resByKey.data.length);
  TestValidator.equals("session_id precise match")(randomSession.id)(resByKey.data[0].id);

  // --- 4. Pagination: Query with smaller limit, reconstitute, check for missing or duplicates ---
  {
    const pagedIds: Set<string> = new Set();
    let curr = 1;
    let all: IChannelSession[] = [];
    let done = false;
    while (!done) {
      const res = await api.functional.apiOmnichannel.channelSessions.patch(connection, {
        body: { pagination: { page: curr, limit: 2 } }
      });
      typia.assert(res);
      for (const s of res.data) {
        TestValidator.predicate("no duplicate on paging")(!pagedIds.has(s.id));
        pagedIds.add(s.id);
        all.push(s);
      }
      if (pagedIds.size >= created.length || res.data.length === 0 || curr >= res.pagination.pages) done = true; else ++curr;
    }
    TestValidator.equals("paging returns all created")(
      created.length
    )(
      created.filter(s=>pagedIds.has(s.id)).length
    );
  }

  // --- 5. Boundary tests: invalid page/limit ---
  // page out of bounds: too high
  {
    const res = await api.functional.apiOmnichannel.channelSessions.patch(connection, {
      body: { pagination: { page: 99, limit: 2 } }
    });
    typia.assert(res);
    // Expect empty data or last valid page
    TestValidator.predicate("out of bounds page: empty or final")(
      res.data.length === 0 || res.pagination.current <= res.pagination.pages
    );
  }
  // limit=0 (invalid, should be clamped to min=1)
  {
    const res = await api.functional.apiOmnichannel.channelSessions.patch(connection, {
      body: { pagination: { page: 1, limit: 0 } }
    });
    typia.assert(res);
    // Should default at least 1 per schema
    TestValidator.predicate("limit clamped >=1")(res.data.length >= 1);
  }
  // limit>max (invalid, should be clamped to max=1000)
  {
    const res = await api.functional.apiOmnichannel.channelSessions.patch(connection, {
      body: { pagination: { page: 1, limit: 9999 } }
    });
    typia.assert(res);
    TestValidator.predicate("limit max-clamped")(res.data.length <= 1000);
  }
}

