import { tags } from "typia";

/**
 * ChannelSession entity for omnichannel session management (API_Omnichannel).
 * Captures user, channel, API token, session key, start/end timing for
 * analytics, compliance, and evidence auditing. Follows Prisma/ERD.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IChannelSession = {
  /**
   * Globally unique identifier for the session, as defined in
   * channel_sessions.id ERD.
   */
  id: string & tags.Format<"uuid">;

  /**
   * Channel reference (integration_channels.id) for the session, enabling
   * omnichannel analytics/audit. Part of core session reporting requirement.
   */
  integration_channel_id: string & tags.Format<"uuid">;

  /**
   * API token used to establish session, per ERD/API. Required for full audit
   * and regulatory evidence chain, ties session lifecycle to identity.
   */
  api_token_id: string & tags.Format<"uuid">;

  /**
   * User ID for user-linked sessions. Null for partner/system-only/anonymous
   * sessions. Implements evidence, security, and analytic flows required by
   * compliance reporting.
   */
  user_id?: (string & tags.Format<"uuid">) | null;

  /**
   * Server-generated opaque session identifier. Uniqueness enforced by ERD.
   * Required by all forensics and session audit dashboards.
   */
  session_key: string;

  /**
   * Session creation timestamp (ISO8601). For audit, analytics,
   * chain-of-custody.
   */
  started_at: string & tags.Format<"date-time">;

  /**
   * Timestamp this session ended (logout, expiry). Null if still open.
   * Evidence for legal compliance, forensic audit, and session lifecycle
   * monitoring.
   */
  ended_at?: (string & tags.Format<"date-time">) | null;
};
export namespace IChannelSession {
  /**
   * Payload for creating a new omnichannel session record (channel_sessions).
   * All required attributes reference ERD/Prisma db fields and maintain
   * non-repudiation via audit log.
   */
  export type ICreate = {
    /**
     * UUID of integration channel for session; must reference active
     * channel. Enforces multidomain audit/analytics workflows.
     */
    integration_channel_id: string & tags.Format<"uuid">;

    /**
     * API token under which session is established. Ensures trace
     * throughout registry.
     */
    api_token_id: string & tags.Format<"uuid">;

    /**
     * User ID for session; null for anonymous/system only. Implements
     * privacy/separation as required by analytics, forensics, and
     * regulatory compliance.
     */
    user_id?: (string & tags.Format<"uuid">) | null;

    /**
     * Opaque session identifier, generated by server for unique evidence
     * tracking. Must not duplicate existing session (ERD unique index).
     */
    session_key: string;

    /**
     * ISO8601 start timestamp, set by server or trusted client. Ensures
     * evidence and legal clock tracking.
     */
    started_at: string & tags.Format<"date-time">;
  };
}

