import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IChannelSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IChannelSession";

/**
 * Validate retrieval of omnichannel session details and non-existent session error.
 *
 * 1. Create a new omnichannel session (channelSessions.post), saving its ID for reference.
 * 2. Fetch the session using getById (channelSessions.getById) with a valid ID and verify audit/evidence fields.
 * 3. Attempt to fetch details of a missing (random/invalid) session and check for an error (ideally 404).
 */
export async function test_api_apiOmnichannel_channelSessions_test_get_channel_session_detail_and_missing_case(
  connection: api.IConnection,
) {
  // 1. Create a new omnichannel session
  const createInput: IChannelSession.ICreate = {
    integration_channel_id: typia.random<string & tags.Format<"uuid">>(),
    api_token_id: typia.random<string & tags.Format<"uuid">>(),
    // user_id is optional; test with null (anonymous session)
    user_id: null,
    session_key: RandomGenerator.alphaNumeric(16),
    started_at: new Date().toISOString() as string & tags.Format<"date-time">,
  };
  const created: IChannelSession = await api.functional.apiOmnichannel.channelSessions.post(connection, { body: createInput });
  typia.assert(created);

  // 2. Fetch the created session by ID
  const fetched: IChannelSession = await api.functional.apiOmnichannel.channelSessions.getById(connection, { id: created.id });
  typia.assert(fetched);

  // Business logic validation: all audit/evidence fields should match and appear valid
  TestValidator.equals("integration_channel_id")(
    createInput.integration_channel_id
  )(fetched.integration_channel_id);
  TestValidator.equals("api_token_id")(createInput.api_token_id)(fetched.api_token_id);
  TestValidator.equals("session_key")(createInput.session_key)(fetched.session_key);
  TestValidator.equals("started_at")(createInput.started_at)(fetched.started_at);
  TestValidator.equals("user_id")(createInput.user_id)(fetched.user_id);
  TestValidator.equals("ended_at")(null)(fetched.ended_at);

  // 3. Attempt to fetch a non-existing session, expect error or not found
  await TestValidator.error("non-existent session 404")(() =>
    api.functional.apiOmnichannel.channelSessions.getById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
    })
  );
}

