import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IChannelSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IChannelSession";

/**
 * End-to-end test for channel session creation validation and persistence.
 *
 * This function performs the following:
 *   1. Creates a valid channel session via POST /apiOmnichannel/channelSessions and
 *      confirms the resulting entity.
 *   2. Validates that the created session appears with correct properties by re-querying (if a session listing/get API exists).
 *   3. Attempts to create a session with missing required fields and checks that validation fails as expected.
 *
 * Each step checks type conformance via typia.assert as well as business logic constraints. The test ensures both positive and negative paths are covered for robust contract assurance.
 */
export async function test_api_apiOmnichannel_channelSessions_post(
  connection: api.IConnection,
) {
  // 1. Create a valid channel session
  const validSessionInput: IChannelSession.ICreate = {
    integration_channel_id: typia.random<string & tags.Format<"uuid">>(),
    api_token_id: typia.random<string & tags.Format<"uuid">>(),
    user_id: typia.random<string & tags.Format<"uuid">>(),
    session_key: RandomGenerator.alphaNumeric(32),
    started_at: new Date().toISOString() as string & tags.Format<"date-time">,
  };
  const session = await api.functional.apiOmnichannel.channelSessions.post(connection, {
    body: validSessionInput,
  });
  typia.assert(session);

  // Business logic validation: ensure returned properties match input for non-generated fields
  TestValidator.equals("integration_channel_id")(validSessionInput.integration_channel_id)(session.integration_channel_id);
  TestValidator.equals("api_token_id")(validSessionInput.api_token_id)(session.api_token_id);
  TestValidator.equals("session_key")(validSessionInput.session_key)(session.session_key);
  TestValidator.equals("started_at")(validSessionInput.started_at)(session.started_at);

  // 2. (Optional) Re-query to verify persistence (If GET endpoint exists)
  // Not implemented here since no read/list endpoint is provided in the DTO/API spec.

  // 3. Attempt to create a session with missing required fields - integration_channel_id is missing
  await TestValidator.error("missing integration_channel_id should fail")(() =>
    api.functional.apiOmnichannel.channelSessions.post(connection, {
      body: {
        // integration_channel_id: intentionally omitted
        api_token_id: typia.random<string & tags.Format<"uuid">>(),
        session_key: RandomGenerator.alphaNumeric(32),
        started_at: new Date().toISOString() as string & tags.Format<"date-time">,
      } as any, // Safe bypass for negative testing (TypeScript disallows omitting required fields)
    }),
  );

  // 4. Attempt to create a session with an invalid started_at (not ISO string)
  await TestValidator.error("invalid started_at format should fail")(() =>
    api.functional.apiOmnichannel.channelSessions.post(connection, {
      body: {
        integration_channel_id: typia.random<string & tags.Format<"uuid">>(),
        api_token_id: typia.random<string & tags.Format<"uuid">>(),
        session_key: RandomGenerator.alphaNumeric(32),
        started_at: "not-a-date-time" as any,
      } as any,
    }),
  );
