import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IWebhookEvent } from "@ORGANIZATION/PROJECT-api/lib/structures/IWebhookEvent";
import type { IPageIWebhookEvent } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIWebhookEvent";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate searching and filtering of webhook events by creation date, endpoint, delivery status, and pagination.
 *
 * Business context:
 * System administrators and compliance personnel must be able to efficiently query webhook delivery events for operational monitoring, forensics, and regulatory/export. This test ensures webhook events can be filtered by delivery_status, destination_url, and creation timestamps, and paginated, returning both correct event subsets and metadata as required for analytics, compliance, and monitoring.
 *
 * Step-by-step process:
 * 1. Create several webhook events with varied statuses, URLs, and event types at different timestamps.
 * 2. List all events unfiltered and validate all inserted entries appear, with correct pagination.
 * 3. Filter by delivery_status (e.g., 'pending'), verify only matching events are returned.
 * 4. Filter by destination_url for a specific event, confirm only that event returns.
 * 5. Filter using created_from/created_to date window, validate matching set.
 * 6. Paginate through events with limit=2, verify pagination metadata and subsets are correct.
 * 7. Edge: Filter for non-existent hash, verify results are empty with valid pagination metadata.
 * 8. Validate all webhook event objects in results using runtime type assertions.
 */
export async function test_api_apiOmnichannel_test_search_webhook_events_by_criteria(
  connection: api.IConnection,
) {
  // 1. Create several webhook events with distinct parameters
  const now = new Date();
  // Distinct delivery statuses and URLs for filter coverage
  const events = await Promise.all([
    api.functional.apiOmnichannel.webhookEvents.post(connection, {
      body: {
        integration_channel_id: typia.random<string & tags.Format<"uuid">>(),
        event_type: "order.created",
        destination_url: `https://webhook-${RandomGenerator.alphaNumeric(4)}.sitehook.io`
          .slice(0, 255),
        event_hash: RandomGenerator.alphaNumeric(24),
      } satisfies IWebhookEvent.ICreate,
    }),
    api.functional.apiOmnichannel.webhookEvents.post(connection, {
      body: {
        integration_channel_id: typia.random<string & tags.Format<"uuid">>(),
        event_type: "order.updated",
        destination_url: `https://deliveryhook-${RandomGenerator.alphaNumeric(4)}.com`
          .slice(0, 255),
        event_hash: RandomGenerator.alphaNumeric(24),
      } satisfies IWebhookEvent.ICreate,
    }),
    api.functional.apiOmnichannel.webhookEvents.post(connection, {
      body: {
        integration_channel_id: typia.random<string & tags.Format<"uuid">>(),
        event_type: "payment.completed",
        destination_url: `https://payhook-${RandomGenerator.alphaNumeric(4)}.net`
          .slice(0, 255),
        event_hash: RandomGenerator.alphaNumeric(24),
      } satisfies IWebhookEvent.ICreate,
    }),
  ]);
  events.forEach(typia.assert);

  // Patch one event to simulate a different delivery status
  // (Assume event delivery simulation is not available in this context)
  // We'll assume all are 'pending' or system default

  // 2. Unfiltered search
  let pageRes = await api.functional.apiOmnichannel.webhookEvents.patch(connection, {
    body: {
      // no filters
    } satisfies IWebhookEvent.IRequest,
  });
  typia.assert(pageRes);
  // All created events must be present
  events.forEach(ev => {
    TestValidator.predicate("created event exists in unfiltered list")(pageRes.data.some(x => x.id === ev.id));
  });

  // 3. Filter by delivery_status ('pending')
  pageRes = await api.functional.apiOmnichannel.webhookEvents.patch(connection, {
    body: {
      delivery_status: "pending",
    } satisfies IWebhookEvent.IRequest,
  });
  typia.assert(pageRes);
  pageRes.data.forEach(event => {
    TestValidator.equals("delivery_status")(event.delivery_status)("pending");
  });

  // 4. Filter by one event's destination_url
  const destUrl = events[1].destination_url;
  pageRes = await api.functional.apiOmnichannel.webhookEvents.patch(connection, {
    body: {
      destination_url: destUrl,
    } satisfies IWebhookEvent.IRequest,
  });
  typia.assert(pageRes);
  pageRes.data.forEach(event => {
    TestValidator.equals("destination_url")(event.destination_url)(destUrl);
  });
  // The correct event must appear
  TestValidator.predicate("event with destination_url exists")(
    pageRes.data.some(x => x.id === events[1].id)
  );

  // 5. Filter by creation date range (using created_from, created_to)
  const lower = new Date(new Date(events[0].created_at).getTime() - 60 * 1000).toISOString();
  const upper = new Date(new Date(events[0].created_at).getTime() + 60 * 1000).toISOString();
  pageRes = await api.functional.apiOmnichannel.webhookEvents.patch(connection, {
    body: {
      created_from: lower,
      created_to: upper,
    } satisfies IWebhookEvent.IRequest,
  });
  typia.assert(pageRes);
  // Only events in that 2-min window (likely just events[0])
  pageRes.data.forEach(event => {
    TestValidator.predicate("created_at inside range")(
      new Date(event.created_at) >= new Date(lower) && new Date(event.created_at) <= new Date(upper)
    );
  });
  TestValidator.predicate("at least one event in date range")(pageRes.data.length >= 1);

  // 6. Pagination checks - limit to 2 per page, traverse pages
  pageRes = await api.functional.apiOmnichannel.webhookEvents.patch(connection, {
    body: {
      limit: 2,
      page: 1,
    } satisfies IWebhookEvent.IRequest,
  });
  typia.assert(pageRes);
  TestValidator.equals("limit")(2)(pageRes.pagination.limit);
  // At least 1 event, up to 2 expected
  TestValidator.predicate("nonzero page size")(pageRes.data.length >= 1 && pageRes.data.length <= 2);

  // 7. Edge: filter with impossible hash returns zero
  pageRes = await api.functional.apiOmnichannel.webhookEvents.patch(connection, {
    body: {
      event_hash: "no-such-hash-test-ai-e2e-case",
    } satisfies IWebhookEvent.IRequest,
  });
  typia.assert(pageRes);
  TestValidator.equals("empty for non-existent hash")(pageRes.data.length)(0);
  // Check valid pagination metadata
  TestValidator.equals("pages for empty result")(pageRes.pagination.pages)(1);
  TestValidator.equals("records for empty result")(pageRes.pagination.records)(0);

  // 8. Type assertion over all search results
  pageRes.data.forEach(typia.assert);
}

