import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IWebhookEvent } from "@ORGANIZATION/PROJECT-api/lib/structures/IWebhookEvent";

/**
 * Validate retrieval of a single webhook event by ID including both the success case (existing record) and failure case (non-existent/deleted record).
 * 
 * Business context:
 * Webhook events provide a complete audit trail for notifications delivered via omnichannel integrations. Each retrieval must provide full compliance and evidence metadata, enabling monitoring, incident forensics, and regulatory export. The test covers positive and negative lookup scenarios expected in compliance/audit review systems.
 *
 * Step-by-step process:
 * 1. Create a new webhook event using valid test data (dependency step).
 * 2. Retrieve the newly-created webhook event by its exact UUID (getById) and verify all key details.
 * 3. Attempt to GET a webhook event with a random, non-existent UUID and validate the API returns a proper error (e.g., 404 not found or compliance error). 
 * 4. (Optional) Delete the event and reattempt retrieval to check error handling (if delete endpoint exists — skip if not part of scope).
 */
export async function test_api_apiOmnichannel_test_get_webhook_event_detail_and_invalid_id_case(
  connection: api.IConnection,
) {
  // 1. Create webhook event
  const createPayload: IWebhookEvent.ICreate = {
    integration_channel_id: typia.random<string & tags.Format<"uuid">>(),
    event_type: "order.updated",
    destination_url: "https://webhook.example.com/api/integration/hook",
    event_hash: RandomGenerator.alphaNumeric(64),
  };
  const created: IWebhookEvent = await api.functional.apiOmnichannel.webhookEvents.post(connection, {body: createPayload});
  typia.assert(created);

  // 2. Retrieve the webhook event by ID
  const fetched: IWebhookEvent = await api.functional.apiOmnichannel.webhookEvents.getById(connection, {id: created.id});
  typia.assert(fetched);
  TestValidator.equals("id")(created.id)(fetched.id);
  TestValidator.equals("integration_channel_id")(createPayload.integration_channel_id)(fetched.integration_channel_id);
  TestValidator.equals("event_type")(createPayload.event_type)(fetched.event_type);
  TestValidator.equals("destination_url")(createPayload.destination_url)(fetched.destination_url);
  TestValidator.equals("event_hash")(createPayload.event_hash)(fetched.event_hash);

  // 3. Attempt to fetch with a non-existent/deleted ID—should error
  const randomId = typia.random<string & tags.Format<"uuid">>();
  if (randomId !== created.id) {
    await TestValidator.error("not found or deleted webhook event fetch")(async () => {
      await api.functional.apiOmnichannel.webhookEvents.getById(connection, {id: randomId});
    });
  }
}

