import api from "@ORGANIZATION/PROJECT-api";
import type { IWebhookEvent } from "@ORGANIZATION/PROJECT-api/lib/structures/IWebhookEvent";

/**
 * Validate the creation and error handling of webhook events in the
 * Omnichannel system.
 *
 * This scenario verifies that webhook events can be created with valid
 * metadata, that the system rejects invalid or incomplete payloads (with
 * validation errors), and that once created, events are correctly retrievable
 * through further listing or searching.
 *
 * Steps:
 * 1. Create a webhook event with all valid required fields. Verify success
 *    and type-check with typia.assert.
 * 2. Attempt to create webhook event with invalid data (e.g., invalid uuid,
 *    destination_url too long, empty event_type, etc.) and confirm correct
 *    validation errors are thrown.
 * 3. (Optional) If a search/list endpoint is available, search for the
 *    created event (by integration_channel_id or event_type) and verify its
 *    existence and correctness in the search results.
 */
export async function test_api_apiOmnichannel_test_create_webhook_event_success_and_invalid_payload(
  connection: api.IConnection,
) {
  // 1. Create a webhook event with valid required fields
  const validEventInput: IWebhookEvent.ICreate = {
    integration_channel_id: typia.random<string & tags.Format<"uuid">>(),
    event_type: "order.created",
    destination_url: "https://webhook-test.client/callback",
    event_hash: "abc123def456", // realistic but arbitrary hash
  };
  const createdEvent: IWebhookEvent = await api.functional.apiOmnichannel.webhookEvents.post(
    connection,
    { body: validEventInput },
  );
  typia.assert(createdEvent);
  // Validate result matches input (ignoring autogenerated fields)
  TestValidator.equals("integration_channel_id")(
    validEventInput.integration_channel_id,
  )(createdEvent.integration_channel_id);
  TestValidator.equals("event_type")(validEventInput.event_type)(
    createdEvent.event_type,
  );
  TestValidator.equals("destination_url")(validEventInput.destination_url)(
    createdEvent.destination_url,
  );
  TestValidator.equals("event_hash")(validEventInput.event_hash)(
    createdEvent.event_hash,
  );

  // 2. Attempt to create with invalid data (TypeScript-valid but runtime-invalid)
  await TestValidator.error("Invalid UUID triggers validation error")(
    async () => {
      await api.functional.apiOmnichannel.webhookEvents.post(connection, {
        body: {
          integration_channel_id: "not-a-uuid" as string & tags.Format<"uuid">,
          event_type: "order.created",
          destination_url: "https://webhook-test.client/callback",
          event_hash: "abc123def456",
        },
      });
    },
  );
  await TestValidator.error(
    "Destination URL over max length triggers validation error",
  )(async () => {
    await api.functional.apiOmnichannel.webhookEvents.post(connection, {
      body: {
        integration_channel_id: typia.random<string & tags.Format<"uuid">>(),
        event_type: "order.created",
        destination_url: "https://" + "a".repeat(80001) + ".com/",
        event_hash: "abc123def456",
      },
    });
  });
  await TestValidator.error(
    "Empty event_type triggers validation error",
  )(async () => {
    await api.functional.apiOmnichannel.webhookEvents.post(connection, {
      body: {
        integration_channel_id: typia.random<string & tags.Format<"uuid">>(),
        event_type: "",
        destination_url: "https://webhook-test.client/callback",
        event_hash: "abc123def456",
