 * analytics, audit, and regulatory export. Fulfills all requirements from the
 * communication, evidence, and traceability modules.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IWebhookEvent = {
  /**
   * Unique identifier for the webhook event record.
   *
   * Directly derived from ProductCatalog/Omnichannel Prisma– used for
   * traceability in audit, regulatory, and operational reporting.
   */
  id: string & tags.Format<"uuid">;

  /**
   * The integration channel through which the webhook event was routed.
   *
   * References the integration_channels entity, fulfilling omnichannel
   * traceability and regulatory monitoring. Required by business logic and
   * analytics.
   */
  integration_channel_id: string & tags.Format<"uuid">;

  /**
   * Webhook business/technical event code (e.g., 'order.updated',
   * 'payment.completed').
   *
   * Used in event-based monitoring, analytics, audit, and regulatory
   * workflows. Referenced from the events table and requirement analysis.
   */
  event_type: string;

  /**
   * Destination URL that received the webhook event notification.
   *
   * Evidence field: enables compliance workflows for partner, external, or
   * regulatory reporting. As per API integration best practices.
   */
  destination_url: string & tags.MaxLength<80000>;

  /**
   * Number of delivery attempts made to the destination URL.
   *
   * Fulfills monitoring, incident analysis, and evidence preservation under
   * SLA rules. Prisma schema requirement.
   */
  attempt_count: number & tags.Type<"int32">;

  /**
   * Timestamp when delivery was last attempted.
   *
   * Enabling trace of retry/incident logic as required for evidence and
   * audit. Referenced in business continuity and Analytics modules.
   */
  last_attempted_at: string & tags.Format<"date-time">;

  /**
   * Timestamp when webhook was successfully delivered. Null if not delivered
   * yet.
   *
   * Enables compliance reporting and evidence traceability for
   * delivery/failure as regulated under omnichannel requirement and SLA
   * standards.
   */
  delivered_at?: (string & tags.Format<"date-time">) | null;

  /**
   * Current status of this webhook delivery ('pending','success','failed').
   *
   * Enum/constraint from API_Omnichannel and regulatory/audit chain
   * standards.
   */
  delivery_status: "pending" | "success" | "failed";

  /**
   * Hashed payload/event content reference for compliance, evidence, and
   * audit chain. Used for anti-tampering and traceability in regulatory
   * reporting.
   */
  event_hash: string;

  /**
   * Date/time of webhook event creation.
   *
   * Directly referenced for ordering, time-window analytics, and regulatory
   * export. Prisma schema column and incident chain origin.
   */
  created_at: string & tags.Format<"date-time">;
};
export namespace IWebhookEvent {
  /**
   * Request schema for creating a new webhook event record for
   * delivery/compliance.
   *
   * Captures all fields required for registering a delivery attempt, meeting
   * regulatory trace, evidence, and monitoring obligations under omnichannel
   * requirements.
   */
  export type ICreate = {
    /**
     * Reference to the integration channel delivering this webhook event.
     *
     * Enforces traceability and compliance for API extensibility and
     * partner integrations. Prisma schema field, required.
     */
    integration_channel_id: string & tags.Format<"uuid">;

    /**
     * Business or technical event code for webhook (e.g., 'order.updated').
