import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IWebhookEvent } from "@ORGANIZATION/PROJECT-api/lib/structures/IWebhookEvent";

/**
 * Test updating an existing webhook event's delivery metadata and verify audit correctness. Also ensure API returns proper error for updating a non-existent or finalized event.
 *
 * Business Context:
 * Webhook events represent outbound notifications delivered through an omnichannel integration. Each event has full audit/evidence records and can be monitored/modified by the system for compliance and traceability. Updating delivery-state-related fields is key for compliance with SLAs, monitoring, and incident/audit analytics. Finalized (delivered) events shouldn't be modifiable for audit/evidence integrity.
 *
 * Test Steps:
 * 1. Create a new webhook event via the API dependency.
 * 2. Update the event's delivery metadata (attempt count, status, timestamps) using the update endpoint.
 * 3. Retrieve the updated event and validate that all fields are properly changed, including status, audit, and dates.
 * 4. Try to update a non-existent webhook event (random UUID) and assert the API returns a not found (404) or appropriate error for missing event.
 * 5. Mark event as delivered (simulate 'finalized' by setting delivered_at and status='success'), then attempt update again. Ensure the API rejects modification and returns the correct business error (finalized/locked for audit).
 */
export async function test_api_apiOmnichannel_test_update_webhook_event_metadata_and_fail_on_nonexistent(
  connection: api.IConnection,
) {
  // 1. Create webhook event for update test
  const createdEvent = await api.functional.apiOmnichannel.webhookEvents.post(connection, {
    body: {
      integration_channel_id: typia.random<string & tags.Format<'uuid'>>(),
      event_type: 'order.updated',
      destination_url: 'https://webhook.delivery.example/' + RandomGenerator.alphabets(8),
      event_hash: RandomGenerator.alphaNumeric(32)
    } satisfies IWebhookEvent.ICreate,
  });
  typia.assert(createdEvent);
  // 2. Update event metadata (simulate one delivery attempt, failed)
  const updateBody = {
    attempt_count: 1,
    last_attempted_at: new Date().toISOString(),
    delivery_status: 'failed',
    delivered_at: null,
  } satisfies IWebhookEvent.IUpdate;
  const updatedEvent = await api.functional.apiOmnichannel.webhookEvents.putById(connection, {
    id: createdEvent.id,
    body: updateBody,
  });
  typia.assert(updatedEvent);
  TestValidator.equals('attempt_count')(1)(updatedEvent.attempt_count);
  TestValidator.equals('delivery_status')('failed')(updatedEvent.delivery_status);
  TestValidator.equals('delivered_at')(null)(updatedEvent.delivered_at);
  // 3. Try to update a non-existent event (should error)
  await TestValidator.error('update non-existent event fails')(async () => {
    await api.functional.apiOmnichannel.webhookEvents.putById(connection, {
      id: typia.random<string & tags.Format<'uuid'>>(),
      body: updateBody,
    });
  });
  // 4. Mark event as delivered/finalized, then attempt update (should error)
  const deliveredUpdateBody = {
    delivered_at: new Date().toISOString(),
    delivery_status: 'success',
  } satisfies IWebhookEvent.IUpdate;
  const finalizedEvent = await api.functional.apiOmnichannel.webhookEvents.putById(connection, {
    id: createdEvent.id,
    body: deliveredUpdateBody,
  });
  typia.assert(finalizedEvent);
  TestValidator.equals('delivery_status')('success')(finalizedEvent.delivery_status);
  // Now, further update should be rejected (simulate audit lock)
  await TestValidator.error('update finalized (delivered) event fails')(async () => {
    await api.functional.apiOmnichannel.webhookEvents.putById(connection, {
      id: createdEvent.id,
      body: updateBody,
    });
  });
}

