import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IWebhookEvent } from "@ORGANIZATION/PROJECT-api/lib/structures/IWebhookEvent";

/**
 * Validate soft deletion (archival) of a webhook event and evidence preservation.
 * 
 * This test ensures that a webhook event can be soft-deleted (archived) and that the deletion preserves audit evidence. It also verifies robust error handling when attempting to delete an already-removed event and when trying to delete with an invalid or non-existent ID.
 *
 * Test steps:
 * 1. Create a new webhook event (as dependency for a valid deletion target)
 * 2. Soft-delete (archive) the webhook event and validate the returned evidence object
 * 3. Attempt to delete the same event a second time and confirm correct error or idempotency behavior
 * 4. Attempt to delete with a random/invalid ID and confirm error handling
 */
export async function test_api_apiOmnichannel_test_soft_delete_webhook_event_and_error_on_missing_id(
  connection: api.IConnection,
) {
  // 1. Create a webhook event for deletion
  const event = await api.functional.apiOmnichannel.webhookEvents.post(connection, {
    body: {
      integration_channel_id: typia.random<string & tags.Format<"uuid">>(),
      event_type: "order.updated",
      destination_url: "https://webhook-destination.example.com",
      event_hash: typia.random<string>(),
    } satisfies IWebhookEvent.ICreate,
  });
  typia.assert(event);

  // 2. Soft-delete (archive) the webhook event
  const deleted = await api.functional.apiOmnichannel.webhookEvents.eraseById(connection, {
    id: event.id,
  });
  typia.assert(deleted);
  TestValidator.equals("deleted id matches event id")(event.id)(deleted.id);
  TestValidator.equals("status is archived")("archived")(deleted.status);
  TestValidator.predicate("archived_at is date-time string")(
    !!deleted.archived_at && !isNaN(Date.parse(deleted.archived_at)),
  );

  // 3. Try to delete the same event again (should error or be idempotent as per business logic)
  await TestValidator.error("second delete should fail or be idempotent")(() =>
    api.functional.apiOmnichannel.webhookEvents.eraseById(connection, {
      id: event.id,
    }),
  );

  // 4. Try to delete a non-existent webhook event ID
  await TestValidator.error("delete with invalid/nonexistent id should error")(() =>
    api.functional.apiOmnichannel.webhookEvents.eraseById(connection, {
      id: typia.random<string & tags.Format<"uuid">>()
    }),
  );
}

