 *
 * Steps:
 * 1. Prepare a unique product_id (uuid string)
 * 2. POST with valid product option data (all required fields)
 * 3. Assert successful creation and correct response schema
 * 4. Try POST with missing each required field, expect validation error
 * 5. Try creating the same product option again (duplicate), expect constraint error
 *
 * Edge Cases:
 * - product_id must be a valid uuid (test invalid value if error logic exists)
 * - Empty or blank option_type and value fields
 */
export async function test_api_productCatalog_test_create_product_option_valid_and_invalid_data(
  connection: api.IConnection,
) {
  // 1. Generate a valid, unique product_id
  const product_id: string = typia.random<string & tags.Format<"uuid">>();
  const option_type: string = RandomGenerator.pick(["color", "size", "material"]);
  const value: string = RandomGenerator.alphabets(5);

  // 2. Successfully create a product option
  const created = await api.functional.productCatalog.productOptions.post(connection, {
    body: {
      product_id,
      option_type,
      value,
    } satisfies IProductOption.ICreate,
  });
