  TestValidator.equals("product_id")(product_id)(created.product_id);
  TestValidator.equals("option_type")(option_type)(created.option_type);
  TestValidator.equals("value")(value)(created.value);

  // 3. Try POST missing each required field (product_id)
  await TestValidator.error("missing product_id fails")(async () => {
    await api.functional.productCatalog.productOptions.post(connection, {
      body: {
        // product_id intentionally omitted
        option_type,
        value,
      } as any, // Should never use in production; for test illustration
    });
  });

  // 4. Try POST with missing option_type
