    await api.functional.productCatalog.productOptions.post(connection, {
      body: {
        product_id,
        // option_type omitted
        value,
      } as any,
    });
  });

  // 5. Try POST with missing value
  await TestValidator.error("missing value fails")(async () => {
    await api.functional.productCatalog.productOptions.post(connection, {
      body: {
        product_id,
        option_type,
        // value omitted
      } as any,
    });
