 *
 * This test simulates a catalog management/admin scenario (also applicable to AI/ML backend services) where multiple product tags must be listed, searched, and paginated via the patch API.
 *
 * Steps:
 * 1. Create multiple product tags with diverse, unique values (for search variety).
 * 2. Query the tag list without filters; confirm all (non-deleted) tags appear and pagination/meta is correct.
 * 3. Query with value-based (partial/fuzzy) filter; results must match the filtered tags only.
 * 4. Query with a limit/page size (e.g., 2 or 3 per page), iterate through pages; confirm correct slicing of data and pagination meta matches total count.
 * 5. Query for an out-of-bounds page (way beyond total pages); must yield an empty data array and correct pagination meta.
 * 6. Simulate deletion (soft-delete). If delete is truly unavailable, this is acknowledged and skipped.
 * 7. Confirm that deleted/soft-deleted tags do NOT appear in the listing/search results, only active tags are listed.
 *
 * Validation:
 * - Results must match supplied filters (e.g., search by unique value returns only expected tag[s]).
 * - Pagination meta (total records, pages, current, limit) must be consistent.
 * - Out-of-bounds page yields empty data.
 * - No deleted/soft-deleted tags in the results.
 */
export async function test_api_productCatalog_test_list_search_product_tags_with_filters_and_pagination(
  connection: api.IConnection,
) {
  // 1. Create multiple unique product tags (at least 4 for pagination variety)
  const tagValues = ArrayUtil.repeat(4)(i => `test-auto-tag-${RandomGenerator.alphaNumeric(6)}-${i}`);
  const createdTags = [];
  for (const tagValue of tagValues) {
    const tag = await api.functional.productCatalog.productTags.post(connection, {
      body: { value: tagValue } satisfies IProductTag.ICreate,
    });
    typia.assert(tag);
    createdTags.push(tag);
  }

  // 2. Query without filter
  const allResult = await api.functional.productCatalog.productTags.patch(connection, {
    body: {} satisfies IProductTag.IRequest,
  });
  typia.assert(allResult);
  for (const tagValue of tagValues) {
    TestValidator.predicate(`Should include created tag: ${tagValue}`)(allResult.data.some(t => t.value === tagValue));
  }

  // 3. Query with value-based filter (partial match)
  const testPrefix = tagValues[0].substring(0, Math.floor(tagValues[0].length / 2));
  const filteredResult = await api.functional.productCatalog.productTags.patch(connection, {
    body: { value: testPrefix } satisfies IProductTag.IRequest,
  });
  typia.assert(filteredResult);
  // Only tags matching the filter must be present
  TestValidator.predicate('Filter result matches')(filteredResult.data.every(t => t.value.includes(testPrefix)));

  // 4. Pagination: query pages (limit 2 per page)
  const pageSize = 2;
  let allPagedIds: string[] = [];
  for (let page = 1; page <= Math.ceil(tagValues.length / pageSize); ++page) {
    const paged = await api.functional.productCatalog.productTags.patch(connection, {
      body: {
        page,
        limit: pageSize,
      } satisfies IProductTag.IRequest,
    });
    typia.assert(paged);
    allPagedIds.push(...paged.data.map(t => t.id));
    // Pagination meta
    TestValidator.equals('current')(page)(paged.pagination.current);
    TestValidator.equals('limit')(pageSize)(paged.pagination.limit);
  }
  // All paged ids should include all created tags
  TestValidator.predicate('Paged covers all created')(tagValues.length <= allPagedIds.length);

  // 5. Out-of-bounds page (no results)
  const tooHighPage = 100;
  const emptyPaged = await api.functional.productCatalog.productTags.patch(connection, {
    body: { page: tooHighPage, limit: pageSize } satisfies IProductTag.IRequest,
  });
  typia.assert(emptyPaged);
  TestValidator.equals('empty data')(0)(emptyPaged.data.length);

