import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IProductTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IProductTag";

/**
 * 테스트 목적: 제품 태그 단일 조회(Get by ID) 기능의 다양한 동작 시나리오 검증
 *
 * 1. (정상) 실제 존재하는 product tag의 id로 조회를 시도하여 태그 데이터가 정확히 반환됨을 검증한다.
 * 2. (에러) 존재하지 않는 UUID로 요청 시 404 Not Found 에러가 발생하는지 검증한다.
 * 3. (에러/특이케이스) (만약 soft delete가 구현되어 있다면) 삭제된 태그 id로 요청 시 적절한 에러 혹은 null/404 반환을 확인한다.
 *
 * 준비 작업: 사전 productTag 1개를 신규 생성(post)하여 실제 id를 준비해야 하며, 별도 삭제 동작은 해당 시스템이 soft/hard delete를 지원하는지에 따라 분기한다.
 *
 * Step by Step:
 * 1. (사전 준비) productTag 생성 API로 태그를 하나 만든다.
 * 2. 정상 케이스: 생성된 태그의 id로 getById 요청, 응답 데이터가 방금 만든 데이터와 일치하는지 검증
 * 3. 비정상 케이스: 랜덤한(존재 불가능한) UUID로 getById 요청 시 404 에러 반환 확인
 * 4. (선택) 삭제 동작과 soft delete가 지원된다면, 태그를 삭제 후(별도의 delete API 필요) 동일 id로 재조회 시 결과 확인 (본 테스트에서는 삭제 API/플로우가 없는 관계로 생략)
 *
 * 비즈니스적 검증포인트:
 * - 입력한 value 유일성 및 id와 일치 검증
 * - 404 에러 발생시 명확한 예외 처리 검증
 */
export async function test_api_productCatalog_test_get_product_tag_by_id_various_scenarios(connection: api.IConnection) {
  // 1. 사전 준비: 태그 1개를 생성
  const tagCreateInput: IProductTag.ICreate = {
    value: RandomGenerator.alphaNumeric(10),
  };
  const createdTag: IProductTag = await api.functional.productCatalog.productTags.post(connection, { body: tagCreateInput });
  typia.assert(createdTag);

  // 2. 정상 케이스: 생성된 태그 id로 조회
  const fetchedTag: IProductTag = await api.functional.productCatalog.productTags.getById(connection, { id: createdTag.id });
  typia.assert(fetchedTag);
  TestValidator.equals("id 일치")(createdTag.id)(fetchedTag.id);
  TestValidator.equals("value 일치")(createdTag.value)(fetchedTag.value);
  TestValidator.equals("created_at 일치")(createdTag.created_at)(fetchedTag.created_at);

  // 3. 비정상 케이스: 존재하지 않는 id로 조회시 404 에러
  await TestValidator.error("없는 태그 id로 조회시 404 반환")(async () => {
    await api.functional.productCatalog.productTags.getById(connection, { id: typia.random<string & tags.Format<"uuid">>() });
  });

  // 4. 삭제/soft-delete 케이스는 본 API SDK에 지원 불가로 생략함.
}

