import api from "@ORGANIZATION/PROJECT-api";
import type { IProductTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IProductTag";

/**
 * 제품 태그 단일 조회 API(getById)의 정상 및 예외 시나리오 검증 E2E
 *
 * 비즈니스 맥락:
 * - 카탈로그의 productTag는 AI 추천, 검색 필터 등에 쓰이는 핵심 메타 데이터로, 유일성과 신뢰성이 중요하다.
 * - 단일 태그 레코드는 UUID로 PK 관리되므로, 정확한 단일조회와 404 처리 등이 필수적이다.
 *
 * [과정 요약]
 * 1. productTag를 직접 하나 생성한다. (단일조회 테스트용 id 확보)
 * 2. 생성된 id로 getById API를 호출해 실제로 방금 저장한 데이터와 완벽히 일치하는지 검증한다.
 * 3. 존재하지 않는 무작위 UUID로 요청 시 404 not found 오류 발생 여부를 체크한다.
 * 4. (현재 Delete/soft-delete API 미지원 관계로 삭제 후 재조회 케이스 생략)
 *
 * [주요 검증 포인트]
 * - 정상조회: id, value, created_at 등 전체 속성이 완전불일치 없이 반환되는가
 * - 예외: 미존재 id에 대해 정확히 404 error 또는 예외가 발생하는가
 */
export async function test_api_productCatalog_test_get_product_tag_by_id_various_scenarios(
  connection: api.IConnection,
) {
  // 1. 사전 productTag 생성 (정상 id 확보)
  const tagCreateInput: IProductTag.ICreate = {
    value: RandomGenerator.alphaNumeric(10),
  };
  const createdTag: IProductTag = await api.functional.productCatalog.productTags.post(connection, { body: tagCreateInput });
  typia.assert(createdTag);

  // 2. 정상조회: 바로 생성한 id로 단일조회
  const fetchedTag: IProductTag = await api.functional.productCatalog.productTags.getById(connection, { id: createdTag.id });
  typia.assert(fetchedTag);
  TestValidator.equals("id 일치")(createdTag.id)(fetchedTag.id);
  TestValidator.equals("value 일치")(createdTag.value)(fetchedTag.value);
  TestValidator.equals("created_at 일치")(createdTag.created_at)(fetchedTag.created_at);

  // 3. 비정상: 존재하지 않는 UUID로 단일조회 → 404 반환 검증
  await TestValidator.error("존재하지 않는 태그 id여야 404 난다")(async () => {
    await api.functional.productCatalog.productTags.getById(connection, { id: typia.random<string & tags.Format<"uuid">>() });
  });

  // 4. 삭제 후 재조회 케이스(soft/hard delete)는 미지원이므로 생략
}

