 *   - 이미 존재하는 value(선행 생성 태그의 value)로 update 요청 시 유니크 제약 오류를 반환하는지 확인합니다.
 *
 * 3. "value 필드 미입력":
 *   - value 필드를 명시적으로 입력하지 않고 update 시도 시(정의상 value는 optional임), 기존 값이 변경되지 않고,
 *     응답의 value가 기존 value와 동일한지 확인합니다.
 *
 * 4. "존재하지 않는 ID":
 *   - 존재하지 않는 UUID로 update 시 HTTP 404 오류 등 적절한 에러가 반환되는지 확인합니다.
 *
 * 참고: 비즈니스 정책상 태그 엔터티는 임의 삭제가 불가하므로, 삭제 상태 테스트 대신 "없는 id 사용"만 검증합니다.
 */
export async function test_api_productCatalog_test_update_product_tag_various_conditions(
  connection: api.IConnection,
) {
  // 1. 사전 데이터 준비 - 태그 2개 생성
  const initialTag = await api.functional.productCatalog.productTags.post(connection, {
    body: { value: `테스트태그_${RandomGenerator.alphabets(8)}` } satisfies IProductTag.ICreate,
  });
  typia.assert(initialTag);

  const duplicateTag = await api.functional.productCatalog.productTags.post(connection, {
    body: { value: `중복체크_${RandomGenerator.alphabets(8)}` } satisfies IProductTag.ICreate,
  });
  typia.assert(duplicateTag);

  // 2. 정상 업데이트: value 값 변경
  const newValue = `수정후값_${RandomGenerator.alphabets(8)}`;
  const updated = await api.functional.productCatalog.productTags.putById(connection, {
    id: initialTag.id,
    body: { value: newValue } satisfies IProductTag.IUpdate,
  });
  typia.assert(updated);
  TestValidator.equals("value 업데이트반영")(newValue)(updated.value);

  // 3. value 중복 업데이트 시도 (UNIQUE 제약)
  await TestValidator.error("value 중복 에러")(() =>
    api.functional.productCatalog.productTags.putById(connection, {
      id: updated.id,
      body: { value: duplicateTag.value } satisfies IProductTag.IUpdate,
    }),
  );

  // 4. value 미입력 시도 (undefined) – 기존 값 유지
  const keepValueResp = await api.functional.productCatalog.productTags.putById(connection, {
    id: updated.id,
    body: { } satisfies IProductTag.IUpdate,
  });
  typia.assert(keepValueResp);
  TestValidator.equals("value 변경없음")(updated.value)(keepValueResp.value);

  // 5. 존재하지 않는 태그 id로 업데이트 시도 (404)
  await TestValidator.error("없는 id 에러")(() =>
    api.functional.productCatalog.productTags.putById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
      body: { value: `임의_${RandomGenerator.alphabets(8)}` } satisfies IProductTag.IUpdate,
    }),
  );
}

