import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IProductTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IProductTag";
import type { IDeleteResponse } from "@ORGANIZATION/PROJECT-api/lib/structures/IDeleteResponse";

/**
 * 제품 태그의 삭제(논리 삭제/아카이브) 기능 검증 및 오류 상황 처리 테스트.
 *
 * 1. 제품 태그를 하나 생성한다.
 * 2. 해당 태그를 정상적으로 삭제(아카이브/soft-delete)한다.
 *    - 반환 결과의 id와 status, deletedAt이 정확히 채워져 있는지 검증한다.
 * 3. 삭제된 태그 id로 다시 삭제 요청 시도 시 에러 발생을 확인한다.
 * 4. 존재하지 않는 랜덤 UUID로 삭제 시도 시도 시 적절한 에러 반환을 검증한다.
 * 5. 현재 할당 중(active)인 제품에서 사용되고 있는 태그라면, 삭제 시 참조 무결성 오류가 발생함을 검증한다.
 *    - (단, 실제 참조 중인 product 엔터티/연결관계가 없으면 본 테스트는 스킵할 수 있음)
 *
 * 상세 절차:
 *
 * 1. api.functional.productCatalog.productTags.post로 테스트용 태그를 만든다.
 * 2. api.functional.productCatalog.productTags.eraseById로 정상 삭제 요청 및 결과를 검증한다.
 * 3. 같은 id로 한번 더 삭제 요청 시, 예외/에러 반환을 확인한다.
 * 4. typia.random<string & tags.Format<"uuid">>() 등으로 생성한 임의 UUID로 삭제 시, 에러 상황도 추가 검증한다.
 * 5. (선택) 실제로 사용 중인 태그 id(별도 생성 혹은 셋업 필요)로 삭제 시도시, 참조 무결성 위반/에러발생 확인.
 */
export async function test_api_productCatalog_test_delete_product_tag_and_error_conditions(
  connection: api.IConnection,
) {
  // 1. 신규 제품 태그 생성
  const tag = await api.functional.productCatalog.productTags.post(connection, {
    body: {
      value: RandomGenerator.alphaNumeric(16)
    } satisfies IProductTag.ICreate
  });
  typia.assert(tag);

  // 2. 정상 삭제 시도 및 삭제/아카이빙 결과값 검증
  const deleted = await api.functional.productCatalog.productTags.eraseById(connection, {
    id: tag.id
  });
  typia.assert(deleted);
  TestValidator.equals("deleted id")(tag.id)(deleted.id);
  TestValidator.equals("deleted status")("deleted")(deleted.status);
  TestValidator.predicate("deletedAt exists")(
    typeof deleted.deletedAt === 'string' && deleted.deletedAt.length > 0
  );

  // 3. 이미 삭제된 id로 또 삭제 요청 → 에러
  await TestValidator.error("already deleted tag")(() =>
    api.functional.productCatalog.productTags.eraseById(connection, {
      id: tag.id
    })
  );

  // 4. 임의의 랜덤 uuid로 삭제 요청 → non-existent error
  await TestValidator.error("not found tag")(() =>
    api.functional.productCatalog.productTags.eraseById(connection, {
      id: typia.random<string & tags.Format<"uuid">>()
    })
  );

  // 5. (참조 무결성) 실제 사용 중인 tag id는 별도 참조 데이터 필요하므로,
  // 실제 사용 제품을 별도 생성 연결할 수 있거나, 제품 태그 할당 API 정보가 있을 때 테스트 확장 가능
}

