    typeof deleted.deletedAt === "string" && deleted.deletedAt.length > 0,
  );

  // 3. 이미 삭제된 태그 id로 재삭제 요청 (에러 검증)
  await TestValidator.error("already deleted tag")(() =>
    api.functional.productCatalog.productTags.eraseById(connection, {
      id: tag.id,
    }),
  );

  // 4. 존재하지 않는 랜덤 uuid로 삭제 요청 (not found 에러 검증)
  await TestValidator.error("not found tag")(() =>
    api.functional.productCatalog.productTags.eraseById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
    }),
  );

  // 5. (참조 무결성) 실제로 제품에 연결되어 사용중인 tag에 대한 삭제는 별도의 제품 셋업이 필요
  // 본 테스트에서는 제품과의 연결관계 API/데이터 셋업이 없는 경우, 해당 케이스는 스킵 가능
}

