import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IProductMedia } from "@ORGANIZATION/PROJECT-api/lib/structures/IProductMedia";
import type { IPageIProductMedia } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIProductMedia";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * 제품 미디어(디지털 에셋) 목록/검색 API의 동작을 검증.
 *
 * 다양한 필터(media_type, locale, alt_text, product_id, product_variant_id, 생성일자 범위 등) 및 페이지네이션(offset/limit, 정렬) 조건을 모두 조합(AND 조건 우선)해 반환되는 Media 목록이 정확히 필터됨을 검증한다.
 *
 * - 미디어 등록: 먼저 충분히 다양한 조건으로(다국어, 여러 media_type, 서로 다른 alt_text, 여러 product/variant 관계) 미디어 여러 건을 생성한다.
 *   이때 편의상 한 product_id는 랜덤 생성, 2~3건은 product_variant_id로 등록한다.
 * - 필터링: 생성된 데이터에 맞는 다양한 조합으로 미디어 검색을 실행한다. locale별 검색, media_type별, alt_text 부분검색 등
 *   반환된 목록의 각 Media가 필터 조건을 반드시 충족하는지 체크한다(부분 검색은 포함 여부).
 * - 페이지네이션: limit=2 등 소수로 지정하여 여러 페이지에 걸쳐 데이터가 끊어짐을 확인한다.
 *   여러 페이지를 순차 조회해서 전체 데이터 대비 누락 없음을 보장.
 *   offset=음수(에러), offset/limit 누락(default 동작) 케이스도 함께 검증.
 * - 삭제(archived)된 미디어가 목록 결과에 나타나지 않음을 검증한다(삭제는 이후의 확장일 수 있으므로 우선 생성/검색에서 미반영).
 * - page를 넘겨가며 범위를 모두 초과한 경우 빈 배열 반환도 체크(데이터 개수+10 등 크게 offset).
 *
 * 1. 미디어 5~7개를 생성(조건 다양화)
 * 2. 각종 필터별로 검색 요청을 보내 반환값의 Media가 인풋과 일치하는지 assert
 * 3. 페이지네이션 테스트: limit/offset으로 여러 페이지를 조회, 전체 합산 결과가 모두 존재하는지 확인
 * 4. 범위를 벗어난 페이지 요청에 빈 배열 결과 assert
 */
export async function test_api_productCatalog_test_list_search_product_media_with_filters_and_pagination(
  connection: api.IConnection,
) {
  // 1. 다양한 조건(minimum 7건)으로 ProductMedia 생성
  const medias = await ArrayUtil.asyncRepeat(7)(async (_, i) => {
    return await api.functional.productCatalog.productMedia.post(connection, {
      body: {
        product_id: i % 2 === 0
          ? typia.random<string & tags.Format<"uuid">>()
          : undefined,
        product_variant_id: i % 2 !== 0
          ? typia.random<string & tags.Format<"uuid">>()
          : undefined,
        uri: `https://media.example.com/asset_${i}.jpg`,
        media_type: i % 3 === 0 ? "image" : i % 3 === 1 ? "video" : "pdf",
        locale: i % 2 === 0 ? "en-US" : "ko-KR",
        alt_text: `테스트 에셋 ${i} 한글 alt`,
      } satisfies IProductMedia.ICreate,
    });
  });
  medias.forEach(typia.assert);

  // 2. media_type별 필터 검색 및 검증
