import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IProductMedia } from "@ORGANIZATION/PROJECT-api/lib/structures/IProductMedia";

/**
 * Test product media retrieval by ID including success, not-found, and deleted cases.
 *
 * 1. Create a new product media as a fixture (required for 'success' + 'deleted' queries).
 * 2. Retrieve the product media by its ID - validate all fields and metadata are present and correct.
 * 3. Attempt to retrieve a product media record using a non-existent UUID - expect a 404 error.
 * 4. (Soft-delete/archive scenario) - If there is a built-in way to 'archive/soft-delete' media, perform it, then try to retrieve and confirm correct behavior (404, error, or known API response).
 * Note: If no soft-delete/archive is implemented, step 4 may be omitted; document in code.
 */
export async function test_api_productmedia_test_get_product_media_by_id_success_and_failure_cases(
  connection: api.IConnection,
) {
  // 1. Create fixture product media
  const createInput: IProductMedia.ICreate = {
    uri: RandomGenerator.alphaNumeric(32),
    media_type: RandomGenerator.pick(["image","video","pdf"]),
    locale: "ko-KR",
    alt_text: RandomGenerator.paragraph()(),
    // product_id or product_variant_id must be set, set one
    product_id: typia.random<string & tags.Format<"uuid">>(),
  };
  const created: IProductMedia = await api.functional.productCatalog.productMedia.post(connection, { body: createInput });
  typia.assert(created);

  // 2. Retrieve by ID (success)
  const found: IProductMedia = await api.functional.productCatalog.productMedia.getById(connection, { id: created.id });
  typia.assert(found);
  TestValidator.equals("product media id")(created.id)(found.id);

  // 3. Retrieve by non-existent ID (fail)
  await TestValidator.error("non-existent product media should 404")(async () => {
    await api.functional.productCatalog.productMedia.getById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(), // unlikely to exist
    });
  });

  // 4. (Soft-delete/archive test): Only if supported by the API.
  // (No API for archive/delete given, so just add a placeholder comment.)
}

