import { IConnection, HttpError } from "@nestia/fetcher";
import { PlainFetcher } from "@nestia/fetcher/lib/PlainFetcher";
import typia from "typia";
import { NestiaSimulator } from "@nestia/fetcher/lib/NestiaSimulator";

import { IProductMedia } from "../../../structures/IProductMedia";

/**
 * Creates a new product media record in ProductCatalog.product_media.
 *
 * Creates a new atomic digital asset record, conforming to the product_media
 * table schema. Supports secure asset URI, type, locale, alt-text, provenance,
 * and is fully auditable for accessibility and regulatory compliance.
 *
 * Access is limited to catalog managers, asset uploaders or AI/ML asset
 * enrichment processes as defined by RBAC. The input references
 * IProductMedia.ICreate—validating mandatory fields and checking referential
 * constraints (product_id/product_variant_id).
 *
 * Audit entries are triggered on creation, supporting evidence preservation and
 * regulatory trace requirements. Output is full record of inserted asset,
 * useful for downstream data enrichment, accessibility pipeline confirmation or
 * ML training workflows.
 *
 * Other asset management endpoints are recommended for use in batch/import
 * flows or integrated AI asset enrichment loops.
 *
 * @param props.connection
 * @param props.body New product media asset information.
 * @path /productCatalog/productMedia
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export async function post(
  connection: IConnection,
  props: post.Props,
): Promise<post.Response> {
  return !!connection.simulate
    ? post.simulate(connection, props)
    : PlainFetcher.fetch(
        {
          ...connection,
          headers: {
            ...connection.headers,
            "Content-Type": "application/json",
          },
        },
        {
          ...post.METADATA,
          path: post.path(),
          status: null,
        },
        props.body,
      );
}
export namespace post {
  export type Props = {
    /** New product media asset information. */
    body: IProductMedia.ICreate;
  };
  export type Body = IProductMedia.ICreate;
  export type Response = IProductMedia;

  export const METADATA = {
    method: "POST",
    path: "/productCatalog/productMedia",
    request: {
      type: "application/json",
      encrypted: false,
    },
    response: {
      type: "application/json",
      encrypted: false,
    },
  } as const;

  export const path = () => "/productCatalog/productMedia";
  export const random = (g?: Partial<typia.IRandomGenerator>): IProductMedia =>
    typia.random<IProductMedia>(g);
  export const simulate = (
    connection: IConnection,
    props: post.Props,
  ): Response => {
    const assert = NestiaSimulator.assert({
      method: METADATA.method,
      host: connection.host,
      path: post.path(),
      contentType: "application/json",
    });
    try {
      assert.body(() => typia.assert(props.body));
    } catch (exp) {
      if (!typia.is<HttpError>(exp)) throw exp;
      return {
        success: false,
        status: exp.status,
        headers: exp.headers,
        data: exp.toJSON().message,
      } as any;
    }
    return random(
      "object" === typeof connection.simulate && null !== connection.simulate
        ? connection.simulate
        : undefined,
    );
  };
}

