import { tags } from "typia";

/**
 * 제품에 연결된 디지털 에셋(이미지, 비디오 등)의 메타데이터 개체로, ProductMedia는 엄격히 단일 파일 단위를 가집니다.
 *
 * 다국어, 다문화, 접근성(a11y) 표준, AI 파이프라인, 감사/증적 요구사항 모두 만족하며, 제품별/옵션별로 다수 생성될 수 있습니다.
 *
 * 모든 필드는 3NF 정상화를 보장하며, 파일/BLOB은 외부 저장에 URI만 DB에 저장합니다.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IProductMedia = {
  /**
   * 제품 미디어 고유 식별자(UUID). PK 역할입니다.
   *
   * Prisma product_media.id 컬럼.
   */
  id: string & tags.Format<"uuid">;

  /**
   * 연결된 제품의 UUID. Null 가능.
   *
   * Prisma product_media.product_id 컬럼.
   */
  product_id?: string & tags.Format<"uuid">;

  /**
   * 연결된 옵션(Variant) UUID. Null 가능. 제품 또는 옵션 중 하나만 연결.
   *
   * Prisma product_media.product_variant_id 컬럼.
   */
  product_variant_id?: string & tags.Format<"uuid">;

  /**
   * 원본 디지털 에셋(이미지/영상/PDF 등) URI.
   *
   * 실제 파일은 별도 저장소에 위치.
   */
  uri: string;

  /** 미디어 타입(예: 'image', 'video', 'pdf' 등). ML/추천엔진 문맥 추론에도 사용. */
  media_type: string;

  /** 미디어의 다국어/다문화 구분 로케일 코드. 접근성(a11y) 및 글로벌 검색에 필수. */
  locale: string;

  /**
   * 접근성(a11y) 준수를 위한 Alt Text. WCAG 표준 등 글로벌 규격 반영.
   *
   * 모든 이미지/미디어마다 반드시 제공해야 하며 AI 학습에도 활용.
   */
  alt_text: string;

  /** 미디어가 생성된 시각. 인덱싱, 감사, AI 분석 등에서 사용합니다. */
  created_at: string & tags.Format<"date-time">;
};
export namespace IProductMedia {
  /**
   * 신규 제품 미디어(이미지/영상 등) 등록을 위한 입력 타입입니다.
   *
   * 접근성, 글로벌 다국어, AI 기반 분류, 증적 보전 등 필수 데이터만 입력 가능합니다. product_id,
   * product_variant_id는 둘 중 하나 반드시 필요.
   */
  export type ICreate = {
    /** 이 미디어가 연결될 제품 UUID. product_id와 product_variant_id 중 반드시 한 개는 세팅 필요. */
    product_id?: string & tags.Format<"uuid">;

    /** 이 미디어가 연결될 옵션(Variant) UUID. null 허용. */
    product_variant_id?: string & tags.Format<"uuid">;

    /** 업로드 후 저장소 내 디지털 에셋 URI. 실제 값은 파일 관리 시스템에서 할당. */
    uri: string;

    /** 미디어 타입(예: 'image', 'video' 등). AI/ML 인식에도 활용됨. */
    media_type: string;

    /** 다국어/다문화 구분. ISO/BPC47 표기 필수. */
    locale: string;

    /** 접근성(a11y) 표준에 부합하는 Alt Text. AI 파이프라인, 콘텐츠 감사, 글로벌 서비스 필수. */
    alt_text: string;
  };

  /**
   * 기존 제품 미디어의 메타 정보(URI, 타입, 로케일, 접근성)를 수정할 때 사용하는 타입.
   *
   * 메타 정보 이외의 연결(product/variant)은 불변 원칙(정책상 예외는 반드시 증적 추적 필수)
   */
  export type IUpdate = {
    /** 이미 업로드된 디지털 에셋의 URI(경로)를 수정할 때 사용(실제 변경은 예외적 상황만 허용). */
    uri?: string;

    /** 미디어타입 수정(타입 실수/부정확 시 통제차원에서만 변경 허용). */
    media_type?: string;

    /** 다국어/지역코드 수정. */
    locale?: string;

    /** 이미지/영상 접근성 텍스트(a11y)를 수정. 이력은 반드시 감사 로그에 남겨야 함. */
    alt_text?: string;
  };
}

