import type { IProductMedia } from "@ORGANIZATION/PROJECT-api/lib/structures/IProductMedia";

/**
 * E2E 테스트 - 제품 미디어 정보 업데이트 시나리오
 *
 * 이 테스트는 다음 시나리오 전체 흐름을 검증합니다:
 *
 * 1. 최초로 정상적인 제품 미디어 레코드(디지털 에셋 메타데이터)를 생성한다.
 * 2. 해당 미디어 레코드의 URI/미디어타입/로케일/Alt Text 등 주요 메타 정보를 부분 혹은 전체적으로 정상 값으로 변경해 본다.
 *    - 변경 후 값이 실 DB까지 반영됨을 검증(응답 바디, re-get 값 비교 등)
 * 3. 주요 필드(예: URI 없음, locale 등) 결손/불완전/잘못된 값으로 업데이트 시도를 하여 유효성 검사 오류, 400/422 등 에러를 정상 검출 및 메시지/상태코드 확인
 * 4. 존재하지 않거나 이미 삭제된 id를 대상으로 업데이트를 시도하여 404 Not Found/410 Gone 등 적절한 에러 코드와 메시지가 발생하는지 검사
 *
 * 검증 항목:
 * - 정상 입력 시 메타정보 반영 여부
 * - 필수 필드 결손/오류 시 에러 처리(400 계열)
 * - 잘못된(존재하지 않거나 삭제된) id 대상으로 업데이트 시 에러 처리(404/410 계열)
 *
 * 각 단계마다 typia.assert 및 TestValidator를 통한 타입/비즈니스 규칙 검증을 병행한다.
 */
export async function test_api_productMedia_test_update_product_media_by_id_various_scenarios(connection: api.IConnection) {
  // 1. 미디어 레코드 생성 (사전 데이터 구축)
  const createInput: IProductMedia.ICreate = {
    product_id: typia.random<string & tags.Format<"uuid">>(),
    uri: `https://cdn.example.com/media/${typia.random<string & tags.Format<"uuid">>()}.jpg`,
    media_type: "image",
    locale: "ko-KR",
    alt_text: "샘플 이미지(접근성용 텍스트)",
  };
  const media = await api.functional.productCatalog.productMedia.post(connection, { body: createInput });
  typia.assert(media);

  // 2. 정상 메타정보 업데이트
  const updatedUri = `https://cdn.example.com/media/${typia.random<string & tags.Format<"uuid">>()}.jpeg`;
  const updatedAlt = "(수정) 접근성 보장용 대체텍스트";
  const updateRes = await api.functional.productCatalog.productMedia.putById(connection, {
    id: media.id,
    body: {
      uri: updatedUri,
      alt_text: updatedAlt,
    }
  });
  typia.assert(updateRes);
  TestValidator.equals("id 동일성")(media.id)(updateRes.id);
  TestValidator.equals("URI 필드 변경")(updatedUri)(updateRes.uri);
  TestValidator.equals("alt_text 필드 변경")(updatedAlt)(updateRes.alt_text);

