  await TestValidator.error("alt_text 누락 시 오류")(() =>
    api.functional.productCatalog.productMedia.putById(connection, {
      id: media.id,
      body: {
        uri: "https://cdn.example.com/media/newfile.jpg"
        // alt_text 미제공 -> 접근성 정책 위배 예상
      },
    })
  );

  // 4. 존재하지 않는 id로 업데이트(404 체크)
  const nonexistentId = typia.random<string & tags.Format<"uuid">>()
  await TestValidator.error("존재하지 않는 미디어 ID에는 404 오류")(async () =>
    api.functional.productCatalog.productMedia.putById(connection, {
      id: nonexistentId,
      body: { uri: "https://cdn.example.com/media/noexist.jpg", alt_text: "nope" },
    })
  );
}

