export namespace IProductMedia {
  /**
   * 신규 제품 미디어(이미지/영상 등) 등록을 위한 입력 타입입니다.
   *
   * 접근성, 글로벌 다국어, AI 기반 분류, 증적 보전 등 필수 데이터만 입력 가능합니다. product_id,
