  };
  const media = await api.functional.productCatalog.productMedia.post(connection, { body: createInput });
  typia.assert(media);

  // 2. 정상 삭제(soft-delete/archival)
  const deleteResp = await api.functional.productCatalog.productMedia.eraseById(connection, { id: media.id });
  typia.assert(deleteResp);
  TestValidator.equals("delete status")(deleteResp.status)("deleted"); // 정책상 deleted/archived 구분

