    api.functional.productCatalog.productMedia.eraseById(connection, { id: media.id }),
  );

  // 5. 존재하지 않는 임의 UUID로 삭제 시도 → 오류
  await TestValidator.error("존재하지 않는 미디어 ID 삭제")(() =>
    api.functional.productCatalog.productMedia.eraseById(connection, { id: typia.random<string & tags.Format<"uuid">>() }),
  );

  // 6. (Referential integrity test: 제품/옵션 참조 시 삭제 불가/허용)
  // 본 예제에서는 제품 연결 미디어 생성 및 참조 삭제 제한 정책 명세가 없으므로, 실제 정책에 따라 추가 구현
