import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IInventory } from "@ORGANIZATION/PROJECT-api/lib/structures/IInventory";
import type { IPageIInventory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIInventory";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IProductCatalogProductVariant } from "@ORGANIZATION/PROJECT-api/lib/structures/IProductCatalogProductVariant";

/**
 * Inventory search and paging E2E coverage.
 *
 * This test verifies end-to-end functionality for the inventory search endpoint in the product catalog. 
 * Business goal: Confirm that inventory listing/search with multiple filters and paging works as expected,
 * honors product/variant constraints, and properly handles edge cases including deletion and out-of-bounds pagination.
 *
 * Steps:
 * 1. Create several product variants and their associated inventory records with different stock counts and last_modified_at timestamps.
 * 2. List inventory with no filters, assert full result set with default paging.
 * 3. Search inventory by specific product_variant_id, confirm result consists only of records for that variant.
 * 4. Search inventory with stock_from/stock_to range boundaries, check only matching inventories returned.
 * 5. Search inventory using last_modified_from/last_modified_to for timestamp range, ensure results fall within limits.
 * 6. Test pagination: request limit=2, offset=0,1,2 etc. Check returned data matches correct page and order.
 * 7. (Optional/Placeholder) Delete an associated product/variant (if possible in the system, placeholder only if product deletion is not supported),
 *    then search inventory – confirm either record is absent, or system returns correct status (specification dependent).
 * 8. Query with offset past all available records, confirm data array is empty and page meta matches empty set.
 */
export async function test_api_productCatalog_test_list_search_inventory_with_filters_and_pagination(
  connection: api.IConnection,
) {
  // Step 1: Create multiple inventory records for different variants
  const variantIds: string[] = [];
  const createdInventories: IInventory[] = [];
  const baseStock = 10;
  const now = new Date();
  for (let i = 0; i < 4; ++i) {
    // Simulate unique product_variant_id per record
    const variant_id = typia.random<string & tags.Format<"uuid">>();
    variantIds.push(variant_id);
    const stock_count = baseStock + i * 5;
    const last_modified_at = new Date(now.getTime() - (i * 1000000)).toISOString();
    const created = await api.functional.productCatalog.inventory.post(connection, {
      body: {
        product_variant_id: variant_id,
        stock_count,
        last_modified_at,
      } satisfies IInventory.ICreate,
    });
    typia.assert(created);
    createdInventories.push(created);
  }

  // Step 2: List inventory with no filters (should return all just-created records at minimum)
  const unfilteredResult = await api.functional.productCatalog.inventory.patch(connection, {
    body: {}, // no filters applied
  });
  typia.assert(unfilteredResult);
  // Assert the test records are present (by product_variant_id)
  for (const inv of createdInventories) {
    const found = unfilteredResult.data.some((r) => r.id === inv.id);
    TestValidator.predicate(`Inventory ${inv.id} found in unfiltered results`)(found);
  }

  // Step 3: Search inventory by specific product_variant_id (use first)
  const searchVariantId = variantIds[1];
  const variantIdResult = await api.functional.productCatalog.inventory.patch(connection, {
    body: { product_variant_id: searchVariantId },
  });
  typia.assert(variantIdResult);
  TestValidator.equals("variant filtered count")(1)(variantIdResult.data.length);
  TestValidator.equals("variant id matches")(searchVariantId)(variantIdResult.data[0]?.product_variant_id);

  // Step 4: Search with stock_from/stock_to
  const midStockFrom = baseStock+3;
  const midStockTo = baseStock+10;
  const midStockResult = await api.functional.productCatalog.inventory.patch(connection, {
    body: { stock_from: midStockFrom, stock_to: midStockTo },
  });
  typia.assert(midStockResult);
  for (const inv of midStockResult.data) {
    TestValidator.predicate(`stock_count in range`)(inv.stock_count >= midStockFrom && inv.stock_count <= midStockTo);
  }

  // Step 5: Search using last_modified_from/last_modified_to
  const timeFrom = new Date(now.getTime() - 2000000).toISOString();
  const timeTo = now.toISOString();
  const timeRangeResult = await api.functional.productCatalog.inventory.patch(connection, {
    body: { last_modified_from: timeFrom, last_modified_to: timeTo },
  });
  typia.assert(timeRangeResult);
  for (const inv of timeRangeResult.data) {
    TestValidator.predicate(`last_modified_at in range`)(new Date(inv.last_modified_at) >= new Date(timeFrom)
      && new Date(inv.last_modified_at) <= new Date(timeTo));
  }

  // Step 6: Pagination test - limit=2, offset=0,1,2
  const pagedResult0 = await api.functional.productCatalog.inventory.patch(connection, {
    body: { limit: 2, offset: 0 },
  });
  typia.assert(pagedResult0);
  TestValidator.equals("limit")(2)(pagedResult0.pagination.limit);
