import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IInventory } from "@ORGANIZATION/PROJECT-api/lib/structures/IInventory";
import type { IProductCatalogProductVariant } from "@ORGANIZATION/PROJECT-api/lib/structures/IProductCatalogProductVariant";

/**
 * Validate the full update lifecycle of inventory records via PUT /productCatalog/inventory/{id}.
 *
 * This test covers both successful and failure scenarios for inventory updates. It ensures that:
 *   - Updating an existing record with legitimate changes (such as changing stock_count, updating timestamps) works correctly
 *   - Invalid updates (such as setting stock_count to a negative number, missing required fields) result in appropriate errors
 *   - Attempting to update a non-existent inventory record or a deleted record returns a failure as expected
 *
 * Steps:
 * 1. Create a valid inventory record for update testing using the POST endpoint.
 * 2. Update the record using PUT /productCatalog/inventory/{id} with legitimate changes and verify that the update is reflected accurately.
 * 3. Attempt to update the same record with a negative stock_count (invalid) and ensure the API returns a proper error.
 * 4. Attempt to update with missing all fields (empty body) and confirm validation failure.
 * 5. Attempt to update a random (non-existent) UUID and validate that not found error is returned.
 */
export async function test_api_inventory_test_update_inventory_record_by_id_various(connection: api.IConnection) {
  // 1. Create a valid inventory record
  const product_variant_id = typia.random<string & tags.Format<"uuid">>();
  const stock_count = typia.random<number & tags.Type<"int32"> & tags.Minimum<1> & tags.Maximum<1000>>();
  const createdInventory = await api.functional.productCatalog.inventory.post(
    connection,
    {
      body: {
        product_variant_id,
        stock_count,
        last_modified_at: new Date().toISOString(),
      } satisfies IInventory.ICreate
    },
  );
  typia.assert(createdInventory);

  // 2. Successful update: valid stock_count and new last_modified_at
  const updatedStockCount = stock_count + 7;
  const updatedLastModifiedAt = new Date(Date.now() + 1000 * 60).toISOString();
  const updatedInventory = await api.functional.productCatalog.inventory.putById(
    connection,
    {
      id: createdInventory.id,
      body: {
        stock_count: updatedStockCount,
        last_modified_at: updatedLastModifiedAt,
      } satisfies IInventory.IUpdate,
    },
  );
  typia.assert(updatedInventory);
  TestValidator.equals("updated stock_count")(updatedStockCount)(updatedInventory.stock_count);
  TestValidator.equals("updated last_modified_at")(updatedLastModifiedAt)(updatedInventory.last_modified_at);

  // 3. Failure: Attempt to update with a negative stock_count
  await TestValidator.error("negative stock_count rejected")(async () => {
    await api.functional.productCatalog.inventory.putById(
      connection,
      {
        id: createdInventory.id,
        body: {
          stock_count: -10 as number & tags.Type<"int32">,
          last_modified_at: new Date(Date.now() + 2000 * 60).toISOString(),
        } satisfies IInventory.IUpdate,
      },
    );
  });

  // 4. Failure: Missing all fields (empty body)
  await TestValidator.error("empty body is rejected")(async () => {
    await api.functional.productCatalog.inventory.putById(
      connection,
      {
        id: createdInventory.id,
        body: {},
      },
    );
  });

  // 5. Failure: Non-existent record update
  await TestValidator.error("not-found error for random id")(async () => {
    await api.functional.productCatalog.inventory.putById(
      connection,
      {
        id: typia.random<string & tags.Format<"uuid">>(),
        body: {
          stock_count: 5 as number & tags.Type<"int32">,
          last_modified_at: new Date(Date.now() + 3000 * 60).toISOString(),
        },
      },
    );
  });
}

