  const inventory = await api.functional.productCatalog.inventory.post(connection, {
    body: {
      product_variant_id: typia.random<string & tags.Format<"uuid">>(),
      stock_count: typia.random<number & tags.Type<"int32"> & tags.Minimum<0>>(),
      last_modified_at: new Date().toISOString(),
