  const confirmation = await api.functional.productCatalog.inventory.eraseById(connection, {
    id: inventory.id,
  });
  typia.assert(confirmation);

  // 3. Attempt to delete the same record again — expect either idempotency or error
  await TestValidator.error("double deletion should error or be idempotent")(() =>
    api.functional.productCatalog.inventory.eraseById(connection, { id: inventory.id })
  );

  // 4. Attempt to delete a non-existent record
