 * 1. Creates a new inventory record via POST /productCatalog/inventory.
 * 2. Deletes the created inventory record with DELETE /productCatalog/inventory/{id}.
 * 3. Confirms that the deleted record cannot be deleted again (error or idempotent behavior).
 * 4. Attempts to delete a non-existent inventory record and confirms error handling.
 * 5. Documents (in comments) business logic regarding prevention of deletion while actively referenced, but skips implementation unless link endpoints exist.
 *
 * Steps:
 * 1. Create a new inventory record for deletion testing.
 * 2. Delete the inventory record by its ID.
 * 3. Attempt double deletion to confirm correct API behavior.
 * 4. Attempt deletion of a random, non-existent ID and validate error response.
 * 5. (Commented) If supported, check business restriction on active record relations.
 */
export async function test_api_productCatalog_test_delete_inventory_record_and_restrictions(
  connection: api.IConnection,
) {
  // 1. Create a new inventory record
  const inventory = await api.functional.productCatalog.inventory.post(connection, {
    body: {
