/**
 * Represents an individual import_feed record, fulfilling business and
 * compliance requirements for provenance, catalog enrichment, and regulatory
 * audit. Mapped to ProductCatalog.import_feeds table as defined in the schema
 * and requirements.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IImportFeed = {
  /** Primary key/unique identifier for the import_feed record. */
  id: string & tags.Format<"uuid">;

  /**
   * Human-friendly label for this import source/feed. Example: 'Google
   * Shopping', 'Partner ERP Feed'. Uniqueness enforced in DB.
   */
  source_name: string;

  /**
   * URI or location from where this import feed's catalog data is fetched.
   * May be a URL or file reference. Uniqueness enforced—important for
   * evidence and provenance.
   */
  source_uri: string & tags.MaxLength<80000>;

  /**
   * UTC timestamp for when the import was performed. Serves as the anchor for
   * all derived catalog enrichment and audit reporting.
   */
  imported_at: string & tags.Format<"date-time">;

  /**
   * Any variants that were imported via this feed. Not stored as array in
   * DB—populated only where relevant in detail responses.
   */
  product_variants?: IProductCatalogProductVariant[];
};
export namespace IImportFeed {
  /**
   * Request type for searching, filtering, and paginating import feed
   * records. Used in PATCH /productCatalog/importFeeds. Enables advanced
   * analytics and compliance workflows.
   *
   * Refer to catalog audit, provenance, and event trace requirements.
   */
  export type IRequest = {
    /**
     * Filter by the source_name property in import_feeds (e.g., Google
     * Shopping, Partner API). Useful for searching or grouping imports.
     */
    source_name?: string;

    /**
     * Optional lower bound (inclusive) for filtering
     * import_feeds.imported_at. Effective for time-based analytics and
     * compliance reporting.
     */
    imported_from?: string & tags.Format<"date-time">;

    /**
     * Optional upper bound (inclusive) for filtering
     * import_feeds.imported_at. Enables analytics for import activity
     * within a time window.
     */
    imported_to?: string & tags.Format<"date-time">;

    /**
     * Optional general string search across source_name and source_uri,
     * using full-text or trigram indices for fuzzy matches.
     */
    search?: string;

    /** Page number for result pagination. Default is 1 if not supplied. */
    page?: number & tags.Type<"int32">;

    /**
     * Maximum number of results per page. Default and enforced limits per
     * API policy.
     */
    limit?: number & tags.Type<"int32">;

    /**
     * Sort order for returned results. Supports imported_at/date or
     * source_name, asc/desc.
     */
    sort?:
      | "imported_at-asc"
      | "imported_at-desc"
      | "source_name-asc"
      | "source_name-desc";
  };

  /**
   * Payload for registering a new import feed. Sends all business/required
   * data needed for creation, excluding system-generated id and
   * relationships. All insertions must respect uniqueness and
   * audit/traceability requirements.
   */
  export type ICreate = {
