 * 4. List feeds filtered by date (imported_from/imported_to)
 * 5. Paginate results (limit 2, various pages) and verify pagination/records/pages metadata
 * 6. Paginate with page number beyond last page to validate empty data set
 * 7. (Edge) Emulate a deleted feed by excluding it after creation (DB-level flag not exposed, so simulate by removal from check-set) and confirm it's not returned (conceptual, as API does not expose delete)
 */
export async function test_api_productCatalog_test_list_search_import_feeds_filters_pagination(
  connection: api.IConnection,
) {
  // 1. Create import feeds with differing attributes
  const feeds = await ArrayUtil.asyncRepeat(5)(async (i) => {
    const now = new Date();
    now.setDate(now.getDate() - i); // different date for each
    return await api.functional.productCatalog.importFeeds.post(connection, {
      body: {
        source_name: `TestSourceName_${i}`,
        source_uri: `https://feeds.example.com/test_feed_${i}.csv`,
        imported_at: now.toISOString(),
      } satisfies IImportFeed.ICreate
    });
  });
  feeds.forEach(typia.assert);

  // 2. List all (no filter)
  {
    const res = await api.functional.productCatalog.importFeeds.patch(connection, {
      body: {}
    });
    typia.assert(res);
    // Should return all feeds just created
    for (const f of feeds) {
      TestValidator.predicate(`created feed appears in list: ${f.source_name}`)(
        !!res.data?.find((x) => x.id === f.id),
      );
    }
    // Should not return duplicates
    const uniqueIds = new Set(res.data?.map((x) => x.id));
    TestValidator.equals("unique feed ids")(uniqueIds.size)(res.data?.length ?? 0);
  }

  // 3. Filter by exact source_name and by partial search
  {
    const sourceName = feeds[0].source_name;
    // Exact source_name filter
    const res1 = await api.functional.productCatalog.importFeeds.patch(connection, {
      body: { source_name: sourceName }
    });
    typia.assert(res1);
    TestValidator.predicate("filtered by exact source_name")(
      Array.isArray(res1.data) && res1.data.length === 1 && res1.data[0].source_name === sourceName,
    );
    // Partial string search filter (should pick at least one feed)
    const res2 = await api.functional.productCatalog.importFeeds.patch(connection, {
      body: { search: "TestSourceName_" }
    });
    typia.assert(res2);
    TestValidator.predicate("search picks up feeds")(
      Array.isArray(res2.data) && res2.data.some(x => x.source_name.startsWith("TestSourceName_")),
    );
  }

  // 4. Filter by import date window
  {
    // Should find subset: only feeds imported within most recent 2 days
    const from = new Date(feeds[0].imported_at);
    from.setDate(from.getDate() - 1); // includes feeds[0], feeds[1]
    const to = new Date(feeds[1].imported_at);
    to.setHours(to.getHours() + 2); // within range
    const res = await api.functional.productCatalog.importFeeds.patch(connection, {
      body: {
        imported_from: from.toISOString(),
        imported_to: to.toISOString(),
      },
    });
    typia.assert(res);
    const expectedIds = [feeds[0].id, feeds[1].id];
    TestValidator.equals("date window subset")(
      expectedIds.sort()
    )((res.data?.map(x => x.id).filter(id => expectedIds.includes(id)).sort()) ?? []);
  }

  // 5. Pagination: limit 2, check pages
  {
    // First page
    const res1 = await api.functional.productCatalog.importFeeds.patch(connection, {
      body: { limit: 2, page: 1, sort: "imported_at-desc" }
    });
    typia.assert(res1);
    TestValidator.equals("limit 2, first page")(2)(res1.data?.length || 0);
    TestValidator.equals("pagination meta present")(true)(!!res1.pagination);

    // Second page
    const res2 = await api.functional.productCatalog.importFeeds.patch(connection, {
      body: { limit: 2, page: 2, sort: "imported_at-desc" }
    });
    typia.assert(res2);
    // At least 1 record should be on last (third) page if total feeds = 5
    const res3 = await api.functional.productCatalog.importFeeds.patch(connection, {
      body: { limit: 2, page: 3, sort: "imported_at-desc" }
    });
    typia.assert(res3);
    // Either 1 or 0 (should exhaust after this)
    TestValidator.predicate("third page has 1 or 0 feeds")(
      res3.data ? res3.data.length <= 2 : true,
    );

    // 6. Pagination beyond last page → expect data empty/undefined
    const res4 = await api.functional.productCatalog.importFeeds.patch(connection, {
      body: { limit: 2, page: 4, sort: "imported_at-desc" }
    });
    typia.assert(res4);
    TestValidator.predicate("page beyond last is empty")(
      !res4.data || res4.data.length === 0
    );
  }

  // 7. Simulate a deleted feed by removing from check set and ensure not found
  // (Without delete API, just skip validation for it – in real use, test would check 'deleted != true')
}

