/**
 * Get a specific import feed record by ID (ProductCatalog: import_feeds table).
 *
 * Fetches the full record of a catalog import feed by its unique UUID. The
 * returned data includes source, metadata, imported_at, and other business
 * attributes required for evidence, trouble-shooting, and monitoring imported
 * catalog data. The query checks permissions and cross-links with related
 * records if necessary (such as imported product/variants). Robust error
 * handling is required for non-existent, inaccessible, or deleted records. All
 * access attempts must be logged for audit. This endpoint is central to ongoing
 * catalog hygiene and regulatory tracing of data provenance.
 *
 * @param props.connection
 * @param props.id Import feed record’s unique UUID.
 * @path /productCatalog/importFeeds/:id
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export async function getById(
  connection: IConnection,
  props: getById.Props,
): Promise<getById.Response> {
  return !!connection.simulate
    ? getById.simulate(connection, props)
    : PlainFetcher.fetch(
