    },
  } as const;

  export const path = (props: Props) =>
    `/productCatalog/importFeeds/${encodeURIComponent(props.id ?? "null")}`;
  export const random = (g?: Partial<typia.IRandomGenerator>): IImportFeed =>
    typia.random<IImportFeed>(g);
