import { tags } from "typia";

import { IProductCatalogProductVariant } from "./IProductCatalogProductVariant";

/**
 * Represents an individual import_feed record, fulfilling business and
 * compliance requirements for provenance, catalog enrichment, and regulatory
 * audit. Mapped to ProductCatalog.import_feeds table as defined in the schema
 * and requirements.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IImportFeed = {
  /** Primary key/unique identifier for the import_feed record. */
  id: string & tags.Format<"uuid">;

  /**
   * Human-friendly label for this import source/feed. Example: 'Google
   * Shopping', 'Partner ERP Feed'. Uniqueness enforced in DB.
   */
  source_name: string;

  /**
   * URI or location from where this import feed's catalog data is fetched.
   * May be a URL or file reference. Uniqueness enforced—important for
   * evidence and provenance.
   */
  source_uri: string & tags.MaxLength<80000>;

  /**
   * UTC timestamp for when the import was performed. Serves as the anchor for
   * all derived catalog enrichment and audit reporting.
   */
  imported_at: string & tags.Format<"date-time">;

  /**
   * Any variants that were imported via this feed. Not stored as array in
   * DB—populated only where relevant in detail responses.
   */
  product_variants?: IProductCatalogProductVariant[];
};
export namespace IImportFeed {
  /**
   * Payload for registering a new import feed. Sends all business/required
   * data needed for creation, excluding system-generated id and
   * relationships. All insertions must respect uniqueness and
   * audit/traceability requirements.
   */
  export type ICreate = {
    /**
     * Human-friendly name for this import feed source (required).
     * Uniqueness enforced.
     *
     * See import_feeds.source_name.
     */
    source_name: string;

    /**
     * Full URI describing the import source/destination. Required for data
     * provenance and audit.
     */
    source_uri: string & tags.MaxLength<80000>;

    /**
     * Timestamp the import actually occurred (should be set by system if
     * omitted). Sets the evidence anchor for audit and compliance
     * reporting.
     */
    imported_at?: string & tags.Format<"date-time">;
  };
}

