import type { IProductCatalogProductVariant } from "@ORGANIZATION/PROJECT-api/lib/structures/IProductCatalogProductVariant";

/**
 * Validate retrieval of an import feed by its unique ID, including negative cases.
 *
 * 1. Create a new import feed using productCatalog.importFeeds.post and ensure the record is created correctly.
 * 2. Retrieve the just-created import feed by its ID via productCatalog.importFeeds.getById. Check all its key fields match those from creation and response typing is correct.
 * 3. Attempt to fetch an import feed by a random non-existent UUID. Assert that a 404 or proper error is returned, and the error is properly typed/handled.
 *
 * This test ensures functional GET by ID, covers standard successful and error response paths, evidence for audit/reliability, and aligns with business rules for catalog feed import provenance.
 */
export async function test_api_productCatalog_importFeeds_getById(
  connection: api.IConnection,
) {
  // 1. Create new import feed
  const input: IImportFeed.ICreate = {
    source_name: `Partner ERP Feed - ${RandomGenerator.alphabets(6)}`,
    source_uri: `https://feeds.partner.com/catalog/${RandomGenerator.alphaNumeric(10)}`,
    imported_at: new Date().toISOString(),
  };
  const created: IImportFeed = await api.functional.productCatalog.importFeeds.post(connection, { body: input });
  typia.assert(created);

  // 2. Retrieve created feed by ID and verify fields
  const retrieved: IImportFeed = await api.functional.productCatalog.importFeeds.getById(connection, { id: created.id });
  typia.assert(retrieved);
  TestValidator.equals("id")(created.id)(retrieved.id);
  TestValidator.equals("source_name")(input.source_name)(retrieved.source_name);
  TestValidator.equals("source_uri")(input.source_uri)(retrieved.source_uri);
  TestValidator.equals("imported_at")(input.imported_at)(retrieved.imported_at);

  // 3. Attempt GET by a random non-existent UUID (should 404 or error appropriately)
  await TestValidator.error("getById with non-existent id")(() =>
    api.functional.productCatalog.importFeeds.getById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
    })
  );
}

