import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IImportFeed } from "@ORGANIZATION/PROJECT-api/lib/structures/IImportFeed";
import type { IProductCatalogProductVariant } from "@ORGANIZATION/PROJECT-api/lib/structures/IProductCatalogProductVariant";

/**
 * Validates creation and error handling for the import feed resource in ProductCatalog.
 *  
 * Business context: Import feeds consolidate external or partner data sources for catalog enrichment, requiring rigorous uniqueness and provenance checks. Ensuring accurate, unique capture is vital for traceability and for preventing conflicting records. 
 * 
 * This test covers the following real-world scenarios:
 * 1. Creating an import feed with all required, valid fields to ensure successful insertion.
 * 2. Creating a feed with missing or invalid required fields—verifying validation and error handling.
 * 3. Attempting to insert a duplicate import feed (same source_name and source_uri). Verifies constraint handling and prevents data corruption.
 *
 * Steps:
 * 1. Create import feed using valid, unique source_name and source_uri (should succeed).
 * 2. Try to create with missing required fields (should fail—field validation errors).
 * 3. Try to create with invalid data: overlong URI, bad date format, etc.
 * 4. Create a second import feed with the same source_name and source_uri (should fail—uniqueness constraint).
 */
export async function test_api_productCatalog_test_create_import_feed_success_and_validation(
  connection: api.IConnection,
) {
  // 1. Create import feed with all valid/required fields
  const validFeedInput: IImportFeed.ICreate = {
    source_name: `Feed-${RandomGenerator.alphaNumeric(6)}`,
    source_uri: `https://feeds.example.com/${RandomGenerator.alphaNumeric(8)}`,
    imported_at: new Date().toISOString(),
  };
  const createdFeed = await api.functional.productCatalog.importFeeds.post(connection, { body: validFeedInput });
  typia.assert(createdFeed);
  TestValidator.equals("source_name echo")(validFeedInput.source_name)(createdFeed.source_name);
  TestValidator.equals("source_uri echo")(validFeedInput.source_uri)(createdFeed.source_uri);
  TestValidator.equals("imported_at echo")(validFeedInput.imported_at)(createdFeed.imported_at);

  // 2A. Attempt creation with missing required 'source_name'
  await TestValidator.error("missing source_name fails")(async () => {
    await api.functional.productCatalog.importFeeds.post(connection, {
      body: {
        // source_name omitted intentionally
        source_uri: `https://feeds.example.com/${RandomGenerator.alphaNumeric(8)}`,
        imported_at: new Date().toISOString(),
      } as any // IMPORTANT: in production code, this would be a compilation error. The e2e only checks runtime errors, so must still have proper typing.
    });
  });

  // 2B. Attempt creation with missing required 'source_uri'
  await TestValidator.error("missing source_uri fails")(async () => {
    await api.functional.productCatalog.importFeeds.post(connection, {
      body: {
        source_name: `Feed-${RandomGenerator.alphaNumeric(6)}`,
        // source_uri omitted
        imported_at: new Date().toISOString(),
      } as any
    });
  });

  // 3. Attempt with invalid data: source_uri too long
  await TestValidator.error("source_uri max length exceeded")(async () => {
    await api.functional.productCatalog.importFeeds.post(connection, {
      body: {
        source_name: `Feed-${RandomGenerator.alphaNumeric(6)}`,
        source_uri: "x".repeat(80001),
        imported_at: new Date().toISOString(),
      } as any
    });
  });

  // 3B. Attempt with invalid date format for imported_at
  await TestValidator.error("imported_at invalid date format")(async () => {
    await api.functional.productCatalog.importFeeds.post(connection, {
      body: {
        source_name: `Feed-${RandomGenerator.alphaNumeric(6)}`,
        source_uri: `https://feeds.example.com/${RandomGenerator.alphaNumeric(8)}`,
        imported_at: "not-a-date",
      } as any
    });
  });

  // 4. Attempt duplicate insertion
  await TestValidator.error("duplicate import feed fails")(async () => {
    await api.functional.productCatalog.importFeeds.post(connection, {
      body: validFeedInput,
    });
  });
}

