import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IImportFeed } from "@ORGANIZATION/PROJECT-api/lib/structures/IImportFeed";
import type { IProductCatalogProductVariant } from "@ORGANIZATION/PROJECT-api/lib/structures/IProductCatalogProductVariant";

/**
 * E2E test for updating import feed records by ID including edge/error cases.
 *
 * This test covers multiple scenarios around the PUT /productCatalog/importFeeds/:id endpoint:
 * 1. Preparation: Create an import feed to obtain a valid record for update scenarios.
 * 2. Success path: Update the newly created feed's source_name and imported_at, verify applied changes.
 * 3. Error path: Update with invalid (malformed) UUID string, expect error.
 * 4. Error path: Update with an empty body object, expect validation error.
 * 5. Error path: Update a non-existent (random valid UUID) feed, expect not found error.
 *
 * All responses are type-asserted and error conditions check for proper rejections.
 * The test does not cover deletion-after-creation as DELETE endpoint is not specified.
 */
export async function test_api_productCatalog_importFeeds_putById_various_scenarios(
  connection: api.IConnection,
) {
  // 1. Preparation: Create a new import feed to work with
  const createdFeed = await api.functional.productCatalog.importFeeds.post(connection, {
    body: {
      source_name: `Feed ${RandomGenerator.alphabets(6)}`,
      source_uri: `https://feeds.example.com/${RandomGenerator.alphabets(8)}`,
      imported_at: new Date().toISOString(),
    } satisfies IImportFeed.ICreate,
  });
  typia.assert(createdFeed);

  // 2. Success: Update the import feed's data with valid changes
  const newSourceName = `Updated ${RandomGenerator.alphabets(6)}`;
  const newImportedAt = new Date(Date.now() + 1000 * 60 * 60).toISOString();
  const updatedFeed = await api.functional.productCatalog.importFeeds.putById(connection, {
    id: createdFeed.id,
    body: {
      source_name: newSourceName,
      imported_at: newImportedAt,
    } satisfies IImportFeed.IUpdate,
  });
  typia.assert(updatedFeed);
  // Check that updated fields apply
  TestValidator.equals("feed id should be unchanged")(createdFeed.id)(updatedFeed.id);
  TestValidator.equals("updated source_name")(newSourceName)(updatedFeed.source_name);
  TestValidator.equals("updated imported_at")(newImportedAt)(updatedFeed.imported_at);

  // 3. Error: Try update with invalid UUID (malformed)
  await TestValidator.error("update with invalid UUID should error")(
    async () => {
      await api.functional.productCatalog.importFeeds.putById(connection, {
        id: "not-a-uuid",
        body: {
          source_name: "Invalid try",
        } satisfies IImportFeed.IUpdate,
      });
    },
  );

  // 4. Error: Try update with empty body object (should fail validation)
  await TestValidator.error("empty body should error")(
    async () => {
      await api.functional.productCatalog.importFeeds.putById(connection, {
        id: createdFeed.id,
        body: {} as IImportFeed.IUpdate,
      });
    },
  );

  // 5. Error: Try update with a valid but non-existent UUID
  await TestValidator.error("update with non-existent UUID should error")(
    async () => {
      await api.functional.productCatalog.importFeeds.putById(connection, {
        id: typia.random<string & tags.Format<"uuid">>(),
        body: {
          source_name: "Ghost update",
          imported_at: new Date().toISOString(),
        } satisfies IImportFeed.IUpdate,
      });
    },
  );
}

