import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ICatalogEvent } from "@ORGANIZATION/PROJECT-api/lib/structures/ICatalogEvent";
import type { IPageICatalogEvent } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageICatalogEvent";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IProductCatalogProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IProductCatalogProduct";
import type { IProductCatalogProductVariant } from "@ORGANIZATION/PROJECT-api/lib/structures/IProductCatalogProductVariant";
import type { IUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IUser";
import type { ICatalogEvidence } from "@ORGANIZATION/PROJECT-api/lib/structures/ICatalogEvidence";

/**
 * Validate catalog event filtering and pagination logic.
 *
 * Ensures that the catalog event listing endpoint robustly supports filtering (by event_type, user, product, variant, and date window) and pagination, and that deleted/archived events do not appear in the result. Also checks that paginating beyond the record limit yields empty results and verifies correct pagination metadata.
 *
 * 1. Create at least 6 catalog events with intentionally varied properties (event_type, users, products, variants, timestamps).
 * 2. Query using various filters to confirm only correct events are returned for each filter type (event_type, user_id, product_id, product_variant_id, occurred_at window).
 * 3. Paginate results (limit=2) and validate page data and metadata.
 * 4. Explicitly request a page number that exceeds available records to check we receive an empty result.
 * 5. Ensure any deleted/archived events do not appear in search results (if API supports soft deletion or archiving and such event was created).
 */
export async function test_api_productCatalog_test_list_search_catalog_events_filters_pagination(
  connection: api.IConnection,
) {
  // Helper to get a safe ISO timestamp X minutes apart
  const shiftMinutes = (base: string, minutes: number): string => {
    return new Date(new Date(base).getTime() + minutes * 60 * 1000).toISOString();
  };

  // 1. Prepare distinct users, products, and variants
  const userA: string = typia.random<string & tags.Format<"uuid">>();
  const userB: string = typia.random<string & tags.Format<"uuid">>();
  const productA: string = typia.random<string & tags.Format<"uuid">>();
  const productB: string = typia.random<string & tags.Format<"uuid">>();
  const variantA: string = typia.random<string & tags.Format<"uuid">>();
  const variantB: string = typia.random<string & tags.Format<"uuid">>();
  const now: string = new Date().toISOString();

  // Event types varied intentionally
  const EVENT_TYPE_CREATE = "create";
  const EVENT_TYPE_UPDATE = "update";
  const EVENT_TYPE_DELETE = "delete";

  // 2. Create 6 events across various combinations
  const createdEvents: ICatalogEvent[] = [];

  // Event 1: Type=create, userA, productA, variantA, now
  createdEvents.push(await api.functional.productCatalog.catalogEvents.post(connection, {
    body: {
      product_id: productA,
      product_variant_id: variantA,
      user_id: userA,
      event_type: EVENT_TYPE_CREATE,
      description: "Product created",
      occurred_at: now,
    },
  }));
  // Event 2: Type=update, userA, productA, variantB, now+1min
  createdEvents.push(await api.functional.productCatalog.catalogEvents.post(connection, {
    body: {
      product_id: productA,
      product_variant_id: variantB,
      user_id: userA,
      event_type: EVENT_TYPE_UPDATE,
      description: "Product variant updated",
      occurred_at: shiftMinutes(now, 1),
    },
  }));
  // Event 3: Type=create, userB, productB, variantA, now+2min
  createdEvents.push(await api.functional.productCatalog.catalogEvents.post(connection, {
    body: {
      product_id: productB,
      product_variant_id: variantA,
      user_id: userB,
      event_type: EVENT_TYPE_CREATE,
      description: "Product created for second user",
      occurred_at: shiftMinutes(now, 2),
    },
  }));
  // Event 4: Type=update, userB, productB, variantB, now+3min
  createdEvents.push(await api.functional.productCatalog.catalogEvents.post(connection, {
    body: {
      product_id: productB,
      product_variant_id: variantB,
      user_id: userB,
      event_type: EVENT_TYPE_UPDATE,
      description: "Other product variant updated",
      occurred_at: shiftMinutes(now, 3),
    },
  }));
  // Event 5: Type=delete, userA, productA, null variant, now+4min
  createdEvents.push(await api.functional.productCatalog.catalogEvents.post(connection, {
    body: {
      product_id: productA,
      product_variant_id: null,
      user_id: userA,
      event_type: EVENT_TYPE_DELETE,
      description: "Product deleted",
      occurred_at: shiftMinutes(now, 4),
    },
  }));
  // Event 6: Type=create, userA, productB, variantB, now+5min
  createdEvents.push(await api.functional.productCatalog.catalogEvents.post(connection, {
    body: {
      product_id: productB,
      product_variant_id: variantB,
      user_id: userA,
      event_type: EVENT_TYPE_CREATE,
      description: "Product created again",
      occurred_at: shiftMinutes(now, 5),
    },
  }));
  createdEvents.forEach(typia.assert);

  // 2. Query by event_type: EVENT_TYPE_CREATE
  let output = await api.functional.productCatalog.catalogEvents.patch(connection, {
    body: {
      event_type: EVENT_TYPE_CREATE,
      page: 1,
      limit: 10,
    },
  });
  typia.assert(output);
  TestValidator.predicate("event_type filtered")(!!output.data && output.data.every(e => e.event_type === EVENT_TYPE_CREATE));

  // 3. Query by user_id: userB
  output = await api.functional.productCatalog.catalogEvents.patch(connection, {
    body: {
      user_id: userB,
      page: 1,
      limit: 10,
    },
  });
  typia.assert(output);
  TestValidator.predicate("user_id filtered")(!!output.data && output.data.every(e => e.user_id === userB));

  // 4. Query by product_id: productA
  output = await api.functional.productCatalog.catalogEvents.patch(connection, {
    body: {
      product_id: productA,
      page: 1,
      limit: 10,
    },
  });
  typia.assert(output);
  TestValidator.predicate("product_id filtered")(!!output.data && output.data.every(e => e.product_id === productA));

  // 5. Query by product_variant_id: variantB
  output = await api.functional.productCatalog.catalogEvents.patch(connection, {
    body: {
      product_variant_id: variantB,
      page: 1,
      limit: 10,
    },
  });
  typia.assert(output);
  TestValidator.predicate("product_variant_id filtered")(!!output.data && output.data.every(e => e.product_variant_id === variantB));

  // 6. Query by occurred_at window (from: now+2min, to: now+4min) - should match event 3, 4, 5
  const from = shiftMinutes(now, 2);
  const to = shiftMinutes(now, 4);
  output = await api.functional.productCatalog.catalogEvents.patch(connection, {
    body: {
      from,
      to,
      page: 1,
      limit: 10,
    },
  });
  typia.assert(output);
  TestValidator.predicate("occurred_at window filtered")(
    !!output.data && output.data.every(e => e.occurred_at >= from && e.occurred_at <= to)
  );

  // 7. Paginate with limit=2
  let allPageIds: string[] = [];
  let page = 1;
  // Retrieve all records page by page
  while (true) {
    const pageResult = await api.functional.productCatalog.catalogEvents.patch(connection, {
      body: {
        page,
        limit: 2,
      },
    });
    typia.assert(pageResult);
    if (!pageResult.data || pageResult.data.length === 0) break;
    allPageIds.push(...pageResult.data.map(e => e.id));
    page++;
    // Should not exceed total number of events created in this test
    if (allPageIds.length >= createdEvents.length) break;
  }
  // Check all page IDs are in created set (no more, no less, and no duplicates)
  const createdIds = createdEvents.map(e => e.id);
  TestValidator.equals("all paginated events accounted for")(
    createdIds.sort()
  )(
    allPageIds.sort()
  );

  // 8. Paginate beyond last page (e.g., page=100)
  const lastPageResult = await api.functional.productCatalog.catalogEvents.patch(connection, {
    body: {
      page: 100,
      limit: 10,
    },
  });
  typia.assert(lastPageResult);
  TestValidator.predicate("empty result on out-of-range page")(
    !!lastPageResult.data && lastPageResult.data.length === 0
  );

  // 9. Pagination metadata correctness
  if (output.pagination) {
    TestValidator.equals("pagination limit")(output.pagination.limit)(10);
    TestValidator.predicate("pagination current page")(
      typeof output.pagination.current === "number" && output.pagination.current > 0
    );
    TestValidator.predicate("pagination metadata consistency")(
      typeof output.pagination.pages === "number" && output.pagination.pages >= 1
    );
  }

  // 10. If soft deletion/archival supported, confirm deleted/archived events are NOT returned.
  // (Requires API support and test-setup for deletion/archival; skipped if unsupported in this API)
}

