import { tags } from "typia";

import { IProductCatalogProduct } from "./IProductCatalogProduct";
import { IProductCatalogProductVariant } from "./IProductCatalogProductVariant";
import { IUser } from "./IUser";
import { ICatalogEvidence } from "./ICatalogEvidence";

/**
 * Represents a single, immutable catalog action/event entry. Encodes
 * who/what/when/why for every state change to products, variants, or catalog
 * import. Fulfills audit, evidence, compliance, and forensic requirements for
 * the Product Catalog module and aligns to strict business/Prisma schema
 * design.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type ICatalogEvent = {
  /** Primary key/unique reference for this catalog event. */
  id: string & tags.Format<"uuid">;

  /** Product related to this event (optional—nullable in DB/response). */
  product_id?: string & tags.Format<"uuid">;

  /** Variant related to this event (nullable if event is product-scope only). */
  product_variant_id?: string & tags.Format<"uuid">;

  /**
   * User/actor who triggered this event (required for audit tracing and
   * compliance).
   */
  user_id: string & tags.Format<"uuid">;

  /**
   * Event type (e.g., 'create', 'update', 'import', 'status_change'). All
   * system/lifecycle changes must be explicitly typed for evidence
   * requirements.
   */
  event_type: string;

  /**
   * Detailed event description for audit, evidence, and regulatory
   * compliance.
   */
  description: string;

  /**
   * Timestamp of event occurrence (UTC). For evidence chain and regulatory
   * timeline mapping.
   */
  occurred_at: string & tags.Format<"date-time">;

  /**
   * Embedded product details if relevant (hydrated from relationship or for
   * audit purposes).
   */
  product?: IProductCatalogProduct;

  /** Embedded variant details if relevant (hydrated for evidence/audit). */
  variant?: IProductCatalogProductVariant;

  /** User entity data for the actor who performed this action. */
  user?: IUser;

  /**
   * Array of catalog evidence records linked to this event (may be empty).
   * Included for audit trace/explainability.
   */
  evidence?: ICatalogEvidence[];
};
export namespace ICatalogEvent {
  /**
   * Payload for creating a catalog event.
   *
   * Corresponds to the atomic record for an event or change in the product
   * catalog. Tightly aligned with the 'catalog_events' table in the Prisma DB
   * schema. All required fields contribute to evidence, audit, and regulatory
   * trace, aligning with the system's advanced integrity and explainability
   * requirements.
   */
  export type ICreate = {
    /**
     * The ID of the related product (nullable). Links to the products
     * entity as per event context.
     *
     * Prisma: catalog_events.product_id.
     */
    product_id?: string & tags.Format<"uuid">;

    /**
     * The unique identifier of the variant linked to this event, nullable
     * where the event is at the catalog level only.
     *
     * Prisma: catalog_events.product_variant_id.
     */
    product_variant_id?: (string & tags.Format<"uuid">) | null;

    /**
     * The unique identifier of the user (actor) who performed this event.
     * Required for audit, evidence, and compliance traceability.
     *
     * Prisma: catalog_events.user_id.
     */
    user_id: string & tags.Format<"uuid">;

    /**
     * Type/category of the catalog event (e.g., creation, update, import,
     * deletion, status_change). Maintains atomicity for event type,
     * required for compliance evidence classification.
     *
     * Prisma: catalog_events.event_type.
     */
    event_type: string;

    /**
     * Detailed human-readable description of the event. Required for full
     * context and compliance explainability. Not calculated, single atomic
     * field.
     *
     * Prisma: catalog_events.description.
     */
    description: string;

    /**
     * The timestamp representing when the event occurred. Used for audit,
     * evidence preservation, and forensic ordering of catalog state
     * changes.
     *
     * Prisma: catalog_events.occurred_at.
     */
    occurred_at: string & tags.Format<"date-time">;
  };
}

