import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ICatalogEvent } from "@ORGANIZATION/PROJECT-api/lib/structures/ICatalogEvent";
import type { IProductCatalogProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IProductCatalogProduct";
import type { IProductCatalogProductVariant } from "@ORGANIZATION/PROJECT-api/lib/structures/IProductCatalogProductVariant";
import type { IUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IUser";
import type { ICatalogEvidence } from "@ORGANIZATION/PROJECT-api/lib/structures/ICatalogEvidence";

/**
 * Validate fetching a catalog event record by ID (success and error).
 *
 * This test verifies two scenarios:
 * 1. Successful retrieval: After creating a catalog event record, it should be retrievable by its unique ID, and the returned data should match what was created, asserting the completeness and correctness of its properties.
 * 2. Failure retrieval: Fetching a catalog event with an invalid or non-existent (deleted/random) ID should return a 404 error or equivalent, confirming error handling and defensive behavior of the endpoint.
 *
 * Steps:
 * 1. Create a valid catalog event
 * 2. Fetch by its returned ID and check data
 * 3. Try fetching by random (non-existent) UUID and assert 404
 */
export async function test_api_productCatalog_test_get_catalog_event_by_id_success_and_failure(connection: api.IConnection) {
  // Step 1: Create a valid catalog event (for positive test)
  const createPayload: ICatalogEvent.ICreate = {
    // Product is optional for catalog event; for realism, test with and without
    // For required fields, generate valid, realistic data
    user_id: typia.random<string & tags.Format<"uuid">>(),
    event_type: RandomGenerator.pick([
      "create",
      "update",
      "import",
      "status_change",
      "delete"
    ]),
    description: RandomGenerator.paragraph()(),
    occurred_at: new Date().toISOString(),
    // product_id/product_variant_id optional
  };

  const created: ICatalogEvent = await api.functional.productCatalog.catalogEvents.post(connection, { body: createPayload });
  typia.assert(created);

  // Step 2: Fetch the event by its ID and validate the returned record matches
  const fetched: ICatalogEvent = await api.functional.productCatalog.catalogEvents.getById(connection, { id: created.id });
  typia.assert(fetched);

  // Assert on property equivalence for immutable fields (other fields like product, variant, user etc are hydrated/embedded, so only check the core atomic fields)
  TestValidator.equals("id")(created.id)(fetched.id);
  TestValidator.equals("event_type")(created.event_type)(fetched.event_type);
  TestValidator.equals("description")(created.description)(fetched.description);
  TestValidator.equals("occurred_at")(created.occurred_at)(fetched.occurred_at);
  TestValidator.equals("user_id")(created.user_id)(fetched.user_id);

  // Step 3: Attempt to fetch a catalog event with a non-existent/random UUID. Should fail with 404 (HttpError)
  await TestValidator.error("404 on non-existent catalog event")(() => 
    api.functional.productCatalog.catalogEvents.getById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
    })
  );
}

