import type { ICatalogEvidence } from "@ORGANIZATION/PROJECT-api/lib/structures/ICatalogEvidence";

/**
 * Validate the creation of a new catalog event record, including success and failure scenarios based on business rules and constraints.
 *
 * Purpose:
 * This test ensures that catalog event creation supports full audit, evidence, compliance, and forensic requirements for the Product Catalog module. It checks for correct record creation, proper validation of required fields, error responses on missing/invalid data, and enforcement of unique/constraint rules.
 *
 * Test steps:
 * 1. Create a new catalog event with all required and optional metadata.
 *     - Validate that the API returns the correct event record and all fields are as expected.
 * 2. Attempt to create a catalog event with missing required fields (user_id, event_type, description, occurred_at).
 *     - Validate that the API returns an appropriate validation error for missing fields.
 * 3. Attempt to create a catalog event with an invalid format for required fields (e.g., malformed UUID, incorrect date-time string).
 *     - Validate response includes the proper validation error.
 * 4. Attempt to create a duplicate catalog event using the same unique constraint fields (if any, e.g., identical (user_id, event_type, occurred_at)).
 *     - Validate the system rejects the duplicate and returns a constraint violation error.
 */
export async function test_api_productCatalog_test_create_catalog_event_success_and_constraint_failure(
  connection: api.IConnection,
) {
  // 1. Create a new catalog event with all required and optional metadata
  const validEventInput: ICatalogEvent.ICreate = {
    product_id: typia.random<string & tags.Format<'uuid'>>(),
    product_variant_id: typia.random<string & tags.Format<'uuid'>>(),
    user_id: typia.random<string & tags.Format<'uuid'>>(),
    event_type: "create",
    description: "New product catalog event for audit logging.",
    occurred_at: new Date().toISOString(),
  };
  const createdEvent = await api.functional.productCatalog.catalogEvents.post(connection, { body: validEventInput });
  typia.assert(createdEvent);
  // Validate returned fields match sent values
  TestValidator.equals("user_id")(validEventInput.user_id)(createdEvent.user_id);
  TestValidator.equals("event_type")(validEventInput.event_type)(createdEvent.event_type);
  TestValidator.equals("description")(validEventInput.description)(createdEvent.description);
  TestValidator.equals("occurred_at")(validEventInput.occurred_at)(createdEvent.occurred_at);

  // 2. Create catalog event with missing required fields
  await TestValidator.error("missing required fields")(() =>
    api.functional.productCatalog.catalogEvents.post(connection, {
      body: {
        description: "Missing required fields."
        // missing user_id, event_type, occurred_at intentionally
      } as ICatalogEvent.ICreate,
    })
  );

  // 3. Create catalog event with invalid format for required fields
  await TestValidator.error("invalid UUID / date-time format")(() =>
    api.functional.productCatalog.catalogEvents.post(connection, {
      body: {
        user_id: "not-a-uuid",
        event_type: "update",
        description: "Invalid field formats.",
        occurred_at: "not-a-date"
      } as ICatalogEvent.ICreate,
    })
  );

  // 4. Attempt to create duplicate catalog event with same user_id, event_type, occurred_at
  await TestValidator.error("duplicate catalog event constraint violation")(() =>
    api.functional.productCatalog.catalogEvents.post(connection, {
      body: validEventInput,
    })
  );
}

