 * 3. Confirm the API responds with a validation error or forbidden status
 * 4. (Optionally) Try allowed field updates as a correctness check
 */
export async function test_api_paymentsDiscounts_test_update_refund_record_with_immutable_fields(connection: api.IConnection) {
  // 1. Create a refund record
  const createInput: IRefund.ICreate = {
    payment_id: typia.random<string & tags.Format<"uuid">>(),
    transaction_id: typia.random<string & tags.Format<"uuid">>(),
    order_id: typia.random<string & tags.Format<"uuid">>(),
    amount: 1000.0,
    currency: "USD",
    status: "requested",
    reason: "Initial refund request for testing invalid update",
  };
  const created: IRefund = await api.functional.paymentsDiscounts.refunds.post(connection, { body: createInput });
  typia.assert(created);

  // 2. Attempt to update immutable/disallowed fields (id, payment_id, transaction_id)
  // According to IRefund.IUpdate and IRefund definition, these fields should not be allowed for update.
  // Prepare an update payload that tries to mutate these primary/foreign keys, which should be rejected.
  // Since the update endpoint only accepts the allowed fields (see IRefund.IUpdate), forcibly pass extra/invalid fields via type violation to trigger error (HOWEVER, per strict e2e guide, we must only use allowed fields; so ensure test targets only API contract, not TypeScript circuit-break)
  // Instead, try updating a field to an invalid value, e.g., negative amount, to trigger validation.

  // 2a. Try updating 'amount' to a negative value (violates atomic positive requirement if such enforced)
  await TestValidator.error("updating refund amount to negative not allowed")(async () => {
    await api.functional.paymentsDiscounts.refunds.putById(connection, {
      id: created.id,
      body: {
        amount: -100.0,
      } satisfies IRefund.IUpdate,
    });
  });

  // 2b. Try updating all fields to null (if schema will reject null for required ones)
  await TestValidator.error("nullifying required refund fields not allowed")(async () => {
    await api.functional.paymentsDiscounts.refunds.putById(connection, {
      id: created.id,
      body: {
        amount: null,
        currency: null,
        status: null,
        completed_at: null,
        order_id: null,
        reason: null,
      } satisfies IRefund.IUpdate,
    });
  });

  // 3. Optionally, update allowed field with valid payload to verify operation works
  const updateResult: IRefund = await api.functional.paymentsDiscounts.refunds.putById(connection, {
    id: created.id,
    body: { status: "processed", reason: "Test allowed mutation" } satisfies IRefund.IUpdate,
  });
  typia.assert(updateResult);
  TestValidator.equals("status updated correctly")("processed")(updateResult.status);
}

