import { tags } from "typia";

/**
 * Atomic audit event record related to the PaymentsDiscounts module (payments,
 * discounts, refunds).
 *
 * Represents an immutable record of changes and evidence trails for all
 * operations that must be captured for compliance, regulatory, financial, and
 * forensic reasons.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IPaymentAudit = {
  /**
   * Unique identifier for the payment audit log record. Serves as the primary
   * key in the payment_audits table.
   *
   * Referenced in compliance and forensics for traceability.
   */
  id: string & tags.Format<"uuid">;

  /**
   * User who performed this audit action. Can be null for automated/system
   * events. References users.id in the Prisma schema.
   */
  user_id?: (string & tags.Format<"uuid">) | null;

  /**
   * Entity type being audited (e.g. 'payment', 'discount', 'refund').
   * Specifies the nature of the audited business entity. Required for dynamic
   * audit workflows and evidence preservation.
   */
  entity_type: string;

  /**
   * UUID of the payment, discount, or refund being audited. Forms the
   * evidence chain by connecting audit log to the affected entity.
   */
  entity_id: string & tags.Format<"uuid">;

  /**
   * Describes the operation performed (e.g. 'create', 'update', 'fail',
   * 'refund'). Required for legal and compliance evidence tracing.
   */
  action: string;

  /**
   * Optional snapshot of the state before the operation. May be null for
   * creation events or system actions. Preserved strictly for evidence.
   */
  old_value?: string | null;

  /**
   * Optional snapshot of the state after the operation. May be null for
   * deletions or certain system events. Key for legal hold and forensics.
   */
  new_value?: string | null;

  /**
   * Exact time the audit event was recorded. Follows the ISO 8601 format with
   * timezone.
   *
   * Central evidence field for regulatory and dispute analysis.
   */
  timestamp: string & tags.Format<"date-time">;
};
export namespace IPaymentAudit {
  /**
   * Paginated evidence/audit log search for payment_audits table. All filter
   * criteria map directly to normalized schema columns and are used for
   * regulatory reports, forensic queries, and compliance dashboards.
   */
  export type IRequest = {
    /**
     * Restrict audit logs to events triggered by a specific user. From
     * payment_audits.user_id. Key evidence filter.
     */
    user_id?: (string & tags.Format<"uuid">) | null;

    /**
     * Entity class (e.g. 'payment', 'discount', 'refund', etc). String,
     * mapped from payment_audits.entity_type.
     */
    entity_type?: string | null;

    /**
     * UUID of the entity modified in this event (payment, refund, etc).
     * payment_audits.entity_id; for fine-grained review.
     */
    entity_id?: (string & tags.Format<"uuid">) | null;

    /**
     * Audit action performed (e.g., 'create', 'update', 'refund', etc).
     * Indexed string from payment_audits.action.
     */
    action?: string | null;

    /**
     * Filter audit entries occurring after this UTC time. Supports audit
     * window queries for compliance.
     */
    timestamp_from?: (string & tags.Format<"date-time">) | null;

    /**
     * Filter audit entries before this UTC timestamp. Enables audit window
     * selection for forensics or reporting.
     */
    timestamp_to?: (string & tags.Format<"date-time">) | null;

    /** The results page to return. For pagination efficiency. */
    page?:
      | (number &
          tags.Type<"int32"> &
          tags.JsonSchemaPlugin<{
            format: "uint32";
          }>)
      | null;

    /**
     * Page size. Administrative cap may apply to prevent evidence query
     * overload.
     */
    limit?:
      | (number &
          tags.Type<"int32"> &
          tags.JsonSchemaPlugin<{
            format: "uint32";
          }>)
      | null;
  };

  /**
   * Payload for creating a new payment audit record, capturing the action,
   * evidence, and user/system association for compliance.
   */
  export type ICreate = {
    /**
     * The UUID of the user who performed this action. May be null for
     * system or automated actions.
     */
    user_id?: (string & tags.Format<"uuid">) | null;

    /**
     * String identifier for the type of entity being audited (e.g.,
     * 'payment', 'discount', 'refund').
     */
    entity_type: string;

    /**
     * The UUID of the target entity for which this audit log is being
     * recorded.
     */
    entity_id: string & tags.Format<"uuid">;

    /**
     * The action taken, such as 'create', 'update', 'apply', 'fail',
     * 'refund'.
     */
    action: string;

    /**
     * Optional. The previous state or value before the audit action, for
     * evidence and regulatory review. May be null when not applicable
     * (e.g., initial creation).
     */
    old_value?: string | null;

    /**
     * Optional. The new state or value after the action, for compliance and
     * evidence. May be null (e.g., for deletes).
     */
    new_value?: string | null;

    /**
     * The timestamp at which this audit event is created. Should be set to
     * the precise time the event occurred.
     */
    timestamp: string & tags.Format<"date-time">;
  };
}

