import type { IPaymentAudit } from "@ORGANIZATION/PROJECT-api/lib/structures/IPaymentAudit";
import type { IPageIPaymentAudit } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPaymentAudit";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * E2E 테스트: 결제 감사(Audit) 이벤트의 목록 조회 및 필터
 *
 * 이 테스트는 다음을 검증합니다:
 * - 결제/할인/환불 등의 감사를 위한 단일 atomic 이벤트 레코드가 존재할 경우 목록 조회가 정상 동작하는지
 * - 다양한 필터(user_id, entity_type, entity_id, action, timestamp 등)와 페이징 기능(page, limit)이 올바르게 동작하는지
 * - 결과에 총 개수/필드가 정확히 반영되는지 및 비정상 케이스(검색결과 없음, 과도한 page size 등)에서의 동작을 검증
 *
 * [테스트 시나리오]
 * 1. audit record 생성 (dependency API)
 * 2. 기본 목록 조회 (제약없는 전부 검색)
 * 3. 각 필터별 단일 조회(user_id, entity_type, entity_id, action, timestamp)
 * 4. 페이지네이션(page, limit) 정상동작 검증
 * 5. 없는 값 필터시 결과 없음 확인
 * 6. 허용 limit 초과시 페일 오버 검증
 */
export async function test_api_paymentsDiscounts_test_list_and_filter_payment_audit_events(
  connection: api.IConnection,
) {
  // 1. (의존성) 결제 감사 이벤트 레코드 생성
  const auditCreateInput: IPaymentAudit.ICreate = {
    user_id: typia.random<string & tags.Format<'uuid'>>(),
    entity_type: 'payment',
    entity_id: typia.random<string & tags.Format<'uuid'>>(),
    action: 'create',
    old_value: null,
    new_value: JSON.stringify({ amount: 10000 }),
    timestamp: new Date().toISOString(),
  };
  const created: IPaymentAudit = await api.functional.paymentsDiscounts.paymentAudits.post(connection, {
    body: auditCreateInput,
  });
  typia.assert(created);

  // 2. 전체 목록 조회 - 필터 없이 모두 (방금 생성 포함)
  const foundAll = await api.functional.paymentsDiscounts.paymentAudits.patch(connection, {
    body: {},
  });
  typia.assert(foundAll);
  TestValidator.predicate('생성한 audit가 포함되어야 함')(!!foundAll.data.find(a => a.id === created.id));

  // 3-1. user_id 필터
  const foundByUser = await api.functional.paymentsDiscounts.paymentAudits.patch(connection, {
    body: { user_id: created.user_id },
  });
  typia.assert(foundByUser);
