import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPaymentAudit } from "@ORGANIZATION/PROJECT-api/lib/structures/IPaymentAudit";

/**
 * Validate retrieval of a payment audit event record by its unique identifier.
 *
 * This test covers both successful retrieval with a known, valid payment audit ID and failure handling with a non-existent ID.
 *
 * Business Context:
 * The audit trail in payments, discounts, and refunds is critical for compliance, regulatory processes, and dispute forensics. Access to audit logs is privileged and must always provide an immutable, correct history for any given operation ID. Proper error responses are essential to prevent information leakage and ensure UI error handling is robust.
 *
 * Test Steps:
 * 1. Create a new payment audit record (to guarantee existence of a valid ID for GET test).
 * 2. Retrieve the payment audit event by its ID using GET. Validate the returned record matches what was inserted and follows the contract (all required fields, type safety).
 * 3. Try retrieving a payment audit record with a random, non-existent UUID. Confirm that the endpoint returns 404 or proper error response, and does not expose private details in the error.
 */
export async function test_api_paymentsDiscounts_test_get_payment_audit_event_by_id(connection: api.IConnection) {
  // 1. Create a new payment audit record for control
  const now = new Date().toISOString();
  const createInput: IPaymentAudit.ICreate = {
    // user_id is optional/null for system events, but we provide it for test completeness
    user_id: typia.random<string & tags.Format<"uuid">>(),
    entity_type: "payment",
    entity_id: typia.random<string & tags.Format<"uuid">>(),
    action: "create",
    old_value: null,
    new_value: JSON.stringify({ amount: 1000, currency: "KRW" }),
    timestamp: now,
  };
  const audit: IPaymentAudit = await api.functional.paymentsDiscounts.paymentAudits.post(connection, { body: createInput });
  typia.assert(audit);

  // 2. Retrieve the payment audit event by ID
  const got: IPaymentAudit = await api.functional.paymentsDiscounts.paymentAudits.getById(connection, { id: audit.id });
  typia.assert(got);
  TestValidator.equals("audit.id")(audit.id)(got.id);
  TestValidator.equals("entity_type")(createInput.entity_type)(got.entity_type);
  TestValidator.equals("action")(createInput.action)(got.action);
  TestValidator.equals("entity_id")(createInput.entity_id)(got.entity_id);
  TestValidator.equals("timestamp")(createInput.timestamp)(got.timestamp);

  // 3. Negative case: attempt to get a non-existent ID
  const randomId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("404 Not Found on non-existent audit ID")(() => 
    api.functional.paymentsDiscounts.paymentAudits.getById(connection, { id: randomId })
  );
}

