import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPaymentAudit } from "@ORGANIZATION/PROJECT-api/lib/structures/IPaymentAudit";

/**
 * Validate creation of payment audit events for the PaymentsDiscounts module.
 *
 * This test covers both successful and failure scenarios:
 * 1. Successfully create a new payment audit event with all required fields and confirm the output is persisted and well-formed.
 * 2. Attempt to create with missing required fields (e.g. missing entity_id, entity_type, action) and expect a validation error.
 * 3. Attempt to create with incorrect data types (e.g. non-uuid for entity_id, non-date string for timestamp) and expect validation failure.
 *
 * Steps:
 * 1. Prepare valid IPaymentAudit.ICreate payload: include required fields like entity_type, entity_id (uuid), action, and timestamp (date-time).
 * 2. Call the API and assert the response type and data completeness.
 * 3. Try missing required fields one by one and check for proper error responses.
 * 4. Try invalid types (entity_id not a uuid, timestamp not ISO date-time) and check for error.
 */
export async function test_api_paymentsDiscounts_test_create_payment_audit_event_with_valid_and_invalid_data(
  connection: api.IConnection,
) {
  // 1. Create a valid payment audit record
  const validPayload: IPaymentAudit.ICreate = {
    user_id: typia.random<string & tags.Format<"uuid">>(),
    entity_type: "payment",
    entity_id: typia.random<string & tags.Format<"uuid">>(),
    action: "create",
    old_value: null,
    new_value: JSON.stringify({ amount: 1000, currency: "KRW" }),
    timestamp: new Date().toISOString(),
  };

  const audit = await api.functional.paymentsDiscounts.paymentAudits.post(connection, { body: validPayload });
  typia.assert(audit);
  TestValidator.equals("entity_type")(validPayload.entity_type)(audit.entity_type);
  TestValidator.equals("entity_id")(validPayload.entity_id)(audit.entity_id);
  TestValidator.equals("action")(validPayload.action)(audit.action);
  TestValidator.equals("timestamp")(validPayload.timestamp)(audit.timestamp);

  // 2. Failure: missing required field - entity_id
  const { entity_id, ...payloadMissingEntityId } = validPayload;
  await TestValidator.error("missing entity_id should fail")(async () => {
    // @ts-expect-error: for test only (simulate field omission)
    await api.functional.paymentsDiscounts.paymentAudits.post(connection, { body: payloadMissingEntityId });
  });

  // 3. Failure: invalid data type for entity_id
  const invalidEntityIdPayload = { ...validPayload, entity_id: "not-a-uuid" };
  await TestValidator.error("invalid entity_id type should fail")(async () => {
    await api.functional.paymentsDiscounts.paymentAudits.post(connection, { body: invalidEntityIdPayload });
  });

  // 4. Failure: invalid type for timestamp
  const invalidTimestampPayload = { ...validPayload, timestamp: "not-a-date" };
  await TestValidator.error("invalid timestamp type should fail")(async () => {
    await api.functional.paymentsDiscounts.paymentAudits.post(connection, { body: invalidTimestampPayload });
  });
}

