import { tags } from "typia";

import { IMessage } from "./IMessage";

/**
 * Atomic conversation thread entity for user-to-user, user-to-support, or
 * moderation/communication flows.
 *
 * Implements message_threads table. All business, evidence, and regulatory
 * fields are preserved for compliance and observability.
 *
 * May embed message DTOs in detail view depending on query.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IMessageThread = {
  /** Unique identifier for the thread. See message_threads.id in schema. */
  id: string & tags.Format<"uuid">;

  /** UUID of the user who created the thread. */
  created_by_user_id: string & tags.Format<"uuid">;

  /** Thread subject/title. Used for navigation, inbox listings, and discovery. */
  subject: string;

  /**
   * Soft delete/archival flag (never physically deleted). Used by
   * compliance/evidence/audit for traceability.
   */
  archived: boolean;

  /** Timestamp when thread was created. Evidence/audit trace (created_at). */
  created_at: string & tags.Format<"date-time">;

  /**
   * Timestamp when thread was last updated (user activity, archiving, new
   * message, etc.).
   */
  updated_at: string & tags.Format<"date-time">;

  /**
   * Array of individual message DTOs in thread. Populated only in
   * detail/export views; for list queries, typically omitted for
   * scalability.
   */
  messages?: IMessage[];
};
export namespace IMessageThread {
  /**
   * Search and filtering request object for listing or searching message
   * threads. Enables advanced inbox, admin, or evidence query workflows.
   */
  export type IRequest = {
    /**
     * Case-insensitive search or filter on the thread subject. Supports
     * partial match for inbox or admin discovery.
     */
    subject?: string;

    /**
     * UUID of the thread creator. Used for filtering threads in
     * multi-tenant or support scenarios.
     */
    created_by_user_id?: string & tags.Format<"uuid">;

    /**
     * Filter by archival status. True shows only archived (deleted)
     * threads. False or omitted shows only active or non-archived threads.
     */
    archived?: boolean;

    /** Filter: earliest creation timestamp for thread discovery. ISO string. */
    created_from?: string & tags.Format<"date-time">;

    /** Filter: latest creation timestamp for thread discovery. ISO string. */
    created_to?: string & tags.Format<"date-time">;

    /** Filter: earliest updated timestamp for thread discovery. ISO string. */
    updated_from?: string & tags.Format<"date-time">;

    /** Filter: latest updated timestamp for thread discovery. ISO string. */
    updated_to?: string & tags.Format<"date-time">;

    /** Page number for pagination (1-based). */
    page?: number &
      tags.Type<"int32"> &
      tags.Default<1> &
      tags.Minimum<1> &
      tags.JsonSchemaPlugin<{
        format: "int32";
      }>;

    /** Number of threads per page. */
    limit?: number &
      tags.Type<"int32"> &
      tags.Default<20> &
      tags.Minimum<1> &
      tags.Maximum<200> &
      tags.JsonSchemaPlugin<{
        format: "int32";
      }>;

    /** Sort result set by this field (created_at, updated_at, or subject). */
    sort_field?: "created_at" | "updated_at" | "subject";

    /** Sort direction (ascending or descending). */
    sort_order?: "asc" | "desc";
  };

  /**
   * Payload for creating new conversation thread. Must include subject,
   * created_by_user_id (if system/admin), and may set archived flag for admin
   * flows.
   */
  export type ICreate = {
    /**
     * The creating user's UUID. Required only for system/admin
     * audits—otherwise set from authentication context.
     */
    created_by_user_id?: string & tags.Format<"uuid">;

    /**
     * Subject/title for the thread. Required for thread discoverability and
     * navigation.
     */
    subject: string;

    /**
     * Create thread as archived (unusual, admin use only). Default is false
     * (active).
     */
    archived?: boolean;
  };
}

