import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IMessageThread } from "@ORGANIZATION/PROJECT-api/lib/structures/IMessageThread";
import type { IPageIMessageThread } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIMessageThread";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IMessage } from "@ORGANIZATION/PROJECT-api/lib/structures/IMessage";

/**
 * 메시지 스레드의 리스트 조회와 검색 기능을 검증합니다.
 *
 * 이 테스트는 다양한 조건(subject, status, sender 등)으로 메시지 스레드를 검색 및 조회하는 전체 워크플로우, 그리고 페이지네이션/필터 조합을 종합적으로 검증합니다. 데이터가 없거나, 필터에 맞지 않는 쿼리(0건 반환) 등 엣지 케이스도 같이 확인합니다.
 *
 * 1. 샘플 메시지 스레드를 생성합니다(의존성).
 * 2. 생성된 subject로 필터 검색해 해당 thread가 노출되는지 확인합니다.
 * 3. 존재하지 않는 subject로 검색 시 결과가 0건임을 검증합니다.
 * 4. created_by_user_id, archived 플래그 등 다양한 필터 조합으로도 결과를 검증합니다.
 * 5. page, limit을 조절해 페이지네이션 로직도 확인합니다.
 */
export async function test_api_communicationReview_test_list_and_filter_message_threads(
  connection: api.IConnection,
) {
  // 1. 샘플 메시지 스레드 생성
  const sampleSubject = RandomGenerator.paragraph()(1);
  const createThread = await api.functional.communicationReview.messageThreads.post(connection, {
    body: {
      subject: sampleSubject,
    } satisfies IMessageThread.ICreate,
  });
  typia.assert(createThread);
  // 2. subject로 검색(존재O)
  const searchBySubject = await api.functional.communicationReview.messageThreads.patch(connection, {
    body: { subject: sampleSubject } satisfies IMessageThread.IRequest,
  });
  typia.assert(searchBySubject);
  TestValidator.predicate("subject로 검색 시 반환됨")(searchBySubject.data.map(t => t.id).includes(createThread.id));
  // 3. subject로 검색(존재X)
  const notExistSubject = sampleSubject + "_NO_HIT";
  const noResult = await api.functional.communicationReview.messageThreads.patch(connection, {
    body: { subject: notExistSubject } satisfies IMessageThread.IRequest,
  });
  typia.assert(noResult);
  TestValidator.equals("0건 반환")(0)(noResult.data.length);
  // 4. created_by_user_id, archived 플래그 등 복합 조건 검색
  const compoundSearch = await api.functional.communicationReview.messageThreads.patch(connection, {
    body: { created_by_user_id: createThread.created_by_user_id, subject: sampleSubject, archived: false } satisfies IMessageThread.IRequest,
  });
  typia.assert(compoundSearch);
  TestValidator.predicate("user와 subject, archived 복합 조건 반환됨")(compoundSearch.data.some(t => t.id === createThread.id));
  // 5. 페이지네이션 (limit 1)
  const page1 = await api.functional.communicationReview.messageThreads.patch(connection, {
    body: { limit: 1, sort_field: "created_at", sort_order: "desc" } satisfies IMessageThread.IRequest,
  });
  typia.assert(page1);
  TestValidator.equals("페이지네이션 limit=1")(1)(page1.data.length);
}

