import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IMessageThread } from "@ORGANIZATION/PROJECT-api/lib/structures/IMessageThread";
import type { IPageIMessageThread } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIMessageThread";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IMessage } from "@ORGANIZATION/PROJECT-api/lib/structures/IMessage";

/**
 * 메시지 스레드의 리스트 조회와 다양한 필터 검색 및 페이지네이션 논리를 종합적으로 검증합니다.
 *
 * - 사용자는 다양한 조건(subject, archived, 생성자 등)으로 메시지 스레드 목록을 검색할 수 있어야 합니다.
 * - 페이지네이션 및 정렬 로직, 잘못된 필터 조합이나 데이터가 없는 필터(0건 반환) 등 엣지 케이스도 함께 검증합니다.
 *
 * [테스트 절차]
 * 1. 테스트 검증용 샘플 메시지 스레드를 생성한다.
 * 2. subject로만 검색해 해당 thread가 정확히 검색되는지 확인한다.
 * 3. 존재하지 않는 subject로 검색 시 0건임을 검증한다.
 * 4. created_by_user_id, archived 플래그 등 다양한 필터 조합으로도 검색이 올바르게 동작하는지 확인한다.
 * 5. page, limit을 조절(예: limit=1)해 페이지네이션 논리 및 응답이 일관적인지도 확인한다.
 */
export async function test_api_communicationReview_test_list_and_filter_message_threads(
  connection: api.IConnection,
) {
  // 1. 샘플 메시지 스레드 생성
  const sampleSubject = RandomGenerator.paragraph()(1);
  const createdThread = await api.functional.communicationReview.messageThreads.post(connection, {
    body: {
      subject: sampleSubject,
    } satisfies IMessageThread.ICreate,
  });
  typia.assert(createdThread);

  // 2. subject로 검색 (존재O, 정확히 노출)
  const foundBySubject = await api.functional.communicationReview.messageThreads.patch(connection, {
    body: { subject: sampleSubject } satisfies IMessageThread.IRequest,
  });
  typia.assert(foundBySubject);
  TestValidator.predicate("subject로 검색 시 thread가 반환됨")(
    foundBySubject.data.map(t => t.id).includes(createdThread.id)
  );

  // 3. 존재하지 않는 subject로 검색 (0건)
  const noHitSubject = sampleSubject + "_NORESULT";
  const notFound = await api.functional.communicationReview.messageThreads.patch(connection, {
    body: { subject: noHitSubject } satisfies IMessageThread.IRequest,
  });
  typia.assert(notFound);
  TestValidator.equals("존재하지 않는 subject 0건 반환")(0)(notFound.data.length);

  // 4. created_by_user_id, archived 복합 조건 검색
  const filteredByUserAndArchived = await api.functional.communicationReview.messageThreads.patch(connection, {
    body: {
      created_by_user_id: createdThread.created_by_user_id,
      subject: sampleSubject,
      archived: false,
    } satisfies IMessageThread.IRequest,
  });
  typia.assert(filteredByUserAndArchived);
  TestValidator.predicate("user/subject/archived로도 thread 노출")(
    filteredByUserAndArchived.data.some(t => t.id === createdThread.id)
  );

  // 5. 페이지네이션, 정렬 (limit=1)
  const pageLimited = await api.functional.communicationReview.messageThreads.patch(connection, {
    body: {
      limit: 1,
      sort_field: "created_at",
      sort_order: "desc",
    } satisfies IMessageThread.IRequest,
  });
  typia.assert(pageLimited);
  TestValidator.equals("limit 1 반환")(1)(pageLimited.data.length);
}

