import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IMessageThread } from "@ORGANIZATION/PROJECT-api/lib/structures/IMessageThread";
import type { IMessage } from "@ORGANIZATION/PROJECT-api/lib/structures/IMessage";

/**
 * Validate fetching a specific message thread by its ID.
 *
 * This test checks two scenarios: (1) retrieving a thread with a valid ID returns all expected information, and (2) attempting to fetch a non-existent thread returns an error. It also demonstrates dependency handling by first creating a thread for use in the valid test scenario.
 *
 * Step-by-step process:
 * 1. Create a new message thread, retrieving its ID for subsequent retrieval.
 * 2. Fetch the newly created thread by its ID and validate that all relevant fields are present and correct (ID consistency, subject, etc).
 * 3. Attempt fetching a thread using a random (invalid) UUID, and confirm that the API responds with an error (not found or permission denied).
 */
export async function test_api_communicationReview_messageThreads_getById(
  connection: api.IConnection,
) {
  // 1. Create a message thread to use as the valid test subject
  const thread = await api.functional.communicationReview.messageThreads.post(connection, {
    body: {
      subject: RandomGenerator.paragraph()(3),
    } satisfies IMessageThread.ICreate,
  });
  typia.assert(thread);

  // 2. Fetch the thread by its ID and validate the data
  const fetched = await api.functional.communicationReview.messageThreads.getById(connection, {
    id: thread.id,
  });
  typia.assert(fetched);
  TestValidator.equals("fetched.id matches thread.id")(thread.id)(fetched.id);
  TestValidator.equals("fetched.subject matches thread.subject")(thread.subject)(fetched.subject);

  // 3. Try fetching by invalid ID and expect error
  await TestValidator.error("should fail for random non-existent id")(() =>
    api.functional.communicationReview.messageThreads.getById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
    }),
  );
}

