import api from "@ORGANIZATION/PROJECT-api";
import type { IMessageThread } from "@ORGANIZATION/PROJECT-api/lib/structures/IMessageThread";
import type { IMessage } from "@ORGANIZATION/PROJECT-api/lib/structures/IMessage";

/**
 * Validate fetching a specific message thread by its ID.
 *
 * 검증 목적:
 * - 정상 케이스: 실제로 존재하는 메시지 스레드의 ID로 조회 시, 올바른 레코드와 세부 정보(주제, 식별자 등)가 반환되는지 확인합니다.
 * - 오류 케이스: 임의/존재하지 않는 ID로 조회 시, API가 적절한 오류를 반환하는지 확인합니다.
 *
 * 실제 사용 워크플로우에 따라 의존성으로 스레드를 생성한 후, 그 ID를 사용해 세부정보를 요청하며,
 * 잘못된(존재하지 않는) ID 요청 시에도 예상대로 실패하는지 검증합니다.
 *
 * [프로세스]
 * 1. 메시지 스레드를 새로 생성합니다.
 * 2. 생성된 스레드를 ID로 가져와 모든 필드(식별자, 주제 등) 일치 여부를 검증합니다.
 * 3. 무작위(존재하지 않는) UUID로 요청 시, 에러가 발생하는지 확인합니다.
 */
export async function test_api_communicationReview_messageThreads_getById(
  connection: api.IConnection,
) {
  // 1. 메시지 스레드 생성(후속 조회 테스트를 위해)
  const created = await api.functional.communicationReview.messageThreads.post(connection, {
    body: {
      subject: RandomGenerator.paragraph()(3),
    } satisfies IMessageThread.ICreate,
  });
  typia.assert(created);

  // 2. 방금 생성한 id로 조회, 상세 필드 검증
  const fetched = await api.functional.communicationReview.messageThreads.getById(connection, {
    id: created.id,
  });
  typia.assert(fetched);
  TestValidator.equals("fetched.id matches created.id")
    (created.id)(fetched.id);
  TestValidator.equals("fetched.subject matches created.subject")
    (created.subject)(fetched.subject);

  // 3. 존재하지 않는 ID 요청 시, 적절히 실패하는지 확인
  await TestValidator.error("non-existent id fetch should fail")(
    async () =>
      api.functional.communicationReview.messageThreads.getById(connection, {
        id: typia.random<string & tags.Format<"uuid">>(),
      })
  );
}

