import type { IMessage } from "@ORGANIZATION/PROJECT-api/lib/structures/IMessage";

/**
 * Update a message thread and validate persistence and error handling for nonexistent ID.
 *
 * Business purpose: Ensures that atomic changes to a message thread (such as updating subject or archiving status) are applied correctly and reflected when reloading, and verifies error response when attempting to update a nonexistent thread. This supports compliance, auditability, and correct UX for communication systems.
 *
 * Step-by-step process:
 * 1. Create a message thread (dependency setup for update testing).
 * 2. Update an attribute of the created thread (e.g., change subject, archived flag).
 * 3. Reload/fetch the thread and ensure updates are reflected (subject, archival status match the updated values).
 * 4. Attempt to update a thread using a random non-existent UUID, expect an error (exception thrown or failed status).
 */
export async function test_api_communicationReview_test_update_message_thread_by_id(connection: api.IConnection) {
  // 1. Create a message thread to have a valid entity to update
  const initialSubject = RandomGenerator.paragraph()(1);
  const thread = await api.functional.communicationReview.messageThreads.post(connection, {
    body: {
      subject: initialSubject
    } satisfies IMessageThread.ICreate
  });
  typia.assert(thread);

  // 2. Update the subject and archive status
  const updatedSubject = initialSubject + " - updated";
  const updatedArchived = !thread.archived;
  const updated = await api.functional.communicationReview.messageThreads.putById(connection, {
    id: thread.id,
    body: {
      subject: updatedSubject,
      archived: updatedArchived
    } satisfies IMessageThread.IUpdate
  });
  typia.assert(updated);
  TestValidator.equals("id matches")(thread.id)(updated.id);
  TestValidator.equals("subject updated")(updatedSubject)(updated.subject);
  TestValidator.equals("archived flag updated")(updatedArchived)(updated.archived);

  // 3. Optionally reload the thread (if get API exists), skipped here (no fetch API specified)

  // 4. Try to update with a non-existent thread ID and expect error
  await TestValidator.error("updating non-existent thread fails")(async () => {
    await api.functional.communicationReview.messageThreads.putById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
      body: {
        subject: RandomGenerator.paragraph()(1),
        archived: false
      } satisfies IMessageThread.IUpdate
    });
  });
}

