import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IMessageThread } from "@ORGANIZATION/PROJECT-api/lib/structures/IMessageThread";
import type { IMessage } from "@ORGANIZATION/PROJECT-api/lib/structures/IMessage";

/**
 * Validates soft-delete (archiving) functionality for a message thread by its unique ID.
 *
 * Ensures:
 * - Deleting (archiving) a valid thread returns success and records archive timestamp.
 * - Archived threads are not present in regular queries (out of scope here but mentioned for design completeness).
 * - System preserves archived thread for audit (as per business/investigation requirements).
 * - Deleting a non-existent thread returns a proper error response without side effects.
 *
 * Step-by-step process:
 * 1. Create a new message thread to obtain a valid thread id (dependency step).
 * 2. Archive (delete) the thread using eraseById and check returned result structure (archive timestamp, id match).
 * 3. Attempt to archive a non-existent thread id and assert error is thrown.
 */
export async function test_api_communicationReview_test_archive_message_thread_by_id(
  connection: api.IConnection,
) {
  // 1. Create a new message thread (dependency)
  const subject = `Thread for soft delete test - ${RandomGenerator.alphaNumeric(8)}`;
  const created: IMessageThread = await api.functional.communicationReview.messageThreads.post(connection, {
    body: {
      subject
    } satisfies IMessageThread.ICreate,
  });
  typia.assert(created);

  // 2. Archive (soft-delete) the thread by ID
  const result: IMessageThread.IDeleteResult = await api.functional.communicationReview.messageThreads.eraseById(connection, {
    id: created.id,
  });
  typia.assert(result);
  TestValidator.equals('archived thread id')(created.id)(result.id);
  TestValidator.predicate('archive timestamp exists')(!!result.archived_at);

  // 3. Try archiving a non-existent thread id (random UUID not matching any thread)
  await TestValidator.error('non-existent thread yields error')(() =>
    api.functional.communicationReview.messageThreads.eraseById(connection, {
      id: typia.random<string & tags.Format<'uuid'>>(),
    }),
  );
}

