  sent_at: string & tags.Format<"date-time">;

  /** 수신자가 읽은 시각(읽지 않았으면 null). CommunicationReview.messages.read_at. */
  read_at?: (string & tags.Format<"date-time">) | null;

  /** 삭제/보관(아카이브) 여부. 삭제 시 true. CommunicationReview.messages.archived. */
  archived: boolean;
};
export namespace IMessage {
  /**
   * Filter/search request for messages within a conversation thread.
   * Full-text, archival, timestamp, sender, and thread filtering enabled for
   * moderation or audit evidentiary review.
   */
  export type IRequest = {
    /** Filter for messages belonging to specific thread. */
    thread_id?: string & tags.Format<"uuid">;

    /** Filter for messages sent by specific user. */
    sender_user_id?: string & tags.Format<"uuid">;

    /** Filter for type (user, system, notification, or custom code). */
    message_type?: string;

    /** Search by archived (deleted) status. */
    archived?: boolean;

    /**
     * Full-text message content query. Partial or keyword search enabled
     * for analytics/mod/search.
     */
    content?: string;

    /** Filter: earliest sent_at timestamp. */
    sent_from?: string & tags.Format<"date-time">;

    /** Filter: latest sent_at timestamp. */
    sent_to?: string & tags.Format<"date-time">;

    /** Search by read (true/false) status. */
    read?: boolean;

    /** Page number for paging. */
    page?: number &
      tags.Type<"int32"> &
      tags.Default<1> &
      tags.Minimum<1> &
      tags.JsonSchemaPlugin<{
        format: "int32";
      }>;

    /** Paging size. */
    limit?: number &
      tags.Type<"int32"> &
      tags.Default<25> &
      tags.Minimum<1> &
      tags.Maximum<100> &
      tags.JsonSchemaPlugin<{
        format: "int32";
      }>;

    /** Field to sort on (sent_at or read_at). */
    sort_field?: "sent_at" | "read_at";

    /** Sort direction for results. */
    sort_order?: "asc" | "desc";
  };

  /**
   * 메시지 신규 생성시 입력하는 데이터 구조.
   *
   * 스레드 ID, 메시지 본문, 메시지 종류(사용자, 시스템 등)를 명시적으로 입력해야 하며, 답장/인용 메시지라면
   * parent_message_id도 함께 전달합니다. CommunicationReview.messages 테이블 구조와 동일하게
   * 맞추어 생성 입력 파라미터를 정의함.
   */
  export type ICreate = {
    /**
     * 대상이 되는 스레드의 ID. 메시지 생성시 반드시 명시해야 함.
     * CommunicationReview.messages.thread_id.
     */
    thread_id: string & tags.Format<"uuid">;

    /** 작성할 메시지 본문. CommunicationReview.messages.content. */
    content: string;

    /**
     * 메시지 타입(user/system/notification 등).
     * CommunicationReview.messages.message_type.
     */
    message_type: string;

    /**
     * 답장/인용할 상위 메시지의 ID (없으면 null 허용).
     * CommunicationReview.messages.parent_message_id.
     */
    parent_message_id?: (string & tags.Format<"uuid">) | null;
  };
}

