import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IMessage } from "@ORGANIZATION/PROJECT-api/lib/structures/IMessage";
import type { IPageIMessage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIMessage";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * 메시지 목록/검색 및 필터링 + 페이징 테스트
 *
 * - 다양한 필터(thread_id, sender_user_id, message_type 등)와 페이징 조합이 의도한 데이터만 반환하는지 검증
 * - 레코드가 없거나 잘못된 검색 시 빈 리스트, pagination 일관성 확인
 * - limit/page 조합으로 오프셋·페이징 정상 동작, 전체 갯수/offset 일관성
 * - 잘못된 uuid 등 유효성/에러 처리
 */
export async function test_api_communicationReview_test_list_and_filter_messages(
  connection: api.IConnection,
) {
  // 1. 테스트용 기본 메시지 데이터 여러 건 생성 (thread_id/sender_user_id/message_type 조합 다양화)
  // 1-1. 각각 다른 thread/발신자/유형/내용/상태(archived/read 등)로 3건 생성
  const threadId1 = typia.random<string & tags.Format<"uuid">>();
  const threadId2 = typia.random<string & tags.Format<"uuid">>();
  const senderUserId1 = typia.random<string & tags.Format<"uuid">>();
  const senderUserId2 = typia.random<string & tags.Format<"uuid">>();

  // 메시지 3건 생성(1번 스레드-1번유저/2번유저, 2번 스레드-1번유저)
  const msg1 = await api.functional.communicationReview.messages.post(connection, {
    body: {
      thread_id: threadId1,
      content: "메시지-테스트-본문1",
      message_type: "user",
      parent_message_id: null,
    },
  });
  typia.assert(msg1);

  const msg2 = await api.functional.communicationReview.messages.post(connection, {
    body: {
      thread_id: threadId1,
      content: "두번째 메시지 내용",
      message_type: "system",
      parent_message_id: null,
    },
  });
  typia.assert(msg2);

  const msg3 = await api.functional.communicationReview.messages.post(connection, {
    body: {
      thread_id: threadId2,
      content: "세번째 thread/다른 사용자",
      message_type: "notification",
      parent_message_id: null,
    },
  });
  typia.assert(msg3);

  // 2. 전체 메시지 목록(아무 필터 없이) 조회 - 3건 이상 존재 + pagination 전체 카운트
  const resAll = await api.functional.communicationReview.messages.patch(connection, {
    body: {}, // 필터 없음
  });
  typia.assert(resAll);
  TestValidator.predicate("message 전체 3건 이상 존재")(resAll.data.length >= 3);
  TestValidator.equals("전체 pagination.records==생성 메시지 수")(
    resAll.pagination.records,
  )(resAll.data.length);

  // 3. thread_id로만 필터링 → thread1 소속만
  const resThread1 = await api.functional.communicationReview.messages.patch(connection, {
    body: { thread_id: threadId1 },
  });
  typia.assert(resThread1);
  TestValidator.predicate("thread1의 메시지 2건 반환")(
    resThread1.data.length === 2 && resThread1.data.every((m) => m.thread_id === threadId1),
  );
  TestValidator.equals("thread1 pagination records==2")(2)(resThread1.pagination.records);

  // 4. sender_user_id 필터(존재하지 않는 가상id → 빈결과)
  const resNoSender = await api.functional.communicationReview.messages.patch(connection, {
    body: { sender_user_id: typia.random<string & tags.Format<"uuid">>() },
  });
  typia.assert(resNoSender);
  TestValidator.equals("없는 sender_user_id는 0건")(
    0,
  )(resNoSender.data.length);
  TestValidator.equals("없는 sender_user_id pagination.records==0")(0)(resNoSender.pagination.records);

  // 5. message_type + thread 조합
  const resCombo = await api.functional.communicationReview.messages.patch(connection, {
    body: { thread_id: threadId1, message_type: "system" },
  });
  typia.assert(resCombo);
  TestValidator.equals("thread1+system 조합 1건")(
    1,
  )(resCombo.data.length);
  TestValidator.equals("thread1+system pagination.records==1")(1)(resCombo.pagination.records);
  if (resCombo.data.length) {
    TestValidator.equals("combo 결과의 message_type=system")(
      "system",
    )(resCombo.data[0].message_type);
    TestValidator.equals("combo 결과의 thread_id==threadId1")(
      threadId1,
    )(resCombo.data[0].thread_id);
  }

  // 6. content(본문 키워드)로 검색 (부분일치)
  const resContent = await api.functional.communicationReview.messages.patch(connection, {
    body: { content: "테스트-본문" },
  });
  typia.assert(resContent);
  TestValidator.predicate("content=테스트-본문 포함된 결과 존재")(resContent.data.some((m) => m.content.includes("테스트-본문")));

  // 7. 페이징: limit=2, page=1
  const resLimit2_page1 = await api.functional.communicationReview.messages.patch(connection, {
    body: { limit: 2, page: 1 },
  });
  typia.assert(resLimit2_page1);
  TestValidator.equals("limit=2, page=1 데이터 2건(최대)")(
    2,
  )(resLimit2_page1.data.length);
  TestValidator.predicate("pagination.limit=2")(resLimit2_page1.pagination.limit === 2);
  TestValidator.equals(
    "페이징 전체 records==생성 메시지 수",
  )(resLimit2_page1.pagination.records)(resAll.pagination.records);

  // 8. 페이징: page=2, limit=2 → 남은 1건 또는 0건 반환 (합계 3건 기준)
  const resLimit2_page2 = await api.functional.communicationReview.messages.patch(connection, {
    body: { limit: 2, page: 2 },
  });
  typia.assert(resLimit2_page2);
  TestValidator.predicate(
    "limit=2, page=2 데이터 1건 이하",
  )(resLimit2_page2.data.length <= 1);

  // 9. 읽음/아카이브/잘못된 필드(존재하지 않는 uuid 등) 조회 → 예외 검증
  // 9-1. archived=false로 조회(생성 데이터 모두 archived=false)
  const resArchived = await api.functional.communicationReview.messages.patch(connection, {
    body: { archived: false },
  });
  typia.assert(resArchived);
  TestValidator.predicate(
    "archived=false는 결과 있음",
  )(resArchived.data.length > 0);
  TestValidator.equals("archived=false는 모두 archived=false")(
    true,
  )(resArchived.data.every((m) => !m.archived));

  // 9-2. 존재하지 않는 thread_id(uuid)로 조회시 결과 없음
  const resFakeThread = await api.functional.communicationReview.messages.patch(connection, {
    body: { thread_id: typia.random<string & tags.Format<"uuid">>() },
  });
  typia.assert(resFakeThread);
  TestValidator.equals(
    "없는 thread id 검색 결과",
    0,
  )(resFakeThread.data.length);
  TestValidator.equals("없는 thread id pagination.records==0")(0)(resFakeThread.pagination.records);

  // 9-3. 잘못된 uuid 형식으로 조회시 에러
  await TestValidator.error("uuid 포맷 아님 에러 반환")(() =>
    api.functional.communicationReview.messages.patch(connection, {
      body: { thread_id: "not-a-uuid" as any },
    }),
  );
}

