import { IConnection, HttpError } from "@nestia/fetcher";
import { PlainFetcher } from "@nestia/fetcher/lib/PlainFetcher";
import typia, { tags } from "typia";
import { NestiaSimulator } from "@nestia/fetcher/lib/NestiaSimulator";

import { IMessage } from "../../../structures/IMessage";

/**
 * Get detail for a specific message by ID (messages table).
 *
 * This API operation provides all fields of a single Message resource,
 * identified by its unique ID. It retrieves message content, sender and thread
 * references, parent message linkage, type, timestamps, and archived/read
 * status.
 *
 * Access checks are performed based on thread participation or permissions,
 * ensuring only authorized users can view the message. All evidence,
 * versioning, and audit requirements from the messages schema are addressed.
 *
 * The operation surfaces any relationships needed for UI rendering, such as
 * parent message thread and user data, without exposing sensitive information
 * beyond the requester's scope.
 *
 * Related operations: message listing with filters (PATCH), create (POST),
 * update (PUT), delete (DELETE).
 *
 * @param props.connection
 * @param props.id Unique identifier of the target message.
 * @path /communicationReview/messages/:id
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export async function getById(
  connection: IConnection,
  props: getById.Props,
): Promise<getById.Response> {
  return !!connection.simulate
    ? getById.simulate(connection, props)
    : PlainFetcher.fetch(
        {
          ...connection,
          headers: {
            ...connection.headers,
            "Content-Type": "application/json",
          },
        },
        {
          ...getById.METADATA,
          path: getById.path(props),
          status: null,
        },
      );
}
export namespace getById {
  export type Props = {
    /** Unique identifier of the target message. */
    id: string & tags.Format<"uuid">;
  };
  export type Response = IMessage;

  export const METADATA = {
    method: "GET",
    path: "/communicationReview/messages/:id",
    request: null,
    response: {
      type: "application/json",
      encrypted: false,
    },
  } as const;

  export const path = (props: Props) =>
    `/communicationReview/messages/${encodeURIComponent(props.id ?? "null")}`;
  export const random = (g?: Partial<typia.IRandomGenerator>): IMessage =>
    typia.random<IMessage>(g);
  export const simulate = (
    connection: IConnection,
    props: getById.Props,
  ): Response => {
    const assert = NestiaSimulator.assert({
      method: METADATA.method,
      host: connection.host,
      path: getById.path(props),
      contentType: "application/json",
    });
    try {
      assert.param("id")(() => typia.assert(props.id));
    } catch (exp) {
      if (!typia.is<HttpError>(exp)) throw exp;
      return {
        success: false,
        status: exp.status,
        headers: exp.headers,
        data: exp.toJSON().message,
      } as any;
    }
    return random(
      "object" === typeof connection.simulate && null !== connection.simulate
        ? connection.simulate
        : undefined,
    );
  };
}

/**
 * Create a new message within a communication thread (messages table).
 *
 * This API operation enables the creation of a new message by an authenticated
 * user within a message thread. The required data includes the target thread
 * ID, content, sender ID (authenticated user), and optionally a parent message
 * ID for replies.
 *
 * All fields are validated for data type, relationship integrity, and business
 * logic constraints (such as max content length, only valid message types, and
 * thread participation verification). Timestamps for sent_at and initial status
 * are set automatically.
 *
