import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IMessage } from "@ORGANIZATION/PROJECT-api/lib/structures/IMessage";

/**
 * 메시지 ID로 단일 메시지를 조회하는 동작의 정상 및 실패 케이스를 검증합니다.
 *
 * [비즈니스 목적 및 시나리오]
 * 본 테스트는 메시지 테이블(CommunicationReview.messages)에서 한 건의 메시지를 식별자로 가져오는 API를 검증합니다.
 * 1) 우선 정상적인 메시지를 생성하고, 반환받은 id로 getById API를 호출해 응답 메시지의 각 필드(id, thread_id, sender_user_id,
 * content, message_type, sent_at, archived 등)가 정상적으로 반환되는지, 생성시에 준 값과 정확히 일치하는지 검증합니다.
 * 2) 존재하지 않는(무작위) UUID 값으로 API를 호출하여, 서버가 적절한 오류 응답(예: 404 Not Found, 혹은 커스텀 error code 등)을 내보내는지
 * 검증합니다.
 *
 * [테스트 절차]
 * 1. IMessage.ICreate 타입으로 메시지를 생성한다 (POST /communicationReview/messages)
 *   - thread_id, content, message_type(예: "user") 등 필수 입력을 랜덤값 또는 유의미한 값으로 지정
 * 2. 응답된 id로 GET /communicationReview/messages/{id}를 호출한다
 *   - 반환 데이터의 각 필드(내용, 타입, 타임스탬프 등)를 생성 요청시의 값과 일치 여부 비교(정확성 검증)
 * 3. 무작위/비존재 UUID로 GET을 호출해 404 또는 적절한 오류 확인
 */
export async function test_api_communicationReview_test_get_message_by_id(
  connection: api.IConnection,
) {
  // 1. 메시지 생성 (의존성)
  const createInput: IMessage.ICreate = {
    thread_id: typia.random<string & tags.Format<"uuid">>(),
    content: RandomGenerator.paragraph()(),
    message_type: "user",
    parent_message_id: null // 대댓글/인용 아닌 case
  };
  const created: IMessage = await api.functional.communicationReview.messages.post(
    connection,
    { body: createInput },
  );
  typia.assert(created);

  // 2. GET by ID: 생성된 메시지 id로 상세 조회
  const found: IMessage = await api.functional.communicationReview.messages.getById(
    connection,
    { id: created.id },
  );
  typia.assert(found);
  // 입력한 데이터와 반환 데이터 비교(정확성 검증)
  TestValidator.equals("thread_id")(createInput.thread_id)(found.thread_id);
  TestValidator.equals("content")(createInput.content)(found.content);
  TestValidator.equals("message_type")(createInput.message_type)(found.message_type);

  // parent_message_id 필드는 null 허용
  TestValidator.equals("parent_message_id")(createInput.parent_message_id)(found.parent_message_id);
  // archived 등 나머지 필드도 검증 필요(생성 직후 archived=false, sender_user_id 변환 불가 값은 해당 여부만 체크 등)
  TestValidator.equals("archived")(false)(found.archived);

  // 3. 존재하지 않는 메시지 id로 조회 -> 404(또는 커스텀 오류) 발생 검증
  await TestValidator.error("NotFound: 잘못된 메시지 id")(() =>
    api.functional.communicationReview.messages.getById(
      connection,
      { id: typia.random<string & tags.Format<"uuid">>() },
    ),
  );
}

