 * 2. 반환된 id로 getById API를 호출하여 상세 정보를 조회(정상 경로 검증)
 *    - 반환 데이터의 thread_id, content, message_type, parent_message_id, archived 값이 생성시 입력값과 일치하는지 비교
 * 3. 존재하지 않는 가짜 UUID로 조회하여 404 또는 커스텀 에러 반환 여부를 검증(실패 경로)
 */
export async function test_api_communicationReview_test_get_message_by_id(
  connection: api.IConnection,
) {
  // 1. 메시지 생성 (POST /communicationReview/messages)
  const createInput = {
