import { tags } from "typia";

import { IMessage } from "./IMessage";

/**
 * Atomic conversation thread entity for user-to-user, user-to-support, or
 * moderation/communication flows.
 *
 * Implements message_threads table. All business, evidence, and regulatory
 * fields are preserved for compliance and observability.
 *
 * May embed message DTOs in detail view depending on query.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IMessageThread = {
  /** Unique identifier for the thread. See message_threads.id in schema. */
  id: string & tags.Format<"uuid">;

  /** UUID of the user who created the thread. */
  created_by_user_id: string & tags.Format<"uuid">;

  /** Thread subject/title. Used for navigation, inbox listings, and discovery. */
  subject: string;

  /**
   * Soft delete/archival flag (never physically deleted). Used by
   * compliance/evidence/audit for traceability.
   */
  archived: boolean;

  /** Timestamp when thread was created. Evidence/audit trace (created_at). */
  created_at: string & tags.Format<"date-time">;

  /**
   * Timestamp when thread was last updated (user activity, archiving, new
   * message, etc.).
   */
  updated_at: string & tags.Format<"date-time">;

