import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IMessageThread } from "@ORGANIZATION/PROJECT-api/lib/structures/IMessageThread";
import type { IMessage } from "@ORGANIZATION/PROJECT-api/lib/structures/IMessage";

/**
 * 메시지 스레드 내 메시지 생성 및 실패 시나리오 검증 E2E
 *
 * 메시지 스레드 생성 후, 해당 스레드에 메시지를 정상적으로 생성하고,
 * 1) 필수 필드 누락, 2) 존재하지 않는 스레드 ID 사용 같은 실패 케이스도 함께 검증한다.
 *
 * [비즈니스 흐름]
 * 1. 새로운 메시지 스레드를 생성한다.
 * 2. 해당 스레드로 정상 메시지 생성(내용, 타입 등 입력)
 * 3. 생성된 메시지가 올바르게 스레드에 연결 및 메타데이터 세팅 검증
 * 4. content(필수) 누락: 400 등 실패 응답 검증
 * 5. 존재하지 않는 thread_id 사용: 404 또는 400 등 실패 응답 검증
 */
export async function test_api_communicationReview_test_create_message_with_valid_and_invalid_data(
  connection: api.IConnection,
) {
  // 1. 메시지 스레드 선행 생성
  const threadSubject = RandomGenerator.paragraph()(1);
  const thread = await api.functional.communicationReview.messageThreads.post(connection, {
    body: {
      subject: threadSubject,
    } satisfies IMessageThread.ICreate,
  });
  typia.assert(thread);

  // 2. 해당 스레드에 메시지 정상 생성
  const messageContent = RandomGenerator.content()()();
  const messageType = "user"; // 일반 사용자가 작성하는 메시지 시나리오
  const message = await api.functional.communicationReview.messages.post(connection, {
    body: {
      thread_id: thread.id,
      content: messageContent,
      message_type: messageType,
    } satisfies IMessage.ICreate,
  });
  typia.assert(message);
  // 핵심 필드 및 스레드 연결, 메타데이터 검증
  TestValidator.equals("thread 연결") (thread.id) (message.thread_id);
  TestValidator.equals("메시지 본문") (messageContent) (message.content);
  TestValidator.equals("메시지 타입") (messageType) (message.message_type);
  TestValidator.predicate("메타데이터: sent_at ISO 형식 및 archived false") (
    typeof message.sent_at === "string" &&
    message.archived === false
  );

  // 3. 필수 필드(content) 누락 시도 → 실패 검증
  await TestValidator.error("content 누락 시 400 오류") (async () => {
    await api.functional.communicationReview.messages.post(connection, {
      body: {
        thread_id: thread.id,
        // content 누락 intentionally, 타입 컴파일 가능 범위 내에서 시도
        message_type: "user",
      } as IMessage.ICreate, // 실제 E2E에서는 타입 안전 위해 매뉴얼로 테스트 필요
    });
  });

  // 4. 존재하지 않는 thread_id 사용 시도 → 실패 검증
  await TestValidator.error("존재하지 않는 thread_id 사용시 404/400 에러") (async () => {
    await api.functional.communicationReview.messages.post(connection, {
      body: {
        thread_id: typia.random<string & tags.Format<"uuid">>(),
        content: RandomGenerator.content()()(),
        message_type: "user",
      } satisfies IMessage.ICreate,
    });
  });
}

