import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IMessage } from "@ORGANIZATION/PROJECT-api/lib/structures/IMessage";

/**
 * Validate updating a message's content or metadata.
 *
 * Business context:
 * - Messages are core entities exchanged in threads, and users may update them (edit for typo, clarify, archive, etc.).
 * - Updates must apply only where permitted (existing ID).
 *
 * Test steps:
 * 1. Create a new message (so we have a valid message ID to update).
 * 2. Perform an update (change content and/or metadata) using the valid ID.
 *    - Verify the response reflects changes and no unrelated fields are affected.
 * 3. Attempt to update a message with a random non-existent ID (well-formed uuid).
 *    - Expect a 404 or specific error response (update must fail, no resource updated).
 */
export async function test_api_communicationReview_test_update_message_content_and_metadata(connection: api.IConnection) {
  // 1. Create a message to update
  const created = await api.functional.communicationReview.messages.post(connection, {
    body: {
      thread_id: typia.random<string & tags.Format<'uuid'>>(),
      content: 'Original message content',
      message_type: 'user',
      parent_message_id: null,
    } satisfies IMessage.ICreate,
  });
  typia.assert(created);

  // 2. Update the message's content and archived flag
  const updated = await api.functional.communicationReview.messages.putById(connection, {
    id: created.id,
    body: {
      content: 'Updated content',
      archived: true,
