  const nonExistentId = typia.random<string & tags.Format<'uuid'>>();
  await TestValidator.error('404 when updating non-existent message')(async () => {
    await api.functional.communicationReview.messages.putById(connection, {
      id: nonExistentId,
      body: {
        content: 'Should not work',
      } satisfies IMessage.IUpdate,
    });
  });
