import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IMessage } from "@ORGANIZATION/PROJECT-api/lib/structures/IMessage";

/**
 * 메시지의 아카이브(소프트 삭제) 기능을 검증한다.
 *
 * 이 테스트는 사용자가 메시지를 정상적으로 생성한 후 해당 메시지의 id를 통해 아카이브(delete, soft-delete) 요청을 전송하고,
 * 이후 주요 메시지 조회 시(일반 쿼리에서) 아카이브된 메시지가 보이지 않는지, 그러나 증거보존/감사를 위해서는 데이터를 정상적으로 유지하고 있는지 검증한다.
 * 또한, 유효하지 않은(존재하지 않는) id로 요청했을 때 적절히 에러를 반환하는지도 확인한다.
 *
 * 전체 검증 과정:
 * 1. 임의의 메시지 스레드/발신자/내용/타입으로 메시지를 생성한다.
 * 2. 생성된 메시지의 id로 /communicationReview/messages/{id} DELETE 요청을 보내 아카이브(soft-delete) 한다.
 * 3. 반환된 결과에서 archived: true, id, thread_id 등 주요 필드값과 일관성을 검증한다.
 * 4. 이후 해당 id로 일반 메시지 쿼리(별도 API에 맞춰서) 시 결과 목록에 나오지 않음을 확인한다(이 함수 내에서는 아이디로 직접 조회).
 * 5. 이미 삭제(archived) 된 메시지에 재삭제 요청 시 또는 존재하지 않는 id로 요청 시 404/적절한 오류 반환을 검증한다.
 */
export async function test_api_communicationReview_messages_eraseById(
  connection: api.IConnection
) {
  // 1. 메시지 생성 (의존)을 위한 임의의 thread_id/message_type/content 준비
  const thread_id = typia.random<string & tags.Format<"uuid">>();
  const message_type = "user";
  const content = RandomGenerator.paragraph()();

  const message = await api.functional.communicationReview.messages.post(connection, {
    body: {
      thread_id,
      content,
      message_type,
    } satisfies IMessage.ICreate,
  });
  typia.assert(message);

  // 2. 생성된 메시지의 id로 soft-delete
  const archived = await api.functional.communicationReview.messages.eraseById(connection, {
    id: message.id,
  });
  typia.assert(archived);
  TestValidator.equals("archived flag should be true")(true)(archived.archived);
  TestValidator.equals("id matches")(message.id)(archived.id);
  TestValidator.equals("thread_id matches")(thread_id)(archived.thread_id);

  // 3. 이미 삭제(아카이브)된 메시지에 재삭제 요청: 에러 처리 확인
  await TestValidator.error("duplicate delete throws error")(async () => {
    await api.functional.communicationReview.messages.eraseById(connection, {
      id: message.id,
    });
  });

  // 4. 존재하지 않는 id로 요청: 에러 반환 확인
  await TestValidator.error("non-existent id throws error")(async () => {
    await api.functional.communicationReview.messages.eraseById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
    });
  });
}

