  notif2.read_at = new Date(now.getTime() + 1000).toISOString() as string & tags.Format<"date-time">;
  const notif3 = await api.functional.communicationReview.notifications.post(connection, {
    body: {
      user_id: userA,
      notification_type: "system",
      content: "Archived system notif",
    },
  });
  typia.assert(notif3);
  notif3.archived = true;
  const notif4 = await api.functional.communicationReview.notifications.post(connection, {
    body: {
      user_id: userB,
      notification_type: "promotion",
      content: "UserB promotion unread",
    },
  });
  typia.assert(notif4);
  const notif5 = await api.functional.communicationReview.notifications.post(connection, {
    body: {
      user_id: userA,
      notification_type: "message",
      content: "Message notif userA unread",
    },
  });
  typia.assert(notif5);

  // 3. user_id별 목록조회(userA) - 총 4건
  const byUserA = await api.functional.communicationReview.notifications.patch(connection, {
    body: {
      user_id: userA,
    },
  });
  typia.assert(byUserA);
  TestValidator.equals("userA notifications count")(4)(byUserA.data.length);
  byUserA.data.forEach((n) => TestValidator.equals("user id matches")(userA)(n.user_id));

  // userB도 개별 검증(1건)
  const byUserB = await api.functional.communicationReview.notifications.patch(connection, {
    body: {
      user_id: userB,
    },
  });
  typia.assert(byUserB);
  TestValidator.equals("userB notifications count")(1)(byUserB.data.length);
  byUserB.data.forEach((n) => TestValidator.equals("user id matches")(userB)(n.user_id));

  // 4. notification_type별 목록(message)
  const messageNotifs = await api.functional.communicationReview.notifications.patch(connection, {
    body: {
      notification_type: "message",
    },
  });
  typia.assert(messageNotifs);
  messageNotifs.data.forEach((n) => TestValidator.equals("message type")(n.notification_type)("message"));

  // 5. 미읽음(read_at null), 읽음(not null) 조건(수신자A)
  const unreadOfUserA = await api.functional.communicationReview.notifications.patch(connection, {
    body: {
      user_id: userA,
    },
  });
  typia.assert(unreadOfUserA);
