    .filter((n) => n.read_at == null)
    .forEach((n) => TestValidator.equals("not read")(null)(n.read_at));

  // 6. archived=false 필터(수신자A)
  const activeNotifsA = await api.functional.communicationReview.notifications.patch(connection, {
    body: { user_id: userA, archived: false },
  });
  typia.assert(activeNotifsA);
  activeNotifsA.data.forEach((n) => TestValidator.equals("not archived")(false)(n.archived));

  // 7. page, limit 페이징(2건씩 2페이지)
  const paged1 = await api.functional.communicationReview.notifications.patch(connection, {
    body: { user_id: userA, page: 1, limit: 2 },
