  TestValidator.equals("pagination current")(1)(paged1.pagination.current);
  TestValidator.equals("pagination limit")(2)(paged1.pagination.limit);
  paged1.data.forEach((n) => TestValidator.equals("userA paged notif")(userA)(n.user_id));
  const paged2 = await api.functional.communicationReview.notifications.patch(connection, {
    body: { user_id: userA, page: 2, limit: 2 },
  });
  typia.assert(paged2);
  TestValidator.equals("2nd page notifications count")(paged2.data.length + paged1.data.length)(4);

  // 8. page 넘는 값(ex: page=999) 빈리스트 확인
  const pageOut = await api.functional.communicationReview.notifications.patch(connection, {
    body: { user_id: userA, page: 999 },
  });
  typia.assert(pageOut);
  TestValidator.equals("out-of-range page is empty")(0)(pageOut.data.length);

  // 9. pagination 정보/카운트/전체 상태와 data 리스트 일관성
  const fullListA = await api.functional.communicationReview.notifications.patch(connection, {
    body: { user_id: userA },
  });
  typia.assert(fullListA);
  TestValidator.equals("records matches data + other pages")(fullListA.data.length)(fullListA.pagination.records);
}

