 */
export type INotification = {
  /** 고유 식별자 (CommunicationReview.notifications.id). */
  id: string & tags.Format<"uuid">;

  /** 알림 수신자(사용자) ID (CommunicationReview.notifications.user_id). */
  user_id: string & tags.Format<"uuid">;

  /** 관련 메시지 스레드 ID(존재시). CommunicationReview.notifications.thread_id. */
  thread_id?: (string & tags.Format<"uuid">) | null;

  /**
