import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { INotification } from "@ORGANIZATION/PROJECT-api/lib/structures/INotification";

/**
 * 알림 단건 조회 기능의 E2E 테스트.
 *
 * 사용자가 특정 알림 리소스의 uuid로 상세 정보를 조회했을 때 모든 필드가 정확히 반환되는지 확인합니다.
 * 실패 케이스로, 존재하지 않는 id나 잘못된 id를 요청하면 오류를 리턴해야 함을 검증합니다.
 *
 * 테스트 절차:
 * 1. 테스트용 알림을 생성해 조회 대상을 준비한다.
 * 2. 해당 알림의 id(정상 uuid)로 단건 조회: 모든 필드가 정확히 반환되는지 검증한다.
 * 3. 존재하지 않는 uuid로 조회 시 404 오류 발생하는지 검증한다.
 * 4. 형식이 잘못된(비-uuid) id로 조회 시 400 오류 혹은 적절한 에러 반환되는지 검증한다.
 */
export async function test_api_communicationReview_test_get_notification_by_id(
  connection: api.IConnection,
) {
  // 1. 테스트용 알림 생성
  const createInput: INotification.ICreate = {
    user_id: typia.random<string & tags.Format<"uuid">>(),
    notification_type: "system",
    content: `테스트 알림: ${RandomGenerator.alphabets(8)}`,
    thread_id: null,
  };
  const created: INotification = await api.functional.communicationReview.notifications.post(connection, {
    body: createInput,
  });
  typia.assert(created);

  // 2. 정상id로 조회
  const output = await api.functional.communicationReview.notifications.getById(connection, { id: created.id });
  typia.assert(output);
  TestValidator.equals("id一致")(created.id)(output.id);
  TestValidator.equals("user_id一致")(created.user_id)(output.user_id);
  TestValidator.equals("notification_type一致")(created.notification_type)(output.notification_type);
  TestValidator.equals("content一致")(created.content)(output.content);
  // thread_id, sent_at, archived, read_at 필드 존재 및 값 확인
  TestValidator.equals("archived false")(false)(output.archived);
  TestValidator.predicate("sent_at is string/date-time")(typeof output.sent_at === "string");

  // 3. 존재하지 않는 uuid로 조회시 404
  const notFoundId = typia.random<string & tags.Format<"uuid">>();
  TestValidator.error("존재하지 않는 uuid 404 확인")(async () => {
    await api.functional.communicationReview.notifications.getById(connection, { id: notFoundId });
  });

  // 4. 잘못된 형식 id 조회시 400 or error
  TestValidator.error("uuid 포맷 아님")(async () => {
    await api.functional.communicationReview.notifications.getById(connection, { id: "not-a-uuid" as any });
  });
}

