import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { INotification } from "@ORGANIZATION/PROJECT-api/lib/structures/INotification";

/**
 * Test notification creation (valid and invalid cases)
 *
 * This test ensures creation of a new notification via POST /communicationReview/notifications works correctly. First, it tries a valid payload – success and persistence (all key fields as expected) are checked. Then, requests are made omitting required fields (user_id, notification_type, content), expecting business or validation errors. It covers: reference integrity (valid/invalid user/thread), type correctness, and field business rules.
 *
 * Step-by-step:
 * 1. Create notification with valid required values – assert all returned properties.
 * 2. Attempt creation with missing required fields, expecting validation errors for each.
 */
export async function test_api_communicationReview_test_create_notification_with_valid_and_invalid_payload(
  connection: api.IConnection,
) {
  // 1. Create with all valid fields
  const payloadValid: INotification.ICreate = {
    user_id: typia.random<string & tags.Format<"uuid">>(),
    notification_type: "system",
    content: "Test notification content",
    thread_id: typia.random<string & tags.Format<"uuid">>(), // thread_id is optional, but providing for completeness
  };
  const created = await api.functional.communicationReview.notifications.post(connection, { body: payloadValid });
  typia.assert(created);
  TestValidator.equals("user_id")(payloadValid.user_id)(created.user_id);
  TestValidator.equals("notification_type")(payloadValid.notification_type)(created.notification_type);
  TestValidator.equals("content")(payloadValid.content)(created.content);
  if (payloadValid.thread_id) TestValidator.equals("thread_id")(payloadValid.thread_id)(created.thread_id);
  TestValidator.predicate("sent_at format")(!!created.sent_at && typeof created.sent_at === "string");
  TestValidator.equals("archived")(false)(created.archived); // Should default to false upon creation

  // 2. Missing user_id
  await TestValidator.error("missing user_id should fail async")(
    async () => {
      await api.functional.communicationReview.notifications.post(connection, {
        body: {
          // user_id omitted
          notification_type: "system",
          content: "Test w/o user_id",
        } as any, // forcibly omit for error simulation
      });
    }
  );

  // 3. Missing notification_type
  await TestValidator.error("missing notification_type should fail async")(
    async () => {
      await api.functional.communicationReview.notifications.post(connection, {
        body: {
          user_id: typia.random<string & tags.Format<"uuid">>(),
          // notification_type omitted
          content: "Test w/o type",
        } as any,
      });
    }
  );

  // 4. Missing content
  await TestValidator.error("missing content should fail async")(
    async () => {
      await api.functional.communicationReview.notifications.post(connection, {
        body: {
          user_id: typia.random<string & tags.Format<"uuid">>(),
          notification_type: "system",
          // content omitted
        } as any,
      });
    }
  );
}

