import api from "@ORGANIZATION/PROJECT-api";
import type { INotification } from "@ORGANIZATION/PROJECT-api/lib/structures/INotification";

/**
 * Validate update of notification fields by ID and handle failure on non-existent ID.
 *
 * This test covers the update flow for a notification in the CommunicationReview.notifications domain.
 * It first creates a notification to ensure an existing, valid ID is available for update. It then updates selected mutable fields (content, notification_type, archived, read_at) and checks persistence. As a negative scenario, it attempts to update a notification with a random (non-existent) ID and expects a proper error.
 *
 * Steps:
 * 1. Create a notification (dependency setup)
 * 2. Update a notification using a valid, existing ID (success path)
 *    - Change content (string mutation)
 *    - Optionally change archived/read_at if present
 *    - Change notification_type
 *    - Validate all changes persist
 * 3. Attempt to update a notification with a non-existent ID and ensure proper error is raised
 */
export async function test_api_communicationReview_test_update_notification_by_id(
  connection: api.IConnection,
) {
  // 1. Create a notification (dependency)
  const initial: INotification = await api.functional.communicationReview.notifications.post(connection, {
    body: {
      user_id: typia.random<string & tags.Format<"uuid">>(),
      notification_type: "system",
      content: "Original notification content.",
    } satisfies INotification.ICreate,
  });
  typia.assert(initial);

  // 2. Update the notification using its ID
  const updateInput: INotification.IUpdate = {
    content: "Updated notification content.",
    notification_type: "promotion",
    archived: !initial.archived,
    read_at: initial.read_at ?? new Date().toISOString(),
  };
  const updated: INotification = await api.functional.communicationReview.notifications.putById(connection, {
    id: initial.id,
    body: updateInput,
  });
  typia.assert(updated);
  // Validate that changes are persisted
  TestValidator.equals("content")(updateInput.content)(updated.content);
  TestValidator.equals("notification_type")(updateInput.notification_type)(updated.notification_type);
  TestValidator.equals("archived")(updateInput.archived)(updated.archived);
  if (updateInput.read_at) {
    TestValidator.equals("read_at")(updateInput.read_at)(updated.read_at);
  }

  // 3. Try to update a non-existent notification (should throw error)
  const randomId: string & tags.Format<"uuid"> = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("update non-existent notification should fail")(async () => {
    await api.functional.communicationReview.notifications.putById(connection, {
      id: randomId,
      body: updateInput,
    });
  });
}

