import { tags } from "typia";

/**
 * 단일 알림 엔티티. CommunicationReview.notifications 테이블의 구조와 완전히 일치합니다.
 *
 * 수신자, 스레드 연결, 알림 유형/본문, 읽음/전송 시간, 보관 상태를 모두 기록합니다. 증거성, 실시간커뮤니케이션, 개인정보보호 요구를
 * 만족합니다.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type INotification = {
  /** 고유 식별자 (CommunicationReview.notifications.id). */
  id: string & tags.Format<"uuid">;

  /** 알림 수신자(사용자) ID (CommunicationReview.notifications.user_id). */
  user_id: string & tags.Format<"uuid">;

  /** 관련 메시지 스레드 ID(존재시). CommunicationReview.notifications.thread_id. */
  thread_id?: (string & tags.Format<"uuid">) | null;

  /**
   * 알림 유형(시스템, 메시지, 프로모션 등).
   * CommunicationReview.notifications.notification_type.
   */
  notification_type: string;

  /** 알림 본문. CommunicationReview.notifications.content. */
  content: string;

  /** 알림 발송 시각. CommunicationReview.notifications.sent_at. */
  sent_at: string & tags.Format<"date-time">;

  /** 알림 읽음 시각, 읽지 않았으면 null. CommunicationReview.notifications.read_at. */
  read_at?: (string & tags.Format<"date-time">) | null;

  /** 아카이브/삭제 플래그(기록 보존용). CommunicationReview.notifications.archived. */
  archived: boolean;
};
export namespace INotification {
  /** 알림 생성시 필수 입력 데이터. CommunicationReview.notifications 엔티티와 1:1 매핑. */
  export type ICreate = {
    /** 알림 수신자 ID. 반드시 명시. CommunicationReview.notifications.user_id. */
    user_id: string & tags.Format<"uuid">;

    /**
     * 알림 종류(시스템/이벤트/메시지/프로모션 등).
     * CommunicationReview.notifications.notification_type.
     */
    notification_type: string;

    /** 알림 본문 또는 요약 컨텐츠. CommunicationReview.notifications.content. */
    content: string;

    /** 관련 메시지 스레드 ID (있으면). CommunicationReview.notifications.thread_id. */
    thread_id?: (string & tags.Format<"uuid">) | null;
  };
}

