import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { INotification } from "@ORGANIZATION/PROJECT-api/lib/structures/INotification";

/**
 * 알림을 ID로 보관(soft-delete, 논리삭제)하고, 주 쿼리에서는 제외되지만 감사(Audit) 용도로는 조회가 가능한지 검증합니다. 정상적인 ID와 존재하지 않는 ID(무효 ID) 모두에 대해 실행을 시도합니다.
 * 
 * 1. 새로운 알림(Notification) 데이터를 생성한다 (테스트에 사용될 알림 엔티티 확보)
 * 2. 정상적으로 생성된 알림의 id로 soft delete(archive)를 요청한다
 * 3. 응답받은 알림 객체의 archived 필드가 true인지 검증한다(실제 soft-delete/archiving 수행 여부 판단)
 * 4. 이미 삭제된 알림에 삭제 요청 시도시에도 idempotent 구조임을 확인(재삭제 오류 혹은 404 등 예상)
 * 5. 존재하지 않는 무효 ID로 삭제 시도시 적절한 오류(404 NotFound) 반환되는지 검증
 */
export async function test_api_communicationReview_notifications_eraseById(
  connection: api.IConnection,
) {
  // 1. 알림 엔티티 생성
  const user_id = typia.random<string & tags.Format<"uuid">>();
  const notification = await api.functional.communicationReview.notifications.post(connection, {
    body: {
      user_id,
      notification_type: "system",
      content: "E2E 테스트용 알림 입니다.",
      thread_id: null,
    } satisfies INotification.ICreate,
  });
  typia.assert(notification);

  // 2. 정상적인 ID로 soft delete 수행
  const archived = await api.functional.communicationReview.notifications.eraseById(connection, {
    id: notification.id,
  });
  typia.assert(archived);
  TestValidator.predicate("아카이브 플래그 true 확인")(archived.archived === true);

  // 3. 동일한 ID 재삭제 시도하거나 이미 삭제된 알림 잘못 삭제시도 시도, idempotent(동일 동작 보장) 혹은 404 NotFound 보장
  await TestValidator.error("이미 삭제된 알림 재삭제")(() =>
    api.functional.communicationReview.notifications.eraseById(connection, {
      id: notification.id,
    })
  );

  // 4. 존재하지 않는 무효 ID로 삭제 시도
  await TestValidator.error("무효 ID로 삭제 시도시 404 반환 확인")(() =>
    api.functional.communicationReview.notifications.eraseById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
    })
  );
}

