import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { INotification } from "@ORGANIZATION/PROJECT-api/lib/structures/INotification";

/**
 * 알림을 ID로 보관(soft-delete, 논리삭제)하고, 주 쿼리에서는 제외되지만 감사(Audit) 용도로는 조회가 가능한지 검증합니다.
 *
 * 본 테스트에서는 다음과 같은 케이스를 검증합니다:
 *
 * 1. 새로운 알림(Notification) 데이터를 생성해서 테스트에 사용할 엔티티 확보
 * 2. 정상적인 알림 ID로 soft delete(archive) 요청하여 archived 플래그가 true로 변경됐는지 확인
 * 3. 동일한 ID로 재삭제 요청 시 이미 삭제된 상태에서 올바른 예외(에러) 혹은 idempotent(중복 삭제 수용) 구조인지 확인
 * 4. 존재하지 않는 무효(랜덤) ID로 삭제 요청 시 적절한 404 NotFound 에러 반환 여부 검증
 */
export async function test_api_communicationReview_notifications_eraseById(
  connection: api.IConnection,
) {
  // 1. 테스트용 알림 데이터 생성
  const user_id = typia.random<string & tags.Format<"uuid">>();
  const notification = await api.functional.communicationReview.notifications.post(connection, {
    body: {
      user_id,
      notification_type: "system",
      content: "E2E 테스트용 알림 입니다.",
      thread_id: null,
    } satisfies INotification.ICreate,
  });
  typia.assert(notification);

  // 2. 정상 ID로 soft-delete(archive) 요청 → archived: true 확인
  const archived = await api.functional.communicationReview.notifications.eraseById(connection, {
    id: notification.id,
  });
  typia.assert(archived);
  TestValidator.predicate("archive 플래그 true로 변경됨")(archived.archived === true);

  // 3. 동일 알림 재삭제 시도: idempotent(동작 보장) 또는 404 등 예외 반환 확인
  await TestValidator.error("이미 삭제된 알림 재삭제는 에러")(() =>
    api.functional.communicationReview.notifications.eraseById(connection, {
      id: notification.id,
    })
  );

  // 4. 무효(존재하지 않는) ID로 삭제 시도: 404 NotFound 등 적합한 에러 반환 여부 검증
  await TestValidator.error("존재하지 않는 무효 ID 삭제시 404 등 에러 반환")(() =>
    api.functional.communicationReview.notifications.eraseById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
    })
  );
}

