import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IReview } from "@ORGANIZATION/PROJECT-api/lib/structures/IReview";
import type { IPageIReview } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIReview";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * /communicationReview/reviews 목록/검색(필터 및 페이징 전체 동작 검증)
 *
 * 다양한 리뷰 조건 필터, 페이징, 빈 검색 등 리뷰 관리/검색 Feature의 완전성 검증
 *
 * 1. 사전 테스트데이터용 리뷰 2건 생성(작성자/상품/언어/구매여부 조합 다르게)
 * 2. 전체 검색(제한 조건 없이) → 생성 2레코드 반환/카운트 확인
 * 3. 주요 필터(user_id, product_id, language_code, verified_purchase, archived)별 각각 개별조건 검색
 * 4. 페이징 조건(limit=1, page=2): 2건 → 2페이지 구성/각 slice 정확성
 * 5. 존재하지 않는 조건(랜덤 user_id, 미래 created_after 등): 빈 검색·pagination 확인
 * 6. 반환 object 구조/타입/pagination 상세 검증
 */
export async function test_api_communicationReview_test_list_and_filter_reviews(
  connection: api.IConnection,
) {
  // ------ 1. 사전 리뷰 데이터 2건 등록 ------
  // 서로 다른 user, product, 언어, 구매여부 조합
  const user_ids = [typia.random<string & tags.Format<"uuid">>(), typia.random<string & tags.Format<"uuid">>()];
  const product_ids = [typia.random<string & tags.Format<"uuid">>(), typia.random<string & tags.Format<"uuid">>()];
  const language_codes = ["ko", "en"];
  const verifieds = [true, false];
  const basePayloads = [
    {
      user_id: user_ids[0],
      product_id: product_ids[0],
      content: "첫 번째 리뷰 본문입니다.",
      language_code: language_codes[0],
      verified_purchase: verifieds[0],
    },
    {
      user_id: user_ids[1],
      product_id: product_ids[1],
      content: "Second review body for filtering.",
      language_code: language_codes[1],
      verified_purchase: verifieds[1],
    },
  ];
  const reviews = [] as IReview[];
  for (const body of basePayloads) {
    const created = await api.functional.communicationReview.reviews.post(connection, { body });
    typia.assert(created);
    reviews.push(created);
  }

  // ------ 2. 전체 조회 ------
  const resAll = await api.functional.communicationReview.reviews.patch(connection, { body: {} });
  typia.assert(resAll);
  TestValidator.equals("총 리뷰 건수")(2)(resAll.pagination.records);
  TestValidator.equals("리뷰 레코드 개수")(2)(resAll.data.length);

  // ------ 3. 필터 조합별 단일조건 검색 ------
  for (const [idx, review] of reviews.entries()) {
    // user_id 필터
    const byUser = await api.functional.communicationReview.reviews.patch(connection, { body: { user_id: review.user_id } });
    typia.assert(byUser);
    TestValidator.equals(`user_id로 필터된 결과(${idx})`)(1)(byUser.data.length);
    TestValidator.equals("user_id 매칭")(review.user_id)(byUser.data[0].user_id);

    // product_id 필터
    const byProduct = await api.functional.communicationReview.reviews.patch(connection, { body: { product_id: review.product_id } });
    typia.assert(byProduct);
    TestValidator.equals(`product_id로 필터된 결과(${idx})`)(1)(byProduct.data.length);
    TestValidator.equals("product_id 매칭")(review.product_id)(byProduct.data[0].product_id);

    // language_code 필터
    const byLang = await api.functional.communicationReview.reviews.patch(connection, { body: { language_code: review.language_code } });
    typia.assert(byLang);
    TestValidator.equals(`language_code로 필터된 결과`)(1)(byLang.data.length);
    TestValidator.equals("language_code 매칭")(review.language_code)(byLang.data[0].language_code);

    // verified_purchase 필터
    const byVerified = await api.functional.communicationReview.reviews.patch(connection, { body: { verified_purchase: review.verified_purchase } });
    typia.assert(byVerified);
    TestValidator.predicate("verified_purchase 매칭")(
      byVerified.data.some((r) => r.verified_purchase === review.verified_purchase),
    );
  }

  // archived 필터(생성 리뷰는 archived: false 이므로)
  const byArchived = await api.functional.communicationReview.reviews.patch(connection, { body: { archived: false } });
  typia.assert(byArchived);
  TestValidator.equals("archived: false 필터")(2)(byArchived.data.length);
  TestValidator.predicate("archived 값 검증")(
    byArchived.data.every((r) => r.archived === false),
  );

  // ------ 4. 페이징 테스트(limit/page) ------
  // limit = 1, page 1
  const page1 = await api.functional.communicationReview.reviews.patch(connection, { body: { limit: 1, page: 1 } });
  typia.assert(page1);
  TestValidator.equals("page1 - 리뷰 개수")(1)(page1.data.length);
  TestValidator.equals("pagination.limit")(1)(page1.pagination.limit);
  TestValidator.equals("pagination.current")(1)(page1.pagination.current);
  TestValidator.equals("pagination.pages")(2)(page1.pagination.pages);
  // limit = 1, page 2
  const page2 = await api.functional.communicationReview.reviews.patch(connection, { body: { limit: 1, page: 2 } });
  typia.assert(page2);
  TestValidator.equals("page2 - 리뷰 개수")(1)(page2.data.length);
  TestValidator.equals("pagination.current")(2)(page2.pagination.current);
  // limit=5, page=2(건수보다 큰 페이지): 빈결과
  const bigPage = await api.functional.communicationReview.reviews.patch(connection, { body: { limit: 5, page: 2 } });
  typia.assert(bigPage);
  TestValidator.equals("전체건수" )(2)(bigPage.pagination.records);
  TestValidator.equals("큰 페이지 요청시 데이터 없음")(0)(bigPage.data.length);

  // ------ 5. 잘못된 조건/빈 결과 ------
  // 존재하지 않는 user_id
  const emptyByUser = await api.functional.communicationReview.reviews.patch(connection, { body: { user_id: typia.random<string & tags.Format<"uuid">>() } });
  typia.assert(emptyByUser);
  TestValidator.equals("존재X user_id 필터")(0)(emptyByUser.data.length);
  TestValidator.equals("pagination 카운트 0")(0)(emptyByUser.pagination.records);
  // 미래 시점 이후 created_after -> 0건
  const farFuture = new Date(Date.now() + 365*24*60*60*1000).toISOString();
  const emptyByFuture = await api.functional.communicationReview.reviews.patch(connection, { body: { created_after: farFuture } });
  typia.assert(emptyByFuture);
  TestValidator.equals("미래 created_after 빈검색")(0)(emptyByFuture.data.length);
  TestValidator.equals("pagination 0")(0)(emptyByFuture.pagination.records);

  // ------ 6. object 및 필드/pagination 타입 체크 ------
  // 전체 조회 재확인 + 각 레코드 구조
  const finalAll = await api.functional.communicationReview.reviews.patch(connection, { body: {} });
  typia.assert(finalAll);
  TestValidator.equals("총 리뷰 건수(2회)" )(2)(finalAll.pagination.records);
