import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IReview } from "@ORGANIZATION/PROJECT-api/lib/structures/IReview";

/**
 * 리뷰 단건 조회 API에 대한 엔드 투 엔드 검증
 *
 * 1. 신규 리뷰 엔트리를 선행 생성한다 (POST /communicationReview/reviews).
 * 2. 생성된 id로 GET /communicationReview/reviews/{id}에 요청—정상적으로 review full 데이터 반환됨을 검증한다.
 * 3. 존재하지 않는(랜덤 uuid) id로 요청 시 404 등 오류처리되는지 검증한다.
 * 4. 삭제/보관된(arhived=true) 리뷰 id로 요청 시 허용/실패 케이스를 정밀 검증한다 (삭제처리, 아카이빙 등 정책 따라 변경).   
 */
export async function test_api_communicationReview_reviews_getById(
  connection: api.IConnection,
) {
  // 1. 신규 리뷰 생성 (테스트용)
  const reviewCreate: IReview.ICreate = {
    user_id: typia.random<string & tags.Format<"uuid">>(),
    product_id: typia.random<string & tags.Format<"uuid">>(),
    parent_review_id: null,
    content: "테스트 리뷰 내용 " + RandomGenerator.paragraph()(),
    language_code: "ko",
    verified_purchase: true,
  };
  const created: IReview = await api.functional.communicationReview.reviews.post(connection, { body: reviewCreate });
  typia.assert(created);
  TestValidator.equals("content")(reviewCreate.content)(created.content);
  TestValidator.equals("user_id")(reviewCreate.user_id)(created.user_id);
  TestValidator.equals("product_id")(reviewCreate.product_id)(created.product_id);

  // 2. 생성된 리뷰 id로 조회 성공
  const fetched: IReview = await api.functional.communicationReview.reviews.getById(connection, { id: created.id });
  typia.assert(fetched);
  TestValidator.equals("id")(created.id)(fetched.id);
  TestValidator.equals("archived")(false)(fetched.archived);

  // 3. 랜덤 uuid로 조회 (존재X)
  await TestValidator.error("존재하지 않는 id 오류 처리")(
    async () => {
      await api.functional.communicationReview.reviews.getById(connection, { id: typia.random<string & tags.Format<"uuid">>() });
    },
  );

  // 4. 보관(arhived=true) 상태 리뷰의 처리
  // 우선 review 생성 후 직접 archived 값을 true로 변경할 API가 없을 경우—skip, 그렇지 않다면 코드 작성.
  // 예시: 리뷰를 따로 아카이브 처리하는 기능 존재 시 테스트 케이스 추가
  // (본 예제에서는 아카이브 시나리오는 검증하지 않음)
}

