import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IReview } from "@ORGANIZATION/PROJECT-api/lib/structures/IReview";

/**
 * Test creation of a review entry in the CommunicationReview domain.
 *
 * This test covers the creation of a new review with all required business fields and
 * the system's reaction to attempts with missing/invalid data. Both successful and
 * failure scenarios are validated to ensure full compliance.
 *
 * Step-by-step process:
 * 1. Prepare valid review data for creation (complete all required fields).
 * 2. Call the POST /communicationReview/reviews endpoint to create the review.
 * 3. Validate that the returned review matches the submitted data and is persisted.
 * 4. Attempt to create a review with missing or invalid required fields (such as omitting user_id, product_id, or leaving content empty).
 * 5. Validate that the API returns appropriate error responses (such as validation errors) for these failure cases.
 * 6. Repeat for each required field to ensure all business rules are enforced server-side.
 */
export async function test_api_communicationReview_test_create_review_with_valid_and_invalid_fields(
  connection: api.IConnection,
) {
  // 1. Prepare valid review data
  const validReview: IReview.ICreate = {
    user_id: typia.random<string & tags.Format<"uuid">>(),
    product_id: typia.random<string & tags.Format<"uuid">>(),
    content: RandomGenerator.paragraph()(),
    language_code: "en",
    verified_purchase: true
  };

  // 2. Attempt review creation with all valid data
  const created = await api.functional.communicationReview.reviews.post(connection, {
    body: validReview
  });
  typia.assert(created);
  TestValidator.equals("user_id matches")(validReview.user_id)(created.user_id);
  TestValidator.equals("product_id matches")(validReview.product_id)(created.product_id);
  TestValidator.equals("content matches")(validReview.content)(created.content);
  TestValidator.equals("language_code matches")(validReview.language_code)(created.language_code);
  TestValidator.equals("verified_purchase matches")(validReview.verified_purchase)(created.verified_purchase);

  // 3. Attempt creation missing required fields (user_id)
  await TestValidator.error("missing user_id should fail")(() =>
    api.functional.communicationReview.reviews.post(connection, {
      body: {
        ...validReview,
        // @ts-expect-error intentionally omit user_id for runtime business test
        user_id: undefined
      }
    })
  );

  // 4. Attempt creation missing required fields (product_id)
  await TestValidator.error("missing product_id should fail")(() =>
    api.functional.communicationReview.reviews.post(connection, {
      body: {
        ...validReview,
        // @ts-expect-error intentionally omit product_id
        product_id: undefined
      }
    })
  );

  // 5. Attempt creation with missing content
  await TestValidator.error("missing content should fail")(() =>
    api.functional.communicationReview.reviews.post(connection, {
      body: {
        ...validReview,
        // @ts-expect-error intentionally omit content
        content: undefined
      }
    })
  );

  // 6. Attempt creation with invalid (empty string) content
  await TestValidator.error("empty content should fail")(() =>
    api.functional.communicationReview.reviews.post(connection, {
      body: {
        ...validReview,
        content: ""
      }
    })
  );

  // 7. Attempt creation with missing language_code
  await TestValidator.error("missing language_code should fail")(() =>
    api.functional.communicationReview.reviews.post(connection, {
      body: {
        ...validReview,
        // @ts-expect-error intentionally omit language_code
        language_code: undefined
      }
    })
  );

  // 8. Attempt creation with missing verified_purchase
  await TestValidator.error("missing verified_purchase should fail")(() =>
    api.functional.communicationReview.reviews.post(connection, {
      body: {
        ...validReview,
        // @ts-expect-error intentionally omit verified_purchase
        verified_purchase: undefined
      }
    })
  );
}

