import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IReview } from "@ORGANIZATION/PROJECT-api/lib/structures/IReview";

/**
 * E2E test for updating an existing review by ID in the CommunicationReview domain.
 *
 * This test covers both successful and failure scenarios:
 * - Happy path: Modifies selected fields of a review and validates the changes persist.
 * - Error: Attempts to update non-existent or soft deleted (archived) reviews and expects failures.
 *
 * Test Steps:
 * 1. Create a valid review (dependency).
 * 2. Update mutable fields (e.g., content, language_code, verified_purchase) using its id.
 * 3. Retrieve review and validate updated fields match.
 * 4. Try updating with a non-existent (random) ID, expect error.
 * 5. Soft-delete (archive) the review, then try updating it again, expect error.
 */
export async function test_api_communicationReview_test_update_review_by_id(
  connection: api.IConnection,
) {
  // 1. Create a review for update testing
  const newReview = await api.functional.communicationReview.reviews.post(connection, {
    body: {
      user_id: typia.random<string & tags.Format<"uuid">>(),
      product_id: typia.random<string & tags.Format<"uuid">>(),
      content: RandomGenerator.paragraph()(),
      language_code: "en",
      verified_purchase: true,
    } satisfies IReview.ICreate,
  });
  typia.assert(newReview);

  // 2. Update fields of the existing review
  const updateInput = {
    content: RandomGenerator.paragraph()(),
    language_code: "fr",
    verified_purchase: false,
  } satisfies IReview.IUpdate;
  const updated = await api.functional.communicationReview.reviews.putById(connection, {
    id: newReview.id,
    body: updateInput,
  });
  typia.assert(updated);
  TestValidator.equals("content updated")(updateInput.content)(updated.content);
  TestValidator.equals("language code updated")(updateInput.language_code)(updated.language_code);
  TestValidator.equals("verified_purchase updated")(updateInput.verified_purchase)(updated.verified_purchase);

  // 3. Error: update non-existent ID
  await TestValidator.error("update non-existent review should fail")(
    async () =>
      api.functional.communicationReview.reviews.putById(connection, {
        id: typia.random<string & tags.Format<"uuid">>(),
        body: updateInput,
      })
  );

  // 4. Archive (soft-delete) the review
  const archived = await api.functional.communicationReview.reviews.putById(connection, {
    id: newReview.id,
    body: { archived: true } satisfies IReview.IUpdate,
  });
  typia.assert(archived);
  TestValidator.equals("archived flag")(true)(archived.archived);

  // 5. Error: update after archiving
  await TestValidator.error("update archived review should fail")(
    async () =>
      api.functional.communicationReview.reviews.putById(connection, {
        id: newReview.id,
        body: updateInput,
      })
  );
}

