  product_id: string & tags.Format<"uuid">;

  /** 상위 리뷰(댓글) 연결. CommunicationReview.reviews.parent_review_id. */
  parent_review_id?: (string & tags.Format<"uuid">) | null;

  /** 리뷰 본문(텍스트/다국어 포함). CommunicationReview.reviews.content. */
  content: string;

  /** 언어코드(로케일) - a11y, 증거보강, 시스템 지원용. */
  language_code: string;

  /** 작성 시각. */
  created_at: string & tags.Format<"date-time">;

  /** 수정 마지막 시각. */
  updated_at: string & tags.Format<"date-time">;

  /** 실구매 여부(사실 인증용). */
  verified_purchase: boolean;

  /** 삭제/보관(검증 및 감사용). */
  archived: boolean;
};
export namespace IReview {
  /**
