   * as required by the reviews table in the Prisma schema. Fully supports
   * evidence trace, multilingual and auditability requirements as specified
   * in requirements analysis.
   */
  export type ICreate = {
    /**
     * The unique identifier of the user creating the review.
     *
     * Referenced from users.id in the Prisma schema. Required for user
     * association and audit compliance.
     */
    user_id: string & tags.Format<"uuid">;

    /**
     * The unique identifier of the product being reviewed.
     *
     * Referenced from products.id in the Prisma schema. Ensures the review
     * is correctly associated with a product.
     */
    product_id: string & tags.Format<"uuid">;

    /**
     * Optional. The unique identifier of the parent review if this is a
     * reply or nested review.
     *
     * Referenced from reviews.id in the Prisma schema.
     */
    parent_review_id?: (string & tags.Format<"uuid">) | null;

    /**
     * The body/content of the review. Must be provided by the end user.
     *
     * Directly maps to reviews.content in the Prisma schema. Supports
     * evidence compliance and audit trails.
     */
    content: string;

    /**
     * The code of the language the review is written in (BCP 47 or ISO
     * code, e.g., 'ko', 'en', 'fr').
     *
     * Referenced from reviews.language_code for i18n and multicultural
