/**
 * Tests the archive (soft-delete) functionality of a review by its ID.
 *
 * Business context:
 * - Ensures that when a review is archived, it disappears from standard lists while being preserved for audit/evidence.
 *   This is a legal, regulatory requirement for evidentiary trails (tamper-proof logic, a11y, compliance etc).
 *
 * Steps performed by this test:
 * 1. Create a new review (to have a valid id for deletion).
 * 2. Archive (DELETE/soft-delete) the review by ID.
 * 3. Check the returned review object has 'archived: true' and correct id.
 * 4. (Optionally) Attempt to retrieve (list/query) unarchived reviews and confirm this review is not present (not implemented unless endpoint is available).
 * 5. Attempt to archive the same review again (expect error response since already archived, or confirm idempotent/no-change behavior as API defines).
 * 6. Attempt to archive a completely invalid/non-existent review id (expect error response).
 *
 * This covers both the happy path and error paths (nonexistent review, double-deletion).
 */
export async function test_api_communicationReview_reviews_eraseById(
  connection: api.IConnection,
) {
  // 1. Create a new review (via dependency)
  const newReview: IReview = await api.functional.communicationReview.reviews.post(connection, {
    body: {
      user_id: typia.random<string & tags.Format<"uuid">>(),
      product_id: typia.random<string & tags.Format<"uuid">>(),
      content: RandomGenerator.paragraph()(),
      language_code: "en",
      verified_purchase: true
    } satisfies IReview.ICreate
  });
  typia.assert(newReview);

  // 2. Archive (soft-delete) the review by id
  const archived: IReview = await api.functional.communicationReview.reviews.eraseById(connection, {
    id: newReview.id
  });
  typia.assert(archived);
  TestValidator.equals("archived.id")(archived.id)(newReview.id);
  TestValidator.predicate("archived flag set")(archived.archived === true);

  // 3. Try to archive again (expect error or correct behavior)
  await TestValidator.error("double-archive error or idempotent")(() =>
    api.functional.communicationReview.reviews.eraseById(connection, {
      id: newReview.id
    })
  );

  // 4. Try an invalid/nonexistent id
  await TestValidator.error("nonexistent review id should fail")(() =>
    api.functional.communicationReview.reviews.eraseById(connection, {
      id: typia.random<string & tags.Format<"uuid">>()
    })
  );
}

