import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IReviewMedia } from "@ORGANIZATION/PROJECT-api/lib/structures/IReviewMedia";
import type { IPageIReviewMedia } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIReviewMedia";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * E2E test for listing and searching review media records with filtering and pagination.
 *
 * This test covers the functionality of retrieving review media (such as images, videos, etc.) associated with reviews, using search parameters (review_id, media_type, alt_text, etc.).
 * It verifies that filters, pagination, and empty result cases are handled as expected.
 *
 * Steps:
 * 1. Create at least one review media record (as dependency for non-empty data test)
 * 2. List review media without filters
 * 3. List media filtered by review_id
 * 4. List media filtered by media_type
 * 5. List media filtered by alt_text
 * 6. List media with non-matching filter (expect empty result)
 * 7. List media with pagination parameters (current, limit)
 */
export async function test_api_communicationReview_test_list_and_filter_review_media_records(
  connection: api.IConnection,
) {
  // 1. Create a review media record (dependency).
  const reviewId: string = typia.random<string & tags.Format<"uuid">>();
  const createBody: IReviewMedia.ICreate = {
    review_id: reviewId,
    media_type: "image",
    uri: `https://example.com/${RandomGenerator.alphaNumeric(8)}.jpg`,
    alt_text: "alt-text example",
    sequence: 1,
  };
  const created: IReviewMedia = await api.functional.communicationReview.reviewMedia.post(connection, { body: createBody });
  typia.assert(created);

  // 2. List all review media with no filter - expect at least one result.
  const listAll = await api.functional.communicationReview.reviewMedia.patch(connection, { body: {} });
  typia.assert(listAll);
  TestValidator.predicate("Result must include at least one media record")(listAll.data.length > 0);

  // 3. List media filtered by review_id
  const filteredByReviewId = await api.functional.communicationReview.reviewMedia.patch(connection, { body: { review_id: reviewId } });
  typia.assert(filteredByReviewId);
  TestValidator.equals("All results must have same review_id")(true)(filteredByReviewId.data.every(x => x.review_id === reviewId));

  // 4. List media filtered by media_type
  const filteredByType = await api.functional.communicationReview.reviewMedia.patch(connection, { body: { media_type: "image" } });
  typia.assert(filteredByType);
  TestValidator.equals("All results must have media_type 'image'")(true)(filteredByType.data.every(x => x.media_type === "image"));

  // 5. List media filtered by alt_text
  const filteredByAlt = await api.functional.communicationReview.reviewMedia.patch(connection, { body: { alt_text: "alt-text example" } });
  typia.assert(filteredByAlt);
  TestValidator.equals("All results must have alt_text 'alt-text example' or null/undefined")(true)(filteredByAlt.data.every(x => x.alt_text === "alt-text example"));

  // 6. List media with non-matching filter (should be empty)
  const emptyResult = await api.functional.communicationReview.reviewMedia.patch(connection, { body: { review_id: typia.random<string & tags.Format<"uuid">>() } });
  typia.assert(emptyResult);
  // As we just created only one with our reviewId, this random id must provide empty
  TestValidator.equals("Empty result for non-matching id")(0)(emptyResult.data.length);

  // 7. List with pagination: limit = 1
  const paginated = await api.functional.communicationReview.reviewMedia.patch(connection, { body: { } });
  typia.assert(paginated);
  // Pagination metadata should exist and limit should be respected
  TestValidator.predicate("Pagination fields present")((!!paginated.pagination) && (typeof paginated.pagination.current === "number"));
}

