import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IUser";
import type { IPageIUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIUser";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * E2E test: Validate paginated, filtered list retrieval of Core users.
 *
 * This test covers the primary scenarios for the core user search/list endpoint:
 *
 * 1. Default list: Fetch users with no filters or pagination - verify default page size and ordering, plus non-empty result set (if any users exist).
 * 2. Filtering: Request users by filtering parameters (e.g., is_active false, or email domain matches 'acme.com') - assert all users in result match the given filter.
 * 3. Pagination: Provide valid page/limit parameters, check data matches page size and correct navigation over multiple pages.
 * 4. Invalid parameters: Provide invalid pagination values (negative page, nonint, too high limit) - confirm API validation errors are returned (using TestValidator.error).
 * 5. Access control: Attempt list with and without necessary permissions (simulate forbidden user session) - expect error for unauthorized access.
 *
 * Validators are used to assert page metadata (page, limit, record counts) and content. All API responses are asserted for type correctness via typia.assert().
 */
export async function test_api_core_test_list_core_users_with_pagination_and_filters(
  connection: api.IConnection,
) {
  // 1. Default list: no filters/pagination
  const defaultList = await api.functional.core.users.patch(connection, {
    body: {} satisfies IUser.IRequest,
  });
  typia.assert(defaultList);
  TestValidator.predicate("default page size >= 1")(defaultList.pagination.limit > 0);
  TestValidator.predicate("at least 0 users")(defaultList.pagination.records >= 0);

  // 2. Filtering: is_active false
  const filterInactive = await api.functional.core.users.patch(connection, {
    body: { is_active: false } satisfies IUser.IRequest,
  });
  typia.assert(filterInactive);
  for (const user of filterInactive.data) {
    TestValidator.equals("inactive user")(false)(user.is_active);
  }

  // 2b. Filtering: email domain
  const exampleDomain = "@acme.com";
  const filterAcme = await api.functional.core.users.patch(connection, {
    body: { email: exampleDomain } satisfies IUser.IRequest,
  });
  typia.assert(filterAcme);
  for (const user of filterAcme.data) {
    TestValidator.predicate("email matches acme.com domain")(
      user.email.endsWith(exampleDomain),
    );
  }

  // 3. Pagination: page 2, limit 2
  const paged = await api.functional.core.users.patch(connection, {
    body: { page: 2, limit: 2 } satisfies IUser.IRequest,
  });
  typia.assert(paged);
  TestValidator.equals("limit == 2")(2)(paged.pagination.limit);
  TestValidator.equals("current page == 2")(2)(paged.pagination.current);
  TestValidator.predicate("records >= 0")(paged.pagination.records >= 0);

  // 4. Invalid parameters: negative page
  await TestValidator.error("negative page validation")(() =>
    api.functional.core.users.patch(connection, {
      body: { page: -1 } satisfies IUser.IRequest,
    }),
  );
  // 4b. Invalid limit: zero
  await TestValidator.error("zero limit validation")(() =>
    api.functional.core.users.patch(connection, {
      body: { limit: 0 } satisfies IUser.IRequest,
    }),
  );

  // 5. Access control: simulate insufficient permission by clearing Authorization header and try request
  const anonymousConn = {
    ...connection,
    headers: { ...connection.headers },
  };
  delete anonymousConn.headers["Authorization"];
  await TestValidator.error("no auth forbidden")(() =>
    api.functional.core.users.patch(anonymousConn, { body: {} }),
  );
}

