import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IUser";

/**
 * Validate various user creation flows for Core.users endpoint
 *
 * This function verifies both the successful creation of a user and the enforcement of validation/business rules by the API when faced with missing, duplicate, or invalid input values. It thoroughly tests API-side field validation and uniqueness constraints to ensure correct behavior and error signaling.
 *
 * 1. Successfully create a new user providing all required fields with valid data; verify returned record contains correct properties and audit timestamps.
 * 2. Attempt to create a user omitting required fields (e.g., missing email, missing password), and confirm a validation error is returned.
 * 3. Try creating a second user with an email address that already exists—verify that a uniqueness constraint error is triggered.
 * 4. Attempt to create a user with an invalid email format to confirm input validation errors are handled appropriately.
 */
export async function test_api_core_test_create_core_user_success_and_validation_cases(
  connection: api.IConnection,
) {
  // 1. Successfully create a new user
  const userCreateInput = {
    organization_id: typia.random<string & tags.Format<"uuid">>(),
    role_id: typia.random<string & tags.Format<"uuid">>(),
    username: RandomGenerator.alphaNumeric(8),
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12),
    phone: RandomGenerator.mobile(),
  } satisfies IUser.ICreate;

  const createdUser = await api.functional.core.users.post(connection, {
    body: userCreateInput,
  });
  typia.assert(createdUser);
  TestValidator.equals("username")(userCreateInput.username)(createdUser.username);
  TestValidator.equals("email")(userCreateInput.email)(createdUser.email);
  TestValidator.equals("role_id")(userCreateInput.role_id)(createdUser.role_id);
  TestValidator.equals("organization_id")(userCreateInput.organization_id)(createdUser.organization_id);
  TestValidator.predicate("created_at exists")(
    typeof createdUser.created_at === "string" && !!createdUser.created_at,
  );
  TestValidator.predicate("updated_at exists")(
    typeof createdUser.updated_at === "string" && !!createdUser.updated_at,
  );

  // 2. Attempt creating a user with missing required fields (missing email)
  await TestValidator.error("missing email yields validation error")(async () => {
    await api.functional.core.users.post(connection, {
      body: {
        organization_id: typia.random<string & tags.Format<"uuid">>(),
        role_id: typia.random<string & tags.Format<"uuid">>(),
        username: RandomGenerator.alphaNumeric(8),
        // missing email
        password: RandomGenerator.alphaNumeric(12),
        phone: RandomGenerator.mobile(),
      } as any, // required for runtime validation scenario, do not use as any unless forced for test
    });
  });

  // 2-2. Attempt creating a user with missing password field
  await TestValidator.error("missing password yields validation error")(async () => {
    await api.functional.core.users.post(connection, {
      body: {
        organization_id: typia.random<string & tags.Format<"uuid">>(),
        role_id: typia.random<string & tags.Format<"uuid">>(),
        username: RandomGenerator.alphaNumeric(8),
        email: typia.random<string & tags.Format<"email">>(),
        phone: RandomGenerator.mobile(),
        // missing password
      } as any,
    });
  });

  // 3. Try to create a user with a duplicate email
  await TestValidator.error("duplicate email should fail")(async () => {
    await api.functional.core.users.post(connection, {
      body: {
        ...userCreateInput,
        username: RandomGenerator.alphaNumeric(8),
      },
    });
  });

  // 4. Attempt creating a user with invalid email format
  await TestValidator.error("invalid email format yields validation error")(async () => {
    await api.functional.core.users.post(connection, {
      body: {
        organization_id: typia.random<string & tags.Format<"uuid">>(),
        role_id: typia.random<string & tags.Format<"uuid">>(),
        username: RandomGenerator.alphaNumeric(8),
        email: "not-an-email", // malformed
        password: RandomGenerator.alphaNumeric(12),
        phone: RandomGenerator.mobile(),
      } as any,
    });
  });
}

