import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IUser";

/**
 * 테스트 목적: 사용자 정보 업데이트 엔드포인트의 성공/실패 시나리오를 모두 검증합니다.
 *
 * 1. 기본 시나리오: 사용자를 생성한 뒤, display name(여기서 username)과 활성 상태(is_active) 등 가변 필드를 변경 요청합니다. 정상적으로 변경 반영됨을 확인하고, 응답 본문과 DB 실제 값이 일치함을 검증합니다.
 *
 * 2. 입력값 누락/불량: 필수 필드(예: username 또는 role_id 등)를 일부러 빠트린 body로 업데이트 요청 시 validation 에러(400)를 발생시켜야 함을 확인합니다.
 *
 * 3. 존재하지 않는 사용자: 무작위 UUID로 putById 호출 시 404 응답을 반환하는지 확인합니다.
 *
 * 4. 불변 필드: id, created_at 등 불변 필드를 update body에 포함시켜도 실제 DB에 변경 반영되지 않거나, 에러가 나는지 확인합니다.
 */
export async function test_api_core_test_update_core_user_success_and_error_cases(
  connection: api.IConnection,
) {
  // 1. 사용자 생성
  const newUser = await api.functional.core.users.post(connection, {
    body: {
      role_id: typia.random<string & tags.Format<'uuid'>>(),
      organization_id: typia.random<string & tags.Format<'uuid'>>(),
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<'email'>>(),
      phone: RandomGenerator.mobile(),
      password: 'TestPassword123!'
    },
  });
  typia.assert(newUser);

  // 2. 정상 업데이트: display name(username)과 is_active 변경
  const updated = await api.functional.core.users.putById(connection, {
    id: newUser.id,
    body: {
      username: RandomGenerator.alphaNumeric(10),
      is_active: !newUser.is_active,
    },
  });
  typia.assert(updated);
  TestValidator.equals('id')(newUser.id)(updated.id);
  TestValidator.equals('username')(updated.username)();
  TestValidator.equals('is_active')(updated.is_active)();

  // 3. 필수 필드 누락 테스트 (role_id 생략)
  await TestValidator.error('필수 값 없는 업데이트 실패')(() =>
    api.functional.core.users.putById(connection, {
      id: newUser.id,
      body: {
        username: RandomGenerator.alphaNumeric(10),
      },
    }),
  );

  // 4. 존재하지 않는 사용자 업데이트
  await TestValidator.error('없는 사용자 업데이트 실패')(() =>
    api.functional.core.users.putById(connection, {
      id: typia.random<string & tags.Format<'uuid'>>(),
      body: {
        username: RandomGenerator.alphaNumeric(8),
      },
    }),
  );

  // 5. 불변 필드(immutable) 값 변경 시도
  const tryImmutable = await api.functional.core.users.putById(connection, {
    id: newUser.id,
    body: {
      id: typia.random<string & tags.Format<'uuid'>>(), // 실제로 반영되어선 안 됨
      created_at: new Date(0).toISOString() as string & tags.Format<'date-time'>, // 실제로 반영 안 됨
      username: RandomGenerator.alphaNumeric(10),
    } as any,
  });
  typia.assert(tryImmutable);
  TestValidator.equals('id unchanged')(tryImmutable.id)(newUser.id);
  TestValidator.notEquals('created_at 변경 불가')(tryImmutable.created_at)(new Date(0).toISOString());
}

