import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IUser";

/**
 * 사용자 정보 업데이트 엔드포인트의 성공/오류 케이스 종합 검증
 *
 * - 기존 사용자를 생성 후 display name(username) 및 활성화 상태(is_active) 등 가변 필드 정상 업데이트 및 반영여부 검증
 * - 필수 필드 누락 시(예: role_id) validation 에러(400)가 발생함을 확인
 * - 존재하지 않는 UUID의 사용자에 대해 404 반환 여부 확인
 * - id/created_at 등 불변 필드가 변경 body에 전달되어도 시스템에서 실제로 반영되지 않음을 검증
 *
 * 테스트 플로우
 * 1. 신규 사용자 생성 (post)
 * 2. 정상 업데이트 with username/is_active 변경
 * 3. 필수 필드(role_id) 누락 업데이트 - 입력 validation 에러 확인
 * 4. 존재하지 않는 id로 업데이트 - 404 에러 확인
 * 5. 불변 필드(body에 id/created_at 전달)도 값이 실제로 바뀌지 않음을 검증
 */
export async function test_api_core_test_update_core_user_success_and_error_cases(
  connection: api.IConnection,
) {
  // 1. 신규 사용자 생성
  const newUser = await api.functional.core.users.post(connection, {
    body: {
      role_id: typia.random<string & tags.Format<'uuid'>>(),
      organization_id: typia.random<string & tags.Format<'uuid'>>(),
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<'email'>>(),
      phone: RandomGenerator.mobile(),
      password: 'TestPassword123!'
    },
  });
  typia.assert(newUser);

  // 2. 정상 업데이트 - username, is_active 변경
  const nextUsername = RandomGenerator.alphaNumeric(10);
  const updated = await api.functional.core.users.putById(connection, {
    id: newUser.id,
    body: {
      username: nextUsername,
      is_active: !newUser.is_active,
    },
  });
  typia.assert(updated);
  TestValidator.equals('id')(newUser.id)(updated.id);
  TestValidator.equals('username')(nextUsername)(updated.username);
  TestValidator.equals('is_active')(!newUser.is_active)(updated.is_active);

  // 3. 필수 필드 누락(role_id) - validation error
  await TestValidator.error('필수 값 없는 업데이트 실패')(() =>
    api.functional.core.users.putById(connection, {
      id: newUser.id,
      body: {
        username: RandomGenerator.alphaNumeric(10),
      },
    }),
  );

  // 4. 존재하지 않는 사용자 업데이트(404)
  await TestValidator.error('없는 사용자 업데이트 실패')(() =>
    api.functional.core.users.putById(connection, {
      id: typia.random<string & tags.Format<'uuid'>>(),
      body: {
        username: RandomGenerator.alphaNumeric(8),
      },
    }),
  );

  // 5. 불변 필드(id, created_at 등) update 시도해도 값이 유지됨 확인
  const mutatedImmutable = await api.functional.core.users.putById(connection, {
    id: newUser.id,
    body: {
      id: typia.random<string & tags.Format<'uuid'>>(), // 무효 처리 예상
      created_at: new Date(0).toISOString() as string & tags.Format<'date-time'>, // 무효 처리 예상
      username: RandomGenerator.alphaNumeric(10),
    } as any, // 실제 IUser.IUpdate 타입에는 없는 속성이지만, 시스템이 무시하는지 검증한다
  });
  typia.assert(mutatedImmutable);
  TestValidator.equals('id unchanged')(newUser.id)(mutatedImmutable.id);
  TestValidator.notEquals('created_at 변경 불가')(mutatedImmutable.created_at)(new Date(0).toISOString());
}

