import { tags } from "typia";

/**
 * User core entity for actor data embedding. Derived from Core.users table.
 * Ensures audit and evidence context for regulatory events.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IUser = {
  id: string & tags.Format<"uuid">;
  organization_id: string & tags.Format<"uuid">;
  role_id: string & tags.Format<"uuid">;
  username: string;
  email: string;
  phone?: string;
  is_active: boolean;
  created_at: string & tags.Format<"date-time">;
  updated_at: string & tags.Format<"date-time">;
  deleted_at?: string & tags.Format<"date-time">;
};
export namespace IUser {
  /**
   * Payload for user registration/onboarding (Core.users). Used in
   * conjunction with administrative and self-service flows. Raw credentials
   * handled by secure backend logic. Auditable for compliance per requirement
   * analysis, references atomic schema columns for full normalization.
   */
  export type ICreate = {
    /**
     * UUID of the organization to which the user will be assigned
     * (Core.users.organization_id). Null for system/default or
     * single-tenant deployments.
     */
    organization_id?: string & tags.Format<"uuid">;

    /**
     * Role UUID for RBAC assignment (Core.users.role_id). Must reference
     * existing role.
     */
    role_id: string & tags.Format<"uuid">;

    /**
     * Unique username to register (Core.users.username). Enforces secure
     * login and normalization policies.
     */
    username: string;

    /**
     * Email to be assigned to user. Must be unique within system
     * (Core.users.email).
     */
    email: string & tags.Format<"email">;

    /** Optional phone to enable MFA or communications (Core.users.phone). */
    phone?: string | null;

    /**
     * Raw user password. Will be securely hashed and stored as
     * Core.users.password_hash by backend logic. Never returned in any
     * response. Ingest-only field.
     */
    password: string;
  };

  /**
   * Confirmation type for user soft deletion. Includes evidence-preserving
   * fields, supporting compliance, audit logging, and right-to-erasure
   * protocols. Returned following DELETE endpoint for users.
   */
  export type ISoftDelete = {
    /** ID of user that was soft-deleted (Core.users.id). */
    id?: string & tags.Format<"uuid">;

    /** Timestamp when the user was marked deleted (Core.users.deleted_at). */
    deleted_at?: string & tags.Format<"date-time">;
  };
}

