import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IUser";

/**
 * E2E test for soft-deleting a user in the Core system, ensuring both proper business logic and failure scenarios are handled.
 *
 * This test exercises the complete deletion workflow for a user:
 * 1. Create a new user in the Core system (User A) with valid properties.
 * 2. As an authorized actor, soft-delete the user via DELETE /core/users/{id}, verifying the user is not physically removed and deleted_at is set.
 * 3. Attempt to soft-delete the same user again (should error, already deleted).
 * 4. Attempt deletion as a user with insufficient permissions (should deny access).
 * 5. Attempt deletion of a non-existent user (should result in 404 error).
 *
 * The test validates soft-deletion evidence (deleted_at), preserves audit compliance, ensures RBAC logic, and validates error handling for edge cases and abuse paths.
 */
export async function test_api_core_test_delete_core_user_soft_delete_and_permissions(connection: api.IConnection) {
  // 1. Create a new user (User A)
  const createUserInput: IUser.ICreate = {
    organization_id: typia.random<string & tags.Format<"uuid">>(),
    role_id: typia.random<string & tags.Format<"uuid">>(),
    username: RandomGenerator.alphaNumeric(8),
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12),
  };
  const user = await api.functional.core.users.post(connection, { body: createUserInput });
  typia.assert(user);
  TestValidator.equals("user initially not deleted")(undefined)(user.deleted_at);

  // 2. Soft-delete the user (success path)
  const deleted = await api.functional.core.users.eraseById(connection, { id: user.id });
  typia.assert(deleted);
  TestValidator.equals("deleted user id")(user.id)(deleted.id);
  TestValidator.predicate("deleted_at is set on soft delete")(typeof deleted.deleted_at === "string" && deleted.deleted_at.length > 0);

  // 3. Try deleting the same user again -- should fail with business error
  await TestValidator.error("cannot delete already soft-deleted user")(() =>
    api.functional.core.users.eraseById(connection, { id: user.id })
  );

  // 4. Try deletion as an unauthorized actor (simulate by creating a new user with non-admin rights)
  const basicUserInput: IUser.ICreate = {
    organization_id: typia.random<string & tags.Format<"uuid">>(),
    role_id: typia.random<string & tags.Format<"uuid">>(),
    username: RandomGenerator.alphaNumeric(8),
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12),
  };
  const basicUser = await api.functional.core.users.post(connection, { body: basicUserInput });
  typia.assert(basicUser);
  // Simulate login with new (unauthorized) user account -- requires switching context; assuming test infra supports this.
  if (typeof api.functional.core.users.login === "function") {
    await api.functional.core.users.login(connection, { email: basicUser.email, password: basicUserInput.password });
  }
  await TestValidator.error("deletion denied for insufficient permissions")(() =>
    api.functional.core.users.eraseById(connection, { id: user.id })
  );

  // 5. Attempt to delete a random non-existent user
  await TestValidator.error("404 on deleting non-existent user")(() =>
    api.functional.core.users.eraseById(connection, { id: typia.random<string & tags.Format<"uuid">>() })
  );
}

