import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IUserProfile } from "@ORGANIZATION/PROJECT-api/lib/structures/IUserProfile";

/**
 * E2E test for retrieving a user profile by valid and invalid ID with permission validation.
 *
 * This test validates the following:
 * - Successful retrieval of a user profile by a valid ID, with all business/audit fields
 * - NotFound (404) error returned for a non-existent profile ID
 * - Permission checks: a user who should not access another profile receives an error
 *
 * Steps:
 * 1. Create a user profile and obtain its UUID
 * 2. Retrieve profile by that ID as the profile owner; check all returned fields
 * 3. Attempt retrieval by a randomly generated, non-existent UUID; expect 404 error
 * 4. (Optional) Attempt to retrieve created profile as another user without admin permissions and verify access denial (error/forbidden)
 */
export async function test_api_core_test_get_core_user_profile_by_id_valid_and_invalid_cases(connection: api.IConnection) {
  // 1. Create the user profile
  const profileCreateInput: IUserProfile.ICreate = {
    user_id: typia.random<string & tags.Format<"uuid">>(),
    locale_id: typia.random<string & tags.Format<"uuid">>(),
    full_name: RandomGenerator.name(),
    avatar_url: RandomGenerator.pick([
      null,
      RandomGenerator.alphaNumeric(20),
      "https://randomuser.me/api/portraits/men/1.jpg",
    ]),
    timezone: "Asia/Seoul",
    bio: RandomGenerator.sample([null, RandomGenerator.paragraph()()])(1)[0],
    a11y_prefs: null,
  };
  const created: IUserProfile = await api.functional.core.userProfiles.post(connection, { body: profileCreateInput });
  typia.assert(created);

  // 2. Retrieve the created profile as owner
  const fetched: IUserProfile = await api.functional.core.userProfiles.getById(connection, { id: created.id });
  typia.assert(fetched);
  // Validate basic fields
  TestValidator.equals("profile.id")(created.id)(fetched.id);
  TestValidator.equals("profile.user_id")(created.user_id)(fetched.user_id);

  // 3. Try to get a non-existent profile by random UUID (should 404)
  await TestValidator.error("not found")(async () => {
    await api.functional.core.userProfiles.getById(connection, { id: typia.random<string & tags.Format<"uuid">>() });
  });

  // 4. (Optional) Check permissions by trying to retrieve as another user (skipped here - depends on implemented permissions and connection context management)
  // If the permission model is enforced, swap to another user context and retry; implementation required as per auth flows
}

