import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IUser";
import type { IUserProfile } from "@ORGANIZATION/PROJECT-api/lib/structures/IUserProfile";

/**
 * Validate creation of user profiles for full metadata, required fields, and uniqueness.
 *
 * This E2E test covers user profile creation in three ways:
 * 1. Normal creation: Creates a user, then creates a profile for that user with all required and optional metadata fields populated (full deep metadata, including localization/a11y/bio/avatar). Verifies that the returned profile reflects all input data as well as system-managed audit fields and is properly linked to the user.
 * 2. Validation error: Attempts to create a profile with missing required fields (e.g. omitting user_id), and confirms the API responds with a validation error.
 * 3. Uniqueness constraint: Attempts to create a second profile for a user who already has one and verifies that the API returns an error indicating a uniqueness constraint or conflict.
 *
 * Steps:
 * 1. Create a user using the users API endpoint (save user_id).
 * 2. Create a profile for this user with all optional/localization/metadata fields populated (using the user_id above).
 * 3. Assert that the returned profile matches the sent and expected fields, and that all fields are properly returned.
 * 4. Attempt another profile creation for the same user_id — expect an error (uniqueness constraint).
 * 5. Attempt creation of a user profile missing required field(s) (e.g., omit user_id) and confirm error response for validation failure.
 */
export async function test_api_core_test_create_core_user_profile_full_and_error_cases(connection: api.IConnection) {
  // 1. Create a user using the users API endpoint (dependency)
  const userEmail = typia.random<string & tags.Format<"email">>();
  const username = RandomGenerator.alphaNumeric(12);
  const user = await api.functional.core.users.post(connection, {
    body: {
      role_id: typia.random<string & tags.Format<"uuid">>(),
      username,
      email: userEmail,
      password: RandomGenerator.alphaNumeric(16),
      organization_id: typia.random<string & tags.Format<"uuid">>(),
      phone: RandomGenerator.mobile(),
    } satisfies IUser.ICreate,
  });
  typia.assert(user);

  // 2. Create a profile for this user with all optional/localization/metadata fields populated
  const fullProfileInput = {
    user_id: user.id,
    locale_id: typia.random<string & tags.Format<"uuid">>(),
    full_name: RandomGenerator.name(),
    avatar_url: `https://cdn.example.com/avatar/${user.id}.jpg`,
    timezone: "Asia/Seoul",
    bio: RandomGenerator.paragraph()(2),
    a11y_prefs: JSON.stringify({ contrast: "high", fontSize: "large" }),
  } satisfies IUserProfile.ICreate;
  const profile = await api.functional.core.userProfiles.post(connection, {
    body: fullProfileInput,
  });
  typia.assert(profile);

  // 3. Assert returned profile fields match the sent and system-managed values
  TestValidator.equals("user_id")(fullProfileInput.user_id)(profile.user_id);
  TestValidator.equals("locale_id")(fullProfileInput.locale_id)(profile.locale_id);
  TestValidator.equals("full_name")(fullProfileInput.full_name)(profile.full_name);
  TestValidator.equals("avatar_url")(fullProfileInput.avatar_url)(profile.avatar_url);
  TestValidator.equals("timezone")(fullProfileInput.timezone)(profile.timezone);
  TestValidator.equals("bio")(fullProfileInput.bio)(profile.bio);
  TestValidator.equals("a11y_prefs")(fullProfileInput.a11y_prefs)(profile.a11y_prefs);
  TestValidator.predicate("created_at ISO string")(!!profile.created_at && typeof profile.created_at === "string");
  TestValidator.predicate("updated_at ISO string")(!!profile.updated_at && typeof profile.updated_at === "string");

  // 4. Attempt another profile creation for the same user_id — expect uniqueness/conflict error
  await TestValidator.error("duplicate profile for user should fail")(() =>
    api.functional.core.userProfiles.post(connection, {
      body: fullProfileInput,
    })
  );

  // 5. Attempt creation with missing required field (user_id) — expect validation error
  await TestValidator.error("missing required user_id for profile should fail")(() =>
    api.functional.core.userProfiles.post(connection, {
      body: {
        // user_id intentionally omitted in this error path test
        full_name: RandomGenerator.name(),
      } as any, // required only to force runtime API error; type safety violation not permitted in real TypeScript
    })
  );
}

