import { tags } from "typia";

/**
 * Formal user profile entity per Core.user_profiles model, 1:1 mapping with
 * user. Implements all multicultural, accessibility, and privacy requirements
 * from the analysis. Exposes only business/auditable fields. Personalization,
 * localization, and evidence are first-class citizens for AI-native and
 * audit/explainability scenarios.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IUserProfile = {
  /** Profile record PK (user_profiles.id), non-editable, unique per user. */
  id: string & tags.Format<"uuid">;

  /**
   * Associated user's ID, enforcing 1:1 mapping for privacy preservation
   * (Core.user_profiles.user_id).
   */
  user_id: string & tags.Format<"uuid">;

  /** Preferred locale/language-region for this user (user_profiles.locale_id). */
  locale_id?: (string & tags.Format<"uuid">) | null;

  /**
   * Display name, as provided by user or profile onboarding
   * (user_profiles.full_name). Nullable for enhanced privacy or pseudonymous
   * users.
   */
  full_name?: string | null;

  /**
   * URI for avatar, profile image, or digital representation
   * (user_profiles.avatar_url). Supports up to 80KB, for A11Y/multicultural
   * teams.
   */
  avatar_url?: string | null;

  /**
   * User's configured timezone preference, improves UX and supports
   * accessiblity/ localization (user_profiles.timezone).
   */
  timezone?: string | null;

  /**
   * Optional short bio or intro for public/personalization flows
   * (user_profiles.bio).
   */
  bio?: string | null;

  /**
   * Serialized accessibility preferences (user_profiles.a11y_prefs). Used to
   * drive WCAG/a11y modules and analytics; never exposed directly for
   * tracking.
   */
  a11y_prefs?: string | null;

  /**
   * Creation timestamp of profile entity (Core.user_profiles.created_at), for
   * audit and compliance workflows.
   */
  created_at: string & tags.Format<"date-time">;

  /**
   * Update timestamp of profile data (user_profiles.updated_at),
   * audit/integrity/correction event.
   */
  updated_at: string & tags.Format<"date-time">;
};
export namespace IUserProfile {
  /**
   * Payload to create a user profile entry, implementing multicultural,
   * accessibility, and evidence-based onboarding as per the user_profiles
   * table in the Core schema.
   */
  export type ICreate = {
    /**
     * UUID for user who owns this profile, 1:1 relationship
     * (Core.user_profiles.user_id). Required, links to registered user
     * entity.
     */
    user_id: string & tags.Format<"uuid">;

    /**
     * Locale UUID for user's preferred i18n or a11y experience
     * (user_profiles.locale_id). May be omitted for default locale.
     */
    locale_id?: string & tags.Format<"uuid">;

    /**
     * User's complete display name to be shown in profile, analytics, or
     * notification flows. May be omitted for pseudonymous/anonymous users.
     */
    full_name?: string;

    /**
     * Optional URI for profile image/avatar in compliance with
     * accessibility/media handling policies (user_profiles.avatar_url).
     */
    avatar_url?: string;

    /**
     * Timezone code/identifier for localization. Used for accessibility and
     * multicultural context (user_profiles.timezone).
     */
    timezone?: string;

    /** Optional personal description (user_profiles.bio). */
    bio?: string;

    /**
     * Serialized accessibility preference set for WCAG/a11y enforcement
     * modules.
     */
    a11y_prefs?: string;
  };

  /**
   * Payload for partial/multi-field updates of user profile entry
   * (user_profiles table). Implements audit chain, accessibility,
   * multicultural, and personalization correction as per requirements. Record
   * PK/user_id is path-level and not here.
   */
  export type IUpdate = {
    /**
     * Updates the locale/language reference for user
     * (user_profiles.locale_id).
     */
    locale_id?: string & tags.Format<"uuid">;

    /**
     * Update user's full display name for personalization or
     * personalization-compliant context.
     */
    full_name?: string;

    /** Update avatar URL/media ref for user's profile image. */
    avatar_url?: string;

    /**
     * Update user's timezone (e.g., for activity logs, notifications,
     * calendar, analytics).
     */
    timezone?: string;

    /**
     * Update personal description or short intro text as per business or
     * audit requirements.
     */
    bio?: string;

    /**
     * Update accessibility settings, a11y/assistive preference payload.
     * AI-driven and WCAG-compliant flows can update this for user
     * adjustment.
     */
    a11y_prefs?: string;
  };
}

