import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IUserProfile } from "@ORGANIZATION/PROJECT-api/lib/structures/IUserProfile";

/**
 * Test updating a user profile including edge/error scenarios (not found, no permission).
 *
 * Validates that updates to localization, display name, and accessibility metadata on user profiles
 * are correctly applied and audited. Ensures error handling for update attempts on non-existent
 * profiles and with insufficient authorization works as designed.
 *
 * Process:
 * 1. Create a user profile, as only existing profiles may be updated.
 * 2. Update localization and metadata fields on the created user profile.
 * 3. Confirm all updated values and audit-relevant timestamps are changed appropriately.
 * 4. Attempt update on a randomly-generated (non-existent) profile id — expect 404 error.
 * 5. Attempt update as an unauthorized user (requires multi-user context) — expect permission error.
 */
export async function test_api_core_test_update_core_user_profile_and_handle_edge_cases(connection: api.IConnection) {
  // 1. Create a new user profile, required for update
  const newProfile = await api.functional.core.userProfiles.post(connection, {
    body: {
      user_id: typia.random<string & tags.Format<"uuid">>(),
      locale_id: typia.random<string & tags.Format<"uuid">>(),
      full_name: RandomGenerator.name(),
      avatar_url: `https://cdn.example.com/avatar/${typia.random<string & tags.Format<"uuid">>()}.png`,
      timezone: "Asia/Seoul",
      bio: RandomGenerator.paragraph()(),
      a11y_prefs: JSON.stringify({ contrast: "high", fontScale: 1.2 })
    } satisfies IUserProfile.ICreate
  });
  typia.assert(newProfile);

  // Capture timestamps before update
  const createdAtBefore = newProfile.created_at;
  const updatedAtBefore = newProfile.updated_at;

  // 2. Update specific fields (e.g. locale, timezone, name, a11y_prefs)
  const updatedFields: IUserProfile.IUpdate = {
    locale_id: typia.random<string & tags.Format<"uuid">>(),
    full_name: RandomGenerator.name(),
    avatar_url: `https://cdn.example.com/avatar/${typia.random<string & tags.Format<"uuid">>()}.png`,
    timezone: "Europe/London",
    bio: RandomGenerator.paragraph()(),
    a11y_prefs: JSON.stringify({ contrast: "low", screenReader: true })
  };
  const updatedProfile = await api.functional.core.userProfiles.putById(connection, {
    id: newProfile.id,
    body: updatedFields
  });
  typia.assert(updatedProfile);

  // 3. Confirm all updated values
  TestValidator.equals("update/locale_id")(updatedFields.locale_id)(updatedProfile.locale_id);
  TestValidator.equals("update/full_name")(updatedFields.full_name)(updatedProfile.full_name);
  TestValidator.equals("update/avatar_url")(updatedFields.avatar_url)(updatedProfile.avatar_url);
  TestValidator.equals("update/timezone")(updatedFields.timezone)(updatedProfile.timezone);
  TestValidator.equals("update/bio")(updatedFields.bio)(updatedProfile.bio);
  TestValidator.equals("update/a11y_prefs")(updatedFields.a11y_prefs)(updatedProfile.a11y_prefs);
  TestValidator.notEquals("updated_at should change")(updatedAtBefore)(updatedProfile.updated_at);
  TestValidator.equals("created_at remains")(createdAtBefore)(updatedProfile.created_at);

  // 4. Try to update a profile that does not exist (expect 404 error)
  await TestValidator.error("update not found")(() =>
    api.functional.core.userProfiles.putById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
      body: updatedFields
    })
  );

  // 5. (If context/user switching available) Try update with insufficient/no permission
  // NOTE: This step assumes a method to switch users/permissions in test runner context.
  // If not available, this step should be skipped or annotated as such.
}

