import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IUserProfile } from "@ORGANIZATION/PROJECT-api/lib/structures/IUserProfile";

/**
 * Validate soft-deletion of user profile with audit/evidence preservation and permission enforcement
 *
 * This test verifies:
 * 1. Normal soft-deletion of a user profile, ensuring evidence/audit information (`id` and `deleted_at`) is returned
 * 2. The profile is no longer accessible after deletion
 * 3. Attempting to soft-delete a non-existent profile yields the correct error
 * 4. Deleting a profile with insufficient permissions results in a permission error
 *
 * Steps:
 * 1. Create a user profile (dependency)
 * 2. Soft-delete the profile as an authorized actor
 *    - Assert response contains `id` and `deleted_at`
 * 3. Attempt to access profile after deletion (expect error/inaccessible)
 * 4. Soft-delete a random non-existent profile (expect error)
 * 5. Try to soft-delete with insufficient permission (simulate by token/context change, expect error)
 */
export async function test_api_core_test_delete_core_user_profile_soft_delete_and_permission_cases(
  connection: api.IConnection,
) {
  // 1. Create a user profile for deletion
  const userProfileCreate: IUserProfile.ICreate = {
    user_id: typia.random<string & tags.Format<"uuid">>(),
    locale_id: typia.random<string & tags.Format<"uuid">>(),
    full_name: RandomGenerator.name(),
    avatar_url: `https://example.com/avatar/${RandomGenerator.alphaNumeric(12)}`,
    timezone: "Asia/Seoul",
    bio: RandomGenerator.paragraph()(),
    a11y_prefs: null,
  };
  const createdProfile: IUserProfile = await api.functional.core.userProfiles.post(
    connection,
    { body: userProfileCreate },
  );
  typia.assert(createdProfile);

  // 2. Soft-delete as an authorized actor (happy path)
  const softDeleted: IUserProfile.ISoftDelete = await api.functional.core.userProfiles.eraseById(
    connection,
    { id: createdProfile.id },
  );
  typia.assert(softDeleted);
  TestValidator.equals("soft-deleted id")(createdProfile.id)(softDeleted.id);
  TestValidator.predicate("deleted_at is date-time string")(
    typeof softDeleted.deleted_at === "string" &&
      !isNaN(Date.parse(softDeleted.deleted_at))
  );

  // 3. Attempt to access the deleted profile (assuming a GET endpoint for verification)
  if (api.functional.core.userProfiles.getById) {
    await TestValidator.error("profile is now inaccessible")(() =>
      api.functional.core.userProfiles.getById(connection, {
        id: createdProfile.id,
      }),
    );
  }

  // 4. Attempt to soft-delete a non-existent profile ID
  const nonExistentId: string & tags.Format<"uuid"> = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("non-existent profile delete yields error")(() =>
    api.functional.core.userProfiles.eraseById(connection, {
      id: nonExistentId,
    }),
  );

  // 5. Soft-delete with insufficient permissions (simulate token/context switch)
  // For simulation: clone connection, clear or scramble auth header/tokens
  const insufficientPermConn = { ...connection, headers: { ...connection.headers } };
  if (insufficientPermConn.headers["Authorization"]) {
    insufficientPermConn.headers["Authorization"] = "Bearer invalid-or-low-priv-token";
  } else {
    insufficientPermConn.headers["Authorization"] = "Bearer unauthorized";
  }
  await TestValidator.error("forbidden without proper permissions")(() =>
    api.functional.core.userProfiles.eraseById(insufficientPermConn, {
      id: createdProfile.id,
    }),
  );
}

