import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IOrganization } from "@ORGANIZATION/PROJECT-api/lib/structures/IOrganization";

/**
 * 조직 생성 및 고유성/유효성 검증 E2E 테스트.
 *
 * 이 테스트는 조직(Organization) 엔티티를 생성하고 성공적으로 생성 및 반환된 모든 필드를 검증한 뒤,
 * 필수 입력 누락 시의 유효성 실패, 그리고 동일 name/code 중복 생성 시 오류 발생 케이스까지 모두 확인한다.
 *
 * Business 배경:
 * - 조직은 multi-tenant, B2B 구조에서 핵심 엔티티로 모든 유저, 권한, 연계 데이터의 기초가 된다.
 * - organizations.name, organizations.code 모두 DB 레벨 및 API 레벨에서 고유(unique) 제약을 갖는다.
 *
 * 테스트 시나리오 및 단계:
 * 1. 모든 필수 필드를 포함한 유효한 조직을 생성하고, 정상적으로 생성된 조직 오브젝트의 반환을 검증한다.
 *    반환된 조직의 name/code가 입력과 일치하며, id와 created_at, updated_at의 값이 올바른 포맷을 갖는지 확인한다.
 * 2. 필수 입력(name/code) 중 하나가 누락된 상태로 조직 생성 시도를 하여, API에서 유효성 오류가 적절히 반환되는지 검증한다. (각각 name 누락, code 누락 케이스 별도 검증)
 * 3. 1번에서 생성한 조직의 name 또는 code와 동일한 값으로 조직 생성 시도를 하여, 중복(unique) 오류가 반환되는지 확인한다. (name 중복, code 중복 케이스 별도 검증)
 *
 * 모든 단계에서 typia.assert로 타입 유효성을 검증하며, TestValidator.error를 통해 실패 케이스 오류 메시지를 검증한다.
 */
export async function test_api_core_test_create_core_organization_valid_and_duplicate_cases(connection: api.IConnection) {
  // 1. 정상 조직 생성
  const organizationInput = {
    name: RandomGenerator.alphabets(12),
    code: RandomGenerator.alphaNumeric(10).toLowerCase(),
  } satisfies IOrganization.ICreate;

  const created = await api.functional.core.organizations.post(connection, { body: organizationInput });
  typia.assert(created);
  TestValidator.equals("조직명 일치")(organizationInput.name)(created.name);
  TestValidator.equals("조직코드 일치")(organizationInput.code)(created.code);
  TestValidator.predicate("id는 uuid 포맷")(typeof created.id === "string" && /^([0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12})$/i.test(created.id));
  TestValidator.predicate("created_at ISO-8601 포맷")(typeof created.created_at === "string" && !isNaN(Date.parse(created.created_at)));
  TestValidator.predicate("updated_at ISO-8601 포맷")(typeof created.updated_at === "string" && !isNaN(Date.parse(created.updated_at)));

  // 2. 필수 입력값 누락 케이스
  await TestValidator.error("name 누락시 에러")(() =>
    api.functional.core.organizations.post(connection, {
      body: { code: RandomGenerator.alphaNumeric(10).toLowerCase() } as any
    })
  );

  await TestValidator.error("code 누락시 에러")(() =>
    api.functional.core.organizations.post(connection, {
      body: { name: RandomGenerator.alphabets(12) } as any
    })
  );

  // 3. name/code 중복 입력 시도 케이스
  await TestValidator.error("name 중복시 에러")(() =>
    api.functional.core.organizations.post(connection, {
      body: { name: organizationInput.name, code: RandomGenerator.alphaNumeric(10).toLowerCase() } satisfies IOrganization.ICreate,
    })
  );
  await TestValidator.error("code 중복시 에러")(() =>
    api.functional.core.organizations.post(connection, {
      body: { name: RandomGenerator.alphabets(12), code: organizationInput.code } satisfies IOrganization.ICreate,
    })
  );
}

