import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IOrganization } from "@ORGANIZATION/PROJECT-api/lib/structures/IOrganization";

/**
 * 조직(Organization) 생성의 정상/예외 및 중복 검증 E2E 테스트.
 *
 * 1. 모든 필수 입력(name, code)을 포함해 새로운 조직을 성공적으로 생성하고,
 *    반환된 오브젝트의 각 필드(id, created_at, updated_at, name, code)의 유효성과 포맷을 검증한다.
 * 2. 필수 입력(name/code) 누락 상황에서의 유효성 검사 실패(런타임) 케이스를 각각 검증한다.
 * 3. 이미 생성한 조직의 name 또는 code와 동일한 값으로 추가 조직 생성 시도 시
 *    고유성(unique) 제약 위반 오류가 발생하는지를 각각 검증한다.
 *
 * 모든 과정에서 typia.assert로 타입 검증, TestValidator로 비즈니스 로직 결과 평가.
 */
export async function test_api_core_test_create_core_organization_valid_and_duplicate_cases(
  connection: api.IConnection,
) {
  // 1. 정상 조직 생성 및 필드/유효성 검증
  const organizationInput = {
    name: RandomGenerator.alphabets(12),
    code: RandomGenerator.alphaNumeric(10).toLowerCase(),
  } satisfies IOrganization.ICreate;

  const created = await api.functional.core.organizations.post(connection, {
    body: organizationInput,
  });
  typia.assert(created);
  TestValidator.equals("조직명 일치")(organizationInput.name)(created.name);
  TestValidator.equals("조직코드 일치")(organizationInput.code)(created.code);
  TestValidator.predicate("id는 uuid 포맷임")(
    typeof created.id === "string" &&
      /^([0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12})$/i.test(created.id),
  );
  TestValidator.predicate("created_at은 ISO-8601 포맷임")(
    typeof created.created_at === "string" && !isNaN(Date.parse(created.created_at)),
  );
  TestValidator.predicate("updated_at은 ISO-8601 포맷임")(
    typeof created.updated_at === "string" && !isNaN(Date.parse(created.updated_at)),
  );

  // 2. 필수 입력(name, code) 누락 시 유효성 검증(런타임)
  await TestValidator.error("name 누락 시 에러")(() =>
    api.functional.core.organizations.post(connection, {
      // TypeScript 타입 시스템 우회 없이 실제 값만 테스트(필드는 명시적으로 누락)
      body: { code: RandomGenerator.alphaNumeric(10).toLowerCase() } as any,
    })
  );
  await TestValidator.error("code 누락 시 에러")(() =>
    api.functional.core.organizations.post(connection, {
      body: { name: RandomGenerator.alphabets(12) } as any,
    })
  );

  // 3. name과 code 별도 중복(unique) 에러 검증
  await TestValidator.error("name 중복 시 에러")(() =>
    api.functional.core.organizations.post(connection, {
      body: {
        name: organizationInput.name,
        code: RandomGenerator.alphaNumeric(10).toLowerCase(),
      } satisfies IOrganization.ICreate,
    })
  );
  await TestValidator.error("code 중복 시 에러")(() =>
    api.functional.core.organizations.post(connection, {
      body: {
        name: RandomGenerator.alphabets(12),
        code: organizationInput.code,
      } satisfies IOrganization.ICreate,
    })
  );
}

