import api from "@ORGANIZATION/PROJECT-api";
import type { IOrganization } from "@ORGANIZATION/PROJECT-api/lib/structures/IOrganization";

/**
 * E2E test for updating organizations via Core module API.
 *
 * Validates both successful update of organization details and error paths (non-existent resource, insufficient privileges).
 *
 * Flow overview:
 * 1. Create a new organization to update (via dependencies).
 * 2. Update this organization's name and code. Confirm that output reflects changes and maintains correct audit fields.
 * 3. Attempt update (PUT) for a non-existent organization UUID. Confirm 404 error.
 * 4. Simulate insufficient privileges (by, e.g., stripping auth headers or using a forbidden/anonymous connection). Confirm operation is blocked with a permission error (typically 403 or 401).
 */
export async function test_api_core_test_update_core_organization_success_and_error_paths(connection: api.IConnection) {
  // 1. Create organization
  const created = await api.functional.core.organizations.post(connection, {
    body: {
      name: RandomGenerator.alphabets(8),
      code: RandomGenerator.alphaNumeric(10)
    } satisfies IOrganization.ICreate
  });
  typia.assert(created);

  // 2. Update organization name and code
  const newName = RandomGenerator.alphabets(10);
  const newCode = RandomGenerator.alphaNumeric(12);
  const updated = await api.functional.core.organizations.putById(connection, {
    id: created.id,
    body: {
      name: newName,
      code: newCode
    } satisfies IOrganization.IUpdate
  });
