import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IOrganization } from "@ORGANIZATION/PROJECT-api/lib/structures/IOrganization";

/**
 * Tests soft-deletion (archiving) of an organization entity by its unique ID with comprehensive permission and edge case checks.
 *
 * Business context: Organizations in the system represent major B2B boundaries and are preserved for compliance, evidence, and multi-tenant isolation. Soft-deletion archives the entity via deleted_at timestamp, keeping audit trail and data retained. Only proper administrators may perform this operation, improper usage or invalid IDs must fail cleanly with no data side-effects.
 *
 * Test process:
 * 1. Create a new organization using unique parameters
 * 2. Perform a DELETE by id as an authorized actor; expect successful soft-delete (organization object is returned and can no longer be fetched from standard list)
 * 3. Attempt to delete a non-existent (random UUID) organization — expect clear not found error
 * 4. Simulate insufficient permission by calling delete as a non-admin (or non-authenticated connection if roles not implemented); expect permission denied error and no state change
 * 5. Confirm audit preservation (created_at, updated_at, soft delete fields are intact and logical)
 * 6. Verify organization cannot be deleted twice (second delete attempt returns error)
 */
export async function test_api_core_test_delete_core_organization_soft_delete_and_permission_checks(connection: api.IConnection) {
  // 1. Create a new organization
  const orgCreatePayload = {
    name: RandomGenerator.paragraph()(2),
    code: RandomGenerator.alphaNumeric(8),
  } satisfies IOrganization.ICreate;
  const org = await api.functional.core.organizations.post(connection, { body: orgCreatePayload });
  typia.assert(org);

  // 2. Soft-delete the organization by id
  const deletedOrg = await api.functional.core.organizations.eraseById(connection, { id: org.id });
  typia.assert(deletedOrg);
  TestValidator.equals("id after delete")(org.id)(deletedOrg.id);
  TestValidator.equals("name after delete")(org.name)(deletedOrg.name);
  TestValidator.equals("code after delete")(org.code)(deletedOrg.code);
  TestValidator.predicate("soft delete field exists")(!!deletedOrg.updated_at);

  // 3. Try deleting a non-existent org (should get 404 or similar error)
  const fakeId = typia.random<string & tags.Format<"uuid">>();
  TestValidator.error("deleting non-existent org fails")(() =>
    api.functional.core.organizations.eraseById(connection, { id: fakeId }),
  );

  // 4. Simulate insufficient permissions: call with insufficient context (e.g., no auth headers)
  const unauthConnection = { ...connection, headers: {} };
  TestValidator.error("delete with insufficient rights fails")(() =>
    api.functional.core.organizations.eraseById(unauthConnection, { id: org.id }),
  );

  // 5. Confirm audit trail preservation
  TestValidator.equals("creation time preserved")(org.created_at)(deletedOrg.created_at);
  TestValidator.predicate("modification time updated")(deletedOrg.updated_at > org.created_at);

  // 6. Double deletion returns error (cannot soft-delete twice)
  TestValidator.error("double deletion fails")(() =>
    api.functional.core.organizations.eraseById(connection, { id: org.id }),
  );
}

