/**
 * Test listing and filtering roles with proper and invalid queries, and permission handling.
 *
 * - Confirm functional role listing (with/without filters), correct pagination, and filter support for 'code' and 'name'.
 * - Ensure invalid filters (random name/code not present) yield empty or correct results.
 * - Attempt to call as unauthorized/restricted user and expect an error/forbidden response.
 * - Validate that the response data and pagination match IPageIRole typing, and all roles have correct structure.
 * - Edge cases: non-existent filters, large-page numbers, and unauthorized access checks.
 */
export async function test_api_core_test_list_core_roles_with_filters_and_permissions(
  connection: api.IConnection,
) {
  // 1. List all roles (no filter)
  const pageUnfiltered = await api.functional.core.roles.patch(connection, {
    body: {}
  });
  typia.assert(pageUnfiltered);
  TestValidator.predicate('should have roles')(Array.isArray(pageUnfiltered.data));

  // 2. Filter by an existing role's name, if possible
  let filterName: string | undefined = pageUnfiltered.data.length ? pageUnfiltered.data[0].name : undefined;
  if (filterName) {
    const pageByName = await api.functional.core.roles.patch(connection, {
      body: { name: filterName }
    });
    typia.assert(pageByName);
    TestValidator.predicate('filtered roles all match')(pageByName.data.every(r => r.name === filterName));
  }

  // 3. Filter by non-existent name
  const pageByInvalid = await api.functional.core.roles.patch(connection, {
    body: { name: 'non-existent-role-' + Date.now() }
  });
  typia.assert(pageByInvalid);
  TestValidator.equals('should return 0 roles')(0)(pageByInvalid.data.length);

  // 4. Paginate with large page number
  const pageLarge = await api.functional.core.roles.patch(connection, {
    body: { page: 9999 }
  });
  typia.assert(pageLarge);
  TestValidator.predicate('large page yields 0 or empty')(pageLarge.data.length === 0 || pageLarge.pagination.current >= 9999);

  // 5. Test forbidden access (simulate restricted/unauthorized user)
  // Attempt call with missing/invalid token or insufficient permission
  const unauthConn = { ...connection, headers: {} };
  await TestValidator.error('unauthorized cannot list roles')(() => api.functional.core.roles.patch(unauthConn, { body: {} }));
}

