import api from "@ORGANIZATION/PROJECT-api";
import type { IRole } from "@ORGANIZATION/PROJECT-api/lib/structures/IRole";
import type { IPageIRole } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIRole";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test listing and filtering of roles including permission/authorization edge cases.
 *
 * This test verifies the API for listing roles (with filtering and pagination), covers normal and edge filters, and confirms RBAC/permission controls work as expected.
 *
 * **Steps:**
 * 1. List all roles (no filter) and validate shape and content
 * 2. Filter by an existing role's name and check filtered result
 * 3. Filter by a non-existent role name (should yield zero results)
 * 4. Test pagination with a large page number (should yield empty data)
 * 5. Attempt with an unauthorized connection (should throw/forbid)
 */
export async function test_api_core_test_list_core_roles_with_filters_and_permissions(
  connection: api.IConnection,
) {
  // 1. List all roles (no filter)
  const allRoles = await api.functional.core.roles.patch(connection, {
    body: {}
  });
  typia.assert(allRoles);
  TestValidator.predicate('should return roles array')(Array.isArray(allRoles.data));
  TestValidator.predicate('pagination structure')(typeof allRoles.pagination === 'object');
  TestValidator.predicate('roles shape')(allRoles.data.every(role => typeof role.id === 'string' && typeof role.name === 'string'));

  // 2. Filter by an existing role's name (if any role exists)
  if (allRoles.data.length > 0) {
    const name = allRoles.data[0].name;
    const filtered = await api.functional.core.roles.patch(connection, {
      body: { name }
    });
    typia.assert(filtered);
    TestValidator.predicate('filtered roles match the given name')(filtered.data.every(role => role.name === name));
  }

  // 3. Filter by a non-existent name
  const impossibleName = 'no-such-role-' + Date.now();
  const filteredNone = await api.functional.core.roles.patch(connection, {
    body: { name: impossibleName }
  });
  typia.assert(filteredNone);
  TestValidator.equals('should be empty array')(0)(filteredNone.data.length);

  // 4. Paginate with a large (out of range) page number
  const largePage = await api.functional.core.roles.patch(connection, {
    body: { page: 9999 }
  });
  typia.assert(largePage);
  TestValidator.predicate('should be empty array or on page 9999')(largePage.data.length === 0 || largePage.pagination.current === 9999);

  // 5. Simulate a forbidden/unauthed connection (headers removed)
  const noAuthConn = { ...connection, headers: {} };
  await TestValidator.error('forbidden for unauth users')(() =>
    api.functional.core.roles.patch(noAuthConn, { body: {} }),
  );
}

