 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IRole = {
  /**
   * Primary key identifier for the role. Direct mapping to roles.id field in
   * Prisma schema. Used in permission/RBAC enforcement, audit, and API
   * assignment controls.
   */
  id: string & tags.Format<"uuid">;

  /**
   * Organization to which this role belongs. Allows for organization-scoped
   * RBAC and regulatory separation. Derived from roles.organization_id field
   * in schema and ERD.
   */
  organization_id: string & tags.Format<"uuid">;

  /**
   * Human-friendly display name for the role (e.g., 'admin', 'manager',
   * 'customer'). Used in UI, policy management, and compliance evidence
   * reporting.
   */
  name: string;

  /**
   * Unique slug/code for this role, enforced unique within the organization.
   * Key for API-level policy enforcement and automated permission mapping.
   * Sourced from roles.code in schema.
   */
  code: string;

  /**
   * Long-form explanation for this role's authority, business context, and
   * operational scope. Key for evidence, admin onboarding, and auditing (see
   * requirements for traceability and future extensibility).
   */
  description?: string;

  /**
   * Timestamp for role creation. Analytics, audit, compliance
   * trace—immutable.
   */
  created_at: string & tags.Format<"date-time">;

  /**
   * Timestamp of last update. Used for compliance, permission change history,
   * and onboarding review.
   */
  updated_at: string & tags.Format<"date-time">;
};
export namespace IRole {
  /**
   * Payload for creating a new role entity. Enforcement of RBAC, onboarding,
   * and compliance evidence policies (see requirements analysis, Prisma
   * schema roles table, ERD).
   */
  export type ICreate = {
    /**
     * Required unique identifier of the organization context in which to
     * create the role.
     *
     * Referenced from: roles.organization_id in schema. Ensures audit trace
     * and B2B isolation.
     */
    organization_id: string & tags.Format<"uuid">;

    /**
     * Display name for new role (e.g., 'admin', 'staff'). Enforced for
     * uniqueness, compliance, and onboarding workflows.
     */
    name: string;

    /**
     * Machine slug for the role. Used for programmatic RBAC
     * mapping/automation. Reference: roles.code in schema. Must be unique
     * within the org.
     */
    code: string;

    /**
     * Optional human readable explanation of the role context. Assists in
     * onboarding, evidence management, and permission documentation.
     */
    description?: string;
  };
}

