import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ISession } from "@ORGANIZATION/PROJECT-api/lib/structures/ISession";
import type { IPageISession } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageISession";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate advanced session search and pagination for sessions (PATCH /core/sessions).
 *
 * This E2E test covers: 
 * - Correctness of filter and pagination for diverse session search conditions
 * - Error handling for invalid filters/pagination
 * - Business logic validation for session active, expired and user-specific queries
 *
 * Process:
 * 1. Query all sessions (default pagination), assert structure
 * 2. Query sessions for a specific user via user_id filter; all results should match user_id
 * 3. Query only expired and only active sessions (expires_before, expires_after)
 * 4. Query by device_fingerprint and by ip (if present)
 * 5. Invalid: send negative page/large limit, expect error
 * 6. Edge: send empty filter, expect all sessions, valid pagination
 * 7. Check pagination metadata always consistent with data length
 */
export async function test_api_core_test_advanced_session_search_with_multiple_conditions(
  connection: api.IConnection,
) {
  // 1. Query all sessions, default (no filter)
  const allSessions = await api.functional.core.sessions.patch(connection, {
    body: {},
  });
  typia.assert(allSessions);
  TestValidator.predicate("data non-empty")(Array.isArray(allSessions.data));
  TestValidator.predicate("has pagination object")(!!allSessions.pagination);

  // Edge: double check consistency with empty filter
  const edgeSessions = await api.functional.core.sessions.patch(connection, {
    body: {},
  });
  typia.assert(edgeSessions);
  TestValidator.equals("all sessions result")(allSessions.data.length)(edgeSessions.data.length);

  // 2. Pick a user_id from existing sessions (if any) for user_id-based search
  if (allSessions.data.length > 0) {
    const userId = allSessions.data[0].user_id;
    const userSessions = await api.functional.core.sessions.patch(connection, {
      body: {
        user_id: userId,
      },
    });
    typia.assert(userSessions);
    // All sessions should belong to that user
    for (const session of userSessions.data) {
      TestValidator.equals("user_id matches")(userId)(session.user_id);
    }
  }

  // 3. Test expired and active sessions filter with expires_before/after
  const nowDate = new Date().toISOString();
  // Expired sessions: expires_before = now
  const expiredRes = await api.functional.core.sessions.patch(connection, {
    body: {
      expires_before: nowDate,
    },
  });
  typia.assert(expiredRes);
  for (const session of expiredRes.data) {
    TestValidator.predicate("expired session: expires_at < now")(session.expires_at < nowDate);
  }
  // Active sessions: expires_after = now
  const activeRes = await api.functional.core.sessions.patch(connection, {
    body: {
      expires_after: nowDate,
    },
  });
  typia.assert(activeRes);
  for (const session of activeRes.data) {
    TestValidator.predicate("active session: expires_at >= now")(session.expires_at >= nowDate);
  }

  // 4. Attempt filtering by device_fingerprint and ip if such value is present in data
  const df = allSessions.data.find((s) => s.device_fingerprint);
  if (df) {
    const dfRes = await api.functional.core.sessions.patch(connection, {
      body: {
        device_fingerprint: df.device_fingerprint!,
      },
    });
    typia.assert(dfRes);
    for (const s of dfRes.data) {
      TestValidator.equals("device_fingerprint")(df.device_fingerprint)(s.device_fingerprint);
    }
  }
  const ip = allSessions.data.find((s) => s.ip);
  if (ip) {
    const ipRes = await api.functional.core.sessions.patch(connection, {
      body: {
        ip: ip.ip!,
      },
    });
    typia.assert(ipRes);
    for (const s of ipRes.data) {
      TestValidator.equals("ip")(ip.ip)(s.ip);
    }
  }

  // 5. Invalid: negative page, too large limit, expect error (simulate with TestValidator.error)
  await TestValidator.error("negative page fails")(() =>
    api.functional.core.sessions.patch(connection, {
      body: {
        page: -1,
      },
    })
  );
  await TestValidator.error("large limit fails")(() =>
    api.functional.core.sessions.patch(connection, {
      body: {
        limit: 1000000,
      },
    })
  );

  // 6. Pagination structure correctness - check values are consistent
  TestValidator.equals("pagination current page")(1)(allSessions.pagination.current);
  TestValidator.equals("pagination limit is data length or default")(
    allSessions.data.length
  )(
    allSessions.pagination.limit <= allSessions.data.length
      ? allSessions.pagination.limit
      : allSessions.data.length
  );
  TestValidator.predicate("pagination pages positive")(allSessions.pagination.pages >= 1);
  TestValidator.predicate("pagination records >= data length")(allSessions.pagination.records >= allSessions.data.length);
}

