import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ISession } from "@ORGANIZATION/PROJECT-api/lib/structures/ISession";

/**
 * E2E test for retrieving sessions by ID and enforcing access restrictions.
 *
 * This test covers both success and error paths for retrieving session details:
 *
 * 1. Create a session (dependency setup).
 * 2. Retrieve the newly created session by its ID. Assert ALL expected fields.
 * 3. Attempt retrieval using a non-existent session ID and confirm a 404 error.
 * 4. Attempt retrieval as a different user without access to the session and verify permission denied (security check).
 */
export async function test_api_core_test_get_core_session_by_id_success_and_denied_paths(connection: api.IConnection) {
  // 1. Create a new session for a test user
  const sessionInput: ISession.ICreate = {
    user_id: typia.random<string & tags.Format<"uuid">>(),
    token: RandomGenerator.alphaNumeric(32),
    expires_at: new Date(Date.now() + 1000 * 60 * 60).toISOString(), // 1 hour from now
    device_fingerprint: RandomGenerator.alphaNumeric(24),
    ip: "192.168.0.1",
  };

  const createdSession: ISession = await api.functional.core.sessions.post(connection, {
    body: sessionInput,
  });
  typia.assert(createdSession);

  // 2. Retrieve the created session by its ID
  const fetched: ISession = await api.functional.core.sessions.getById(connection, {
    id: createdSession.id,
  });
  typia.assert(fetched);

  // Validate all expected fields
  TestValidator.equals("session.id")(createdSession.id)(fetched.id);
  TestValidator.equals("session.user_id")(createdSession.user_id)(fetched.user_id);
  TestValidator.equals("session.token")(createdSession.token)(fetched.token);
  TestValidator.equals("session.expires_at")(createdSession.expires_at)(fetched.expires_at);
