  updated_at: string & tags.Format<"date-time">;
  deleted_at?: string & tags.Format<"date-time">;
};
export namespace IUser {
  /**
   * Payload for user registration/onboarding (Core.users). Used in
   * conjunction with administrative and self-service flows. Raw credentials
   * handled by secure backend logic. Auditable for compliance per requirement
   * analysis, references atomic schema columns for full normalization.
   */
  export type ICreate = {
    /**
     * UUID of the organization to which the user will be assigned
     * (Core.users.organization_id). Null for system/default or
     * single-tenant deployments.
     */
    organization_id?: string & tags.Format<"uuid">;

    /**
     * Role UUID for RBAC assignment (Core.users.role_id). Must reference
     * existing role.
     */
    role_id: string & tags.Format<"uuid">;

