     * login and normalization policies.
     */
    username: string;

    /**
     * Email to be assigned to user. Must be unique within system
     * (Core.users.email).
     */
    email: string & tags.Format<"email">;

    /** Optional phone to enable MFA or communications (Core.users.phone). */
    phone?: string | null;

    /**
     * Raw user password. Will be securely hashed and stored as
     * Core.users.password_hash by backend logic. Never returned in any
     * response. Ingest-only field.
     */
    password: string;
  };
}

