import { tags } from "typia";

/**
 * Represents an individual user session, as modeled in the `sessions` table of
 * the Core schema.
 *
 * A session tracks authentication, user context, device information, and
 * lifecycle for login, audit, and security analytics. Bound to MFA, privacy
 * protections, and session/logout evidence. See `sessions` in Prisma schema.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type ISession = {
  /**
   * The unique session identifier. See `sessions.id` in the Prisma schema.
   *
   * Provides secure, non-reusable assignment by system for every login
   * session.
   */
  id: string & tags.Format<"uuid">;

  /**
   * References the user who owns this session. See `sessions.user_id`.
   *
   * Enforces 1:N relationship with users for account/session management.
   */
  user_id: string & tags.Format<"uuid">;

  /**
   * Opaque authentication token for this session. See `sessions.token` in the
   * schema.
   *
   * Never exposes raw passwords; used for cookie or client-auth context.
   */
  token: string;

  /**
   * Timestamp for session expiry. See `sessions.expires_at` column.
   *
   * Used for session management and regulatory compliance (idle/absolute
   * timeout).
   */
  expires_at: string & tags.Format<"date-time">;

  /**
   * Optional device fingerprint for risk/MFA/analytics. See
   * `sessions.device_fingerprint`.
   *
   * Null if unknown; enables fraud and anomaly detection.
   */
  device_fingerprint?: string | null;

  /**
   * Last known IP address for the session (tracked for security). See
   * `sessions.ip`.
   *
   * May be IPv4 or v6. Nullable for privacy and evidence preservation.
   */
  ip?: string | null;

  /**
   * Timestamp for session creation.
   *
   * Used for activity auditing, anomaly detection, and compliance chain of
   * events.
   */
  created_at: string & tags.Format<"date-time">;

  /**
   * Timestamp if session was revoked (e.g., logout, sec event, GDPR). Null if
   * active.
   *
   * See `sessions.revoked_at` in schema for audit/evidence.
   */
  revoked_at?: (string & tags.Format<"date-time">) | null;
};
export namespace ISession {
  /**
   * Payload for creating a new user session record, as defined in the Core
   * schema (`sessions`).
   *
   * Enforces normalization, evidence, and integrity for authentication and
   * session tracking.
   */
  export type ICreate = {
    /**
     * References the user for whom the session is being created.
     *
     * Business logic must validate this exists in the users table
     * (`users.id`).
     */
    user_id: string & tags.Format<"uuid">;

    /**
     * Opaque unique authentication token for the session.
     *
     * Generated securely and must not duplicate existing values in
     * `sessions.token`.
     */
    token: string;

    /**
     * Datetime for native session expiration.
     *
     * Required for compliance, auto-logout, and session lifecycle logic.
     */
    expires_at: string & tags.Format<"date-time">;

    /**
     * Optional device fingerprint for fraud/anomaly/analytics tracking.
     *
     * See `sessions.device_fingerprint`.
     */
    device_fingerprint?: string | null;

    /**
     * Optional client IP address (IPv4/v6).
     *
     * May be populated for security tracking; null for privacy situations.
     */
    ip?: string | null;
  };
}

