import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IUser";
import type { ISession } from "@ORGANIZATION/PROJECT-api/lib/structures/ISession";

/**
 * Validate creation and error handling for user session creation in the Core schema.
 *
 * Business justification:
 *   - A session is tied to a specific user and must record authentication context.
 *   - All required fields (user_id, token, expires_at) must be enforced.
 *   - Creation should fail with schema or business errors if fields are missing/invalid, or if the session is a duplicate (same token/user).
 *   - Ensures compliance with audit, evidence, and security requirements.
 *
 * Steps:
 *   1. Create a user (to supply a valid user_id for the session).
 *   2. Create a new session for that user, supplying all required and some optional fields. Check that the resulting session is valid, and all returned properties match expectations.
 *   3. Attempt to create a session with missing required fields (should fail with API validation error).
 *   4. Attempt to create a session with an invalid user_id (should fail: user not found).
 *   5. Attempt to create a session with a duplicate (reused) token for the same user (should fail with business or constraint error, or otherwise be handled gracefully).
 *   6. Attempt to create a session with duplicate token but a different user (should fail or handle as business logic dictates).
 */
export async function test_api_core_test_create_core_session_with_success_and_validation_cases(connection: api.IConnection) {
  // 1. Create a user to supply a valid user_id
  const userEmail = typia.random<string & tags.Format<"email">>();
  const roleId = typia.random<string & tags.Format<"uuid">>();
  const organizationId = typia.random<string & tags.Format<"uuid">>();
  const username = RandomGenerator.alphaNumeric(8);
  const user = await api.functional.core.users.post(connection, {
    body: {
      username,
      email: userEmail,
      role_id: roleId,
      organization_id: organizationId,
      password: RandomGenerator.alphaNumeric(12),
      phone: null
    } satisfies IUser.ICreate,
  });
  typia.assert(user);

  // 2. Create a new session with all required (and optional) fields
  const sessionToken = RandomGenerator.alphaNumeric(32);
  const expiresAt = new Date(Date.now() + 1000 * 60 * 60 * 8).toISOString(); // 8hr from now
  const deviceFingerprint = RandomGenerator.alphaNumeric(16);
  const ip = "192.0.2." + typia.random<number & tags.Type<"uint8"> & tags.Minimum<1> & tags.Maximum<255>>()
  const session = await api.functional.core.sessions.post(connection, {
    body: {
      user_id: user.id,
      token: sessionToken,
      expires_at: expiresAt,
      device_fingerprint: deviceFingerprint,
      ip,
    } satisfies ISession.ICreate,
  });
  typia.assert(session);
  TestValidator.equals("session.user_id")(user.id)(session.user_id);
  TestValidator.equals("session.token")(sessionToken)(session.token);
  TestValidator.equals("session.expires_at")(expiresAt)(session.expires_at);
  if (session.device_fingerprint !== undefined && session.device_fingerprint !== null)
    TestValidator.equals("session.device_fingerprint")(deviceFingerprint)(session.device_fingerprint);
  if (session.ip !== undefined && session.ip !== null)
    TestValidator.equals("session.ip")(ip)(session.ip);

  // 3. Attempt to create session with missing required fields -- should error
  await TestValidator.error("missing required field 'token'")(() =>
    api.functional.core.sessions.post(connection, {
      body: {
        // user_id is set, but token is missing
        user_id: user.id,
        expires_at,
      } as any, // Intentionally violate contract for runtime negative scenario
    })
  );

  // 4. Attempt to create session with invalid user_id
  await TestValidator.error("invalid user_id should fail")(() =>
    api.functional.core.sessions.post(connection, {
      body: {
        user_id: typia.random<string & tags.Format<"uuid">>(), // not a real user
        token: RandomGenerator.alphaNumeric(32),
        expires_at,
      } satisfies ISession.ICreate,
    })
  );

  // 5. Attempt to create a duplicate session for the same user+token
  await TestValidator.error("duplicate session for same user+token")(() =>
    api.functional.core.sessions.post(connection, {
      body: {
        user_id: user.id,
        token: sessionToken,
        expires_at: new Date(Date.now() + 1000 * 60 * 60 * 24).toISOString(),
      } satisfies ISession.ICreate,
    })
  );

  // 6. Attempt to create a duplicate token for a different user
  const user2 = await api.functional.core.users.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      role_id: typia.random<string & tags.Format<"uuid">>(),
      organization_id: typia.random<string & tags.Format<"uuid">>(),
      password: RandomGenerator.alphaNumeric(12),
      phone: null,
    } satisfies IUser.ICreate,
  });
  typia.assert(user2);
  await TestValidator.error("duplicate token for different user should fail or be rejected")(() =>
    api.functional.core.sessions.post(connection, {
      body: {
        user_id: user2.id,
        token: sessionToken,
        expires_at: new Date(Date.now() + 1000 * 60 * 60 * 10).toISOString(),
      } satisfies ISession.ICreate,
    })
  );
}

