import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ISession } from "@ORGANIZATION/PROJECT-api/lib/structures/ISession";

/**
 * Test updating session attributes and associated error scenarios for the Core schema session resource.
 *
 * 1. Successfully create a new session and update its attributes (e.g., expires_at, device_fingerprint, ip, revoked_at).
 * 2. Verify that updates have persisted by fetching the session and checking values.
 * 3. Attempt to update a non-existent session (random UUID) and confirm a 404 or equivalent error is returned.
 * 4. Simulate insufficient permissions (e.g., by using a new/invalid connection) and verify the update operation is blocked by authorization rules (expect error response).
 */
export async function test_api_core_test_update_core_session_success_and_error_handling(
  connection: api.IConnection
) {
  // 1. Create a baseline session
  const createInput: ISession.ICreate = {
    user_id: typia.random<string & tags.Format<"uuid">>(),
    token: RandomGenerator.alphaNumeric(32),
    expires_at: new Date(Date.now() + 1000 * 60 * 60 * 24).toISOString(), // 24hr expiry
    device_fingerprint: RandomGenerator.alphaNumeric(16),
    ip: "192.168.1.100"
  };
  const session: ISession = await api.functional.core.sessions.post(connection, { body: createInput });
  typia.assert(session);

  // 2. Update session fields (set revoked_at, change expires_at and ip)
  const updateInput: ISession.IUpdate = {
    expires_at: new Date(Date.now() + 1000 * 60 * 60 * 48).toISOString(), // extend by +1 day
    ip: "10.11.22.33",
    revoked_at: new Date().toISOString(),
    device_fingerprint: "new-device-fp"
  };
  const updated: ISession = await api.functional.core.sessions.putById(connection, { id: session.id, body: updateInput });
  typia.assert(updated);
  TestValidator.equals("session id preserved")(session.id)(updated.id);
  TestValidator.equals("user id unchanged")(session.user_id)(updated.user_id);
  TestValidator.equals("expires_at updated")(updateInput.expires_at)(updated.expires_at);
  TestValidator.equals("ip updated")(updateInput.ip)(updated.ip);
  TestValidator.equals("revoked_at set")(updateInput.revoked_at)(updated.revoked_at);
  TestValidator.equals("device_fingerprint updated")(updateInput.device_fingerprint)(updated.device_fingerprint);

  // 3. Attempt update of a non-existent session
  await TestValidator.error("update non-existent session should fail")(() =>
    api.functional.core.sessions.putById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
      body: {
        expires_at: new Date(Date.now() + 1000 * 60 * 60 * 48).toISOString()
      }
    })
  );

  // 4. Attempt update with insufficient permissions (simulate invalid connection)
  const invalidConnection = { ...connection, headers: { ...connection.headers, Authorization: "Bearer invalid-token" } };
  await TestValidator.error("forbidden update should fail")(() =>
    api.functional.core.sessions.putById(invalidConnection, {
      id: session.id,
      body: { expires_at: new Date(Date.now() + 1000 * 60 * 60 * 50).toISOString() }
    })
  );
}

