import api from "@ORGANIZATION/PROJECT-api";
import type { ICoreLocale } from "@ORGANIZATION/PROJECT-api/lib/structures/ICoreLocale";

/**
 * End-to-end test for updating core locale entries with validation and security scenarios
 *
 * This test verifies the behavior of locale update operation through the API:
 * - Successfully updates an existing locale entry (integration: verify updated field values)
 * - Ensures audit-traceability post-update (implied, but mainly focus on updated values)
 * - Attempts to update a non-existent locale, expecting not-found or error response
 * - Tries update operation without proper privilege (simulate privilege drop/removal), expecting denial
 *
 * Steps:
 * 1. Create a locale (dependency)
 * 2. Update the created locale's name and code, check success and value update
 * 3. Attempt update for random (invalid) UUID, expect error
 * 4. (If possible) Simulate non-privileged user and try update, expect error
 */
export async function test_api_core_test_update_core_locale_and_handle_invalid_and_permission(
  connection: api.IConnection,
) {
  // 1. Create locale dependency
  const locale: ICoreLocale = await api.functional.core.locales.post(connection, {
    body: {
      code: "en-US",
      name: "English (United States)",
    },
  });
  typia.assert(locale);

  // 2. Update the locale with new name/code
  const updated: ICoreLocale = await api.functional.core.locales.putById(connection, {
    id: locale.id,
    body: {
      code: "en-US-test",
      name: "US English Test",
    },
  });
  typia.assert(updated);
  TestValidator.equals("id should remain unchanged")(locale.id)(updated.id);
  TestValidator.equals("code should update")("en-US-test")(updated.code);
  TestValidator.equals("name should update")("US English Test")(updated.name);

  // 3. Try to update a non-existent locale and expect error
  await TestValidator.error("should fail for unknown id")(() =>
    api.functional.core.locales.putById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
      body: {
        code: "ko-KR-invalid",
        name: "Invalid Locale",
      },
    }),
  );

  // 4. Attempt update without proper privileges (simulate privilege drop)
  // [Assume connection manipulation disables privilege, or skip with explanation if not possible]
  // If privilege simulation possible:
  if (connection.headers && "Authorization" in connection.headers) {
    const noAuthConnection = {
      ...connection,
      headers: { ...connection.headers, Authorization: undefined },
    };
    await TestValidator.error("should reject update without privilege")(() =>
      api.functional.core.locales.putById(noAuthConnection, {
        id: locale.id,
        body: {
          code: "unauthorized",
          name: "No Priv Update",
        },
      }),
    );
  }
}

