import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ICoreLocale } from "@ORGANIZATION/PROJECT-api/lib/structures/ICoreLocale";

/**
 * Test deletion of locale entries in the Core system.
 *
 * This test covers deletion (soft/logical) of locale entries using the eraseById endpoint, focusing on audit record preservation, not-found error handling, and permission security.
 *
 * Steps:
 * 1. Create a new locale entry for setup.
 * 2. Delete the created locale by its ID and validate soft/logical delete and correct audit information (deleted_at, locale_id, etc).
 * 3. Attempt to delete a non-existent (random UUID) locale and expect a not-found (404) error.
 * 4. (If auth/permissions available) Attempt deletion with insufficient rights and expect a security error. Otherwise, skip this step.
 *
 * The test verifies type safety, audit trail correctness, logical delete semantics, and proper access controls for robust admin flows.
 */
export async function test_api_core_test_delete_core_locale_soft_delete_and_permission_cases(
  connection: api.IConnection,
) {
  // 1. Create a locale entry to later delete
  const locale = await api.functional.core.locales.post(connection, {
    body: {
      code: `test-${RandomGenerator.alphaNumeric(8)}`,
      name: `Test Locale ${RandomGenerator.alphabets(4)}`,
    } satisfies ICoreLocale.ICreate,
  });
  typia.assert(locale);

  // 2. Delete (soft/logical) the created locale
  const result = await api.functional.core.locales.eraseById(connection, {
    id: locale.id,
  });
  typia.assert(result);
  TestValidator.equals("delete success")(true)(result.success);
  TestValidator.equals("deleted locale id")(locale.id)(result.locale_id);
  TestValidator.predicate("deleted_at is valid ISO date")(
    !isNaN(new Date(result.deleted_at).getTime()),
  );

  // 3. Try deleting a non-existent locale (should 404)
  await TestValidator.error("delete non-existent locale should 404")(async () => {
    await api.functional.core.locales.eraseById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
    });
  });

  // 4. (Optional) If env supports, test insufficient permissions (security error)
  //    - Skipped here: Would require role switching or mocking auth context.
}

