import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ICatalogEvidence } from "@ORGANIZATION/PROJECT-api/lib/structures/ICatalogEvidence";
import type { IPageICatalogEvidence } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageICatalogEvidence";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate listing of catalog evidence with pagination and various filters.
 *
 * This test confirms that catalog evidence records can be fetched with a variety of filter combinations, and that paginated response metadata and data arrays behave as intended. The scenario covers both typical and edge use cases, such as empty results, valid/invalid filter sets, and request parameters at limit conditions.
 *
 * Steps:
 * 1. Attempt to list catalog evidence with no filters (should receive some or empty results, valid pagination)
 * 2. List with a filter (reference_uri, description, catalog_event_id, date range)
 * 3. List with pagination: valid (page/limit), out-of-bounds (high page), and limit=0
 * 4. List with a filter combination that should yield no results (random UUID and reference_uri)
 * 5. Validate that each result is a valid catalog evidence object and that pagination metadata matches received data
 * 6. Send an invalid filter (e.g., malformed date) and verify error response or empty result
 */
export async function test_api_productCatalog_test_list_catalog_evidence_with_pagination_and_filters(
  connection: api.IConnection,
) {
  // 1. List evidence with no filters
  const resultAll = await api.functional.productCatalog.catalogEvidence.patch(connection, {
    body: {},
  });
  typia.assert(resultAll);
  if (resultAll.data) {
    for (const evidence of resultAll.data) typia.assert(evidence);
  }
  if (resultAll.pagination) {
    TestValidator.equals("limit matches data.length")(
      Math.min(resultAll.pagination.limit, resultAll.pagination.records - (resultAll.pagination.current - 1) * resultAll.pagination.limit)
    )(resultAll.data?.length ?? 0);
    TestValidator.predicate("current page >= 1")(resultAll.pagination.current >= 1);
    TestValidator.predicate("limit positive")(resultAll.pagination.limit > 0);
    TestValidator.predicate("page count positive")(resultAll.pagination.pages > 0);
    TestValidator.predicate("record count >= 0")(resultAll.pagination.records >= 0);
  }

  // 2. List with filters: random reference_uri & created_at window
  const filterReference = await api.functional.productCatalog.catalogEvidence.patch(connection, {
    body: {
      reference_uri: "nonexistent://dummy" as string & tags.MaxLength<80000>,
      created_at_from: new Date(2000, 0, 1).toISOString() as string & tags.Format<"date-time">,
      created_at_to: new Date(2200, 0, 1).toISOString() as string & tags.Format<"date-time">,
    },
  });
  typia.assert(filterReference);
  TestValidator.equals("filtered result is empty")(0)(filterReference.data?.length ?? 0);

  // 3. Pagination: high page, low/0 limit
  const outOfBoundsPage = await api.functional.productCatalog.catalogEvidence.patch(connection, {
    body: { page: 9999, limit: 10 },
  });
  typia.assert(outOfBoundsPage);
  TestValidator.equals("empty array for OOB page")(0)(outOfBoundsPage.data?.length ?? 0);

  const zeroLimit = await api.functional.productCatalog.catalogEvidence.patch(connection, {
    body: { limit: 0 },
  });
  typia.assert(zeroLimit);
  TestValidator.equals("empty array for zero limit")(0)(zeroLimit.data?.length ?? 0);

  // 4. No matching filter
  const uuid = typia.random<string & tags.Format<"uuid">>();
  const noResult = await api.functional.productCatalog.catalogEvidence.patch(connection, {
    body: {
      catalog_event_id: uuid,
      description: "gibberish-no-match",
      reference_uri: "urn:no:match" as string & tags.MaxLength<80000>,
    },
  });
  typia.assert(noResult);
  TestValidator.equals("no results with impossible filter")(0)(noResult.data?.length ?? 0);

  // 5. Malformed input (invalid date string)
  await TestValidator.error("malformed date is rejected")(async () => {
    await api.functional.productCatalog.catalogEvidence.patch(connection, {
      body: {
        created_at_from: "definitely-not-a-date" as any,
      },
    });
  });
}

