import type { ICatalogEvidence } from "@ORGANIZATION/PROJECT-api/lib/structures/ICatalogEvidence";

/**
 * E2E test for catalog evidence creation endpoint, covering success and validation/failure scenarios.
 *
 * This function tests the following:
 * 1. Successfully creates a catalog evidence record with all valid required fields, and verifies the returned object.
 * 2. Tries to create a record with required fields missing, expecting validation errors.
 * 3. Attempts to create a record with an invalid data type, expecting failure and error handling.
 * 4. Attempts to create a record referencing a non-existent catalog_event_id (foreign key), expecting a referential integrity error (e.g., 409).
 */
export async function test_api_productCatalog_test_create_catalog_evidence_with_valid_and_invalid_data(connection: api.IConnection) {
  // 1. Success: Create with all required and valid data
  const evidenceBody: ICatalogEvidence.ICreate = {
    reference_uri: RandomGenerator.alphaNumeric(16),
    description: RandomGenerator.paragraph()(),
    // Optional foreign key can be omitted or set to null here for main case
    catalog_event_id: null,
  };
  const evidence = await api.functional.productCatalog.catalogEvidence.post(connection, { body: evidenceBody });
  typia.assert(evidence);
  TestValidator.equals("reference_uri")(evidence.reference_uri)(evidenceBody.reference_uri);
  TestValidator.equals("description")(evidence.description)(evidenceBody.description);
  TestValidator.equals("catalog_event_id")(evidence.catalog_event_id ?? null)(null);
  TestValidator.predicate("created_at ISO string")(!!evidence.created_at);
  TestValidator.predicate("id is UUID")(typeof evidence.id === "string" && evidence.id.length > 0);

  // 2. Failure: Missing required field (reference_uri)
  await TestValidator.error("missing reference_uri triggers validation error")(async () => {
    // @ts-expect-error: Intentionally omitting required field for runtime error
    return api.functional.productCatalog.catalogEvidence.post(connection, {
      body: {
        description: RandomGenerator.paragraph()(),
        catalog_event_id: null,
      },
    });
  });

  // 3. Failure: Invalid data type (reference_uri too long)
  await TestValidator.error("reference_uri exceeds maxLength triggers error")(async () => {
    return api.functional.productCatalog.catalogEvidence.post(connection, {
      body: {
        reference_uri: RandomGenerator.alphaNumeric(90001), // exceed MaxLength<80000>
        description: RandomGenerator.paragraph()(),
        catalog_event_id: null,
      },
    });
  });

  // 4. Referential integrity: non-existent catalog_event_id
  await TestValidator.error("non-existent catalog_event_id triggers integrity error")(async () => {
    return api.functional.productCatalog.catalogEvidence.post(connection, {
      body: {
        reference_uri: RandomGenerator.alphaNumeric(16),
        description: RandomGenerator.paragraph()(),
        catalog_event_id: typia.random<string & tags.Format<"uuid">>(), // random likely to not exist
      },
    });
  });
}

