import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ICart } from "@ORGANIZATION/PROJECT-api/lib/structures/ICart";
import type { IPageICart } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageICart";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Tests listing carts with pagination, search, and filter.
 * 
 * This test covers cart list functionality using the PATCH /cartOrder/cart endpoint. It validates that:
 * - carts can be listed with pagination (page/limit)
 * - searching and filtering using user_id, session_id, and date ranges is respected
 * - pagination and page metadata (current, limit, records, pages) are accurate
 * - the results properly reflect the filter (all carts match the search)
 * - edge conditions: no carts, one cart, or filter that returns empty
 * - invalid filter parameters are handled and errors returned as expected
 * 
 * Steps:
 * 1. List all carts with default pagination
 * 2. List carts with a specific limit and page
 * 3. If any carts, filter by user_id and check only those carts are returned
 * 4. If any carts, filter by a creation window and assert only relevant carts show up
 * 5. Create a filter that will definitely yield empty results (impossible uuid), expect data empty
 * 6. Call with invalid filter parameters (malformed uuid, invalid pagination), expect error
 */
export async function test_api_cartOrder_test_list_and_search_carts_with_pagination_and_filters(connection: api.IConnection) {
  // 1. List carts with default pagination
  const defaultResult = await api.functional.cartOrder.cart.patch(connection, { body: {} });
  typia.assert(defaultResult);
  if (defaultResult.data && defaultResult.data.length) {
    // 2. List with a specific page/limit
    const limit = 1;
    const paged = await api.functional.cartOrder.cart.patch(connection, { body: { page: 1, limit } });
    typia.assert(paged);
    TestValidator.equals("page/limit")(paged.pagination?.limit)(limit);
    TestValidator.predicate("Correct number of results")(paged.data!.length <= limit);

    // 3. Filter by user_id
    const userId = defaultResult.data[0].user_id;
    const filteredByUser = await api.functional.cartOrder.cart.patch(connection, { body: { user_id: userId } });
    typia.assert(filteredByUser);
    TestValidator.predicate("Filter by user")(filteredByUser.data!.every(c => c.user_id === userId));

    // 4. Filter by creation window (to first cart's created_at)
    const firstCreated = defaultResult.data[0].created_at;
    const filteredByDate = await api.functional.cartOrder.cart.patch(connection, { body: { created_at_to: firstCreated } });
    typia.assert(filteredByDate);
    TestValidator.predicate("created_at <= created_at_to")(filteredByDate.data!.every(c => c.created_at <= firstCreated));
  }

  // 5. Edge: filter that yields empty results
  const none = await api.functional.cartOrder.cart.patch(connection, { body: { user_id: "00000000-0000-0000-0000-000000000000" } });
  typia.assert(none);
  TestValidator.equals("empty filter")(none.data?.length ?? 0)(0);

  // 6. Invalid: bad uuid (should error), invalid page/limit
  await TestValidator.error("invalid user_id")(() => api.functional.cartOrder.cart.patch(connection, { body: { user_id: "not-a-uuid" } }));
  await TestValidator.error("invalid pagination")(() => api.functional.cartOrder.cart.patch(connection, { body: { page: 0, limit: -1 } }));
}

