/**
 * 카트 목록을 페이지네이션, 검색, 필터와 함께 조회합니다.
 *
 * 이 테스트는 PATCH /cartOrder/cart 엔드포인트를 이용해 아래 사항을 검증합니다:
 * - 페이지네이션(page, limit) 및 기본 조회 가능성
 * - user_id, session_id, 생성일자(created_at) 등 필터링 조건의 정상 작동
 * - 응답의 페이지 메타데이터(current, limit, records, pages)의 정확성
 * - 필터 조건 사용 시 결과 데이터가 요구를 충족하는지 확인
 * - 데이터가 없을 때나 단일 카트만 있을 때, 불가능한 조건으로 완전 빈 결과가 나오는지 테스트
 * - 잘못된 필터(예: 잘못된 uuid, 잘못된 page/limit) 사용 시 오류 응답이 반환되는지 확인
 *
 * [점검 절차]
 * 1. 기본 페이지네이션(필터 없이) 카트 목록 조회
 * 2. 특정 페이지/limit 지정 조회
 * 3. 데이터가 있으면 user_id로 필터링 및 일치성 확인
 * 4. 데이터가 있으면 생성일(created_at) 조건으로 필터링
 * 5. 절대 존재하지 않는 user_id 값(올 제로 uuid)으로 빈 결과 확인
 * 6. 잘못된 user_id(비-uuid 포맷), page/limit 음수로 요청 시 오류 반환 검증
 */
export async function test_api_cartOrder_test_list_and_search_carts_with_pagination_and_filters(
  connection: api.IConnection,
) {
  // 1. 기본 페이지네이션으로 카트 목록 조회
  const defaultResult = await api.functional.cartOrder.cart.patch(connection, { body: {} });
  typia.assert(defaultResult);

  if (defaultResult.data && defaultResult.data.length) {
    // 2. 페이지/limit을 지정하여 일부 카트만 조회
    const limit = 1;
    const paged = await api.functional.cartOrder.cart.patch(connection, { body: { page: 1, limit } });
    typia.assert(paged);
    TestValidator.equals("page/limit")(paged.pagination?.limit)(limit);
    TestValidator.predicate("결과가 limit 이하인지")(paged.data!.length <= limit);

    // 3. user_id로 필터링
    const userId = defaultResult.data[0].user_id;
    const filteredByUser = await api.functional.cartOrder.cart.patch(connection, { body: { user_id: userId } });
    typia.assert(filteredByUser);
    TestValidator.predicate("user_id 필터 일치 여부")(filteredByUser.data!.every(c => c.user_id === userId));

    // 4. 생성일자(created_at <= 기준)로 필터링
    const firstCreated = defaultResult.data[0].created_at;
    const filteredByDate = await api.functional.cartOrder.cart.patch(connection, { body: { created_at_to: firstCreated } });
    typia.assert(filteredByDate);
    TestValidator.predicate("created_at <= created_at_to")(filteredByDate.data!.every(c => c.created_at <= firstCreated));
  }

  // 5. 데이터가 절대 나올 수 없는 조건(user_id 전부 0)으로 빈 결과 확인
  const none = await api.functional.cartOrder.cart.patch(connection, { body: { user_id: "00000000-0000-0000-0000-000000000000" } });
  typia.assert(none);
  TestValidator.equals("빈 결과 필터")(none.data?.length ?? 0)(0);

  // 6. 잘못된 user_id(uuid 포맷 아님), page/limit 잘못된 값은 오류를 반환해야 함
  await TestValidator.error("잘못된 user_id")(() => api.functional.cartOrder.cart.patch(connection, { body: { user_id: "not-a-uuid" } }));
  await TestValidator.error("잘못된 pagination")(() => api.functional.cartOrder.cart.patch(connection, { body: { page: 0, limit: -1 } }));
}

