import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ICart } from "@ORGANIZATION/PROJECT-api/lib/structures/ICart";

/**
 * 종합적으로 장바구니 단건 조회(GET /cartOrder/cart/:id)에 대한 E2E 테스트 수행.
 *
 * 비즈니스 목적: 장바구니 활성 세션 복구, 사용자 개인화, 관리자의 감사, 사용자 접근권한 검증 등. cart 엔티티의 PK인 id로 조회했을 때의 정상/비정상 흐름을 검증한다.
 *
 * [테스트 프로세스]
 * 1. 테스트용 사용자를 생성하여 access token을 세팅한다 (세션/로그인 필요시).
 * 2. cartOrder.cart.post API로 장바구니를 생성한다 (user_id 직접 주입), 성공 응답 받아 ICart.id 확보.
 * 3. 해당 id로 cartOrder.cart.getById API 정상 호출 후, 응답값(ICart 전체 필드)이 올바른지 모두 검증.
 * 4. 존재하지 않는 id (UUID 랜덤)로 getById 시도 → 404 not found 에러 확인.
 * 5. (권한 강제 검증) 테스트 사용자 user_id와 다른 타인 user_id로 cart를 만든 뒤, 원래 사용자 세션으로 해당 cart를 조회 → 403 forbidden 등 권한 에러 발생하는지 검증.
 * 6. 필요한 경우 soft delete(cart.deleted_at) 케이스도 추가 가능.
 */
export async function test_api_cartOrder_test_get_cart_by_valid_and_invalid_id(
  connection: api.IConnection,
) {
  // 1. 테스트용 사용자1(OWNER) UUID 및 세션 정의
  const user1_id: string = typia.random<string & tags.Format<"uuid">>();

  // 2. OWNER용 cart 생성
  const ownerCart: ICart = await api.functional.cartOrder.cart.post(connection, {
    body: {
      user_id: user1_id
    } satisfies ICart.ICreate
  });
  typia.assert(ownerCart);

  // 3. 정상: 생성된 장바구니 id로 단건 조회
  const getCart: ICart = await api.functional.cartOrder.cart.getById(connection, {
    id: ownerCart.id
  });
  typia.assert(getCart);
  TestValidator.equals("cart.id")(ownerCart.id)(getCart.id);
  TestValidator.equals("cart.user_id")(ownerCart.user_id)(getCart.user_id);
  TestValidator.equals("cart.session_id")(ownerCart.session_id ?? null)(getCart.session_id ?? null);
  TestValidator.equals("created_at")(ownerCart.created_at)(getCart.created_at);
  TestValidator.equals("updated_at")(ownerCart.updated_at)(getCart.updated_at);
  TestValidator.equals("deleted_at")(ownerCart.deleted_at ?? null)(getCart.deleted_at ?? null);

  // 4. 실패: 존재하지 않는 UUID로 조회 → 404
  await TestValidator.error("not found")(() =>
    api.functional.cartOrder.cart.getById(connection, {
      id: typia.random<string & tags.Format<"uuid">>()
    })
  );

  // 5. 실패: 타인 user_id cart 조회 → 403 또는 권한 에러 (동작 정책에 따라)
  const user2_id: string = typia.random<string & tags.Format<"uuid">>();
  const otherCart: ICart = await api.functional.cartOrder.cart.post(connection, {
    body: {
      user_id: user2_id
    } satisfies ICart.ICreate
  });
  typia.assert(otherCart);

  await TestValidator.error("permission denied")(() =>
    api.functional.cartOrder.cart.getById(connection, {
      id: otherCart.id
    })
  );
}

