import { IConnection, HttpError } from "@nestia/fetcher";
import { PlainFetcher } from "@nestia/fetcher/lib/PlainFetcher";
import typia from "typia";
import { NestiaSimulator } from "@nestia/fetcher/lib/NestiaSimulator";

import { ICart } from "../../../structures/ICart";

/**
 * Create and persist a new cart record (CartOrder.cart subsystem).
 *
 * Creates a new persistent cart record, supporting both authenticated (user)
 * and anonymous (session-based) carts. Request body includes all required
 * fields for normalized cart creation (user/session reference, created_at at
 * server time, etc.).
 *
 * API must check for existing active cart where appropriate to avoid
 * duplicates. Typical creation is initiated by new session, user login, or cart
 * recovery flows. Post-creation, audit and evidence records for action are
 * produced. Data retention and privacy policies apply (soft delete logic on
 * abandonment).
 *
 * Returns the complete cart object on success. Errors: 409 for duplicate/active
 * cart, 403 for permission issues, 400 for invalid payload.
 *
 * @param props.connection
 * @param props.body Payload for new cart creation (user/session refs, etc.).
 * @path /cartOrder/cart
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export async function post(
  connection: IConnection,
  props: post.Props,
): Promise<post.Response> {
  return !!connection.simulate
    ? post.simulate(connection, props)
    : PlainFetcher.fetch(
        {
          ...connection,
          headers: {
            ...connection.headers,
            "Content-Type": "application/json",
          },
        },
        {
          ...post.METADATA,
          path: post.path(),
          status: null,
        },
        props.body,
      );
}
export namespace post {
  export type Props = {
    /** Payload for new cart creation (user/session refs, etc.). */
    body: ICart.ICreate;
  };
  export type Body = ICart.ICreate;
  export type Response = ICart;

  export const METADATA = {
    method: "POST",
    path: "/cartOrder/cart",
    request: {
      type: "application/json",
      encrypted: false,
    },
    response: {
      type: "application/json",
      encrypted: false,
    },
  } as const;

  export const path = () => "/cartOrder/cart";
  export const random = (g?: Partial<typia.IRandomGenerator>): ICart =>
    typia.random<ICart>(g);
  export const simulate = (
    connection: IConnection,
    props: post.Props,
  ): Response => {
    const assert = NestiaSimulator.assert({
      method: METADATA.method,
      host: connection.host,
      path: post.path(),
      contentType: "application/json",
    });
    try {
      assert.body(() => typia.assert(props.body));
    } catch (exp) {
      if (!typia.is<HttpError>(exp)) throw exp;
      return {
        success: false,
        status: exp.status,
        headers: exp.headers,
        data: exp.toJSON().message,
      } as any;
    }
    return random(
      "object" === typeof connection.simulate && null !== connection.simulate
        ? connection.simulate
        : undefined,
    );
  };
}

