import { tags } from "typia";

/**
 * Cart entity structure as per core requirements for persistent shopping cart.
 * Fully aligned with cart table in CartOrder schema. Atomic, immutable evidence
 * attributes ensure compliance and fluid session recovery.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type ICart = {
  /**
   * Unique identifier of the cart instance. Immutable PK.
   *
   * Prisma: cart.id.
   */
  id: string & tags.Format<"uuid">;

  /**
   * ID of the user who owns this cart. Enforces access, permission, and
   * recovery.
   *
   * Prisma: cart.user_id.
   */
  user_id: string & tags.Format<"uuid">;

  /**
   * ID of session associated with this cart. Allows anonymous/omnichannel
   * context and session recovery. Can be null for fully-identified carts.
   *
   * Prisma: cart.session_id.
   */
  session_id?: (string & tags.Format<"uuid">) | null;

  /**
   * Timestamp when cart was first created. Used for audit, session presence,
   * compliance.
   *
   * Prisma: cart.created_at.
   */
  created_at: string & tags.Format<"date-time">;

  /**
   * Timestamp for last update/activity on the cart. Key for auto-abandon,
   * analytics, evidence.
   *
   * Prisma: cart.updated_at.
   */
  updated_at: string & tags.Format<"date-time">;

  /**
   * Soft deletion timestamp for evidence, compliance, and session management.
   * Null if not deleted.
   *
   * Prisma: cart.deleted_at.
   */
  deleted_at?: (string & tags.Format<"date-time">) | null;
};
export namespace ICart {
  /**
   * Payload for creating a new persistent cart instance. Implements the
   * requirements for audit-grade, user/session-linked carts (see Intelligent
   * Cart and Order Processing Requirements). All properties map directly to
   * fields in the `cart` table. Required for new cart onboarding.
   */
  export type ICreate = {
    /**
     * The ID of the user to whom this cart belongs. Referenced from the
     * `users.id` column in the Core schema. Fulfills the requirement for
     * persistent, cross-device cart storage (see requirements sections on
     * Intelligent Cart).
     *
     * This is a required field during cart creation for authenticated
     * users, and assures direct linkage for audit trails and regulatory
     * evidence. For anonymous sessions, see `session_id`.
     */
    user_id: string & tags.Format<"uuid">;

    /**
     * The session ID associated with this cart, referenced from
     * `sessions.id` for anonymous/pre-login states. Satisfies requirements
     * for persistent, recoverable cart experience prior to authentication
     * (see system overview requirements on session cart handover).
     *
     * Optional: may be null for authenticated users creating a new cart.
     */
    session_id?: (string & tags.Format<"uuid">) | null;
  };
}

