import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ICart } from "@ORGANIZATION/PROJECT-api/lib/structures/ICart";

/**
 * 테스트 목적: 카트(Cart) 생성 엔드포인트의 필수 입력 필드 유효성 및 비즈니스 제약 검증
 *
 * 비즈니스 컨텍스트와 시나리오:
 * - 사용자가 최소 필수 정보(user_id)로 카트를 정상적으로 생성할 수 있어야 한다.
 * - session_id는 선택적으로 제공 가능하며, null 혹은 undefined를 허용함을 확인한다.
 * - 존재하지 않거나 형식이 잘못된 user_id, session_id에 대해 입력 유효성 검사를 수행해야 한다.
 * - 동일 user_id로 여러 카트 생성 요청 시 허용/불가 정책(중복 제어, 세션 정책 등)을 실제 응답으로 검증한다.
 *
 * [테스트 절차]
 * 1. 정상 입력(user_id만 포함)으로 카트 생성 → 성공 및 반환 필드 검증
 * 2. session_id가 null인 경우 생성 → 성공 및 세션 정책 검증
 * 3. session_id가 적절한 uuid 값일 경우 생성 → 성공 및 반환 필드 검증
 * 4. user_id 누락 → 400 오류 등 유효성 실패 확인 (TypeScript 수준 필수 타입이므로 별도 케이스 제외)
 * 5. user_id 값이 유효하지 않은 uuid 문자열일 경우 → 400 오류 확인
 * 6. session_id 값이 uuid 형식이 아닌 임의 스트링일 경우 → 400 오류 확인
 * 7. 동일 user_id로 2회 이상 생성 가능 여부 및 비즈니스 정책 확인
 */
export async function test_api_cartOrder_test_create_cart_with_valid_and_invalid_data(
  connection: api.IConnection,
) {
  // 1. 정상 입력(user_id만 필수)으로 카트 생성
  const userId: string = typia.random<string & tags.Format<"uuid">>();
  const cart1 = await api.functional.cartOrder.cart.post(connection, {
    body: {
      user_id: userId,
    },
  });
  typia.assert(cart1);
  TestValidator.equals("user_id 일치")(cart1.user_id)(userId);

  // 2. session_id가 null인 경우 생성
  const cart2 = await api.functional.cartOrder.cart.post(connection, {
    body: {
      user_id: userId,
      session_id: null,
    },
  });
  typia.assert(cart2);
  TestValidator.equals("user_id 일치")(cart2.user_id)(userId);
  TestValidator.equals("session_id null")(cart2.session_id)(null);

  // 3. session_id가 랜덤 uuid일 때 생성
  const randomSessionId: string = typia.random<string & tags.Format<"uuid">>();
  const cart3 = await api.functional.cartOrder.cart.post(connection, {
    body: {
      user_id: userId,
      session_id: randomSessionId,
    },
  });
  typia.assert(cart3);
  TestValidator.equals("user_id 일치")(cart3.user_id)(userId);
  TestValidator.equals("session_id 일치")(cart3.session_id)(randomSessionId);

  // 4. user_id가 잘못된 포맷인 경우 (ex. 일반 string), 400 등 오류 발생 확인
  await TestValidator.error("user_id 잘못된 uuid 포맷 오류")(() =>
    api.functional.cartOrder.cart.post(connection, {
      body: {
        user_id: "invalid-uuid-format",
      },
    })
  );

  // 5. session_id가 uuid 포맷이 아닌 경우, 400 등 오류 발생 확인
  await TestValidator.error("session_id 잘못된 포맷 오류")(() =>
    api.functional.cartOrder.cart.post(connection, {
      body: {
        user_id: userId,
        session_id: "not-a-uuid-format",
      },
    })
  );

  // 6. 동일 user_id로 재차 생성 시 정책 확인 (허용, 409, 또는 기존 레코드 반환 여부 등)
  const cartAgain = await api.functional.cartOrder.cart.post(connection, {
    body: {
      user_id: userId,
    },
  });
  typia.assert(cartAgain);
  TestValidator.equals("user_id 일치")(cartAgain.user_id)(userId);
}

