import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ICart } from "@ORGANIZATION/PROJECT-api/lib/structures/ICart";

/**
 * E2E test for updating cart metadata via PUT /cartOrder/cart/:id.
 *
 * - Validates correct update of cart fields (excluding items)
 * - Confirms audit and data persistence (updates reflected)
 * - Verifies input validation (bad formats, missing fields)
 * - Checks not-found handling for deleted/non-existent carts
 *
 * Steps:
 * 1. Create a new cart (dependency met via POST /cartOrder/cart)
 * 2. Update cart's user_id, session_id, and updated_at with valid values using PUT
 *    - Assert that returned cart reflects changes
 *    - Fetch the cart again to confirm update persisted
 * 3. Attempt to update cart using invalid user_id/session_id formats (bad UUIDs)
 *    - Expect 400 validation errors
 * 4. Attempt to update cart missing all updatable properties (empty body)
 *    - Expect 400 validation error
 * 5. Soft-delete or use a random (non-existent) cart ID then attempt update
 *    - Expect 404 not-found error
 *
 * Notes:
 * - Only cart metadata (user_id, session_id, updated_at) is updatable here; items not affected.
 * - Both success and full error paths are verified.
 */
export async function test_api_cartOrder_test_update_cart_metadata_with_valid_and_invalid_data(
  connection: api.IConnection,
) {
  // 1. Create a new cart
  const cart = await api.functional.cartOrder.cart.post(connection, {
    body: {
      user_id: typia.random<string & tags.Format<"uuid">>(),
      session_id: typia.random<string & tags.Format<"uuid">>(),
    },
  });
  typia.assert(cart);

  // 2. Update with valid new user_id, session_id, updated_at
  const updatedFieldsValid = {
    user_id: typia.random<string & tags.Format<"uuid">>(),
    session_id: typia.random<string & tags.Format<"uuid">>(),
    updated_at: new Date().toISOString() as string & tags.Format<"date-time">,
  } satisfies ICart.IUpdate;
  const updated = await api.functional.cartOrder.cart.putById(connection, {
    id: cart.id,
    body: updatedFieldsValid,
  });
  typia.assert(updated);
  TestValidator.equals("user_id")(updatedFieldsValid.user_id)(updated.user_id);
  TestValidator.equals("session_id")(updatedFieldsValid.session_id)(updated.session_id);
  TestValidator.equals("updated_at")(updatedFieldsValid.updated_at)(updated.updated_at);

  // 2b. Confirm fetch returns updated data
  // No dedicated fetch-by-id endpoint shown; if available would be used here

  // 3. Invalid user_id/session_id (bad UUIDs)
  await TestValidator.error("invalid user_id format should 400")(() =>
    api.functional.cartOrder.cart.putById(connection, {
      id: cart.id,
      body: {
        user_id: "not-a-uuid" as any, // Type violation for test, actual code should only pass strings
      },
    }),
  );
  await TestValidator.error("invalid session_id format should 400")(() =>
    api.functional.cartOrder.cart.putById(connection, {
      id: cart.id,
      body: {
        session_id: "bad-session-id" as any,
      },
    }),
  );
  await TestValidator.error("invalid updated_at format should 400")(() =>
    api.functional.cartOrder.cart.putById(connection, {
      id: cart.id,
      body: {
        updated_at: "notadate" as any,
      },
    }),
  );

  // 4. All fields missing (empty body)
  await TestValidator.error("empty body update is invalid")(() =>
    api.functional.cartOrder.cart.putById(connection, {
      id: cart.id,
      body: {}, // Empty object
    }),
  );

  // 5. Non-existent/deleted cart
  await TestValidator.error("not-found on random cart id")(() =>
    api.functional.cartOrder.cart.putById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
      body: updatedFieldsValid,
    }),
  );
}

