 * Steps:
 *   1. Create first user (A) & login.
 *   2. Create a cart as user A.
 *   3. Soft-delete the cart and confirm deleted_at.
 *   4. Try to read (or list) the deleted cart (should be inaccessible).
 *   5. Repeat deletion, confirming error/idempotency.
 *   6. Create second user (B) and login.
 *   7. As user B, attempt to delete A's cart (should be forbidden).
 */
export async function test_api_cartOrder_test_soft_delete_cart_and_permission_enforcement(
  connection: api.IConnection,
) {
  // User A context assumed in `connection`
  // 1. Create cart as user A
  const userAId = typia.random<string & tags.Format<"uuid">>();
  const cart = await api.functional.cartOrder.cart.post(connection, {
    body: {
      user_id: userAId,
