  // 4. Attempt to soft-delete again
  await TestValidator.error("repeat soft-delete errors or is idempotent")(() =>
    api.functional.cartOrder.cart.eraseById(connection, { id: cart.id })
  );

  // 5. New connection for user B
  const userBId = typia.random<string & tags.Format<"uuid">>();
