import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ICart } from "@ORGANIZATION/PROJECT-api/lib/structures/ICart";
import type { ICartItem } from "@ORGANIZATION/PROJECT-api/lib/structures/ICartItem";
import type { IPageICartItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageICartItem";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { ICartOrderCartItem } from "@ORGANIZATION/PROJECT-api/lib/structures/ICartOrderCartItem";

/**
 * E2E test for searching/listing cart items with filters and pagination.
 *
 * This test creates a cart record, then exercises the cart item listing/search
 * endpoint with various filter and pagination combinations. It validates that the
 * API returns correct filtered results, properly formatted pagination metadata,
 * correct empty responses for out-of-range or non-existent queries, and handles
 * invalid parameters as appropriate.
 *
 * Steps:
 * 1. Create a cart (dependency)
 * 2. (Synthetic) Simulate several cart items varying in fields (UUIDs, dates, etc.)
 * 3. List items filtered by cart_id; validate all returned data matches cart_id
 * 4. Filter by non-existent cart_id; expect empty results
 * 5. Filter by (potential) product_variant_id; check result
 * 6. Filter by added_after/added_before; check date-based list
 * 7. Test pagination: limit, page, crossing boundaries
 * 8. Request with no filters; expect results (if items exist)
 * 9. Use invalid page/limit values; expect correct error/handling or boundary behavior
 * 10. Confirm pagination metadata is accurate every time
 *
 * Note: If item creation endpoint is not available, steps 2/5/6/7 will simulate using random UUIDs/dates that are not present; the test will then expect empty results for filter combinations. When actual items exist, adjust test as appropriate to check concrete results.
 */
export async function test_api_cartOrder_test_list_and_search_cart_items_with_filters_and_pagination(
  connection: api.IConnection,
) {
  // Step 1: Create a cart
  const cart = await api.functional.cartOrder.cart.post(connection, {
    body: {
      user_id: typia.random<string & tags.Format<"uuid">>(),
      session_id: null,
    },
  });
  typia.assert(cart);

  // Step 2: Simulate cart item query (no real creation endpoint available):
  // We'll use filtering with the new cart's id and random product_variant_id/date ranges
  // Step 3: Query items by cart_id
  const result_by_cart = await api.functional.cartOrder.cartItem.patch(connection, {
    body: { cart_id: cart.id, page: 1, limit: 10 },
  });
  typia.assert(result_by_cart);
  // All data.cart_id in result should equal our cart.id
  TestValidator.predicate("all items match cart_id")(
    result_by_cart.data.every((item) => item.cart_id === cart.id)
  );
  // Pagination meta check
  TestValidator.equals("pagination: current page")(1)(result_by_cart.pagination.current);

  // Step 4: Filter by non-existent cart_id (expect empty)
  const result_none = await api.functional.cartOrder.cartItem.patch(connection, {
    body: { cart_id: typia.random<string & tags.Format<"uuid">>(), page: 1, limit: 10 },
  });
  typia.assert(result_none);
  TestValidator.equals("empty data on non-existent cart_id")(0)(result_none.data.length);

  // Step 5: Filter by non-existent product_variant_id (empty expected)
  const result_none_prod = await api.functional.cartOrder.cartItem.patch(connection, {
    body: { product_variant_id: typia.random<string & tags.Format<"uuid">>(), page: 1, limit: 10 },
  });
  typia.assert(result_none_prod);

  // Step 6: Filter with added_before/after set in the future/past (should be empty)
  const future = new Date(Date.now() + 1000 * 60 * 60 * 24).toISOString();
  const result_future = await api.functional.cartOrder.cartItem.patch(connection, {
    body: { cart_id: cart.id, added_after: future, page: 1, limit: 10 },
  });
  typia.assert(result_future);
  TestValidator.equals("empty data for added_after in future")(0)(result_future.data.length);

  // Step 7: Pagination boundary checks (page > 1 on likely single-page data, expect empty)
  const result_page2 = await api.functional.cartOrder.cartItem.patch(connection, {
    body: { cart_id: cart.id, page: 2, limit: 10 },
  });
  typia.assert(result_page2);
  TestValidator.equals("page 2 empty when no items")(0)(result_page2.data.length);

  // Step 8: Empty filter request (should not throw, may return empty or all user-accessible items)
  const result_no_filter = await api.functional.cartOrder.cartItem.patch(connection, {
    body: {},
  });
  typia.assert(result_no_filter);
  TestValidator.predicate("data field is array")(
    Array.isArray(result_no_filter.data)
  );
  // Step 9: Invalid limit (over max)
  await TestValidator.error("limit greater than 200 returns error")(
    async () =>
      api.functional.cartOrder.cartItem.patch(connection, {
        body: { limit: 500 },
      })
  );
  // Step 10: Pagination structure always present
  TestValidator.predicate("pagination field present")(
    typeof result_by_cart.pagination === "object" && result_by_cart.pagination !== null
  );
}

