 * 2. Add a valid item to the cart (random product variant ID, positive quantity)
 * 3. Attempt to add an item with invalid cart ID
 * 4. Attempt to add with non-existent product variant ID
 * 5. Attempt to add a duplicate item for the same product variant in the cart
 *
 * Validates persistence, response content, referential integrity, and duplicate policy enforcement.
 */
export async function test_api_cartOrder_test_add_cart_item_with_valid_invalid_data_and_duplicate_check(connection: api.IConnection) {
