  const productVariantId = typia.random<string & tags.Format<"uuid">>();
  const quantity = typia.random<number & tags.Type<"int32"> & tags.Minimum<1> & tags.Maximum<5>>();
  const cartItem = await api.functional.cartOrder.cartItem.post(connection, {
