  await TestValidator.error("adding with non-existent cart ID fails")(() =>
    api.functional.cartOrder.cartItem.post(connection, {
      body: {
        cart_id: typia.random<string & tags.Format<"uuid">>(),
        product_variant_id: typia.random<string & tags.Format<"uuid">>(),
        quantity: 2,
      },
    }),
  );

