  await TestValidator.error("존재하지 않는 cart ID로 추가 시 실패")(() =>
    api.functional.cartOrder.cartItem.post(connection, {
      body: {
        cart_id: typia.random<string & tags.Format<"uuid">>(),
        product_variant_id: typia.random<string & tags.Format<"uuid">>(),
        quantity: 2,
      },
    }),
  );

  // 4. 존재하지 않는 product variant ID로 추가(실패 예상)
  await TestValidator.error("존재하지 않는 product_variant_id로 추가 시 실패")(() =>
    api.functional.cartOrder.cartItem.post(connection, {
      body: {
        cart_id: cart.id,
        product_variant_id: typia.random<string & tags.Format<"uuid">>(),
        quantity: 2,
      },
    }),
  );

  // 5. 동일 product_variant에 중복 아이템 추가(정책상 금지, 실패 기대 또는 정책대로 동작)
  await TestValidator.error("동일 카트 내 동일 product_variant 중복 추가 시 정책 적용됨(금지/수량업데이트)")(() =>
    api.functional.cartOrder.cartItem.post(connection, {
      body: {
        cart_id: cart.id,
        product_variant_id: productVariantId,
        quantity: 1,
      },
    }),
  );
}

