import { tags } from "typia";

/**
 * Cart item entity for a user's persistent/concurrent cart. Maps all attributes
 * to the cart_item table, forming the atomic evidence and analytics point as
 * per Intelligent Cart and Order Processing requirements.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type ICartOrderCartItem = {
  /**
   * The unique primary key of this cart item record. See `cart_item.id` in
   * the schema.
   */
  id: string & tags.Format<"uuid">;

  /**
   * The cart to which this item belongs. Links to `cart.id`; fulfills audit
   * and cross-device recovery requirements.
   */
  cart_id: string & tags.Format<"uuid">;

  /**
   * The specific product variant added to the cart. Links to
   * `product_variants.id`, supporting both compliance and inventory
   * requirements.
   */
  product_variant_id: string & tags.Format<"uuid">;

  /**
   * Atomic quantity of this item in the cart. Fulfills explicit quantity
   * tracking for evidence and behavioral analytics.
   */
  quantity: number & tags.Type<"int32">;

  /**
   * The timestamp when the item was added to the cart. Implements compliance,
   * forensics, and recommendation pipeline requirements.
   */
  added_at: string & tags.Format<"date-time">;

  /**
   * The last timestamp this cart item was changed, for audit and evidence.
   * See requirements for continuous learning data capture.
   */
  updated_at: string & tags.Format<"date-time">;
};
export namespace ICartOrderCartItem {
  /**
   * Payload for adding a new cart item to the cart (atomic intent record).
   * Requires cart and variant references and intended quantity as per
   * cart_item schema and evidence compliance.
   */
  export type ICreate = {
    /**
     * Cart instance reference (`cart.id`) to which this item should be
     * added. Implements business logic for item addition in an
     * authenticated/session context.
     */
    cart_id: string & tags.Format<"uuid">;

    /**
     * Reference to the exact product variant, matching
     * `product_variants.id`. Enforces strict 3NF in evidence/data flow.
     */
    product_variant_id: string & tags.Format<"uuid">;

    /**
     * Number of units to add for this cart item. Fulfills audit, analytics,
     * and AI feedback requirements.
     */
    quantity: number & tags.Type<"int32">;
  };

  /**
   * Payload for updating a cart item (in-place intent revision). Only
   * quantity is typically mutable, as per business logic and audit
   * standards.
   */
  export type IUpdate = {
    /**
     * Optional. Updated quantity of this cart item. Evidence and compliance
     * requirement: changing intent must be audit-traceable.
     */
    quantity?: (number & tags.Type<"int32">) | null;
  };
}

