import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ICart } from "@ORGANIZATION/PROJECT-api/lib/structures/ICart";
import type { ICartOrderCartItem } from "@ORGANIZATION/PROJECT-api/lib/structures/ICartOrderCartItem";

/**
 * Test updating a cart item and parameter/validation scenarios.
 *
 * This scenario covers:
 * - Updating quantity of an existing cart item (success path)
 * - Attempting updates with invalid quantities (0, negative)
 * - Attempting update on a non-existent cart item (should 404)
 *
 * Step-by-step:
 * 1. Create a cart (valid user/session id)
 * 2. Create a cart item for that cart, using a random product_variant_id
 * 3. Update the cart item with a new valid quantity (should succeed)
 * 4. Attempt to update the cart item with 0 quantity (should fail validation)
 * 5. Attempt to update with negative quantity (should fail validation)
 * 6. Attempt to update a non-existent cart item (should 404)
 *
 * For this test: Only quantity can be updated (per DTOs).
 * If deletion is not supported directly, skip deleted cart item test.
 */
export async function test_api_cartOrder_test_update_cart_item_with_quantity_and_parameter_validation(connection: api.IConnection) {
  // 1. Create a Cart
  const cart = await api.functional.cartOrder.cart.post(connection, { body: { user_id: typia.random<string & tags.Format<"uuid">>() } });
  typia.assert(cart);

  // 2. Create a Cart Item (must use an existing cart_id and random product_variant_id)
  const productVariantId = typia.random<string & tags.Format<"uuid">>();
  const item = await api.functional.cartOrder.cartItem.post(connection, { body: { cart_id: cart.id, product_variant_id: productVariantId, quantity: 1 } });
  typia.assert(item);

  // 3. Update with valid quantity (increment)
  const newQuantity = item.quantity + 1;
  const updated = await api.functional.cartOrder.cartItem.putById(connection, { id: item.id, body: { quantity: newQuantity } });
  typia.assert(updated);
  TestValidator.equals("quantity updated")(newQuantity)(updated.quantity);

  // 4. Try update with 0 quantity (should fail)
  await TestValidator.error("should fail: zero quantity")(async () => {
    await api.functional.cartOrder.cartItem.putById(connection, { id: item.id, body: { quantity: 0 } });
  });

  // 5. Try update with negative quantity
  await TestValidator.error("should fail: negative quantity")(async () => {
    await api.functional.cartOrder.cartItem.putById(connection, { id: item.id, body: { quantity: -1 } });
  });

  // 6. Try to update a non-existent cart item (random uuid)
  await TestValidator.error("should fail: not-found cart item")(async () => {
    await api.functional.cartOrder.cartItem.putById(connection, { id: typia.random<string & tags.Format<"uuid">>(), body: { quantity: 1 } });
  });
}

