import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ICart } from "@ORGANIZATION/PROJECT-api/lib/structures/ICart";
import type { ICartOrderCartItem } from "@ORGANIZATION/PROJECT-api/lib/structures/ICartOrderCartItem";
import type { ICartOrderCartItemDeleteResult } from "@ORGANIZATION/PROJECT-api/lib/structures/ICartOrderCartItemDeleteResult";

/**
 * 테스트 목적: 장바구니 아이템 삭제 및 권한 검증
 * 
 * 시나리오 상세:
 * 1. 장바구니(카트)를 생성한다.
 * 2. 테스트에 사용할 임의의 상품(product_variant_id)을 준비한다.
 *    - product_variant_id는 실운영 환경에서는 카탈로그에서 선택하지만,
 *      이 테스트에서는 typia.random<string & tags.Format<'uuid'>>() 값 사용.
 * 3. 생성된 카트에 cart item을 추가한다.
 * 4. cart item 삭제 API를 올바른 ID로 호출하여 정상 삭제됨을 확인한다.
 *    - 응답으로 삭제된 아이템 ID와 deleted_at 등 audit 필드 확인
 *    - 같은 ID로 다시 삭제 시도 시 404 에러 또는 적절한 에러 발생
 * 5. 다른 사용자를 생성하여, 해당 사용자가 위 아이템 삭제 시도 시 권한 에러(403 등)를 검증한다.
 * 
 * 검증 단계:
 * - 삭제 성공 후, 목록 또는 카트 조회 시 아이템이 사라졌음을 별도 API로 검증 가능하다면 확인
 * - 예외 발생 시 TestValidator.error로 에러 코드 및 메시지 검증
 */
export async function test_api_cartOrder_test_delete_cart_item_and_permission_scenarios(connection: api.IConnection) {
  // 1. 본인 카트 생성
  const user_id = typia.random<string & tags.Format<'uuid'>>();
  const cart = await api.functional.cartOrder.cart.post(connection, {
    body: { user_id },
  });
  typia.assert(cart);

  // 2. product_variant_id 준비
  const product_variant_id = typia.random<string & tags.Format<'uuid'>>();

  // 3. cart item 생성
  const cartItem = await api.functional.cartOrder.cartItem.post(connection, {
    body: { cart_id: cart.id, product_variant_id, quantity: 1 },
  });
  typia.assert(cartItem);

  // 4. 정상 삭제: 올바른 cart item ID
  const delRes = await api.functional.cartOrder.cartItem.eraseById(connection, { id: cartItem.id });
  typia.assert(delRes);
  TestValidator.equals('deleted id')(cartItem.id)(delRes.id);
  TestValidator.predicate('deleted_at is iso date string')(
    !!delRes.deleted_at && !isNaN(Date.parse(delRes.deleted_at)),
  );

  // 5. 동일 ID로 재삭제 시도: 404 혹은 에러 확인
  await TestValidator.error('삭제된 아이템 재삭제 시도시 404 에러')(() =>
    api.functional.cartOrder.cartItem.eraseById(connection, { id: cartItem.id }),
  );

  // 6. 다른 계정으로 재현: (user_id 다름)
  const other_user_id = typia.random<string & tags.Format<'uuid'>>();
  const other_cart = await api.functional.cartOrder.cart.post(connection, {
    body: { user_id: other_user_id },
  });
  typia.assert(other_cart);

  const another_cartItem = await api.functional.cartOrder.cartItem.post(connection, {
    body: { cart_id: other_cart.id, product_variant_id, quantity: 1 },
  });
  typia.assert(another_cartItem);

  // 다른 유저의 cart item을 원래 user가 삭제 시도 (권한 없음, 403 등 발생해야 함)
  // 통합 인증 구조상, 각 user_id별 connection.headers 값이 달라야 실제 권한이 걸릴 수 있는 구조라면,
  // 인증 세션/토큰이 별도라면 connection 복제/토큰 변경 필요. 본 구조에서는 user_id 필드만 구분하나,
  // 필요시 여기서 인증 설정 추가.
  await TestValidator.error('다른 사용자의 아이템 삭제 시도시 403/권한 에러')(() =>
    api.functional.cartOrder.cartItem.eraseById(connection, { id: another_cartItem.id }),
  );
}

