 * This test function performs the following scenarios:
 * 1. Create a cart for a user.
 * 2. Create a random product variant id.
 * 3. Add an item to the user's cart.
 * 4. Delete the cart item with the correct id and assert success (deleted id and audit fields).
 * 5. Attempt to delete the same item again and assert that a 404 or appropriate error is thrown.
 * 6. Create a cart and cart item for a different user.
 * 7. Attempt to delete this second user's item with the original user's session, expecting a permission error.
 *
 * Note:
 * - product_variant_id uses a random uuid value since there's no real product catalog in this test environment.
 * - If real authentication is required for each user, ensure proper session/token isolation when switching users.
 * - This test expects the API to enforce proper permission checks.
 */
export async function test_api_cartOrder_test_delete_cart_item_and_permission_scenarios(connection: api.IConnection) {
  // 1. Create a cart for the first user
  const user_id = typia.random<string & tags.Format<'uuid'>>();
  const cart = await api.functional.cartOrder.cart.post(connection, {
    body: { user_id } satisfies ICart.ICreate,
  });
  typia.assert(cart);

  // 2. Generate a random product_variant_id
  const product_variant_id = typia.random<string & tags.Format<'uuid'>>();

  // 3. Add item to user's cart
  const cartItem = await api.functional.cartOrder.cartItem.post(connection, {
    body: {
      cart_id: cart.id,
      product_variant_id,
