import { tags } from "typia";

/**
 * Atomic order record entity mapped from the `order` table in CartOrder schema.
 * All fields are required by audit chains, compliance, and analytics workflows
 * per requirements analysis and Prisma schema comments. Downstream modules
 * reference this record for order-items, state transitions, and payment flows.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type ICartOrderOrder = {
  /**
   * Unique identifier for this order record. Direct reference to `order.id`
   * in the schema. Fulfills compliance chain for all downstream analytics,
   * audit, and legal trace needs.
   */
  id: string & tags.Format<"uuid">;

  /**
   * User placing this order. Foreign key from `users.id`, fulfilling
   * analytics, compliance, and lifecycle audit requirements.
   */
  user_id: string & tags.Format<"uuid">;

  /**
   * Source cart for this order. Links to `cart.id`, forming one end of the
   * evidence chain for abandoned/placed cart analytics.
   */
  cart_id: string & tags.Format<"uuid">;

  /**
   * Order creation timestamp, required for audit, compliance, and pipeline
   * requirements.
   */
  created_at: string & tags.Format<"date-time">;

  /**
   * Last change timestamp for this order entity. Required for evidence and
   * analytics pipelines. Compliance requirements on all order revisions.
   */
  updated_at: string & tags.Format<"date-time">;

  /**
   * Soft delete marker for this order. Preserves audit evidence for
   * compliance and incident forensics. Required by evidence preservation
   * requirements (see GDPR/CCPA compliance sections).
   */
  deleted_at?: (string & tags.Format<"date-time">) | null;
};
export namespace ICartOrderOrder {
  /**
   * Payload structure for creating a new order (checkout flow) in the
   * CartOrder context.
   *
   * - References all required keys (user and cart) and ensures strong
   *   normalization according to the CartOrder.order table (see comments wrt
   *   compliance/evidence).
   */
  export type ICreate = {
    /**
     * The unique identifier of the user placing the order. References
     * `users.id` in the database. This is atomic and required for
     * audit-trace compliance.
     *
     * Drawn from the CartOrder.order schema, conforms to requirements for
     * strong referential integrity and evidence preservation.
     */
    user_id: string & tags.Format<"uuid">;

    /**
     * The unique identifier of the cart used to place this order.
     * References `cart.id` in the CartOrder module for session/cart
     * consistency, enabling full evidence chains for compliance.
     *
     * Must be populated for every order creation to assure data integrity
     * and support dispute resolution.
     */
    cart_id: string & tags.Format<"uuid">;
  };

  /**
   * Object for updating certain mutable order fields, in compliance with
   * audit/evidence requirements from schema docs. Only appropriate fields
   * (timestamp, potentially notes or business attributes) are modifiable,
   * never primary or referential keys.
   *
   * Updates are evidence-logged and form part of the audit chain for the
   * CartOrder.order table.
   */
  export type IUpdate = {
    /**
     * The timestamp at which the order was last updated. Driving evidence
     * chain and required by compliance for every mutation event.
     *
     * Matches audit/evidence preservation comments in CartOrder.order.
     */
    updated_at: string & tags.Format<"date-time">;
  };
}

