/**
 * Test fetching details for a specific order item by ID as well as negative (error/access control) cases.
 * 
 * This test verifies:
 * 1. Successfully retrieving a real order item by its ID and checking all returned fields
 * 2. Attempting to fetch an order item that does not exist or is deleted returns a not-found error
 * 3. If access controls are enforced, attempt to access another user's order item as a different user and check for correct denial
 *
 * Steps:
 * 1. Create an order for User A
 * 2. Create an order item for that order
 * 3. Fetch the order item by its real ID, check response and all fields (id, order_id, product_variant_id, etc.)
 * 4. Attempt to fetch a non-existent order item ID (random uuid); expect a 404 or similar not found error
 * 5. Create (if supported) a second user, and as that user, attempt to fetch User A’s order item; expect denial/404 (if access controls apply)
 *
 * This ensures correctness of retrieval, error handling, and access enforcement.
 */
export async function test_api_cartOrder_test_get_order_item_by_valid_invalid_id_and_access_control(
  connection: api.IConnection,
) {
  // 1. Create an order for User A
  const userAId: string = typia.random<string & tags.Format<"uuid">>();
  const cartId: string = typia.random<string & tags.Format<"uuid">>();
  const order = await api.functional.cartOrder.order.post(connection, {
    body: {
