import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IOrderStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/IOrderStatus";
import type { IPageIOrderStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIOrderStatus";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * List, filter, and audit order status entries (CartOrder.order_status).
 *
 * This comprehensive test validates:
 * - Endpoint supports searching order_status records by various filters:
 *   - order_id
 *   - status_code (e.g., "pending", "paid", "shipped")
 *   - changed_at_range (array of 2 ISO8601 timestamps)
 * - Pagination fields (current, limit, records, pages) are accurate in responses.
 * - Filter logics work as intended:
 *   - Single filter (by order, by status_code, by date range)
 *   - Multiple filters combined
 *   - Filter combos that should yield no results (confirming empty page/data)
 * - System remains robust and returns correct structure even when no data matches or filters are logically contradictory.
 * - Status auditability: For a given order_id, returned statuses reflect its lifecycle transitions in timestamp sort order and are traceable by status_code and date.
 *
 * Test steps:
 * 1. Query with no filters, check paginated result and presence of meaningful entries.
 * 2. Query with one filter at a time (order_id, status_code, changed_at_range), validate all returned data matches the filter.
 * 3. Query combining filters with expected intersection (e.g., order_id + status_code).
 * 4. Query with a purposely unmatchable combo (random order_id + unlikely status_code), assert data array is empty but pagination fields still reasonable.
 * 5. For a specific order_id, fetch all statuses, check that their timestamps tell a logical progression (e.g., 'pending' < 'paid' < 'shipped') and all have required audit fields.
 * 6. Try changed_at_range with a time period where no status change occurred, confirm empty result but no errors.
 *
 * Throughout, typia.assert() is used for type validation, TestValidator for logic and business rule verification.
 */
export async function test_api_cartOrder_test_list_order_statuses_with_filters_pagination_and_auditability(
  connection: api.IConnection,
) {
  // 1. Query with no filters (fetch all)
  const allResults = await api.functional.cartOrder.orderStatus.patch(connection, {
    body: {} as IOrderStatus.IRequest,
  });
  typia.assert(allResults);
  TestValidator.predicate("pagination is valid")(allResults.pagination.current >= 1);
  TestValidator.predicate("data is array")(Array.isArray(allResults.data));

  if (allResults.data.length) {
    // Pick a random order_id/status_code/changed_at for filter tests
    const target = RandomGenerator.pick(allResults.data);
    const { order_id, status_code, changed_at } = target;

    // 2a. Filter by order_id
    const byOrder = await api.functional.cartOrder.orderStatus.patch(connection, {
      body: { order_id },
    });
    typia.assert(byOrder);
    byOrder.data.forEach((row) => TestValidator.equals("order_id match")(order_id)(row.order_id));
    // 2b. Filter by status_code
    const byStatus = await api.functional.cartOrder.orderStatus.patch(connection, {
      body: { status_code },
    });
    typia.assert(byStatus);
    byStatus.data.forEach((row) => TestValidator.equals("status_code match")(status_code)(row.status_code));
    // 2c. Filter by changed_at_range
    const byTime = await api.functional.cartOrder.orderStatus.patch(connection, {
      body: { changed_at_range: [changed_at, changed_at] },
    });
    typia.assert(byTime);
    byTime.data.forEach((row) => TestValidator.equals("changed_at match")(changed_at)(row.changed_at));

    // 3. Combined filters
    const combo = await api.functional.cartOrder.orderStatus.patch(connection, {
      body: { order_id, status_code },
    });
    typia.assert(combo);
    combo.data.forEach((row) => [
      TestValidator.equals("order_id match")(order_id)(row.order_id),
      TestValidator.equals("status_code match")(status_code)(row.status_code),
    ]);

    // 4. Unmatchable combo (random uuid + unlikely code)
    const none = await api.functional.cartOrder.orderStatus.patch(connection, {
      body: {
        order_id: typia.random<string & tags.Format<"uuid">>(),
        status_code: "___unlikely_status_code___",
      },
    });
    typia.assert(none);
    TestValidator.equals("no match data")(0)(none.data.length);
    TestValidator.predicate("pagination is present")(none.pagination !== undefined);

    // 5. Audit ordering for this order_id
    const forAudit = await api.functional.cartOrder.orderStatus.patch(connection, { body: { order_id } });
    typia.assert(forAudit);
    let lastTime = '';
    forAudit.data.forEach((row, idx) => {
      TestValidator.equals("order_id matches")(order_id)(row.order_id);
      if (lastTime) {
        TestValidator.predicate("audit timestamps nondecreasing")(row.changed_at >= lastTime);
      }
      lastTime = row.changed_at;
      TestValidator.predicate("status_code present")(typeof row.status_code === "string" && !!row.status_code);
      TestValidator.predicate("valid uuid")(!!row.id.match(/^[0-9a-f\-]{36}$/i));
    });
  }

  // 6. Empty result: time window with no status
  const farPast = new Date(1980, 0, 1).toISOString();
  const farFuture = new Date(2100, 0, 1).toISOString();
  const emptyByTime = await api.functional.cartOrder.orderStatus.patch(connection, {
    body: {
      changed_at_range: [farPast, farPast],
    },
  });
  typia.assert(emptyByTime);
  TestValidator.equals("no match data (far past)")(0)(emptyByTime.data.length);
  TestValidator.predicate("pagination present")(emptyByTime.pagination !== undefined);
}

