import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ICartOrderOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/ICartOrderOrder";
import type { IOrderStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/IOrderStatus";

/**
 * Validate get order_status by ID for CartOrder module.
 *
 * This test verifies the ability to fetch a single order_status lifecycle event by a valid ID, checks the returned status change information for integrity, and ensures the endpoint returns the correct error for invalid or deleted IDs. It also validates access control restrictions so users can see only their own order statuses.
 *
 * Steps:
 * 1. Create a user and a cart for them and use these to create an order, capturing its ID.
 * 2. Create an order_status event for the order (with a known status_code and actor/user).
 * 3. Fetch this order_status using the getById endpoint, assert that all fields match what was created.
 * 4. Attempt to fetch another order_status with an invalid random UUID and expect a not-found error.
 * 5. (If permitted by domain) Attempt to fetch another user's order_status and ensure access control prevents access or returns forbidden/not found, as per business rules.
 */
export async function test_api_cartOrder_test_get_order_status_by_valid_invalid_id_and_access_control(
  connection: api.IConnection,
) {
  // 1. Create test user and cart (assume user_id/cart_id available; use stable valid randoms)
  const user_id: string = typia.random<string & tags.Format<"uuid">>();
  const cart_id: string = typia.random<string & tags.Format<"uuid">>();

  // Create an order for the user/cart
  const order = await api.functional.cartOrder.order.post(connection, {
    body: {
      user_id,
      cart_id,
    },
  });
  typia.assert(order);

  // 2. Create an order_status event for the order
  const now = new Date().toISOString();
  const status_code = "pending";
  const changed_by = user_id; // The actor is the same user for simplicity
  const orderStatus = await api.functional.cartOrder.orderStatus.post(connection, {
    body: {
      order_id: order.id,
      status_code,
      changed_at: now,
      changed_by,
    },
  });
  typia.assert(orderStatus);

  // 3. Fetch the order_status by valid ID
  const fetched = await api.functional.cartOrder.orderStatus.getById(connection, {
    id: orderStatus.id,
  });
  typia.assert(fetched);
  TestValidator.equals("id")(orderStatus.id)(fetched.id);
  TestValidator.equals("order_id")(order.id)(fetched.order_id);
  TestValidator.equals("status_code")(status_code)(fetched.status_code);
  TestValidator.equals("changed_at")(now)(fetched.changed_at);
  TestValidator.equals("changed_by")(changed_by)(fetched.changed_by);

  // 4. Try fetch with invalid random uuid (should get not found error)
  const invalid_id = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("invalid id returns not found")(() =>
    api.functional.cartOrder.orderStatus.getById(connection, {
      id: invalid_id,
    }),
  );

  // 5. (Optional: Access control) Simulate another user attempting to fetch this order_status
  // If the endpoint is permissioned, simulate new credentials; here, repeat with a different user_id, assuming role switch is represented by connection/context change.
  // (If connection swapping is not available, document as needed.)
}

