import { tags } from "typia";

/**
 * Atomic record of a catalog evidence object.
 *
 * Implements full audit and evidence requirements for product catalog event
 * chains. Used for legal and regulatory trace throughout system. Maps to
 * catalog_evidence Prisma DB entity.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type ICatalogEvidence = {
  /**
   * Unique identifier for the evidence record. System-generated and
   * immutable.
   *
   * Prisma: catalog_evidence.id.
   */
  id: string & tags.Format<"uuid">;

  /**
   * Foreign key reference to catalog_event. Provides evidentiary context for
   * event causing/using evidence.
   *
   * Prisma: catalog_evidence.catalog_event_id.
   */
  catalog_event_id?: (string & tags.Format<"uuid">) | null;

  /**
   * URI reference to evidence object (file, hash, external source). Immutable
   * after issuance for evidence preservation.
   *
   * Prisma: catalog_evidence.reference_uri.
   */
  reference_uri: string & tags.MaxLength<80000>;

  /**
   * Atomic description of evidence (intended for audit and legal trace). Not
   * calculated.
   *
   * Prisma: catalog_evidence.description.
   */
  description: string;

  /**
   * Timestamp of evidence entry creation. Used for immutable legal chain and
   * evidence retention enforcement.
   *
   * Prisma: catalog_evidence.created_at.
   */
  created_at: string & tags.Format<"date-time">;
};

