import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ICatalogEvent } from "@ORGANIZATION/PROJECT-api/lib/structures/ICatalogEvent";
import type { IProductCatalogProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IProductCatalogProduct";
import type { IProductCatalogProductVariant } from "@ORGANIZATION/PROJECT-api/lib/structures/IProductCatalogProductVariant";
import type { IUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IUser";
import type { ICatalogEvidence } from "@ORGANIZATION/PROJECT-api/lib/structures/ICatalogEvidence";

/**
 * 테스트 목적: Catalog event(카탈로그 이벤트) 업데이트 기능 검증
 *
 * 시나리오:
 * 1. 정상적인 입력값으로 카탈로그 이벤트를 먼저 생성한 후, 일부 필드(예: description, event_type)를 수정하여 PUT 업데이트 요청을 보낸다. 응답으로 변경된 값이 정상 반영되었는지 검증한다.
 * 2. 필수 필드 누락(예: description=null, event_type=null), 혹은 잘못된 타입 등으로 업데이트 요청 시 validation 에러가 발생하는지 확인한다.
 * 3. 존재하지 않는 id로 업데이트 요청 시 404 Not Found 에러가 발생하는지 검증한다.
 *
 * 검증 포인트:
 * - 성공 케이스: 업데이트 후 description/event_type 값이 실제 변경되었음이 응답으로 확인될 것
 * - 실패 케이스: 각 필수 파라미터를 null/undefined로 넣고 validation 실패하는지, fake id로 요청 시 404 반환되는지
 */
export async function test_api_productCatalog_test_update_catalog_event_with_various_conditions(
  connection: api.IConnection,
) {
  // 1. 카탈로그 이벤트 생성 (업데이트 대상 데이터 준비)
  const eventCreateInput: ICatalogEvent.ICreate = {
    user_id: typia.random<string & tags.Format<"uuid">>(),
    event_type: "initial_event",
    description: "Initial event description.",
    occurred_at: new Date().toISOString(),
    product_id: typia.random<string & tags.Format<"uuid">>(),
    product_variant_id: null,
  };
  const createdEvent: ICatalogEvent = await api.functional.productCatalog.catalogEvents.post(connection, {
    body: eventCreateInput,
  });
  typia.assert(createdEvent);

  // 2. 정상 업데이트 - description과 event_type 수정
  const updateInput: ICatalogEvent.IUpdate = {
    description: "Updated event description.",
    event_type: "updated_event_type",
  };
  const updatedEvent: ICatalogEvent = await api.functional.productCatalog.catalogEvents.putById(connection, {
    id: createdEvent.id,
    body: updateInput,
  });
  typia.assert(updatedEvent);
  TestValidator.equals("update description")(updateInput.description)(updatedEvent.description);
  TestValidator.equals("update event_type")(updateInput.event_type)(updatedEvent.event_type);

  // 3. event_type와 description을 null로 - validation 에러 기대
  await TestValidator.error("Both fields null")(async () => {
    await api.functional.productCatalog.catalogEvents.putById(connection, {
      id: createdEvent.id,
      body: {
        description: null,
        event_type: null,
      },
    });
  });

  // 4. 존재하지 않는 id로 요청 시 404응답
  await TestValidator.error("Non-existent id returns 404")(async () => {
    await api.functional.productCatalog.catalogEvents.putById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
      body: updateInput,
    });
  });
}

