import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ICatalogEvent } from "@ORGANIZATION/PROJECT-api/lib/structures/ICatalogEvent";
import type { IProductCatalogProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IProductCatalogProduct";
import type { IProductCatalogProductVariant } from "@ORGANIZATION/PROJECT-api/lib/structures/IProductCatalogProductVariant";
import type { IUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IUser";
import type { ICatalogEvidence } from "@ORGANIZATION/PROJECT-api/lib/structures/ICatalogEvidence";

/**
 * Catalog 이벤트 레코드 업데이트 기능에 대한 종합적인 E2E 테스트
 *
 * - 정상 메타데이터 입력 시 해당 이벤트의 데이터가 올바르게 변경되는지 검증
 * - 필수 필드가 누락되거나 잘못된 입력일 때 올바른 validation 에러가 반환되는지 확인
 * - 존재하지 않는 카탈로그 이벤트 ID로 요청 시 404 Not Found 응답을 검증
 *
 * 테스트 단계:
 * 1. 새로운 catalog event를 생성하여 업데이트 대상 데이터를 준비
 * 2. 일부 필드(description, event_type)를 수정하여 정상 업데이트 작동을 확인
 * 3. description, event_type을 null로 하여 validation 에러(assertion error) 확인
 * 4. 실제 존재하지 않는 ID에 업데이트 요청하여 404 Not Found 반환되는지 확인
 */
export async function test_api_productCatalog_test_update_catalog_event_with_various_conditions(
  connection: api.IConnection,
) {
  // 1. Catalog event 생성 (정상 케이스 테스트용 데이터 준비)
  const eventCreateInput: ICatalogEvent.ICreate = {
    user_id: typia.random<string & tags.Format<"uuid">>(),
    event_type: "initial_event",
    description: "Initial event description for E2E test.",
    occurred_at: new Date().toISOString(),
    product_id: typia.random<string & tags.Format<"uuid">>(),
    product_variant_id: null,
  };
  const createdEvent: ICatalogEvent = await api.functional.productCatalog.catalogEvents.post(connection, {
    body: eventCreateInput,
  });
  typia.assert(createdEvent);

  // 2. 정상 업데이트 - description 및 event_type 필드 수정
  const updateInput: ICatalogEvent.IUpdate = {
    description: "Updated catalog event description (E2E)",
    event_type: "updated_event_type",
  };
  const updatedEvent: ICatalogEvent = await api.functional.productCatalog.catalogEvents.putById(connection, {
    id: createdEvent.id,
    body: updateInput,
  });
  typia.assert(updatedEvent);
  TestValidator.equals("description 업데이트 반영")(updateInput.description)(updatedEvent.description);
  TestValidator.equals("event_type 업데이트 반영")(updateInput.event_type)(updatedEvent.event_type);

  // 3. 필수 업데이트 필드를 null 입력 → validation 에러 기대
  await TestValidator.error("description/event_type 모두 null로 validation 에러")(
    async () => {
      await api.functional.productCatalog.catalogEvents.putById(connection, {
        id: createdEvent.id,
        body: {
          description: null,
          event_type: null,
        },
      });
    },
  );

  // 4. 존재하지 않는 id 입력 시 404 오류를 반환해야 함
