import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPaymentMethod } from "@ORGANIZATION/PROJECT-api/lib/structures/IPaymentMethod";

/**
 * E2E test for updating payment method details, covering normal and error scenarios.
 *
 * This test ensures partial update of non-sensitive, permitted fields works correctly, and that attempts to update restricted fields or non-existent records are properly rejected.
 *
 * Steps:
 * 1. Create a new payment method for a (random/test) user (dependency)
 * 2. Update one or more permitted fields (masked_detail, provider, active)
 * 3. Confirm the returned record reflects updated fields only, while immutable fields are unchanged
 * 4. Attempt to update prohibited/sensitive fields (should be ignored or cause error)
 * 5. Attempt to update using an invalid payment method ID (expect 404 error)
 */
export async function test_api_paymentsDiscounts_test_update_payment_method_with_valid_and_invalid_data(
  connection: api.IConnection,
) {
  // 1. Create payment method to update
  const createInput: IPaymentMethod.ICreate = {
    user_id: typia.random<string & tags.Format<"uuid">>(),
    type: "VISA",
    masked_detail: "**** **** **** 1234",
    provider: "Stripe",
    active: true,
  };
  const paymentMethod = await api.functional.paymentsDiscounts.paymentMethods.post(connection, {
    body: createInput,
  });
  typia.assert(paymentMethod);

  // 2. Update a permitted field (masked_detail and provider)
  const updateInput: IPaymentMethod.IUpdate = {
    masked_detail: "**** **** **** 5678",
    provider: "Toss",
    active: false,
  };
  const updated = await api.functional.paymentsDiscounts.paymentMethods.putById(connection, {
    id: paymentMethod.id,
    body: updateInput,
  });
  typia.assert(updated);
  TestValidator.equals("masked_detail updated")("**** **** **** 5678")(updated.masked_detail);
  TestValidator.equals("provider updated")("Toss")(updated.provider);
  TestValidator.equals("active updated")(false)(updated.active);
  TestValidator.equals("immutable type unchanged")(paymentMethod.type)(updated.type);
  TestValidator.equals("immutable user_id unchanged")(paymentMethod.user_id)(updated.user_id);

  // 3. Attempt to update restricted/immutable fields (should not allow changes)
  await TestValidator.error("Should not update immutable fields (type)")(() =>
    api.functional.paymentsDiscounts.paymentMethods.putById(connection, {
      id: paymentMethod.id,
      body: {
        type: "MIRAI_CARD", // not in update DTO, will be ignored by TS, so runtime fails or ignored
      } as unknown as IPaymentMethod.IUpdate,
    })
  );

  // 4. Update using invalid payment method ID (should get 404)
  await TestValidator.error("Not found on invalid payment method id")(() =>
    api.functional.paymentsDiscounts.paymentMethods.putById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
      body: updateInput,
    })
  );
}

