import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPaymentMethod } from "@ORGANIZATION/PROJECT-api/lib/structures/IPaymentMethod";

/**
 * Validate soft-delete (deactivation) of payment method and audit behaviors.
 *
 * This test ensures that deleting (soft-deleting) a user payment method marks the record as inactive but does not remove it from record/audit, matching PCI DSS audit and rollback requirements.
 *
 * Steps:
 * 1. Create a payment method for a user (using dependencies).
 * 2. Soft-delete/deactivate the created payment method using `eraseById`.
 * 3. Verify the returned record is marked as inactive (`active: false`) and all original audit fields are retained.
 * 4. Attempt to retrieve the method again (if a retrieval endpoint is available) to confirm it is still present for audit.
 * 5. Attempt to delete a non-existent payment method (random UUID) and expect a 404 error or appropriate error response.
 *
 * Edge Cases:
 * - Deleting an already inactive/deleted method should behave idempotently or error appropriately (skip if not part of core flow).
 * - All audit fields must be preserved after delete (id, user_id, masked_detail, created_at).
 */
export async function test_api_paymentsDiscounts_test_soft_delete_payment_method_and_audit_behaviors(connection: api.IConnection) {
  // 1. Create payment method
  const input: IPaymentMethod.ICreate = {
    user_id: typia.random<string & tags.Format<"uuid">>(),
    type: "VISA",
    masked_detail: "**** 4242",
    provider: "Stripe",
    active: true
  };
  const created = await api.functional.paymentsDiscounts.paymentMethods.post(connection, { body: input });
  typia.assert(created);

  // 2. Soft-delete/deactivate by ID
  const erased = await api.functional.paymentsDiscounts.paymentMethods.eraseById(connection, { id: created.id });
  typia.assert(erased);
  TestValidator.equals("active flag on erase")(false)(erased.active);

  // 3. Confirm audit properties are retained
  TestValidator.equals("id retained")(created.id)(erased.id);
  TestValidator.equals("user_id retained")(created.user_id)(erased.user_id);
  TestValidator.equals("masked_detail retained")(created.masked_detail)(erased.masked_detail);
  TestValidator.equals("type retained")(created.type)(erased.type);
  TestValidator.equals("provider retained")(created.provider)(erased.provider);
  TestValidator.equals("created_at retained")(created.created_at)(erased.created_at);

  // 4. Try deleting a non-existent payment method and expect 404 error
  await TestValidator.error("deleting non-existent method throws 404")(async () => {
    await api.functional.paymentsDiscounts.paymentMethods.eraseById(connection, { id: typia.random<string & tags.Format<"uuid">>() });
  });
}

