import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscount } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscount";
import type { IPageIDiscount } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscount";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * 할인(Discounts) 검색 및 페이징 목록 조회 테스트.
 *
 * 이 테스트는 할인 목록 API의 필터 및 페이징 동작을 검증합니다. 다양한 필드(주문, 할인정책, 금액/기간 등)로 검색 시 필터링이 정확히 동작하는지,
 * page/limit 파라미터로 페이징이 정상 반환되는지, 존재하지 않는 조건(없는 주문ID 등)으로는 빈 결과가 반환되는지 확인합니다.
 *
 * 1. 검색 및 페이징 검증 데이터(할인 3건 이상)를 사전 생성한다.
 * 2. 여러 필터(주문ID, 할인룰ID, 금액범위/시점/notes)로 리스트를 각각 필터 조회하여 각 조건에 부합하는 항목만 반환되는지 확인한다.
 * 3. page/limit으로 페이징 동작(첫페이지, 두번째페이지 등) 결과를 체크한다.
 * 4. 실제 존재하지 않는 주문ID 혹은 너무 높은 난수조건 등으로 조회하면 빈 결과 배열(data)만 반환되는지 검증한다.
 */
export async function test_api_paymentsDiscounts_test_list_search_discounts_with_filters_pagination(connection: api.IConnection) {
  // 1. 테스트 데이터: 할인 3건 이상 생성
  const discounts: IDiscount[] = [];
  for (let i = 0; i < 3; ++i) {
    const discount = await api.functional.paymentsDiscounts.discounts.post(connection, {
      body: {
        discount_rule_id: typia.random<string & tags.Format<"uuid">>(),
        order_id: typia.random<string & tags.Format<"uuid">>(),
        amount: -1000 * (i + 1),
        notes: `테스트 할인-${i + 1}`,
      } satisfies IDiscount.ICreate,
    });
    typia.assert(discount);
    discounts.push(discount);
  }

  // 2. 각 필드별 필터링 테스트 (주문ID, 할인룰ID, 금액, 시점 등)
  // 주문ID로 필터
  const byOrder = await api.functional.paymentsDiscounts.discounts.patch(connection, {
    body: {
      order_id: discounts[0].order_id,
    } satisfies IDiscount.IRequest
  });
  typia.assert(byOrder);
  TestValidator.predicate("filter by order_id는 1건 이상 반환")(byOrder.data.length > 0);
  byOrder.data.forEach(d=>TestValidator.equals("order_id 필터 일치값")(discounts[0].order_id)(d.order_id));

  // 할인룰ID로 필터
  const byRule = await api.functional.paymentsDiscounts.discounts.patch(connection, {
    body: {
      discount_rule_id: discounts[1].discount_rule_id,
    } satisfies IDiscount.IRequest,
  });
  typia.assert(byRule);
  TestValidator.predicate("filter by discount_rule_id 는 1건 이상 반환")(byRule.data.length > 0);
  byRule.data.forEach(d=>TestValidator.equals("discount_rule_id 필터 일치값")(discounts[1].discount_rule_id)(d.discount_rule_id));

  // 금액 범위 필터: amount_from/amount_to
  const byAmount = await api.functional.paymentsDiscounts.discounts.patch(connection, {
    body: {
      amount_from: -2000,
      amount_to: -999,
    } satisfies IDiscount.IRequest,
  });
  typia.assert(byAmount);
  TestValidator.predicate("amount 범위 지정 시 1건 이상")(byAmount.data.length > 0);
  byAmount.data.forEach(d=>TestValidator.predicate("amount 범위 내 값")(d.amount >= -2000 && d.amount < -999));

  // notes(텍스트) 키워드 포함 검사
  const byNotes = await api.functional.paymentsDiscounts.discounts.patch(connection, {
    body: {
      notes: "테스트 할인-2"
    } as any // 할인 notes로 검색 예시(스키마엔 없음, 실제 API 확장시 반영 필요)
  } as any);
  // 만약 notes 파라미터 미지원이면 스킵 가능

  // 3. 페이징: limit=2로 1,2page 결과가 나뉘는지
  const page1 = await api.functional.paymentsDiscounts.discounts.patch(connection, {
    body: {
      limit: 2,
      page: 1,
      sort: "applied_at:desc",
    } satisfies IDiscount.IRequest,
  });
  typia.assert(page1);
  TestValidator.equals("1페이지 최대 2건")(2)(page1.data.length);
  TestValidator.equals("pagination 구조 확인")(1)(page1.pagination.current);
  TestValidator.predicate("페이지당 최대건수 이하")(page1.data.length <= 2);

  const page2 = await api.functional.paymentsDiscounts.discounts.patch(connection, {
    body: {
      limit: 2,
      page: 2,
      sort: "applied_at:desc",
    } satisfies IDiscount.IRequest,
  });
  typia.assert(page2);
  TestValidator.equals("2페이지 current 페이지")(2)(page2.pagination.current);

  // 4. 검색조건 불일치로 빈 결과 반환(존재하지 않는 주문ID)
  const none = await api.functional.paymentsDiscounts.discounts.patch(connection, {
    body: {
      order_id: typia.random<string & tags.Format<"uuid">>(), // 실존 불가 uuid
    } satisfies IDiscount.IRequest,
  });
  typia.assert(none);
  TestValidator.equals("존재하지 않는 조건 시 empty result")(0)(none.data.length);
}

