import typia, { tags } from "typia";
import { NestiaSimulator } from "@nestia/fetcher/lib/NestiaSimulator";

import { IDiscount } from "../../../structures/IDiscount";

/**
 * Get single discount record by ID from discounts table (PaymentsDiscounts).
 *
 * This API retrieves details of a single discount record identified by its
 * unique ID. The response includes all atomic discount fields (ID, rule
 * reference, order linkage, amount, timestamps, notes), and, if applicable, any
 * linked evidence or audit entries for regulatory traceability. Security
 * validation ensures only authorized roles or the discount's originating users
 * may access. All read operations are logged for compliance, supporting
 * forensic and legal hold requirements.
 *
 * Typical use includes discount review in admin/ops dashboards, audit
 * investigation, or analytics drilldown. Related endpoints allow search/list,
 * create, update, or delete operations on discounts. Error cases include not
 * found, permission denied, or archived discounts.
 *
 * @param props.connection
 * @param props.id ID of the discount to retrieve.
 * @path /paymentsDiscounts/discounts/:id
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
