  export type Props = {
    /** ID of the discount to retrieve. */
    id: string & tags.Format<"uuid">;
  };
  export type Response = IDiscount;

  export const METADATA = {
    method: "GET",
    path: "/paymentsDiscounts/discounts/:id",
    request: null,
    response: {
      type: "application/json",
      encrypted: false,
    },
  } as const;

  export const path = (props: Props) =>
    `/paymentsDiscounts/discounts/${encodeURIComponent(props.id ?? "null")}`;
  export const random = (g?: Partial<typia.IRandomGenerator>): IDiscount =>
    typia.random<IDiscount>(g);
