import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscount } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscount";

/**
 * Discount creation (success and failure scenarios)
 *
 * This test validates the discount creation endpoint under both success and failure conditions.
 * 
 * 1. Creates a valid discount and asserts it is correctly stored, with all data matching the input.
 * 2. Attempts to create a discount missing required fields (such as amount, rule or order) and expects validation errors.
 * 3. Attempts to create a duplicate discount using the same rule and order (if uniqueness constraint applies) and expects an error.
 *
 * Steps:
 * 1. Generate random, valid discount_rule_id and order_id (simulate proper linkage - as those entities are not created here).
 * 2. Call POST /paymentsDiscounts/discounts with valid body. Assert response structure matches IDiscount, fields match input, and amount is negative or 0.
 * 3. Try to call creation API with missing required properties (one at a time: drop discount_rule_id, order_id, amount). Use TestValidator.error() to confirm rejection.
 * 4. Call API again with identical (discount_rule_id, order_id) as in #2 if business rule applies; if not, skip. If error, confirm with TestValidator.error().
 * 5. (If unique constraints do not apply, document this and explain in comments)
 */
export async function test_api_paymentsDiscounts_test_create_discount_success_and_failure_scenarios(
  connection: api.IConnection,
) {
  // 1. Generate random valid discount creation props
  const createInput: IDiscount.ICreate = {
    discount_rule_id: typia.random<string & tags.Format<"uuid">>(),
    order_id: typia.random<string & tags.Format<"uuid">>(),
    amount: -Math.abs(typia.random<number & tags.JsonSchemaPlugin<{ format: "double" }>>()),
    notes: "테스트 할인: 자동화 시나리오",
  };

  // 2. 정상 할인 생성
  const created: IDiscount = await api.functional.paymentsDiscounts.discounts.post(connection, { body: createInput });
  typia.assert(created);
  TestValidator.equals("discount_rule_id")(createInput.discount_rule_id)(created.discount_rule_id);
  TestValidator.equals("order_id")(createInput.order_id)(created.order_id);
  TestValidator.equals("amount")(createInput.amount)(created.amount);
  if (createInput.notes)
    TestValidator.equals("notes")(createInput.notes)(created.notes);

  // 3. 필수값 미기입 케이스별 validation error
  for (const [key] of Object.entries(createInput)) {
    if (key === "notes") continue;
    TestValidator.error(`missing required property: ${key}`)(async () => {
      // Spread input and delete required property one at a time
      const invalidInput = { ...createInput };
      delete invalidInput[key as keyof typeof invalidInput];
      await api.functional.paymentsDiscounts.discounts.post(connection, {
        body: invalidInput as IDiscount.ICreate,
      });
    });
  }

  // 4. (예상) 중복 할인 적용: 같은 discount_rule_id, order_id로 재시도 (유니크 제약 여부 확인)
  try {
    await api.functional.paymentsDiscounts.discounts.post(connection, { body: createInput });
    // 성공 시 (제약 없음): 코멘트 남기기
    // (Failure expected: no assertion needed if not error)
  } catch (err) {
    // 실패 시 오류 객체 확인
    TestValidator.predicate("duplicate constraint raised")(!!err);
  }
}

