import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscount } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscount";

/**
 * 할인 생성 API의 성공 및 실패 시나리오 통합 검증
 *
 * 본 테스트는 /paymentsDiscounts/discounts 엔드포인트의 할인 생성 동작을 실전 조건에서 검증합니다.
 * 1. 정상적으로 할인 레코드를 생성(성공 케이스: 모든 필수값 포함)하고, 결과를 검증합니다.
 * 2. 필수값(할인 룰/ref, 주문ref, 금액 등)이 누락된 경우 각각 validation error가 발생하는지 테스트합니다.
 * 3. 동일한 (discount_rule_id, order_id)로 재시도 시 business rule상 중복 제약이 적용되는지 확인하며, 에러가 발생하면 체크합니다.
 * (단, 중복 제약이 없는 경우, 실제 시스템 정책에 따라 주석 추가)
 *
 * [테스트 절차 요약]
 * 1. 랜덤(실제 유효 UUID 및 음수 금액)으로 할인 생성 IDiscount.ICreate 데이터 구성
 * 2. 최초 정상 생성 → 결과를 입력값과 비교/Assert
 * 3. 필수 프로퍼티별 누락 케이스별 For문 - TestValidator.error로 검증(옵셔널 notes 제외)
 * 4. 같은 값 재시도(중복) → 오류/성공 여부 주석화
 */
export async function test_api_paymentsDiscounts_test_create_discount_success_and_failure_scenarios(
  connection: api.IConnection,
) {
  // 1. 랜덤한 할인 생성 입력(필수값 모두 포함)
  const createInput: IDiscount.ICreate = {
    discount_rule_id: typia.random<string & tags.Format<"uuid">>(),
    order_id: typia.random<string & tags.Format<"uuid">>(),
    amount: -Math.abs(typia.random<number & tags.JsonSchemaPlugin<{ format: "double" }>>()),
    notes: `E2E 자동화 - ${RandomGenerator.paragraph()(2)}`,
  };

  // 2. [성공 케이스] 정상 생성 → 결과 Assert 및 입력값 비교
  const created: IDiscount = await api.functional.paymentsDiscounts.discounts.post(connection, {
    body: createInput,
  });
  typia.assert(created);
  TestValidator.equals("discount_rule_id")(createInput.discount_rule_id)(created.discount_rule_id);
  TestValidator.equals("order_id")(createInput.order_id)(created.order_id);
  TestValidator.equals("amount")(createInput.amount)(created.amount);
  TestValidator.equals("notes")(
    "notes" in createInput ? createInput.notes ?? null : null
  )(created.notes ?? null);

  // 3. [실패 케이스] 필수 필드별 누락 -> 각각 error 발생 확인(옵셔널 notes 제외)
  for (const key of ["discount_rule_id", "order_id", "amount"]) {
    TestValidator.error(`missing required property: ${key}`)(async () => {
      const invalidInput = { ...createInput };
      delete invalidInput[key as keyof typeof invalidInput];
      await api.functional.paymentsDiscounts.discounts.post(connection, {
        body: invalidInput as IDiscount.ICreate,
      });
    });
  }

  // 4. [중복 제약 테스트] 동일 (discount_rule_id, order_id)로 재생성 시도
  try {
    await api.functional.paymentsDiscounts.discounts.post(connection, {
      body: createInput,
    });
    // 성공 시(중복 허용): 정책상 제약 없음. 해당 정책은 각 서비스마다 상이할 수 있으니 참고만 함
  } catch (err) {
    // 실패(유니크 제약, 에러 발생): 해당 상황이면 에러 객체 감지 및 메시지화
    TestValidator.predicate("duplicate constraint raised")(!!err);
  }
}

