import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscount } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscount";

/**
 * 할인 정보의 필드 업데이트 검증 및 오류 처리 케이스 테스트.
 *
 * 1. 신규 할인 레코드(discount)를 생성한다. (사전의존성)
 * 2. 생성된 할인 레코드의 notes(설명) 필드를 정상적으로 업데이트 요청한다.
 *    - 성공적으로 변경됐는지 결과에서 확인한다.
 * 3. amount(할인금액) 필드를 정상적인 음수로(=수정 허용 시나리오) 수정 요청한다.
 *    - 결과 반영 및 음수 값이 반영됨을 확인한다.
 * 4. 비허용 필드(id, discount_rule_id, order_id, applied_at)에 대해 업데이트를 시도한다.
 *    - API spec상 허용되지 않은 필드 추가 시 에러(400 등)이 발생해야 한다. 이를 확인.
 * 5. 잘못된 데이터(예: amount에 양수값, notes에 너무 긴 문자열 등)를 넣어 오류 발생(400)
 *    - 오류 메시지가 비즈니스 벨리데이션 조건에 부합하는지 체크
 * 6. 존재하지 않는 discount id로 업데이트해 404(NotFound) 응답을 유도한다.
 */
export async function test_api_paymentsDiscounts_test_update_discount_field_validations_and_error_cases(
  connection: api.IConnection,
) {
  // 1. 신규 할인 레코드 생성
  const discount = await api.functional.paymentsDiscounts.discounts.post(connection, {
    body: {
      discount_rule_id: typia.random<string & tags.Format<'uuid'>>(),
      order_id: typia.random<string & tags.Format<'uuid'>>(),
      amount: -Math.abs(typia.random<number & tags.JsonSchemaPlugin<{format: 'double'}>>()),
      notes: RandomGenerator.paragraph()(20),
    } satisfies IDiscount.ICreate
  });
  typia.assert(discount);

  // 2. notes 필드 정상 수정
  const updatedNotes = 'Updated audit note '+RandomGenerator.alphabets(8);
  const res1 = await api.functional.paymentsDiscounts.discounts.putById(connection, {
    id: discount.id,
    body: {
      notes: updatedNotes
    } satisfies IDiscount.IUpdate
  });
  typia.assert(res1);
  TestValidator.equals('notes updated')(res1.notes)(updatedNotes);

  // 3. amount 필드 정상 수정 (음수값)
  const updatedAmount = -Math.abs(typia.random<number & tags.JsonSchemaPlugin<{format: 'double'}>>());
  const res2 = await api.functional.paymentsDiscounts.discounts.putById(connection, {
    id: discount.id,
    body: {
      amount: updatedAmount,
    } satisfies IDiscount.IUpdate
  });
  typia.assert(res2);
  TestValidator.equals('amount updated')(res2.amount)(updatedAmount);

  // 4. 금지 필드(id 등) 포함 시도 (타입단에서도 불가하지만 실제 API에서도 forbidden 확인 필요)
  await TestValidator.error('불가필드(id) 포함시 400')(
    async () => {
      // @ts-expect-error: 금지 필드 존재
      await api.functional.paymentsDiscounts.discounts.putById(connection, {
        id: discount.id,
        body: {
          // @ts-expect-error: 실제 타입불일치도 발생해야 하며,
          id: typia.random<string & tags.Format<'uuid'>>()
        }
      });
    }
  );

  // 5. 잘못된 데이터로 업데이트 시도 (양수, 장문 notes)
  await TestValidator.error('amount에 양수시 400')(
    async () => {
      await api.functional.paymentsDiscounts.discounts.putById(connection, {
        id: discount.id,
        body: {
          amount: Math.abs(typia.random<number & tags.JsonSchemaPlugin<{format: 'double'}>>())
        } satisfies IDiscount.IUpdate
      });
    }
  );
  await TestValidator.error('notes에 과다 긴 문자열시 400')(
    async () => {
      await api.functional.paymentsDiscounts.discounts.putById(connection, {
        id: discount.id,
        body: {
          notes: RandomGenerator.paragraph()(500)
        } satisfies IDiscount.IUpdate
      });
    }
  );

  // 6. 존재하지 않는 discount id에 대해 404 Not Found
  await TestValidator.error('없는 할인id 404')(
    async () => {
      await api.functional.paymentsDiscounts.discounts.putById(connection, {
        id: typia.random<string & tags.Format<'uuid'>>(),
        body: {
          notes: 'will not be found'
        } satisfies IDiscount.IUpdate
      });
    }
  );
}

