import { IConnection, HttpError } from "@nestia/fetcher";
import { PlainFetcher } from "@nestia/fetcher/lib/PlainFetcher";
import typia, { tags } from "typia";
import { NestiaSimulator } from "@nestia/fetcher/lib/NestiaSimulator";

import { IDiscount } from "../../../structures/IDiscount";

/**
 * Create a new discount record in discounts table, assigning to rule/order
 * (PaymentsDiscounts).
 *
 * This API creates a new discount associated with a rule and order, including
 * atomic fields such as amount, application timestamp, notes/calculation
 * rationale, and full linkage to downstream audit. The request requires input
 * validation: only eligible rules, non-empty order linkage, and non-conflicting
 * discount stacking are accepted. Upon success, the new discount is saved and
 * becomes immutable, except for compliance-audited updates.
 *
 * Security and evidence: The action is fully logged for forensic and evidence
 * purposes, with rollback or explainability enforced per business policies.
 * Errors include invalid input, rule/order reference checks, or denied
 * operation due to compliance logic. Related endpoints: GET/patch discounts,
 * rule management, and discount campaigns.
 *
 * @param props.connection
 * @param props.body Discount creation details including rule reference, order,
 *   amount, notes, and timing.
 * @path /paymentsDiscounts/discounts
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export async function post(
  connection: IConnection,
  props: post.Props,
): Promise<post.Response> {
  return !!connection.simulate
    ? post.simulate(connection, props)
    : PlainFetcher.fetch(
        {
          ...connection,
          headers: {
            ...connection.headers,
            "Content-Type": "application/json",
          },
        },
        {
          ...post.METADATA,
          path: post.path(),
          status: null,
        },
        props.body,
      );
}
export namespace post {
  export type Props = {
    /**
     * Discount creation details including rule reference, order, amount,
     * notes, and timing.
     */
    body: IDiscount.ICreate;
  };
  export type Body = IDiscount.ICreate;
  export type Response = IDiscount;

  export const METADATA = {
    method: "POST",
    path: "/paymentsDiscounts/discounts",
    request: {
      type: "application/json",
      encrypted: false,
    },
    response: {
      type: "application/json",
      encrypted: false,
    },
  } as const;

  export const path = () => "/paymentsDiscounts/discounts";
  export const random = (g?: Partial<typia.IRandomGenerator>): IDiscount =>
    typia.random<IDiscount>(g);
  export const simulate = (
    connection: IConnection,
    props: post.Props,
  ): Response => {
    const assert = NestiaSimulator.assert({
      method: METADATA.method,
      host: connection.host,
      path: post.path(),
      contentType: "application/json",
    });
    try {
      assert.body(() => typia.assert(props.body));
    } catch (exp) {
      if (!typia.is<HttpError>(exp)) throw exp;
      return {
        success: false,
        status: exp.status,
        headers: exp.headers,
        data: exp.toJSON().message,
      } as any;
    }
    return random(
      "object" === typeof connection.simulate && null !== connection.simulate
        ? connection.simulate
        : undefined,
    );
  };
}

/**
 * Soft-delete or disable a discount by ID in discounts table
 * (PaymentsDiscounts) for evidence/compliance.
 *
 * This API disables (soft-deletes) a discount record by marking it inactive or
 * otherwise not eligible for future application. The record remains available
 * for compliance review, evidence, and rollback. All deletions are logged with
 * actor identity, timestamp, and reason, supporting forensics and legal
 * inquiries.
 *
 * Deletions are rejected if the discount has already been fully applied to
 * completed business events, rolled up to refunds, or is locked for evidence
 * hold. Permission/authentication checks ensure only rightful operators may
