import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscount } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscount";

/**
 * Validate soft-delete (disable) operation for a discount by a valid ID and confirm compliance evidence
 *
 * This test ensures that a discount, once created, can be soft-deleted (disabled) such that it becomes ineligible for future application but remains present in the system for evidence/compliance requirements. The record must not be physically removed, only made inactive. This also covers cases like compliance auditing and evidentiary rollbacks.
 *
 * Steps:
 * 1. Create a new discount using a valid rule and order reference.
 * 2. Soft-delete (disable) the discount by its returned ID.
 * 3. Assert that the returned value has the same ID, and the record remains available (not null/404), likely reflecting an inactive/disabled state for traceability.
 * 4. Try to soft-delete (disable) a discount by a random non-existent UUID; assert a 404 error or expected failure is returned, confirming robust handling of invalid IDs without system crash.
 */
export async function test_api_paymentsDiscounts_test_soft_delete_discount_and_behavior_on_nonexistent_id(
  connection: api.IConnection,
) {
  // 1. Create a valid discount
  const input: IDiscount.ICreate = {
    discount_rule_id: typia.random<string & tags.Format<"uuid">>(),
    order_id: typia.random<string & tags.Format<"uuid">>(),
    amount: -Math.abs(typia.random<number>()), // Ensures amount is always negative (discount)
    notes: "TestDiscount for soft-delete validation"
  };
  const discount = await api.functional.paymentsDiscounts.discounts.post(connection, { body: input });
  typia.assert(discount);

  // 2. Soft-delete the discount by ID
  const erased = await api.functional.paymentsDiscounts.discounts.eraseById(connection, { id: discount.id });
  typia.assert(erased);
  TestValidator.equals("discount id after erase")(discount.id)(erased.id);
  // Possible further check: erased record is disabled/inactive, if such a property exists

  // 3. Attempt to erase a non-existent discount, expect 404
  const nonExistentId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("non-existent discount erase triggers 404")(
    async () => {
      await api.functional.paymentsDiscounts.discounts.eraseById(connection, { id: nonExistentId });
    }
  );
}

