import { tags } from "typia";

/**
 * Full record and evidence for each moderation action on a review. All actions
 * are immutable and traceable; rationale and timestamps are required for
 * compliance and forensic audit.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IReviewModeration = {
  /**
   * Primary key. Unique identifier for this moderation action.
   *
   * Field: review_moderations.id
   */
  id: string & tags.Format<"uuid">;

  /**
   * ID of the moderated review.
   *
   * Schema: review_moderations.review_id
   */
  review_id: string & tags.Format<"uuid">;

  /**
   * The user ID of the moderator who acted.
   *
   * Review_moderations.moderator_user_id field. Tracks the actor for
   * compliance and audit.
   */
  moderator_user_id: string & tags.Format<"uuid">;

  /**
   * Type of moderation action ('remove', 'restore', 'flag', etc.).
   *
   * 3NF: review_moderations.action_type.
   */
  action_type: string;

  /**
   * Requiring every moderation event to have an explicit written rationale.
   * Maps directly to review_moderations.rationale.
   */
  rationale: string;

  /**
   * Timestamp when the moderation action occurred.
   *
   * Field: review_moderations.created_at. Supports full audit and legal
   * chain.
   */
  created_at: string & tags.Format<"date-time">;
};
export namespace IReviewModeration {
  /**
   * Structure for creating a review moderation event. Only allowed for
   * permitted users. Written rationale and full attribution required for
   * evidence preservation.
   */
  export type ICreate = {
    /** Target review's unique ID. (review_moderations.review_id). */
    review_id: string & tags.Format<"uuid">;

    /** Moderator's user ID. (review_moderations.moderator_user_id). */
    moderator_user_id: string & tags.Format<"uuid">;

    /**
     * Moderation action type (remove, flag, restore, etc.). Atomic,
     * normalized field.
     */
    action_type: string;

    /**
     * Written rationale for moderation action.
     * review_moderations.rationale. Mandatory for all events.
     */
    rationale: string;
  };
}

