import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IReviewModeration } from "@ORGANIZATION/PROJECT-api/lib/structures/IReviewModeration";

/**
 * Validate updating rationale/notes for an existing review moderation record, and handle error scenarios for non-existent records and invalid updates.
 *
 * This test validates both successful update flows and error handling, including:
 *   1. Creating a review moderation record as a prerequisite.
 *   2. Successfully updating the rationale/notes by record ID and confirming the change persists.
 *   3. Attempting to update a moderation record that does not exist, and verifying a 404 (not found) error is thrown.
 *   4. Submitting an invalid update body (e.g., empty rationale) and confirming validation feedback is provided (e.g., 400 Bad Request or similar validation error).
 *
 * This ensures that only rationale/notes are mutable for compliance annotation and that the system enforces existence and validity constraints.
 */
export async function test_api_communicationReview_test_update_review_moderation_rationale_and_error_handling(
  connection: api.IConnection,
) {
  // 1. Create an initial review moderation record (prereq)
  const createInput: IReviewModeration.ICreate = {
    review_id: typia.random<string & tags.Format<"uuid">>(),
    moderator_user_id: typia.random<string & tags.Format<"uuid">>(),
    action_type: "remove", // Example action
    rationale: "Initial rationale for moderation."
  };
  const original = await api.functional.communicationReview.reviewModerations.post(connection, { body: createInput });
  typia.assert(original);

  // 2. Successfully update rationale/notes by ID
  const updateInput: IReviewModeration.IUpdate = { rationale: "Updated rationale for compliance." };
  const updated = await api.functional.communicationReview.reviewModerations.putById(
    connection, { id: original.id, body: updateInput }
  );
  typia.assert(updated);
  TestValidator.equals("Rationale updated")(updateInput.rationale)(updated.rationale);
  TestValidator.equals("ID unchanged")(original.id)(updated.id);

  // 3. Attempt to update a moderation that doesn't exist (random UUID)
  await TestValidator.error("404 not found for missing record")(
    () => api.functional.communicationReview.reviewModerations.putById(
      connection, {
        id: typia.random<string & tags.Format<"uuid">>(),
        body: updateInput,
      }
    )
  );

  // 4. Try an invalid update (e.g., empty rationale)
  await TestValidator.error("Validation on empty rationale")(
    () => api.functional.communicationReview.reviewModerations.putById(
      connection, {
        id: original.id,
        body: { rationale: "" }, // Likely invalid per business rules
      }
    )
  );
}

