import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IReviewModeration } from "@ORGANIZATION/PROJECT-api/lib/structures/IReviewModeration";

/**
 * Validates soft deletion of a review moderation record and robust error handling for non-existent IDs.
 *
 * Business context:
 * - Moderation records are crucial audit evidence and must not be physically deleted, only soft-deleted for compliance.
 * - Attempting to delete a non-existent moderation record should return a 404 error.
 *
 * Step-by-step process:
 * 1. Create a new moderation record (as dependency).
 * 2. Delete (soft delete) the moderation record using its ID.
 * 3. Attempt to delete the same moderation record again and verify appropriate error (already deleted or not found).
 * 4. Attempt to delete a clearly non-existent moderation record ID and verify 404 error.
 */
export async function test_api_communicationReview_test_soft_delete_review_moderation_and_nonexistent_id(
  connection: api.IConnection,
) {
  // 1. Create a new moderation record
  const createInput: IReviewModeration.ICreate = {
    review_id: typia.random<string & tags.Format<"uuid">>(),
    moderator_user_id: typia.random<string & tags.Format<"uuid">>(),
    action_type: "remove",
    rationale: "Violation of guidelines during product review."
  };
  const moderation = await api.functional.communicationReview.reviewModerations.post(connection, { body: createInput });
  typia.assert(moderation);

  // 2. Soft delete the moderation record by ID
  await api.functional.communicationReview.reviewModerations.eraseById(connection, { id: moderation.id });

  // 3. Attempt to delete the same record again (should return error)
  await TestValidator.error("Duplicate delete returns error")(() =>
    api.functional.communicationReview.reviewModerations.eraseById(connection, { id: moderation.id })
  );

  // 4. Attempt to delete using a non-existent ID (should return 404)
  const nonexistentId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("Non-existent moderation ID returns 404")(() =>
    api.functional.communicationReview.reviewModerations.eraseById(connection, { id: nonexistentId })
  );
}

