import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IReviewSentiment } from "@ORGANIZATION/PROJECT-api/lib/structures/IReviewSentiment";
import type { IPageIReviewSentiment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIReviewSentiment";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate the search and paginated retrieval of review sentiment analysis records (review_sentiments).
 *
 * This test covers the workflow of:
 * 1. Creating multiple review sentiment analysis records to serve as test data for searching and pagination scenarios.
 * 2. Querying the records with default parameters (no filter) to verify data is returned and paginated.
 * 3. Using specific filter parameters (such as review_id, ai_model_version_id, sentiment, score range, date range) to limit the results and validate correct filtering logic.
 * 4. Testing with a non-existent review_id or impossible filters to ensure an empty set is properly returned.
 * 5. Verifying correct handling of extreme pagination parameters (e.g., page exceeding last page, page=1/limit=1, and limit greater than available records).
 * 6. Ensuring that all pagination metadata (page/limit/records/pages) is accurate for various scenarios.
 *
 * Steps:
 * 1. Create N sentiment analysis records with varied field values (different review_id, model_version_id, sentiment, scores, dates).
 * 2. Perform query with no filters; verify that paginated results are returned containing these records, with correct pagination details.
 * 3. Perform query filtered for one of the created review_id values; confirm only those records are returned.
 * 4. Perform query using a sentiment value, and using score/score_min/score_max range parameters, confirming correct subset and order.
 * 5. Query with a date range that does not intersect any data – response is empty. Likewise for a random non-existent review_id.
 * 6. Test pagination (limit=1, page=N+1, etc.) for correct handling at edges and metadata.
 * 7. Assert type correctness of all responses, that data values match filters, and that error/empty conditions are handled gracefully.
 */
export async function test_api_communicationReview_test_list_review_sentiment_analysis_with_search_and_pagination(connection: api.IConnection) {
  // Step 1: Create distinct sentiment analysis records for testing search/pagination
  const SENTIMENT_VARIANTS = ["positive", "negative", "neutral"];
  const NUM_RECORDS = 5;
  const reviewIds: string[] = ArrayUtil.repeat(NUM_RECORDS)(() => typia.random<string & tags.Format<"uuid">>());
  const aiModelVersionIds: string[] = ArrayUtil.repeat(2)(() => typia.random<string & tags.Format<"uuid">>());
  const now = new Date();
  const sentimentRecords: IReviewSentiment[] = [];

  for (let i = 0; i < NUM_RECORDS; ++i) {
    const record: IReviewSentiment = await api.functional.communicationReview.reviewSentiments.post(connection, {
      body: {
        review_id: reviewIds[i],
        ai_model_version_id: aiModelVersionIds[i % aiModelVersionIds.length],
        sentiment: SENTIMENT_VARIANTS[i % SENTIMENT_VARIANTS.length],
        score: 0.5 + 0.1 * i,
        analyzed_at: new Date(now.getTime() - 86400000 * i).toISOString(),
      } satisfies IReviewSentiment.ICreate,
    });
    typia.assert(record);
    sentimentRecords.push(record);
  }

  // Step 2: Query all records with no filters
  const allResult = await api.functional.communicationReview.reviewSentiments.patch(connection, {
    body: {},
  });
  typia.assert(allResult);
  TestValidator.predicate("all records returned")(
    allResult.data.some((r) => reviewIds.includes(r.review_id)),
  );
  // Pagination metadata validation
  TestValidator.predicate("pagination fields present and valid")(
    typeof allResult.pagination.current === "number" &&
      typeof allResult.pagination.limit === "number" &&
      typeof allResult.pagination.records === "number" &&
      typeof allResult.pagination.pages === "number",
  );

  // Step 3: Filter by review_id
  const filterReviewId = reviewIds[0];
  const filterReviewResult = await api.functional.communicationReview.reviewSentiments.patch(connection, {
    body: { review_id: filterReviewId },
  });
  typia.assert(filterReviewResult);
  TestValidator.equals("only one review_id matches")(
    filterReviewResult.data.every((r) => r.review_id === filterReviewId),
    true,
  );

  // Step 4: Filter by sentiment and score range
  const sentiment = SENTIMENT_VARIANTS[1];
  const score_min = 0.5; // Expect some overlap
  const score_max = 0.8;
  const filterSentimentScoreResult = await api.functional.communicationReview.reviewSentiments.patch(connection, {
    body: { sentiment, score_min, score_max },
  });
  typia.assert(filterSentimentScoreResult);
  TestValidator.predicate("sentiment & score filter")(
    filterSentimentScoreResult.data.every((r) =>
      r.sentiment === sentiment && r.score >= score_min && r.score <= score_max),
  );

  // Step 5: Filter with impossible values (non-existent review_id)
  const impossibleReviewId = typia.random<string & tags.Format<"uuid">>();
  const impossibleResult = await api.functional.communicationReview.reviewSentiments.patch(connection, {
    body: { review_id: impossibleReviewId },
  });
  typia.assert(impossibleResult);
  TestValidator.equals("impossible filter returns empty set")(impossibleResult.data.length)(0);

  // And with a date range outside known data
  const futureDate = new Date(now.getTime() + 10 * 86400000).toISOString();
  const impossibleDateResult = await api.functional.communicationReview.reviewSentiments.patch(connection, {
    body: { analyzed_at_from: futureDate, analyzed_at_to: futureDate },
  });
  typia.assert(impossibleDateResult);
  TestValidator.equals("impossible date filter returns empty set")(impossibleDateResult.data.length)(0);

  // Step 6: Edge-case pagination params (limit=1, page > count, limit > all records)
  const pageLimit1 = await api.functional.communicationReview.reviewSentiments.patch(connection, {
    body: { limit: 1 },
  });
  typia.assert(pageLimit1);
  TestValidator.equals("limit=1 returns 1 record or less")(
    pageLimit1.data.length <= 1,
    true,
  );
  // Excessive page number
  const excessPage = await api.functional.communicationReview.reviewSentiments.patch(connection, {
    body: { page: 999, limit: 1 },
  });
  typia.assert(excessPage);
  TestValidator.equals("excessive page returns no data")(excessPage.data.length)(0);
  // Large limit
  const largeLimit = await api.functional.communicationReview.reviewSentiments.patch(connection, {
    body: { limit: 100 },
  });
  typia.assert(largeLimit);
  TestValidator.predicate("large limit returns <= all records")(
    largeLimit.data.length <= NUM_RECORDS,
  );
}

