import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IReviewSentiment } from "@ORGANIZATION/PROJECT-api/lib/structures/IReviewSentiment";

/**
 * 검증: 유효한 리뷰 감정분석 레코드를 정상적으로 조회하고, 존재하지 않는 ID로 조회 시 404 오류를 검증한다.
 * 
 * 1. /communicationReview/reviewSentiments 엔드포인트로 레코드를 1건 생성한다.
 * 2. 반환된 id로 /communicationReview/reviewSentiments/{id} GET 요청을 보내고 결과를 확인한다.
 *    - 반환 객체가 생성된 객체와 일치하는지 비즈니스 속성(예: review_id, sentiment 등)까지 검증한다.
 * 3. 임의의(랜덤) UUID(GUID) 등 존재하지 않는 id로 조회시도 시도, 404 HttpError 응답(존재하지 않음)을 확인한다.
 */
export async function test_api_communicationReview_reviewSentiments_getById(
  connection: api.IConnection,
) {
  // 1. 리뷰 감정분석 레코드 등록
  const toCreate: IReviewSentiment.ICreate = {
    review_id: typia.random<string & tags.Format<'uuid'>>(),
    ai_model_version_id: typia.random<string & tags.Format<'uuid'>>(),
    sentiment: RandomGenerator.pick(["positive", "negative", "neutral"]),
    score: Math.round(Math.random() * 2000 - 1000) / 1000, // -1 ~ 1
    analyzed_at: new Date().toISOString(),
  };
  const created = await api.functional.communicationReview.reviewSentiments.post(connection, { body: toCreate });
  typia.assert(created);

  // 2. 유효한 id로 조회
  const fetched = await api.functional.communicationReview.reviewSentiments.getById(connection, { id: created.id });
  typia.assert(fetched);
