   * sentiment analysis evidence record.
   */
  id: string & tags.Format<"uuid">;

  /**
   * Foreign key to the referenced review record.
   *
   * Reference: `review_sentiments.review_id`. Links sentiment evidence to the
   * original user review.
   */
  review_id: string & tags.Format<"uuid">;

  /**
   * Foreign key to the model version used for the sentiment analysis.
   *
