  score: number &
    tags.JsonSchemaPlugin<{
      format: "double";
    }>;

  /**
   * Timestamp when the analysis was executed.
   *
   * Reference: `review_sentiments.analyzed_at`. Evidence for audit,
   * compliance, and traceability.
   */
  analyzed_at: string & tags.Format<"date-time">;
};
export namespace IReviewSentiment {
  /**
