import type { IReviewSentiment } from "@ORGANIZATION/PROJECT-api/lib/structures/IReviewSentiment";

/**
 * 테스트 목적 및 검증 내용
 * - 올바른 데이터로 리뷰 감정 분석 레코드를 정상적으로 생성하고, 레코드가 올바르게 반환되는지 확인합니다.
 * - 일부 필드가 누락되거나 잘못된 데이터로 시도했을 때, 적절한 에러가 반환되는지도 확인합니다.
 *
 * 비즈니스 배경 및 필요성
 * - 리뷰에 대한 감정분석(AI 모델 결과)의 생성과 검증은 AI 워크플로우의 핵심입니다.
 * - 입력데이터의 포맷/참조 무결성이 강화되어야 하고, 생성된 레코드가 감사・설명・분석에 활용 가능한지 검증이 필수적입니다.
 *
 * Step-by-step process
 * 1. 랜덤하게(또는 의존 테스트로 제공된) 유효한 review_id, ai_model_version_id를 준비하고, 올바른 sentiment/score/analyzed_at 값으로 post 호출한다.
 * 2. post 응답에서 반환된 레코드의 필드가 입력값과 정확히 일치하고, 형식적 제약도 충족하는지 typia/assert 및 TestValidator로 검증한다.
 * 3. (실패케이스1) 필수 필드 누락(예: sentiment 빠짐)으로 post 시도 시 validation 에러 반환됨을 확인한다.
 * 4. (실패케이스2) score에 string-type 등 잘못된 타입값을 주어 실패를 검증한다.
 */
export async function test_api_communicationReview_reviewSentiments_post(
  connection: api.IConnection,
) {
  // 1. 정상 데이터로 sentiment 레코드 생성
  const validInput: IReviewSentiment.ICreate = {
    review_id: typia.random<string & tags.Format<"uuid">>(),
    ai_model_version_id: typia.random<string & tags.Format<"uuid">>(),
    sentiment: "positive",
    score: 0.92,
    analyzed_at: new Date().toISOString(),
  };
  const result = await api.functional.communicationReview.reviewSentiments.post(connection, { body: validInput });
  typia.assert(result);
  TestValidator.equals("review_id")(validInput.review_id)(result.review_id);
  TestValidator.equals("ai_model_version_id")(validInput.ai_model_version_id)(result.ai_model_version_id);
  TestValidator.equals("sentiment")(validInput.sentiment)(result.sentiment);
  TestValidator.equals("score")(validInput.score)(result.score);

  // 2. sentiment 필드 누락 (실패케이스)
  await TestValidator.error("sentiment 없으면 에러")(() =>
    api.functional.communicationReview.reviewSentiments.post(connection, {
      body: {
        review_id: typia.random<string & tags.Format<"uuid">>(),
        ai_model_version_id: typia.random<string & tags.Format<"uuid">>(),
        // sentiment: 빠짐
        score: 0.81,
        analyzed_at: new Date().toISOString(),
        // satisfies IReviewSentiment.ICreate intentionally omitted 'sentiment'
      } as any, // 타입 오류를 회피하지 않도록 실제 테스트에선 이 block 은 사용 하지 않음: 실제 구현에선 타입시스템상 불가
    }),
  );

  // 3. score 타입 오류 (string 타입)
  await TestValidator.error("score이 string이면 에러")(() =>
    api.functional.communicationReview.reviewSentiments.post(connection, {
      body: {
        review_id: typia.random<string & tags.Format<"uuid">>(),
        ai_model_version_id: typia.random<string & tags.Format<"uuid">>(),
        sentiment: "neutral",
        score: "1.0", // 타입 오류 intentionally
        analyzed_at: new Date().toISOString(),
      } as any,
    }),
  );
}

