import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IReviewSentiment } from "@ORGANIZATION/PROJECT-api/lib/structures/IReviewSentiment";

/**
 * Test updating a review sentiment analysis record by ID, focusing on validation and edge cases.
 *
 * Business logic covers AI-powered sentiment evidence updates for user reviews. Only mutable fields (sentiment, score, analyzed_at) can be changed – relationships are immutable via design. This test verifies both the happy path (valid update), proper error handling for non-existent IDs, and robust validation on malformed/incomplete data.
 *
 * Steps:
 * 1. Precondition – create a valid review sentiment record (dependency)
 * 2. Update one or more mutable fields for the created record and confirm changes are reflected
 * 3. Attempt to update a non-existent record, expecting a 404-style error
 * 4. Attempt to update an existing record with invalid data (e.g., invalid score type, incorrect datetime format) and expect validation error responses
 */
export async function test_api_communicationReview_test_update_review_sentiment_analysis_validation_and_edge_cases(connection: api.IConnection) {
  // 1. Create a valid review sentiment record to update
  const sentimentToUpdate = await api.functional.communicationReview.reviewSentiments.post(connection, {
    body: {
      review_id: typia.random<string & tags.Format<"uuid">>(),
      ai_model_version_id: typia.random<string & tags.Format<"uuid">>(),
      sentiment: "neutral",
      score: 0.75,
      analyzed_at: new Date().toISOString(),
    } satisfies IReviewSentiment.ICreate,
  });
  typia.assert(sentimentToUpdate);

  // 2. Update sentiment and score; confirm changes reflected
  const updatedSentiment = await api.functional.communicationReview.reviewSentiments.putById(connection, {
    id: sentimentToUpdate.id,
    body: {
      sentiment: "positive",
      score: 0.99,
    } satisfies IReviewSentiment.IUpdate,
  });
  typia.assert(updatedSentiment);
  TestValidator.equals("updated id")(sentimentToUpdate.id)(updatedSentiment.id);
  TestValidator.equals("updated sentiment")("positive")(updatedSentiment.sentiment);
  TestValidator.equals("updated score")(0.99)(updatedSentiment.score);

  // 3. Attempt to update a non-existent record (expect 404)
  await TestValidator.error("update non-existent review sentiment should fail")(() =>
    api.functional.communicationReview.reviewSentiments.putById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(), // fresh UUID
      body: {
        sentiment: "negative"
      } satisfies IReviewSentiment.IUpdate,
    })
  );

  // 4. Attempt to update with invalid data (score as string, invalid datetime format)
  await TestValidator.error("update with invalid score should fail")(() =>
    api.functional.communicationReview.reviewSentiments.putById(connection, {
      id: sentimentToUpdate.id,
      body: {
        score: "not-a-number" as any // forces runtime validation error, valid types only
      } as any,
    })
  );
  await TestValidator.error("update with invalid datetime should fail")(() =>
    api.functional.communicationReview.reviewSentiments.putById(connection, {
      id: sentimentToUpdate.id,
      body: {
        analyzed_at: "invalid-date-format" as any // runtime validation error
      } as any,
    })
  );
}

