import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ISentimentAnalysisLog } from "@ORGANIZATION/PROJECT-api/lib/structures/ISentimentAnalysisLog";
import type { IPageISentimentAnalysisLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageISentimentAnalysisLog";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * E2E test the listing/filtering/pagination for sentiment analysis logs.
 *
 * This test ensures evidence logs can be filtered and paged, and edge cases such as no matches or pagination beyond real results are handled.
 *
 * Steps:
 * 1. Create several sentiment analysis log records with various values (changing review_id, ai_model_version_id, and model_version).
 * 2. Query with no filter, limit to 2/page 1: Expect 2 logs, total/page meta valid.
 * 3. Query with filter on a specific review_id: Expect only relevant logs returned.
 * 4. Query with filter on ai_model_version_id/model_version: Expect correct subset.
 * 5. Query with input_match and time range: Expect filtered by raw_input/timestamp.
 * 6. Query with page/limit offset beyond data end: Expect empty result array, meta reflects correct last page.
 * 7. Query with extremely high limit (e.g., 2048): Should cap at reasonable max/count, not error.
 */
export async function test_api_communicationReview_test_list_search_sentiment_analysis_logs_with_filtering_pagination(
  connection: api.IConnection,
) {
  // 1. Create several diverse sentiment analysis log records
  const reviewId1 = typia.random<string & tags.Format<"uuid">>();
  const reviewId2 = typia.random<string & tags.Format<"uuid">>();
  const aiModelId1 = typia.random<string & tags.Format<"uuid">>();
  const aiModelId2 = typia.random<string & tags.Format<"uuid">>();
  const modelVersion1 = `model-${RandomGenerator.alphaNumeric(4)}`;
  const modelVersion2 = `model-${RandomGenerator.alphaNumeric(4)}`;
  const rawInputBase = RandomGenerator.paragraph()(8);
  const now = new Date();
  const isoNow = now.toISOString();
  const isoPast = new Date(now.getTime() - 1000 * 60 * 60 * 24 * 7).toISOString(); // 7 days ago

  // Each log has unique input and timestamp
  const logData = [
    {
      review_id: reviewId1,
      ai_model_version_id: aiModelId1,
      raw_input: rawInputBase,
      output: RandomGenerator.content()()(),
      model_version: modelVersion1,
      analyzed_at: isoPast,
    },
    {
      review_id: reviewId1,
      ai_model_version_id: aiModelId2,
      raw_input: rawInputBase + " keyword",
      output: RandomGenerator.content()()(),
      model_version: modelVersion2,
      analyzed_at: isoNow,
    },
    {
      review_id: reviewId2,
      ai_model_version_id: aiModelId1,
      raw_input: rawInputBase + " special",
      output: RandomGenerator.content()()(),
      model_version: modelVersion1,
      analyzed_at: isoPast,
    },
    {
      review_id: reviewId2,
      ai_model_version_id: aiModelId2,
      raw_input: rawInputBase + " token",
      output: RandomGenerator.content()()(),
      model_version: modelVersion2,
      analyzed_at: isoNow,
    },
  ];

  // Actually create the logs via API
  const createdLogs = [] as ISentimentAnalysisLog[];
  for (const item of logData) {
    const created = await api.functional.communicationReview.sentimentAnalysisLogs.post(
      connection,
      {
        body: item satisfies ISentimentAnalysisLog.ICreate,
      },
    );
    typia.assert(created);
    createdLogs.push(created);
  }

  // 2. Query with no filter, limit=2 page=1: Expect 2 logs (most recent?) and valid pagination
  let res = await api.functional.communicationReview.sentimentAnalysisLogs.patch(
    connection,
    {
      body: {
        page: 1,
        limit: 2,
      } satisfies ISentimentAnalysisLog.IRequest,
    },
  );
  typia.assert(res);
  TestValidator.equals("pagination.limit")(2)(res.pagination.limit);
  TestValidator.equals("pagination.current")(1)(res.pagination.current);
  TestValidator.predicate("paged results (<=2)")(res.data.length <= 2);

  // 3. Query by review_id: Only relevant logs
  res = await api.functional.communicationReview.sentimentAnalysisLogs.patch(
    connection,
    {
      body: {
        review_id: reviewId1,
        limit: 10,
      },
    },
  );
  typia.assert(res);
  TestValidator.predicate("all review_id match")(
    res.data.every((log) => log.review_id === reviewId1),
  );

  // 4. Query by ai_model_version_id, model_version
  res = await api.functional.communicationReview.sentimentAnalysisLogs.patch(
    connection,
    {
      body: {
        ai_model_version_id: aiModelId2,
        model_version: modelVersion2,
        limit: 10,
      },
    },
  );
  typia.assert(res);
