import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ISentimentAnalysisLog } from "@ORGANIZATION/PROJECT-api/lib/structures/ISentimentAnalysisLog";

/**
 * Validate the retrieval of a single sentiment analysis log by ID, including error handling for nonexistent IDs.
 *
 * This test confirms that the API endpoint to fetch an individual sentiment analysis log entry (by UUID) returns the correct result when queried with a valid ID, and returns a 404 error if an invalid/nonexistent ID is requested. This is critical for forensic, compliance, and explainability workflows.
 *
 * Workflow:
 * 1. Create a new sentiment analysis log entry (dependency setup).
 * 2. Fetch the log using its valid ID — verify all returned fields match the original input, and types conform to ISentimentAnalysisLog.
 * 3. Attempt fetching the log using a random (nonexistent) UUID — expect a 404 error response.
 */
export async function test_api_communicationReview_test_get_sentiment_analysis_log_by_valid_and_invalid_id(connection: api.IConnection) {
  // 1. Create a new sentiment analysis log entry (dependency)
  const createInput: ISentimentAnalysisLog.ICreate = {
    review_id: typia.random<string & tags.Format<"uuid">>(),
    ai_model_version_id: typia.random<string & tags.Format<"uuid">>(),
    raw_input: RandomGenerator.content()()(),
    output: RandomGenerator.content()()(),
    model_version: RandomGenerator.alphaNumeric(8),
    analyzed_at: new Date().toISOString() as string & tags.Format<"date-time">,
  };
  const created: ISentimentAnalysisLog = await api.functional.communicationReview.sentimentAnalysisLogs.post(connection, { body: createInput });
  typia.assert(created);

  // 2. Fetch the log by valid ID and validate response fields and types
  const fetched: ISentimentAnalysisLog = await api.functional.communicationReview.sentimentAnalysisLogs.getById(connection, { id: created.id });
  typia.assert(fetched);
  TestValidator.equals("id matches")(created.id)(fetched.id);
  TestValidator.equals("review_id matches")(createInput.review_id)(fetched.review_id);
  TestValidator.equals("ai_model_version_id matches")(createInput.ai_model_version_id)(fetched.ai_model_version_id);
  TestValidator.equals("raw_input matches")(createInput.raw_input)(fetched.raw_input);
  TestValidator.equals("output matches")(createInput.output)(fetched.output);
  TestValidator.equals("model_version matches")(createInput.model_version)(fetched.model_version);
  TestValidator.equals("analyzed_at matches")(createInput.analyzed_at)(fetched.analyzed_at);

  // 3. Fetch by invalid/nonexistent ID and expect 404 error
  await TestValidator.error("404 on nonexistent ID")(() =>
    api.functional.communicationReview.sentimentAnalysisLogs.getById(connection, { id: typia.random<string & tags.Format<"uuid">>() })
  );
}

