import { tags } from "typia";

/**
 * Complete machine evidence record of a sentiment analysis model run, as
 * required by regulatory, legal, forensic, or explainability systems.
 *
 * Derived from the sentiment_analysis_logs table. All attribute mappings and
 * documentation correspond directly to column descriptions in the Prisma schema
 * file. Non-repudiable evidence entity; all fields are atomic.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type ISentimentAnalysisLog = {
  /**
   * Primary key of sentiment analysis log entry.
   *
   * Reference: `sentiment_analysis_logs.id`. Audit, legal, explainability
   * trace evidence.
   */
  id: string & tags.Format<"uuid">;

  /**
   * Foreign key: links evidence log to reviewed item/entity.
   *
   * Reference: `sentiment_analysis_logs.review_id`.
   */
  review_id: string & tags.Format<"uuid">;

  /**
   * Foreign key: which AI model version performed this sentiment analysis
   * action.
   *
   * Reference: `sentiment_analysis_logs.ai_model_version_id` (explainability
   * evidence, not null).
   */
  ai_model_version_id: string & tags.Format<"uuid">;

  /**
   * Raw or preprocessed input delivered to the model for this inference run.
   *
   * Reference: `sentiment_analysis_logs.raw_input`. Could be JSON, text, or
   * encoded vector for full trace.
   */
  raw_input: string;

  /**
   * Model's exact output (could include label, score, or structured JSON).
   *
   * Reference: `sentiment_analysis_logs.output`. Legal, model debugging, and
   * audit output.
   */
  output: string;

  /**
   * Model version string assigned for explainability and audit.
   *
   * Reference: `sentiment_analysis_logs.model_version` (redundant for
   * traceability, optional but recommended).
   */
  model_version: string;

  /**
   * Timestamp when analysis was executed.
   *
   * Reference: `sentiment_analysis_logs.analyzed_at` (immutable timestamp for
   * regulatory chain-of-custody).
   */
  analyzed_at: string & tags.Format<"date-time">;
};
export namespace ISentimentAnalysisLog {
  /**
   * Create contract for sentiment analysis evidence log.
   *
   * Ensures strict mapping to all fields required in the
   * sentiment_analysis_logs schema. Regulatory, explainability, audit, and
   * legal review depend on this structure matching all atomic field
   * requirements. Input validation enforced for referential integrity and
   * conformance.
   */
  export type ICreate = {
    /**
     * The review which is input to the sentiment model evaluation.
     *
     * Reference: `sentiment_analysis_logs.review_id`. Required, not null.
     */
    review_id: string & tags.Format<"uuid">;

    /**
     * Version of the inference model used during analysis.
     *
     * Reference: `sentiment_analysis_logs.ai_model_version_id` (required
     * for tracking and explainability).
     */
    ai_model_version_id: string & tags.Format<"uuid">;

    /**
     * The exact input delivered to the ML workflow (serialized, encoded, or
     * raw as needed).
     *
     * Reference: `sentiment_analysis_logs.raw_input`. This field must be
     * evidence-grade for regulatory review.
     */
    raw_input: string;

    /**
     * Full output record from the AI model run (may be JSON, encoded
     * struct, or plain text).
     *
     * Reference: `sentiment_analysis_logs.output`. Required for
     * explainability and evidence.
     */
    output: string;

    /**
     * External, traceable model version string.
     *
     * Reference: `sentiment_analysis_logs.model_version`. Must match system
     * explainability and DSAR contracts.
     */
    model_version: string;

    /**
     * Timestamp of execution/evidence creation.
     *
     * Reference: `sentiment_analysis_logs.analyzed_at`. Required and
     * immutable for audit trace.
     */
    analyzed_at: string & tags.Format<"date-time">;
  };

  /**
   * Update contract for sentiment analysis machine evidence log.
   *
   * Supports regulatory, forensic, or administrative amendment under strict
   * audit trail. Permitted field updates only. Core relationships (review
   * reference, model_version PK) cannot be changed by design.
   */
  export type IUpdate = {
    /**
     * Optionally update/correct the output field after model evaluation.
     * All changes are audit-traced and must comply with evidence protocol.
     */
    output?: string;

    /**
     * Optionally correct or annotate model_version as externally visible
     * for audit/trace purposes.
     */
    model_version?: string;

    /**
     * Optionally update evidence timestamp; all changes are tracked and
     * must be justified in audit log.
     */
    analyzed_at?: string & tags.Format<"date-time">;
  };
}

