import type { ISentimentAnalysisLog } from "@ORGANIZATION/PROJECT-api/lib/structures/ISentimentAnalysisLog";

/**
 * Validate update functionality and input validation of sentiment analysis log updates.
 *
 * 1. Create a sentiment analysis log entry (dependency setup)
 * 2. Update the created log with valid fields (output, model_version, analyzed_at)
 *    - Validate the response for correct update and retained immutable fields
 * 3. Attempt to update a non-existent log ID and check for 404 or equivalent error
 * 4. Supply various invalid values for update body (bad format analyzed_at, overly short/empty model_version, non-string output) and expect error responses
 */
export async function test_api_communicationReview_sentimentAnalysisLogs_putById(
  connection: api.IConnection,
) {
  // Step 1: Create real log
  const createBody: ISentimentAnalysisLog.ICreate = {
    review_id: typia.random<string & tags.Format<"uuid">>(),
    ai_model_version_id: typia.random<string & tags.Format<"uuid">>(),
    raw_input: RandomGenerator.paragraph()(),
    output: RandomGenerator.paragraph()(),
    model_version: RandomGenerator.alphaNumeric(8),
    analyzed_at: new Date().toISOString() as string & tags.Format<"date-time">,
  };
  const log = await api.functional.communicationReview.sentimentAnalysisLogs.post(connection, { body: createBody });
  typia.assert(log);

  // Step 2: Update the log with new audit data
  const updateBody: ISentimentAnalysisLog.IUpdate = {
    output: RandomGenerator.paragraph()(),
    model_version: RandomGenerator.alphaNumeric(12),
    analyzed_at: new Date(Date.now() + 60000).toISOString() as string & tags.Format<"date-time">,
  };
  const updated = await api.functional.communicationReview.sentimentAnalysisLogs.putById(connection, {
    id: log.id,
    body: updateBody,
  });
  typia.assert(updated);
  TestValidator.equals("id after update")(log.id)(updated.id);
  TestValidator.equals("output updated")(updateBody.output)(updated.output);
  TestValidator.equals("model_version updated")(updateBody.model_version)(updated.model_version);
  TestValidator.equals("analyzed_at updated")(updateBody.analyzed_at)(updated.analyzed_at);

  // Step 3: Try updating a non-existent log (expect 404)
  await TestValidator.error("404 for missing ID")(() =>
    api.functional.communicationReview.sentimentAnalysisLogs.putById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
      body: updateBody,
    })
  );

  // Step 4: Bad-input checks
  // 4a. Bad analyzed_at
  await TestValidator.error("Invalid analyzed_at format")(() =>
    api.functional.communicationReview.sentimentAnalysisLogs.putById(connection, {
      id: log.id,
      body: {
        analyzed_at: "not-a-date",
      },
    })
  );
  // 4b. Empty model_version
  await TestValidator.error("Empty model_version")(() =>
    api.functional.communicationReview.sentimentAnalysisLogs.putById(connection, {
      id: log.id,
      body: {
        model_version: "",
      },
    })
  );
  // 4c. Numeric output (expect failure as output must be string)
  await TestValidator.error("Non-string output fails")(() =>
    api.functional.communicationReview.sentimentAnalysisLogs.putById(connection, {
      id: log.id,
      body: {
        output: 12345 as unknown as string,
      },
    })
  );
}

