import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IFavorite } from "@ORGANIZATION/PROJECT-api/lib/structures/IFavorite";
import type { IPageIFavorite } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIFavorite";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IFavoritesPersonalization } from "@ORGANIZATION/PROJECT-api/lib/structures/IFavoritesPersonalization";

/**
 * 검증: 다양한 조건(유저 ID, 상품 ID, 생성일 등)과 페이징을 활용한 좋아요(즐겨찾기) 기록 조회가 올바르게 동작하는지 검증한다.
 *
 * - 우선 테스트에 사용할 예시 유저 2명과 상품 3개를 준비한다(typia.random UUID).
 * - 각 조합(유저x상품별)로 즐겨찾기를 생성해서 총 6개의 레코드를 기록한다.
 * - 기준점이 될 생성일을 미리 저장해두고(예: 기준일 이전/이후 혹은 일부는 같은 시간), 다양한 created_at_from/to 필터 케이스를 만든다.
 *
 * 주요 검증 시나리오:
 *  1. 유저별(user_id)로 필터하여 해당 사용자의 즐겨찾기만 조회된다.
 *  2. 상품별(product_id)로 필터하여 올바른 즐겨찾기만 조회된다.
 *  3. created_at_from, created_at_to 조합으로 시간대 필터가 로그에 맞게 정상 동작함을 확인한다.
 *  4. deleted 여부를 true/false로 지정시 소프트딜리트된 결과만/혹은 미포함 결과만 필터링됨을 검증한다.
 *  5. 페이지네이션(page/limit) 조합으로 각 페이지에 기대한 레코드 개수/순서가 내려옴을 확인.
 *  6. 검색 조건이 너무 좁아(존재하지 않는 id 등) 결과가 비어 있거나 페이지 범위를 벗어난 경우 빈 결과가 내려오는 것도 확인한다.
 */
export async function test_api_favoritesPersonalization_test_list_search_favorites_with_various_filters_pagination(connection: api.IConnection) {
  // 1. 테스트용 유저 및 상품 id 생성
  const userA = typia.random<string & tags.Format<"uuid">>();
  const userB = typia.random<string & tags.Format<"uuid">>();
  const product1 = typia.random<string & tags.Format<"uuid">>();
  const product2 = typia.random<string & tags.Format<"uuid">>();
  const product3 = typia.random<string & tags.Format<"uuid">>();

  // 2. createAt용 기준시간(ISO8601, now-base)
  const now = new Date();
  const createdAtList: string[] = [
    new Date(now.getTime() - 100000).toISOString(),
    new Date(now.getTime() - 50000).toISOString(),
    new Date(now).toISOString(),
  ];

  // 3. 유저*상품 6조합으로 즐겨찾기 생성 (created_at 분산)
  const favorites = [
    { user_id: userA, product_id: product1, created_at: createdAtList[0] },
    { user_id: userA, product_id: product2, created_at: createdAtList[1] },
    { user_id: userA, product_id: product3, created_at: createdAtList[2] },
    { user_id: userB, product_id: product1, created_at: createdAtList[2] },
    { user_id: userB, product_id: product2, created_at: createdAtList[0] },
    { user_id: userB, product_id: product3, created_at: createdAtList[1] },
  ];

  // 실제 기록 반영 (favoritesPersonalization.favorites.post)
  for (const fav of favorites) {
    await api.functional.favoritesPersonalization.favorites.post(connection, {
      body: {
        user_id: fav.user_id,
        product_id: fav.product_id,
      },
    });
  }

  // 1. user_id로 필터 조회
  {
    const { data } = await api.functional.favoritesPersonalization.favorites.patch(connection, {
      body: { user_id: userA },
    });
    typia.assert(data);
    for (const fav of data) TestValidator.equals("userA") (userA) (fav.user_id);
    TestValidator.equals("userA count") (3) (data.length);
  }

  // 2. product_id로 필터 조회
  {
    const { data } = await api.functional.favoritesPersonalization.favorites.patch(connection, {
      body: { product_id: product2 },
    });
    typia.assert(data);
    for (const fav of data) TestValidator.equals("product2") (product2) (fav.product_id);
    TestValidator.equals("product2 count") (2) (data.length);
  }

  // 3. created_at_from/to
  {
    // from: 기준 생성일 바로 전, to: 기준 생성일 바로 후
    const from = createdAtList[0];
    const to = createdAtList[2];
    const { data } = await api.functional.favoritesPersonalization.favorites.patch(connection, {
      body: { created_at_from: from, created_at_to: to },
    });
    typia.assert(data);
    // from<=created_at<=to 만족하는지 체크
    for (const fav of data) {
      TestValidator.predicate("created_at 범위내") (
        fav.created_at >= from && fav.created_at <= to
      );
    }
  }

  // 4. deleted filter(soft delete)
  // 테스트 편의상 1건을 soft-delete로 가정해 deleted_at을 직접 세팅해야 하는데, 지정 불가하면 skip. (api 사용 불가 시 생략)

  // 5. 페이지네이션 (limit/page)
  {
    const { data, pagination } = await api.functional.favoritesPersonalization.favorites.patch(connection, {
      body: { limit: 2, page: 2 },
    });
    typia.assert(data);
    typia.assert(pagination);
    TestValidator.equals("limit") (2) (pagination.limit);
    TestValidator.equals("page") (2) (pagination.current);
    TestValidator.predicate("records 2개") (data.length <= 2);
  }

  // 6. 빈 결과(존재X id, page block)
  {
    const res = await api.functional.favoritesPersonalization.favorites.patch(connection, {
      body: { user_id: typia.random<string & tags.Format<"uuid">>() },
    });

    TestValidator.equals("empty") (0) (res.data.length);
  }
}

