import type { IFavoritesPersonalization } from "@ORGANIZATION/PROJECT-api/lib/structures/IFavoritesPersonalization";

/**
 * 다양한 조건(유저 ID, 상품 ID, 생성일 등)과 페이징을 활용해 즐겨찾기(좋아요) 기록 목록을 조회하는 기능의 통합 E2E 테스트
 *
 * - 두 명의 테스트 유저와 세 개의 테스트 상품을 가상 ID로 생성한다.
 * - 각 유저/상품 조합별(총 6개)로 즐겨찾기를 실제 API를 통해 생성한다.
 * - 테스트의 기준일자 배열을 정의해 created_at 필터 검증에 활용한다.
 * - 이후 다양한 필터(user_id, product_id, created_at 범위 등)와 페이징 옵션(limit/page)을 patch API로 조합별 검증한다.
 * - 없는 id 조건, 과도한 페이지네이션 등 에지케이스도 반드시 판단한다.
 * - (참고) soft-delete는 실제 API에서 deleted_at 조작이 가능해야 검증 가능. 불가 시 해당 블록은 skip.
 *
 * 검증 포인트 요약:
 *  1. user_id, product_id별 필터링 정상동작 (각 대상만 필터됨)
 *  2. created_at_from, to 범위 쿼리 정확성
 *  3. 페이지네이션(2개 per page, 2페이지 등) 옵션별 레코드 분포 적합 여부
 *  4. 존재하지 않는 id/페이지에 대해 빈 목록 반환 정상 동작
 */
export async function test_api_favoritesPersonalization_test_list_search_favorites_with_various_filters_pagination(connection: api.IConnection) {
  // 1. 테스트 유저, 상품 id 미리 생성
  const userA = typia.random<string & tags.Format<"uuid">>();
  const userB = typia.random<string & tags.Format<"uuid">>();
  const product1 = typia.random<string & tags.Format<"uuid">>();
  const product2 = typia.random<string & tags.Format<"uuid">>();
  const product3 = typia.random<string & tags.Format<"uuid">>();

  // 2. created_at 기준값(테스트 시점 분산)
  const now = new Date();
  const createdAtList: string[] = [
    new Date(now.getTime() - 100000).toISOString(),
    new Date(now.getTime() - 50000).toISOString(),
    new Date(now).toISOString(),
  ];

  // 3. 6개 즐겨찾기 조합 레코드 생성
  const favorites = [
    { user_id: userA, product_id: product1 },
    { user_id: userA, product_id: product2 },
    { user_id: userA, product_id: product3 },
    { user_id: userB, product_id: product1 },
    { user_id: userB, product_id: product2 },
    { user_id: userB, product_id: product3 },
  ];

  for (const fav of favorites) {
    await api.functional.favoritesPersonalization.favorites.post(connection, {
      body: { user_id: fav.user_id, product_id: fav.product_id },
    });
  }

  // 1. user_id 필터
  {
    const { data } = await api.functional.favoritesPersonalization.favorites.patch(connection, {
      body: { user_id: userA },
    });
    typia.assert(data);
    for (const fav of data) TestValidator.equals("userA 필터") (userA) (fav.user_id);
    TestValidator.equals("userA count") (3) (data.length);
  }

  // 2. product_id 필터
  {
    const { data } = await api.functional.favoritesPersonalization.favorites.patch(connection, {
      body: { product_id: product2 },
    });
    typia.assert(data);
    for (const fav of data) TestValidator.equals("product2 필터") (product2) (fav.product_id);
    TestValidator.equals("product2 count") (2) (data.length);
  }

  // 3. created_at_from, to
  {
    // 0~2 index를 테스트에 활용
    const from = createdAtList[0];
    const to = createdAtList[2];
    const { data } = await api.functional.favoritesPersonalization.favorites.patch(connection, {
      body: { created_at_from: from, created_at_to: to },
    });
    typia.assert(data);
    for (const fav of data) {
      TestValidator.predicate("created_at 검증") (
        fav.created_at >= from && fav.created_at <= to
      );
    }
  }

  // 4. soft-delete 확인 블록 (API에서 deleted_at 직접 설정 허용시만 테스트)
  // (deleted 플래그 true/false 케이스는 환경/권한별로 추가 구현 필요. 불가시 skip)

  // 5. 페이지네이션 (limit/page)
  {
    const { data, pagination } = await api.functional.favoritesPersonalization.favorites.patch(connection, {
      body: { limit: 2, page: 2 },
    });
    typia.assert(data);
    typia.assert(pagination);
    TestValidator.equals("limit") (2) (pagination.limit);
    TestValidator.equals("page") (2) (pagination.current);
    TestValidator.predicate("records 최대 2개") (data.length <= 2);
  }

  // 6. 없는 user_id, 과한 페이지 번호 등 빈 결과 검증
  {
    const res = await api.functional.favoritesPersonalization.favorites.patch(connection, {
      body: { user_id: typia.random<string & tags.Format<"uuid">>() },
    });
    TestValidator.equals("empty result") (0) (res.data.length);
  }
}

