import { IConnection, HttpError } from "@nestia/fetcher";
import { PlainFetcher } from "@nestia/fetcher/lib/PlainFetcher";
import typia, { tags } from "typia";
import { NestiaSimulator } from "@nestia/fetcher/lib/NestiaSimulator";

import { IFavoritesPersonalization } from "../../../structures/IFavoritesPersonalization";

/**
 * Get a favorite record by ID from favoritesPersonalization.favorites table.
 *
 * This endpoint retrieves a single favorite record, as stored in the
 * favoritesPersonalization.favorites entity. It utilizes the unique ID to fetch
 * the atomic record, including all tracked fields such as user reference,
 * product reference, createdAt, deletedAt (for soft deletion/audit), as well as
 * any auditing metadata.
 *
 * Security checks and access control are enforced at the user level; only
 * authorized users or administrators can access favorite records. Evidence
 * trails and access logs are updated to comply with audit and regulatory
 * mandates.
 *
 * Business logic ensures that attempts to fetch non-existent or deleted records
 * (where deletedAt is set) result in appropriate error responses (e.g., 404 Not
 * Found or 410 Gone).
 *
 * The endpoint is often used in conjunction with creating, updating, or listing
 * favorites, serving evidence and explainability needs for personalized
 * services and compliance tracing.
 *
 * @param props.connection
 * @param props.id Favorite record unique identifier
 * @path /favoritesPersonalization/favorites/:id
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export async function getById(
  connection: IConnection,
  props: getById.Props,
): Promise<getById.Response> {
  return !!connection.simulate
    ? getById.simulate(connection, props)
    : PlainFetcher.fetch(
        {
          ...connection,
          headers: {
            ...connection.headers,
            "Content-Type": "application/json",
          },
        },
        {
          ...getById.METADATA,
          path: getById.path(props),
          status: null,
        },
      );
}
export namespace getById {
  export type Props = {
    /** Favorite record unique identifier */
    id: string & tags.Format<"uuid">;
  };
  export type Response = IFavoritesPersonalization.IFavorite;

  export const METADATA = {
    method: "GET",
    path: "/favoritesPersonalization/favorites/:id",
    request: null,
    response: {
      type: "application/json",
      encrypted: false,
    },
  } as const;

  export const path = (props: Props) =>
    `/favoritesPersonalization/favorites/${encodeURIComponent(props.id ?? "null")}`;
  export const random = (
    g?: Partial<typia.IRandomGenerator>,
  ): IFavoritesPersonalization.IFavorite =>
    typia.random<IFavoritesPersonalization.IFavorite>(g);
  export const simulate = (
    connection: IConnection,
    props: getById.Props,
  ): Response => {
    const assert = NestiaSimulator.assert({
      method: METADATA.method,
      host: connection.host,
      path: getById.path(props),
      contentType: "application/json",
    });
    try {
      assert.param("id")(() => typia.assert(props.id));
    } catch (exp) {
      if (!typia.is<HttpError>(exp)) throw exp;
      return {
        success: false,
        status: exp.status,
        headers: exp.headers,
        data: exp.toJSON().message,
      } as any;
    }
    return random(
      "object" === typeof connection.simulate && null !== connection.simulate
        ? connection.simulate
        : undefined,
    );
  };
}

/**
 * Create a new favorite record in favoritesPersonalization.favorites table.
 *
 * This endpoint allows an authorized user to mark a product as favorite,
 * resulting in a new persistent record in the
 * favoritesPersonalization.favorites table. The operation enforces per-user
 * uniqueness on (user, product), ensuring no duplicate favorite records are
 * created.
 *
 * Audit evidence and consent checks are performed according to compliance
 * requirements before creation. The request payload includes references to the
 * target product (and optionally other metadata if allowed by business logic).
 * Upon creation, evidence trails are updated, and the full favorite record
 * (including timestamps, user, and product references) is returned.
 *
 * If a user attempts to create a duplicate favorite, the endpoint returns an
 * error indicating conflict. ACL ensures only the correct user can create
 * records in their context.
 *
 * @param props.connection
 * @param props.body Data for creating a new favorite relationship, including
 *   product reference.
 * @path /favoritesPersonalization/favorites
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export async function post(
  connection: IConnection,
  props: post.Props,
): Promise<post.Response> {
  return !!connection.simulate
    ? post.simulate(connection, props)
    : PlainFetcher.fetch(
        {
          ...connection,
          headers: {
            ...connection.headers,
            "Content-Type": "application/json",
          },
        },
        {
          ...post.METADATA,
          path: post.path(),
          status: null,
        },
        props.body,
      );
}
export namespace post {
  export type Props = {
    /**
     * Data for creating a new favorite relationship, including product
     * reference.
     */
    body: IFavoritesPersonalization.IFavoriteCreate;
  };
