import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IFavoritesPersonalization } from "@ORGANIZATION/PROJECT-api/lib/structures/IFavoritesPersonalization";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * E2E test for listing and searching bookmarks with various filters and pagination.
 *
 * This test will:
 * 1. Create several bookmarks for multiple users and products.
 * 2. List/search bookmarks by user_id - ensuring that only the relevant user's bookmarks are returned.
 * 3. List/search bookmarks by product_id - confirming only expected bookmarks (across users).
 * 4. Perform searches with custom_folder, tag, note filters to validate their searchability.
 * 5. Test pagination (limit, page) including edge case with high values.
 * 6. Test with empty search criteria (should return all bookmarks).
 * 7. Test with criteria that match nothing (should return empty list).
 *
 * At each step, assert that the data matches the expected set of bookmarks.
 */
export async function test_api_favoritesPersonalization_test_list_search_bookmarks_with_pagination_and_filters(
  connection: api.IConnection,
) {
  // 1. Create test users, products, and several bookmarks with diverse metadata.
  const user1 = typia.random<string & tags.Format<"uuid">>();
  const user2 = typia.random<string & tags.Format<"uuid">>();
  const product1 = typia.random<string & tags.Format<"uuid">>();
  const product2 = typia.random<string & tags.Format<"uuid">>();

  // Create bookmarks for different scenarios
  const bookmark1 = await api.functional.favoritesPersonalization.bookmarks.post(connection, {
    body: {
      user_id: user1,
      product_id: product1,
      custom_folder: "Work",
      tag: "urgent",
      note: "Check this for proposal"
    },
  });
  typia.assert(bookmark1);

  const bookmark2 = await api.functional.favoritesPersonalization.bookmarks.post(connection, {
    body: {
      user_id: user1,
      product_id: product2,
      custom_folder: "Personal",
      tag: "readlater",
      note: "Interesting article"
    }
  });
  typia.assert(bookmark2);

  const bookmark3 = await api.functional.favoritesPersonalization.bookmarks.post(connection, {
    body: {
      user_id: user2,
      product_id: product1,
      custom_folder: "Work",
      tag: "share",
      note: "Share with team"
    }
  });
  typia.assert(bookmark3);

  // 2. Query by user_id (user1)
  const user1List = await api.functional.favoritesPersonalization.bookmarks.patch(connection, {
    body: { user_id: user1 }
  });
  typia.assert(user1List);
  TestValidator.predicate("all user_id match user1")(user1List.data.every(b => b.user_id === user1));

  // 3. Query by product_id (product1)
  const product1List = await api.functional.favoritesPersonalization.bookmarks.patch(connection, {
    body: { product_id: product1 }
  });
  typia.assert(product1List);
  TestValidator.predicate("all product_id match product1")(product1List.data.every(b => b.product_id === product1));

  // 4. Filter by custom_folder/tag/note
  const folderList = await api.functional.favoritesPersonalization.bookmarks.patch(connection, {
    body: { custom_folder: "Work" }
  });
  typia.assert(folderList);
  TestValidator.predicate("all custom_folder is Work")(folderList.data.every(b => b.custom_folder === "Work"));

  const tagList = await api.functional.favoritesPersonalization.bookmarks.patch(connection, {
    body: { tag: "urgent" }
  });
  typia.assert(tagList);
  TestValidator.predicate("all tag is urgent")(tagList.data.every(b => b.tag === "urgent"));

  const noteList = await api.functional.favoritesPersonalization.bookmarks.patch(connection, {
    body: { note: "Interesting article" }
  });
  typia.assert(noteList);
  TestValidator.predicate("all notes match")(noteList.data.every(b => b.note === "Interesting article"));

  // 5. Test pagination: page 1, limit 1
  const paged = await api.functional.favoritesPersonalization.bookmarks.patch(connection, {
    body: { page: 1, limit: 1 }
  });
  typia.assert(paged);
  TestValidator.equals("items per page")(1)(paged.data.length);
  TestValidator.equals("current page")(1)(paged.pagination.current);
  TestValidator.equals("limit")(1)(paged.pagination.limit);

  // Edge case: high page number (no results expected)
  const emptyPage = await api.functional.favoritesPersonalization.bookmarks.patch(connection, {
    body: { page: 9999, limit: 10 }
  });
  typia.assert(emptyPage);
  TestValidator.equals("empty data on high page")([])(emptyPage.data);

  // 6. Empty criteria (should return all bookmarks)
  const allList = await api.functional.favoritesPersonalization.bookmarks.patch(connection, {
    body: {}
  });
  typia.assert(allList);
  TestValidator.predicate("returns at least all created bookmarks")(
    [bookmark1.id, bookmark2.id, bookmark3.id].every(id => allList.data.some(b => b.id === id))
  );

  // 7. Non-matching criteria
  const noMatch = await api.functional.favoritesPersonalization.bookmarks.patch(connection, {
    body: { tag: "nonexistenttag" }
  });
  typia.assert(noMatch);
  TestValidator.equals("empty array if no bookmarks match")([])(noMatch.data);
}

