import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IFavoritesPersonalization } from "@ORGANIZATION/PROJECT-api/lib/structures/IFavoritesPersonalization";

/**
 * 테스트 목적: 유효한 ID와 잘못된 ID로 즐겨찾기(bookmark) 항목 단건 조회 검증
 *
 * 비즈니스 시나리오:
 * 1. bookmark를 생성한다 (테스트에 사용할 실제 ID 확보)
 * 2. 해당 bookmark를 ID로 정상적으로 조회한다
 * 3. 조회 결과가 생성된 bookmark와 일치하는지 유형과 주요 필드값을 검증한다
 * 4. 존재하지 않는(무작위 UUID) 값을 ID로 조회를 시도하고, 404 응답 또는 적절한 오류가 발생하는지 검증한다
 */
export async function test_api_favoritesPersonalization_test_get_bookmark_by_valid_and_invalid_id(
  connection: api.IConnection,
) {
  // 1. bookmark를 생성해서 테스트에 사용할 id를 확보
  const input: IFavoritesPersonalization.IBookmarkCreate = {
    user_id: typia.random<string & tags.Format<"uuid">>(),
    product_id: typia.random<string & tags.Format<"uuid">>(),
    custom_folder: RandomGenerator.alphabets(8),
    tag: RandomGenerator.alphaNumeric(5),
    note: "API 테스트용 bookmark"
  };
  const created: IFavoritesPersonalization.IBookmark = await api.functional.favoritesPersonalization.bookmarks.post(
    connection,
    { body: input }
  );
  typia.assert(created);
  TestValidator.equals("user_id")(input.user_id)(created.user_id);
  TestValidator.equals("product_id")(input.product_id)(created.product_id);

  // 2. 생성한 bookmark ID로 정상 조회
  const found = await api.functional.favoritesPersonalization.bookmarks.getById(
    connection,
    { id: created.id }
  );
  typia.assert(found);
  TestValidator.equals("created_at")(created.created_at)(found.created_at);
  TestValidator.equals("deleted_at")(created.deleted_at ?? null)(found.deleted_at ?? null);
  TestValidator.equals("custom_folder")(input.custom_folder)(found.custom_folder);
  TestValidator.equals("tag")(input.tag)(found.tag);
  TestValidator.equals("note")(input.note)(found.note);

  // 3. 존재하지 않는 ID로 조회하여 404(또는 적절 오류) 발생 체크
  await TestValidator.error("존재하지 않는 bookmark id 조회시 404 또는 오류 발생")(
    async () => {
      await api.functional.favoritesPersonalization.bookmarks.getById(
        connection,
        { id: typia.random<string & tags.Format<"uuid">>() }
      );
    }
  );
}

