import { IConnection, HttpError } from "@nestia/fetcher";
import { PlainFetcher } from "@nestia/fetcher/lib/PlainFetcher";
import typia from "typia";
import { NestiaSimulator } from "@nestia/fetcher/lib/NestiaSimulator";

import { IFavoritesPersonalization } from "../../../structures/IFavoritesPersonalization";

/**
 * Create a new bookmark in favoritesPersonalization.bookmarks table.
 *
 * This endpoint enables users to organize products/content as bookmarks,
 * optionally assigning folders, tags, or notes. Creation enforces
 * per-user/product uniqueness—duplicate bookmarks for the same user/product are
 * not allowed.
 *
 * Audit evidence and compliance checks (e.g., consent for personalization
 * processing) precede actual creation. The result includes all bookmark fields,
 * such as custom_folder, tag, note, timestamps, and compliance audit metadata.
 * Upon conflict (duplicate), an error is returned.
 *
 * Usage is logged for downstream analytics, personalization, and compliance
 * evidence needs.
 *
 * @param props.connection
 * @param props.body Data for new user bookmark, including product,
 *   custom_folder, tag, and note.
 * @path /favoritesPersonalization/bookmarks
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export async function post(
  connection: IConnection,
  props: post.Props,
): Promise<post.Response> {
  return !!connection.simulate
    ? post.simulate(connection, props)
    : PlainFetcher.fetch(
        {
          ...connection,
          headers: {
            ...connection.headers,
            "Content-Type": "application/json",
          },
        },
        {
          ...post.METADATA,
          path: post.path(),
          status: null,
        },
        props.body,
      );
}
export namespace post {
  export type Props = {
    /**
     * Data for new user bookmark, including product, custom_folder, tag,
     * and note.
     */
    body: IFavoritesPersonalization.IBookmarkCreate;
  };
  export type Body = IFavoritesPersonalization.IBookmarkCreate;
  export type Response = IFavoritesPersonalization.IBookmark;

  export const METADATA = {
    method: "POST",
    path: "/favoritesPersonalization/bookmarks",
    request: {
      type: "application/json",
      encrypted: false,
    },
    response: {
      type: "application/json",
      encrypted: false,
    },
  } as const;

  export const path = () => "/favoritesPersonalization/bookmarks";
  export const random = (
    g?: Partial<typia.IRandomGenerator>,
  ): IFavoritesPersonalization.IBookmark =>
    typia.random<IFavoritesPersonalization.IBookmark>(g);
  export const simulate = (
    connection: IConnection,
    props: post.Props,
  ): Response => {
    const assert = NestiaSimulator.assert({
      method: METADATA.method,
      host: connection.host,
      path: post.path(),
      contentType: "application/json",
    });
    try {
      assert.body(() => typia.assert(props.body));
    } catch (exp) {
      if (!typia.is<HttpError>(exp)) throw exp;
      return {
        success: false,
        status: exp.status,
        headers: exp.headers,
        data: exp.toJSON().message,
      } as any;
    }
    return random(
      "object" === typeof connection.simulate && null !== connection.simulate
        ? connection.simulate
        : undefined,
    );
  };
}

