import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IFavoritesPersonalization } from "@ORGANIZATION/PROJECT-api/lib/structures/IFavoritesPersonalization";

/**
 * Test creation of a personal bookmark for a product with input validation.
 *
 * This test ensures that a user can successfully create a product bookmark and that the bookmark persists.
 * It also ensures that attempts to create a bookmark with missing required fields or with invalid datatypes are rejected with validation errors.
 *
 * Steps:
 * 1. Create a bookmark for a (fake) user and product using valid uuid values, custom_folder, tag, and note.
 * 2. Assert that the API response contains the expected fields and correct values.
 * 3. Attempt to create a bookmark with a missing required field (e.g., omit product_id); assert a validation error is thrown.
 * 4. Attempt to create a bookmark with an invalid datatype (e.g., set product_id to an invalid string that is not a uuid); assert a validation error is thrown.
 * 5. (Optional) Test uniqueness: attempt to create a second identical bookmark for the same user/product and expect an error (if the system enforces per-user/product uniqueness).
 */
export async function test_api_favoritesPersonalization_test_create_bookmark_with_valid_and_invalid_data(
  connection: api.IConnection,
) {
  // 1. Create a valid bookmark
  const validUserId = typia.random<string & tags.Format<"uuid">>();
  const validProductId = typia.random<string & tags.Format<"uuid">>();
  const createInput: IFavoritesPersonalization.IBookmarkCreate = {
    user_id: validUserId,
    product_id: validProductId,
    custom_folder: "Spring Wishlist",
    tag: "garden",
    note: "For my garden project",
  };
  const bookmark = await api.functional.favoritesPersonalization.bookmarks.post(connection, { body: createInput });
  typia.assert(bookmark);
  TestValidator.equals("user_id matches")(validUserId)(bookmark.user_id);
  TestValidator.equals("product_id matches")(validProductId)(bookmark.product_id);

  // 2. Attempt missing required field
  await TestValidator.error("missing product_id causes error")(() =>
    api.functional.favoritesPersonalization.bookmarks.post(connection, {
      body: {
        user_id: validUserId,
        // product_id: intentionally omitted
        custom_folder: "Test Folder",
        tag: "failcase",
        note: "Should fail due to missing product_id",
      } as unknown as IFavoritesPersonalization.IBookmarkCreate,
    })
  );

  // 3. Invalid datatype for product_id
  await TestValidator.error("invalid product_id type causes error")(() =>
    api.functional.favoritesPersonalization.bookmarks.post(connection, {
      body: {
        user_id: validUserId,
        product_id: "not-a-uuid-format" as any,
        custom_folder: null,
        tag: null,
        note: null,
      } as unknown as IFavoritesPersonalization.IBookmarkCreate,
    })
  );

  // 4. Uniqueness: try to create the same bookmark again
  await TestValidator.error("duplicate bookmark should fail")(() =>
    api.functional.favoritesPersonalization.bookmarks.post(connection, {
      body: createInput,
    })
  );
}

