import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IFavoritesPersonalization } from "@ORGANIZATION/PROJECT-api/lib/structures/IFavoritesPersonalization";

/**
 * E2E test for updating an existing bookmark with both valid and invalid data.
 * 
 * This test ensures that bookmarks — in the FavoritesPersonalization domain — can be updated successfully with new valid parameters, and that the system properly rejects updates with invalid IDs or payloads. This involves creating a bookmark, updating its allowed fields (like folder, tag, and note), verifying the update, and covering error scenarios.
 * 
 * Test workflow steps:
 * 1. Create a bookmark as a test fixture using valid user/product.
 * 2. Update the bookmark with a valid payload (change folder, tag, note).
 * 3. Retrieve and assert that the updated values persist.
 * 4. Attempt to update using a random non-existent ID — expect a not-found error.
 * 5. Attempt to update with an invalid payload (illegal field, or type violation) — expect a validation error.
 */
export async function test_api_favoritesPersonalization_test_update_bookmark_with_valid_and_invalid_data(connection: api.IConnection) {
  // 1. Create a test bookmark
  const bookmarkCreate: IFavoritesPersonalization.IBookmarkCreate = {
    user_id: typia.random<string & tags.Format<"uuid">>(),
    product_id: typia.random<string & tags.Format<"uuid">>(),
    custom_folder: "wishlist",
    tag: "test-tag",
    note: "Test note for updating",
  };
  const created = await api.functional.favoritesPersonalization.bookmarks.post(connection, { body: bookmarkCreate });
  typia.assert(created);

  // 2. Update fields on the bookmark
  const updatePayload: IFavoritesPersonalization.IBookmarkUpdate = {
    custom_folder: "updated-list",
    note: "Updated note",
    tag: "updated-tag",
    // not setting deleted_at for this test
  };
  const updated = await api.functional.favoritesPersonalization.bookmarks.putById(connection, { id: created.id, body: updatePayload });
  typia.assert(updated);
  TestValidator.equals("custom_folder")(updatePayload.custom_folder)(updated.custom_folder);
  TestValidator.equals("tag")(updatePayload.tag)(updated.tag);
  TestValidator.equals("note")(updatePayload.note)(updated.note);

  // 3. Validation: updated values persist in returned record
  TestValidator.equals("id matches")(created.id)(updated.id);
  TestValidator.equals("user_id matches")(created.user_id)(updated.user_id);
  TestValidator.equals("product_id matches")(created.product_id)(updated.product_id);

  // 4. Attempt to update with a non-existent/random bookmark ID
  await TestValidator.error("Not found: update with random ID")(() =>
    api.functional.favoritesPersonalization.bookmarks.putById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(), // intentionally using an unknown ID
      body: updatePayload,
    })
  );

  // 5. Attempt to update with an invalid payload (type invalid tag value)
  await TestValidator.error("Validation error: update with illegal field value")(() =>
    api.functional.favoritesPersonalization.bookmarks.putById(connection, {
      id: created.id,
      body: { tag: 123 as any }, // forcibly breaking type to test API validation
    })
  );
}

