/**
 * Validate the retrieval of an AI feature store record by both valid and invalid (non-existent) IDs.
 *
 * Business Context:
 * This test ensures the feature store retrieval endpoint returns accurate, complete data for a real feature set, including all audit/metadata fields, and robustly handles the case where a requested ID does not exist by returning a compliant error response.
 *
 * Test Steps:
 * 1. Create a new AI feature store record using POST /advancedAI/aiFeatureStore with valid, random data.
 * 2. Retrieve that feature store record by its ID using GET /advancedAI/aiFeatureStore/{id}.
 * 3. Validate that all expected fields (id, ai_model_version_id, ai_training_data_id, name, description, schema, created_at) are present and have expected types/values. Compare response to what was created.
 * 4. Attempt to retrieve a feature store record by a random but non-existent UUID (not used in step 1).
 * 5. Validate that the API returns a not found error (e.g., 404 or compliant error structure).
 */
export async function test_api_advancedAI_test_get_ai_feature_store_by_valid_and_invalid_id(connection: api.IConnection) {
  // Step 1: Create a new AI feature store record
  const createInput: IAIFeatureStore.ICreate = {
    ai_model_version_id: typia.random<string & tags.Format<"uuid">>(),
    ai_training_data_id: typia.random<string & tags.Format<"uuid">>(),
