 * Validate creation of a new AI feature store record with correct data.
 *
 * This test ensures that the AI feature store registry API accepts a fully valid record payload,
 * responds with a correctly structured IAIFeatureStore result,
 * and that business-relevant fields are echoed or properly composed.
 * The function verifies field integrity and that the record can be reliably used in downstream flows.
 *
 * 1. Build a valid IAIFeatureStore.ICreate input (with referential model version ID, unique name, schema, optional fields).
 * 2. POST to /advancedAI/aiFeatureStore endpoint.
 * 3. Assert response structure: id (uuid), name, ai_model_version_id, schema, created_at (date-time), and optional fields.
 * 4. Compare critical fields from input to output to confirm accuracy.
 */
export async function test_api_advancedAI_test_create_ai_feature_store_with_valid_and_invalid_data(
  connection: api.IConnection,
) {
  // 1. Build a valid AI feature store creation input
  const input: IAIFeatureStore.ICreate = {
    ai_model_version_id: typia.random<string & tags.Format<"uuid">>(),
    ai_training_data_id: typia.random<string & tags.Format<"uuid">>(),
    name: RandomGenerator.alphaNumeric(8),
    description: RandomGenerator.paragraph()(),
    schema: '{"type":"object","properties":{"featureA":{"type":"number"}}}',
  };

  // 2. POST to create feature store record
  const featureStore = await api.functional.advancedAI.aiFeatureStore.post(connection, { body: input });

  // 3. Assert the response matches expected IAIFeatureStore structure
  typia.assert(featureStore);
  TestValidator.equals("name")(input.name)(featureStore.name);
  TestValidator.equals("ai_model_version_id")(input.ai_model_version_id)(featureStore.ai_model_version_id);
  TestValidator.equals("schema")(input.schema)(featureStore.schema);
  // If input description provided, match; else output can be null
  if (input.description !== undefined) {
    TestValidator.equals("description")(input.description)(featureStore.description);
  }
  if (input.ai_training_data_id !== undefined) {
    TestValidator.equals("ai_training_data_id")(input.ai_training_data_id)(featureStore.ai_training_data_id);
  }
  // 4. Validate format for id and created_at
  if (!/^\w{8}(-\w{4}){3}-\w{12}$/.test(featureStore.id)) {
    throw new Error("Returned id is not in UUID format");
  }
  if (isNaN(Date.parse(featureStore.created_at))) {
    throw new Error("Returned created_at is not a valid ISO date-time string");
  }
}

