import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAIFeatureStore } from "@ORGANIZATION/PROJECT-api/lib/structures/IAIFeatureStore";

/**
 * Test updating an AI feature store record (PUT /advancedAI/aiFeatureStore/{id}) with valid and invalid data.
 *
 * This test verifies both successful update flows and correct error handling for invalid operations.
 *
 * Steps:
 * 1. Create an initial AI feature store record to serve as the update target using POST /advancedAI/aiFeatureStore.
 * 2. Update the record with valid changes (alter name, description, and schema), verify the response matches the new data and the ID remains the same.
 * 3. Attempt to update with an invalid (non-existent) ID and check for proper error response.
 * 4. Attempt to update with invalid data formats (e.g., pass a malformed schema), ensure an error is thrown.
 * 5. Retrieve the feature store by the updated ID and confirm all persisted changes are reflected.
 */
export async function test_api_advancedAI_test_update_ai_feature_store_with_valid_and_invalid_data(
  connection: api.IConnection,
) {
  // 1. Create a new AI feature store record
  const initial: IAIFeatureStore = await api.functional.advancedAI.aiFeatureStore.post(connection, {
    body: {
      ai_model_version_id: typia.random<string & tags.Format<"uuid">>(),
      ai_training_data_id: typia.random<string & tags.Format<"uuid">>(),
      name: "Initial Feature Set",
      description: "Original feature set for testing update.",
      schema: '{"features": ["f1", "f2"]}',
    } satisfies IAIFeatureStore.ICreate,
  });
  typia.assert(initial);

  // 2. Update the record with valid data
  const updatedFields: IAIFeatureStore.IUpdate = {
    name: "Updated Feature Set",
    description: "Updated feature set for testing PUT.",
    schema: '{"features": ["f1", "f2", "f3"]}',
  };
  const updated: IAIFeatureStore = await api.functional.advancedAI.aiFeatureStore.putById(connection, {
    id: initial.id,
    body: updatedFields,
  });
  typia.assert(updated);
  TestValidator.equals("id")(initial.id)(updated.id);
  TestValidator.equals("name")(updatedFields.name)(updated.name);
  TestValidator.equals("description")(updatedFields.description)(updated.description);
  TestValidator.equals("schema")(updatedFields.schema)(updated.schema);

  // 3. Attempt to update using a non-existent ID
  await TestValidator.error("update with invalid id should fail")(async () => {
    await api.functional.advancedAI.aiFeatureStore.putById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
      body: updatedFields,
    });
  });

  // 4. Attempt to update with invalid schema format (simulate schema parse failure)
  await TestValidator.error("update with invalid schema format should fail")(async () => {
    await api.functional.advancedAI.aiFeatureStore.putById(connection, {
      id: initial.id,
      body: {
        schema: '{not a valid json}',
      },
    });
  });

  // 5. Fetch the updated feature store record to confirm changes
  // (Assume there is a "getById" or similar endpoint, or skip if not available.)
  // If not implemented, we already relied on the update response for correctness.
}

