import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAIFeatureStore } from "@ORGANIZATION/PROJECT-api/lib/structures/IAIFeatureStore";
import type { IOperationResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IOperationResult";

/**
 * E2E test for deletion of AI feature store entries via ID, covering success & error conditions.
 *
 * Business context:
 * - AI feature store entries are critical for audit, explainability, and compliance.
 * - Deletion is soft (audit preserved), must not allow phantom delete or cascade violations.
 * - Test both correct deletion and idempotent/error handling for already-deleted or invalid IDs.
 *
 * Steps:
 * 1. Create a new AI feature store record (to guarantee a valid test subject).
 * 2. Delete it using its ID.
 * 3. Assert deletion reports success, and after deletion, it cannot be found (future search/list API not implemented—so we’ll focus on result).
 * 4. Attempt to delete again (same ID) – should produce either an error, or (preferably) a success=false idempotency report.
 * 5. Attempt to delete using an invalid (nonexistent and well-formed UUID) ID – must report correct error.
 */
export async function test_api_advancedAI_test_delete_ai_feature_store_by_valid_and_invalid_id(
  connection: api.IConnection,
) {
  // 1. Create a valid AI feature store entry
  const feature: IAIFeatureStore = await api.functional.advancedAI.aiFeatureStore.post(connection, {
    body: {
      ai_model_version_id: typia.random<string & tags.Format<"uuid">>(),
      ai_training_data_id: null,
      name: RandomGenerator.alphaNumeric(12),
      description: RandomGenerator.paragraph()(),
      schema: JSON.stringify({ fields: [RandomGenerator.name()] }),
    } satisfies IAIFeatureStore.ICreate,
  });
  typia.assert(feature);

  // 2. Delete the entry by valid ID
  const deleted: IOperationResult = await api.functional.advancedAI.aiFeatureStore.eraseById(connection, {
    id: feature.id,
  });
  typia.assert(deleted);
  TestValidator.equals("deletion succeeded")(true)(deleted.success);

  // 3. Attempt to delete again (should be idempotent or error, not succeed again)
  const deletedAgain: IOperationResult = await api.functional.advancedAI.aiFeatureStore.eraseById(connection, {
    id: feature.id,
  });
  typia.assert(deletedAgain);
  TestValidator.equals("repeat delete should not succeed")(false)(deletedAgain.success);

  // 4. Attempt with invalid (well-formed but nonexistent) ID
  const invalidId = typia.random<string & tags.Format<"uuid">>();
  // (Guarantee it's not the same as our valid one)
  if (invalidId === feature.id) throw new Error("Generated invalidId collides with actual id");
  const resultInvalid: IOperationResult = await api.functional.advancedAI.aiFeatureStore.eraseById(connection, {
    id: invalidId,
  });
  typia.assert(resultInvalid);
  TestValidator.equals("deletion for invalid id should fail")(false)(resultInvalid.success);
}

