import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAIDecisionLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IAIDecisionLog";
import type { IPageIAIDecisionLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIAIDecisionLog";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * E2E test for listing and searching AI decision log entries with various filters and pagination.
 *
 * This test validates that the AI decision log search endpoint correctly supports a wide variety
 * of filters, returns paginated results, and properly handles edge cases (such as filters that
 * return empty results).
 *
 * Process:
 * 1. Create several AI decision log entries with distinct attributes (model version, entity, decision, etc)
 * 2. List all decision logs, confirm all created entries are present
 * 3. Search by model version, target entity, target user, and decision type
 * 4. Search with pagination: page 1 and 2, validate returned data and total count
 * 5. Apply filters that should match zero entries and confirm result is empty list
 * 6. Assert that responses match expected format and data integrity is preserved
 */
export async function test_api_advancedAI_test_list_ai_decision_logs_with_various_filters(
  connection: api.IConnection,
) {
  // 1. Create several diverse decision log entries
  const modelVersionA = typia.random<string & tags.Format<"uuid">>();
  const modelVersionB = typia.random<string & tags.Format<"uuid">>();
  const targetUser = typia.random<string & tags.Format<"uuid">>();
  const targetEntity = "order";
  const targetEntity2 = "product";
  const rationaleSearch = "Human readable rationale - Pagination Test";
  const timestampBase = new Date(Date.now() - 1000 * 60 * 5).toISOString(); // 5 mins ago

  // First entry: modelVersionA, user, entity 'order', decision 'approve'
  const logA = await api.functional.advancedAI.aiDecisionLogs.post(connection, {
    body: {
      ai_model_version_id: modelVersionA,
      target_user_id: targetUser,
      target_entity: targetEntity,
      target_entity_id: typia.random<string & tags.Format<"uuid">>(),
      decision: "approve",
      input_snapshot: RandomGenerator.paragraph()(),
      rationale: rationaleSearch,
    } satisfies IAIDecisionLog.ICreate,
  });
  typia.assert(logA);

  // Second entry: modelVersionA, other user, entity 'product', decision 'block'
  const logB = await api.functional.advancedAI.aiDecisionLogs.post(connection, {
    body: {
      ai_model_version_id: modelVersionA,
      target_user_id: typia.random<string & tags.Format<"uuid">>(),
      target_entity: targetEntity2,
      target_entity_id: typia.random<string & tags.Format<"uuid">>(),
      decision: "block",
      input_snapshot: RandomGenerator.paragraph()(),
      rationale: null,
    } satisfies IAIDecisionLog.ICreate,
  });
  typia.assert(logB);

  // Third entry: modelVersionB, no user, entity 'order', decision 'review'
  const logC = await api.functional.advancedAI.aiDecisionLogs.post(connection, {
    body: {
      ai_model_version_id: modelVersionB,
      target_user_id: null,
      target_entity: targetEntity,
      target_entity_id: typia.random<string & tags.Format<"uuid">>(),
      decision: "review",
      input_snapshot: RandomGenerator.paragraph()(),
      rationale: "Second rationale for review entry",
    } satisfies IAIDecisionLog.ICreate,
  });
  typia.assert(logC);

  // 2. List all decision logs (no filter) -- should include above entries
  const allLogs = await api.functional.advancedAI.aiDecisionLogs.patch(connection, {
    body: {} satisfies IAIDecisionLog.IRequest,
  });
  typia.assert(allLogs);
