import { tags } from "typia";

/**
 * AI decision log record documenting a single model inference, automated
 * output, or business rule fired by an AI.
 *
 * Draws directly from ai_decision_logs table as described in Prisma schema and
 * requirements.
 *
 * Records model version, target entity/user, result/rationale, input snapshot,
 * and full evidence attributes to support regulatory compliance, forensic
 * audit, explainability, and ML optimization.
 *
 * Evidence preservation is paramount; this object is returned in detail views
 * and paged results, and acts as a canonical log for explainability requests.
 *
 * Properties mirror the source DB schema and include compliance-oriented
 * documentation for each field.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IAIDecisionLog = {
  /**
   * Unique identifier for this decision log record.
   *
   * Maps to ai_decision_logs.id (UUID). Canonical reference for audit,
   * evidence, or model feedback trace.
   */
  id: string & tags.Format<"uuid">;

  /**
   * The model version ID (ai_model_versions.id) used for inference.
   *
   * Drawn from the foreign key in ai_decision_logs; supports model
   * governance, explainability, and tracking of drift/version changes.
   */
  ai_model_version_id: string & tags.Format<"uuid">;

  /**
   * The user impacted by the decision, or null if not user-specific.
   *
   * Enables personalized explainability as per compliance (e.g., GDPR subject
   * right-to-explanation).
   */
  target_user_id?: (string & tags.Format<"uuid">) | null;

  /**
   * Entity type impacted by the decision (e.g. 'order', 'product', 'review').
   *
   * Supports traceability, BI analytics, and explainability reporting.
   */
  target_entity: string;

  /**
   * ID of the impacted entity; corresponds to the referenced entity's PK.
   *
   * Preserves entity trace for evidence.
   */
  target_entity_id: string & tags.Format<"uuid">;

  /**
   * The business or model outcome (e.g. recommend, block, set price).
   *
   * Represents the actual AI/model output.
   */
  decision: string;

  /**
   * Snapshot of the exact model input used for this inference; serialized
   * JSON or base64.
   *
   * Supports later forensics or explainability analysis.
   */
  input_snapshot: string;

  /**
   * Optional human/machine-readable rationale for the decision.
   *
   * Critical for explainability and legal review.
   */
  rationale?: string | null;

  /**
   * Timestamp when the AI/ML model inference was executed.
   *
   * Required by audit and evidence-trace mandates.
   */
  created_at: string & tags.Format<"date-time">;
};
export namespace IAIDecisionLog {
  /**
   * Creation DTO for a new AI decision log entry.
   *
   * Corresponds to the data required to record an automated model/event
   * inference in the ai_decision_logs table. Used by backend AI subsystems,
   * explainability pipelines, and compliance evidence publishers for logging
   * inference decisions with full trace.
   *
   * Strict validation and evidence policies apply.
   *
   * Property descriptions reference Prisma model columns and regulatory
   * requirements.
   */
  export type ICreate = {
    /**
     * Foreign key to ai_model_versions.id.
     *
     * Indicates the deployed AI/ML model version responsible for this
     * inference.
     */
    ai_model_version_id: string & tags.Format<"uuid">;

    /**
     * User impacted by the decision inference, if applicable.
     *
     * Mapped to users.id for evidence and personalization trace.
     */
    target_user_id?: (string & tags.Format<"uuid">) | null;

    /**
     * Entity type affected (e.g., 'order', 'product').
     *
     * Audit and explainability require explicit type declaration for
     * reference.
     */
    target_entity: string;

    /**
     * Unique identifier of the affected entity.
     *
     * Enables entity-specific audits, forensic trace, and BI reporting.
     */
    target_entity_id: string & tags.Format<"uuid">;

    /**
     * Outcome/model output (e.g., recommend, block, price value, etc).
     *
     * Derived model prediction or business action.
     */
    decision: string;

    /**
     * Serialized snapshot of model input at inference (full or
     * feature-selected payload).
     *
     * Required for audit and explainability.
     */
    input_snapshot: string;

    /**
     * Machine/human-readable rationale for the model outcome.
     *
     * Critical for AI legal compliance and evidence export.
     */
    rationale?: string | null;
  };
}

