/**
 * Validate fetching of a single AI decision log record by valid and invalid ID.
 *
 * Business context:
 * - AI decision logs are critical audit records capturing all evidence, input snapshots, model outcome, and rationale for each model-driven event.
 * - Regulatory and explainability workflows require extracting full decision context—accuracy, completeness, and evidence preservation are paramount for compliance and auditability.
 *
 * Test Steps:
 * 1. Create a valid AI decision log record (using POST /advancedAI/aiDecisionLogs).
 * 2. Fetch the created log by ID and verify all fields are present, correct, and compliant with schema.
 * 3. Attempt to fetch using a non-existent UUID; validate appropriate error/404 is returned, per audit traceability requirements.
 *
 * The test ensures both correct retrieval as well as strong error handling for missing logs.
 */
export async function test_api_advancedAI_aiDecisionLogs_getById(
  connection: api.IConnection,
) {
  // 1. Create a valid AI decision log record for setup
  const createInput: IAIDecisionLog.ICreate = {
    ai_model_version_id: typia.random<string & tags.Format<"uuid">>(),
