 * 2. Attempt to create a log missing required fields (`ai_model_version_id`, `target_entity`, etc.) – expect validation error responses.
 * 3. (Optional by API) If GET/list endpoints exist: retrieve to confirm creation is persisted; otherwise, validate creation return matches submitted attributes.
 *
 * This test ensures the API enforces evidence and compliance data policies for AI decisions and supports auditability by requiring all necessary evidence in the log entries.
 */
export async function test_api_advancedAI_test_create_ai_decision_log_with_valid_and_invalid_inputs(
  connection: api.IConnection,
) {
  // 1. Successfully create a new AI/ML decision log.
  const createInput: IAIDecisionLog.ICreate = {
    ai_model_version_id: typia.random<string & tags.Format<"uuid">>(),
    target_user_id: typia.random<string & tags.Format<"uuid">>(),
    target_entity: "order",
    target_entity_id: typia.random<string & tags.Format<"uuid">>(),
    decision: "approve",
    input_snapshot: JSON.stringify({ foo: "bar", trace: 123 }),
    rationale: "Test creation rationale for compliance and audit."
  };

  const createdLog = await api.functional.advancedAI.aiDecisionLogs.post(connection, { body: createInput });
  typia.assert(createdLog);
  TestValidator.equals("audit: ai_model_version_id")(createInput.ai_model_version_id)(createdLog.ai_model_version_id);
  TestValidator.equals("audit: target_entity")(createInput.target_entity)(createdLog.target_entity);
  TestValidator.equals("audit: decision")(createInput.decision)(createdLog.decision);
  TestValidator.equals("audit: input_snapshot")(createInput.input_snapshot)(createdLog.input_snapshot);
  TestValidator.equals("audit: rationale")(createInput.rationale)(createdLog.rationale);
  TestValidator.equals("audit: target_entity_id")(createInput.target_entity_id)(createdLog.target_entity_id);
  if (createInput.target_user_id)
    TestValidator.equals("audit: target_user_id")(createInput.target_user_id)(createdLog.target_user_id);
  TestValidator.predicate("audit: id is uuid")(typeof createdLog.id === "string" && /^[0-9a-f\-]{36}$/.test(createdLog.id));
  TestValidator.predicate("audit: created_at is iso8601")(typeof createdLog.created_at === "string" && !Number.isNaN(Date.parse(createdLog.created_at)));

  // 2. Attempt create with missing required fields and expect error(s)
  for (const [field, payload] of Object.entries({
    ai_model_version_id: (({ ai_model_version_id, ...rest }) => rest)(createInput),
    target_entity: (({ target_entity, ...rest }) => rest)(createInput),
    target_entity_id: (({ target_entity_id, ...rest }) => rest)(createInput),
    decision: (({ decision, ...rest }) => rest)(createInput),
    input_snapshot: (({ input_snapshot, ...rest }) => rest)(createInput),
  })) {
    await TestValidator.error(`creation fails without required ${field}`)(async () =>
      api.functional.advancedAI.aiDecisionLogs.post(connection, { body: payload as IAIDecisionLog.ICreate }),
    );
  }

  // 3. Extra: If GET/list endpoint exists, could be called here to verify persistence.
}

