import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAIDecisionLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IAIDecisionLog";

/**
 * Validate updating AI decision log metadata and error/audit behavior.
 *
 * This test validates:
 *   1. We can update mutable fields (e.g., rationale) of an existing AI decision log
 *   2. The changes are reflected in the returned record and detail API
 *   3. When attempting to update a non-existent log ID, we get the expected error (not found/audit)
 *   4. When submitting invalid update data, runtime validation is enforced (e.g., rationale string/nullable)
 *   5. All changes are constrained by audit/evidence rules (no change to immutable fields, only rationale, data integrity, etc)
 *
 * Steps:
 *   1. Create a valid decision log
 *   2. Update only the rationale on the log
 *   3. Verify response returns updated rationale; no change in other evidence fields
 *   4. Fetch the log via detail API to confirm the correct update
 *   5. Try to update using a random (likely non-existent) UUID, expect NotFound error
 *   6. Try to update using clearly invalid rationale (optional: very long string, type error, etc), expect validation error
 */
export async function test_api_advancedAI_test_update_ai_decision_log_with_valid_and_invalid_inputs(connection: api.IConnection) {
  // 1. Create a valid AI decision log
  const log = await api.functional.advancedAI.aiDecisionLogs.post(connection, {
    body: {
      ai_model_version_id: typia.random<string & tags.Format<"uuid">>(),
      target_user_id: typia.random<string & tags.Format<"uuid">>(),
      target_entity: "order",
      target_entity_id: typia.random<string & tags.Format<"uuid">>(),
      decision: "approve",
      input_snapshot: JSON.stringify({ x: 1, y: 2, reason: "A" }),
      rationale: "Initial rationale for evidence.",
    } satisfies IAIDecisionLog.ICreate
  });
  typia.assert(log);

  // 2. Update the rationale
  const newRationale = `Updated rationale, audit at ${new Date().toISOString()}`;
  const updated = await api.functional.advancedAI.aiDecisionLogs.putById(connection, {
    id: log.id,
    body: { rationale: newRationale } satisfies IAIDecisionLog.IUpdate
  });
  typia.assert(updated);
  TestValidator.equals("updated rationale")(newRationale)(updated.rationale);
  // Immutable fields must remain the same
  TestValidator.equals("id")(log.id)(updated.id);
  TestValidator.equals("ai_model_version_id")(log.ai_model_version_id)(updated.ai_model_version_id);
  TestValidator.equals("target_entity_id")(log.target_entity_id)(updated.target_entity_id);
  TestValidator.equals("decision")(log.decision)(updated.decision);
  TestValidator.equals("input_snapshot")(log.input_snapshot)(updated.input_snapshot);

  // 3. (Optionally) Read detail API for the log (assume GET exists, otherwise skip)
  // Skipped as only update and post functions were provided

  // 4. Attempt to update using a non-existent UUID
  await TestValidator.error("Should fail: updating with non-existing ID")(() =>
    api.functional.advancedAI.aiDecisionLogs.putById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(), // Very likely a non-existent new ID
      body: { rationale: "Rationale for non-existent record" } satisfies IAIDecisionLog.IUpdate
    })
  );

  // 5. Attempt invalid rationale update (null, empty, very long string, etc)
  await TestValidator.error("Should fail: invalid rationale format")(() =>
    api.functional.advancedAI.aiDecisionLogs.putById(connection, {
      id: log.id,
      body: { rationale: 12345 as unknown as string } // Deliberate type error, will error at runtime
    })
  );
  // Optionally: excessive length string etc if enforced

}

