import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAIDecisionLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IAIDecisionLog";
import type { IDeletionResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IDeletionResult";

/**
 * Validates the deletion of AI decision log entries, covering both successful deletion by valid ID and deletion attempt for a non-existent ID.
 *
 * This test ensures evidence and compliance traceability for destructive operations:
 *   1. An AI decision log entry is created, then deleted by ID. The deletion result is validated: correct ID, status is 'deleted' or equivalent, and timestamp is present.
 *   2. After deletion, further queries for the same ID should fail or confirm nonexistence (if query endpoint exists—if not, just infer by no error on re-delete).
 *   3. Idempotency or error-handling is verified by attempting to delete a non-existent (random or previously deleted) ID. The expected error or compliance-safe result is confirmed.
 *
 * Steps:
 * 1. Create an AI decision log entry via the POST endpoint.
 * 2. Delete it using the DELETE endpoint and assert the response fields (id matches, status is 'deleted', deleted_at is set).
 * 3. Attempt to delete the same ID again—should either return not_found (or idempotent success indicating prior delete)
 * 4. Attempt to delete an obviously non-existent log ID (random UUID)—should return not_found or suitable error/status.
 */
export async function test_api_advancedAI_test_delete_ai_decision_log_by_valid_and_invalid_id(
  connection: api.IConnection,
) {
  // 1. Create an AI decision log entry
  const aiLog = await api.functional.advancedAI.aiDecisionLogs.post(connection, {
    body: {
      ai_model_version_id: typia.random<string & tags.Format<"uuid">>(),
      target_user_id: typia.random<string & tags.Format<"uuid">>(),
      target_entity: "order",
      target_entity_id: typia.random<string & tags.Format<"uuid">>(),
      decision: "approve",
      input_snapshot: JSON.stringify({ orderAmount: 1000, currency: "KRW" }),
      rationale: "Test decision for delete E2E.",
    },
  });
  typia.assert(aiLog);

  // 2. Delete the created AI decision log
  const delResult = await api.functional.advancedAI.aiDecisionLogs.eraseById(connection, {
    id: aiLog.id,
  });
  typia.assert(delResult);
  TestValidator.equals("deleted ID matches")(aiLog.id)(delResult.id);
  TestValidator.equals("status is deleted")("deleted")(delResult.status);
  TestValidator.predicate("deleted_at is present")(!!delResult.deleted_at);

  // 3. Re-delete same ID -- expects not_found or idempotent result
  await TestValidator.error("delete non-existent ID should fail or be idempotent")(() =>
    api.functional.advancedAI.aiDecisionLogs.eraseById(connection, { id: aiLog.id }),
  );

  // 4. Delete a random non-existent ID
  const randomId = typia.random<string & tags.Format<"uuid">>()
  await TestValidator.error("delete random non-existent ID should fail")(() =>
    api.functional.advancedAI.aiDecisionLogs.eraseById(connection, { id: randomId }),
  );
}

