import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAiFeedback } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiFeedback";
import type { IPageIAiFeedback } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIAiFeedback";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validates listing/searching AI feedback records with various filters, ensuring correct pagination and filter application.
 *
 * Business context: AI feedback records are critical for audit, model improvement, and regulatory explainability. Listing with complex filters is often used by modelers, compliance, and ops staff to analyze ML usage, responses, and user experience.
 *
 * Steps:
 * 1. Create multiple deterministic AI feedback records (with known decision_log_id, user_id, feedback_type, timestamps).
 * 2. List/search feedback records using filters on feedback_type, user_id, decision_log_id, and time ranges.
 * 3. For each filter, confirm only matching feedback records appear and fields match expectations; verify pagination meta.
 * 4. Query non-matching filter (e.g., future-only range/invalid type) and confirm empty results, valid pagination, no error.
 * 5. (Edge) In an empty DB, system yields empty set (simulate by unique filter or verify empty state first).
 */
export async function test_api_advancedAI_test_list_ai_feedback_with_various_filters(
  connection: api.IConnection,
) {
  // Helper to make timestamp strings
  const now = new Date();
  const toISOString = (date: Date) => date.toISOString();

  // Step 1: Create deterministic feedback records
  // Use the same timestamps/ids for precise matching
  const decisionLogId1 = typia.random<string & tags.Format<"uuid">>();
  const decisionLogId2 = typia.random<string & tags.Format<"uuid">>();
  const userId1 = typia.random<string & tags.Format<"uuid">>();
  const userId2 = typia.random<string & tags.Format<"uuid">>();

  // Feedback types for diversity
  const type1 = "explicit-accept";
  const type2 = "implicit-dismiss";

  // Feedback at different times
  const earlier = new Date(now.getTime() - 1000 * 60 * 60 * 24); // 1 day ago
  const later = new Date(now.getTime() - 1000 * 60 * 10); // 10 minutes ago

  // Create records
  const recordA = await api.functional.advancedAI.aiFeedback.post(connection, {
    body: {
      decision_log_id: decisionLogId1,
      user_id: userId1,
      feedback_type: type1,
      feedback_value: "positive",
      metadata: JSON.stringify({ browser: "Chrome", reason: "looked good" }),
    },
  });
  typia.assert(recordA);

  const recordB = await api.functional.advancedAI.aiFeedback.post(connection, {
    body: {
      decision_log_id: decisionLogId1,
      user_id: userId2,
      feedback_type: type2,
      feedback_value: "negative",
      metadata: JSON.stringify({ browser: "Firefox", reason: "wrong answer" }),
    },
  });
  typia.assert(recordB);

  const recordC = await api.functional.advancedAI.aiFeedback.post(connection, {
    body: {
      decision_log_id: decisionLogId2,
      user_id: userId1,
      feedback_type: type2,
      feedback_value: null,
      metadata: null,
    },
  });
  typia.assert(recordC);

  // Step 2: List all feedback for decisionLogId1, expect recordA and recordB
  let resp = await api.functional.advancedAI.aiFeedback.patch(connection, {
    body: { decision_log_id: decisionLogId1 },
  });
  typia.assert(resp);
  const ids = resp.data.map((f) => f.id);
  TestValidator.predicate("List by decision_log_id filters correctly")(
    ids.includes(recordA.id) && ids.includes(recordB.id) && ids.length === 2,
  );
  resp.data.forEach((fb) => {
    TestValidator.equals("decision_log_id match")(
      decisionLogId1,
    )(fb.decision_log_id);
  });

  // Step 3: List feedback by user_id=userId1, expect recordA and recordC
  resp = await api.functional.advancedAI.aiFeedback.patch(connection, {
    body: { user_id: userId1 },
  });
  typia.assert(resp);
  const found = resp.data.map((f) => f.id);
  TestValidator.predicate("List by user_id filters correctly")(
    found.includes(recordA.id) && found.includes(recordC.id) && found.length === 2,
  );
  resp.data.forEach((fb) => {
    TestValidator.equals("user_id match")(userId1)(fb.user_id);
  });

  // Step 4: List feedback by feedback_type=type2, expect recordB and recordC
  resp = await api.functional.advancedAI.aiFeedback.patch(connection, {
    body: { feedback_type: type2 },
  });
  typia.assert(resp);
  const idsByType = resp.data.map((f) => f.id);
  TestValidator.predicate("List by feedback_type filters correctly")(
    idsByType.includes(recordB.id) && idsByType.includes(recordC.id) && idsByType.length === 2,
  );
  resp.data.forEach((fb) => {
    TestValidator.equals("feedback_type match")(type2)(fb.feedback_type);
  });

  // Step 5: List by time_range_start/lower bound (later), should only match those created after 'later'
  resp = await api.functional.advancedAI.aiFeedback.patch(connection, {
    body: { time_range_start: toISOString(later) },
  });
  typia.assert(resp);
  // All records were just created, so at least all 3 (unless backend has different logic)
  TestValidator.predicate("List by time_range_start yields non-empty subset")(
    resp.data.length >= 3,
  );

  // Step 6: Query with time_range in the far past, should include all
  resp = await api.functional.advancedAI.aiFeedback.patch(connection, {
    body: { time_range_start: toISOString(earlier) },
  });
  typia.assert(resp);
  TestValidator.predicate("List by wide time_range includes all")(
    [recordA.id, recordB.id, recordC.id].every((id) =>
      resp.data.map((f) => f.id).includes(id),
    ),
  );

  // Step 7: Query with a future time range: should return 0
  const future = new Date(now.getTime() + 10000);
  resp = await api.functional.advancedAI.aiFeedback.patch(connection, {
    body: { time_range_start: toISOString(future) },
  });
  typia.assert(resp);
  TestValidator.equals("Future-only time range yields none")(0)(resp.data.length);
  TestValidator.predicate("Empty pagination valid")(
    resp.pagination.current === 1 && resp.pagination.limit > 0,
  );

  // Step 8: Query with feedback_type that does not exist
  resp = await api.functional.advancedAI.aiFeedback.patch(connection, {
    body: { feedback_type: "nonexistent-type" },
  });
  typia.assert(resp);
  TestValidator.equals("Nonexistent feedback_type yields none")(0)(resp.data.length);
  TestValidator.predicate("Still gives valid empty pagination")(
    resp.pagination.current === 1 && resp.pagination.limit > 0,
  );

  // Step 9: (Edge) Simulate empty DB query (by using absurd/unique filter)
  resp = await api.functional.advancedAI.aiFeedback.patch(connection, {
    body: { decision_log_id: typia.random<string & tags.Format<"uuid">>() },
  });
  typia.assert(resp);
  TestValidator.equals("Unknown decision_log_id yields none")(0)(resp.data.length);
  TestValidator.predicate("Empty DB returns valid pagination")(
    resp.pagination.current === 1 && resp.pagination.limit > 0,
  );
}

