import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAiFeedback } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiFeedback";

/**
 * Validate AI feedback creation with valid and invalid inputs.
 *
 * Scenario:
 * 1. Create a new AI feedback record using all required (and some optional) fields – expect successful persistence.
 * 2. Attempt to create a feedback record with missing required fields (e.g., no decision_log_id, no feedback_type) and expect a validation or business logic error.
 * 3. Attempt to create a feedback record with an invalid value (e.g., an invalid uuid for decision_log_id) and expect validation failure.
 *
 * Steps:
 * 1. Construct a valid IAiFeedback.ICreate payload (with decision_log_id, feedback_type, and optional user_id, feedback_value, metadata).
 * 2. Call api.functional.advancedAI.aiFeedback.post – verify output matches IAiFeedback (fields: id [uuid], decision_log_id, feedback_type, timestamps, etc.).
 * 3. Omit required fields (one at a time); each time expect api.functional.advancedAI.aiFeedback.post to error, and validate error is thrown.
 * 4. Provide incorrect format for a field (invalid uuid for decision_log_id); verify validation error is thrown.
 *
 * Validation:
 * - On success: All returned fields populated correctly; e.g., output.decision_log_id matches payload, output.id is uuid, output.created_at is ISO datetime.
 * - On failure cases: api.functional.advancedAI.aiFeedback.post throws error, and error message explains validation failure due to missing or invalid fields.
 * - All assertions must use typia.assert and TestValidator error checks for runtime failures.
 */
export async function test_api_advancedAI_test_create_ai_feedback_with_valid_and_invalid_inputs(
  connection: api.IConnection,
) {
  // 1. Create a valid AI feedback record
  const validPayload: IAiFeedback.ICreate = {
    decision_log_id: typia.random<string & tags.Format<"uuid">>(),
    feedback_type: "explicit",
    user_id: typia.random<string & tags.Format<"uuid">>(),
    feedback_value: "positive",
    metadata: JSON.stringify({ device: "web", reason: "explicit user test" }),
  };
  const output = await api.functional.advancedAI.aiFeedback.post(connection, {
    body: validPayload,
  });
  typia.assert(output);
  TestValidator.equals("decision_log_id")(validPayload.decision_log_id)(output.decision_log_id);
  TestValidator.equals("feedback_type")(validPayload.feedback_type)(output.feedback_type);
  TestValidator.predicate("output.id is uuid")(!!output.id && typeof output.id === 'string' && output.id.length > 0);
  TestValidator.predicate("output.created_at is ISO datetime")(!!output.created_at && typeof output.created_at === 'string');

  // 2. Test missing required field: decision_log_id
  await TestValidator.error("missing decision_log_id should fail")(async () => {
    // Omitting decision_log_id - should cause validation error
    await api.functional.advancedAI.aiFeedback.post(connection, {
      body: {
        // decision_log_id omitted (but still type-safe TS, so supply an invalid uuid string instead)
        decision_log_id: "not-a-uuid",
        feedback_type: "explicit",
      },
    });
  });

  // 3. Test missing required field: feedback_type
  await TestValidator.error("missing feedback_type should fail")(async () => {
    await api.functional.advancedAI.aiFeedback.post(connection, {
      body: {
        decision_log_id: typia.random<string & tags.Format<"uuid">>(),
        // feedback_type omitted - simulate with empty string
        feedback_type: "",
      },
    });
  });

  // 4. Test invalid format: decision_log_id must be uuid
  await TestValidator.error("invalid uuid in decision_log_id")(async () => {
    await api.functional.advancedAI.aiFeedback.post(connection, {
      body: {
        decision_log_id: "INVALID-UUID-1234",
        feedback_type: "explicit",
      },
    });
  });
}

