/**
 * Validate update operation for AI feedback by ID and edge/error handling.
 *
 * This test ensures the system admits updates only for existing feedback records and strictly enforces schema/business rules, and compliance/audit standards. It also verifies attempted updates to nonexistent or schema-invalid records fail as expected and are audit-safe.
 *
 * 1. Create a valid AI feedback record to use for update
 * 2. Perform an update on the created feedback record using a valid ID and new values for mutable fields (feedback_type, feedback_value, metadata)
 * 3. Retrieve the updated record (if possible) or assert via response verification that fields have changed
 * 4. Attempt to update with an invalid (random) UUID – system must return a not-found error
 * 5. Attempt to update with schema-violating request payload (e.g., missing all updatable fields or overly long feedback_type if known limit)—system must reject with validation error (runtime, no TypeScript-level omission)
 */
export async function test_api_advancedai_test_update_ai_feedback_with_valid_and_invalid_inputs(connection: api.IConnection) {
  // 1. Create a valid AI feedback record (dependency)
  const createInput: IAiFeedback.ICreate = {
    decision_log_id: typia.random<string & tags.Format<"uuid">>(),
    user_id: typia.random<string & tags.Format<"uuid">>(),
    feedback_type: "accepted",
    feedback_value: "positive",
    metadata: '{"traceId":"' + typia.random<string & tags.Format<"uuid">>() + '"}',
