  const created: IAiFeedback = await api.functional.advancedAI.aiFeedback.post(connection, { body: createInput });
  typia.assert(created);

  // 2. Update mutable fields of the feedback record
  const updateFields: IAiFeedback.IUpdate = {
    feedback_type: "overridden",
    feedback_value: "disputed",
    metadata: '{"reason":"user requested correction"}',
  };
  const updated: IAiFeedback = await api.functional.advancedAI.aiFeedback.putById(connection, {
    id: created.id,
    body: updateFields,
  });
  typia.assert(updated);
  TestValidator.equals("feedback_type updated")("overridden")(updated.feedback_type);
  TestValidator.equals("feedback_value updated")("disputed")(updated.feedback_value);
  TestValidator.equals("metadata updated")('{"reason":"user requested correction"}')(updated.metadata);

  // 3. Attempt to update with invalid/nonexistent ID
  await TestValidator.error("Not found error for nonexistent feedback ID")(() =>
    api.functional.advancedAI.aiFeedback.putById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(), // random UUID, unlikely to exist
      body: updateFields,
    }),
  );

  // 4. Attempt schema-violating update (payload missing all fields)
  await TestValidator.error("Schema violation: empty update payload")(() =>
    api.functional.advancedAI.aiFeedback.putById(connection, {
      id: created.id,
      body: {} as IAiFeedback.IUpdate,
    }),
  );

  // 5. (Optional) Attempt schema violation: feedback_type overly long
  await TestValidator.error("Schema violation: feedback_type long string")(() =>
    api.functional.advancedAI.aiFeedback.putById(connection, {
      id: created.id,
      body: { feedback_type: "X".repeat(2049) },
    }),
  );
