/**
 * AI feedback event record as defined in ai_feedback schema.
 *
 * Links a feedback event (explicit/implicit/overridden, etc.) to a
 * corresponding AI decision log, tracking user, feedback nature/value,
 * metadata, and timestamp. Used to close the feedback loop, power model
 * retraining, enable audit chain for explainability, and satisfy regulatory
 * evidence requirements.
 *
 * Each property is deeply documented and aligns to compliance, audit, model
 * ops, and ML improvement flows.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IAiFeedback = {
  /**
   * Unique identifier for this feedback event; ai_feedback.id (PK).
   *
   * Serves as canonical reference for evidence and audit.
   */
  id: string & tags.Format<"uuid">;

  /** Foreign key to the original model inference (ai_decision_logs.id). */
  decision_log_id: string & tags.Format<"uuid">;

  /**
   * Identity of user associated with the feedback; null for implicit/auto
   * signals.
   *
   * Links to users.id if present.
   */
  user_id?: (string & tags.Format<"uuid">) | null;

  /**
   * Feedback type (categorical): e.g., accepted, dismissed, overridden,
   * implicit-click, etc.
   *
   * Business logic or enum dictates acceptable values.
   */
  feedback_type: string;

  /**
   * Quantitative or qualitative feedback value (e.g., rating=5, positive,
   * negative).
   *
   * Supports regulatory evidence for model tuning and explainability.
   */
  feedback_value?: string | null;

  /**
   * Additional context, device info, or feedback rationale. Key/JSON string.
   *
   * Enables richer explainability and evidence preservation for compliance.
   */
  metadata?: string | null;

  /**
   * Timestamp for the feedback event; set on record creation. Audit chain and
   * evidence tracking depend on this.
   */
  created_at: string & tags.Format<"date-time">;
};
export namespace IAiFeedback {
  /**
   * Creation DTO for a new AI feedback event. Mapped to ai_feedback schema.
   *
   * Input structure for feedback, supports both explicit (user-triggered) and
   * implicit (system-observed) feedback loops. Used by model retrainers,
   * annotation pipelines, compliance triggers, and feedback UIs. Strict
   * business and compliance validation is required for all fields.
   */
  export type ICreate = {
    /**
     * FK to original model inference (ai_decision_logs.id). Required.
     *
     * Enables evidence-chain linkage for feedback.
     */
    decision_log_id: string & tags.Format<"uuid">;

    /**
     * User identifier; null for implicit/anonymous feedback event.
     *
     * Links to users.id, ensuring feedback traceability.
     */
    user_id?: (string & tags.Format<"uuid">) | null;

    /**
     * Categorical value for feedback (e.g., explicit, implicit, accepted,
     * dismissed).
     *
     * Enumerated by business logic/policy.
     */
    feedback_type: string;

    /**
     * Value of feedback (e.g., rating=5, positive/negative/disputed, etc).
     * Nullable for signal-only records.
     *
     * Supports evidence-based retraining and explainability.
     */
    feedback_value?: string | null;

    /**
     * JSON/key-value string for device, context, or rationale for feedback
     * (optional).
     */
    metadata?: string | null;
  };
}

