import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAiFeedback } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiFeedback";
import type { IDeletionResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IDeletionResult";

/**
 * Test deletion of AI Feedback with both valid and invalid IDs
 *
 * This test ensures that deleting an existing AI feedback record works and that subsequent deletes or deletes with non-existent IDs are handled appropriately (idempotent behavior or suitable error returned).
 *
 * Steps:
 * 1. Create a new AI feedback record (dependency setup).
 * 2. Delete the feedback by its real ID and verify the deletion result (ID/status/deleted_at fields).
 * 3. Attempt to delete the same feedback again (should return 'not_found' or indicate idempotency).
 * 4. Attempt to delete a randomly generated, non-existent feedback ID (should return 'not_found' or appropriate error).
 * 5. Optionally, if possible, verify the deleted feedback no longer appears in system queries/lists.
 */
export async function test_api_advancedAI_test_delete_ai_feedback_by_valid_and_invalid_id(connection: api.IConnection) {
  // 1. Create a new feedback record
  const feedback = await api.functional.advancedAI.aiFeedback.post(connection, {
    body: {
      decision_log_id: typia.random<string & tags.Format<"uuid">>(),
      user_id: null,
      feedback_type: "explicit",
      feedback_value: "positive",
      metadata: null,
    } satisfies IAiFeedback.ICreate,
  });
  typia.assert(feedback);

  // 2. Delete the feedback by valid ID
  const deletion = await api.functional.advancedAI.aiFeedback.eraseById(connection, {
    id: feedback.id,
  });
  typia.assert(deletion);
  TestValidator.equals("deleted id matches")(feedback.id)(deletion.id);
  TestValidator.equals("status is deleted")("deleted")(deletion.status);
  TestValidator.predicate("deleted_at is present")(!!deletion.deleted_at);

  // 3. Attempt to delete the same feedback again (should be idempotent/not found)
  const deletionAgain = await api.functional.advancedAI.aiFeedback.eraseById(connection, {
    id: feedback.id,
  });
  typia.assert(deletionAgain);
  TestValidator.equals("deleted id matches again")(feedback.id)(deletionAgain.id);
  TestValidator.equals("status is not_found or idempotent")(
    true
  )(
    deletionAgain.status === "not_found" || deletionAgain.status === "deleted"
  );

  // 4. Attempt to delete a random non-existent feedback ID
  const randomId = typia.random<string & tags.Format<"uuid">>();
  const deletionInvalid = await api.functional.advancedAI.aiFeedback.eraseById(connection, {
    id: randomId,
  });
  typia.assert(deletionInvalid);
  TestValidator.equals("status is not_found for invalid id")("not_found")(deletionInvalid.status);
}

