import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ISecurityEvent } from "@ORGANIZATION/PROJECT-api/lib/structures/ISecurityEvent";
import type { IPageISecurityEvent } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageISecurityEvent";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate listing and filtering of security event logs through the securityCompliance.securityEvent.patch endpoint.
 *
 * This test ensures the search, pagination, and filtering of security event records satisfy business requirements for security evidence, compliance, and investigation use cases.
 *
 * Scenario:
 * 1. Create multiple security event records with different combinations of event_type, user_id, session_id and timestamps by calling securityCompliance.securityEvent.post multiple times (dependency).
 * 2. Retrieve events list unfiltered (no filters) to confirm all records are returned.
 * 3. Retrieve events filtered by a specific event_type and confirm only matching records are returned.
 * 4. Retrieve events filtered by a specific time range (from_time/to_time) and confirm only matching records are returned.
 * 5. Test pagination parameters (limit, page) and confirm correct number of records and pages.
 * 6. Filter with a combination that yields zero results and confirm empty data array with correct pagination metadata.
 * 7. Validate that all response items are structurally correct and match the type specification.
 */
export async function test_api_securityCompliance_test_list_security_event_logs_with_various_filters(connection: api.IConnection) {
  // 1. Create 6 distinct security event records for filtering and paging scenarios
  const now = new Date();
  const sixMinutesAgo = new Date(now.getTime() - 6 * 60 * 1000).toISOString();
  const fiveMinutesAgo = new Date(now.getTime() - 5 * 60 * 1000).toISOString();
  const fourMinutesAgo = new Date(now.getTime() - 4 * 60 * 1000).toISOString();
  const threeMinutesAgo = new Date(now.getTime() - 3 * 60 * 1000).toISOString();
  const twoMinutesAgo = new Date(now.getTime() - 2 * 60 * 1000).toISOString();
  const oneMinuteAgo = new Date(now.getTime() - 1 * 60 * 1000).toISOString();
  const events = [
    { event_type: "login_attempt", created_at: sixMinutesAgo },
    { event_type: "token_rotation", created_at: fiveMinutesAgo },
    { event_type: "login_attempt", created_at: fourMinutesAgo },
    { event_type: "privilege_escalation", created_at: threeMinutesAgo },
    { event_type: "login_attempt", created_at: twoMinutesAgo },
    { event_type: "token_rotation", created_at: oneMinuteAgo },
  ];
  const createdEvents = [];
  for (const eventMeta of events) {
    const record = await api.functional.securityCompliance.securityEvent.post(connection, {
      body: {
        event_type: eventMeta.event_type,
        event_details: JSON.stringify({ message: `Details for ${eventMeta.event_type}` }),
        created_at: eventMeta.created_at,
      } satisfies ISecurityEvent.ICreate,
    });
    typia.assert(record);
    createdEvents.push(record);
  }

  // 2. Retrieve all events unfiltered
  const allEvents = await api.functional.securityCompliance.securityEvent.patch(connection, { body: {} });
  typia.assert(allEvents);
  TestValidator.predicate("Unfiltered event list contains all created records")(
    createdEvents.every(e => allEvents.data.some(x => x.id === e.id)));

  // 3. Filter by event_type
  const loginFilter = await api.functional.securityCompliance.securityEvent.patch(connection, { body: { event_type: "login_attempt" } });
  typia.assert(loginFilter);
  TestValidator.predicate("Event type filter works")(
    loginFilter.data.every(e => e.event_type === "login_attempt"));

  // 4. Filter by time range
  const timeFiltered = await api.functional.securityCompliance.securityEvent.patch(connection, { body: { from_time: twoMinutesAgo, to_time: now.toISOString() } });
  typia.assert(timeFiltered);
  TestValidator.predicate("Time range filter works")(
    timeFiltered.data.every(e => e.created_at >= twoMinutesAgo && e.created_at <= now.toISOString()));

  // 5. Pagination
  const paged = await api.functional.securityCompliance.securityEvent.patch(connection, { body: { limit: 2, page: 2 } });
  typia.assert(paged);
  TestValidator.equals("Pagination page size")(2)(paged.data.length);
  TestValidator.equals("Pagination page index")(2)(paged.pagination.current);

  // 6. Zero result
  const none = await api.functional.securityCompliance.securityEvent.patch(connection, { body: { event_type: "NON_EXISTENT_EVENT_TYPE" } });
  typia.assert(none);
  TestValidator.equals("No results for impossible filter")(0)(none.data.length);
  TestValidator.equals("Pagination intact when no results")(1)(none.pagination.pages);
}

