 * 2. Query events unfiltered: confirm all created records are present.
 * 3. Filter by event_type: verify only matching records are returned.
 * 4. Filter by a time window: verify only records within the range are returned.
 * 5. Test pagination (page, limit): confirm correct data slice and metadata.
 * 6. Query with a filter that yields zero results: expect empty data and valid pagination.
 * 7. Validate type-safety and business rules at every step.
 */
export async function test_api_securityCompliance_test_list_security_event_logs_with_various_filters(
  connection: api.IConnection,
) {
  // 1. Create 6 security event records with known event_types and timestamps
  const now = new Date();
  const sixMinutesAgo = new Date(now.getTime() - 6 * 60 * 1000).toISOString();
  const fiveMinutesAgo = new Date(now.getTime() - 5 * 60 * 1000).toISOString();
  const fourMinutesAgo = new Date(now.getTime() - 4 * 60 * 1000).toISOString();
  const threeMinutesAgo = new Date(now.getTime() - 3 * 60 * 1000).toISOString();
  const twoMinutesAgo = new Date(now.getTime() - 2 * 60 * 1000).toISOString();
  const oneMinuteAgo = new Date(now.getTime() - 1 * 60 * 1000).toISOString();

  // Use distinctive event_types for filters
  const events = [
    { event_type: "login_attempt", created_at: sixMinutesAgo },
    { event_type: "token_rotation", created_at: fiveMinutesAgo },
    { event_type: "login_attempt", created_at: fourMinutesAgo },
    { event_type: "privilege_escalation", created_at: threeMinutesAgo },
    { event_type: "login_attempt", created_at: twoMinutesAgo },
    { event_type: "token_rotation", created_at: oneMinuteAgo },
  ];

  const created: ISecurityEvent[] = [];
  for (const meta of events) {
