import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ISecurityEvent } from "@ORGANIZATION/PROJECT-api/lib/structures/ISecurityEvent";

/**
 * Validate fetching of a specific security event log by both valid and invalid ID.
 *
 * Business context:
 * Security event logs provide essential evidence for audits, compliance, and incident response. Accurate retrieval by ID is crucial for forensic review and regulatory reporting, while error handling for invalid IDs prevents information disclosure and ensures system robustness.
 *
 * Steps:
 * 1. Insert a new security event log using POST /securityCompliance/securityEvent (dependency) to ensure a valid event exists for retrieval.
 * 2. Fetch the inserted security event log by its ID using GET /securityCompliance/securityEvent/{id}.
 *    - Confirm that all event details (id, user_id, session_id, api_client_id, event_type, event_details, created_at) match what was stored or required by schema.
 * 3. Attempt to fetch a non-existent security event log using a random UUID that does not correspond to any record.
 *    - Confirm that an HTTP error is returned (such as 404 Not Found), and that error reporting is appropriate and does not leak sensitive information.
 */
export async function test_api_securityCompliance_test_get_security_event_by_valid_and_invalid_id(
  connection: api.IConnection,
) {
  // 1. Insert a new security event log as setup
  const createInput: ISecurityEvent.ICreate = {
    event_type: "login_attempt",
    event_details: JSON.stringify({ reason: "user login for audit e2e" }),
  };
  const created: ISecurityEvent = await api.functional.securityCompliance.securityEvent.post(
    connection,
    { body: createInput },
  );
  typia.assert(created);
  TestValidator.equals("event_type")(createInput.event_type)(created.event_type);
  TestValidator.equals("event_details")(createInput.event_details)(created.event_details);

  // 2. Fetch by valid ID and confirm details
  const output: ISecurityEvent = await api.functional.securityCompliance.securityEvent.getById(
    connection,
    { id: created.id },
  );
  typia.assert(output);
  TestValidator.equals("id")(created.id)(output.id);
  TestValidator.equals("event_type")(created.event_type)(output.event_type);
  TestValidator.equals("event_details")(created.event_details)(output.event_details);

  // 3. Fetch by invalid ID and confirm error reporting
  await TestValidator.error("fetching invalid security event id throws error")(
    async () => {
      await api.functional.securityCompliance.securityEvent.getById(connection, {
        id: typia.random<string & tags.Format<"uuid">>(), // random UUID, unlikely to exist
      });
    },
  );
}

