import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ISecurityEvent } from "@ORGANIZATION/PROJECT-api/lib/structures/ISecurityEvent";

/**
 * E2E test for updating security event logs with valid and invalid inputs.
 *
 * Validates the system's behavior for updating security event entries as required by audit and compliance operations.
 *
 * Steps:
 * 1. Create a security event log entry (dependency setup).
 * 2. Update its event_details field using its valid ID.
 * 3. Retrieve and verify that the event_details were actually updated.
 * 4. Attempt to update a non-existent (random) ID and ensure the system returns error or does not update any resource (test for appropriate error code, such as 404 or system-defined behavior).
 *
 * Business Rules Verified:
 * - Only event_details are mutable in security event updates.
 * - Updates by valid ID are persisted and retrievable.
 * - Attempts to update with invalid/nonexistent ID are rejected and do not affect data.
 */
export async function test_api_securityCompliance_test_update_security_event_with_valid_and_invalid_inputs(
  connection: api.IConnection,
) {
  // 1. Create security event (dependency)
  const creation: ISecurityEvent = await api.functional.securityCompliance.securityEvent.post(connection, {
    body: {
      user_id: null,
      session_id: null,
      api_client_id: null,
      event_type: "login_attempt",
      event_details: "Initial log for E2E update test.",
      created_at: new Date().toISOString(),
    } satisfies ISecurityEvent.ICreate,
  });
  typia.assert(creation);

  // 2. Update the event_details of the created security event
  const newEventDetails = "Updated by E2E test at " + new Date().toISOString();
  const updated: ISecurityEvent = await api.functional.securityCompliance.securityEvent.putById(connection, {
    id: creation.id,
    body: {
      event_details: newEventDetails,
    } satisfies ISecurityEvent.IUpdate,
  });
  typia.assert(updated);
  TestValidator.equals("event_details updated")(newEventDetails)(updated.event_details);

  // 3. Retrieve and confirm event_details are updated (redundancy in this API, but for completeness, can re-fetch if GET were supported... here verify fields inline)
  TestValidator.equals("event_type should remain unchanged")(creation.event_type)(updated.event_type);

  // 4. Attempt update with non-existent event ID
  const invalidId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("update with invalid ID should fail")(() =>
    api.functional.securityCompliance.securityEvent.putById(connection, {
      id: invalidId,
      body: {
        event_details: "This should not succeed.",
      },
    })
  );
}

