 * audit, compliance, and extensible role/permission mapping. Used throughout
 * user/role, API, audit, and compliance subsystems.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IPermission = {
  /**
   * Unique identifier for the permission record (primary key).
   *
   * Enforces referential integrity and allows evidential linking in RBAC
   * workflows.
   */
  id: string & tags.Format<"uuid">;

  /**
   * Foreign key to the policy this permission is grouped under, enabling
   * pluggable security policy management.
   *
   * Nullable for root permissions.
   */
  policy_id?: (string & tags.Format<"uuid">) | null;

  /**
   * Unique permission code within the system, e.g., 'order.edit',
   * 'user.read'.
   *
   * Supports granular, explainable security model per requirements.
   */
  code: string;

  /**
   * Human-readable description of what the permission allows, for audit,
   * explainability, and UI management.
   */
  description: string;

  /**
   * Timestamp of permission creation for evidence review and compliance
   * reporting.
   */
  created_at: string & tags.Format<"date-time">;
};
export namespace IPermission {
  /**
   * Structured search/filter/pagination options for permission list API.
   * Supports advanced permission registry queries in admin and compliance
   * dashboards as per SecurityCompliance module.
   */
  export type IRequest = {
    /**
     * Filter by permission code using exact or fuzzy match. Used for
     * advanced permission management UIs or audit dashboards.
     */
    code?: string;

    /** Filter by permission description for search/navigation workflows. */
    description?: string | null;

    /**
     * Filter by assigned policy (UUID). Restricts search by parent policy
     * relationship.
     */
    policy_id?: string & tags.Format<"uuid">;

    /**
     * Start timestamp (inclusive) for creation time filtering. Allows
     * time-based analysis of permission onboarding trends.
     */
    created_from?: string & tags.Format<"date-time">;

    /** End timestamp (exclusive) for creation time filtering. */
    created_to?: string & tags.Format<"date-time">;

    /** Page number for paginated search results. */
    page?: number &
      tags.Type<"int32"> &
      tags.Minimum<1> &
      tags.JsonSchemaPlugin<{
        format: "int32";
      }>;

    /**
