import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPermission } from "@ORGANIZATION/PROJECT-api/lib/structures/IPermission";
import type { IPageIPermission } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPermission";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * E2E test for listing and filtering Permission records with various filters and pagination.
 *
 * Business context:
 * This test validates the permissions list/search endpoint used for RBAC audits, admin dashboards, and compliance. It verifies the endpoint can filter permissions by code, description, and policy_id, supports proper paging, and handles empty result edge cases. Permission records are created as prerequisites for meaningful search/filter/pagination logic.
 *
 * Steps:
 * 1. Create several unique permissions with distinct code, description, and (optionally) policy_id values.
 * 2. List all permissions (no filters), confirm expected records are returned with correct pagination metadata.
 * 3. Filter permissions by code, expect only the matching record(s).
 * 4. Filter permissions by description, expect correct subset.
 * 5. Filter permissions by policy_id, expect correct records or empty if no match.
 * 6. List permissions with a non-existing code or policy_id, verify zero results edge case.
 * 7. Page through results (limit/page), ensure correct ordering and consistent pagination metadata.
 */
export async function test_api_securityCompliance_test_list_permissions_with_various_filters(
  connection: api.IConnection,
) {
  // 1. Create several unique permissions
  const permissions = [] as IPermission[];
  const policies = [
    undefined,
    typia.random<string & tags.Format<"uuid">>(),
    typia.random<string & tags.Format<"uuid">>(),
  ];
  for (let i = 0; i < 3; ++i) {
    const permission = await api.functional.securityCompliance.permission.post(
      connection,
      {
        body: {
          code: `test_permission_code_${RandomGenerator.alphaNumeric(6)}_${i}`,
          description: `test description ${i}`,
          policy_id: policies[i],
        } satisfies IPermission.ICreate,
      },
    );
    permissions.push(permission);
    typia.assert(permission);
  }

  // 2. List all permissions (no filter)
  const allResult = await api.functional.securityCompliance.permission.patch(
    connection,
    {
      body: {} satisfies IPermission.IRequest,
    },
  );
  typia.assert(allResult);
  TestValidator.predicate("list all: at least 3 permissions exist")(allResult.data.length >= 3);

  // 3. Filter by code
  const filterByCode = await api.functional.securityCompliance.permission.patch(
    connection,
    {
      body: { code: permissions[0].code } satisfies IPermission.IRequest,
    },
  );
  typia.assert(filterByCode);
  TestValidator.equals("filter by code match count")(1)(filterByCode.data.length);
  TestValidator.equals("code matches")(permissions[0].code)(filterByCode.data[0].code);

  // 4. Filter by description
  const filterByDesc = await api.functional.securityCompliance.permission.patch(
    connection,
    {
      body: { description: permissions[1].description } satisfies IPermission.IRequest,
    },
  );
  typia.assert(filterByDesc);
  TestValidator.predicate("filter by description non-empty")(filterByDesc.data.length >= 1);
  TestValidator.predicate("description matches some")(filterByDesc.data.some(p => p.description === permissions[1].description));

  // 5. Filter by policy_id (valid and no-match)
  const filterByPolicyId = await api.functional.securityCompliance.permission.patch(
    connection,
    {
      body: { policy_id: policies[1] } satisfies IPermission.IRequest,
    },
  );
  typia.assert(filterByPolicyId);
  TestValidator.predicate("policy_id match")(filterByPolicyId.data.some(p => p.policy_id === policies[1]));

  // 6. Filter with non-existing code or policy_id (edge no-results)
  const nonExistingResult = await api.functional.securityCompliance.permission.patch(
    connection,
    {
      body: { code: "no_such_code_xyz" } satisfies IPermission.IRequest,
    },
  );
  typia.assert(nonExistingResult);
  TestValidator.equals("no result for fake code")(0)(nonExistingResult.data.length);

  // 7. Pagination: get page 1/limit=2, then next page
  const paged1 = await api.functional.securityCompliance.permission.patch(
    connection,
    {
      body: { page: 1, limit: 2, sort_field: "created_at", sort_direction: "asc" } satisfies IPermission.IRequest,
    },
  );
  typia.assert(paged1);
  TestValidator.equals("pagination 1st page length")(2)(paged1.data.length);

  if (paged1.pagination.pages > 1) {
    const paged2 = await api.functional.securityCompliance.permission.patch(
      connection,
      {
        body: { page: 2, limit: 2, sort_field: "created_at", sort_direction: "asc" } satisfies IPermission.IRequest,
      },
    );
    typia.assert(paged2);
    TestValidator.predicate("pagination 2nd page not empty")(paged2.data.length > 0);
  }
}

