import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPermission } from "@ORGANIZATION/PROJECT-api/lib/structures/IPermission";

/**
 * E2E test to validate fetching a single permission by ID, both positive (existing ID) and negative (invalid ID) scenarios.
 *
 * This test ensures that:
 *   - When a valid permission ID is supplied, the details returned exactly match the created permission.
 *   - When a non-existent/invalid ID is provided, the proper error is thrown and no sensitive information is leaked.
 *
 * Steps:
 * 1. Create a permission using POST /securityCompliance/permission (for a known valid ID).
 * 2. Fetch that same permission by ID using GET /securityCompliance/permission/{id} and verify all fields match.
 * 3. Attempt to fetch a permission using a random (unallocated) UUID and expect a not-found error.
 */
export async function test_api_securityCompliance_permission_getById(
  connection: api.IConnection,
) {
  // 1. Create a new permission (POST)
  const createInput: IPermission.ICreate = {
    code: `test.permission.${RandomGenerator.alphaNumeric(8)}`,
    description: RandomGenerator.paragraph()(1),
    policy_id: null,
  };
  const created: IPermission = await api.functional.securityCompliance.permission.post(connection, { body: createInput });
  typia.assert(created);
  TestValidator.equals("code")(createInput.code)(created.code);
  TestValidator.equals("description")(createInput.description)(created.description);
  TestValidator.equals("policy_id")(null)(created.policy_id);

  // 2. Fetch the permission by its ID (GET)
  const fetched: IPermission = await api.functional.securityCompliance.permission.getById(connection, { id: created.id });
  typia.assert(fetched);
  TestValidator.equals("id")(created.id)(fetched.id);
  TestValidator.equals("code")(created.code)(fetched.code);
  TestValidator.equals("description")(created.description)(fetched.description);
  TestValidator.equals("policy_id")(created.policy_id)(fetched.policy_id);
  TestValidator.predicate("has created_at timestamp")(!!fetched.created_at);

  // 3. Attempt to fetch a permission with an invalid/non-existent ID (expect error)
  await TestValidator.error("not-found for non-existent permission ID")(() =>
    api.functional.securityCompliance.permission.getById(connection, {
      id: typia.random<string & tags.Format<"uuid">>()
    })
  );
}

