 *    - 응답이 IPermission 타입에 부합하고, id, created_at 값도 존재하는지 확인
 * 2. 잘못된 데이터(필수 필드 누락, 유효성 불일치):
 *    - code가 없거나 빈 string, description이 없거나 빈 string 등 변형하여 시도
 *    - API가 적절한 validation error 반환하는지 TestValidator.error()로 검증
 *    - 기존 등록된 code로 중복 등록시에도 오류 나는지 확인
 */
export async function test_api_securityCompliance_test_create_permission_with_valid_and_invalid_data(connection: api.IConnection) {
  // 1. 올바른 permission 생성
  const uniqueCode: string = `e2e.permission.${RandomGenerator.alphabets(10)}`;
  const permission = await api.functional.securityCompliance.permission.post(connection, {
    body: {
      code: uniqueCode,
      description: `E2E Permission for ${uniqueCode}`
    } satisfies IPermission.ICreate
  });
  typia.assert(permission);
  TestValidator.equals("code")(uniqueCode)(permission.code);
  TestValidator.equals("description")(`E2E Permission for ${uniqueCode}`)(permission.description);
  TestValidator.predicate("permission.id is uuid")(!!permission.id && /^([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12})$/.test(permission.id));
  TestValidator.predicate("permission.created_at is date-time")(!!permission.created_at && !isNaN(Date.parse(permission.created_at)));

  // 2. 필수 필드 누락/이상 데이터 : code 누락
  await TestValidator.error("code 누락시 validation error")(() =>
    api.functional.securityCompliance.permission.post(connection, {
      body: {
        description: "desc without code"
        // code는 누락됨
      } as any // 실제 E2E에선 타입으로는 누락 불가, 런타임에서만 테스트 가능
    })
  );

  // 2-2. code 빈문자열
  await TestValidator.error("code 빈값 validation error")(() =>
    api.functional.securityCompliance.permission.post(connection, {
      body: {
        code: "", description: "desc with empty code"
      }
    })
  );

  // 2-3. description 누락
  await TestValidator.error("description 누락 validation error")(() =>
    api.functional.securityCompliance.permission.post(connection, {
      body: {
        code: "test.missingdesc" // desc 누락
      } as any
    })
  );

  // 2-4. desc 빈문자열
  await TestValidator.error("description 빈값 validation error")(() =>
    api.functional.securityCompliance.permission.post(connection, {
      body: {
        code: "test.emptydesc", description: ""
      }
    })
