import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPermission } from "@ORGANIZATION/PROJECT-api/lib/structures/IPermission";

/**
 * Test updating Permission records by ID, validating both success and error conditions.
 *
 * 1. Create a new Permission record (as prerequisite)
 * 2. Update that Permission with valid fields and confirm update by re-fetching
 * 3. Attempt to update a non-existent (random) Permission ID and assert not-found/validation error
 * 4. Attempt to update with duplicate/invalid code and assert validation error handling
 */
export async function test_api_securityCompliance_test_update_permission_with_valid_and_invalid_data(
  connection: api.IConnection,
) {
  // 1. Create a new Permission record
  const created = await api.functional.securityCompliance.permission.post(connection, {
    body: {
      code: RandomGenerator.alphaNumeric(10),
      description: RandomGenerator.paragraph()(2),
      policy_id: null,
    },
  });
  typia.assert(created);

  // 2. Update the Permission (valid update)
  const newDescription = RandomGenerator.paragraph()();
  const updated = await api.functional.securityCompliance.permission.putById(connection, {
    id: created.id,
    body: {
      description: newDescription,
    },
  });
  typia.assert(updated);
  TestValidator.equals("updated description")(newDescription)(updated.description);
  TestValidator.equals("code unchanged")(created.code)(updated.code);

  // 3. Attempt to update non-existent Permission, expect not-found error
  await TestValidator.error("Not-found error updating non-existent permission")(
    async () =>
      api.functional.securityCompliance.permission.putById(connection, {
        id: typia.random<string & tags.Format<"uuid">>() /* unlikely to exist */,
        body: {
          description: RandomGenerator.paragraph()(),
        },
      })
  );

  // 4. Attempt to update with duplicate code, expect validation error
  const duplicate = await api.functional.securityCompliance.permission.post(connection, {
    body: {
      code: RandomGenerator.alphaNumeric(12),
      description: RandomGenerator.paragraph()(),
      policy_id: null,
    },
  });
  typia.assert(duplicate);

  await TestValidator.error("Validation error on duplicate code")(
    async () =>
      api.functional.securityCompliance.permission.putById(connection, {
        id: created.id,
        body: {
          code: duplicate.code,
        },
      })
  );
}

