/**
 * Test updating Permission records by ID, validating both success and error conditions.
 *
 * This E2E test validates the ability to update existing Permission records using the admin API, and asserts both successful mutation and error handling for invalid scenarios. Permission records control fine-grained RBAC/policy compliance, and unique code enforcement is critical for system reliability.
 *
 * Steps:
 * 1. Create a Permission record (dependency)
 * 2. Update the created record by ID and confirm changes
 * 3. Attempt to update a non-existent (random) ID and assert not-found error
 * 4. Attempt to update with a duplicate code and check validation error
 */
export async function test_api_securityCompliance_test_update_permission_with_valid_and_invalid_data(
  connection: api.IConnection,
) {
  // 1. Create a Permission record
  const perm = await api.functional.securityCompliance.permission.post(connection, {
    body: {
      code: RandomGenerator.alphaNumeric(10),
      description: RandomGenerator.paragraph()(2),
      policy_id: null,
    } satisfies IPermission.ICreate,
  });
  typia.assert(perm);

  // 2. Update the Permission's description, confirm result
  const newDescription = RandomGenerator.paragraph()();
  const updated = await api.functional.securityCompliance.permission.putById(connection, {
    id: perm.id,
    body: {
      description: newDescription,
    } satisfies IPermission.IUpdate,
