        body: {
          description: RandomGenerator.paragraph()(),
        } satisfies IPermission.IUpdate,
      })
  );

  // 4. Create a duplicate code for validation error
  const dupe = await api.functional.securityCompliance.permission.post(connection, {
    body: {
      code: RandomGenerator.alphaNumeric(12),
      description: RandomGenerator.paragraph()(),
      policy_id: null,
    } satisfies IPermission.ICreate,
  });
  typia.assert(dupe);

  await TestValidator.error("duplicate code should fail")(
    async () =>
      api.functional.securityCompliance.permission.putById(connection, {
        id: perm.id,
        body: {
          code: dupe.code,
        } satisfies IPermission.IUpdate,
      })
  );
}

