import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPermission } from "@ORGANIZATION/PROJECT-api/lib/structures/IPermission";

/**
 * Validate deletion of a permission record and error handling for non-existent IDs.
 *
 * This test covers both successful and unsuccessful "delete" operations for the Permission entity:
 *   - It first creates a permission (to ensure a valid target exists),
 *   - Successfully deletes it and asserts the entity is removed,
 *   - Then attempts to delete it again (should be not-found or idempotent),
 *   - Also tests deletion with a random invalid UUID to check error handling.
 *
 * Steps:
 * 1. Create a permission with unique code and description
 * 2. Delete the permission by its ID and validate the returned entity info matches what was created
 * 3. Attempt to delete the same ID again (should yield not-found or proper idempotent error)
 * 4. Attempt deletion using a random non-existent UUID (invalid target)
 */
export async function test_api_securityCompliance_test_delete_permission_by_valid_and_invalid_id(
  connection: api.IConnection,
) {
  // 1. Create a new permission to be deleted
  const createInput: IPermission.ICreate = {
    code: `test.${RandomGenerator.alphaNumeric(12)}`,
    description: `E2E Test Permission ${RandomGenerator.paragraph()(1)}`,
  };
  const created: IPermission = await api.functional.securityCompliance.permission.post(connection, { body: createInput });
  typia.assert(created);
  TestValidator.equals("created code")(createInput.code)(created.code);
  TestValidator.equals("created description")(createInput.description)(created.description);

  // 2. Delete by ID and check the returned deleted entity info
  const deleted: IPermission = await api.functional.securityCompliance.permission.eraseById(connection, { id: created.id });
  typia.assert(deleted);
  TestValidator.equals("deleted id")(created.id)(deleted.id);
  TestValidator.equals("deleted code")(created.code)(deleted.code);

  // 3. Attempt to delete the already-deleted ID (should error, or be idempotent)
  await TestValidator.error("delete already deleted permission should fail")(() =>
    api.functional.securityCompliance.permission.eraseById(connection, { id: created.id })
  );

  // 4. Attempt to delete using a random, non-existent UUID
  const randomId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("delete with invalid/non-existent permission id should fail")(() =>
    api.functional.securityCompliance.permission.eraseById(connection, { id: randomId })
  );
}

